globalThis.ANDE_CHUNKS["97af8497ca62bd32f272db1ca190d386a2ff95942bd1c2aa24285d81408c9f9a"] = [{"id":"bytedance:7688390314206251317","sourceKey":"bytedance","company":"字节跳动","title":"后端开发实习生 - 中国交易与广告","city":"北京","category":"后端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7688390314206251317/detail","duty":"团队介绍：中国交易与广告，基于个性化推荐、深度学习和大模型技术，依托抖音、今日头条、红果短剧、西瓜视频、番茄小说等多元产品，构建抖音电商、生活服务、广告营销等核心营收业务的算法策略和工程架构。部门运用领先的算法能力，精准连接海量用户与商家，通过推荐、广告和搜索算法精准匹配需求并促进交易达成，保障用户体验与商家权益，实现营收业务可持续增长；基于深厚的技术积累，构建高效、智能、可靠的交易与广告产品，全面提升多行业收入变现与市场占有。在这里，你将直面超大规模流量与复杂业务场景的技术挑战，深度应用业界领先的商业模型与算法技术，投身面向未来的数字营销能力建设，持续探索前沿技术。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、负责架构设计和开发，为亿级用户提供优质顺畅的信息服务和极致体验；\n2、参与设计系统技术方案，核心代码开发和系统调优；\n3、参与制定代码规范、测试规范，建立起开发质量控制方法；\n4、协助团队攻克各种高并发、数据隔离、系统解耦等方面的技术难关；\n5、参与各专项技术调研，新技术引入等前瞻项目；\n6、参与机器学习与异构计算系统研发。","requirements":"1、本科及以上学历在读，计算机相关专业优先；\n2、至少熟悉一种主流编程语言（Go/Java/C++），有扎实的编程能力和良好的编码风格；\n3、熟悉Linux操作系统和开发环境，有良好的数据结构、算法基础和系统设计能力；\n4、善于沟通，工作积极主动，责任心强，具备良好的团队协作能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7687890394097436933","sourceKey":"bytedance","company":"字节跳动","title":"AI产品实习生（效果评测方向） - TikTok","city":"上海","category":"产品经理","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7687890394097436933/detail","duty":"团队介绍：TikTok是一个覆盖150个国家和地区的国际短视频平台，我们希望通过TikTok发现真实、有趣的瞬间，让生活更美好。TikTok在全球各地设有办公室，全球总部位于洛杉矶和新加坡，办公地点还包括纽约、伦敦、都柏林、巴黎、柏林、迪拜、雅加达、首尔和东京等多个城市。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、参与面向国际市场的AI内容效果评测，协助搭建和持续优化评测标准与测试集并开展评估；\n2、协助推进评测相关产品能力建设，参与测评相关需求梳理、方案讨论、测试验收及上线效果跟踪，推动评测流程和工具效率持续提升；\n3、参与产品分析及行业趋势研究，了解不同国家和地区用户对互动效果内容的偏好，沉淀典型案例、用户反馈和产品洞察；\n4、协调设计、研发、运营等合作团队，跟进评测任务、实验进度及问题解决，协助形成可复用的评测方法和结论。","requirements":"1、本科及以上学历在读，计算机、统计学、心理学、市场营销、广告学、交互设计、数字媒体等相关专业优先；\n2、对AI内容产品有浓厚兴趣，关注AIGC、国际内容产品的发展趋势，有较强的产品体验和用户视角；\n3、具备良好的数据分析能力，熟练使用Excel/WPS，能够完成数据整理、筛选、透视和基础统计；会使用SQL、Python或数据可视化工具者优先；\n4、具备较强的逻辑分析和问题拆解能力，能够根据统一标准开展评测，从定量数据与定性反馈中识别明显问题并形成清晰结论；\n5、英语六级以上，能够阅读英文材料并进行基础沟通；了解欧美等国际市场的内容趋势、用户偏好和文化差异者优先；\n6、具备良好的沟通协作、项目跟进和时间管理能力，做事细致、有责任心，能够高效按时完成任务；可实习至少3个月，每周4天，有互联网产品、效果评测、数据分析、A/B实验、用户研究或人工标注相关经历优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7687460702554212613","sourceKey":"bytedance","company":"字节跳动","title":"创作者运营（音乐方向）实习生 - 番茄小说","city":"北京","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7687460702554212613/detail","duty":"团队介绍：番茄小说是抖音在 2019 年推出的免费阅读产品，致力于为读者提供优质的阅读体验。番茄小说拥有海量正版小说，涵盖言情、都市、玄幻、悬疑等主流网文类型，以及大量热剧原著和经典出版物，支持用户看书、听书。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、协助基于消费数据进行音乐人分层，按照不同层级开展作者分层运营与关系维护，及时收集音乐人的问题和需求，并推动反馈与解决；\n2、协助整理音乐人拉新名单，定期跟进音乐人的触达、沟通及合作进度，参与原创音乐人的合作准入工作，完成资料收集、信息审核及流程跟进；\n3、参与歌曲定制及原创音乐采买项目，协助完成作品征集、信息整理、进度记录和交付验收等工作，跟进各环节时间节点，保障项目顺利推进；\n4、定期汇总作者引入、运营及内容采买数据，整理项目进展和阶段性结果，协助完成相关复盘与运营资料沉淀。","requirements":"1、本科及以上学历在读；\n2、每周可实习4天，可实习3个月优先；\n3、具备优秀的对外沟通能力，工作细致、有责任心；\n4、对音乐行业/内容版权有兴趣，有创作者运营实习经验优先；\n5、熟练使用基础办公软件，具备数据整理与分析能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7686468528744646965","sourceKey":"bytedance","company":"字节跳动","title":"AI服务后端开发实习生 - Data语音","city":"北京","category":"后端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7686468528744646965/detail","duty":"团队介绍：Data-语音团队致力于语音、音乐等大模型AIGC技术的研发和产品创新，我们的使命是通过多模态AIGC音频技术赋能内容创作和语音交互，让内容生产、消费与互动变得更加简单、沉浸、多元化。当前团队已有成熟的大模型语音合成、语音理解、音乐生成等多模态音频技术，并持续迭代大模型端到端语音交互方案等，一方面通过中台形式服务于公司众多业务线，例如豆包/Dola、抖音/TikTok、剪映/CapCut、番茄小说、海绵音乐等产品；另一方面，团队已经通过字节跳动旗下的火山引擎开放平台-语音技术和火山方舟平台，向众多企业开放技术成熟稳定的能力和服务。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、负责字节跳动语音AI产品落地应用的服务架构研发，快速搭建AI语音相关平台应用、后端服务链路，持续优化服务体验、稳定性；\n2、将基于大模型相关的语音和多模态对话技术框架落地应用到实际业务中；\n3、持续探索在各种场景下，利用AI能力增强产品体验，提升工程效率；\n4、为字节跳动相关产品提供先进的语音能力，赋能抖音、剪映等业务，以及豆包等AI产品，用AI技术影响数亿用户。","requirements":"1、本科及以上学历在读，计算机相关专业优先；\n2、有C++/Go/Python项目开发经验，较强的代码能力，对工程、代码质量有较高要求；\n3、精通数据结构和算法设计，熟悉系统性能调优的方式，熟悉Linux开发环境；\n4、有责任心，做事细致，考虑周全。\n\n加分项：\n1、ACM/NOI/IOI/TopCoder等竞赛获奖；\n2、有AI领域大影响力的项目经验；\n3、有分布式、高并发、大流量等特点在线系统相关项目经验。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7686006134032943413","sourceKey":"bytedance","company":"字节跳动","title":"厂商策略实习生 - 抖音","city":"深圳","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7686006134032943413/detail","duty":"团队介绍：抖音致力于打造一个开放、积极、多元、友善的平台，鼓励表达、沟通和记录，激发创造，丰富人们的精神世界，让现实生活更美好。我们通过AI算法驱动的个性化推荐与智能创作工具，满足用户表达、学习、娱乐、社交、消费等需求。回顾抖音一路走来的历程，我们在帮助亿万用户记录美好生活的过程中，努力变得更好。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、深度参与团队AI Agent从0到1的建设与迭代，梳理投放业务逻辑并转化为自动化工作流，提升渠道投放效率；\n2、负责字节跳动中国区产品在手机厂商渠道的用户增长，探索并落地基于AI与大模型技术的创新营销及投放策略，实现全产品增长目标；\n3、负责数据监控及日常分析，梳理广告转化漏斗，并尝试引入大语言模型/Agent工具辅助数据洞察与BI报表优化；\n4、关注大模型前沿应用及手机厂商行业发展动态，挖掘AI技术与移动端系统能力的结合点，探索前沿的创新增长方式。","requirements":"1、本科及以上学历在读；\n2、对AI Agent及大语言模型工具有强烈兴趣及实践经验优先（如熟悉Prompt编写、搭建过自动化工作流等）；有产品思维和创新思维，能抽象投放经验，将重复工作自动化；\n3、具备良好的逻辑思维能力、数据敏感度和分析能力、学习能力，自驱力强，擅长沟通；\n4、资深数码爱好者优先，对安卓主流手机厂商（如小米、vivo、OPPO、华为、荣耀等）生态、系统特性及3C数码行业有基本了解和持续关注的热情。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7684186573348849973","sourceKey":"bytedance","company":"字节跳动","title":"后端开发实习生（应用商店管理） - 开发者服务","city":"北京","category":"后端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7684186573348849973/detail","duty":"团队介绍：字节跳动开发者服务团队负责公司研发工具与基础设施体系建设，为内部开发者提供覆盖全技术栈的框架、工具和研发体系能力，支撑业务高效稳定迭代。\n在此基础上，团队正打造面向全场景的AI Agent平台，将大模型与公司内部工程知识深度结合，覆盖需求分析、编码开发、测试发布、运维治理等软件全生命周期，帮助ByteDancer显著提升生产力，重塑开发者服务的形态与体验。\n期待对研发工具体系、AI工程生产力有热情、希望在大规模真实场景中打磨技术的同学加入，与我们一起建设新一代开发者基础设施，共同成长！\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、参与建设面向App Store、安卓、鸿蒙等平台的应用上架预审能力，探索并应用LLM、Agent、AI Coding等技术，完成原型构建、流程验证与方案迭代，参与多Agent编排、工具接入、知识检索与上下文管理的设计与落地；\n2、围绕平台审核规则、历史驳回案例及业务需求，沉淀可执行的预审规则、知识库与风险识别策略，覆盖隐私声明、权限使用、三方SDK、应用内容、商店元数据及区域化配置等场景；\n3、参与预审平台、服务及工作流的设计与开发，推动能力接入CI/CD与应用发布链路，实现风险前置发现、自动诊断与闭环跟踪；\n4、建设预审效果评估与反馈机制，持续优化风险召回率、误报率、规则更新效率及用户体验；\n5、跟踪Apple等审核政策变化，与客户端研发、测试、隐私合规、法务及发布团队协作，推动预审能力持续演进。","requirements":"1、本科及以上学历在读，计算机、软件工程、人工智能、电子信息等相关专业优先；\n2、具备扎实的计算机基础和良好的工程编码能力，熟悉至少一种编程语言，包括但不限于Java、Go、C++等，掌握Python和TypeScrip语言优先；\n3、了解LLM、Agent、Prompt Engineering或模型评测等AI技术，并愿意探索其在软件工程中的应用；\n4、具备较强的学习能力、问题分析能力和动手能力，能够完成技术调研、原型验证及工程化落地；\n5、具备良好的英文阅读能力，能够理解Apple等国际化平台的政策和技术文档；\n6、具备良好的沟通协作能力和责任心，能够主动推进跨团队问题闭环。\n\n加分项\n1、有iOS/Android应用开发、打包、签名、提审或App Store Connect等使用经验优先；\n2、了解移动端隐私合规、权限管理、第三方SDK治理或应用商店审核规则优先；\n3、有AI Agent/LLM应用相关的开源项目、竞赛、论文或个人作品（含GitHub项目）优先；\n4、熟悉CI/CD、服务端开发或数据分析工具优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7683858992657303813","sourceKey":"bytedance","company":"字节跳动","title":"安全策略产品经理 - 番茄小说","city":"北京","category":"产品经理","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7683858992657303813/detail","duty":"团队介绍：番茄小说是抖音在 2019 年推出的免费阅读产品，致力于为读者提供优质的阅读体验。番茄小说拥有海量正版小说，涵盖言情、都市、玄幻、悬疑等主流网文类型，以及大量热剧原著和经典出版物，支持用户看书、听书。\n\n1、参与番茄系内容安全的产品需求分析和规划，设计产品原型，并撰写需求文档；\n2、负责产品方案的设计、分析、落地，为项目节点负责，并持续进行功能优化和策略迭代；\n3、具备较好的数据分析能力，对产品运营数据进行追踪和分析，制定优化方案并推动产品持续迭代；\n4、与研发、运营等部门密切合作，推进产品的快速升级，保证产品按时、高质量上线。","requirements":"1、2027届获得本科及以上学历，计算机等相关专业优先；\n2、熟悉内容型产品，具备复杂策略类产品设计基础和实战经验者优先；\n3、具有较强逻辑思维能力和数据敏感性，独立思考，并善于创造性解决问题；\n4、有较强的沟通能力，有同理心，并有取舍的判断力；\n5、对工作有责任心、积极主动完成工作，接地气。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7683086347003349253","sourceKey":"bytedance","company":"字节跳动","title":"Seedance2.5AIGC导演实习生 - 火山方舟","city":"北京","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7683086347003349253/detail","duty":"团队介绍：火山方舟是火山引擎推出的一站式大模型服务平台，是中国大模型市场产品和份额领跑者。平台提供模型推理、评测、精调等全流程服务。方舟搭载了豆包及业界主流大模型，提供丰富的插件生态和AI应用开发服务，并通过稳定可靠的安全互信方案、专业的算法技术服务，全方位保障企业级AI应用落地。\n\nByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n\n1、基于Seedance模型及内部测试版本，独立或主导创作电影叙事短片、概念片、预告片、MV、动画影像等AIGC视频作品，负责创意构思、导演阐述、分镜设计、视听风格、生成执行到成片交付的完整链路；\n2、从导演视角评估模型生成结果，识别其在人物表演、镜头调度、空间连续性、视线关系、情绪递进、叙事节奏和风格一致性上的问题，形成结构化、可验证的改进建议；\n3、围绕复杂人物互动、多角色一致性、长镜头调度、动作连续性、多镜头叙事、光影氛围和世界观稳定性等方向开展创作压力测试，将创作痛点转化为模型训练、数据建设和产品能力需求；\n4、与编剧、剪辑师、制片、算法科学家及产品经理紧密协作，搭建适用于专业叙事创作的AIGC工作流，持续优化剧本拆解、视觉开发、Prompt设计、角色资产、镜头生成、声音与后期衔接；\n5、参与高质量影视数据的策划与评估，基于导演专业标准定义镜头语言、人物调度、表演层次、场面组织和视听风格等维度的质量标尺；\n6、持续关注全球AIGC影像、电影节作品与新型内容形态，沉淀Seedance导演场景的案例库、创作方法论和最佳实践，推动团队作品质量与创作效率提升。","requirements":"1、2027届本科及以上学历在读，戏剧影视导演、电影制作、动画、摄影、数字媒体艺术等相关专业优先；\n2、具备剧情短片、电影、剧集、MV、动画或实验影像导演经验，有成熟个人代表作优先，具备扎实的导演基本功，能够独立完成剧本理解、分镜设计、场面调度、人物表演、镜头语言、声音设计与剪辑节奏把控；\n3、具备鲜明且稳定的审美判断，能够根据不同题材建立统一的视觉规则，并在多镜头创作中保持人物、空间、光影和情绪的一致性；\n4、熟悉主流AIGC视频和图像工具，例如Seedance、Runway、Luma、Pika、即梦、可灵、ComfyUI等，具备独立完成复杂AI视频项目的能力；\n5、对大模型、生成式视频、Diffusion、Transformer、RL及数据训练保持强烈好奇心，能够把“画面不对”“表演不成立”等创作判断拆解为具体问题和测试标准；\n6、具备良好的项目推进与跨团队沟通能力，能在创作标准、技术边界和交付节奏之间做清晰判断，推动作品按质量要求落地。\n\n加分项\n1、作品曾入围或获得FIRST青年电影展、平遥国际电影展、金鸡电影节、上海国际电影节等国内外主流影视节展奖项；\n2、有AI原生短片、虚拟制作、动画导演、视效导演或游戏过场动画创作经验；\n3、拥有持续更新的个人AIGC作品账号、公开传播案例，或在AIGC影像创作社区具备一定影响力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7681185345474218245","sourceKey":"bytedance","company":"字节跳动","title":"产品营销经理 - TikTok Shop","city":"上海","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7681185345474218245/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商。平台汇聚全球优质商家与创作者，通过短视频、直播等多场景连接消费者，让新奇好物畅销全球，让美好生活触手可得。目前团队分布在美国、英国、法国、印尼、墨西哥、中国等全球多个国家和地区，在这里你将有机会深入国际业务场景，面向全世界商家及用户，和跨区域团队协作，共同探索创新购物模式。期待和优秀的你一起创造更多可能！\n\n1、与内部产品、运营、数据等团队合作以及外部商家、创作者协作，持续优化TikTok Shop整体产品的营销策略；\n2、与跨团队合作，通过内容可视化等方式，对多来源信息进行精简整合，转化为面向市场的故事，并完成多渠道的产品能力推广；\n3、深入了解适用于所在领域用户的营销渠道及内容标准，并持续利用数据优化策略，并提出产品优化建议。","requirements":"1、2027届获得本科及以上学历；\n2、精通英语，且掌握欧洲、亚太、中东的一门小语种语言者优先；拥有产品运营、产品营销或内容营销相关经验，有电商/消费科技工作经验者优先；\n3、能持续深入了解所在领域及地区的产品用户，可以从营销角度理解并深入掌握产品功能、用户体验、商业价值及市场影响；\n4、擅长故事构建与讲述，能将复杂背景转化为多种形式的有吸引力的内容，熟练掌握图片、音视频编辑技能者更佳；掌握基本的数据分析能力，熟练使用SQL者更佳；\n5、能在快速变化的环境中高效工作、灵活适应并达成目标；具备出色的沟通、协作及项目管理能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7680848112689416501","sourceKey":"bytedance","company":"字节跳动","title":"AI Agent全栈工程师实习生 - 中国交易与广告","city":"上海","category":"后端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7680848112689416501/detail","duty":"团队介绍：中国交易与广告，负责抖音电商、生活服务、广告营销等营收业务的研发。用技术带来美好生活，让用户发现更多优价好物，为用户提供更丰富独特的生活体验；连接海量用户与商家，促进交易达成，让生态里全流程体验更流畅，助力营收业务长效增长。\n加入团队，你将投身流量与增长主战场，挑战复杂业务场景技术难题；直面真实商家和用户，用技术解决看得见的问题，在实战中快速成长，书写属于你的价值故事！\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、依托各类AI Coding工具，负责前/后端技术选型，独立完成广告业务相关项目的前后端全栈开发、功能迭代与接口联调，参与方案设计，保障业务需求高质量落地；\n2、主导或参与前后端基础设施建设，包括组件库沉淀、工程化工具链优化、CI/CD流程改进，提升团队研发效率；\n3、与产品、算法等团队紧密协作，推动跨团队技术方案对齐，保障项目按时交付；\n4、关注前端前沿技术发展，推动新技术在业务中的落地实践，持续优化用户体验和页面性能；\n5、参与Agent在广告业务场景中的落地探索（如Agent产品交互开发、工作流编排等），跟进前沿Agent开源方案，沉淀可复用的调度模板与工程最佳实践；善于利用AI Coding工具提升个人及团队开发效率，具备工程提效意识。","requirements":"1、本科及以上学历在读，计算机、人工智能、软件工程等相关专业；\n2、掌握Python/Go/Java/JavaScript任意2门开发语言，熟悉Node.js/Go，具备前后端一体化开发能力；\n3、理解LLM基础原理，熟悉AI Agent核心模块（Prompt、记忆机制、工具调用、RAG、多智能体），能区分不同层级模型的业务适用场景；\n4、熟练掌握主流AI编码工具（TRAE、Claude Code、Codex等），能够利用AI完成需求拆解、代码编写、复杂逻辑重构、Bug定位修复、单测编写、代码评审，具备AI协同研发思维；\n5、熟悉Git基础操作，具备良好的沟通能力与团队合作精神；对技术保持好奇心，善于独立思考并反思总结；\n6、有相关岗位实习及项目开发经历优先。\n\n加分项\n1、有AI辅助前后端全栈开发、Agent项目部署与二次开发实战经验；\n2、实操过Agent任务拆分、多智能体并行调度、模型自动择优等核心功能；\n3、熟悉MCP协议、LLM工具调用、AI自动化工作流搭建；\n4、有对话应用、智能编排、知识库平台等相关项目开发经验。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7677855581592848693","sourceKey":"bytedance","company":"字节跳动","title":"国际电商产品战略实习生 - TikTok Shop","city":"上海/北京","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7677855581592848693/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商。平台汇聚全球优质商家与创作者，通过短视频、直播等多场景连接消费者，让新奇好物畅销全球，让美好生活触手可得。目前团队分布在美国、英国、法国、印尼、墨西哥、中国等全球多个国家和地区，在这里你将有机会深入国际业务场景，面向全世界商家及用户，和跨区域团队协作，共同探索创新购物模式。期待和优秀的你一起创造更多可能！\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、扫描国内外主要电商、AI公司在电商、B端与C端产品、AIGC、Agentic Commerce前沿动态、探索新的商业模式及机会；\n2、推动商家、服务商、用户访谈，提炼洞察，撰写访谈报告；\n3、结构化地研究并体验市场产品、撰写产品使用报告；\n4、对关键的业务假设，建立数据分析思路，通过AI工具分析数据集，得到对业务有影响的结论。","requirements":"1、本科及以上学历在读；\n2、实习期保证4个月以上，每周工作4天以上，能长期实习优先，有战略、商业分析、研究岗位的实习经历优先，拥有独立负责过一个复杂的行业、公司研究的经历优先；\n3、日常已深度且高频使用，包括不限于Claude Code、Codex等AI工具，近3个月已高频使用AI工具Claude Code、Codex优先；\n4、精通英语，读写听说能力强。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7675375199224547589","sourceKey":"bytedance","company":"字节跳动","title":"AIGC前端开发工程师（小云雀Pippit） - 剪映CapCut","city":"北京/深圳","category":"前端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7675375199224547589/detail","duty":"团队介绍：剪映研发团队，主要支持剪映、CapCut、醒图、Hypic、即梦、Dreamina、小云雀、Pippit等多款国内外产品的研发工作，业务覆盖多元化影像创作场景，并孵化了多款AIGC明星产品，相关产品多次登顶国内外App Store 免费应用榜第一，并继续保持高速增长。加入我们，一起打造全球最受用户欢迎的影像创作和GenAI产品。\n\n1、参与剪映小云雀需求迭代，为小云雀的能力迭代贡献力量；\n2、参与小云雀AIGC链路的稳定性保障工作，完善监控和报警；\n3、参与AIGC相关能力的业务开发，针对业务痛点做基础能力相关的改进。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程等相关专业优先；\n2、热爱计算机科学和技术，精通至少一门编程语言，包括但不仅限于：C/C++、Python、Go、Java、TypeScript、JavaScript；\n3、掌握扎实的计算机基础知识，深入理解数据结构、算法和操作系统知识；\n4、有优秀的逻辑分析能力，能够对业务逻辑进行合理的抽象和拆分；\n5、有强烈的求知欲，优秀的学习和沟通能力；\n6、有项目经验优先。\n\n加分项：\n1、有个人开源项目，且STAR数过500；\n2、对AI兴趣浓厚，前端领域之外扩展学习AI相关知识，熟练掌握AI工具提升编程效率。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7671174222509541685","sourceKey":"bytedance","company":"字节跳动","title":"豆包AI大模型产品实习生 - 火山方舟","city":"北京","category":"产品","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7671174222509541685/detail","duty":"团队介绍：火山方舟是火山引擎推出的一站式大模型服务平台，是中国大模型市场产品和份额领跑者。平台提供模型推理、评测、精调等全流程服务。方舟搭载了豆包及业界主流大模型，提供丰富的插件生态和AI应用开发服务，并通过稳定可靠的安全互信方案、专业的算法技术服务，全方位保障企业级AI应用落地。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、参与AI产品的需求调研、产品设计与功能迭代；\n2、通过用户调研、市场分析等方式了解需求和使用场景，产出需求文档并推进落地；\n3、跟踪产品上线效果、用户反馈，为产品功能的优化提供合理建议；\n4、通过优化产品体验、文档等方式为用户提供支持，提升产品体验和用户满意度；\n5、关注AI领域的技术和产品动态，为团队提供有价值的洞察和行动方案。","requirements":"1、本科及以上学历在读，计算机科学、信息技术、人工智能或相关专业优先；\n2、有产品实习经验，了解产品经理基本方法论；\n3、具备良好的逻辑思维、问题分析解决能力、沟通能力与团队合作能力；\n4、对AI、大语言模型、多模态、机器学习ML/强化学习RL等底层技术有较深入理解。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7671130584277682485","sourceKey":"bytedance","company":"字节跳动","title":"算法工程师 - Pangle","city":"上海/北京/杭州","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7671130584277682485/detail","duty":"团队介绍：Pangle 是国际化业务旗下独家广告联盟网络，目前已覆盖近 50 个市场。该平台通过值得信赖、智能且注重实效的广告解决方案，助力广告主对接优质本地发布渠道，将营销触角延伸至整个国际化业务生态。Pangle 已在 20 多个新兴市场构建行业领先的广告网络，于亚太、中东及拉丁美洲地区拥有经市场验证的成功经验。与此同时，Pangle 为开发者打造广告变现与用户获取的闭环增长，助力开发者获取更高收益、更优质用户，全面释放成长潜能。\n\n1、负责Pangle广告投放中出价策略与算法，及定向、召回、精排、出价等各阶段模型改进，极致优化变现效率和广告ROI；\n2、负责大规模Online Learning的深度模型效率改进和效果优化；\n3、负责利用策略和模型手段，从度量归因、投放体验、长期可持续的广告业务等方面，探索最新的商业化变现技术和商业产品设计，提出行业创新性解决方案；\n4、参与CTR，CVR等广告模型的设计、开发和迭代。","requirements":"1、2027届获得本科及以上学历，计算机、机器学习和模式识别相关专业；\n2、热爱计算机科学和技术，对人工智能类产品有浓厚兴趣；\n3、具优秀的编码能力，熟悉Linux开发环境，熟悉C++和Python语言优先；\n4、有扎实的数据结构和算法功底，熟悉机器学习、自然语言处理、数据挖掘、分布式计算、计算机视觉、计算机图形、语音识别与合成中一项或多项；\n5、对推荐系统、计算广告、搜索引擎相关技术有经验者优先；\n6、优秀的分析问题和解决问题的能力，对解决具有挑战性问题充满激情。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669752384818055477","sourceKey":"bytedance","company":"字节跳动","title":"算法研究员（搜广推大模型） - Data AML","city":"北京/杭州","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669752384818055477/detail","duty":"团队介绍：Data AML是字节跳动的机器学习中台，为抖音/今日头条/西瓜视频等业务提供推荐/广告/CV/语音/NLP的训练和推理系统。为公司内业务部门提供强大的机器学习算力，并在这些业务的问题上研究一些具有通用性和创新性的算法。同时，也通过火山引擎将一些机器学习/推荐系统的核心能力提供给外部企业客户。\n\n1、探索推荐算法和大语言模型/多模态理解的深度融合，主要研究方向包括：LLM4Rec、跨端跨场景的Foundation Model、千亿级参数规模的模型和多模态大模型；\n2、参与抖音中深度学习算法应用与优化，覆盖推荐、广告、多模态等需大量算力的业务场景；\n3、与工程团队密切配合，探索新架构下的算法方向。","requirements":"1、2027届获得本科及以上学历，计算机、人工智能等相关专业优先；\n2、在推荐广告或者大模型领域主导过项目或论文者优先；\n3、扎实的机器学习、NLP基础和出色的探索能力，在ACL/NeurIPS/ICML/ICLR/CVPR等会议上发表论文者优先；\n4、积极性强，愿意接受挑战，具有独立解决问题的能力，良好的团队合作意识和沟通能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669689412078405941","sourceKey":"bytedance","company":"字节跳动","title":"大客户销售（互动娱乐） - 商业化","city":"上海/广州","category":"销售","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669689412078405941/detail","duty":"团队介绍：抖音集团商业化是抖音集团旗下的综合数字化营销服务平台，致力于让不分行业、地域的企业及个体都能通过数字化技术激发创造、驱动生意，实现商业的可持续增长。\n\n1、按照商业化战略规划，负责消费品行业、互动影视、互动应用、互动娱乐（游戏）、金融、电商平台、教育行业、MCN及达人等方向的客户的开拓与维护工作；\n2、与企业建立深度合作关系，完成既定销售指标；\n3、与公司关联部门沟通协作，确保广告的及时投放与问题反馈、广告资源的合理利用与开发；\n4、通过数据分析客户需求，为客户提供咨询服务、产品培训、优化投放、数据分析等营销策略，制定整合营销方案及策略，推动各行业营销策略的实施。","requirements":"1、2027届获得本科及以上学历；\n2、热爱销售工作，具备良好的客户开拓和服务能力，以及建立良好的客户群体关系的能力；\n3、掌握商务谈判、沟通及文字写作表达交流技巧，具有一定的市场洞察力和执行力；\n4、性格开朗，敢于面对挑战。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669685133130221877","sourceKey":"bytedance","company":"字节跳动","title":"AI产品经理（策略产品方向） - 小荷健康","city":"北京","category":"产品","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669685133130221877/detail","duty":"团队介绍：小荷健康是字节跳动旗下的医疗健康品牌，我们致力于利用大模型技术，探索医疗健康服务的新范式，孵化了“小荷AI医生”app，为用户提供专业的健康咨询服务。小荷健康拥有专业的医学和互联网产研团队，认真探索AI医疗。\n\n1、负责抖音产品工作，独立跟进子项目的需求分析与规划，产品需求梳理；\n2、与技术团队紧密协作，探索并提出创新的解决方案，推动方案落地。","requirements":"1、2027届获得本科及以上学历；\n2、有计算机相关知识，掌握编程能力，了解算法和大语言模型等方面的知识；\n3、有产品思维、有基本的用户理解、行业洞察、数据分析能力；有学习理解能力、逻辑思维能力，有自驱力/好奇心/求知欲等，结果导向，有成长潜力；\n4、对业务有理解，能基于明确的业务场景或需求输出产品Demo或搭建AI应用等工作流，高效推动产品落地；\n5、如果你有医疗背景，对医疗和健康行业有理想与热情，会更加加分。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668520016222603525","sourceKey":"bytedance","company":"字节跳动","title":"国际物流经营分析产品经理 - TikTok Shop","city":"上海/珠海/杭州","category":"产品","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668520016222603525/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商。平台汇聚全球优质商家与创作者，通过短视频、直播等多场景连接消费者，让新奇好物畅销全球，让美好生活触手可得。目前团队分布在美国、英国、法国、印尼、墨西哥、中国等全球多个国家和地区，在这里你将有机会深入国际业务场景，面向全世界商家及用户，和跨区域团队协作，共同探索创新购物模式。期待和优秀的你一起创造更多可能！\n\n1、业务洞察与场景挖掘：深入国际物流全履约链路，包括订单、履约、成本定价、客户体验等环节，主动发现经营痛点与异常，挖掘业务机会点，为成本、时效、体验等核心指标优化提供支持；\n2、经营分析产品能力建设：参与国际物流成本预估、经营损益及归因分析能力建设，推动业务分析框架产品化，协同研发与算法团队建设物流成本与经营洞察平台；\n3、人工智能工具与应用探索：灵活运用大模型、数据智能体、辅助代码及原型工具等，支持日常分析与产品设计，探索人工智能在物流经营分析、预测及决策场景中的应用；\n4、数据流程与产品推进：参与数据流程梳理，厘清物流成本与履约数据的生产依赖逻辑，协同研发、算法及业务团队输出产品原型与需求文档，推动项目迭代与交付。","requirements":"1、2027届获得本科及以上学历，统计、数学、计算机、工业工程、物流管理或理学、工学、商学相关专业优先；\n2、熟练掌握SQL，具备较强的数据分析能力，能够独立完成数据清洗、提取与建模分析，熟练使用至少一种数据可视化工具；\n3、具备较强的业务拆解与逻辑分析能力，能够结合国际物流场景定位问题根因，提炼观点并用数据支持业务判断；\n4、熟练使用人工智能效率工具，能够用于数据分析、逻辑提炼和原型设计，对人工智能技术在业务场景中的应用有探索意愿；\n5、具备较强的自驱力、学习能力、沟通协调能力与跨团队合作意识，有跨境电商、国际物流、供应链、经营分析、商业分析、数据产品或算法模型相关实习或项目经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668324564712294709","sourceKey":"bytedance","company":"字节跳动","title":"安全研发工程师（威胁检测与响应） - 安全与风控","city":"北京","category":"安全","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668324564712294709/detail","duty":"团队介绍：安全工程团队负责设计、搭建并维护字节跳动的全球安全基础设施、平台及服务。我们的核心职责是研发具备可扩展性的系统与工具，为公司全域产品的安全运营提供支撑。通过交付可靠、高性能的安全解决方案，保障字节跳动全球平台的安全，并提升业务韧性。\n\n1、和产品经理、前后端及其他相关需求方密切配合，参与需求讨论、设计与研发威胁检测与响应相关产品，支撑安全运营、入侵检测与响应工作；\n2、参与上述系统的系统架构迭代演进、运维等；\n3、参与工程建设与持续优化，包括但不限于架构优化、性能优化、质量建设、工程效率优化等；\n4、深入业务，理解并合理抽象业务需求，转化成产品能力，提升产品价值，与业务团队紧密合作。","requirements":"1、2027届获得本科及以上学历，计算机/信息安全或相关专业优先；\n2、熟悉一种或几种以下语言：Go/Java/Python等，有扎实的编程能力和良好的编码风格；\n3、有良好沟通能力和团队协作能力，工作积极主动，责任心强；\n4、具备较强的逻辑思维与问题拆解能力，能够将复杂或模糊的问题分解，并及时形成清晰、务实的解决方案。\n\n加分项：\n1、有安全运营或威胁检测响应相关平台和系统经验；\n2、有AI Agent应用开发或使用AI建设威胁检测与响应平台系统经验者优先，包括但不限于LLM集成、Prompt工程、安全检测/响应Agent开发、Agent编排框架平台研发等；\n3、有较强的产品意识、逻辑思维能力和学习能力，善于沟通、乐于协作。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668252612533750021","sourceKey":"bytedance","company":"字节跳动","title":"抖音视频安全治理策略 - 抖音社区治理","city":"北京","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668252612533750021/detail","duty":"团队介绍：抖音致力于打造一个开放、积极、多元、友善的平台，鼓励表达、沟通和记录，激发创造，丰富人们的精神世界，让现实生活更美好。我们通过AI算法驱动的个性化推荐与智能创作工具，满足用户表达、学习、娱乐、社交、消费等需求。回顾抖音一路走来的历程，我们在帮助亿万用户记录美好生活的过程中，努力变得更好。抖音社区治理团队负责抖音的社区治理工作，包括视频、直播等多体裁的内容治理，以及安全产品中台能力建设。\n\n1、负责抖音内容安全治理策略体系建设，协同产品、算法、审核、运营等团队，推进问题发现、定义、识别、处置和复盘机制落地；\n2、围绕内容安全风险与业务场景，参与治理策略设计和能力建设，平衡内容治理效果与业务发展诉求，持续优化审核链路和处置效率；\n3、基于内容特征、用户行为、消费路径及风险表现进行分析，识别潜在治理问题，制定内容处置策略并推动迭代；\n4、结合数据分析、策略评估和业务反馈，参与治理项目目标拆解、优先级判断及跨团队协作推进，产出可持续优化方案；\n5、关注大模型在内容理解、风险识别、策略辅助分析等方向的应用，探索将大模型能力融入治理策略设计、问题归因和效率提升场景。","requirements":"1、2027届获得本科及以上学历，专业不限，统计学/计算机/数据科学等理工专业优先；\n2、具备较强的内容理解能力和文字敏感度，对内容安全、社区生态、平台治理等方向有兴趣，认真负责，主观能动性强；\n3、具备基础的数据分析能力，能通过数据发现问题、验证判断并总结规律，有SQL/Python/数据分析项目经验优先；\n4、逻辑思维清晰，善于拆解问题并推动解决，具备良好的沟通协作能力和一定产品思维；\n5、大模型应用实践经验优先：包括提示词设计、AI工具使用、文本理解/分类/归因场景实践，或参与过大模型相关项目；不要求深度算法背景，需具备主动学习和业务应用意识。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667884307688540421","sourceKey":"bytedance","company":"字节跳动","title":"抖音广告算法工程师 - 端变现","city":"北京/上海","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667884307688540421/detail","duty":"团队介绍：端变现团队是商业化能力的核心承载者之一，负责今日头条、番茄小说、西瓜视频、红果短剧等十数款明星产品的变现价值挖掘、技术体系搭建和业务增长助力，涵盖最丰富的内容体裁和变现场景。团队以“技术驱动商业价值，体验平衡增长效能”为理念，通过整合模型策略、工程技术与增长激励等多元能力，打通“流量-技术-转化-增长”全链路，为产品商业可持续性、用户体验优化及业务规模增长提供全方位支撑。\n\n1、在超大规模在线训推框架下，结合AIGC前沿技术，持续进行算法及工程架构Co-Design，通过极致Scaling up、LLM4Rec等手段构建业界领先的CTR/CVR/生成式召回等推荐模型，服务到抖音系产品的变现目标；\n2、构建高效投放系统，在AIGC广告素材量级显著膨胀的背景下有效应对海量广告候选，做到高效动态算力分配和资源调度，支持到高效系统漏斗分配及素材的投放及探索；\n3、通过最优化策略、强化学习和生成式建模等手段，实现广告和自然内容的高效混排、广告样式生成及优选、金币激励策略优化，提升收入规模的同时兼顾用户体验优化。","requirements":"1、2027届获得本科及以上学历，计算机等相关专业优先；\n2、具备优秀的编码能力，扎实的数据结构和算法功底；\n3、优秀的分析问题和解决问题的能力，对解决具有挑战性问题充满激情；\n4、对技术有热情，有良好的沟通表达能力和团队精神；\n5、熟悉机器学习、计算机视觉、自然语言处理、数据挖掘中一项或多项。\n\n加分项：\n1、在AIGC/推荐/广告团队有相关实习经历，参与了实际的算法和模型研发；\n2、在ACM-ICPC/TopCoder等比赛中获得名次；\n3、作为主要作者在计算机顶会上发表过论文，如KDD/ICML/ICLR/ACL/CVPR/EMNLP/ICCV/NeurIPS等。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667868280900356405","sourceKey":"bytedance","company":"字节跳动","title":"大模型算法评测工程师 - 质量团队","city":"北京","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667868280900356405/detail","duty":"团队介绍：字节跳动质量团队作为公司质量保障体系的核心力量，覆盖Trae、Coze、开发者服务、语音等多个业务关键领域，通过建设和提供更高效的质量保障方案、技术、工具以及业务自动化保障服务，为公司业务稳健发展提供坚实保障。\n当前，我们聚焦用 AI 重构测试流程、提升研发效能，探索从 “自动化” 到 “智能化” 的质量保障新路径。我们坚信，AI 将彻底改变测试行业的底层逻辑，欢迎加入，与我们一同突破技术边界，定义下一代质量保障模式，推动行业变革！\n\n1、负责字节跳动人工智能产品线，站在用户视角构建端到端的算法效果评测体系；\n2、深入业务结合业务需求痛点，设计完备的算法效果质量保障、评测方案；构建合理且置信的标准化评测体系，解决业务评测效率和效果问题；\n3、推动通用人工智能评测方案的升级迭代，逐步推广至公司内的商业化平台。","requirements":"1、2027届获得硕士及以上学位，计算机/人工智能相关专业优先；\n2、对技术和基础原理有执着追求，善于用各种手段解决问题；熟悉各类业界主流的人工智能相关的平台特性，具备平台开发经验和能力；熟悉至少一门编程语言，包括但不仅限于：Java、OC、C、C++、Python、Go、PHP；\n3、了解NLP、神经网络、生成式语言大模型等基本原理，有过AI类产品算法评测经验；\n4、对业界人工智能领域保持高度热情。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667817420166318389","sourceKey":"bytedance","company":"字节跳动","title":"营销算法工程师 - TikTok Shop","city":"上海/北京/杭州","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667817420166318389/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商业务，致力于成为用户发现并获取优价好物的首选平台。面向直播电商、视频内容电商、货架电商等多元购物场景，国际电商持续为全球用户提供更个性化、更主动、更高效的消费体验，也为商家提供稳定、可靠、可持续增长的平台服务，推动“新奇好物畅销全球，美好生活触手可得”的使命落地。\n目前，国际电商算法团队分布在中国、美国、新加坡等多个国家和地区，深度参与全球化业务建设。加入我们，你将有机会面向全球用户、商家和商品生态，与跨区域的产品、工程、运营和业务团队协作，持续提升商品供给质量、用户购物体验、平台交易效率与履约体验，共同探索内容电商与智能购物的新模式。\nData-国际电商团队是 TikTok Shop 的核心算法技术力量，专注于电商场景下的算法创新与规模化落地，方向包括但不限于：生成式推荐与大规模 Foundation Model、多模态商品理解与内容生成、搜索与导购、智能客服、风控治理、物流履约优化、商家经营智能化，以及 Agentic 智能体在电商全链路中的应用。我们希望通过先进的算法能力，帮助用户更高效地发现感兴趣的商品，帮助商家实现更高质量的经营增长，并持续提升交易各环节的智能化水平。\n在这里，你将与一流的产品和技术团队合作，面对复杂且真实的国际化电商挑战，推动前沿技术在大规模业务场景中落地，与团队一起创造更多可能。\n\n1、团队主要负责国际电商全球多区域，包括美国、欧洲、拉美、东南亚等区域的智能营销、用户增长等业务，对电商规模以及用户规模负责；\n2、建立用户全生命周期数据和价值体系，解决电商用户增长中的各种核心痛点和业务问题；\n3、参与搭建业界先进的在线营销推理算法引擎，打通搜索、推荐、营销场域信号，突破各域独立决策到多域联合决策；\n4、负责国际化电商的用户增长和智能营销的业务优化，通过算法优化业务主要预算花钱钱效，包括补贴分发、商品定价、预算分配、流量策略等补贴效率以及流量效率优化业务，促进电商GMV增长。","requirements":"1、2027届获得本科及以上学历，人工智能、机器学习、计算机、数学、运筹学相关专业优先；\n2、有扎实的算法和数据结构基础，优秀的编码能力；\n3、学习能力强，对事物保有好奇心，良好的沟通能力和团队协作能力；\n4、有扎实的机器学习算法基础，熟悉机器学习、深度学习、因果推断、强化学习中一项或多项；\n\n加分项：\n1、在AI领域顶级会议/期刊上发表过论文，或参加ACM/机器学习类竞赛并获得过好名次的优先；\n2、有用户增长、智能营销，广告等相关领域研究或者项目实践，有LTV预估、Uplift、运筹规划、序列建模、多场景建模优化等经验的优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667817009817159941","sourceKey":"bytedance","company":"字节跳动","title":"推荐大模型算法工程师 - TikTok Shop","city":"上海/北京/杭州","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667817009817159941/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商业务，致力于成为用户发现并获取优价好物的首选平台。面向直播电商、视频内容电商、货架电商等多元购物场景，国际电商持续为全球用户提供更个性化、更主动、更高效的消费体验，也为商家提供稳定、可靠、可持续增长的平台服务，推动“新奇好物畅销全球，美好生活触手可得”的使命落地。\n目前，国际电商算法团队分布在中国、美国、新加坡等多个国家和地区，深度参与全球化业务建设。加入我们，你将有机会面向全球用户、商家和商品生态，与跨区域的产品、工程、运营和业务团队协作，持续提升商品供给质量、用户购物体验、平台交易效率与履约体验，共同探索内容电商与智能购物的新模式。\nData-国际电商团队是 TikTok Shop 的核心算法技术力量，专注于电商场景下的算法创新与规模化落地，方向包括但不限于：生成式推荐与大规模 Foundation Model、多模态商品理解与内容生成、搜索与导购、智能客服、风控治理、物流履约优化、商家经营智能化，以及 Agentic 智能体在电商全链路中的应用。我们希望通过先进的算法能力，帮助用户更高效地发现感兴趣的商品，帮助商家实现更高质量的经营增长，并持续提升交易各环节的智能化水平。\n在这里，你将与一流的产品和技术团队合作，面对复杂且真实的国际化电商挑战，推动前沿技术在大规模业务场景中落地，与团队一起创造更多可能。\n\n1、参与推荐算法的探索——服务数亿真实用户、构建和重写算力时代下新的工业级推荐系统：\n2、参与电商十亿级用户与商品的个性化推荐算法优化，覆盖视频、直播、货架场景下的召回、粗排、精排、混排全链路，每次迭代都会在线上直接创造真实业务价值；\n3、LRM/LLM×工业推荐的正面碰撞，重塑下一代推荐范式：\n1）Scaling up to Billion：把排序模型从亿级推到十亿级参数，联合训练与推理侧优化，探索推荐领域的scaling law——包括超长行为序列建模（KV Cache、序列压缩，UG分离，投机解码、动态batching等）、预训练、多场景多任务多阶段联合训练，针对推荐的特点进行模型结构设计和优化，提升MFU，探索在真实时毫秒级推荐系统下的scaling up的边界；\n2）生成式推荐：基于语义ID（RQ-VAE/SID）与MLLM的一阶段生成式检索，用“beam search”与“test-time scaling”替代传统“多路召回+精排”漏斗，摆脱系统对ID记忆的路径依赖；\n3）世界知识注入：用大模型的真实世界认知挖掘用户潜在兴趣与语义表征，突破纯ID共现的表达上限；探索用推理模型（LLM）对用户长周期意图做显式链式推断，提升推荐系统的发现性与新颖性；\n4、极致的训推性能优化深入PyTorch底层算子（自研CUDA/Triton融合算子）、显存与计算图优化、分布式训练与推理加速，混合精度与低比特量化，把推荐场景特有的稀疏Embedding、变长序列、多任务Head打到硬件极限；\n5、用Agent重写研发范式我们正在把Coding Agent深度嵌入算法研发流程：自动化特征挖掘与Pipeline生成、实验配置与训练任务的自动编排、模型评估与线上诊断的自动归因、负面案例的自动挖掘和巡检；你既是这套系统的使用者，也是它的建设者。","requirements":"1、2027届获得本科及以上学历，人工智能、计算机、数学、统计等相关专业优先；\n2、扎实的机器学习基础与工程能力：理解模型背后的数学，也写得出干净、高效、可复现的代码，熟练掌握主流算法与数据结构；\n3、在机器学习、NLP、CV、推荐中至少一个方向有深入的研究或工程实践，并能清楚讲出你为什么这么做、以及可优化的方向；\n4、对LLM/LRM技术有真实的热情，愿意把前沿方法推进到线上生效，而不止步于离线指标；\n5、强烈的问题定义与拆解能力，面对模糊、无标准答案的业务问题时能自己找到突破口。\n\n加分项：\n1、在KDD、SIGIR、RecSys、WWW、ACL、NeurIPS、ICML、ICLR等顶会/顶刊发表过论文，或有高质量开源工作；\n2、有CUDA/Triton算子开发、深度学习框架源码级优化、大规模分布式训练或高性能推理部署经验；\n3、有LLM后训练（SFT/RLHF/DPO/GRPO）、Agent系统构建、或推理加速方向的实践经验；\n4、主导或深度参与过搜索、广告、推荐、大模型方向的关键项目，有完整的从问题到线上收益的闭环经验；\n5、ACM-ICPC、NOI、Kaggle等竞赛获奖经历。\n\n为什么选择我们：\n真实的十亿级流量、海量的算力预算、从算子到系统到业务的完整链路、开放的团队氛围，在这里你有机会和最优秀的算法工程师一起，重塑算力时代下的推荐系统，探索推荐的scaling law，能把自己的创造力和想法，变成真实影响上亿用户、百万商家达人的线上服务。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667805166166706437","sourceKey":"bytedance","company":"字节跳动","title":"算法（Agent方向）实习生 - TikTok直播","city":"上海","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667805166166706437/detail","duty":"团队介绍：TikTok是一个覆盖150个国家和地区的国际短视频平台，我们希望通过TikTok发现真实、有趣的瞬间，让生活更美好。TikTok 在全球各地设有办公室，全球总部位于洛杉矶和新加坡，办公地点还包括纽约、伦敦、都柏林、巴黎、柏林、迪拜、雅加达、首尔和东京等多个城市。\n\nTikTok直播研发团队，旨在实现TikTok直播业务的研发工作，搭建及维护业界领先的产品。\n加入我们，你能接触到包括：社交互动、营收活动、主播生态、消费订阅、游戏直播、公会&运营平台等核心业务场景，支持产品在全球赛道上高速发展；\n也能接触到包括服务架构、大模型算法、基础技术等方向上的技术挑战，保障业务持续高质量、高效率、且安全地为用户服务；同时还能为不同业务场景提供全面的技术解决方案，优化各项产品指标及用户体验。 \n在这里， 有大牛带队与大家一同不断探索前沿， 突破想象空间。 \n在这里，你的每一行代码都将服务亿万用户。\n在这里，团队专业且纯粹，合作氛围平等且轻松。\n目前在北京，上海，杭州、广州、深圳分别开放多个岗位机会。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、参与前沿算法研发：深耕LLM/多模态大模型、CV/NLP等技术，应用于召回、点击率/转化率预估、内容生态、直播热点挖掘、推荐系统等核心场景，参与大规模推荐系统的设计与模型优化；\n2、参与全流程算法落地：独立承担或深度参与大型算法项目，覆盖从模型训练、调优、部署到效果评估、持续迭代的完整链路，支撑大规模乃至超大规模业务场景；\n3、参与学术研究与产出：总结研究成果，有机会发表顶会论文、参与国际学术会议。","requirements":"1、硕士及以上学位在读，计算机、软件工程、电子信息等相关专业优先；\n2、熟练掌握PyTorch等主流深度学习框架，精通Python，熟悉C++、Shell等脚本语言；\n3、熟练掌握多模态大模型相关的技术；\n4、扎实的数据结构与算法基础，优秀的算法设计与编码能力；\n5、熟悉和了解Agentic RL训练，参与过Agent相关的项目研发（训练和测试）。\n\n加分项：\n1、熟悉多模态大语言模型和Agent等方向；\n2、在NeurIPS、ICLR、ACL、ICML、CVPR、ICCV等会议以第一作者发表过论文；\n3、具备较强的工程基建能力；\n4、熟悉常用的RL框架（Verl等）。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667578387524225333","sourceKey":"bytedance","company":"字节跳动","title":"多模态内容理解&创作算法工程师 - TikTok Shop","city":"上海/杭州/北京","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667578387524225333/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商业务，致力于成为用户发现并获取优价好物的首选平台。面向直播电商、视频内容电商、货架电商等多元购物场景，国际电商持续为全球用户提供更个性化、更主动、更高效的消费体验，也为商家提供稳定、可靠、可持续增长的平台服务，推动“新奇好物畅销全球，美好生活触手可得”的使命落地。\n目前，国际电商算法团队分布在中国、美国、新加坡等多个国家和地区，深度参与全球化业务建设。加入我们，你将有机会面向全球用户、商家和商品生态，与跨区域的产品、工程、运营和业务团队协作，持续提升商品供给质量、用户购物体验、平台交易效率与履约体验，共同探索内容电商与智能购物的新模式。\nData-国际电商团队是 TikTok Shop 的核心算法技术力量，专注于电商场景下的算法创新与规模化落地，方向包括但不限于：生成式推荐与大规模 Foundation Model、多模态商品理解与内容生成、搜索与导购、智能客服、风控治理、物流履约优化、商家经营智能化，以及 Agentic 智能体在电商全链路中的应用。我们希望通过先进的算法能力，帮助用户更高效地发现感兴趣的商品，帮助商家实现更高质量的经营增长，并持续提升交易各环节的智能化水平。\n在这里，你将与一流的产品和技术团队合作，面对复杂且真实的国际化电商挑战，推动前沿技术在大规模业务场景中落地，与团队一起创造更多可能。\n\n1、依托百亿级视频资源和多元的内容电商场景，参与General Multimodal Embedding、Multimodal Large Language Model、Large Scale Multimodal Retrieval、Multimodal Reasoning等技术领域的深耕细作；\n2、负责运用计算机视觉、自然语言处理、多模态大模型等前沿技术对全站视频内容与商品内容进行全面深入的理解与分析；\n3、负责运用相关技术，为内容电商的搜索、推荐场景提供丰富的内容场语义信号，为全球商家、创作者提供优质的智能内容创作和趋势跟踪服务；\n4、参与数据到业务落地全流程，包括但不限于数据处理、数据分析、特征工程、算法模型设计、评估、迭代，并持续探索最前沿技术。","requirements":"1、2027届获得本科及以上学历，人工智能、计算机、数学相关专业优先；\n2、在多模态、视觉算法、自然语言处理、AIGC、LLM、搜索、机器学习、深度学习、智能问答、对话管理、知识图谱、文本生成、人机对话等领域有实际的开发和从业经验者优先；\n3、有好奇心，喜欢新事物，善于合作；\n4、至少熟悉一门计算机编程语言，包括并不限于C/C++/Java/Go/Python；\n5、有论文的优先，包括但不限于ACL、EMNLP、COLING、WWW、AAAI等；\n6、实践动手能力强，ACMICPC，NOI/IOI，Top Coder，Kaggle比赛获奖者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667030890266380549","sourceKey":"bytedance","company":"字节跳动","title":"AI Agent研发工程师 - 番茄小说/红果短剧/番茄畅听","city":"上海","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667030890266380549/detail","duty":"团队介绍：\n番茄小说 - 是抖音集团在 2019 年推出的免费阅读产品，致力于为读者提供优质的阅读体验。番茄小说拥有海量正版小说，涵盖言情、都市、玄幻、悬疑等主流网文类型，以及大量热剧原著和经典出版物，支持用户看书、听书。\n番茄畅听 - 于2020年6月推出，是抖音集团旗下的免费音频产品，致力于为用户提供优质的音频体验。番茄畅听拥有海量的正版免费真人有声音频，音频类型丰富多样，包括有声书、评书相声、历史人文、学习成长等。\n红果短剧 - 是抖音集团2023年推出的免费看剧产品，致力于为用户提供海量免费优质短剧，同时也为用户提供电影、电视剧、小说、有声书等多元内容，满足不同用户的内容消费需求。\n\n1、构建高效、可靠的AI Agent；包括但不限于模型接入、Multi-Agent系统，RAG优化、MCP及工具开发、数据和训练工程等；\n2、围绕小说、短剧等内容的全生命周期做引入决策、生态策略、标签挖掘等方向Agent应用开发工作、保证业务的高效迭代；\n3、追踪前沿Agent技术，探索最新的架构与交互范式，推进内容产品相关的Agent技术预研与产品化落地。","requirements":"1、2027届获得本科及以上学历，扎实的计算机、编程基础，熟悉主流大语言模型的原理及方法；\n2、理解Multi-Agent系统、任务分解、自动化规划、Prompt Engineering等技术领域之一或多个；\n3、出色的结构化表达能力，较强的技术敏感度与前瞻性，独立的思考和判断力；自驱力与学习能力突出，对Agent及知识工程前沿技术有强烈探索欲，逻辑清晰，具备优秀的技术攻坚与团队协作能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7665183601352493365","sourceKey":"bytedance","company":"字节跳动","title":"隐私合规工程师 - 安全与风控","city":"北京","category":"安全","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7665183601352493365/detail","duty":"团队介绍：安全治理与合规团队在保障字节跳动全域安全与合规要求落地的同时，为业务发展提供支持。\n我们负责制定并维护多领域的治理框架，涵盖安全认证、政策制定、隐私保护、内部威胁防控、数据合规及法规遵循等方面。\n通过推动治理、风险与合规（GRC）领域的精细化建设，我们在字节跳动信息安全战略的构建中发挥着关键作用。\n\n1、负责对公司产品开展数据安全与隐私合规检测、评估工作，撰写报告并输出整改方案；\n2、针对共性的数据安全与隐私合规问题开展治理专项，进行风险归因以及跨部门的整改方案输出与落地推进；\n3、关注监管动向，基于数据安全与隐私相关政策法规、实施细节等输出适用于公司业务的评估办法；\n4、对接公司业务部门的数据安全与隐私合规咨询工作，提供理论与技术支持。","requirements":"1、2027届获得本科及以上学历，信息安全、网络安全、计算机、通信或相关专业优先；\n2、具有良好的沟通能力、逻辑思维能力、语言表达能力，性格沉稳、善于学习、有团队合作精神；\n3、自驱、结果导向，积极应对挑战性任务，工作激情饱满。\n\n加分项：\n1、对数据安全与隐私相关标准要求有了解，如个人信息保护法、数据安全法、GB/T35273个人信息安全规范等；\n2、对互联网产品的技术架构有了解，了解安卓/iOS的权限机制；\n3、具备网络协议分析方面技能以及一定的代码阅读和分析能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7664538233856313605","sourceKey":"bytedance","company":"字节跳动","title":"前端开发工程师 - 今日头条","city":"北京/深圳","category":"前端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7664538233856313605/detail","duty":"团队介绍：产品覆盖今日头条、头条极速版等各类产品，为上亿用户持续提供优质的资讯、视频等服务。我们通过建立良好的内容生态，鼓励原创优质的内容，为创作者提供优质的服务和创作体验，促进创作和交流，同时我们致力于通过尽可能丰富的内容体裁和尽可能多的分发方式，连接人与信息，丰富大家的精神生活，让人们看到更大的世界。\n\n1、负责今日头条、悟空浏览器等相关产品的前端开发工作，完成从需求分析、方案设计到编码上线的完整研发流程；\n2、参与系统架构设计与优化、性能调优、API设计、自动化测试等工程化工作，提升系统的稳定性和可维护性；\n3、AICoding实践：使用AICoding工具（如Cursor、Copilot、TRAE、Claude Code等）辅助日常开发，探索AI驱动的研发提效方式；\n4、参与将AI能力融入到搜索的技术方案设计与落地，在实践中验证和优化AI驱动开发流程，持续提升生产力；\n5、优化前端功能设计，解决各种浏览器和终端设备的兼容性问题；通过技术手段，提升用户体验并满足高性能要求。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程、人工智能等相关专业优先；\n2、具备良好的计算机基础，掌握JavaScript、CSS、HTML等前端技术，对主流前端框架（React、Vue、Angular等）至少一种有应用经验；\n3、有兴趣深入学习前端技术开发和了解用户交互体验；\n4、熟悉使用Vue/React等前端框架或者具备Web项目开发经验的同学优先；\n5、积极乐观，责任心强，具备良好的沟通协作能力、逻辑思维能力以及服务意识。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7652306125074188597","sourceKey":"bytedance","company":"字节跳动","title":"【实习】基于大系统大算力的超大规模推荐模型建模（算法）-Data AML（北京/杭州）","city":"杭州","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7652306125074188597/detail","duty":"团队介绍：Data AML是字节跳动的机器学习中台，为抖音/今日头条/西瓜视频等业务提供推荐/广告/CV/语音/NLP的训练和推理系统。为公司内业务部门提供强大的机器学习算力，并在这些业务的问题上研究一些具有通用性和创新性的算法。同时，也通过火山引擎将一些机器学习/推荐系统的核心能力提供给外部企业客户。\n\n课题介绍：\n大规模推荐系统正在越来越多的应用到短视频、文本社区、图像等产品上，期望进一步通过算法与工程Co-design，探索推荐算法和大语言模型/多模态理解的深度融合主要研究方向包括：LLM4Rec、跨端跨场景的Foundation Model、千亿级参数规模的模型 和 多模态大模型。工程上研究方向包括多模态样本的高效表征、基于PyTorch架构的高性能推理引擎与训练框架构建，以及异构硬件在推荐场景下的性能极限优化；算法侧研究方向包括LLM4Rec技术路径的设计、千亿级底座模型的研发以及多模态协同训练（Co-training）等核心课题，旨在通过技术创新定义下一代工业级推荐范式。\n\n课题挑战：\n1、千亿模型的训练和推理优化；\n2、多模态表征统一与高效融合难度大；\n3、Foundation Model的设计和工程优化；\n4、算法工程协同设计与异构硬件适配复杂。\n\n课题价值：\n1、技术价值：突破多模态表征融合、超大规模模型训练推理瓶颈，完善算法与工程协同设计体系，推动异构硬件适配与高性能框架国产化落地；\n2、业务价值：提升推荐精准度与泛化能力，突破现有推荐系统模态局限，赋能短视频、文本社区等多产品，降低算力成本，助力业务规模化增长。","requirements":"1、2027届及以后毕业，博士在读；计算机、软件工程等相关专业优先；\n2、在推荐广告或者大模型领域有相关经验优先；\n3、扎实的机器学习、NLP基础和出色的探索能力，在ACL/NeurIPS/ICML/ICLR/CVPR等会议上发表论文者优先；\n4、积极性强，愿意接受挑战，具有独立解决问题的能力，良好的团队合作意识和沟通能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7639700601715394869","sourceKey":"bytedance","company":"字节跳动","title":"AI基建实习生-风控","city":"北京","category":"后端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7639700601715394869/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：风控工程团队聚焦抖音、今日头条等全产品黑灰产对抗工程化落地，覆盖社区安全、交易风控等多领域风险治理。依托高并发架构、大数据、大模型等核心技术，构建端云一体多层对抗体系，提供全时效基建能力；同时搭建技术情报体系，实现威胁前置预警与精准打击，并联动算法、策略团队推进技术转化，打造高效可靠的智能风控解决方案。\n\n1、参与风控AI Infra建设，面向抖音、今日头条等字节跳动全系产品，围绕数据层、训练层、模型层、服务层、计算层，打造稳定高效的算法基础设施；\n2、参与风控模型/Agent的特征工程与数据资产建设，包括样本采集、清洗、标注、特征抽取与质量监控，构建高质量、可追溯的模型数据集；\n3、参与模型及Agent评测体系搭建与优化，建设统一的离线/在线评测流程和榜单，支持效果回归测试、负面案例分析与效果归因；\n4、参与风控场景下AI Agent的基础设施建设和二次开发，沉淀通用组件与工具，提升Agent迭代与落地效率；\n5、参与大模型推理框架（如vLLM/XLLM等）在风控场景的适配与优化，探索推理加速、算力治理与成本优化方案。","requirements":"1、2027届本科及以上学历在读，计算机、通信等相关专业者优先；\n2、热爱计算机科学和互联网技术，熟练掌握至少一门开发语言（Go/Java/Python/C++/Rust等），具备良好编码能力与线上问题排查能力；\n3、掌握扎实的计算机基础知识，深入理解数据结构、算法和操作系统等；\n4、有创新意识，对问题能深入分析本质并能不拘泥现状提出解决方案，具备良好的沟通协作能力与主人翁意识；\n5、对AI Agent、智能决策、自动化风控有兴趣，积极追踪大模型及Agent开源社区进展，了解大模型相关原理者优先；\n6、有以下任一经验者优先：在特征工程/样本质量闭环建设方面有实践；参与过模型评测平台或评测榜单建设；有Agent二次开发或工具链建设经验；熟悉vLLM等大模型推理框架并有实战经验；对开源社区有过贡献。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7629594983490963717","sourceKey":"bytedance","company":"字节跳动","title":"大模型应用算法实习生-隐私和数据保护办公室","city":"上海","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7629594983490963717/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：我们是字节跳动隐私与数据保护核心团队，联动法律、安全、研发等多方力量，为全球数亿用户构建第一道数据安全防线。聚焦隐私合规落地、数据风险防控，在超150个国家/地区的复杂隐私、数据合规场景中，构建全生命周期数据安全方案，以“隐私+数据”双通道驱动保护创新。\n为什么加入我们？\n1、全球化核心战场：加入支撑字节跳动国际化生态的关键团队，主导服务数亿用户的隐私安全体系，同字节跳动系产品一起定义行业标准；\n2、硬核能力历练：攻克数亿级数据防护，横跨美洲、欧盟、东南亚等法律差异等难题，沉淀覆盖多区域的合规技术视野；\n3、多元成长生态：融入跨多国家多城市的协作团队，参与行业隐私标杆项目，在文化碰撞中解锁国际化合规实战经验。\n\n1、构建面向法律、合规与审计场景的垂直AI平台（类似Harvey AI），通过大模型与AI Agent技术，赋能产品研发全流程的风险识别与自动化决策；推动AI在复杂企业场景中的规模化应用；\n2、探索Agent-based Architecture（Multi-Agent/Tool Use/Planning；包括多步推理、工具调用、Workflow Orchestration等；构建从需求理解→风险识别→证据生成→报告输出的端到端AI系统；\n3、优化大模型Prompt、Tool Calling、结构化输出，提高模型在专业场景中的准确性与稳定性，参与RLHF/Reward Modeling等后训练流程，提升模型在法律与合规推理中的表现，设计评估指标（Accuracy/Recall/Hallucination Rate），定位问题，并持续优化模型效果；\n4、构建高质量训练与评测数据集（法律文本、PRD、历史案例等），参与数据清洗、标注与质量评估，提升数据一致性与可用性，探索RAG/GraphRAG/案例-Based Reasoning等知识增强方案；\n5、开发和维护与模型相关的后端服务（API/Pipeline/Workflow Engine），支持模型在线推理服务的性能优化与稳定性保障，参与AI系统在实际业务中的部署与迭代。","requirements":"1、2027届本科及以上学历在读，计算机科学、软件工程、人工智能、数据科学等相关专业优先；\n2、熟悉机器学习/深度学习基础，了解Transformer基本原理，有大模型应用经验（如GPT、Claude、BERT等），具备提示词工程实践；有以下经验者优先：AI Agent、工具使用、Function Calling、RAG、GraphRAG、RLHF、强化学习、后训练优化；\n3、具备一定后端开发技能，熟悉一种后端编程语言如Node.js、Java或C++；有RESTful API开发经验者优先；\n4、参与过机器学习或深度学习相关的实习、课程项目或个人项目；在开源项目中有贡献，有参与大模型（如GPT、BERT）优化经验者优先；\n5、具有较强的分析和解决问题的能力，良好的团队合作精神和沟通能力，快速学习和应用新技术的能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7628897090341882117","sourceKey":"bytedance","company":"字节跳动","title":"飞书办公场景的企业级AI Agent智能体平台构建（自动化评测） - Seed 产品研发","city":"北京","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7628897090341882117/detail","duty":"团队介绍：产品研发和工程架构-Seed 团队深耕大模型技术在场景中的创新应用，负责多款AI产品的工程研发 —— 包括豆包、飞书、豆包工作、豆包爱学、Gauth、猫箱等创新产品，覆盖消费级与企业级多个场景。我们致力于将大模型能力从 \"生成内容\" 推进到 \"完成工作\"，让 AI 服务用户日常与企业协作。你将面对多模态交互、工具调用可靠性、企业级数据安全等真实工程挑战，与团队一起推动 AI 生产力落地。\n\n课题介绍：\n随着大模型能力趋于成熟，飞书正处于将AI能力从单点功能升级为端到端“企业智能体平台”的关键窗口期。本课题聚焦于办公生产力场景，以Memory与Context体系为底座，以知识问答、会议数字分身为典型Long-Horizon任务场景，以自动化评测为质量度量引擎，以通用智能体框架为演进方向，系统性地探索企业级AI Agent的落地路径。目标是打造一套可扩展、可度量、可持续进化的办公智能体基础设施，让AI真正成为企业员工的协作伙伴与数字分身。\n\n课题挑战：\n1、Memory质量与演化：企业多源异构数据理解难度大，Memory的生产、消费与持续进化链路尚不成熟；现有学术Benchmark与真实办公场景存在较大差距，难以有效指导工程实践；\n2、全模态流式内容理解：会议场景要求对音视频、文档、参会人上下文进行实时全模态理解，Streaming Omni能力的稳定性与泛化性是核心技术瓶颈；\n3、评测体系的区分度与规模化：如何从海量线上Query中动态筛选出具有能力区分度的测试样本，并通过自动化手段生成覆盖全面、可校验的评分标准（Rubrics），以支撑天级别迭代，是工程与算法的双重挑战；\n4、通用Agent框架的动态适配：Agent框架与多业务场景的动态适配、跨场景排序因子融合、奖励工程的训练数据稀缺，以及Memory的结构化与跨任务迁移，均是企业级智能体规模化落地的关键障碍。\n\n课题价值：\n1、产品价值：以飞书套件为依托，打通从Memory建设到Agent执行再到效果评测的完整闭环，实现AI能力从孤立Feature向协作式智能体平台的跃迁，显著提升企业用户的生产力效率；\n2、技术引领：在Memory Benchmark、Omni Streaming理解、LLM-as-a-Judge裁判模型、长程Agent任务等前沿方向建立技术积累，形成学术与工业界双向影响力；\n3、生态战略：会议、文档、知识问答等场景天然是多Agent协作的孵化土壤，本课题构建的基础能力将为未来多智能体企业协作生态奠定核心基础，支撑飞书成为国内领先的企业 AI 智能体平台。","requirements":"1、2027届毕业，获得博士学位，计算机科学、人工智能、自然语言处理、语音与多模态等相关专业优先；\n2、具备扎实的机器学习与深度学习理论基础，对Agent长程复杂任务等领域有一定理论积累和强烈的探索热情；\n3、具备良好的数据意识和实践能力，了解LLM、Agent框架等相关工具链；\n4、对办公生产力场景有深入思考，能够结合实际业务需求，自述探索规模化的评测方式；\n5、具备优秀的学习与分析能力、跨团队沟通协作能力，能在多角色协同的研究环境中高效推进工作。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7600293338679986485","sourceKey":"bytedance","company":"字节跳动","title":"AI产品经理实习生 - 中国交易与广告","city":"北京","category":"产品经理","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7600293338679986485/detail","duty":"团队介绍：中国交易与广告，基于个性化推荐、深度学习和大模型技术，依托抖音、今日头条、红果短剧、西瓜视频、番茄小说等多元产品，构建抖音电商、生活服务、广告营销等核心营收业务的算法策略和工程架构。部门运用领先的算法能力，精准连接海量用户与商家，通过推荐、广告和搜索算法精准匹配需求并促进交易达成，保障用户体验与商家权益，实现营收业务可持续增长；基于深厚的技术积累，构建高效、智能、可靠的交易与广告产品，全面提升多行业收入变现与市场占有。在这里，你将直面超大规模流量与复杂业务场景的技术挑战，深度应用业界领先的商业模型与算法技术，投身面向未来的数字营销能力建设，持续探索前沿技术。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、协助产品经理完成大语言模型在知识问答和数据应用类场景的落地，制定应用层的产品策略和规划；\n2、协助产品经理完成大模型Agent在商业化广告场景的落地与应用；\n3、协调完成开发、设计、测试等跨部门沟通，推进方案的有效落地；\n4、推进产品落地，保障项目高质量落地，参与产品全生命周期的跟进，包括开发、测试、运营；\n5、关注用户反馈，日常答疑，业内产品调研，持续改善产品体验。","requirements":"1、本科及以上学历在读，统计学、计算机相关专业优先；\n2、能保证一周至少4天实习，实习期4个月以上，6个月以上优先；\n3、表达能力强，善于沟通，主动积极，高度自驱，独立思考，有互联网产品运营实习经历优先；\n4、英语能力较好者优先，熟悉扣子优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7589592588106451253","sourceKey":"bytedance","company":"字节跳动","title":"搜索广告算法实习生-国际化搜索广告","city":"北京","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7589592588106451253/detail","duty":"日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n团队介绍：国际化搜索广告团队不断突破通用搜索引擎变现的界限，覆盖海外应用，致力于构建全球领先的搜索广告变现系统。在国际化搜索广告团队，您将有机会从事大规模分布式存储和架构、自然语言处理、排序和信息检索相关的问题。您还将深入参与我们的广告样式、创意展示和广告投放链路的创新和优化。我们正在寻找勇于挑战困难、热衷于解决复杂问题并与热情洋溢的候选人们共同发展我们的搜索广告产品。\n\n1、参与大规模广告系统的开发；\n2、使用机器学习参与广告投放的开发和迭代，包括点击率/转化率模型估计准确性、数据分析、建模、特征工程，以及广告定向、出价算法、广告流量控制等研究与开发；\n3、参与自然语言处理（NLP）能力的提升和查询理解，例如查询分类、Seq2Seq、实体识别（NER）、知识图谱、关键词优化等；\n4、负责相关性模型和策略优化，例如语义匹配模型、主动学习、文本/照片/视频多模型、排序策略等；\n5、与产品经理和产品战略与运营团队合作，定义产品策略和功能。","requirements":"1、本科及以上学历在读，计算机相关专业优先；\n2、具备一种或多种通用编程语言的经验，包括但不限于：Go、C/C++、Python；\n3、在以下领域之一具有良好理解：搜索、广告、推荐、电商、商业化产品；\n4、能够批判性地思考问题并以清晰简洁的方式提出解决方案。\n\n加分条件\n1、具有以下领域中的一个或多个领域的经验：机器学习、深度学习、自然语言处理、排名系统、推荐系统；\n2、在NLP领域具有研究经验，在会议/期刊上发表过高质量论文，如ACL/EMNLP/NAACL/NIPS等；\n3、在跨文化、跨职能环境中与内部团队有效合作的良好沟通与协作技能。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7688246124075944197","sourceKey":"bytedance","company":"字节跳动","title":"创意设计实习生 - 剪映CapCut","city":"北京/深圳","category":"设计","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7688246124075944197/detail","duty":"团队介绍：剪映CapCut团队成立七年，先后孵化了剪映、CapCut、醒图、Hypic、即梦、Dreamina、Pippit等产品，覆盖视频、图片、Al生成、视频营销等多领域，打造与AI结合的全球化产品矩阵。\n我们的愿景是：激发想象力，成为全球领先的互动内容平台，创造独特的体验和价值。\n我们期待你的加入，一同极致打磨用户体验,构建创意生态和商业化能力，定义AI与创作结合的无限可能，让内容互动更简单、更精彩!\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、负责工具产品相关的AI短片的视觉设计与制作，能把控画面构图、叙事逻辑及整体风格；\n2、参与创意策划、脚本及分镜设计，兼顾部分产品功能动效设计；\n3、协同团队推进项目，整理创意素材，协助资源管理与外包监修。","requirements":"1、本科及以上学历在读，电影编导、编剧专业优先，设计、动画、摄影等相关专业亦可；\n2、具备优秀的视觉设计与排版能力，审美扎实，有独立的艺术思考与表达；\n3、熟悉AIGC创作工具，有AI短片创作经验，具备叙事、镜头语言及后期制作能力；\n4、有国际电影节、AI影像或设计赛事获奖经历者优先；\n5、创新与学习能力强，善于团队协作及跨部门沟通。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7682672997018667269","sourceKey":"bytedance","company":"字节跳动","title":"游戏策划实习生（boss设计） - 绿洲工作室","city":"北京","category":"游戏策划","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7682672997018667269/detail","duty":"绿洲工作室2019年4月在北京成立，立足动作与休闲核心赛道，依托移动、PC、主机全平台布局，持续探索 RPG、竞技、休闲、棋牌等多品类精品游戏创作。旗下有《晶核》《雾影猎人》《SlashZero》（又名：《零境·入侵》）《Land of Empires》《芒果斗地主》等多款产品。我们的愿景是希望帮助玩家在令人惊叹的虚拟世界中一起玩耍与创造，加入这里，你将与一群简单、务实的优秀伙伴一起，Work hard，Play harder~\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、参与捕鱼游戏BOSS内容设计，在带教指导下负责BOSS形象概念、出场与技能演出、捕获反馈等环节的方案撰写与迭代，产出美术和开发可直接落地的设计文档；\n2、与2D/3D美术、动效、开发对接需求，把设计意图拆成明确的参考和验收点，参与效果审核并提出具体修改意见，保障最终呈现与设计预期一致；\n3、跟进BOSS内容从设计到上线的完整流程，同步进度、暴露风险、配合解决跨环节问题，按节点完成内容集成与测试验收；\n4、参与线上BOSS数据与玩家反馈的复盘，基于结论提出体验优化点。","requirements":"1、本科及以上学历在读，游戏设计、数字媒体、动画、影视、戏剧影视文学等相关专业；\n2、能保证实习4个月以上并且每周稳定实习时间，有基础的游戏设计常识，能拆解一个BOSS战，有美术鉴赏力，能用参考图、分镜或文字准确描述想要的视觉效果；\n3、熟悉捕鱼、休闲或动作品类，对其中的打击感、反馈节奏、成就感设计有自己的判断；\n4、有数值设计基础，能理解掉率、产出、难度曲线等对体验的影响优先；\n5、有可展示的演出/内容设计经验优先，如游戏内BOSS、技能设计等（含Demo、课程作业）。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7672719365292198197","sourceKey":"bytedance","company":"字节跳动","title":"数据科学（用户增长方向） - 抖音增长","city":"北京","category":"数据分析","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7672719365292198197/detail","duty":"团队介绍：抖音增长团队（User Growth）负责抖音旗下产品的增长工作。我们帮助产品量身定做增长方案，并运用营销、产品、数据分析等方式达成业务增长目标。UG团队维护和优化一系列类似付费广告、裂变、导量等成熟的产品增长方案，并熟练将其应用到各种不同的业务中，推动业务增长；同时当发现新的增长机会时，我们也及时构建新的解决方案，帮助业务实现突破。加入 UG 团队，可以负责亿级用户产品的增长工作，掌握业界先进、第一手的增长实践。\n\n1、负责抖音系多产品用户增长的分析工作，通过策略挖掘和数据分析，为业务增长提供数据洞察；\n2、基于A/B实验设计、因果推断等分析方案，对业务优化和决策结论做验证或推演，提供高效的分析方法，解决业务复杂度量问题；\n3、基于深度专题分析，从全局增长视角，挖掘手段增长空间，回答关键策略命题，对业务增长驱动因素做拆解和诊断，看清楚业务长期投入方向，提供增长决策支持；\n4、围绕增长核心手段，设计指标体系，明确度量标准和上线规范，为业务问题提供分析支持，挖掘业务增长方向的机会点及优化策略；并与产品、运营、算法、策略、研发等部门紧密配合，推进结论落地，并带来业务全局提升；\n5、在支持业务发展中，善于思考、总结，沉淀增长分析方法论与数据效率工具，并结合AI做提效。","requirements":"1、2027届获得本科及以上学历，数学、统计学、经济学、计算机专业优先；\n2、擅长量化分析，具备良好的量化思维和结构化思维，较强学习能力和创造力，有用户同理心以及业务敏感度；\n3、有责任心和主动性，有良好的业务配合能力和团队协作能力；\n4、熟练使用Hive，精通SQL/Excel/Python/R等工具。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7628922858037348613","sourceKey":"bytedance","company":"字节跳动","title":"多模态创作大模型研究-智能创作","city":"上海","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7628922858037348613/detail","duty":"团队介绍：智能创作团队是字节跳动的创作场景业务中台，以AI赋能创造，致力于通过AI技术降低创作门槛，赋能视觉内容生产与创作的智能化升级。团队深度支持抖音、剪映、即梦、豆包、商业化等多个业务线，持续深耕图片与视频生成、智能剪辑、数字人、特效等多个业务场景，通过由AI驱动的智能化工具与算法，为用户提供了更智能、更便捷、更丰富的创作体验，助力普通用户轻松实现高质量内容创作，同时为专业创作者提供强大的技术支持，推动内容生态的繁荣与创新。\n\n课题介绍：随着AGI大模型技术发展，AI多模态图文视频创作范式迎来深刻变革，基于生成式AI与Agent技术的创作解决方案不断涌现。多模态创作大模型依托全模态内容理解、AIGC图像视频生成及Agentic基座模型等前沿技术，构建灵活高效、业界领先的多媒体内容创作方式。通过Continual Training、Post-Training等方式，持续提升模型在内容理解、图像视频生成的能力上限，端到端优化基础模型在创作Agent场景下的整体效果。\n\n课题挑战：\n1、深入参与Seed多模态模型及大语言模型后训练（SFT/RL）实践；\n2、参与图像视频生成与统一建模，推动模型效果优化的能力，深度体验模型迭代与大规模实训；\n3、实践Agent技术及架构、优化Agentic Foundation模型的工具调用能力及Long-Horizon Task能力，深入研究Agentic RL领域。\n\n课题价值：本课题聚焦AGI时代多模态创作变革，依托全模态理解、AIGC生成与Agentic基座模型等前沿技术，构建高效智能的多媒体创作体系。通过持续训练与模型优化，不断突破内容生成与理解能力，推动AI创作从被动生成走向自主智能，兼具技术前沿性与产业落地价值，为下一代智能创作提供核心支撑。","requirements":"1、2027届毕业，获得博士学位，计算机、人工智能等相关专业优先；\n2、具备一个或多个领域的研究、实践经验，包括但不限于以下方向；\n1）对多模态理解/Omni-modal模型/LLM的Post-Training有深入理解与实践经验，具备基于基础模型进行图像视频Captioning/Prompt Rephraser/文本创作等任务迭代与优化的潜力；\n2）对图像生成/视频生成/多模态理解生成统一建模等领域有深入研究，有Post-Training（SFT/RL等）、Long CoT（Reasoning/Agent等）实践经验，具备优秀的问题发现、归因及推动模型效果优化的能力，具备大规模实训经验优先；\n3）对Agent技术及架构有深刻理解，对优化Agentic Foundation模型的工具调用能力及Long-Horizon Task能力有良好认知，具备深入的AgenticRL领域研究背景，具有实际Agent项目优化经历加分。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7593027357880912133","sourceKey":"bytedance","company":"字节跳动","title":"前端开发实习生-APM","city":"北京","category":"前端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7593027357880912133/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：字节跳动APM(Application Performance Management) 团队负责公司所有服务端、移动端、 前端、 跨端产品的稳定性和性能质量监控保障，构建业界领先的可观测性基础设施，结合机器学习智能化，提供一站式平台覆盖字节跳动各业务线的排障、监控和稳定性提升等需求。\n\n1、负责字节跳动Web端基础体验的基建（涵盖H5、小程序、Node.js、Electron等），通过Agentic AI提供一系列围绕观测、排障、治理场景的智能体以及智能解决方案，全方位提升业务Web应用的基础体验；\n2、负责前端性能分析工具的设计开发和落地，Web端、Node.js监控工具的设计开发和落地，APM相关平台的前端开发；\n3、负责前端基础体验相关标准的制定、落地以及Workflow/Agent Infra相关的能力建设。","requirements":"1、2027届本科及以上学历在读，计算机、通信和电子信息科学等相关专业优先；\n2、熟练掌握一种及以上前端语言，包括HTML/CSS/JavaScript/TypeScript等；\n3、熟悉前端工程化，在开发效率、性能体验、稳定性、自动化等方面有一定的认知和实践。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7688547060120308021","sourceKey":"bytedance","company":"字节跳动","title":"电商直播间用户产品实习生 - 抖音电商","city":"上海","category":"产品","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7688547060120308021/detail","duty":"团队介绍：抖音电商以“总能发现好东西”为主张，致力于成为用户发现丰富好物的首选平台。众多抖音创作者通过短视频、直播、商城等丰富的形式，给用户提供更个性化、更生动、更高效的消费体验。同时，抖音电商积极引入优质合作伙伴，为商家变现提供多元的选择。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、负责抖音电商直播间的看播侧产品设计，从导购、问询、互动等多场景提升抖音电商直播间的用户购买体验；\n2、理解电商直播的业务逻辑与用户行为范式，了解商家与达人生态，能够结合商家达人的经营诉求、用户的购买场景优化直播用户流程，结合AI的能力提升直播间互动感；\n3、主导相关产品设计，协同达人、抖音主端、商家、商品、算法等多团队推动方案落地，推动直播内容生态与交易规模的增长；\n4、持续搭建数据体系，跟踪产品数据，对实验效果进行评估和分析，指导迭代。","requirements":"1、本科及以上学历在读；\n2、具有产品经理工作经验，电商、直播行业经验优先；\n3、具备用户敏感度、业务理解能力、较强学习能力、自驱力、好奇心与创新精神，勇于接受挑战；\n4、具备严谨的逻辑能力，善于独立思考，能够分析事物本质并抽象规律，数据敏感；\n5、具备良好的沟通协作与项目推动能力；\n6、具备AI理解和应用经验加分。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7685318573782321413","sourceKey":"bytedance","company":"字节跳动","title":"AI数据策略产品实习生 - 国际化商业安全","city":"上海","category":"产品","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7685318573782321413/detail","duty":"团队介绍：国际化商业安全团队致力于在国际化用户、企业和产品之间建立安全可靠的连接。我们通过一系列完善的系统和能力，审核广告内容、预测政策违规行为，并执行广告审核通过或拒绝的措施。\n作为国际商业化团队的业务合作伙伴，我们提供的业务诚信解决方案不仅确保国际化业务始终是一个安全、积极、友好的用户环境，同时也推动业务增长。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、数据策略制定：基于商业化业务场景及模型训练、评估目标，制定并迭代整体数据构建策略，包含真实数据、合成数据、样本采集与配比等方案；结合模型表现、失败案例和业务反馈分析数据缺口，为模型优化提供支撑；\n2、数据链路建设：立足模型训练与评估目标，发起并主导数据采集、清洗、加工、标注、质检及评估链路的设计、搭建与维护、优先级判定及项目管理，保障高效产出高质量数据；\n3、质量与效果评估：建立可量化数据质量验收标准，优化验收流程；开展模型效果评估与深度分析，联动技术团队定位模型改进点；\n4、数据生产自动化：独立完成标注Agent、质检Agent或自动评估Workflow的方案设计、Prompt开发、工具调用、流程编排、效果评估和持续维护，提升数据生产的自动化率、质量和规模化能力。","requirements":"1、本科及以上学历在读，计算机、人工智能、数据科学、统计学、数学等相关专业优先；\n2、理解大模型、Prompt Engineering、Workflow和Agent的基本原理，具备LLM应用、Agent或自动化流程的实际搭建经验；\n3、对AI行业有好奇心，能够快速理解模型训练、评估和数据质量问题，并结合业务目标设计可运行、可验证的数据解决方案；\n4、具备系统思维、产品意识和较强的动手能力，能够独立分析问题、完成原型开发和效果验证，并持续维护和迭代所负责的能力；\n5、具备良好的跨团队协作与项目推进能力，重视数据质量，兼具责任心与全局意识。\n\n加分项\n1、计算机专业+Coding能力，有编程经验优先；\n2、有数据工程、机器学习、模型训练数据生产或模型评测相关项目经验；\n3、有标注Agent、质检Agent、Agent-as-Judge、自动化评测或合成数据实践；\n4、熟悉广告、推荐、搜索、电商等业务场景，有可展示的技术项目、Demo或开源作品。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7682986534270748933","sourceKey":"bytedance","company":"字节跳动","title":"游戏交互策划（UE）实习生 - 绿洲工作室","city":"北京","category":"游戏策划","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7682986534270748933/detail","duty":"绿洲工作室2019年4月在北京成立，立足动作与休闲核心赛道，依托移动、PC、主机全平台布局，持续探索 RPG、竞技、休闲、棋牌等多品类精品游戏创作。旗下有《晶核》《雾影猎人》《SlashZero》（又名：《零境·入侵》）《Land of Empires》《芒果斗地主》等多款产品。我们的愿景是希望帮助玩家在令人惊叹的虚拟世界中一起玩耍与创造，加入这里，你将与一群简单、务实的优秀伙伴一起，Work hard，Play harder~\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、负责设计游戏在PC和主机平台的各主要系统的交互逻辑，并跟进制作完整界面；\n2、协助梳理游戏中的交互设计规范；\n3、负责独立制作游戏中一些基础的系统功能。","requirements":"1、本科及以上学历在读；\n2、逻辑思维能力强，有优秀的文字和语言沟通表达能力；\n3、对UE/UI有深入理解，有较强的审美能力，有一定平面设计能力的优先；\n4、熟悉市面上各种主PC、主机游戏的交互设计方案，能分析市场同类游戏交互方面的核心设计思路和方法论；\n5、游戏面广泛，对市面上主流ARPG类游戏和竞技类游戏都有所涉猎，深度PC主机用户优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7681571462048237877","sourceKey":"bytedance","company":"字节跳动","title":"AIGC策略产品实习生 - 剪映CapCut","city":"上海","category":"产品","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7681571462048237877/detail","duty":"团队介绍：剪映CapCut团队成立七年，先后孵化了剪映、CapCut、醒图、Hypic、即梦、Dreamina、Pippit等产品，覆盖视频、图片、Al生成、视频营销等多领域，打造与AI结合的全球化产品矩阵。\n我们的愿景是：激发想象力，成为全球领先的互动内容平台，创造独特的体验和价值。\n我们期待你的加入，一同极致打磨用户体验,构建创意生态和商业化能力，定义AI与创作结合的无限可能，让内容互动更简单、更精彩!\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、参与AIGC相关产品与策略的制定，推动方案落地、上线及持续优化；\n2、参与AIGC Agent的搭建、维护和效果优化；\n3、跟进图片、视频、音频等多模态能力，参与识别策略和产品能力建设；\n4、开展模型测试、效果分析及行业调研，协助发现并解决实际问题。","requirements":"1、本科及以上学历在读，计算机、软件工程、人工智能等相关专业背景；\n2、对AI有浓厚兴趣，愿意主动探索并持续学习；\n3、熟悉AI工具，能够借助AI高效完成调研、分析及复杂任务；\n4、逻辑清晰，具备良好的问题分析、沟通协作和执行能力；\n5、有主人翁意识，能够在不确定的问题中主动寻找解决方案。\n\n加分项\n1、具备工程背景，有Agent、多模态或其他AI项目实践经验。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7677847856178841909","sourceKey":"bytedance","company":"字节跳动","title":"AI产品经理（业务风控方向） - TikTok研发","city":"北京/杭州","category":"产品经理","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7677847856178841909/detail","duty":"团队介绍：TikTok研发团队，旨在实现TikTok业务的研发工作，搭建及维护业界领先的产品。加入我们，你能接触到包括用户增长、社交、直播、电商C端、内容创造、内容消费等核心业务场景，支持产品在全球赛道上高速发展；也能接触到包括服务架构、基础技术等方向上的技术挑战，保障业务持续高质量、高效率、且安全地为用户服务；同时还能为不同业务场景提供全面的技术解决方案，优化各项产品指标及用户体验。 \n在这里， 有大牛带队与大家一同不断探索前沿， 突破想象空间。 在这里，你的每一行代码都将服务亿万用户。在这里，团队专业且纯粹，合作氛围平等且轻松。目前在北京，上海，杭州、广州、深圳分别开放多个岗位机会。\n\n1、面对TikTok全球场景，负责反作弊处置能力相关的需求分析、产品规划、产品设计，以及项目管理；\n2、利用内外部产品与智能化技术能力，实现处置准确性优化，提升风险账号审核能力和处置效果，为治理质量、用户体验等指标负责；\n3、能够独立进行数据分析，设计科学合理的指标衡量处置有效性、评估治理效果和业务影响；\n4、了解公司相关业务及战略，并能协同各业务方的需求，良好的平衡内部需求及线上效果；\n5、有大模型应用相关的业务经验，能够独立搭建Agent/智能工作流；\n6、对安全或风控各类风险的运作模式和违规、作弊手段有分析经验与业务理解。","requirements":"1、2027届获得本科及以上学历，计算机/信息安全/统计学/数学及相关专业优先；\n2、有技术背景优先，有风控、反作弊、反欺诈、策略及相关领域实习或项目经验优先，具有较强的数据分析能力和逻辑判断能力，目标导向；\n3、对AI行业有好奇心，熟练使用AI工具，能主动追踪前沿技术动态、大模型产品动态；有AI产品经验，具备LLM/VLM/多模态训练数据生产、评估经验；\n4、拥有强烈的责任心和团队合作精神，出色的学习能力；\n5、具备强烈的好奇心和自我驱动力，喜欢接受挑战。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7674932006997150005","sourceKey":"bytedance","company":"字节跳动","title":"产品运营实习生 - 抖音生活服务","city":"北京","category":"产品运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7674932006997150005/detail","duty":"团队介绍：抖音生活服务依托抖音POI （Point of Interest）、短视频、直播、搜索等，以“激发线下生意，丰富美好生活”为使命，致力于成为最值得信赖的生活服务平台，为用户提供更丰富、独特的生活体验，为合作伙伴提供包容且公平的健康营商生态。截至2025年底，抖音生活服务业务已覆盖400+城市，超过1500万家动销门店。抖音生活服务将继续携手生态伙伴，为用户提供值得心动的商品和服务。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、聚焦生活服务产品能力接入流程优化与策略支持，负责商家营销、供给接入等功能模块的配置支持工作，保障商家功能使用的顺畅性；\n2、参与商家准入环节的产品评估，制定并输出标准化SOP指引，明确准入评估标准与操作流程，提升准入环节的规范性与效率；\n3、主导加入白名单配置策略的制定与执行，涵盖权限开通、功能灰度发布等场景，协同产品、技术团队推动配置工具迭代，优化运营流程，提升配置准确性与效率；\n4、以数据驱动解决问题，监控商家接入、功能配置全流程的关键指标（如审核通过率、配置错误率、商家反馈满意度等），通过数据分析定位问题根源；\n5、基于数据洞察输出流程优化方案，推动方案落地执行，同时定期输出运营报告，抽象商家共性需求，为产品功能迭代与优化提供决策输入。","requirements":"1、本科及以上学历在读；\n2、实习周期需满足每周至少出勤4天，且持续3个月以上；逻辑思维清晰，具备数据敏感度，能快速理解复杂业务流程，掌握基础数据分析能力（如Excel函数运用、SQL数据提取），可通过数据论证问题并支撑决策；\n3、具备优秀的沟通与跨团队协作能力，能高效联动产品、技术等多方团队，清晰表达观点与需求，推动问题高效解决；\n4、工作主动性强，有责任心，不仅满足于简单执行任务，愿意深入业务背景挖掘核心需求，主动发现流程优化点并提出可行解决方案；\n5、有产品运营、业务流程管理或工具类项目实习/工作经验者优先，熟悉生活服务行业者加分。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7670755843042642181","sourceKey":"bytedance","company":"字节跳动","title":"服务商渠道经理 - 抖音生活服务","city":"北京","category":"销售","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7670755843042642181/detail","duty":"团队介绍：抖音生活服务依托抖音POI （Point of Interest）、短视频、直播、搜索等，以“激发线下生意，丰富美好生活”为使命，致力于成为最值得信赖的生活服务平台，为用户提供更丰富、独特的生活体验，为合作伙伴提供包容且公平的健康营商生态。截至2025年底，抖音生活服务业务已覆盖400+城市，超过1500万家动销门店。抖音生活服务将继续携手生态伙伴，为用户提供值得心动的商品和服务。\n\n1、负责抖音生活服务服务商的日常管理，包括但不限于准入、考核、清退、风控等，保障服务商日常运营，推动达成业绩目标；\n2、为服务商制定合理的生活服务行业商家运营方案，提供活动、团单设计与运营支持，维护良好合作关系，做好交易额提升优化；\n3、持续研究抖音生活服务行业经营策略，分析服务指标，明确服务商能力现状，制定提升方向并定期复盘，沉淀输出经营方法论；\n4、分析服务商团队架构、经营人效等，根据业务发展规划，给予合理意见，组织并实施服务商团队技能培训和赋能，提升服务商团队作战力；\n5、充分了解市场现状，整合、协调内外部资源，推动整体策略方案输出落地。","requirements":"1、2027届获得本科及以上学历；\n2、具备良好的客户开拓和服务能力，以及建立良好的客户群体关系的能力；\n3、掌握商务谈判、沟通及文字写作表达交流技巧，具有一定的市场洞察力和执行力，项目统筹能力和跨团队协作能力；\n4、性格开朗，敢于面对挑战，具有开拓精神。\n\n加分项：\n1、在本地生活赛道，拥有渠道销售/项目运营等经验；具备数据分析能力，可以搭建数据看板并分析汇报，具备数据洞察和业务洞察力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7670480058276137269","sourceKey":"bytedance","company":"字节跳动","title":"AI全栈开发工程师 - 抖音研发","city":"北京/杭州/上海","category":"客户端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7670480058276137269/detail","duty":"团队介绍：抖音研发部门负责多款大型产品的研发，包括但不限于抖音、西瓜视频、汽水音乐。\n加入我们，你将有机会参与亿级用户场景的开发与架构工作，使用前沿的技术助力业务一起不断成长。\n\n1、参与、负责跨平台端侧核心中间件设计和开发，如Bridge、资源加载、监控SDK等；\n2、参与、负责跨平台用户体验优化，从高性能可维护等方面进行容器优化（如Prefetch、Preload）的设计和落地；\n3、推动公司跨平台开发统一端能力生态，提供良好的大前端开发体验；\n4、推动跨平台动态化技术在抖音研发及字节跳动各产品内落地。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程、电子信息或相关专业；\n2、具备扎实的计算机基础，熟悉计算机网络相关知识，掌握常用的数据结构与算法，有良好的编码规范；精通HTML/CSS/JavaScript等前端基础技术，掌握React或Vue至少一种MV*框架；熟悉Node.js，能完成基础全栈开发工作；了解AI Agent开发基础逻辑，愿意参与AI Agent前端交互层、流程编排、可视化界面开发，协助完成AI Agent与前端系统的集成适配；\n3、具备AI Native产品/技术思维，了解AI与前端全栈结合的核心场景（如智能交互、AI辅助提效、RAG知识库前端适配等），愿意探索AI与前端全栈的融合落地；\n4、积极乐观，责任心强，具备良好的服务意识、沟通能力、团队协作能力，业务理解与学习能力强。\n\n加分项\n1、探索过开源项目，有自己的产品案例或优秀的技术博客、论文等；\n2、有小程序、Hybrid App、AI Agent开发经验与实习经历。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669741058988788021","sourceKey":"bytedance","company":"字节跳动","title":"后端开发工程师 - 风控","city":"深圳/北京","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669741058988788021/detail","duty":"团队介绍：风控团队由算法、工程、产品三大团队协同构成，为抖音、今日头条、豆包、剪映等字节跳动业务的内容、交易、流量、账号场景提供智能风控，服务十亿级用户；场景对抗性极强、推理链路长、多模态数据海量，是 AI 时代最有挑战的实战领域之一。算法团队推进 LLM/MLLM 与 Agentic AI 的工业化落地，构建下一代智能风控基建；工程团队依托高并发、大数据与大模型，搭建端云一体的多层对抗体系与情报预警；产品团队评估业务风险、制定策略、探索 AI 在风控中的边界。三线协同，打造高效、前瞻的智能风控防线。\n\n1、负责策略引擎系统的设计与实现，支持字节跳动各产品线（抖音短视频、电商、直播、生活服务、用户增长等）的风控需求；\n2、负责高性能、高并发、低延迟的后台系统持续优化和演进；\n3、面向超大规模数据问题，每天处理千亿增量的数据；\n4、负责风控Agent应用和基建建设，调研和跟踪AI行业的技术趋势，结合风控业务探索AI解决方案的落地，打造具备自演进能力的下一代智能风控架构；\n5、结合业界AI编程&提效的最佳实践，推动风控工程研发开发流程的迭代和效率的提升。","requirements":"1、2027届获得本科及以上学历，计算机、通信等相关专业优先；\n2、热爱计算机科学和技术，精通至少一门编程语言，包括但不仅限于：Java、C、C++、PHP、Python、Go；\n3、掌握扎实的计算机基础知识，深入理解数据结构、算法和操作系统知识；\n4、具备较强的主动性和独立思考能力，对风控领域的复杂性、动态博弈特性有浓厚兴趣，敢于挑战现有技术范式；\n5、理解Agent原理，有相关框架使用和开发经验者优先；\n6、有AI Coding工具使用及实践经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669732018301045045","sourceKey":"bytedance","company":"字节跳动","title":"多模态大模型算法工程师 - TikTok内容安全算法","city":"上海","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669732018301045045/detail","duty":"团队介绍：国际化内容安全算法研究团队致力于为字节跳动国际化产品的用户维护安全可信赖环境，通过开发、迭代机器学习模型和信息系统以更早、更快发掘风险、监控风险、响应紧急事件，团队同时负责产品基座大模型的研发，我们在研发过程中需要解决数据合规、模型推理能力、多语种性能优化等方面的问题，从而为平台上的内容审核、搜索、推荐等多项业务提供安全合规，性能优越的基座模型。\n\n1、负责国际化搜索场景下多模态大模型安全体系的建设与演进，统筹搜索结果（视频、图像、文本）、搜索推荐词（Query Suggestion）、AI搜索（AI Search）等多链路的内容安全算法能力，打造可持续演进的搜索安全系统；\n2、负责搜索场景下多模态大模型体系建设，包括大规模基座预训练、指令微调（SFT）、强化学习（RLHF、DPO、PPO、GRPO）及后训练（Post-training）等前沿方向探索，构建安全相关的Reward Model/Preference Model，提升模型在复杂安全场景下的泛化能力与鲁棒性；\n3、构建具备Query-Context-Aware能力的搜索安全判断模型，解决搜索高吞吐、长尾Query、跨模态、跨语种场景下的内容理解与风险识别问题，优化风险召回与精排（Recall&Ranking）策略，提高安全覆盖率与精度；\n4、推动LLM安全对齐、Prompt Safety、RAG安全增强、多轮对话风险控制等前沿技术在AI搜索中的落地，主导红蓝对抗（Red Teaming）与安全评测体系建设；\n5、探索RL、自适应推理、长上下文建模、Agent系统、RAG等新技术在搜索安全场景中的可行路径，跟踪前沿研究成果（如NeurIPS、ICLR、CVPR、ACL、SIGIR等），将最新技术引入业务落地并形成突破；\n6、在团队内发挥技术引领作用，定义研究方向，推动跨团队协作与技术标准升级，突破现有搜索安全治理系统的流程，探索下一代搜索内容安全业务交互模式。","requirements":"1、2027届获得硕士及以上学位，计算机、电子、人工智能、数学等相关专业背景；\n2、扎实的机器学习与深度学习基础，在LLM/VLM/MLLM、计算机视觉、NLP或多模态领域有研发经验；熟悉大模型的预训练、微调与对齐方法（SFT/RLHF/DPO/PPO/GRPO等），有实际落地或开源大模型项目经验者优先；精通PyTorch/TensorFlow等深度学习框架，熟悉Transformers/Qwen等主流大模型生态，具备大规模分布式训练与模型优化经验；\n3、有搜索、推荐、信息检索或Query理解相关算法系统建设经验，熟悉搜索召回/排序、Query-level意图识别等技术者优先；对内容安全、风险建模、审核场景或LLM Safety有深入理解者优先；\n4、具备快速决策与落地的能力，优秀的分析问题与解决问题的能力，并热衷于解决具有挑战性的问题；对技术充满热情，具备良好的沟通能力和团队合作精神，能够推动跨团队协作与技术标准建设；\n5、在顶会/顶刊（NeurIPS、ICML、ICLR、CVPR、ACL、SIGIR、EMNLP等）有论文发表，或在业界大模型/搜索相关项目中担任核心研发角色者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668648081264527621","sourceKey":"bytedance","company":"字节跳动","title":"用户增长产品经理（SEA） - TikTok Shop","city":"上海","category":"产品","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668648081264527621/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商。平台汇聚全球优质商家与创作者，通过短视频、直播等多场景连接消费者，让新奇好物畅销全球，让美好生活触手可得。目前团队分布在美国、英国、法国、印尼、墨西哥、中国等全球多个国家和地区，在这里你将有机会深入国际业务场景，面向全世界商家及用户，和跨区域团队协作，共同探索创新购物模式。期待和优秀的你一起创造更多可能！\n\n1、负责区域市场用户增长（拉新、促活、复购），基于市场洞察与数据分析开展策略设计与落地；\n2、结合用户生命周期特征，制定差异化运营策略或产品方案，涉及补贴、投放、玩法工具等手段；\n3、基于市场研究与数据分析，制定补贴和投放标准，推动运营及经营效率提升；\n4、深化对全球市场的理解，与供给、产品、算法等团队紧密合作，推动方案与产品落地。","requirements":"1、2027届获得本科及以上学历，专业不限；\n2、具备较高的数据逻辑和数据敏感性，熟练使用SQL、Excel，掌握分析工具如R，Python，SAS等加分；\n3、对用户购买决策路径有良好的敏感度，有结合数据和用户洞察、制定增长策略或产品的具体实践案例者优先；\n4、英文可作为工作语言、有国际化留学经验加分；\n5、责任心强、可跨部门沟通和处理问题；快速适应变化。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668647742696261941","sourceKey":"bytedance","company":"字节跳动","title":"全球物流网络规划工程师 - TikTok Shop","city":"深圳/上海/杭州","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668647742696261941/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商。平台汇聚全球优质商家与创作者，通过短视频、直播等多场景连接消费者，让新奇好物畅销全球，让美好生活触手可得。目前团队分布在美国、英国、法国、印尼、墨西哥、中国等全球多个国家和地区，在这里你将有机会深入国际业务场景，面向全世界商家及用户，和跨区域团队协作，共同探索创新购物模式。期待和优秀的你一起创造更多可能！\n\n1、参与全球物流网络的日常分析与规划工作，梳理仓储、运输、配送等环节的基础数据与业务现状，为仓网规划和运营决策提供支持；\n2、参与仓网布局、线路调整、库存与时效等规划优化项目，将成本、时效、服务体验等因素拆解为结构化分析问题，输出分析结论和方案建议；\n3、使用Excel、SQL、Python等工具开展数据处理、建模与指标分析，支持需求预测、运量拆分、产能利用率、履约稳定性等核心指标的监控、复盘与预警；\n4、尝试引入人工智能、优化模型、规则引擎等能力，协助搭建网络规划和质量诊断的分析框架与工具，提升分析效率和方案落地效果；\n5、协同部门关键合作方定位业务问题，跟进方案试点与效果评估，并持续关注全球供应链、跨境电商、国际化仓、智能物流、供应链数字化及网络优化等领域的发展趋势。","requirements":"1、2027届获得本科及以上学历，物流工程、工业工程、供应链管理、运筹学、数学、统计学、计算机科学、数据科学等相关专业优先；\n2、具备Python、R、SQL、Excel等工具使用经验，能够使用编程方式开展数据分析、建模或简单优化，参与过商业分析、供应链建模等相关项目者优先；\n3、了解线性规划、整数规划、启发式算法、元启发式算法、仿真分析等方法，熟练应用过LP、MIP求解器，或熟悉离散事件仿真、蒙特卡洛模拟等方法者优先；\n4、了解人工智能、机器学习在运力预测、异常识别、质量监控等场景中的应用，参与过物流网络规划、仓库布局优化、运输优化等相关项目者优先；\n5、具备较强的逻辑思维、问题拆解能力和英文口语、阅读与写作能力，能够将复杂业务问题转化为结构化分析方案并形成清晰结论，有全球供应链、跨境电商、国际物流、制造业供应链相关实习经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668632630972762373","sourceKey":"bytedance","company":"字节跳动","title":"AIGC视频生成算法工程师 - Data AML","city":"上海/北京/深圳/杭州","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668632630972762373/detail","duty":"团队介绍：Data AML是字节跳动的机器学习中台，为抖音/今日头条/西瓜视频等业务提供推荐/广告/CV/语音/NLP的训练和推理系统。为公司内业务部门提供强大的机器学习算力，并在这些业务的问题上研究一些具有通用性和创新性的算法。同时，也通过火山引擎将一些机器学习/推荐系统的核心能力提供给外部企业客户。\n\n1、优化Seedance系列模型，负责提升模型通用能力的相关技术，同时重点关注模型在影视、动漫、广告、营销等生产力场景的效果；\n2、解决生成视频中的一致性、运动质量、稳定性等核心研究难题；\n3、紧跟生成方向的最新研究动态（理解生成统一、超长视频生成、流式互动视频生成等），并对创新想法进行原型验证。","requirements":"1、2027届获得硕士及以上学位，计算机、软件工程等相关专业优先；\n2、在多模态、AIGC等一个或多个领域有较深入的研究者，熟悉生成相关技术路线（扩散模型，自回归模型等），有大规模训练经验、AIGC、VLM、音视频生成等相关经验；\n3、动手能力强，具有熟练的算法和编程能力，熟悉C/C++和Python编程；\n4、工作积极主动，能与团队融洽合作相处，同时能够独立完成研究工作；\n5、具有优秀的基础算法、扎实的机器学习基础，熟悉CV、AIGC、NLP、RL、ML等领域的技术，在CVPR、ECCV、ICCV、NeurIPS、ICLR、SIGGRAPH或SIGGRAPH Asia等顶级会议/期刊上发表论文者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668572675926018309","sourceKey":"bytedance","company":"字节跳动","title":"算法工程师（风控合规方向） - 国际支付","city":"上海/北京/深圳","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668572675926018309/detail","duty":"团队介绍：国际支付，立足于为字节跳动国际化业务提供专业的支付和金融服务，专注于全球支付产品线的质量和效率，确保为国际产品提供高度可靠和稳定的服务，建立国际支付产品和能力，同时在高效助力业务快速拓展的同时，打造行业领先的支付和金融产品能力。团队当前所提供的产品和服务，遍布全球多个国家和地区，团队拥有丰富的国际化产品研发经验；同时这里有全球超大规模的支付网络；覆盖多业务场景的海外钱包及金融产品解决方案；围绕分布式一致性、高并发、高可用、资金安全在内的核心技术能力攻坚；LLM等前沿AI技术在支付&金融服务中的探索、研发和应用。另外，我们在全球设立团队，团队同学背景多元，不同的思维方式，打造了一个多元、碰撞、融合、包容的工作环境。我们邀请你来此成长、专研，发掘无限的潜力，一起应对技术和业务以及跨国合作上的挑战，还有跨文化交流机会在等你！\n\n1、开发并优化Prea、A、B等信贷PD模型；\n2、推动用户行为序列、消费能力、欺诈特征挖掘，推动自有数据、三方数据的特征体系建设；\n3、熟悉大模型调优，通过大模型挖掘用户的行为特征，并完成画像体系建设；\n4、利用深度学习算法能力，解决跨国家、跨地区的通用模型建设，做到全球视角下的模型开发；\n5、研究前沿机器学习算法在领域的实践和应用。","requirements":"1、2027届获得本科及以上学历，数学或计算机专业优先；\n2、扎实的计算机算法基础，熟悉机器学习基本理论，熟练掌握Python/Java/Scala等建模语言，熟练使用SQL/Hive/Spark/Flink等数据统计工具；\n3、熟悉机器学习、多目标学习、深度学习、在线学习算法，良好的编码习惯和工程优化能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668295110720145669","sourceKey":"bytedance","company":"字节跳动","title":"后端开发工程师（数据工程） - TikTok内容安全平台","city":"北京","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668295110720145669/detail","duty":"团队介绍：国际化内容安全平台团队致力于为字节跳动国际化产品的用户维护安全可信赖环境，通过开发、迭代机器学习模型和信息系统以更早、更快发掘风险、监控风险、响应紧急事件，以人工智能技术支持业务发展，力求更高效、更敏捷、更全能地维护站内生态安全。\n\n1、参与国际化内容安全数据建设及AI分析能力建设，负责数据产品、查询服务及AI能力的架构设计与研发，提升数据分析效率和平台智能化水平；\n2、与算法、业务、产品及数据科学团队紧密合作，建设面向AI Agent、智能分析及自动化决策的数据服务能力，支持复杂业务场景快速落地；\n3、参与实时/离线数据链路、实验平台、指标体系、数据质量及可观测性平台建设，持续提升数据准确性、稳定性和开发效率；\n4、参与高并发、高可用、海量数据处理系统的设计与优化，解决存储、计算、查询性能、系统解耦、多租户隔离等关键技术问题；\n5、参与数据平台架构演进，探索AI Native Data Platform、LLM、Agent、向量检索、智能查询等新技术在业务中的落地实践；\n6、持续推动平台工程化建设，包括研发规范、自动化测试、性能优化、稳定性治理及研发效率提升。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程、人工智能、大数据等相关专业优先；\n2、热爱计算机科学与互联网技术，熟练掌握至少一门编程语言，包括但不限于Java、Go、C/C++、Python，掌握扎实的计算机基础知识，深入理解数据结构、算法、操作系统及计算机网络；\n3、具备良好的系统设计能力，对分布式系统、数据库、大数据或云计算有一定理解，有相关项目经验者优先；\n4、具有优秀的逻辑分析能力，能够对复杂业务进行抽象建模，并设计合理的技术方案；\n5、对AI、大模型、Agent或数据平台相关技术有浓厚兴趣，具有探索精神和快速学习能力；\n6、具备良好的沟通协作能力和团队意识，能够跨团队推进复杂项目落地。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668212572303444229","sourceKey":"bytedance","company":"字节跳动","title":"AI服务策略运营 - 抖音生活服务","city":"上海","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668212572303444229/detail","duty":"团队介绍：抖音生活服务依托抖音POI （Point of Interest）、短视频、直播、搜索等，以“激发线下生意，丰富美好生活”为使命，致力于成为最值得信赖的生活服务平台，为用户提供更丰富、独特的生活体验，为合作伙伴提供包容且公平的健康营商生态。截至2025年底，抖音生活服务业务已覆盖400+城市，超过1500万家动销门店。抖音生活服务将继续携手生态伙伴，为用户提供值得心动的商品和服务。\n\n1、参与消费者服务大模型评测体系设计，覆盖智能客服、服务辅助、工单自动化等多类AI应用场景，完善评测方法论与评估维度，推动评测能力在不同业务场景的复用落地；\n2、参与AI服务工作流提效落地，梳理消费者服务运营工作流程，识别低效环节与提效机会，结合大模型能力设计智能化流程优化方案，推动AI工具应用；\n3、参与智能服务解决方案设计，基于不同生命周期下的用户问题，输出适配不同场景的服务方案；\n4、参与横向运营机制建设，协助搭建运营数据看板、定期复盘机制与跨团队沟通机制。","requirements":"1、2027届获得本科及以上学历，经济金融学类、数学统计学类、计算机类、管理学类等相关专业优先；\n2、对用户体验敏感，对本地生活商业业态熟悉，能刻画消费者在消费中的需求和痛点；\n3、对AI大模型、LLM行业应用、智能服务运营方向有浓厚兴趣，愿意探索AI技术在本地生活服务领域的落地价值与业务实践，有AI评测、服务运营、策略运营、产品优化等相关实习经历者优先；\n4、具备较强的逻辑分析能力与结构化思考能力，能够从复杂信息中提炼关键问题并形成清晰结论；\n5、做事认真细致，责任心强，能够在评测、标注、规则制定类工作中保障交付质量；\n6、具备良好的跨团队沟通协同能力与项目推进意识，能够联动多方对齐目标、同步进度，推动方案落地。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668156130133199109","sourceKey":"bytedance","company":"字节跳动","title":"Agent开发工程师 - 抖音","city":"深圳/杭州/北京","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668156130133199109/detail","duty":"团队介绍：抖音致力于打造一个开放、积极、多元、友善的平台，鼓励表达、沟通和记录，激发创造，丰富人们的精神世界，让现实生活更美好。我们通过AI算法驱动的个性化推荐与智能创作工具，满足用户表达、学习、娱乐、社交、消费等需求。回顾抖音一路走来的历程，我们在帮助亿万用户记录美好生活的过程中，努力变得更好。\n\n1、负责大模型Agent体系（Harness、MAS等）架构设计和落地，搭建高可用、高扩展的Agent研发平台；\n2、攻坚Agent核心技术，优化Prompt工程、Skill管理、Context管理、Harness执行管控机制，解决落地技术瓶颈；\n3、学习和研究新技术以提高测试效率和质量；\n4、对产品提出改进建议以建立较好的用户感受，对项目提出改进建议以提高项目整体效率。","requirements":"1、2027届获得本科及以上学历，计算机等相关专业；\n2、扎实的数据结构和算法基础，熟悉至少一门编程语言，包括但不仅限于：Go、Python、Java、OC、C、C++、PHP；\n3、对AI技术与Agent系统有浓厚兴趣，具备主动学习与动手实践能力，有独立搭建过LLM Agent或Demo者优先；\n4、持续追踪最新的技术进展（Claude code、Deepresearch等），能快速理解和复现相关技术博客或者期刊的技术方案者优先；\n5、了解常用客户端、服务端开发或测试工具，如自动化框架、压测工具、大数据处理工具者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667843403313318197","sourceKey":"bytedance","company":"字节跳动","title":"算法工程师 - Pangle","city":"上海/北京/杭州","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667843403313318197/detail","duty":"团队介绍：Pangle 是国际化业务旗下独家广告联盟网络，目前已覆盖近 50 个市场。该平台通过值得信赖、智能且注重实效的广告解决方案，助力广告主对接优质本地发布渠道，将营销触角延伸至整个国际化业务生态。Pangle 已在 20 多个新兴市场构建行业领先的广告网络，于亚太、中东及拉丁美洲地区拥有经市场验证的成功经验。与此同时，Pangle 为开发者打造广告变现与用户获取的闭环增长，助力开发者获取更高收益、更优质用户，全面释放成长潜能。\n\n1、负责Pangle广告投放中出价策略与算法，及定向、召回、精排、出价等各阶段模型的改进，持续优化变现效率和广告ROI；\n2、负责大规模Online Learning的深度模型效率改进和效果优化；\n3、负责利用策略和模型手段，从度量归因、投放体验、长期可持续的广告业务等方面，探索最新的商业化变现技术和商业产品设计，提出行业创新性解决方案；\n4、参与CTR、CVR等广告模型的设计、开发和迭代。","requirements":"1、2027届获得本科及以上学历，计算机、机器学习和模式识别相关专业；\n2、热爱计算机科学和技术，对人工智能类产品有浓厚兴趣；\n3、具优秀的编码能力，熟悉Linux开发环境，熟悉C++和Python语言优先；\n4、有扎实的数据结构和算法功底，熟悉机器学习、自然语言处理、数据挖掘、分布式计算、计算机视觉、计算机图形、语音识别与合成中一项或多项；\n5、对推荐系统、计算广告、搜索引擎相关技术有经验者优先；\n6、优秀的分析问题和解决问题的能力，对解决具有挑战性问题充满激情。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667839080812595461","sourceKey":"bytedance","company":"字节跳动","title":"平台游戏AI产品工程师（抖音AI产品人才校招） - 抖音社交与互动","city":"深圳/北京","category":"产品","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667839080812595461/detail","duty":"团队介绍：抖音社交与互动团队服务于抖音连接人与人的愿景，希望为用户提供更好的社交、创作体验，以拓宽抖音的使用场景，成为更多人打开和使用抖音的新理由，提升抖音的用户规模。我们是一支有朝气、背景多元的团队，致力为用户提供最佳的产品体验，热衷听取用户声音和反馈，也运用科学严谨的分析方法，仔细衡量我们的工作成果。抖音社交与互动欢迎你的加入，和我们一起做有挑战的事情。\n\n这是抖音面向具备AI能力的同学发起的校招项目，覆盖产品、策略运营方向。\nAI 正在重新定义产品，也在重新定义\"做产品\"这件事 —— AI Native 的产品，需要你既能理解大模型技术边界，又能定义产品价值。\n如果你也有着许多的奇思妙想， 欢迎加入抖音，把想法落地成亿万用户真实可感的产品体验，来抖音，和我们一起探索 AI 产品的下一种可能！\n\n1、游戏开发工具建设：针对游戏开发的各环节（玩法原型构建、游戏生成链路、美术素材生成、开发测试辅助等场景），结合AIGC技术，协助完善高效、可规模化的应用方案并推动落地；\n2、分析跟进开发者需求：跟踪游戏开发者动态，结合用户反馈与数据表现，挖掘开发者痛点并提出产品优化建议；\n3、推动跨团队协作：协调技术、运营团队完成需求评审、排期与上线，通过AB测试验证功能效果，确保项目高效交付；\n4、技术追踪与实验：紧密跟进AIGC（图像、视频、音频、代码等）技术等领域的最新进展，设计并执行在具体游戏/玩法中的技术验证实验。","requirements":"1、2027届获得本科及以上学历，计算机科学、人工智能、数字媒体技术、游戏设计等相关专业优先；\n2、熟悉生成式AI的基本原理与应用，有AIGC工具的实际使用和调优经验；了解游戏开发流程及常用工具（如Unity、Cocos、H5等），对游戏互动逻辑有基本认知；\n3、强烈的探索欲与执行力：对AI前沿技术充满好奇，具备出色的自主学习能力，并能快速将想法转化为实践；结果导向与业务敏感度：不只关注技术本身，更能思考技术对业务产能、用户体验和商业价值的实际影响；优秀的沟通与协同能力：能清晰表达技术概念与实验结论，推动跨团队协作；\n4、有AIGC项目实践经验，或独立完成的游戏Demo/互动项目；在技术社区（GitHub、技术博客、论文阅读等）有活跃贡献或深度沉淀；对小程序/小游戏生态有深入了解。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667792982096480565","sourceKey":"bytedance","company":"字节跳动","title":"C端账号AI产品经理（抖音AI产品人才校招） - 抖音社区治理","city":"北京","category":"产品经理","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667792982096480565/detail","duty":"团队介绍：抖音致力于打造一个开放、积极、多元、友善的平台，鼓励表达、沟通和记录，激发创造，丰富人们的精神世界，让现实生活更美好。我们通过AI算法驱动的个性化推荐与智能创作工具，满足用户表达、学习、娱乐、社交、消费等需求。回顾抖音一路走来的历程，我们在帮助亿万用户记录美好生活的过程中，努力变得更好。抖音社区治理团队负责抖音的社区治理工作，包括视频、直播等多体裁的内容治理，以及安全产品中台能力建设。\n\n这是抖音面向具备AI能力的同学发起的校招项目，覆盖产品、策略运营方向。\nAI 正在重新定义产品，也在重新定义\"做产品\"这件事 —— AI Native 的产品，需要你既能理解大模型技术边界，又能定义产品价值。\n如果你也有着许多的奇思妙想， 欢迎加入抖音，把想法落地成亿万用户真实可感的产品体验，来抖音，和我们一起探索 AI 产品的下一种可能！\n\n1、参与抖音用户账号体系全流程产品工作，覆盖注册、登录、注销、身份核验等模块，协助完成产品迭代与体验优化；\n2、负责用户账号侧体验问题治理，跟进用户反馈、客服客户投诉、整理高频产品问题、流程卡点，输出问题复盘与优化建议；\n3、协助完成需求调研、产品分析、流程梳理、原型绘制及PRD撰写，配合团队完成需求评审、迭代跟进、上线验收与数据复盘，保障需求落地闭环；\n4、监控账号体系业务数据，包括各链路的转化率、用户反馈量等，通过数据变化发现业务问题，支撑产品优化决策。","requirements":"1、2027届获得本科及以上学历，计算机相关专业优先；\n2、具备基础的产品思维，逻辑清晰、善于观察用户体验问题，有产品实习、项目策划、产品分析经验者优先；\n3、拥有基础的数据敏感度，可通过数据和用户反馈挖掘产品优化空间；\n4、沟通表达清晰，执行力强，具备良好的跨团队协作能力，愿意深耕用户基建、账号体验方向；\n5、熟悉AI，能熟练使用相关工具，并应用在工作中，探索业务与AI的结合方向。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667440763903232261","sourceKey":"bytedance","company":"字节跳动","title":"AI产品经理（Agent方向） - 剪映CapCut","city":"北京/深圳","category":"产品","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667440763903232261/detail","duty":"团队介绍：剪映CapCut团队成立七年，先后孵化了剪映、CapCut、醒图、Hypic、即梦、Dreamina、Pippit等产品，覆盖视频、图片、Al生成、视频营销等多领域，打造与AI结合的全球化产品矩阵。\n我们的愿景是：激发想象力，成为全球领先的互动内容平台，创造独特的体验和价值。\n我们期待你的加入，一同极致打磨用户体验,构建创意生态和商业化能力，定义AI与创作结合的无限可能，让内容互动更简单、更精彩!\n\n1、产品规划与迭代：负责剪映Agent产品的路线规划，包含LUI体验设计与技术架构演进，洞察C端用户需求与技术趋势，平衡C端用户的创作体验和Agent架构的先进性；\n2、体验与交互设计：主导产品界面设计和用户流程优化，针对Agent特性和用户视角，设计用户易用的LUI体验；\n3、Agent技术策略：具备对Agent技术策略的理解与洞察，能够围绕模型能力、工具调用、任务编排和评测闭环设计可落地的产品方案；\n4、用户研究与洞察：通过用户调研、社群反馈、数据分析等方式，持续挖掘用户需求痛点，持续优化产品的易用性；\n5、跨团队协作：与研发、设计等团队紧密协作，善用AI工具推动需求高效运转，精简协同流程，跟进上线后的用户反馈和数据表现，牵引团队快速迭代。","requirements":"1、2027届获得本科及以上学历，计算机相关学历背景优先；\n2、有校园AI项目实践经验优先，影像创作爱好者优先，对潮流内容和AI工具有敏感度，对创作有热情；\n3、对AI技术、Agent智能体领域有浓厚的兴趣，使用过多款AI产品并对产品逻辑有深入洞察，对用户体验有追求；\n4、良好的逻辑思维能力和换位思考能力，能够高效沟通、跨团队协同。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667086494969530629","sourceKey":"bytedance","company":"字节跳动","title":"Agent开发工程师 - 数据平台","city":"北京/上海/杭州/南京/深圳","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667086494969530629/detail","duty":"团队介绍：数据平台是字节跳动数据中台部门，为公司多业务线（包括抖音、电商、直播和生活服务等）提供一站式大数据解决方案，涵盖数据的生产、清洗、传输、建模、分析等全流程链路，提供数据开发、实验评估、画像标签、增强分析等多元场景解决能力。同时，数据平台部门也致力于把字节跳动积累沉淀的数据中台解决方案做商业化输出，让更多行业能够应用我们的产品能力构建自己的数据中台。在火山引擎上，我们提供了营销增长套件，数据中台等相关产品解决方案，为泛互联网、金融、汽车、新零售等行业提供了行业解决方案。\n\n1、负责数据平台通用或垂类Agent能力的研发工作，参与Agent Framework、任务编排、工具调用、RAG、Workflow等核心能力建设；\n2、参与面向内部或To B业务场景的Agent平台设计与开发，提升Agent能力的复用性、扩展性和易用性；\n3、参与大模型应用后端服务建设，包括Prompt优化、知识库构建、检索增强、工具接入、效果评估与链路优化；\n4、支撑业务快速迭代，保障Agent服务的稳定性、可用性与响应效率；\n5、关注大模型、AI Agent、数据平台等方向的前沿技术，并探索在实际业务中的应用。","requirements":"1、2027届获得本科及以上学历，计算机等相关专业优先；\n2、具备扎实的编程基础，熟悉Python、Java、Go等至少一种编程语言，有良好的代码习惯；\n3、了解大模型应用开发相关技术，包括Prompt Engineering、RAG、Agent、Workflow、工具调用、向量检索等，有相关项目经验优先；\n4、具备良好的学习能力和沟通能力，责任心强，积极主动。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7665590441060419845","sourceKey":"bytedance","company":"字节跳动","title":"广告策略产品经理 - 广告业务","city":"上海/北京/深圳","category":"产品","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7665590441060419845/detail","duty":"团队介绍：广告业务为抖音集团的商业化提供产品规划、迭代与运营，负责端到端大型广告系统建设、覆盖抖音、今日头条、番茄小说、红果短剧、穿山甲等产品矩阵，践行\"激发生意新可能\"理念，致力于让营销更省心、更高效、更美好，推动商业的可持续增长。领先的Al营销能力、成熟的趋势营销理念，让不分体量、地域的企业及个体，在这里都能通过数字化技术激发创造、驱动生意。在这里，你将投身建设面向未来的数字营销能力，接触到先进的商业产品架构、模型、算法、运营模式和营销理念、在互联网广告行业始终创新。\n\n1、负责商业化广告策略产品工作，包括但不限于广告流量策略、投放策略产品、广告出价策略产品、广告创意策略产品、AIGC等新兴策略平台产品等；\n2、洞察和理解上述领域内具体工作事项的需求，结合反馈和用户体验，设计和迭代业务核心指标和方向，产出产品方案，包括但不限于抽象产品业务模块的设计、产品策略、算法模型的应用和落地等；\n3、通过市场机制设计，提升商业化广告产品生态健康度和活力，提升用户、商家和平台的共赢效率；\n4、推进内部交流，协同业务团队、算法、研发团队，保证团队合作的顺畅，不同产品之间的协作等。","requirements":"1、2027届获得本科及以上学历，专业不限；\n2、具备产品规划能力，能主导产品方向和制定长期规划，并拆分为可实施项目；\n3、良好的产品策划能力、设计能力，准确识别并深刻理解客户和用户需求；\n4、良好的沟通协调能力，可独立完成跨职能和跨部门沟通；\n5、有互联网商业产品实习经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7660366216798062853","sourceKey":"bytedance","company":"字节跳动","title":"AI全栈开发后端实习生-引擎工具","city":"上海","category":"后端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7660366216798062853/detail","duty":"日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n团队介绍：TikTok作为覆盖150个国家和地区的国际短视频平台，始终以“发现真实、有趣的瞬间，让生活更美好”为初心，全球总部设于洛杉矶与新加坡，办公网络遍及纽约、伦敦、东京等全球核心城市，影响力触达亿万用户。\n引擎工具团队作为业务中台，以 “建设业界领先的 AI-3D互动特效创作平台”为核心愿景，研发覆盖美颜，美妆，2D互动、3D渲染、物理仿真，AR增强、AIGC特效等多品类的AI-3D互动能力，技术上涉及3D图形渲染，物理仿真模拟，AI-3D的重建和3D生成，端上3D创作工具等范畴，助力短视频/直播/社交/XR/商业化等多业务场景完成高质量的3D内容创作和互动表达。\n在这里，有大牛带队探索前沿AI-3D的技术，你的每一行代码、每一次技术突破都将服务亿万用户，突破想象空间；在这里，团队专业纯粹，合作氛围平等轻松，让你在全球化平台上专注成长；目前上海、北京、深圳、美国圣何塞已开放多个岗位机会，期待你的加入！\n\n1、参与AI UGC游戏生成及AIGC平台等多领域业务的全栈建设；\n2、参与游戏社区、资源库、数据管理平台等配套平台的服务建设；\n3、深度运用AI工具开展工作，提升代码开发效率与质量，主动探索AI工具在多端开发场景的优化空间；\n4、关注AI Coding、全栈开发前沿技术与行业趋势，跟进业内最新工具与应用方案，结合业务场景提出创新思路。","requirements":"1、硕士及以上学位在读，计算机相关专业优先；\n2、熟悉Web前端（TS/Vue/React等）或后端（Node.js/Python/Java等），有全栈开发经验优先，熟练运用任一AI Coding工具（TRAE/Claude Code/Codex等）；\n3、具备可落地的项目经验，非课程作业类项目优先；\n4、热爱AI相关技术，对大型应用和工程感兴趣，富有极客精神；\n5、责任心强，工作认真细致，具备良好的服务意识，具有良好的团队沟通与协作能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7652302955351165189","sourceKey":"bytedance","company":"字节跳动","title":"基于大系统大算力的超大规模推荐模型建模（算法）-Data AML（北京/杭州）","city":"北京","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7652302955351165189/detail","duty":"团队介绍：Data AML是字节跳动的机器学习中台，为抖音/今日头条/西瓜视频等业务提供推荐/广告/CV/语音/NLP的训练和推理系统。为公司内业务部门提供强大的机器学习算力，并在这些业务的问题上研究一些具有通用性和创新性的算法。同时，也通过火山引擎将一些机器学习/推荐系统的核心能力提供给外部企业客户。\n\n课题介绍：\n大规模推荐系统正在越来越多的应用到短视频、文本社区、图像等产品上，期望进一步通过算法与工程Co-design，探索推荐算法和大语言模型/多模态理解的深度融合主要研究方向包括：LLM4Rec、跨端跨场景的Foundation Model、千亿级参数规模的模型 和 多模态大模型。工程上研究方向包括多模态样本的高效表征、基于PyTorch架构的高性能推理引擎与训练框架构建，以及异构硬件在推荐场景下的性能极限优化；算法侧研究方向包括LLM4Rec技术路径的设计、千亿级底座模型的研发以及多模态协同训练（Co-training）等核心课题，旨在通过技术创新定义下一代工业级推荐范式。\n\n课题挑战：\n1、千亿模型的训练和推理优化；\n2、多模态表征统一与高效融合难度大；\n3、Foundation Model的设计和工程优化；\n4、算法工程协同设计与异构硬件适配复杂。\n\n课题价值：\n1、技术价值：突破多模态表征融合、超大规模模型训练推理瓶颈，完善算法与工程协同设计体系，推动异构硬件适配与高性能框架国产化落地；\n2、业务价值：提升推荐精准度与泛化能力，突破现有推荐系统模态局限，赋能短视频、文本社区等多产品，降低算力成本，助力业务规模化增长。","requirements":"1、2027届毕业，获得博士学位，计算机、软件工程、自动化等相关专业优先；\n2、在推荐广告或者大模型领域有相关经验优先；\n3、扎实的机器学习、NLP基础和出色的探索能力，在ACL/NeurIPS/ICML/ICLR/CVPR等会议上发表论文者优先；\n4、积极性强，愿意接受挑战，具有独立解决问题的能力，良好的团队合作意识和沟通能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7582202865793730869","sourceKey":"bytedance","company":"字节跳动","title":"项目管理实习生-TikTok用户增长","city":"上海","category":"项目管理","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7582202865793730869/detail","duty":"日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n团队介绍：TikTok是一个覆盖150个国家和地区的国际短视频平台，我们希望通过TikTok发现真实、有趣的瞬间，让生活更美好。TikTok 在全球各地设有办公室，全球总部位于洛杉矶和新加坡，办公地点还包括纽约、伦敦、都柏林、巴黎、柏林、迪拜、雅加达、首尔和东京等多个城市。\n \n我们是 TikTok用户增长技术团队，我们是公司全球战略的核心引擎之一，是连接全球亿万用户与精彩内容的第一座桥梁。我们的使命非常纯粹：用技术驱动增长，让TikTok成为全球每一个角落的用户发现快乐、激发创造的平台。\n我们的工作远不止是写代码，我们是用技术解决真实世界商业问题的增长建造师。在业务上，我们直面激烈的技术前沿战场： 我们负责全球用户的拉新、促活、留存与变现，你都将会深度参与；你的每一个技术决策和代码实现，都助力着我们全球化业务的发展；这种直接创造价值、见证全球性影响的成就感，是无与伦比的。在技术上，我们挑战的是业界硬核的难题：极致性能下的全球高并发、复杂至极的全球化架构与合规、数据驱动与AI的科学赋能、用户端侧体验的极致打磨。\n\n1、协助TikTok用户增长产品研发团队，跟进项目，协助完成相关项目的流程设计、执行落地、总结改进等；\n2、针对团队协作中发现的问题，归纳总结，协助改进；\n3、帮助团队进行日常通用任务的管理，有效地跟进、推动，确保交付；\n4、在日常过程中，推动团队进行知识库的沉淀、归档等。","requirements":"1、本科及以上学历在读，计算机、软件工程相关专业优先；\n2、有较强的沟通能力，良好的与人交流协作的能力；\n3、有较高的责任心，以及目标导向的落地执行能力、问题解决能力；\n4、乐意迎接变化接受挑战，持续学习，自律；\n5、能保证一周至少4天实习，持续六个月以上；\n6、加分项：英语流利、热爱项目管理，有技术背景。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7561337927117719861","sourceKey":"bytedance","company":"字节跳动","title":"软硬件协同实习生-服务器","city":"杭州","category":"后端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7561337927117719861/detail","duty":"日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n团队介绍：服务器部门的主要职责是通过持续开展业务需求跟踪和行业洞察，以及对各业务场景开展系统性能分析，为公司的全球业务打造具备高性价比和高可靠性的通用计算、存储和智能计算（AI）等产品与解决方案。在技术层面，深入钻研计算体系架构的研究与开发、CPU/GPU及部件的定制与评估、高速电路设计、新型供电散热技术、固件开发、驱动开发、内核及操作系统、编译器、可靠性、可用性和可维护性（RAS）等领域，推动软硬件的联合设计与优化，在人工智能时代为公司提供最具竞争力的算力和存储基础支撑。\n\n1、开发和使用性能分析工具、性能模拟器、仿真工具进行实验，验证通算和智算领域新架构方案的性能收益；\n2、研究和分析数据中心关键Workload的特征，探索软硬件协同设计与优化方案；\n3、参与CPU、GPU及其他开放架构生态的研究，探索开源软硬件协同优化的可能性；\n4、撰写研究报告，并有机会参与学术论文或专利的撰写。","requirements":"1、本科及以上学历在读，计算机体系结构、电子工程、计算机科学等相关专业优先；\n2、具备良好的编程能力，熟悉C/C++、Python；\n3、熟悉计算机体系结构基本知识，如流水线、缓存、分支预测、乱序执行等；\n4、了解x86、ARM、RISC-V或其他主流CPU指令集，有相关优化经验者优先；\n5、熟悉CPU、GPU性能分析工具和仿真器，如Perf、VTune、Gem5、Simics、GPGPU-Sim等；\n6、具备良好的分析能力和研究能力，有学术论文发表经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7532024443712571666","sourceKey":"bytedance","company":"字节跳动","title":"多模态大模型评测实习生-Seed","city":"北京","category":"机器学习","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7532024443712571666/detail","duty":"日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n团队介绍：字节跳动Seed团队成立于2023年，致力于寻找通用智能的新方法，追求智能上限，为科技和社会发展作出贡献。\nSeed团队在AI领域拥有长期愿景与决心，团队研究方向涵盖MLLM、GenMedia、AI for Science、机器人等，在中国、新加坡、美国等地设有实验室和岗位。目前，团队已推出业界领先的通用大模型以及前沿的多模态能力，支持豆包、即梦、TRAE等超过50个应用场景，并通过火山引擎开放给企业客户。第三方数据显示，豆包App用户量在中国市场排名第一，豆包大模型日均Token调用量行业领先。\n\n1、参与多模态大模型评测体系建设，包括但不限于ASR/TTS/音乐生成/多模态交互/Agent等，制定评测方案、评测指标、构建评测集，形成行业Benchmark；\n2、开发自动化、可扩展、可靠的评测系统，提高自动评估的占比，缩短模型评测周期；\n3、对模型能力深度分析，明确模型的优势与缺陷，指导模型发展，探索模型能力边界，完善与扩展评测的维度，构建下一代评测系统；\n4、构建“数据-模型-评测”飞轮，驱动大模型迭代，帮助实现AGI；\n5、追踪大模型方向前沿进展，积极主动地学习和探索新的评测及分析的方法和技术。","requirements":"1、本科及以上学历在读，计算机及相关专业优先；\n2、在语音、多模态、机器学习等一个或多个领域有较深入的研究者；\n3、熟悉C/C++、Python等编程语言，有较强的工程能力；\n4、具有出色的分析、解决问题的能力，有自主探索解决方案的能力者；\n5、对模型评测充满兴趣，具有良好的沟通协作能力，工作积极主动，能够与团队融洽合作，一起探索新技术，推进技术进步。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7689014591235623173","sourceKey":"bytedance","company":"字节跳动","title":"剪映市场实习生 - 剪映CapCut","city":"深圳/北京","category":"市场","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7689014591235623173/detail","duty":"团队介绍：剪映CapCut团队成立七年，先后孵化了剪映、CapCut、醒图、Hypic、即梦、Dreamina、Pippit等产品，覆盖视频、图片、Al生成、视频营销等多领域，打造与AI结合的全球化产品矩阵。\n我们的愿景是：激发想象力，成为全球领先的互动内容平台，创造独特的体验和价值。\n我们期待你的加入，一同极致打磨用户体验,构建创意生态和商业化能力，定义AI与创作结合的无限可能，让内容互动更简单、更精彩!\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、协助项目组完成市场传播工作：包括但不限于选题策划、渠道规划、案例包装等；\n2、协助项目组完成线下活动全流程落地执行工作：包括但不限于创作者对接、活动策划、展示内容落地，活动互动装置策划、线下搭建执行，现场引导创作者拍摄及产出内容，关键合作方对接、活动落地并完成现场执行；\n3、独立完成超创社群小型活动的筹备及执行工作，密切关注行业及产品动态，根据项目需求提供研究分析支持；\n4、负责日常新媒体运营和材料整理相关工作。","requirements":"1、本科及以上学历在读，专业不限优先；\n2、有市场部、品牌部以及AI产品创意传播相关活动项目实习经验优先；\n3、可以进行简单的项目策划，具备较强的协作沟通能力，领悟能力较强，可以举一反三，有较强的视觉审美水准和文案撰写能力，有网感，可驾驭不同风格的文字，熟悉社交平台新趋势；\n4、具备良好的沟通能力和较高的执行力，主动进行内外部沟通，思维活跃，有较强的团队合作精神，责任感强，可以快速融入工作；\n5、尽快到岗，保证每周出勤4天，实习3个月，可实习6个月优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7683402900953188661","sourceKey":"bytedance","company":"字节跳动","title":"语音大模型数据运营 - AI数据与安全","city":"北京/上海","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7683402900953188661/detail","duty":"团队介绍：AI 数据与安全团队为 Seed 基座模型及 AI 原生应用提供跨模态数据服务，覆盖数据生产全流程，包含模型评估标准的制定、数据规模化生产、数据飞轮搭建，不断提升数据质量，支持模型快速迭代。\n团队由产品经理、数据工程、数据运营等跨职能人才组成，并通过与 Seed 研究员、行业专家、全球顶尖数据供应商紧密合作，从真实场景中收集反馈并分析模型表现数据，解决 AI 前沿突破过程中的复杂数据问题，推动模型性能与用户体验的双重提升。我们既是帮助模型技术迭代的一线贡献者，也是模型和 AI 产品的一手用户。\n\n1、搭建具有通用性和可拓展性的语音大模型数据标注和模型评测框架（对话、TTS、ASR等方向），与算法团队对齐标准、撰写相关培训方案，根据模型迭代方向提供高质量数据，对自动化链路搭建、数据质量评估及外部资源管理负责；\n2、结合行业趋势及业务应用场景，迭代更新评测标准、构建评测题库，负责语音大模型效果评测，定期反馈评估结果，产出评估报告，确保大模型评估结果置信；\n3、与产品算法团队协同，积极探索自动化数据生产/模型评估、数据合成等方法，提高数据标注/评测效率，持续跟踪大模型技术进展，持续探索智能高效的数据生产模式。","requirements":"1、2027届获得本科及以上学历，计算语言学、语言学、计算机、心理学、新闻等相关专业优先；\n2、具备互联网产品/运营或大模型数据、评测的实习或项目经验优先（语音方向或多模态融合方向优先）；\n3、对大模型、数据、评测有理解和认知，具备一定的PE或代码能力，对语音大模型的技术和产品应用有兴趣；\n4、具备良好的数据分析和沟通能力，能够适应多线程的工作模式。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7670449603622275333","sourceKey":"bytedance","company":"字节跳动","title":"越南商城策略实习生 - TikTok Shop","city":"上海","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7670449603622275333/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商。平台汇聚全球优质商家与创作者，通过短视频、直播等多场景连接消费者，让新奇好物畅销全球，让美好生活触手可得。目前团队分布在美国、英国、法国、印尼、墨西哥、中国等全球多个国家和地区，在这里你将有机会深入国际业务场景，面向全世界商家及用户，和跨区域团队协作，共同探索创新购物模式。期待和优秀的你一起创造更多可能！\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、协助越南商城策略团队展开模式分析和数据研究工作：包括但不限于数据收集整理与解读、业务指标的下钻分析等；\n2、结合对电商生态、产品逻辑等的理解，深度参与业务策略/执行工作：包括但不限于协助部门进行信息梳理、项目跟进和其他日常运营；\n3、基于对业务全貌、电商活动玩法的深入了解，与商城策略、运营等团队并肩作战，共同推动重点业务开展。","requirements":"1、本科及以上学历在读；\n2、每周可保证5天到岗，可连续实习；\n3、英语听说读写流利，可作为工作语言；\n4、能够熟练使用Excel进行数据处理和分析；\n5、有基础的数据分析、数据整理能力，能使用SQL、Python、Tableau、Excel优先；有数据分析、经验等优先；\n6、善于数据分析，工作细心踏实，对于突发问题和大批量任务处理具备良好的应变能力和责任心，具备较强的逻辑思维能力、自驱力和主动性，以及良好的团队沟通和合作能力，能够积极应对工作挑战，工作态度积极。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668642052930750773","sourceKey":"bytedance","company":"字节跳动","title":"运维工程师 - 安全与风控","city":"北京","category":"运维","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668642052930750773/detail","duty":"团队介绍：安全工程团队负责设计、搭建并维护字节跳动的全球安全基础设施、平台及服务。我们的核心职责是研发具备可扩展性的系统与工具，为公司全域产品的安全运营提供支撑。通过交付可靠、高性能的安全解决方案，保障字节跳动全球平台的安全，并提升业务韧性。\n\n1、参与安全相关基础设施的可靠、稳定与高效运行，协助保障相关产品的服务质量和可用性；\n2、参与安全核心系统运维自动化平台的设计与开发，协助提升系统可观测性，支持问题的发现与定位；\n3、参与推进服务在可靠性、可扩展性以及性能方面的优化工作，协助设计和实现支撑系统持续迭代的自动化能力；\n4、参与SRE工具与流程的平台化、自动化建设，支持基础能力沉淀与工程效率提升。","requirements":"1、2027届获得本科及以上学历，计算机及相关专业背景；\n2、具备扎实的编程能力，熟练掌握Go/Python等至少一种常用程序开发语言；\n3、理解Linux操作系统的基本使用，具备网络、存储、计算机体系结构等方面的基础知识；理解常见网络协议和相关服务（TCP/IP、HTTP、DNS、NAT等），了解网络设备（如路由、交换）的基本原理；\n4、理解云原生架构和容器技术的基本原理，能够使用或了解Kubernetes的核心功能特性；\n5、了解常见运维或系统组件的原理与使用方式（包括但不限于：Load Balancer、Nginx、Ansible、Argo CD、Prometheus、Grafana等），有实际使用经验者优先；\n6、具备较强的学习能力和逻辑思维能力，能够持续学习；具备良好的团队沟通与协作能力，有责任感和主人翁意识。\n\n加分项\n1、熟悉或深入使用过Kubernetes；\n2、具备云平台或基础组件的使用、运维或开发经验；\n3、具备安全相关系统或产品的使用、运维或开发经验；\n4、具备平台型系统、运维管理平台或内部工具的开发经验。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667888717122963765","sourceKey":"bytedance","company":"字节跳动","title":"Agent自进化算法工程师 - AI Platform","city":"上海","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667888717122963765/detail","duty":"团队介绍：AI Platform 团队，隶属于产品研发和工程架构部门。面向公司内部各业务线，建设统一的AI 应用基础设施和工程平台，帮助业务高效、稳定地落地大模型应用，加速 AI 产品创新。\n在平台产品侧，团队打造了新一代AgentOps平台，提供 Prompt Engineering、Agent观测、评测、数据处理、模型微调等 Agent 全生命周期解决方案，帮助Agent开发者构建效果调优的数据飞轮。产品也已成功推出商业化版本。\nAI Platform 团队还持续孵化多种面向内部与外部场景的AI应用创新产品，积极探索大模型应用的技术发展。团队氛围好，发展空间大，欢迎加入！\n\n1、负责Agent自进化平台能力建设，基于已具备的Trace采集能力，设计并实现「评测→归因→分析→优化→再评测」的通用自动迭代循环，使多个业务线能基于自身Trace数据实现Agent的持续自进化，而非仅输出优化建议；\n2、建设通用化Agent评测与归因分析引擎，从海量执行Trace中自动识别退化模式、能力短板与优化机会点，并直接驱动优化执行（Prompt自动改写、工具配置调整、记忆策略更新等），执行后自动触发再评测验证优化效果，形成持续迭代循环；\n3、探索并沉淀自进化方法论，通过评测归因、对比学习、记忆检索、自动优化等手段实现Agent行为的系统化自动调优，使优化能力从单业务定制走向跨业务通用；\n4、与评测平台、Trace分析平台产品团队紧密协作，将上述闭环能力产品化，降低业务接入成本，提升自进化方法的通用性与可迁移性。","requirements":"1、2027届获得硕士及以上学位，人工智能、计算机科学、统计学、软件工程等相关专业优先；\n2、精通Agent应用开发与调优：具备Agentic框架的实际开发与深度定制经验，熟悉主流Agent范式，在Prompt自动优化、记忆系统设计、上下文管理、工具/Skill调度等方向有深入实践；\n3、具备大模型应用认知，熟悉推理流程与能力边界，理解上下文管理、多Agent架构、Agent Teams等核心机制；\n4、扎实的机器学习与数据分析能力：熟练使用Python及常用ML库，擅长分类、聚类、归因分析、A/B实验等定量方法，能从海量Trace数据中发现问题模式；\n5、熟悉AI Coding工具，能利用AI Agent快速完成探索调研、原型开发与实验验证。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667609460127516933","sourceKey":"bytedance","company":"字节跳动","title":"用户研究分析师 - 经营办公室（用户研究）","city":"上海/北京","category":"用户研究","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667609460127516933/detail","duty":"团队介绍：隶属字节跳动经营办公室，对接抖音集团各项业务，通过对用户、创作者、商家的定性、定量研究，针对业务关键发展方向暴露问题、探索解法、激发灵感，为各产品提供支持，帮助业务在各个阶段更加健康稳固的成长。\n\n1、协助完成各类用户研究工作，包括但不限于桌面材料梳理，用户访谈，焦点小组，可用性测试，问卷数据分析等；\n2、能灵活通过各种方式快速进行市场信息扫描与分析整合，高效为业务提供有价值的信息和建议；\n3、独立思考解决问题，深度参与研究项目的执行、推进、落地工作。","requirements":"1、2027届获得本科及以上学历，心理学、社会学、市场营销、广告等相关专业优先；\n2、对用户研究和互联网产品有强烈兴趣，能独立进行分析与判断；\n3、了解常用的用户研究方法，具备数据敏感性；\n4、学习能力强、善于思考和总结，能持续积极地学习并优化工作；\n5、英语能作为工作语言者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7559162029443008786","sourceKey":"bytedance","company":"字节跳动","title":"前端开发实习生-Flow","city":"北京","category":"前端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7559162029443008786/detail","duty":"日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n团队介绍：字节跳动Flow产品研发团队，专注研究AI智能化相关业务落地，目前落地豆包、Cici 等 APP，以及对应的Bot 开发平台等AI智能化创新产品，业务和团队均处于快速发展期，成长空间大，欢迎各位同学加入！\n\n1、负责前端技术选型和开发工作；\n2、优化前端功能设计，解决各种浏览器和终端设备的兼容性问题；\n3、通过技术手段，提升用户体验并满足高性能要求；\n4、通用组件、类库编写，提升开发效率和质量。","requirements":"1、本科及以上学历在读，计算机等相关专业优先；\n2、精通HTML、CSS、JavaScript（JS）、AJAX、DOM、jQuery等技术，熟悉页面架构和布局，HTML5/CSS3等常用技术；\n3、熟悉常用UI框架（如Bootstrap、Pure、Kendo等）及Node.js，熟练使用Grunt、Gulp、Webpack等构建工具；\n4、具备MVVM框架开发经验，如React、Vue.js、AngularJS等；\n5、良好的沟通和团队协作能力，热爱技术，责任心强，能推动技术框架的实施使用。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7439719222781331719","sourceKey":"bytedance","company":"字节跳动","title":"客户端开发实习生-国际化社区","city":"上海","category":"客户端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7439719222781331719/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：国际化社区研发团队，旨在建立面向海外的兴趣种草社区，以图集和视频为内容呈现形式，专注于美妆、时尚、美食、旅行、居家、健身、艺术、萌宠等内容领域，为用户提供有信息价值的优质内容。用户可以在这里发现新的想法，分享通往美好生活道路上的真实经历，共同打造精致、时尚的兴趣种草社区。 加入我们，从业务上你能接触到包括用户增长，社交，内容，消费等核心业务场景，从技术上也能够接触到包括基础技术，服务架构等方向上的挑战；会让你具备保障业务持续高质量高效率安全的为用户服务的能力的同时，还能具备为不同的业务场景提供全面的技术解决方案的能力，享受专业且纯粹的团队带来的工作乐趣和个人成长。\n\n1、负责国际化社区业务相关产品迭代改进新产品功能的开发；\n2、参与APP性能、体验优化及质量监控评估体系建设；\n3、参与客户端基础组件及架构设计，推进研发效率；\n4、参与各类专项技术调研，解决APP关键体验、性能问题。","requirements":"1、2027届本科及以上学历在读，计算机、通信等相关专业优先；\n2、热爱计算机科学和互联网技术，对移动产品有浓厚兴趣；\n3、扎实的数据结构和算法基础，熟练掌握至少一门编程语言（包括但不限于：Java、Kotlin、Objective-C、Swift、C、C++、JS、Python），有Android/iOS开发经验者优先；\n4、关注用户体验，能够积极把技术转化到用户体验改进上，对新技术保持热情，具备良好的分析、解决问题的能力；\n5、能保证至少4个月及以上的实习，每周可出勤至少4天及以上。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7688661294886619445","sourceKey":"bytedance","company":"字节跳动","title":"PR实习生 - 中国公共关系","city":"北京","category":"媒介公关","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7688661294886619445/detail","duty":"团队介绍：负责公司面向社会公众的信息传递和沟通，传递公司产品业务信息，讲述平台产生的社会价值，树立公司形象，增进公众信任。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、基于业务策划内容，挖掘选题，参与文字稿件撰写；\n2、跨部门协作，配合业务需求推动项目进程，达成既定目标；\n3、支持部门其他相关策划工作。","requirements":"1、本科以上学历在读，新闻学、传播学、广告学相关专业优先；\n2、熟悉大模型工具使用，对科技数码行业了解；\n3、思维灵活、有创意，对新鲜事物和新闻热点有兴趣、敏感度高；\n4、拥有良好的学习能力、出色的沟通和协作能力，有责任心，自驱力强；\n5、每周至少出勤4天，可连续实习3个月。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7686805940857522437","sourceKey":"bytedance","company":"字节跳动","title":"价格策略运营实习生 - TikTok Shop","city":"广州","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7686805940857522437/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商。平台汇聚全球优质商家与创作者，通过短视频、直播等多场景连接消费者，让新奇好物畅销全球，让美好生活触手可得。目前团队分布在美国、英国、法国、印尼、墨西哥、中国等全球多个国家和地区，在这里你将有机会深入国际业务场景，面向全世界商家及用户，和跨区域团队协作，共同探索创新购物模式。期待和优秀的你一起创造更多可能！\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、商品定价策略：参与设计跨境电商业务中的价格体系建设和定价、补贴策略的优化；\n2、商品价格运营：参与商品定价流程的梳理与优化，保障相关运营流程的执行落地；\n3、数据分析：通过A/B实验测试追踪业务关键指标，发现数据背后的问题和机会点，助力实现业务目标；\n4、比价追踪：了解并追踪商品在产品平台上的整体定价策略，记录并帮助团队制定对应方案；\n5、支持跨部门沟通、项目管理、信息收集等工作。","requirements":"1、本科及以上学历在读，计算机、运筹、统计、经济、数学等相关专业优先；\n2、熟练使用各种数据分析工具，包括但不限于Excel、SQL、Python等；\n3、英语表达及书写流利，可作为工作语言，有国际化相关留学或经历者优先；\n4、有团队合作精神，对分配的工作有责任心，细心，执行力强，并愿意进入电商行业学习；\n5、每周至少实习4天，实习时间4个月以上。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7685295795688098101","sourceKey":"bytedance","company":"字节跳动","title":"达人&内容策略分析实习生 - TikTok Shop","city":"上海","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7685295795688098101/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商。平台汇聚全球优质商家与创作者，通过短视频、直播等多场景连接消费者，让新奇好物畅销全球，让美好生活触手可得。目前团队分布在美国、英国、法国、印尼、墨西哥、中国等全球多个国家和地区，在这里你将有机会深入国际业务场景，面向全世界商家及用户，和跨区域团队协作，共同探索创新购物模式。期待和优秀的你一起创造更多可能！\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、支持TikTok Shop美国地区达人及内容业务的策略分析工作，包括但不限于达人方向的各项业务策略支持和数据分析工作；\n2、达人业绩管理及数据追踪：美国电商业务的达人整体、达人营销、大促方向的日常目标管理和表现追踪、达成归因，并据此提出优化策略；\n3、策略深耕：监控达人业务当前各项策略手段的效果并结合数据分析结果给出对应的结论；\n4、业务影响：通过数据分析和策略迭代举措实现可量化的业务增长或成本优化。","requirements":"1、本科及以上学历在读；\n2、有跨境电商或内容电商分析经验者优先；\n3、对数字高度敏感，具备出色的数据分析能力与逻辑拆解能力，能够主动发现更细微的问题；\n4、具备优秀的沟通技巧、明确的目标感、从零到一的开拓型工作态度，以及积极的主观能动性；\n5、一周出勤4-5天，实习3个月及以上。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7685217066895247621","sourceKey":"bytedance","company":"字节跳动","title":"IP设计实习生 - 芯片研发","city":"北京","category":"硬件","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7685217066895247621/detail","duty":"团队介绍：字节芯片研发团队目前工作主要集中在芯片设计环节，主要围绕字节自身业务展开芯片探索，为字节多项业务的专用场景定制硬件优化，设计多款基于先进半导体工艺的云端复杂芯片，以期提升性能、降低成本。早期若干芯片项目已经进入到量产部署阶段，有多次一版成功的投片经历，所用工艺包含多个主流的先进工艺节点。与基础设施各团队之间工作的整体协同，能更容易和更好地发挥芯片研发的价值。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、负责AI芯片设计评估，包括矩阵/卷积计算结构探索、向量计算不同路线量化评估、浮点无损/有损压缩分析、Crossbar结构优化分析等。","requirements":"1、本科及以上学历在读，微电子、计算机等相关专业优先；\n2、对芯片前端设计有深入理解，有坚实的RTL设计基础；\n3、有主动学习、深入分析和解决问题的能力及自我驱动力。\n\n加分项\n1、熟悉Transformer架构与大模型核心算法，深刻理解算法算子特性与硬件算力映射关系，具备AI芯片计算架构设计、算力调度优化的算法基础。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7685209267955075333","sourceKey":"bytedance","company":"字节跳动","title":"经营分析师（国际化业务） - Global Business Solutions","city":"上海","category":"商业运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7685209267955075333/detail","duty":"团队介绍：Global Business Solutions (GBS) 负责TikTok为主的全球产品商业化相关工作，为全球品牌和广告商提供集成的数字营销解决方案。具体包括各区域销售、销售运营、渠道管理、商业化战略、To B市场营销、营销科学、商业化合作和商业内容安全等职能。\n\n1、负责全球业务解决方案（GBS）业务数据分析，制定战略规划，输出解决方案及落地执行方案，基于对特定业务领域的理解与分析，持续优化管控规则、产品工具及业务运营，为战略落地提供有力支撑；\n2、对跨境电商各项业务指标开展常态化监控与数据分析，输出对应解决方案，助力平台销售团队持续优化消费者体验；\n3、熟悉跨境电商业务规则，深度支持销售与客户解决方案团队负责人完成项目任务拆解、优先级排序，跟踪重点业务进展，能够通过定量与定性分析，衡量项目产出与效能。","requirements":"1、2027届获得本科及以上学历，数学、统计学、计算机等相关专业优先；\n2、具备扎实的数据分析能力；\n3、优秀的推理能力与逻辑思维，掌握良好的问题解决方法，可独立输出高质量战略方案，学习与适应能力强，具备战略框架思维，对业务拥有敏感度与洞察力，热衷于参与业务工作，能够适应快速迭代的工作环境；\n4、具备战略思考能力，能够快速理解业务，并挖掘业务与数据表现之间的关联；\n5、英语可作为工作语言（书面及口语均需），有国际化学习、交换或跨文化项目经验者优先，对跨文化沟通与跨国业务协作有热情者加分；\n6、熟练使用Tableau、Power BI等BI可视化工具者优先，掌握SQL加分。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7683832311291119877","sourceKey":"bytedance","company":"字节跳动","title":"世界模型算法实习生 - 抖音直播","city":"深圳","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7683832311291119877/detail","duty":"团队介绍：直播团队负责为抖音集团旗下产品提供直播服务。团队负责直播平台技术和直播业务研发，打造灵活稳定的直播服务平台，为用户提供优质直播体验，支持电商、本地生活、游戏、节目、多人互动等不同类型的业务场景。直播业务发展迅猛，处于行业头部地位，业务发展空间巨大。现在加入我们，和优秀的人一起做有挑战的事，你的技术与创意将影响亿级用户，激发创意和丰富生活。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、负责实时生成式世界模型构建，包括数据建设、模型架构优化、模型预训练及后训练、模型Scale Up、模型评估等工作；\n2、探索实时生成式世界模型记忆机制，解决世界模型长时序稳定性、时空一致性、可实时交互生成等痛点问题；\n3、推动实时生成式世界模型在抖音场景落地，为抖音用户提供全新交互体验；\n4、跟踪AI前沿技术进展，持续拓展世界模型能力边界。","requirements":"1、本科及以上学历在读，人工智能、计算机、软件工程等相关专业优先；\n2、具有优秀的编程基础，熟练使用Python编程语言和PyTorch深度学习框架；\n3、具有扎实的机器学习/深度学习基础，熟悉常用算法和神经网络模型结构；\n4、有世界模型、大语言模型、多模态大模型或3D大模型等相关训练经验和高质量论文者优先考虑；\n5、具有优秀的分析和解决问题的能力，对解决具有挑战性的问题充满激情，良好的沟通和团队合作能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7683739993118443829","sourceKey":"bytedance","company":"字节跳动","title":"AI全栈开发工程师 - 抖音用户产品","city":"北京/杭州/广州/深圳/上海","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7683739993118443829/detail","duty":"团队介绍：抖音用户产品研发团队为抖音全业务提供研发支持与底层技术能力，是驱动业务持续进化的重要工程力量之一。团队围绕首页、推荐、搜索、图文、中长视频、AI 创作、相机、账号及社交通讯等核心场景，承担从客户端、服务端到 AI 工程链路的端到端建设，在亿级 DAU 的真实流量下，持续攻坚极致体验与前沿 AI 系统的工程命题。\n我们相信，AI 正在重塑产品的底层架构。团队依托大模型与多模态技术、Multi-Agent 系统工程、在线推理与评测基础设施，面向下一代 AI 原生应用持续投入：在社交与通讯场景，探索长期记忆、多模态理解与人格化对话的技术边界，构建真正能陪伴用户的 AI 交互系统；在内容与创作场景，建设面向亿级创作者的多模态生成与可控创作引擎，让 AI 成为创作者的表达延伸；在搜索与信息获取场景，探索生成式检索、Agentic Search 与个性化推理的新一代系统架构，重新定义 \"人与信息\" 的连接方式。\n这里有工业界领先规模的真实流量，有最前沿的 AI 工程命题，也有一群把技术做到极致的同行者。诚邀热爱技术、追求极致、渴望在真实世界解决硬核问题的你加入我们，一起在 Agent 驱动的技术浪潮中，构建支撑大规模用户的新一代产品。\n\n1、负责抖音及抖音系相关产品的业务研发，参与核心功能从需求分析、方案设计到上线落地的全链路开发；\n2、以AI-Native方式跨越技术栈边界，借助AI能力完成从客户端到服务端、前端的全栈开发，不局限于单一技术领域；\n3、深度参与产品需求讨论与功能定义，与产品、设计、QA等团队紧密协作，设计良好的代码结构并持续迭代重构；\n4、探索和落地AI时代软件开发新范式，在团队内验证并优化AI驱动的开发工作流，推动研发效率与工程质量的提升。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程等相关专业优先；\n2、具备扎实的计算机基础，至少熟练掌握一门编程语言；良好的编程习惯和代码设计，追求良好的用户体验；\n3、对AI产品和技术有热情，认同AI开发范式，日常工作中已主动、深度使用AI工具，真正用AI提升效率；具备AI全栈思维，愿意借助AI能力抹平技术栈差异，能在AI辅助下独立完成跨栈开发任务；\n4、主动性强，具备良好的沟通协作能力，能主动理解业务目标、参与需求讨论与方案决策，与协作职能角色高效协同推进项目落地。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7683416797381101829","sourceKey":"bytedance","company":"字节跳动","title":"开放平台运营（游戏方向）实习生 - TikTok产品","city":"北京","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7683416797381101829/detail","duty":"团队介绍：TikTok是一个覆盖150个国家和地区的国际短视频平台，我们希望通过TikTok发现真实、有趣的瞬间，让生活更美好。TikTok在全球各地设有办公室，全球总部位于洛杉矶和新加坡，办公地点还包括纽约、伦敦、都柏林、巴黎、柏林、迪拜、雅加达、首尔和东京等多个城市。\n\nTikTok产品团队的目标是促进TikTok的发展并能持续成为业界领先的产品。团队包括但不限于产品架构、用户增长、搜索、社交、创作、PGC、音乐、开放平台、内容生态、平台安全、数据科学、商业分析等关键业务场景，支持产品在全球赛道上高速发展，保障业务持续高质量、高效率、且安全地为用户服务。同时覆盖国际化直播场景，为TikTok用户提供独特的内容和消费体验，以及国际化生活服务场景，链接海外线下商家、创作者与用户。\n\nTikTok的使命是通过提供一个创造性表达的产品，通过真实、快乐和积极的体验激发创造力和带来快乐。在TikTok，我们的员工谦逊、聪明、富有同情心和创造力。我们创造是为了激励--为了你，为了我们，也为了我们平台上的10亿用户。我们带着好奇心领导，追求最高目标。在这里，对于那些敢于追求超越可能性边界的大胆想法的人充满机会。加入我们，在TikTok的职业生涯中产生影响。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、支持小游戏投稿活动全流程：筹备排期、规则与素材整理、活动宣传、上线跟进、数据回收等；\n2、建联优质达人，跟进投稿与活动参与，依据数据和内容表现提供选题、内容优化及账号运营建议，沉淀案例；\n3、跟踪美国、欧洲、东南亚游戏内容趋势与平台热点，完成案例采集、基础分析及阶段性白皮书。","requirements":"1、本科及以上学历在读，数据分析、市场营销、广告、新媒体、计算机等相关专业优先；\n2、英语可作为工作语言（读写流利，口语沟通顺畅）；\n3、具备数据驱动思维，可基于内容数据、用户行为拆解问题，制定精细化运营方案；\n4、具备良好沟通、文字表达和基础数据分析能力，执行细致；有内容或账号运营、达人合作、行业研究经历者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7678911812435544373","sourceKey":"bytedance","company":"字节跳动","title":"LLM Infra工程师 - Data-抖音/直播/电商/剪映","city":"北京/上海/杭州/深圳","category":"机器学习","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7678911812435544373/detail","duty":"团队介绍：Data-架构团队是字节跳动的核心技术引擎，为抖音、今日头条、番茄小说、剪映等旗舰产品构建大规模、高可用、可持续演进的推荐、搜索与广告工程架构。团队深耕推荐架构、搜索架构、广告架构、机器学习基础设施、在线服务架构与稳定性工程等领域，在千亿乃至万亿级数据规模、超大流量与复杂业务逻辑的真实工程挑战中，持续以技术创新驱动人与信息、人与服务的高效连接，服务全球数亿用户。\n目前，团队正积极探索搜广推架构下一代范式：从大规模在线预估框架到生成式推荐大模型的训练、后训练与端到端推理，从分布式异步图引擎、统一数据编排到平台化业务策略与 Infra Research，让大模型真正落地于亿级流量的真实在线系统。欢迎热爱分布式、AI 大模型、搜广推架构的同学加入。\n\n1、完成LLM训练/推理技术在搜广推大模型场景的研发、落地和调优，解决推荐场景的大模型工程问题；\n2、针对PyTorch、TensorFlow等框架提供高自动化、极致性能的模型优化方案；\n3、推动基于大模型开源组件构建，设计和实现新一代推荐系统架构，支持推荐大模型在业务落地；\n4、与算法团队Co-Design，推动端到端生成式推荐技术创新的预研和落地。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程等相关专业优先；\n2、扎实的编程和算法基础，熟练掌握C/C++、Python、Java等编程语言，有CUDA开发经验，熟悉TensorRT/Triton/Cutlass经验者优先；\n3、熟悉大模型推理加速的研究和技术进展，包括但不限于模型量化、图编译、算子调优、KVCache、PD分离等；\n4、掌握LLM训练/推理技术，有实际开发和应用落地经验，例如Megatron、Deepspeed、VLLM、SGLang、TRT-LLM等；\n5、对大模型工程有丰富的经验和广阔视野，紧追开源动态，具备独立的Trouble-shooting能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7677588589015615749","sourceKey":"bytedance","company":"字节跳动","title":"AI产品经理 - 抖音电商","city":"上海/北京","category":"产品","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7677588589015615749/detail","duty":"团队介绍：抖音电商以“总能发现好东西”为主张，致力于成为用户发现丰富好物的首选平台。众多抖音创作者通过短视频、直播、商城等丰富的形式，给用户提供更个性化、更生动、更高效的消费体验。同时，抖音电商积极引入优质合作伙伴，为商家变现提供多元的选择。\n\n1、负责抖音电商治理运营平台产品相关工作，通过AI能力优化原有的流程，包括但不限于奖惩中心、智能归因平台、风险模型评测平台等；\n2、探索AI-Native的产品，通过建设治理管家，期望能够逐步建设AI独立接管治理策略的治理中心；\n3、通过用户调研、产品数据分析、行业调研、业务专题讨论等多种手段，抽象产品能力，驱动电商治理问题得到解决，提升运营工作效率；\n4、推进内部交流，协同业务团队、算法、研发团队，保证团队合作的顺畅，及跨横向团队间的协作等。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程、数据、人工智能等相关专业优先；\n2、拥有AI产品/B端/平台产品工作经验，具备出色的学习能力和逻辑思维，跨团队协同能力强，能够深入业务，理解业务，有自驱力目标导向；\n3、熟悉产品全生命周期管理，能够高效的与技术、算法团队沟通，并转化成可行的产品方案。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7675260955961968901","sourceKey":"bytedance","company":"字节跳动","title":"垂类策略运营经理（抖音AI产品人才校招） - 抖音运营","city":"北京/上海","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7675260955961968901/detail","duty":"团队介绍：负责抖音知识，兴趣，消费，生活，娱乐等垂类的创作者运营，主要目标为提升抖音内容供给，探索多元化的作者变现和商业模式，促进多领域的创作者更好地在平台经营和成长。同时也包括抖音中长视频、演出相关业务。\n\n这是抖音面向具备AI能力的同学发起的校招项目，覆盖产品、策略运营方向。\nAI 正在重新定义产品，也在重新定义\"做产品\"这件事 —— AI Native 的产品，需要你既能理解大模型技术边界，又能定义产品价值。\n如果你也有着许多的奇思妙想， 欢迎加入抖音，把想法落地成亿万用户真实可感的产品体验，来抖音，和我们一起探索 AI 产品的下一种可能！\n\n1、参与抖音垂类运营目标的设计、追踪与拆解分析，定期输出业务经营分析，定位业务问题并提出优化策略；\n2、定期开展垂类生态分析、产品策略调研，为业务决策提供数据支撑；\n3、参与内容分类标签、内容质量标签的建设与迭代，参与优质内容标准的制定与优化，提升优质创作者规模与活跃度。","requirements":"1、2027届获得本科及以上学历，统计学、数学、计算机、金融工程等相关专业优先；\n2、熟练掌握SQL，能够独立完成数据提取、清洗与分析工作，熟悉Python加分；\n3、有内容运营、产品运营、数据分析相关实习经验者优先；\n4、具备良好的逻辑思维能力、沟通协作能力和问题解决能力；对内容平台、创作者生态有浓厚兴趣，了解抖音等短视频平台的生态特点。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7674895197978953989","sourceKey":"bytedance","company":"字节跳动","title":"算法工程（音乐智能理解方向）实习生 - AI Music","city":"上海","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7674895197978953989/detail","duty":"团队介绍：我们是TikTok研发旗下的音乐算法团队，主要任务是打造优质高效的AI音乐算法和服务。团队的业务与技术产出丰硕：建设了行业领先的音乐识别系统，率先实现了翻唱识别能力在实际业务中的落地；自研音乐理解大模型首创全局与时序理解能力的统一，业务应用广泛；文生音乐模型效果已达行业第一梯队。学术上，团队在AAAI、ICASSP等顶会发表论文20余篇，其中ByteCover和HTS-AT等已成领域经典算法。团队诚邀优秀算法人才加入，共享千卡算力与数亿级用户的全球落地场景。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、深入参与音乐音频理解与生成式AI的前沿技术研发；你将运用深度学习与音频信号处理技术，探索音乐结构分析、多模态表达及AI音乐等核心领域，推动下一代智能音乐体验落地；\n2、音乐与音频理解：参与音乐特征提取、曲风与情绪识别、自动打标、歌词-音频精准对齐（Forced Alignment）及结构分割（如主副歌识别）等算法研发；\n3、AI音乐：协助探索AI编曲/旋律生成、歌声合成，参与音频大模型（Audio-LLM）及扩散模型的验证与实验以及工程化落地；\n4、数据与基准建设：负责音频数据的清洗、特征预处理、合成数据生成及评价指标的搭建。","requirements":"1、硕士及以上学位在读，计算机、信号处理、声学、人工智能或数学相关专业；\n2、核心技能：熟练掌握Python及PyTorch，熟悉主流深度学习架构（Transformer、Diffusion等）；\n3、实习时间：每周可实习4天以上，能连续实习5个月及以上。\n\n加分项：\n1、了解LLM、CLAP、Encodec、DiffSinger等音频/音乐生成与理解模型；\n2、在ISMIR、ICASSP、Interspeech、NIPS等顶级会议发表过论文，或在相关音频/信号处理竞赛中获奖；\n3、热爱音乐，具备乐理基础、编曲能力或乐器演奏经验者加分。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7670901015386360117","sourceKey":"bytedance","company":"字节跳动","title":"后端开发工程师（社交） - TikTok研发","city":"上海","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7670901015386360117/detail","duty":"团队介绍：TikTok研发团队，旨在实现TikTok业务的研发工作，搭建及维护业界领先的产品。加入我们，你能接触到包括用户增长、社交、直播、电商C端、内容创造、内容消费等核心业务场景，支持产品在全球赛道上高速发展；也能接触到包括服务架构、基础技术等方向上的技术挑战，保障业务持续高质量、高效率、且安全地为用户服务；同时还能为不同业务场景提供全面的技术解决方案，优化各项产品指标及用户体验。 \n在这里， 有大牛带队与大家一同不断探索前沿， 突破想象空间。 在这里，你的每一行代码都将服务亿万用户。在这里，团队专业且纯粹，合作氛围平等且轻松。目前在北京，上海，杭州、广州、深圳分别开放多个岗位机会。\n\n1、深度参与评论、点赞、通知等模块的服务端研发，并探索AI+社交的创新玩法落地；\n2、在真实业务场景中，利用行业前沿大模型编码助手辅助方案设计、代码实现与高质量重构，共同打磨极致的用户体验；\n3、参与产品需求分析，设计系统技术方案，关键代码开发和系统调优；参与各专项技术调研，改进系统性能与稳定性；\n4、借助AI完成日常研发，并持续探索AI研发范式。","requirements":"1、2027届获得本科及以上学历，计算机、软件、电子信息等相关专业；\n2、热爱计算机科学和互联网技术，精通至少一门编程语言，包括但不仅限于：Java、C、C++、PHP、Python、Go；\n3、掌握扎实的计算机基础知识，深入理解数据结构、算法和操作系统知识；\n4、有AI Coding工具使用经验，对AI Agent/Skill/Context Engineering/Harness Engineering有理解的优先；\n5、有优秀的逻辑分析能力，能够对业务逻辑进行合理的抽象和拆分；\n6、有强烈的求知欲，优秀的学习和沟通能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7670547978557819189","sourceKey":"bytedance","company":"字节跳动","title":"数据科学 - TikTok直播","city":"北京/上海","category":"数据分析","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7670547978557819189/detail","duty":"团队介绍：TikTok是一个覆盖150个国家和地区的国际短视频平台，我们希望通过TikTok发现真实、有趣的瞬间，让生活更美好。TikTok在全球各地设有办公室，全球总部位于洛杉矶和新加坡，办公地点还包括纽约、伦敦、都柏林、巴黎、柏林、迪拜、雅加达、首尔和东京等多个城市。\n\nTikTok直播是全球领先的直播业务，以实时互动为核心，提供多元化的商业化模式和创作工具。我们为用户提供独特的内容和消费体验；为创作者找到合适的观众，提供最好的工具和一系列盈利模式，帮助创作者创造更多机会、改变他们的生活；通过直播，平台也能从中获得健康、客观的商业化收益，持续发展。我们一直听到这样的故事 —— “LIVE changes my life” —— 他们更好，我们才会更好。\n\n加入我们，一起探索 “不可能的事”—— 我们是行业的先行者，在一步步改变行业。我们持续让行业了解直播是一种新的内容形式，是创作者可以依赖的商业模式。\n\n1、负责TikTok直播相关的数据分析工作，方向包括观看体验优化、主播生态、公会经营、推荐效果等；\n2、负责业务方向的指标体系设计，搭建对应的监控体系并完成异动分析工作；\n3、利用统计科学方法，开展科学有效的效果评估工作，覆盖A/B实验、因果推断等场景；\n4、深入理解业务目标，通过数据挖掘输出分析洞察，识别潜在优化方向，为业务决策提供数据支撑，协同产品、推荐工程师、研发团队共同推进优化落地；\n5、探索归纳分析方法论，研究数据科学理论，推进数据产品的迭代优化，提升分析效率。","requirements":"1、2027届获得本科及以上学历，统计学、数据科学、经济学等相关专业优先；\n2、有一定的数据分析工作经验；有直播相关行业经验者优先；\n3、熟练掌握SQL，Python/R，可视化等常用工具；了解机器学习、推荐算法原理者优先；\n4、优秀的思维逻辑，善于分析问题和解决问题，良好的沟通协作能力，对于挑战充满热情。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7670180490167109941","sourceKey":"bytedance","company":"字节跳动","title":"供应链商务管理专员 - AI算力基础设施","city":"北京","category":"职能 / 支持","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7670180490167109941/detail","duty":"团队介绍：字节跳动基础设施部门，负责字节跳动的全栈算力基础设施，从芯片服务器产研、到超大规模数据中心，到传统云平台和如今的AI Native Cloud，全方位为抖音、豆包、今日头条、飞书、火山引擎等各类产品提供领先、稳定的百万量级大规模算力基础设施服务。我们的领域涵盖数据中心建设、内核操作系统开发、服务器集群管理、高速网络通信、EB级数据存储体系、搜索型数据库探索、基于LLM的AI基础设施的研发调度与治理等，致力于打造业界领先的、面向LLM的AI云原生基础设施架构与产品矩阵。\n\n1、参与供应链关键商务协同：支持相关商务会议的组织与协调，协助推进重要合作沟通，有机会参与战略供应商关系维护，协助推进关键合作事项；\n2、跟进关键商务会议决议落地：协助推动关键商务会议决议落地，跟踪重点事项进展，关注里程碑、交付节奏与风险问题；\n3、日常跨团队协助支持：组织供应链相关例会、专题会议，做好会议纪要整理、行动项拆解与后续跟进，推动跨团队协作事项闭环；\n4、支持跨部门沟通与协同：协助供应链与相关业务、职能团队之间的沟通协调，支持资料整理、信息汇总等日常工作，提升团队协同效率；\n5、复合型培养规划：在培养过程中，逐步建立对供应链管理、商务协同、项目管理及业务运营的系统认知，为后续进入具体业务方向发展打下基础。","requirements":"1、2027届获得本科及以上学历，专业不限；\n2、熟练使用Office、AI等办公工具，具备良好的信息整理、材料输出和项目管理能力；\n3、具备优秀的沟通协调能力、计划组织能力与逻辑思维能力，有较强责任心、执行力和团队合作精神，能在多任务环境下高效推进工作；\n4、英文读写能力优秀，英文可作为工作语言；\n5、对供应链、采购、基础设施等领域有一定了解或实践经历者优先；\n6、有学生组织、项目管理、商务沟通等实习经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669684051644565765","sourceKey":"bytedance","company":"字节跳动","title":"后端开发工程师 - 中国交易与广告","city":"北京","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669684051644565765/detail","duty":"团队介绍：中国交易与广告，基于个性化推荐、深度学习和大模型技术，依托抖音、今日头条、红果短剧、西瓜视频、番茄小说等多元产品，构建抖音电商、生活服务、广告营销等核心营收业务的算法策略和工程架构。部门运用领先的算法能力，精准连接海量用户与商家，通过推荐、广告和搜索算法精准匹配需求并促进交易达成，保障用户体验与商家权益，实现营收业务可持续增长；基于深厚的技术积累，构建高效、智能、可靠的交易与广告产品，全面提升多行业收入变现与市场占有。在这里，你将直面超大规模流量与复杂业务场景的技术挑战，深度应用业界领先的商业模型与算法技术，投身面向未来的数字营销能力建设，持续探索前沿技术。\n\n1、大规模容灾与常态化兜底；参与交易广告全链路的常态化与应急容灾建设，保障系统营收；\n2、应急大模型与智能排障；参与用大模型和Agent重构线上应急响应、客户问题排查与自动归因止损，把资深工程师的排障经验沉淀成智能系统；\n3、算法质量；参与交易广告的特征、样本与模型质量保障和测试体系建设，从源头拦住模型质量问题，而不是等它到线上才发现；\n4、持续交付与灰度泳道；参与灰度、实验与发布建设，将不可灰度系统实现灰度，在每一次变更之前，拦住线上故障；\n5、架构与平台建设；参与核心系统的稳定性架构设计开发，以及持续交付、应急容灾、大模型等平台的搭建，为大规模算法工程系统的整体稳定性负责。","requirements":"1、2027届获得本科及以上学历，计算机等相关专业优先；\n2、计算机基础扎实，深入理解数据结构、算法、操作系统与计算机网络；\n3、精通至少一门编程语言，C++/Go优先，Java、Python等亦可；\n4、有良好的工程能力与代码素养，能写出清晰、可维护、可靠的代码；\n5、逻辑分析能力强，能对复杂业务和系统做合理的抽象与拆分；\n6、求知欲和学习能力强，沟通协作好，面对未知问题愿意主动钻研、有负责人意识。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668582797787203893","sourceKey":"bytedance","company":"字节跳动","title":"全栈开发/测试开发工程师 - TikTok内容安全平台","city":"北京","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668582797787203893/detail","duty":"团队介绍：国际化内容安全平台团队致力于为字节跳动国际化产品的用户维护安全可信赖环境，通过开发、迭代机器学习模型和信息系统以更早、更快发掘风险、监控风险、响应紧急事件，以人工智能技术支持业务发展，力求更高效、更敏捷、更全能地维护站内生态安全。\n\n1、我们希望寻找具备扎实工程基础、全栈潜力和AI原生能力的应届毕业生，加入TikTok各业务质量工程团队，区别于传统意义上的“测试执行”岗位，这是一个以质量场景为切入点，面向复杂系统和智能工程建设的研发岗位；\n2、参与业务质量平台、研发效能工具和自动化基础设施的设计与开发，覆盖前端、后端、数据链路和平台能力建设；\n3、深入客户端、服务端及上下游协同链路，建设功能、接口、稳定性、性能、安全等多维质量保障能力；通过代码分析、链路分析、日志分析、压测、故障演练等方式发现复杂系统中的深层问题，并推动问题闭环；\n4、探索并落地AI在质量工程中的应用，包括测试生成、智能缺陷分析、质量评测、测试智能体、自主探索式测试等方向；\n5、沉淀可复用的工程能力，包括测试框架、诊断工具、自动化脚本、质量方法论与平台化能力；与研发、产品、算法、数据等团队协作，共同推动质量内建、研发提效和工程规范升级。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程、人工智能、自动化、数学等相关专业优先；\n2、具备扎实的计算机基础，理解数据结构与算法的核心思想，能够将抽象问题转化为可实现、可优化的工程方案；熟悉至少一门编程语言，如Go、Java、Python、TypeScript/C++等，具备独立完成中型工程项目或核心模块开发的能力；\n3、理解操作系统、计算机网络、数据库、并发编程、常见系统架构等基础知识；对软件工程有基本理解，熟悉从需求分析、设计实现到测试验证、上线迭代的研发流程；\n4、具备良好的问题拆解能力、系统性思维和学习能力，能够面对复杂问题持续追问本质并推动解决；具备良好的沟通协作能力和责任心，能够在跨团队、多角色合作中推动目标达成；\n5、能熟练使用AI工具辅助编码、排障、文档理解和方案设计，具备对AI输出进行判断、校验和二次加工的能力；对AI在测试与质量场景中的应用有兴趣，对大语言模型、Agent、RAG、模型评测、自动化工作流等AI工程方向有认知或实践经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668170229178812677","sourceKey":"bytedance","company":"字节跳动","title":"算法工程师 - 抖音","city":"上海/北京/深圳/杭州","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668170229178812677/detail","duty":"团队介绍：Data-抖音团队，负责抖音APP的推荐算法、AI大模型应用、内容算法、增长算法、广告自动化投放、智能对话等算法工作，对接全链路各体裁（短视频，图文）各业务（内容消费，互动，UGC，双列，社交，生态，垂类，创作，消息，汽水音乐，精选，随变，增长投放，评论，内容理解&安全、智能对话等）。我们的工作涉及大规模推荐算法的优化、多业务复杂约束下的优化问题、多模态内容理解、LLM基础技术研究、业务Agent化和创新AI落地应用、CV/NLP等多个学术领域的算法改进工作、对多种场景的推荐架构的设计和实现和对产品数据的复杂深入的分析工作。在这里，你可以深入钻研机器学习算法的改进和优化，探索工业界最领先的推荐系统架构和推荐大模型算法、可以通过使用最新的大模型技术支持抖音的AI分身、业务智能化、智能客服等创新探索；可以通过对产品的深度理解和思考，将算法应用到业务中去；也可以通过对产品和内容生态的深度分析，影响产品未来的发展方向。\n\n1、建设推荐的Agentic RECSYS，包括用户理解、长期/短期Memory、任务规划、策略编排、反馈评估与自我迭代机制；推动LLM based RECSYS在推荐链路中的落地，优化推荐链路多环节决策，结合数据反馈的强化学习进一步提升用户体验；构建推荐Auto Research能力，利用LLM/Agent自动探索模型迭代、策略优化和实验方向，提升算法迭代效率；\n2、负责基础推荐、消息推送等场景的基础推荐算法的持续演进，探索系统和模型Scaling law，搜索、推荐等多场景数据的一体化建模，提升模型在全域场景下的理解与推理能力、推送场景的复杂约束下多目标优化空间；\n3、研发端到端的生成式推荐模型，并深入联合LLM，构建高效的下一代推荐范式；解决现有推荐算法的泛化局限性、用户长尾复杂意图理解和满足、System Bias、系统的推理算力分配等一系列关键问题；也探索基于新的多模态大模型与用户对齐的理解，支持交互性的分发调节与个性化等能力和产品形态上的突破。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程等相关专业优先；\n2、具备优秀的编码能力，扎实的数据结构和算法功底；\n3、对推荐算法和机器学习有热情、乐于学习、思考和创新；\n4、优秀的分析问题和解决问题的能力，有良好的沟通表达能力和团队精神；\n5、熟悉机器学习、自然语言处理、数据挖掘中一项或多项，对推荐系统、计算广告、搜索引擎、CV、NLP、语音相关领域有经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667869542593612085","sourceKey":"bytedance","company":"字节跳动","title":"短剧Agent开发工程师 - 抖音平台产品","city":"深圳/北京","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667869542593612085/detail","duty":"团队介绍：\n平台产品基础：作为抖音平台支撑团队，以 AI为核心抓手，打造高效能平台底座，为全业务线筑牢坚实底层支撑\n生态与运营：聚焦创作者成长与商业化，激活生态活力，夯实内容根基\n营销搭建：全链路营销体系，助力业务推广，实现品效增长\n文娱业务：深耕短剧赛道，打通内容 - 营收 - 宣发全链路，构建健康文娱生态\n变现与资金平台：筑牢交易结算核心底盘，提供全链路支付与清结算能力，保障平台资金安全与高效流转\n治理・体验・客服：三位一体守护平台安全、用户体验 以及 高效响应解决用户诉求\n开放业务：有序开放平台能力与数据，链接外部资源，拓展生态边界\n全体团队以业务增长与用户价值为核心，持续深耕、协同共进，推动抖音生态持续繁荣。\n\n1、负责短剧AI内容方向核心系统研发，聚焦AI剪辑、互动能力、AI小助手等重点业务，支持相关产品能力的快速建设与持续迭代；\n2、参与内容生产链路智能化升级，围绕内容理解、素材组织、自动剪辑、内容生成等场景，完成服务端系统设计与开发；\n3、与产品、算法、前端、运营等跨职能团队密切配合，面向真实业务场景快速交付高质量系统能力；\n4、持续关注AI与内容行业前沿技术，结合业务发展需要，推动新能力在业务中的落地和演进。","requirements":"1、2027届获得本科及以上学历，计算机、通信和电子信息科学、数学等相关专业；\n2、具备良好的编码能力和工程素养，熟悉常见的数据结构、算法及系统设计方法；\n3、有服务端、前端、客户端等开发经验，有全栈的研发经验优先；\n4、具备较好的业务理解、问题抽象和系统设计能力，能够独立负责模块设计与落地；有责任心、自驱力和良好的沟通协同能力，能够在复杂业务场景中持续推进项目；\n5、对AI方向有兴趣，有智能体、内容理解等相关研发经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667542125177948469","sourceKey":"bytedance","company":"字节跳动","title":"行业运营管培生（全托管） - TikTok Shop","city":"深圳/广州/上海","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667542125177948469/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商。平台汇聚全球优质商家与创作者，通过短视频、直播等多场景连接消费者，让新奇好物畅销全球，让美好生活触手可得。目前团队分布在美国、英国、法国、印尼、墨西哥、中国等全球多个国家和地区，在这里你将有机会深入国际业务场景，面向全世界商家及用户，和跨区域团队协作，共同探索创新购物模式。期待和优秀的你一起创造更多可能！\n\n项目介绍：起航计划是国际电商跨境业务板块专为2027届校招生打造的运营管培项目，旨在寻找优秀的有潜力应届毕业生，结合系统的培训与实践，助力他们在国际电商运营领域扬帆起航，迅速提升专业技能，成长为跨境业务未来领军人物。与字节跳动一起，实现“好货卖全球”。 \n\n项目亮点： \n1、全球化视野：有机会深入全球场景，面向全球商家及用户，创新互动式趣味购物模式； \n2、大咖导师带教：行业大牛专属辅导，全程助你提升业务能力与素养； \n3、快速成长通道：定制化职业发展指导，给你更快速的成长； \n4、灵活轮岗机会：安排轮岗实践，深入不同业务板块，让你全方位了解国际电商价值链。\n\n1、负责市场调研与商家经营分析，输出信息反馈与建议，参与品类规划制定并推进执行；\n2、负责梳理商家经营问题与需求，提出改进方案，协同相关方推进问题解决；\n3、参与团队重点专项及子项目推进，例如定向招商、内容场运营、商家标签体系建设等。","requirements":"1、2027届获得本科及以上学历，理科、商科、传播类相关专业优先；\n2、英语口语流利交流，有国际化留学经验优先，有相关英语成绩单或证书可随简历一并上传（如雅思、托福等）；\n3、有较强的数据分析能力、问题解决能力和沟通协作能力；\n4、积极主动，责任心强。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667518399503321349","sourceKey":"bytedance","company":"字节跳动","title":"推荐大模型算法工程师 - 番茄","city":"上海/深圳/杭州/北京","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667518399503321349/detail","duty":"团队介绍：Data-番茄团队，负责字节跳动下番茄小说、红果短剧、番茄畅听、国际化短剧等产品的推荐算法和AI相关工作。我们的工作包括优化业界前沿的大规模推荐系统，探索LLM与推荐的结合，并落地生成式推荐范式，从小说、短剧、音频、音乐等内容方向建设完整的内容生态和AI能力，保持业务规模保持超高速增长。\n\n1、推荐大模型在LLM的启发下，在近一年有了长足的发展；番茄依托字节跳动的先进中台，在推荐大模型（LRM）、生成式推荐（GR）领域已有多代方案落地；随着LLM和硬件算力的进一步发展，该方向空间仍有巨大空间；团队将继续紧跟前沿，在LRM、GR和LLM4Rec三大方向全面发力，推动推荐系统的持续进化；\n2、LRM；设计并探索Scale上限更高，ROI更好的结构，紧跟LLM超长上下文前沿，推动推荐场景的高效长序列压缩与建模，研究粗精一体LRM进一步释放Scale空间等；\n3、生成式推荐；探索番茄多场景多体裁的最佳tokenize方案，研究推荐场景下Reward Model与生成推荐模型的RL后训练，完成生成式模型对部分场景传统推荐模型的替换；\n4、LLM4Rec；包括研究如何将LLM的推理能力融入到推荐排序模型，以及完全基于LLM的交互推荐研究。","requirements":"1、2027届获得本科及以上学历，人工智能、计算机、数学相关专业者优先；\n2、对推荐大模型技术有浓厚兴趣，紧跟行业前沿发展；\n3、具有扎实的机器学习基础和编码能力，熟练掌握主要的算法和数据结构；\n4、在搜索广告推荐大模型领域，有实习或者实践过关键项目的优先；\n5、在国际顶级会议发表论文者优先，包括但不限于KDD、SIGIR、RecSys、ACL、NeurIPS等；有推荐大模型相关论文者优先；\n6、具备良好的沟通协作能力，能够与团队共同探索新技术，推动新技术在业务落地。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667395350599125253","sourceKey":"bytedance","company":"字节跳动","title":"人力运营 - 人力与管理部","city":"北京/上海/成都","category":"人力","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667395350599125253/detail","duty":"团队介绍：人力与管理部作为公司的职能部门之一，助力字节跳动从一家创业公司发展成为拥有超过十万名员工的全球化公司。人力与管理部以“释放人才成长力，激发组织生命力”为使命，在组织、人才、文化等方面持续像打造产品一样打造公司，推动业务成长。\n\n1、前往HROP团队多个领域学习实践，包括薪酬运营、福利运营、人力运营交付等，深入了解各业务模块的具体工作内容，掌握其背后的业务逻辑和管理思路，进一步提升个人专业能力；\n2、在轮岗及项目实践过程中，积极探索AI在人力运营场景中的应用，利用生成式AI等智能工具提升运营效率、优化流程体验，并参与推动AI赋能HR运营的实践；\n3、参与全球项目，在跨文化交流中拓展全球视野。","requirements":"1、2027届获得本科及以上学历，专业不限，人力资源、管理学专业优先；\n2、清晰的职业规划和职业发展目标，对于从事HR相关工作有饱满的热情；\n3、具备良好的团队合作能力，逻辑清晰，积极自驱，做事踏实务实，具备坚韧的职业素养，具备主动提出改进建议并推动优化的能力；\n4、英语能作为工作语言；\n5、具备AI工具应用能力，能够运用生成式AI等智能工具辅助信息检索、数据分析、文档撰写及流程优化，对AI在人力运营场景中的应用保持学习热情和探索意识。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7665707950078675253","sourceKey":"bytedance","company":"字节跳动","title":"后端开发工程师 - 抖音直播","city":"北京","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7665707950078675253/detail","duty":"团队介绍：直播团队负责为抖音集团旗下产品提供直播服务。团队负责直播平台技术和直播业务研发，打造灵活稳定的直播服务平台，为用户提供优质直播体验，支持电商、本地生活、游戏、节目、多人互动等不同类型的业务场景。直播业务发展迅猛，处于行业头部地位，业务发展空间巨大。现在加入我们，和优秀的人一起做有挑战的事，你的技术与创意将影响亿级用户，激发创意和丰富生活。\n\n1、探索AI Native研发和业务提效，优化Agent能力，构建AI友好流程，解决如下方向问题：需求流程Agent、策略诊断Agent、知识库构建和各类Agent流程自动化，以及评测等事项；\n2、参与抖音直播任务平台、公会任务、主播供给相关后端系统研发，支持任务创建、任务下发、进度计算、奖励结算、反作弊扣除、数据展示和对账链路，建设高并发、高可靠、高安全的任务系统，保障任务状态流转、奖励发放、资金安全和数据一致性；\n3、深入理解公会任务和主播供给业务，能从业务目标出发拆解技术方案，而不只是被动实现需求，参与任务配置化、任务引擎、策略平台、数据分析和效果归因等方向建设，提升业务迭代效率；\n4、与产品、运营、数据、算法、风控等角色协作，持续提升任务激励效果、平台效率和业务结果。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程、人工智能、数据科学等相关专业优先；\n2、计算机基础扎实，熟悉数据结构、算法、操作系统、网络、数据库等基础知识；\n3、熟练掌握Go/Python/Java/C++中至少一门语言，具备良好的编码能力和工程习惯；\n4、理解数据库、缓存、消息队列、RPC、分布式系统等后端基础组件，能关注系统可靠性、可观测性和数据一致性；\n5、对业务有兴趣，愿意理解直播、公会、主播、任务激励、结算、反作弊、增长策略等复杂业务问题；对AI有真实使用和实践经验，理解大模型、Prompt、RAG、Agent、AI Coding等基础概念，并能把AI工具用于学习、编码、分析或项目开发；\n6、好奇心强，学习速度快，遇到不确定问题能主动调研、验证和复盘；责任心强，沟通协作顺畅，能在复杂业务和复杂系统之间建立清晰判断。\n\n加分项\n1、有AI应用、Agent、RAG、数据分析工具、自动化测试、代码生成工具链等项目经验；\n2、有后端平台、任务系统、增长系统、风控系统、结算系统或数据平台相关经验；\n3、有开源项目、技术博客、个人工具、AI Demo、比赛项目等可展示作品；\n4、能清楚说明自己如何用AI提升学习、研发、调试、业务分析或交付效率。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7660773953178978613","sourceKey":"bytedance","company":"字节跳动","title":"数据科学实习生-抖音电商","city":"上海","category":"产品","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7660773953178978613/detail","duty":"日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n团队介绍：抖音电商以“总能发现好东西”为主张，致力于成为用户发现丰富好物的首选平台。众多抖音创作者通过短视频、直播、商城等丰富的形式，给用户提供更个性化、更生动、更高效的消费体验。同时，抖音电商积极引入优质合作伙伴，为商家变现提供多元的选择。\n\n1、业务数据分析与洞察：参与业务问题拆解，理解业务目标、指标和分析口径；使用SQL/Python完成数据提取、清洗、统计分析和可视化；输出结构化分析结论，支持产品、运营或业务决策；\n2、数据建模与实验评估：协助完成用户行为分析、特征构建、模型训练和效果评估；参与A/B实验、策略评估、预测建模等数据科学相关工作；对模型或实验结果进行解释，分析效果波动原因和优化方向；\n3、AI工具与大模型应用探索：探索大模型、Agent、RAG、自动化数据分析等技术在DS工作流中的应用；将AI工具用于SQL/Python辅助、数据理解、分析报告生成等场景；搭建轻量Demo或自动化脚本，验证AI对分析效率和质量的提升。","requirements":"1、本科及以上学历在读，统计、数学、计算机、AI等相关专业优先；\n2、熟练SQL+Python，具备数据分析与建模基础；\n3、理解常见统计方法、机器学习基础和实验评估；\n4、对AI/大模型有强兴趣，有实际探索项目经验。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7628839760593455413","sourceKey":"bytedance","company":"字节跳动","title":"飞书办公场景的企业级AI Agent智能体平台构建（Agent训练） - Seed 产品研发","city":"北京","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7628839760593455413/detail","duty":"团队介绍：产品研发和工程架构-Seed 团队深耕大模型技术在场景中的创新应用，负责多款AI产品的工程研发 —— 包括豆包、飞书、豆包工作、豆包爱学、Gauth、猫箱等创新产品，覆盖消费级与企业级多个场景。我们致力于将大模型能力从 \"生成内容\" 推进到 \"完成工作\"，让 AI 服务用户日常与企业协作。你将面对多模态交互、工具调用可靠性、企业级数据安全等真实工程挑战，与团队一起推动 AI 生产力落地。\n\n课题介绍：\n随着大模型能力趋于成熟，飞书正处于将AI能力从单点功能升级为端到端“企业智能体平台”的关键窗口期。本课题聚焦于办公生产力场景，以Memory与Context体系为底座，以知识问答、会议数字分身为典型Long-Horizon任务场景，以自动化评测为质量度量引擎，以通用智能体框架为演进方向，系统性地探索企业级AI Agent的落地路径。目标是打造一套可扩展、可度量、可持续进化的办公智能体基础设施，让AI真正成为企业员工的协作伙伴与数字分身。\n\n课题挑战：\n1、Memory质量与演化：企业多源异构数据理解难度大，Memory的生产、消费与持续进化链路尚不成熟；现有学术Benchmark与真实办公场景存在较大差距，难以有效指导工程实践；\n2、全模态流式内容理解：会议场景要求对音视频、文档、参会人上下文进行实时全模态理解，Streaming Omni能力的稳定性与泛化性是核心技术瓶颈；\n3、评测体系的区分度与规模化：如何从海量线上Query中动态筛选出具有能力区分度的测试样本，并通过自动化手段生成覆盖全面、可校验的评分标准（Rubrics），以支撑天级别迭代，是工程与算法的双重挑战；\n4、通用Agent框架的动态适配：Agent框架与多业务场景的动态适配、跨场景排序因子融合、奖励工程的训练数据稀缺，以及Memory的结构化与跨任务迁移，均是企业级智能体规模化落地的关键障碍。\n\n课题价值：\n1、产品价值：以飞书套件为依托，打通从Memory建设到Agent执行再到效果评测的完整闭环，实现AI能力从孤立Feature向协作式智能体平台的跃迁，显著提升企业用户的生产力效率；\n2、技术引领：在Memory Benchmark、Omni Streaming理解、LLM-as-a-Judge裁判模型、长程Agent任务等前沿方向建立技术积累，形成学术与工业界双向影响力；\n3、生态战略：会议、文档、知识问答等场景天然是多Agent协作的孵化土壤，本课题构建的基础能力将为未来多智能体企业协作生态奠定核心基础，支撑飞书成为国内领先的企业 AI 智能体平台。","requirements":"1、2027届毕业，获得博士学位，图论与组合数学、计算机科学、复杂网络分析、AI等相关专业优先；\n2、具备扎实的机器学习理论基础，对RAG、Agent、AI逻辑推理、模型后训练等领域有理论基础和强烈的好奇心； \n3、具备良好的机器学习实践基础，熟悉机器学习相关类库，了解TensorFlow、PyTorch等深度学习框架之一；\n4、创新思维突出，并且能从本质出发思考问题，有自主探索解决方案的能力；\n5、具备优秀的学习与分析能力、沟通与团队协作能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7628831453627959605","sourceKey":"bytedance","company":"字节跳动","title":"基于LLM的软件缺陷检测技术的探索和研究-质量技术","city":"北京","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7628831453627959605/detail","duty":"团队介绍：字节跳动质量技术团队，我们聚焦质量领域前沿创新，打造稳定、高效、领先的质量技术，深度赋能抖音、今日头条、豆包、电商等亿级用户产品。\n当前，我们通过AI来检测代码、架构、产品的缺陷、风险和效果，用AI重构质量保障模式，提升研发效能。聚焦智能缺陷检测、GUI agent、AI评测等前沿方向，希望通过质量技术的突破，用AI改变测试行业。欢迎加入，与我们一起，定义和构建下一代质量技术，推动行业前进。\n\n课题介绍：\n随着大模型技术在软件开发领域的广泛应用，代码开发效率显著提升，AI生成代码的质量不确定性，都为软件测试带来了全新挑战。传统静态分析方法在复杂业务逻辑校验、功能一致性验证等场景存在明显局限，而动态GUI测试与API测试则面临执行开销高、测试覆盖度不足等问题。\n本课题旨在构建一种基于LLM的智能缺陷检测系统。通过对需求文档和技术方案的语义理解，结合跨端、跨仓的代码调用关系的刻画，产出业务逻辑与代码实现的精准对齐，在此基础上，构建具备对各类缺陷特征有充分感知的缺陷检测智能体，高效、精准的识别业务逻辑、架构性能、程序安全等复杂缺陷。\n\n课题挑战：\n1、公司多样化业务场景下，对多模态需求的语义理解和功能逻辑提取；\n2、跨端、跨仓、多技术栈的代码链路分析；\n3、海量缺陷数据的特征分析和提取；\n4、支持大规模应用的Agent系统工程；\n\n课题价值：\n1、保证软件质量的要求下，构建一种以静态检测技术为主的软件测试模式，优化测试资源的配置和效率；\n2、实现软件缺陷的早期发现，降低缺陷识别和修复的成本，显著提升研发效能。","requirements":"1、2027届毕业，获得博士学位，人工智能、计算机、数学相关专业优先；\n2、对LLM在代码领域的应用有较大的兴趣，有一定实践经验者优先；\n3、出色的问题分析能力，能够自主探索前沿技术，并积极应用到业务问题解决中；\n4、良好的沟通联动能力，与团队持续探索&学习新技术，实现先进技术的不断落地；\n5、优秀的代码能力、数据结构和基础算法功底；\n6、在LLM、Agent架构领域有扎实的理论和实践基础，有发表顶会论文优先，有高影响力的开源项目者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7628573927275022645","sourceKey":"bytedance","company":"字节跳动","title":"基于多模态大模型的视频分析/理解/画质评估及增强与视频智能编码/表达-音视频技术（上海）","city":"上海","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7628573927275022645/detail","duty":"团队介绍：视频与边缘部门承载了字节跳动的媒体内容分发基建及技术中台，支持了字节跳动全系产品，如抖音、今日头条、番茄小说、西瓜视频等APP的点播、直播、实时通信、图片等多媒体业务发展，同时将业务发展过程中沉淀下来的技术能力和工具，通过火山引擎对外输出，面向各行各业用户提供视频云产品和服务，愿景是为内外部业务伙伴提供最低成本、最优画质、最低延时、最安全可靠的富媒体内容分发解决方案，助力业务伙伴降本提效实现持续增长。\n\n课题介绍：\n随着4K、HDR等技术成为主流标准，消费者对视频画质的要求日益提升。然而，视频在拍摄、传输和压缩过程中，画质往往受损，影响观看体验。多模态大模型的出现为视频分析、理解、画质评估、及画质增强提供了新的可能性，因此希望能够探索多模态大模型在多媒体场景的应用可行性，发掘基座大模型在大规模业务视频内容应用的潜力，建立业内领先的多媒体场景的多模态大模型解决方案。\n1、画质分析以及人眼感知：利用多模态大模型，深入分析视频内容及画质退化问题，研究人眼对色彩、帧率、清晰度等画质维度的感知能力，从而使得画质评估更为准确，画质增强对退化的处理更为智能，增强的结果更符合人眼主观；\n2、生成式画质增强：利用生成式大模型的先验信息，大幅提升画质增强的效果天花板，并且解决生成伪像、生成保真度、生成稳定性等当前生成式算法存在的问题；\n3、视频时域任务：研究画质理解和增强在视频上的拓展，包括时域信息表征建模，时域退化理解，时域画质增强连续性，时域推理加速等；\n4、用户视角的验证：在大规模用户环境中，从用户的实际观看体验出发，验证画质增强算法的有效性和用户满意度；\n5、视频智能编码及表达：近年来，深度学习在视频及图像压缩领域逐渐成为研究热点。随着传统编码标准逐渐逼近性能瓶颈，深度学习方法受到了业界的高度重视，发展极为迅速。目前在部分场景下深度学习方法已经可以接近甚至超过H.266/VVC的压缩效率。然后相对传统编码，深度学习方法也面临着诸多挑战，例如在很多应用场景下的压缩效率依然落后于传统编码技术，运算复杂度高，跨平台编解码缺乏兼容性，难以标准化等等。此外，如何将传统编码算法和深度学习算法在统一的硬件架构下实现，并达到极致的算力利用效率，涉及到算法和硬件架构创新，是研究的难点。\n\n课题挑战：\n基于多模态大模型的分析/理解/画质评估和增强面临如下挑战：\n1、多模态长视频复杂时序关系建模；\n2、少样本grounding-based理解画质评估模型；\n3、可交互/用户偏好对齐的视频处理/增强模型。\n\n视频智能编码及表达面临如下挑战：\n1、如何实现压缩效率显著超越传统编码器；\n2、如何满足可接受的复杂度及功耗要求；\n3、如何保证跨平台编解码一致性；\n4、如何高效压缩token等新兴智能信息；\n5、如何有效表达语义信息。\n\n课题价值：\n基于多模态大模型的分析/理解/画质评估和增强的研究价值：\n1、提升中长视频语义理解与事件定位能力及处理效率，支撑广告推荐、内容理解、视频价值评估和转码增强等核心业务；\n2、降低画质标注成本，实现局部退化可解释评估，提升跨内容泛化能力，支持像素级画质质检与优化。\n\n视频智能编码及表达的研究价值：\n1、传统视频编码技术逐渐接近其能力极限，视频的智能编码技术有希望突破该极限，实现前所未有的视频压缩效率；\n2、在新的应用场景中，Token等新兴智能信息将占据显著带宽。对新兴智能信息的压缩将显著提高传输与存储效率；\n3、高效视频智能编码及表达一旦实现标准化，将在市场中占据有利位置，有巨大潜在专利价值；\n4、高效视频智能编码及表达有可能明显节省带宽及存储，直接创造经济收益。","requirements":"1、2027届毕业，获得博士学位，人工智能、计算机、数学等相关专业优先；\n2、精通常见的图像、视频处理算法，掌握常见视觉算法，如分类、检测、分割等；\n3、具有扎实的编程功底，良好的设计能力和编程习惯；\n4、熟悉Diffusion、LLM等大模型相关算法和技术，熟悉大模型训练与调优，并且有实际应用的经验；\n5、支持AIGC大模型在底层视觉、画质、压缩等多媒体方向的探索以及落地；\n6、有较强科研经验优先，在CVPR、ICCV、NeruIPS、ICLR等顶级会议、期刊发表过论文者优先；在大模型领域，有主导过具有影响力的开源项目优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7628457923739846965","sourceKey":"bytedance","company":"字节跳动","title":"【实习】面向复杂任务的数据智能体：程序推理与自适应演进研究-数据智能（北京/上海/杭州）","city":"北京","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7628457923739846965/detail","duty":"团队介绍：专注大模型在数据智能方向的应用落地，横向支持公司多个数据产品的大模型解决方案。团队致力于跟进大模型前沿进展，结合领域模型的优化策略来设计端到端的算法优化和评估方案，实现数据产品的智能升级与应用效果提升。团队鼓励敏捷创新，知识共享的协作氛围，专注投入对数据智能课题的持续探索研究。\n\n课题介绍：\n大语言模型（LLM）驱动的智能Agent在各类任务中展现出强大的推理与交互能力，已成为AI领域的前沿热点。然而，现有大多数Agent设计隐含地基于“确定性假设”，即默认输入信息完全可靠、任务目标明确。这在现实场景中往往并不成立——数据不完整、外部工具执行失败、用户意图随时间演变，使Agent产生误导性甚至错误的结论。面对“信息不确定性”这一核心挑战：课题一方面聚焦知识冲突与推理鲁棒性，另一方面聚焦SQL逻辑依赖与演进维护。\n\n课题挑战：\n1、鲁棒Agent推理问题：检索增强生成（RAG）是获取外部知识主流机制，但存在知识冲突问题，当前LLM面对噪声检索表现仍有提升空间；\n2、演进式SQL任务开发与维护问题：企业级数据治理中，SQL脚本面临底层数仓Schema变更和业务统计口径演进问题，传统方法无法提供深层语义偏差指导，现有模型在超100行存量SQL维护任务成功率较低。\n\n课题价值：\n1、鲁棒Agent推理技术路线：基于POMDP的决策规划，维护信念状态并计算最优行动策略；多策略协同，认知不确定性超阈值时切换并发探索模式；自适应响应，依据信念状态残余不确定性决定输出；\n2、演进式SQL任务开发与维护技术路线：SynSQL-Evolution 数据工程，构建百万级合成语料；GRPO强化学习框架，设计复合奖励函数；计划驱动推理范式，输出“逻辑变更清单”；依赖感知Agent协同，结合拓扑规划器处理长序列需求并构建实时纠错循环。","requirements":"1、2027届及以后毕业，博士在读，人工智能等相关专业优先（如计算机科学、数学、电子工程等）；\n2、熟练使用Python、PyTorch等语言和代码库，熟悉大模型领域尤其是强化学习相关研究工作和算法，有大模型强化学习的研发基础，拥有高影响力会议论文(ICLR、NeurIPS、ICML等)、知名竞赛获奖经验者优先；\n3、具备优秀的学术视野与判断力，拥有出色的问题提出、分析及解决能力，良好的团队协作精神和沟通意识。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7615461847487088901","sourceKey":"bytedance","company":"字节跳动","title":"AI搜索算法实习生-TikTok Shop","city":"上海","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7615461847487088901/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：TikTok Shop 是 TikTok 旗下的内容电商。平台汇聚全球优质商家与创作者，通过短视频、直播等多场景连接消费者，让新奇好物畅销全球，让美好生活触手可得。目前团队分布在美国、英国、法国、印尼、墨西哥、中国等全球多个国家和地区，在这里你将有机会深入国际场景，面向全世界商家及用户，和跨区域团队协作，共同探索创新购物模式。期待和优秀的你一起创造更多可能！\n\n1、个性化排序：传统排序算法难以充分利用多模态信息（如文本、图像、视频等），且模型复杂度有限，无法满足用户对精准化和个性化搜索的需求；\n2、超大规模检索：传统判别式模型在千亿级别候选库的检索中，面临模型容量不足、索引效率低下等问题，亟需新一代检索算法；\n3、复杂Query理解：用户搜索需求日益复杂，传统搜索引擎难以准确理解长难句、多义Query的语义，导致搜索结果满意度低；\n4、资源利用率：搜索系统存储和计算分离的架构导致资源利用率低，如何在保证性能的同时优化资源使用成为关键问题。","requirements":"1、2027届本科及以上学历在读，计算机、软件工程等相关专业优先；\n2、在人工智能领域顶级会议上有发表论文或有深入研究经历者优先；\n3、有扎实的机器学习/深度学习算法基础和代码能力，熟练C/C++或Python；\n4、聪明、自信，敢于突破，对技术有执着的追求和热爱；\n5、具备良好的团队沟通协作能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7600980173110315317","sourceKey":"bytedance","company":"字节跳动","title":"AIGC图像生成算法实习生-火山方舟","city":"北京","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7600980173110315317/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：火山方舟是火山引擎推出的一站式大模型服务平台，是中国大模型市场产品和份额领跑者。平台提供模型推理、评测、精调等全流程服务。方舟搭载了豆包及业界主流大模型，提供丰富的插件生态和AI应用开发服务，并通过稳定可靠的安全互信方案、专业的算法技术服务，全方位保障企业级AI应用落地。\n\n1、优化Seedream系列模型，为模型的通用能力提升相关技术负责，包含图像理解、图像生成、图像编辑等前沿技术；\n2、推动技术在内容创作/特效/素材生成/辅助设计等领域的应用；\n3、参与技术规划制定，把握图像生成技术最新发展趋势。","requirements":"1、2027届本科及以上学历在读，计算机、软件工程等相关专业优先；\n2、在多模态、AIGC等一个或多个领域有较深入的研究者，熟悉生成相关技术路线（扩散模型，自回归模型等），有大规模训练经验、AIGC、VLM、音视频生成等相关经验；\n3、动手能力强，具有熟练的算法和编程能力，熟悉C/C++和Python编程；\n4、工作积极主动，能与团队融洽合作相处，同时能够独立完成研究工作；\n5、具有优秀的基础算法、扎实的机器学习基础，熟悉CV、AIGC、NLP、RL、ML等领域的技术，在CVPR、ECCV、ICCV、NeurIPS、ICLR、SIGGRAPH或SIGGRAPH Asia等顶级会议/期刊上发表论文者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7592132534688860421","sourceKey":"bytedance","company":"字节跳动","title":"后端开发实习生-Flow","city":"北京","category":"后端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7592132534688860421/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：字节跳动Flow产品研发团队，专注研究AI智能化相关业务落地，目前落地豆包、Dola等APP，以及对应的Bot开发平台等AI智能化创新产品，业务和团队均处于快速发展期，成长空间大，欢迎各位同学加入！\n\n1、负责豆包各类场景化Agent的后端研发；\n2、负责AI系统架构构建，快速搭建应用，持续优化产品体验、稳定性；\n3、持续探索在各种场景下，利用AI能力增强产品体验，提升工程效率。","requirements":"1、2027届本科及以上学历在读，计算机等相关专业优先；\n2、学习能力强，有独立解决问题的能力；\n3、熟悉面向对象编程，掌握Java/C++/Python/Go中的至少一门语言，Go背景优先；\n4、有良好的沟通能力和业务理解能力；\n5、对技术有好奇心，持续关注熟悉前沿技术；\n6、每周保证至少4天的实习时间，可实习4个月以上。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7680868934400903429","sourceKey":"bytedance","company":"字节跳动","title":"政务文旅IP运营实习生 - 抖音生活服务","city":"广州","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7680868934400903429/detail","duty":"团队介绍：抖音生活服务依托抖音POI （Point of Interest）、短视频、直播、搜索等，以“激发线下生意，丰富美好生活”为使命，致力于成为最值得信赖的生活服务平台，为用户提供更丰富、独特的生活体验，为合作伙伴提供包容且公平的健康营商生态。截至2025年底，抖音生活服务业务已覆盖400+城市，超过1500万家动销门店。抖音生活服务将继续携手生态伙伴，为用户提供值得心动的商品和服务。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、参与抖音生活服务政务文旅IP活动相关文案撰写，包括活动宣传文案、活动说明、复盘报告等，确保文案贴合活动调性、符合政策导向且具备传播性；\n2、协助完成IP活动的策划执行工作，包括梳理活动流程、构思创意玩法、对接跨部门资源，配合完成活动方案的细化与执行；\n3、收集整理本地生活行业动态、行业案例、用户偏好等信息，为活动策划提供数据与思路支撑；\n4、跟进活动全流程，协助执行相关工作，保障活动高效推进。","requirements":"1、本科及以上学历在读，市场营销、广告、新闻传播、汉语言文学等相关专业优先；\n2、有数据意识，了解AI，了解活动策划基本逻辑，有校园活动、商业活动策划相关经验者优先，具备良好的创意构思能力和落地执行意识；\n3、熟悉互联网生态，对内容平台APP等领域有一定了解，具备较强的信息搜集、梳理和分析能力；\n4、工作认真负责，有良好的沟通协作能力，能够快速响应工作需求，具备较强的学习能力；\n5、尽快入职，每周全勤5天，实习5个月以上。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7672248922642843909","sourceKey":"bytedance","company":"字节跳动","title":"AI全栈开发工程师（电商/前后端） - 中国交易与广告","city":"上海","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7672248922642843909/detail","duty":"团队介绍：中国交易与广告，负责抖音电商、生活服务、广告营销等营收业务的研发。用技术带来美好生活，让用户发现更多优价好物，为用户提供更丰富独特的生活体验；连接海量用户与商家，促进交易达成，让生态里全流程体验更流畅，助力营收业务长效增长。\n加入团队，你将投身流量与增长主战场，挑战复杂业务场景技术难题；直面真实商家和用户，用技术解决看得见的问题，在实战中快速成长，书写属于你的价值故事！\n\n1、依托AI Coding工具开展日常研发工作，独立负责电商、生活服务、广告相关项目前后端全栈开发、功能迭代与接口联调，保障业务需求高质量落地；\n2、承担业务方向前后端技术方案设计、技术选型与开发实现，独立完成功能编码、接口设计与联调；覆盖商品、交易、营销活动、商家经营工作台、履约链路，以及广告投放、创意素材、竞价出价、效果分析等业务场景；\n3、主导或参与前后端基础设施建设，沉淀通用组件库，持续优化工程化工具链、CI/CD交付流程，提升团队整体研发效能；\n4、协同产品、算法、数据等跨职能团队，推进技术方案评审与对齐，把控项目进度，保障业务按时稳定交付；\n5、持续跟进前端前沿技术，推动新技术业务落地，不断优化页面性能、稳定性与终端用户体验；\n6、探索AI、Agent在电商、生活服务、广告场景的创新落地，基于大模型重构营销活动搭建、商家经营诊断、履约异常处置、广告投放与创意生成等业务流程，赋能研发与业务提效。","requirements":"1、2027届获得本科及以上学历，计算机、人工智能、软件工程等相关专业；\n2、熟练掌握Python/Go/Java/JavaScript至少一门开发语言，熟悉Node.js或Go，具备前后端一体化开发实践能力；\n3、熟练使用React等主流前端框架，能够独立完成复杂业务界面、数据可视化功能开发；\n4、理解LLM基础原理，熟悉AI Agent核心能力模块（Prompt工程、记忆机制、工具调用、RAG、多智能体），能够结合业务场景选型适配不同能力层级的大模型；\n5、熟练使用主流AI编码工具（TRAE、Claude Code、Codex等）；可借助AI完成需求拆解、代码编写、复杂逻辑重构、问题定位与修复、单元测试编写、代码评审，具备AI协同研发思维；\n6、掌握Git常用操作；具备良好沟通表达与团队协作能力，对新技术保持好奇心，擅长独立思考、复盘总结。\n\n加分项\n1、拥有AI Agent开发、部署与二次开发经验，可参与智能体在电商/生活服务/广告场景落地探索；包括交互开发、营销/商家经营/广告投放/创意工作流编排、任务拆分、多智能体并行调度、模型动态择优等实践；\n2、具备利用AI Coding工具提升个人与团队研发效能的实战经验；了解MCP协议、LLM工具调用机制，能够搭建AI自动化工作流，沉淀可复用调度模板与工程实践方案；\n3、具备电商交易、商家经营、营销活动、物流履约、本地生活，或是广告投放、创意素材、竞价营销系统等业务开发经历；拥有对话应用、智能任务编排、企业知识库平台相关项目经验优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669700362425190709","sourceKey":"bytedance","company":"字节跳动","title":"AI Agent后端研发工程师 - Data AML","city":"北京/杭州","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669700362425190709/detail","duty":"团队介绍：Data AML是字节跳动的机器学习中台，为抖音/今日头条/西瓜视频等业务提供推荐/广告/CV/语音/NLP的训练和推理系统。为公司内业务部门提供强大的机器学习算力，并在这些业务的问题上研究一些具有通用性和创新性的算法。同时，也通过火山引擎将一些机器学习/推荐系统的核心能力提供给外部企业客户。\n\n1、企业级Agent架构与研发：参与企业级复杂AI Agent的后端服务设计与开发；构建高可用、高扩展的微服务体系，支撑大规模Agent应用、复杂自动化工作流及数据产品的稳定运行；参与推荐系统、AIGC应用的技术方案设计、工程实现及性能优化；\n2、多Agent协作框架：设计多Agent编排与调度系统，支持复杂任务分解、角色分工、消息通信与协同工作流；\n3、可观测性与质量保障：持续监控与优化Agent的回答质量、成功率与响应时延；\n4、实时数据流处理：负责内容数据实时接入、清洗去重、语言识别、结构化解析（正文/作者/时间/互动量/链接）、跨平台去重与归并；基于流式计算实现实时NLP分析、Embedding向量化、话题增量聚类，支撑秒级到分钟级的热点发现、风险预警与业务洞察；运用AI技术建设内容理解、内容生成与安全合规等内容生态通用能力；\n5、高并发系统设计：支撑大规模用户访问，进行性能调优、容量规划与故障排查，保障系统在高并发场景下的稳定性；探索AI原生场景下的软件工程实践与技术范式。","requirements":"1、2027届获得本科及以上学历，计算机、人工智能等相关专业优先；\n2、掌握扎实的计算机基础知识，深入理解数据结构、算法和操作系统知识；熟悉大语言模型相关技术：Prompt Engineering、RAG（检索增强生成）、Function Calling、Fine-Tuning数据工程、长文本处理等；\n3、了解大语言模型相关技术，有Agent开发、Agent框架、Agent Skills等相关经验者优先；有LLM应用开发经验，熟悉LangChain/LlamaIndex/AutoGen/CrewAI等Agent框架，或有自主设计Agent架构的经验；\n4、有优秀的逻辑分析能力，能够对业务逻辑进行合理的抽象和拆分；\n5、有强烈的求知欲，优秀的学习和沟通能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669694620138260789","sourceKey":"bytedance","company":"字节跳动","title":"策略产品经理 - TikTok直播","city":"北京","category":"产品经理","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669694620138260789/detail","duty":"团队介绍：TikTok是一个覆盖150个国家和地区的国际短视频平台，我们希望通过TikTok发现真实、有趣的瞬间，让生活更美好。TikTok在全球各地设有办公室，全球总部位于洛杉矶和新加坡，办公地点还包括纽约、伦敦、都柏林、巴黎、柏林、迪拜、雅加达、首尔和东京等多个城市。\n\nTikTok直播是全球领先的直播业务，以实时互动为核心，提供多元化的商业化模式和创作工具。我们为用户提供独特的内容和消费体验；为创作者找到合适的观众，提供最好的工具和一系列盈利模式，帮助创作者创造更多机会、改变他们的生活；通过直播，平台也能从中获得健康、客观的商业化收益，持续发展。我们一直听到这样的故事 —— “LIVE changes my life” —— 他们更好，我们才会更好。\n\n加入我们，一起探索 “不可能的事”—— 我们是行业的先行者，在一步步改变行业。我们持续让行业了解直播是一种新的内容形式，是创作者可以依赖的商业模式。\n\n1、策略规划与业务增长：负责制定直播推荐的整体策略和规划，聚焦提升直播内容分发效率与精准度，通过优化推荐算法逻辑、研究用户与内容生态匹配度、设计差异化推荐策略等方式，实现看播用户规模与活跃度的增长目标，推动业务持续发展；\n2、内容推荐泛化与区域增长：主导直播内容推荐的泛化策略，拓展内容与用户群体的多样性，挖掘未被满足需求的用户群体，针对不同内容偏好设计推荐增长策略；\n3、数据驱动策略优化：通过深度的用户调研和多维度数据分析，洞察用户行为模式与内容消费偏好，明确用户分层逻辑；依据不同用户群体特征，构建个性化推荐策略模型，以数据为支撑持续迭代优化推荐策略；\n4、用户分层与精准推荐：对用户进行精细化分层管理，针对各层级用户的行为习惯、兴趣偏好制定差异化的推荐产品策略与运营方案，提升用户对推荐内容的满意度与忠诚度，挖掘用户增长潜力。","requirements":"1、2027届获得本科及以上学历，统计学/数学/计算机相关专业优先；\n2、具备优秀的策略设计能力和业务理解能力，能够敏锐通过数据波动、业务流程发现推荐策略中的问题，并推动有效解决方案落地；\n3、具备较强的项目管理能力，能够精准把握各方需求，高效整合资源，在跨部门协作中应对复杂任务，达成业务目标。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667467797661026613","sourceKey":"bytedance","company":"字节跳动","title":"Code Agent策略算法工程师 - TRAE","city":"北京/上海/杭州","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667467797661026613/detail","duty":"团队介绍：TRAE是字节跳动旗下AI办公工具，产品已上线国际版与中国版，拥有TRAE IDE和TRAE Work两种产品；既可以用TRAE IDE写代码、读项目、改Bug，也可以用TRAE Work写方案、做分析、做应用、推进协作。TRAE当前支持PC、手机、Web多端使用，让用户随时随地高效产出！ Let TRAE Work For You！同时我们正在寻找充满热情、富有创造力的人才。期待你的加入！\n\n1、参与TRAE代码场景的大模型效果优化，包括数据建设、指令微调、RLHF/RL后训练及评测体系搭建；\n2、参与TRAE Agent Harness核心能力的设计与迭代，包括多模型适配、Context Engineering、工具调用与多轮规划；\n3、参与Agent效果分析与业务指标建模，通过数据驱动持续提升产品体验；\n4、跟踪LLM、Agentic Workflow、Tool Use、Code Agent等方向的前沿进展，快速验证并落地创新方案。","requirements":"1、2027届获得硕士及以上学位，计算机科学、软件工程、人工智能、数学等相关专业；\n2、具备扎实的编程基础和良好的工程素养，熟悉Python/C++中至少一门语言；\n3、熟悉机器学习/深度学习基本原理，了解Transformer架构及大语言模型相关技术；\n4、自驱力强，对AI编程方向有热情，具备快速学习和独立解决问题的能力。\n\n有以下一项或多项经历者优先：\n1、大模型预训练/微调/RLHF相关研究或项目经验；\n2、Agent框架、工具调用、代码生成相关开发经验；\n3、高质量学术论文发表（NeurIPS、ICML、ICLR、ACL、EMNLP等）；\n4、开源项目贡献或编程竞赛获奖。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667048464069544197","sourceKey":"bytedance","company":"字节跳动","title":"后端开发工程师（治理风控） - TikTok Shop","city":"北京/上海","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667048464069544197/detail","duty":"团队介绍：TikTok Shop是以TikTok为载体的内容电商业务，致力于成为用户发现并获取优价好物的首选平台，在直播电商、视频内容电商等多场景下，TikTok Shop希望能为用户提供更个性化、更主动、更高效的消费体验，为商家提供稳定可靠的平台服务，在更多的地区实现没有难卖的优价好物，让美好生活触手可得的使命。我们邀请你来此成长、钻研，发掘无限的潜力，一起应对技术和业务上的挑战。目前团队拥有丰富的国际产品研发经验，包容多元的文化，且在全球设立研发团队，邀请你来一起接受跨国合作的挑战！\n\n1、负责国际电商治理和风控等业务的后端开发工作；\n2、负责架构设计和开发，为亿级用户提供优质顺畅的信息服务和极致体验；\n3、负责在线大流量高并发系统设计和性能调优；\n4、参与各专项技术调研，新技术引入等前瞻项目。","requirements":"1、2027届获得本科及以上学历，计算机相关专业优先；\n2、热爱计算机科学，精通至少一门编程语言，包括但不仅限于：Java、C、C++、PHP、Python、Go；\n3、掌握扎实的计算机基础知识，深入理解数据结构、算法和操作系统知识；\n4、有优秀的逻辑分析能力，能够对业务逻辑进行合理的抽象和拆分；\n5、有强烈的求知欲，优秀的学习和沟通能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7654853661933783301","sourceKey":"bytedance","company":"字节跳动","title":"AI产品实习生（音视频方向） - 飞书&豆包办公任务","city":"上海","category":"产品经理","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7654853661933783301/detail","duty":"团队介绍：飞书&豆包办公任务模式致力于以 AI 重构办公生产力，推动企业与个人的工作方式从“高效协同”迈向“智能生产”。依托飞书成熟的一站式协作与管理能力，以及豆包办公任务模式领先的大模型能力，我们正在打造深度融合沟通、会议、文档、知识、创作与执行全场景的下一代 AI 办公产品，推动办公平台从传统协作工具升级为智能生产平台，为组织释放更高效、更智能、更具增长潜力的生产力价值。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、深入用户真实使用场景，挖掘用户需求与痛点，提出完善的产品方案，推动产品持续创新与优化；\n2、参与产品需求迭代和优化，负责明确功能的方案撰写跟进及上线；\n3、结合上线产品进行用户反馈、数据分析与复盘，快速迭代优化；\n4、负责增长项目的实验策略及数据效果跟踪。","requirements":"1、本科及以上学历在读，计算机、软件工程等相关专业优先；\n2、良好的产品意识，对产品体验细节敏感，有较好的产品设计能力和经验，及数据分析能力；\n3、目标导向，工作踏实仔细，具备强烈的责任感、自我驱动力与工作热情；\n4、对AI技术有基本认知与了解，日常善于使用AI工具提升效率，具备积极主动探索与尝试新技术的意愿；\n5、拥有强烈的好奇心与求知欲，对行业趋势与市场动态保持敏锐的观察和洞察力，能从用户视角与产品视角综合决策；\n6、过往做过增长或数据分析相关项目的优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7628214297908119813","sourceKey":"bytedance","company":"字节跳动","title":"下一代多模态智能审核大模型及Agentic技术研究-TikTok内容安全算法","city":"北京","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7628214297908119813/detail","duty":"团队介绍：国际化内容安全算法研究团队致力于为字节跳动国际化产品的用户维护安全可信赖环境，通过开发、迭代机器学习模型和信息系统以更早、更快发掘风险、监控风险、响应紧急事件，团队同时负责产品基座大模型的研发，我们在研发过程中需要解决数据合规、模型推理能力、多语种性能优化等方面的问题，从而为平台上的内容审核、搜索、推荐等多项业务提供安全合规，性能优越的基座模型。\n\n课题介绍：\n随着AIGC爆发与内容生态全球化，审核面临策略动态演变、多语言多模态复杂度激增、生成式对抗攻击升级三大挑战，传统\"感知→分类\"范式已触顶。本课题聚焦两大前沿方向：\n1、多模态审核基座——研究大规模MoE架构训练与路由优化、多模态（文本/图像/视频/音频）跨模态对齐与推理、理解与生成统一建模（Unified Understanding & Generation）、面向审核场景的高质量合成数据生产（Self-play/对抗增强），构建超越现有开源/闭源模型的审核基座；\n2、Agentic审核系统——借鉴Agent-R1等前沿范式，以强化学习（GRPO/PPO）端到端训练审核Agent的多步决策能力，通过Context Engineering动态组装审核上下文，基于MCP协议构建工具生态（OCR/ASR/Knowledge Graph/策略RAG/实时搜索），实现审核任务的自主规划、Tool Call协同与可解释性闭环，驱动审核从被动分类向主动智能决策范式跃迁。\n\n课题挑战：\n1、MoE多模态安全基座：大规模稀疏MoE训练稳定性与路由优化、跨模态Token对齐、理解与生成统一架构设计；\n2、RL驱动Agentic决策：基于GRPO/PPO端到端训练Agent多步推理与工具调用策略，突破样本效率与训练稳定性瓶颈；\n3、Context Engineering与工具协同：动态上下文组装、MCP工具生态构建、多源异构证据融合与GraphRAG策略检索；\n4、泛化与对抗鲁棒性：跨200+语言/策略泛化、AIGC生成内容对抗检测、少样本场景的多维Reward信号设计。\n\n课题价值：\n1、技术引领：RL × Agentic × 多模态大模型的交叉融合是当前AI最前沿方向，本课题率先将其落地于大规模内容审核场景，具备独特的工业级数据规模与真实反馈闭环优势；\n2、业务价值：服务全球数十亿用户内容安全，推动审核从人工+外部API依赖向自主Agent全机审演进，直接降低数亿美元级成本，同时提升审核一致性与响应速度；\n3、行业领先：当前业界尚无成熟的RL驱动Agentic审核系统，本课题有望定义该方向的技术范式，产出具有行业影响力的研究成果。","requirements":"1、2027届毕业，获得博士学位，计算机、电子、数学、物理等相关专业；\n2、丰富的ML/CV/NLP/推荐经验，包括但不限于：\n1）机器学习/数据挖掘/CV/NLP/多模态等相关竞赛或行业经验；\n2）机器学习/数据挖掘/人工智能/大模型相关领域的会议论文（KDD/WWW/NIPS/ICML/CVPR/ACL/AAAI）；\n3）有大模型/强化学习相关的研究经历和创新探索；动手快，在开源社区有大模型相关的贡献记录；在业务场景有大模型落地经验者优先；\n3、具备扎实的编码能力、数据结构和基础算法功底，熟练运用各种算法框架与工程框架，熟悉Python/C++等编程语言；\n4、优秀的分析问题和解决问题的能力，并热衷于解决具有挑战性的问题；\n5、对技术充满热情，良好的沟通能力和团队合作精神。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7689039437923862789","sourceKey":"bytedance","company":"字节跳动","title":"家清日用行业实习生 - 抖音电商运营","city":"上海","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7689039437923862789/detail","duty":"团队介绍：抖音电商以“总能发现好东西”为主张，致力于成为用户发现丰富好物的首选平台。众多抖音创作者通过短视频、直播、商城等丰富的形式，给用户提供更个性化、更生动、更高效的消费体验。同时，抖音电商积极引入优质合作伙伴，为商家变现提供多元的选择。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、结合抖音内容特性，制定各行业在抖音产品内的完整运营方案，根据美妆、食品、服饰、母婴、教育、个护家清等行业的特性、发展阶段及市场趋势制定行业策略及商家在字节跳动系内的发展运营策略；\n2、了解抖音的短视频和直播流量规律，关注内容电商的玩法；\n3、承接KA品牌协助支持、客户高价问题协调处理等需求。","requirements":"1、本科及以上学历在读、理科；\n2、具有较强的责任心和合作意识，自驱力优秀，能够完成较为复杂的工作任务，并进行跨部门协作；\n3、具备较强的沟通协作以及组织协调能力，能够与重要商家进行交流与合作；\n4、具备一定的商业洞察能力，能够对行业现状及市场环境进行分析，不断发掘行业发展的底层逻辑。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7687577479330138373","sourceKey":"bytedance","company":"字节跳动","title":"美国Fashion商家管理实习生 - TikTok Shop","city":"上海","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7687577479330138373/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商。平台汇聚全球优质商家与创作者，通过短视频、直播等多场景连接消费者，让新奇好物畅销全球，让美好生活触手可得。目前团队分布在美国、英国、法国、印尼、墨西哥、中国等全球多个国家和地区，在这里你将有机会深入国际业务场景，面向全世界商家及用户，和跨区域团队协作，共同探索创新购物模式。期待和优秀的你一起创造更多可能！\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、协助完成国内跨境一流梯队商家日常运营沟通和重点项目推进，从0到1帮助商家通过短视频平台出海；\n2、挖掘平台特点和商家需求，协助团队跟进和解决商家日常运营问题，梳理商家运营流程并不断迭代；\n3、通过数据分析，不断协助商家优化选品、流量策略、内容策略等运营方向。","requirements":"1、本科及以上学历在读，商科相关专业优先；\n2、熟练使用办公软件，对数据敏感，擅长分析与总结；\n3、对电商行业有基本了解，熟悉短视频平台及欧美社交媒体更优；\n4、耐心负责，具备良好的团队协作能力，沟通能力强，思维活跃，逻辑清晰，工作高效；\n5、每周可实习5天，可实习6个月以上优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7686369683588630789","sourceKey":"bytedance","company":"字节跳动","title":"电商运营AI产品实习生（业务场景方向） - TikTok Shop","city":"上海/北京","category":"产品","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7686369683588630789/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商。平台汇聚全球优质商家与创作者，通过短视频、直播等多场景连接消费者，让新奇好物畅销全球，让美好生活触手可得。目前团队分布在美国、英国、法国、印尼、墨西哥、中国等全球多个国家和地区，在这里你将有机会深入国际业务场景，面向全世界商家及用户，和跨区域团队协作，共同探索创新购物模式。期待和优秀的你一起创造更多可能！\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、负责运营Agent问题解决场景产品建设，围绕运营决策、作业与管理等环节，完成从场景定义、需求挖掘、产品设计到上线的迭代，提升问题解决质量与效率；\n2、深入运营团队一线，理解各类运营人员的工作目标、方法与流程，识别高价值场景，并将复杂运营方法抽象为可复用的产品能力；\n3、能够灵活运用Agent、Skill、MCP、A2UI、知识库等能力，完整设计人机协同方案，持续优化Agent的准确性、可用性与用户体验；\n4、有效协同研发、设计、数据、垂域产品等协作团队，端到端推进产品快速迭代，保证功能按时、高质量上线。","requirements":"1、本科及以上学历在读，专业不限，计算机、数据、商科、电子商务、管理科学等相关背景优先；\n2、日常全勤5天实习，对电商、商业化、AI产品、CRM或SaaS工具有浓厚兴趣，有AI相关实习、校园项目、竞赛或研究经历者优先；\n3、具备较强的学习能力和结构化思考能力，能够快速理解业务场景，并将复杂流程拆解为清晰的问题、角色和行动；\n4、目标感强，主动性高，乐于在环境中解决问题，具备良好的沟通表达和跨团队协作能力；\n5、具备基础的分析意识，能够通过数据和用户反馈发现问题、验证假设并推动优化。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7686025120608438581","sourceKey":"bytedance","company":"字节跳动","title":"3D动画实习生 - 研发支持中心","city":"北京/上海","category":"游戏美术","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7686025120608438581/detail","duty":"团队介绍：研发支持中心主要为各工作室提供音视频视听解决方案，支撑音视频内容制作与技术攻关，持续打造高品质游戏沉浸式视听体验。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、隶属于游戏研发-视频中台，3D动画设计师岗位，负责游戏研发与宣发期视频动画制作工作；\n2、负责游戏研发中的3D动画演出制作，包括但不限于角色战斗动作、过场动画、摄像机动画等；\n3、对齐导演创意，负责游戏局内表演动画制作/优化等工作，与上下游环节积极协作，高效沟通并解决问题；\n4、关注技术积累，完成流程及生产规范整理。","requirements":"1、本科及以上学历在读；\n2、熟悉引擎，对Timeline动画有了解，有游戏研发剧情相关实习经验优先；\n3、熟练使用Maya、3D Max（MotionBuilder等，如需要）3D动画软件；\n4、了解AIGC，能运用相关AI工具来提升动画设计和制作的效率；\n5、热爱游戏或动漫行业，对市面上优秀二次元产品的动作和演出表现有拆解和分析能力；\n6、具备良好的团队协作精神，能够与其他部门同学进行高效的沟通与协作，应聘简历需附带作品。\n\n加分项\n1、有剧情编辑器开发或使用经验；\n2、对绑定有了解和基础制作；\n3、对于当下最新的AI动作演出生产有所了解，并可正向引入到美术与视频制作工艺流中。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7683888783805335861","sourceKey":"bytedance","company":"字节跳动","title":"数码行业运营 - 抖音电商","city":"上海","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7683888783805335861/detail","duty":"团队介绍：抖音电商以“总能发现好东西”为主张，致力于成为用户发现丰富好物的首选平台。众多抖音创作者通过短视频、直播、商城等丰富的形式，给用户提供更个性化、更生动、更高效的消费体验。同时，抖音电商积极引入优质合作伙伴，为商家变现提供多元的选择。\n\n1、结合抖音内容特性，制定运动户外行业在抖音产品内的完整策略，根据行业特性、发展阶段及竞争趋势制定行业策略及商家在字节跳动系内的发展运营策略；\n2、深度理解行业细分市场，负责品类业务规划及商家分层运营，推动品类增长，具备较强的好奇心和快速学习的能力；\n3、了解抖音的短视频和直播流量规律，关注内容电商的玩法；\n4、分析业务数据，归纳问题并落实解决方案，挖掘标杆案例/方法论；\n5、跨部门协同推进项目，整合资源实现业务目标。","requirements":"1、2027届获得本科及以上学历；\n2、数据敏感度好，有行业运营、类目运营、商品运营等实习经验优先，对平台侧商家商品运营有好奇心，有过复杂项目的支持经验；\n3、自我驱动力强，主动学习，有较好的团队合作精神和协同能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7683431514168805685","sourceKey":"bytedance","company":"字节跳动","title":"行业治理策略产品实习生 - TikTok","city":"北京","category":"产品","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7683431514168805685/detail","duty":"团队介绍：TikTok是一个覆盖150个国家和地区的国际短视频平台，我们希望通过TikTok发现真实、有趣的瞬间，让生活更美好。TikTok在全球各地设有办公室，全球总部位于洛杉矶和新加坡，办公地点还包括纽约、伦敦、都柏林、巴黎、柏林、迪拜、雅加达、首尔和东京等多个城市。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、负责平台特定行业/场景的内容案例标注与风险研判，支撑应急响应场景的快速定性，同时为AI模型训练与审核能力提升提供高质量标注数据；\n2、支持特定行业内容生态的风险发现流程建设，日常挖掘/响应风险问题，协助落地治理策略；\n3、参与治理指标的日常监控与根因分析（RCA），基于数据洞察驱动审核标准与治理策略的持续迭代优化；\n4、支持并探索大模型在风险内容识别场景中的应用，参与评测集构建、Prompt调优及模型效果评估。","requirements":"1、本科及以上学历在读；\n2、对内容平台生态治理、内容安全或风险策略方向有兴趣，熟悉内容型社区产品；\n3、具备良好的逻辑分析能力、问题拆解能力和数据分析能力；\n4、具备良好的口头/书面沟通能力（中英双语），富有团队合作精神，责任心强，韧性与自驱力强；\n5、有AI/大模型项目、策略产品运营经验或国际学习经验优先；\n6、每周可保证4-5天到岗，可连续实习3个月及以上。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7680381159226280245","sourceKey":"bytedance","company":"字节跳动","title":"AI产品运营实习生 - 抖音电商","city":"杭州","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7680381159226280245/detail","duty":"团队介绍：抖音电商以“总能发现好东西”为主张，致力于成为用户发现丰富好物的首选平台。众多抖音创作者通过短视频、直播、商城等丰富的形式，给用户提供更个性化、更生动、更高效的消费体验。同时，抖音电商积极引入优质合作伙伴，为商家变现提供多元的选择。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、围绕商家提供的信息，建设可持续迭代的信息与结构化能力，让系统能“理解商家、服务商家、支持后续策略与自动化”；\n2、思考和探索不同商家分型的特征，制定差异化主动诊断与建议能力；不断优化渠道对客呈现的适配性和时效性；\n3、搭建商家的Agent体系，定义商家自助产品的Agent形态、能力边界与演进路径，推动落地可用的产品方案。","requirements":"1、本科及以上学历在读；\n2、具备较强的沟通能力，可顺畅协调内外部沟通；搭建过评测集、案例库（标准/负面案例）、或推动过AI产品的迭代评估体系；\n3、对常见的营销渠道、方式方法有认知，感兴趣，有竞价广告经验或感兴趣同学优先；\n4、对AI热情，积极拥抱新鲜事物，保持好奇心与积极性加分。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7673799813086955829","sourceKey":"bytedance","company":"字节跳动","title":"Agent全栈开发实习生 - 数据平台","city":"北京/南京","category":"前端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7673799813086955829/detail","duty":"团队介绍：数据平台是字节跳动数据中台部门，为公司多业务线（包括抖音、电商、直播和生活服务等）提供一站式大数据解决方案，涵盖数据的生产、清洗、传输、建模、分析等全流程链路，提供数据开发、实验评估、画像标签、增强分析等多元场景解决能力。同时，数据平台部门也致力于把字节跳动积累沉淀的数据中台解决方案做商业化输出，让更多行业能够应用我们的产品能力构建自己的数据中台。在火山引擎上，我们提供了营销增长套件，数据中台等相关产品解决方案，为泛互联网、金融、汽车、新零售等行业提供了行业解决方案。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、参与数据平台前端产品与Agent应用的全栈研发，覆盖Web前端、Node/BFF、服务端接口与Agent Skill，完成分配的模块开发与代码提交；\n2、参与Agent能力及相关服务的建设，建设Prompt Engineering、Workflow、Multi-Agent、Tool Calling等技术方向，承担其中可独立完成的子任务；\n3、结合数据分析、Agent运营分析等业务场景，参与Agent解决方案的原型验证与功能落地；\n4、协助进行日常需求开发、Bug修复与代码优化，配合团队完成迭代节奏；\n5、关注大模型与Agent领域的前沿进展，参与内部技术分享与小范围技术预研。","requirements":"1、本科及以上学历在读，计算机、软件工程等相关专业优先；\n2、每周可到岗4天、连续实习3个月（可长期实习者优先），具备Web前端基础，熟悉HTML、CSS、JavaScript/TypeScript与HTTP协议，了解浏览器渲染与常见性能问题的基本概念；\n3、熟悉常用数据结构与设计模式，掌握Python、Java、Go、Node.js中至少一种服务端语言，能够在指导下完成从前端到接口的小型闭环开发；\n4、学习能力强，喜欢钻研，主动性好，具备良好的团队合作精神和沟通能力，能够按时保质完成导师安排的任务；\n5、有大模型与Agent相关的动手经验优先，如基于大模型API、Agent框架、Prompt/评测等课程项目、开源项目或个人实践。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668622489120688389","sourceKey":"bytedance","company":"字节跳动","title":"豆包大模型Agent算法研究员 - Data AML","city":"上海/北京/深圳/杭州","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668622489120688389/detail","duty":"团队介绍：Data AML是字节跳动的机器学习中台，为抖音/今日头条/西瓜视频等业务提供推荐/广告/CV/语音/NLP的训练和推理系统。为公司内业务部门提供强大的机器学习算力，并在这些业务的问题上研究一些具有通用性和创新性的算法。同时，也通过火山引擎将一些机器学习/推荐系统的核心能力提供给外部企业客户。\n\n1、面向真实生产力场景，探索和提升大模型Agent的核心智能能力，让Agent能够更自主、可靠地完成复杂工作；方向覆盖General Agent、Coding Agent及其交叉场景；\n2、围绕真实高价值任务开展Agent能力优化，包括但不限于：\n1）搜索调研、信息处理、数据分析等复杂知识工作；\n2）代码理解、代码生成与修改、测试、Debug、Repo-level软件工程任务；\n3）跨工具、跨步骤、长程复杂任务中的规划、执行、验证与动态调整；\n3、围绕Agent核心能力和训练方法开展研究与优化，包括但不限于：\n1）Planning、Tool Use、Context Management、Memory、Verification；\n2）指令与格式遵循、事实性与幻觉治理；\n3）Long-horizon Agent、错误恢复与自我纠正；\n4）大规模任务与环境构造、Trajectory生成与筛选；\n5）Reward/Verifier、强化学习、Self-improvement等训练方法；\n4、从真实职业和工作流出发，系统梳理高价值任务，例如研究、数据分析、投资分析、软件开发等，将真实工作转化为可训练、可评测、可规模化的Agent任务与环境；\n5、深入分析Agent的执行轨迹和失败模式，建立从任务与评测、问题定位到数据、训练和系统优化的完整闭环，持续提升Agent在真实任务上的完成能力和泛化能力。","requirements":"1、2027届获得本科及以上学历，专业不限；\n2、扎实的机器学习/强化学习基础，或优秀的软件工程与系统能力，在Agent、强化学习、代码智能或相关方向有深入积累；优秀的代码和工程能力，熟练使用Python，具备良好的系统调试和复杂工程实践能力，能够独立完成数据分析、环境构建、Agent实验、训练、评测和问题定位；出色的问题分析和解决能力，能够从模型表现和真实任务中发现关键问题，形成靠谱的技术判断，并独立推动方案设计、实验验证和最终落地；对AI的实际效用和突破性应用有热情，自驱力强，愿意挑战开放、复杂、没有标准答案的问题，并关注技术最终能否转化为真实可用的Agent能力；\n3、在NeurIPS/ICML/ICLR/ACL/EMNLP等顶级会议发表过相关高质量工作，或主导过有影响力的Agent、模型训练或智能软件系统项目者优先；\n4、在ACM/ICPC、NOI/IOI、Top Coder、Kaggle等算法或编程比赛中取得优秀成绩者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668194099742738693","sourceKey":"bytedance","company":"字节跳动","title":"用户增长产品经理（独立端） - 抖音电商","city":"上海","category":"产品","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668194099742738693/detail","duty":"团队介绍：抖音电商以“总能发现好东西”为主张，致力于成为用户发现丰富好物的首选平台。众多抖音创作者通过短视频、直播、商城等丰富的形式，给用户提供更个性化、更生动、更高效的消费体验。同时，抖音电商积极引入优质合作伙伴，为商家变现提供多元的选择。\n\n1、增长策略设计：深入参与拉新、激活、留存及转化等环节的策略制定，设计包括社交传播、激励体系、渠道承接在内的增长玩法；\n2、数据分析与归因：监控核心指标（如DAU、次日留存、ROI等），建立科学的指标拆解体系，针对波动进行深度异常归因分析，并输出可落地的优化方案；\n3、实验与迭代：负责A/B Testing的全流程管理，从假设推演、方案设计到数据复盘，驱动产品持续快速迭代；\n4、埋点与标准化：负责增长相关业务的埋点需求设计，追求高复用率与标准化的埋点方案，确保数据采集的准确性与合规性；\n5、跨职能协同：与运营、研发、数据分析及市场团队紧密配合，确保增长项目的高质高效落地。","requirements":"1、2027届获得本科及以上学历，专业不限；\n2、具有一线产品实习背景，有增长、策略或电商相关经验者优先，有AI相关项目或实习经验者优先；\n3、具备优秀的逻辑思维与数据分析能力，熟练掌握SQL等工具者加分，能够从海量数据中洞察业务本质；\n4、具备敏锐的用户洞察力，能够运用MECE原则进行复杂的指标拆解与业务分析；\n5、自我驱动力、执行力，沟通顺畅，对电商增长领域充满热情；\n6、熟悉AI技术趋势，具备运用大模型工具（如LLM、AIGC等）提升工作效率及探索业务增长新路径的能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667578387171887365","sourceKey":"bytedance","company":"字节跳动","title":"大模型应用算法工程师 - 抖音电商&直播","city":"北京/上海/杭州","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667578387171887365/detail","duty":"团队介绍：抖音电商算法团队，依托抖音、今日头条、番茄小说、红果短剧等产品，帮助用户发现、讨论并获得好物，享受美好生活；帮助商家高效经营，创建良性商业生态；激励创作并分享购物经验使用心得，构建有真诚有信息的电商内容氛围。在这个团队，我们不仅要通过推荐、广告和搜索算法搭建消费者和商家之间的桥梁，也要通过风控算法和治理算法去甄别违规行为，保护用户的购物体验，保护真正诚信经营的商家；我们还要建设智能客服技术、大规模商品知识图谱来提升各个交易环节的效率，降低商家的经营成本；我们也要结合机器学习和运筹算法，来优化供应链和物流的效率和成本，并进一步提升用户物流体验；另外我们还会用业界先进的数据科学技术为业务健康发展保驾护航。我们的使命：用算法的能力，让用户总能发现好东西，让美好生活触手可得。\n\n抖音直播算法团队，负责抖音、抖音极速版、抖音火山版等App的直播推荐算法优化，业务包括直播体裁基建和直播营收。直播体裁基建从用户侧的召回/粗排/精排/混排等模型和策略和主播侧的冷启动算法，结合多模态内容技术动态理解切片和用户兴趣，建立短视频域到直播域的兴趣迁移，在全场景分发直播体裁，满足用户看播需求并服务于营收、电商、生活服务、游戏等多业务。直播营收致力于为歌唱/舞蹈/弹奏/朗读/情感/户外等广泛的具有一技之长的普通人通过直播这个舞台被更多人看到获得收入，并满足用户多层次的精神消费和情感表达诉求，让优质内容供给持续增长反哺整个直播生态。在推荐技术方面，我们持续验证并落地全链路模型的高效scaling up方案，积极探索生成式推荐和LLM4Rec路线，提升模型系统的整体智能。\n\n1、团队研究大语言模型在各个电商场景的应用，包括文本、视频创作、智能对话、Agent、生成式推荐等领域的全新探索和应用，以提升达人和商家的效率；\n2、运用SFT、RLHF等大模型技术优化内容生成，包括且不限于商品讲解、直播间互动、视频脚本、商品卖点等内容创作场景；\n3、基于语言或多模态大模型，实现文本、短视频和直播切片的理解和推荐；\n4、探索和搭建电商场景下的各类Agent应用，如评论自动回复、智能选品、电商流量分析等；\n5、持续跟进大模型领域的研究成果，将前沿技术应用到抖音电商生态中，不断提升平台的智能化水平。","requirements":"1、2027届获得本科及以上学历，计算机相关专业；\n2、精通编程与算法，具备扎实的数据结构与算法功底，熟练掌握至少一种编程语言，ACM/ICPC、NOI/IOI、Top Coder、Kaggle等比赛获奖者优先；\n3、深入理解语言或多模态大模型，具备SFT、RLHF等研发经验；\n4、在大模型领域，主导过大影响力的项目或论文者优先，在ACL/EMNLP/ECCV/CVPR等顶会发表论文者优先；\n5、有强化学习结合大模型落地经验，有文案生成、创意生成、素材编辑、AI特效等有相关经验优先；\n6、良好的沟通协作能力，能和团队一起探索新技术，推动技术进步；优秀的心理素质与应变能力，面对困难勇于迎接挑战。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667507513423677749","sourceKey":"bytedance","company":"字节跳动","title":"AI产品经理（数据方向） - 数据平台","city":"北京/上海/杭州","category":"产品经理","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667507513423677749/detail","duty":"团队介绍：数据平台是字节跳动数据中台部门，为公司多业务线（包括抖音、电商、直播和生活服务等）提供一站式大数据解决方案，涵盖数据的生产、清洗、传输、建模、分析等全流程链路，提供数据开发、实验评估、画像标签、增强分析等多元场景解决能力。同时，数据平台部门也致力于把字节跳动积累沉淀的数据中台解决方案做商业化输出，让更多行业能够应用我们的产品能力构建自己的数据中台。在火山引擎上，我们提供了营销增长套件，数据中台等相关产品解决方案，为泛互联网、金融、汽车、新零售等行业提供了行业解决方案。\n\n1、参与AI时代数据应用产品的产品设计相关工作，包括对内业务支持，产品规划迭代，ToB客户调研等；\n2、参与产品模块产品规划，用户调研的部分执行工作，协助进行资源协调和项目推进的部分基础事务；\n3、关注业内先进AI产品的动态，对AI方向的数据分析、效果评估有一定理解，独立负责分析全球产品及先进方向的演进迭代研究。","requirements":"1、2027届获得本科及以上学历；\n2、较强的责任心和主动学习的态度，有快速成长的意愿；\n3、对LLM或者数据相关创新方向有兴趣，有一定了解者优先；\n4、有一定的沟通和组织能力，能够协助建立产品与用户之间的初步联系，协助推动团队内的简单工作沟通；\n5、对数据有一定敏感度，有基本的业务意识和场景理解能力，具备一定的学习和总结能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667172332508006709","sourceKey":"bytedance","company":"字节跳动","title":"AI产品经理（即梦用户增长方向） - 剪映CapCut","city":"北京","category":"产品","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667172332508006709/detail","duty":"团队介绍：剪映CapCut团队成立七年，先后孵化了剪映、CapCut、醒图、Hypic、即梦、Dreamina、Pippit等产品，覆盖视频、图片、Al生成、视频营销等多领域，打造与AI结合的全球化产品矩阵。\n我们的愿景是：激发想象力，成为全球领先的互动内容平台，创造独特的体验和价值。\n我们期待你的加入，一同极致打磨用户体验,构建创意生态和商业化能力，定义AI与创作结合的无限可能，让内容互动更简单、更精彩!\n\n1、负责即梦/Dreamina产品增长体系建设，包括用户拉新、促活等，对DAU负责；\n2、理解用户使用AI工具创作的场景和意图，识别用户拉新转化和留存的关键问题，并设计对应产品方案提升拉新和留存效率；\n3、优化产品逻辑和算法策略，根据用户生命周期建立长效的拉新促活机制，其手段包括但不限于内部导量、外部换量、分享回流、Push推送通知、桌面小部件等等；\n4、协同业务、运营、市场、数据、研发等跨部门团队，推进项目落地并对增长结果负责。","requirements":"1、2027届获得本科及以上学历；\n2、相关工作经验，有国际化、增长策略、GTM策略等优先，对剪辑创作行业有热情，拥有AI新机会，具备系统化思考问题的习惯，并且韧性强，可以带领团队开阔新方向，从0-1突破关键方向；\n3、熟悉增长方法论，有较强的综合决策能力，能够高质量的完成目标拆解和优先级判断；\n4、目标导向，具备较好沟通能力，能独立协同项目相关方推进项目落地并拿到结果，能够快速适应变化；\n5、具备英语听说读写能力，对国际化特别是美国市场有实战或者深入认知者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667129902848411957","sourceKey":"bytedance","company":"字节跳动","title":"AI内容运营经理 - 剪映CapCut","city":"北京","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667129902848411957/detail","duty":"团队介绍：剪映CapCut团队成立七年，先后孵化了剪映、CapCut、醒图、Hypic、即梦、Dreamina、Pippit等产品，覆盖视频、图片、Al生成、视频营销等多领域，打造与AI结合的全球化产品矩阵。\n我们的愿景是：激发想象力，成为全球领先的互动内容平台，创造独特的体验和价值。\n我们期待你的加入，一同极致打磨用户体验,构建创意生态和商业化能力，定义AI与创作结合的无限可能，让内容互动更简单、更精彩!\n\n1、负责AI视频创作产品的内容生态建设与供给保障，通过创新的运营手段驱动用户增长与产品渗透率提升；\n2、围绕业务目标与用户需求，参与内容方向策划、运营机制设计及重点项目推进，支持多元内容形态的探索与落地；\n3、对于社媒热点和内容创作趋势敏感，能够策划和打造具有传播影响力的内容案例展示，实现品牌声量放大；\n4、面向不同类型的创作者、合作机构与生态伙伴，理解其特征与诉求，制定有针对性的运营策略、活动方案及合作路径，并推动执行闭环；\n5、紧密追踪全球AI及内容行业的市场前沿动态，对大模型应用及创新工具具备深刻理解与敏锐洞见，有相关实战探索经验者最佳。","requirements":"1、2027届获得本科及以上学历；\n2、具备极佳的“网感”，拥有出色的内容敏锐度与宣发直觉，能精准洞察用户发布动机与大众传播规律；具备优秀的数据敏感度与体系化拆解能力，能以结果为导向对策略进行持续追踪与迭代调优，并对最终业务目标负责；具备自驱力与责任心，拥有优秀的跨团队沟通与整合能力，能够在复杂的业务环境中破局并推动问题解决；具备较强学习能力与自驱力，对未知领域保持好奇，愿意在不确定性中探索解法，并在挑战中持续成长；\n3、拥抱前沿技术，对AI充满热情与好奇心，熟练且善于利用各类AI工具赋能日常工作，具备通过AI手段大幅提升策略产出与落地效率的实战经验优先；\n4、英语可作为工作语言。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667083864120002869","sourceKey":"bytedance","company":"字节跳动","title":"AI产品经理 - 数据平台","city":"北京/上海/深圳/杭州","category":"产品经理","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667083864120002869/detail","duty":"团队介绍：数据平台是字节跳动数据中台部门，为公司多业务线（包括抖音、电商、直播和生活服务等）提供一站式大数据解决方案，涵盖数据的生产、清洗、传输、建模、分析等全流程链路，提供数据开发、实验评估、画像标签、增强分析等多元场景解决能力。同时，数据平台部门也致力于把字节跳动积累沉淀的数据中台解决方案做商业化输出，让更多行业能够应用我们的产品能力构建自己的数据中台。在火山引擎上，我们提供了营销增长套件，数据中台等相关产品解决方案，为泛互联网、金融、汽车、新零售等行业提供了行业解决方案。\n\n1、参与数据智能体、营销智能体、Agent知识库、Agent评测分析在内的多个数据大模型产品设计，协助打造企业级超级Agent平台，支持好字节跳动自身业务发展以及To B商业化售卖；\n2、参与平台级产品的架构与功能设计，支持创新性平台从0到1的探索、构建与落地推广；\n3、协同技术、运营、交付、售前等团队推进产品在业务中的落地应用和客户价值的持续提升。","requirements":"1、2027届获得本科及以上学历；\n2、具备AI需求洞察能力，能够从业务场景中识别高价值AI机会，并通过合理方案解决用户核心痛点；具备快速原型验证能力，熟悉主流大模型能力，能通过调研分析、Demo、Prompt、Vibe coding快速验证想法；\n3、具备强烈的负责人意识、优秀的跨团队协作能力，能与算法、研发、设计、运营、售前高效协作，推动AI需求从方案设计到上线推广的完整流程，为收入、用户数等业务核心指标负责，自我驱动，结果导向；\n4、持续学习，主动关注大模型、Agent、大数据等技术进展，对于产品方向、行业趋势、市场机会有洞察力，能主动挖掘业务增长方向。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7666325865526102325","sourceKey":"bytedance","company":"字节跳动","title":"数据库开发工程师 - AI算力基础设施","city":"上海","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7666325865526102325/detail","duty":"团队介绍：字节跳动基础设施部门，负责字节跳动的全栈算力基础设施，从芯片服务器产研、到超大规模数据中心，到传统云平台和如今的AI Native Cloud，全方位为抖音、豆包、今日头条、飞书、火山引擎等各类产品提供领先、稳定的百万量级大规模算力基础设施服务。我们的领域涵盖数据中心建设、内核操作系统开发、服务器集群管理、高速网络通信、EB级数据存储体系、搜索型数据库探索、基于LLM的AI基础设施的研发调度与治理等，致力于打造业界领先的、面向LLM的AI云原生基础设施架构与产品矩阵。\n\n1、参与AI时代的数据库产品研发与架构设计，包括但不限于：Mem0、Agent RAG、Serverless PG、ContextSearch、Supabase、Lakebase等；\n2、参与AI数据库前沿技术探索，包括但不限于：Multi-Agent/Agentic RAG/DeepResearch前沿研究（LLM×检索)、向量检索算法研究（算法×系统×硬件协同)、多模态查询处理、基于AI Agent工作流的基础设施自动优化等；\n3、参与数据库智能策略研发：基于AI的数据库性能调优系统，包括自动索引推荐、查询计划优化、资源分配策略等；构建智能监控系统，实现异常检测、根因分析、容量预测等AIOps能力；\n4、参与AI与数据库结合的实践方案探索与落地：探索AI技术和数据库各产品结合的最佳实践方案并落地，服务超大规模的集团内部业务及火山引擎业务。","requirements":"1、2027届获得本科及以上学历，计算机、数据科学、人工智能相关专业；\n2、熟悉Go/Java/Python/C++语言中的一种，对代码质量有追求；\n3、掌握扎实的计算机基础知识，深入理解数据结构、算法和操作系统知识；\n4、有优秀的逻辑分析能力，能够对业务逻辑进行合理的抽象和拆分。\n\n加分项：\n1、了解AI领域的基本概念和常用算法，在数据库、信息检索、机器学习或人工智能系统相关领域有高质量论文、开源影响力或代表性技术成果；\n2、有Agent Memory、用户画像、搜广推特征平台、知识库等相关研究或工程经验；\n3、有AI Agent、研发AI工作流等相关实践经验；\n4、具备SQL引擎扩展开发经验，如自定义UDF/存储过程集成AI模型；\n5、参与过AI4DB或DB4AI类开源项目，如Apache MADlib、Mem0、MemOS、MemU。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7664511141422893365","sourceKey":"bytedance","company":"字节跳动","title":"后端开发工程师（Agent/LLM） - 抖音用户产品","city":"北京/上海","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7664511141422893365/detail","duty":"团队介绍：抖音用户产品研发团队为抖音全业务提供研发支持与底层技术能力，是驱动业务持续进化的重要工程力量之一。团队围绕首页、推荐、搜索、图文、中长视频、AI 创作、相机、账号及社交通讯等核心场景，承担从客户端、服务端到 AI 工程链路的端到端建设，在亿级 DAU 的真实流量下，持续攻坚极致体验与前沿 AI 系统的工程命题。\n我们相信，AI 正在重塑产品的底层架构。团队依托大模型与多模态技术、Multi-Agent 系统工程、在线推理与评测基础设施，面向下一代 AI 原生应用持续投入：在社交与通讯场景，探索长期记忆、多模态理解与人格化对话的技术边界，构建真正能陪伴用户的 AI 交互系统；在内容与创作场景，建设面向亿级创作者的多模态生成与可控创作引擎，让 AI 成为创作者的表达延伸；在搜索与信息获取场景，探索生成式检索、Agentic Search 与个性化推理的新一代系统架构，重新定义 \"人与信息\" 的连接方式。\n这里有工业界领先规模的真实流量，有最前沿的 AI 工程命题，也有一群把技术做到极致的同行者。诚邀热爱技术、追求极致、渴望在真实世界解决硬核问题的你加入我们，一起在 Agent 驱动的技术浪潮中，构建支撑大规模用户的新一代产品。\n\n1、负责抖音搜索和AI抖音等后端开发工作，包括搜索产品功能迭代、服务端架构设计、链路优化和用户体验提升；\n2、参与搜索场景下的大模型应用探索与落地，通过PE工程、RAG、模型调用链路设计、效果评估、后训练等方式，将LLM能力应用于搜索业务场景，提升搜索产品体验；\n3、参与搜索Agent能力建设，围绕多轮对话、任务拆解、工具调用、Workflow编排、上下文管理等方向，支持面向具体搜索业务需求的Agent应用开发与效果优化；\n4、参与AI工程提效方向建设，结合研发流程中的编码、测试、评估、配置、问题诊断等场景，探索并落地AI Coding、自动化分析、智能辅助决策等能力，提升团队研发效率。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程、通信、电子信息、人工智能等相关专业优先；\n2、具备扎实的计算机基础，熟悉数据结构、算法、操作系统、计算机网络等基础知识；\n3、熟练掌握至少一门编程语言，包括但不限于C/C++、Python、Go、Java，具备良好的编码习惯和工程实现能力；\n4、具备优秀的逻辑分析能力，能够对复杂业务问题进行合理抽象、拆解和建模，并推动方案落地；\n5、对LLM/Agent技术有浓厚兴趣，了解大模型应用开发的基本范式，如PE工程、RAG、Function Calling、Workflow编排等；\n6、有LLM应用开发、AI Agent、搜索系统、服务端工程等相关项目经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7652019433997453573","sourceKey":"bytedance","company":"字节跳动","title":"Agent研发实习生-AI创新业务","city":"北京","category":"后端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7652019433997453573/detail","duty":"日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n团队介绍：字节跳动内部创新业务团队，专注研究新技术赛道相关领域产品，落地AI智能化创新。\n\n1、参与Auto Research相关Agent Workflow的设计与开发，探索科研自动化场景中的Agent应用；\n2、参与搜索、文献阅读、代码生成、实验执行、结果分析等Agent能力的验证与集成；\n3、基于现有Agent Framework搭建和迭代原型系统，验证不同技术方案的效果与可行性；\n4、参与Agent Tool、Memory、Evaluation等模块的开发与测试，协助完善平台能力；\n5、跟踪Agent、Auto Research领域的最新进展，调研开源项目和前沿技术，并完成技术验证与分享。","requirements":"1、硕士及以上学位在读，计算机、人工智能、软件工程等相关专业；\n2、熟练掌握Python，具备良好的编程基础和代码阅读能力；\n3、了解LLM、Agent、RAG、Tool Calling等相关技术，对Agent方向有浓厚兴趣；\n4、具备较强的学习能力和动手能力，能够快速理解并使用新工具和新框架；\n5、具备良好的沟通能力和团队协作意识。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7647096753016506677","sourceKey":"bytedance","company":"字节跳动","title":"智能客服算法实习生-TikTok","city":"北京","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7647096753016506677/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：TikTok研发团队，旨在实现TikTok业务的研发工作，搭建及维护业界领先的产品。加入我们，你能接触到包括用户增长、社交、直播、搜索、本地生活、内容创造、内容消费等核心业务场景，支持产品在全球赛道上高速发展；也能接触到包括服务架构、基础技术等方向上的技术挑战，保障业务持续高质量、高效率、且安全地为用户服务；同时还能为不同业务场景提供全面的技术解决方案，优化各项产品指标及用户体验。\n在这里，有大牛带队与大家一同不断探索前沿，突破想象空间。在这里，你的每一行代码都将服务亿万用户。在这里，团队专业且纯粹，合作氛围平等且轻松。目前在北京，上海，杭州、广州、深圳分别开放多个岗位机会。\n\n1、深入智能客服业务，承担智能对话、问答系统的算法研究、数据构建、模型训练与评测等工作；\n2、参与海量客服对话数据的清洗、挖掘与分析，协助构建和优化高质量的模型训练数据集；\n3、参与大模型在客服业务场景的通用推理能力，使智能客服系统能够更准确的理解用户、更自然流畅的交互；\n4、跟进NLP及大模型（LLM/MLLM）领域的最新学术进展与应用技术，并结合业务进行落地。","requirements":"1、2027届本科及以上学历在读，计算机、人工智能、数学等相关专业优先；\n2、编程能力扎实，熟悉Python，有良好的数据结构和算法基础；\n3、有机器学习与深度学习基础，了解Transformer、BERT、GPT等主流模型结构及原理；\n4、有强烈的技术好奇心、自驱力和进取心，能及时关注和学习业界实践。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7637725670112446725","sourceKey":"bytedance","company":"字节跳动","title":"推荐算法实习生-抖音直播","city":"上海","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7637725670112446725/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：团队负责抖音、抖音极速版、抖音火山版等App的直播体裁基建和直播营收业务，直播体裁基建立足对边生产边分发时效性高的直播体裁的理解，结合多模态信号理解动态的时间切片和长尾兴趣点，建立短视频域到直播域的兴趣迁移，在全场景分发直播体裁，满足用户看播需求并服务于营收、电商、生活服务、游戏等多业务。直播营收致力于为歌唱/舞蹈/弹奏/朗读/情感/户外等广泛的具有一技之长的普通人通过直播这个舞台被更多人看到获得收入，并满足用户多层次的精神消费和情感表达诉求，让优质内容供给持续增长反哺整个直播生态。\n\n1、参与快速增长的直播业务的推荐算法工作，包含抖音、抖音极速版、抖音火山版、抖音PC版等各端直播业务，结合超大规模机器学习系统，构建业界一流领先的推荐系统；\n2、优化直播在多场景、全链路的推荐核心算法&策略(召回、粗排、精排、混排等)，极致提升个性化直播分发与推荐效率；\n3、深入理解用户、主播、平台等生态角色需求，通过持续技术创新与迭代，驱动用户体验、主播成长、平台营收健康持续增长，并通过直播+赋能优化各垂直行业；\n4、和产品、运营团队紧密合作，通过对产品和用户的深入理解和分析，制定算法策略促进直播生态的长期繁荣发展。","requirements":"1、2027届硕士及以上学位在读，计算机/软件/人工智能/数学等相关专业的优先；\n2、有扎实的编程基础、算法功底、良好的编程风格和工作习惯；\n3、有扎实的机器学习/深度学习理论和丰富的实践经验，熟悉至少一种主流深度学习编程框架；\n4、对数据敏感，有优秀的分析问题和解决问题的能力，对解决具有挑战性问题充满激情；\n5、工作积极主动，做事情认真细致；\n6、在会议中发表过论文，或ACM/机器学习等竞赛获奖，或有大规模推荐系统、计算广告、搜索引擎等算法业务经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7628623984851552517","sourceKey":"bytedance","company":"字节跳动","title":"大模型驱动的内容生产与分发：IP跨体裁生成与LLM推荐 - 番茄","city":"上海/杭州/北京/深圳","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7628623984851552517/detail","duty":"团队介绍：Data-番茄团队，负责字节跳动下番茄小说、红果短剧、番茄畅听、国际化短剧等产品的推荐算法和AI相关工作。我们的工作包括优化业界前沿的大规模推荐系统，探索LLM与推荐的结合，并落地生成式推荐范式，从小说、短剧、音频、音乐等内容方向建设完整的内容生态和AI能力，保持业务规模保持超高速增长。\n\n课题介绍：\n番茄系聚合海量故事IP，今日头条拥有丰富内容形态，但生产与分发仍面临改编链路长、成本高，以及推荐过度依赖稀疏ID、对新内容/低活用户不友好等问题。本课题以多模态大模型为底座：在番茄通过LLM创作提效与结构化内容理解，构建IP资产并打通“小说→剧本→分镜→动态漫/短剧/音频”的生成与辅助创作；在小说、短剧、今日头条把内容理解信号融入推荐建模，提升兴趣捕捉与可解释分发，最终实现生产与分发协同提升。\n1、大模型推荐和推荐Agent：引入LLM的推理能力，以Seed为基础训练大模型执行推荐任务的能力，推荐Token和自然语言Token联合训练实现模态融合，让推荐系统具备理解自然语言的能力，从而用推荐Agent方式实现更具扩展性的分发交互体验\n2、突出强调利用大模型COT的推理能力，改进被动推荐效果\n3、遵循用户的正向、负向指令的能力，彻底解决用户反馈中“Dislike不生效”、新用户兴趣探索、用户调控推荐画风等难题\n4、在产品中提供和用户进行对话交互的能力，用户可根据自身需求调整推荐的效果\n5、消息推送系统中嵌入大模型的用户-内容推理匹配能力，追求在内容零展、低展的情况下精准、快速的推送给用户，实现极高的推送时效性\n6、构建基于大模型的推荐Agent能力，让大模型能和目前推荐系统业务策略和逻辑能更好的融合和调用\n\n课题挑战：\n1、跨体裁一致性与可控生成；\n2、结构化理解准确可复用；\n3、模型落地成本/时延/轻量化；\n4、LLM与内容的对齐、解码方案探索，包括纯文本方案或基于SID的方案；\n5、LLM推荐指令COT数据集构建和个性化推荐推理能力的训练方法探索；\n6、用户推荐正向、负向指令理解和线上执行能力探索；\n7、推荐系统能力模块化&工具化，推荐Agent设计。\n\n课题价值：\n1、提效降本，提升IP产能与变现；\n2、增强推荐效果与可解释性；\n3、沉淀多模态通用底座；\n4、探索基于LLM推理能力的推荐范式。","requirements":"1、2027届毕业，获得博士学位，计算机、软件、人工智能、数学等相关专业优先；\n2、扎实的机器学习基础，深入理解多模态理解及生成、推荐广告等相关技术，具备良好的数理基础和自学能力；\n3、熟练掌握相关机器学习框架和工程框架，具备扎实的编码能力；\n4、在多模态大模型领域有相关经验，尤其在长文本、影视剧领域有经验者优先；\n5、在计算机科学高水平会议和期刊（如NIPS、ICML、CVPR、ICCV、ECCV、IJCAI、AAAI、KDD、SIGIR、WWW、ACL、PAMI、IJCV等）发表过论文或具备竞赛经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7628573292417124661","sourceKey":"bytedance","company":"字节跳动","title":"基于多模态大模型的视频分析/理解/画质评估及增强与视频智能编码/表达-音视频技术（杭州）","city":"杭州","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7628573292417124661/detail","duty":"团队介绍：视频与边缘部门承载了字节跳动的媒体内容分发基建及技术中台，支持了字节跳动全系产品，如抖音、今日头条、番茄小说、西瓜视频等APP的点播、直播、实时通信、图片等多媒体业务发展，同时将业务发展过程中沉淀下来的技术能力和工具，通过火山引擎对外输出，面向各行各业用户提供视频云产品和服务，愿景是为内外部业务伙伴提供最低成本、最优画质、最低延时、最安全可靠的富媒体内容分发解决方案，助力业务伙伴降本提效实现持续增长。\n\n课题介绍：\n随着4K、HDR等技术成为主流标准，消费者对视频画质的要求日益提升。然而，视频在拍摄、传输和压缩过程中，画质往往受损，影响观看体验。多模态大模型的出现为视频分析、理解、画质评估、及画质增强提供了新的可能性，因此希望能够探索多模态大模型在多媒体场景的应用可行性，发掘基座大模型在大规模业务视频内容应用的潜力，建立业内领先的多媒体场景的多模态大模型解决方案。\n1、画质分析以及人眼感知：利用多模态大模型，深入分析视频内容及画质退化问题，研究人眼对色彩、帧率、清晰度等画质维度的感知能力，从而使得画质评估更为准确，画质增强对退化的处理更为智能，增强的结果更符合人眼主观；\n2、生成式画质增强：利用生成式大模型的先验信息，大幅提升画质增强的效果天花板，并且解决生成伪像、生成保真度、生成稳定性等当前生成式算法存在的问题；\n3、视频时域任务：研究画质理解和增强在视频上的拓展，包括时域信息表征建模，时域退化理解，时域画质增强连续性，时域推理加速等；\n4、用户视角的验证：在大规模用户环境中，从用户的实际观看体验出发，验证画质增强算法的有效性和用户满意度；\n5、视频智能编码及表达：近年来，深度学习在视频及图像压缩领域逐渐成为研究热点。随着传统编码标准逐渐逼近性能瓶颈，深度学习方法受到了业界的高度重视，发展极为迅速。目前在部分场景下深度学习方法已经可以接近甚至超过H.266/VVC的压缩效率。然后相对传统编码，深度学习方法也面临着诸多挑战，例如在很多应用场景下的压缩效率依然落后于传统编码技术，运算复杂度高，跨平台编解码缺乏兼容性，难以标准化等等。此外，如何将传统编码算法和深度学习算法在统一的硬件架构下实现，并达到极致的算力利用效率，涉及到算法和硬件架构创新，是研究的难点。\n\n课题挑战：\n基于多模态大模型的分析/理解/画质评估和增强面临如下挑战：\n1、多模态长视频复杂时序关系建模；\n2、少样本grounding-based理解画质评估模型；\n3、可交互/用户偏好对齐的视频处理/增强模型。\n\n视频智能编码及表达面临如下挑战：\n1、如何实现压缩效率显著超越传统编码器；\n2、如何满足可接受的复杂度及功耗要求；\n3、如何保证跨平台编解码一致性；\n4、如何高效压缩token等新兴智能信息；\n5、如何有效表达语义信息。\n\n课题价值：\n基于多模态大模型的分析/理解/画质评估和增强的研究价值：\n1、提升中长视频语义理解与事件定位能力及处理效率，支撑广告推荐、内容理解、视频价值评估和转码增强等核心业务；\n2、降低画质标注成本，实现局部退化可解释评估，提升跨内容泛化能力，支持像素级画质质检与优化。\n\n视频智能编码及表达的研究价值：\n1、传统视频编码技术逐渐接近其能力极限，视频的智能编码技术有希望突破该极限，实现前所未有的视频压缩效率；\n2、在新的应用场景中，Token等新兴智能信息将占据显著带宽。对新兴智能信息的压缩将显著提高传输与存储效率；\n3、高效视频智能编码及表达一旦实现标准化，将在市场中占据有利位置，有巨大潜在专利价值；\n4、高效视频智能编码及表达有可能明显节省带宽及存储，直接创造经济收益。","requirements":"1、2027届毕业，获得博士学位，人工智能、计算机、通信等相关专业优先；\n2、优秀的代码能力、数据结构和基础算法功底或芯片架构设计；\n3、在TPAMI/CVPR/NeurIPS/ICCV等顶级期刊会议上发表论文者优先；\n4、有向标准组织提出过提案并有标准会议的经验者优先；\n5、出色的问题分析和解决能力，有自主探索解决方案的能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7628528202775922997","sourceKey":"bytedance","company":"字节跳动","title":"面向国际电商场景的大模型应用-国际电商（北京）","city":"北京","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7628528202775922997/detail","duty":"团队介绍：国际电商是以TikTok为载体的电商业务（也称为TikTok Shop），致力于成为用户发现并获取优价好物的首选平台，在直播电商、视频内容电商、货架电商等多场景下，国际电商希望能为用户提供更个性化、更主动、更高效的消费体验，为商家提供稳定可靠的平台服务，致力于新奇好物畅销全球，美好生活触手可得的使命。\nData-电商团队是国际电商的核心算法技术力量，专注于电商领域的算法创新，帮助用户高效发现感兴趣的商品，保障用户的购物安全，提升交易各环节的智能化水平。在这里，你将与一流的产品和技术团队合作、钻研，一起应对技术和业务上的挑战，推动技术在电商场景的深度落地。\n\n课题介绍：\n国际电商生态中沉淀了用户行为、商品图文、多媒体内容、商品销量与物流时序等海量异构数据，但传统模型在长周期预测、跨模态理解及复杂决策推理上仍存在明显瓶颈。\n本课题拟以大模型为基础，联合构建面向国际电商场景的基础大模型，将用户、商品、内容、物流与库存等关键信息统一建模，并在其之上设计可插拔的Agent框架，系统整合任务规划、工具调用、多轮交互与环境感知等能力，从而在需求预测、流量分发与个性化推荐等链路中实现端到端的智能决策。\n\n课题挑战：\n1、异构融合与对齐：统一建模用户行为序列、商品销量时序信号与多模态商品内容，完成高维时序与图文表征的深度语义对齐；\n2、推荐大模型与世界模型协同：把推荐问题定义还原为用户推荐列表的生成问题，基于大模型的技术完成端到端推荐建模；\n3、推荐物品的Tokenizor：如何把亿级别的物品进行多模态和特征语义编码，支撑后续训练和生成任务，处理几十TB级别的用户行为Tokens的预训练，通过模型结构和训练方式拉高Scaling Law曲线，把各类推荐任务重构为后训练任务，以RLVR的思路进行推荐任务建模，最大化GMV和体验价值，训练推理优化，基于SGLang 等大模型推理套件定制构建高性能的推荐服务；\n4、电商多模态大模型：构建面向电商领域的多语言多模态大模型，在核心电商场景达到SOTA性能，并以此为基础打造电商智能体基座，广泛支撑各类电商场景下的Agent应用落地；\n5、Agent评测与安全合规：构建贴合实际业务的Agent评测指标与基准，保障在强约束、强对抗环境下的稳定性、安全性与合规性。\n\n课题价值：\n1、技术价值：打造通用多模态基座，以模型、数据、算力迭代实现幂律增长，夯实规模化技术底座；\n2、业务价值：搭建国际电商大模型底座，以生成式推荐、时序大模型、Agent等驱动GMV与留存，打造高杠杆营收引擎。","requirements":"1、2027届毕业，获得博士学位，计算机等相关专业优先；\n2、扎实的机器学习技术基础，了解前沿的AI技术，发表过高水平学术会议论文或有竞赛经验；\n3、熟悉大数据相关框架和应用Hadoop、MapReduce/Spark等；\n4、熟悉TensorFlow/PyTorch模型的训练和部署，了解混合精度训练、分布式训练等训练加速方法；\n5、了解模型压缩&推理加速的研究和技术进展，包括但不限于模型量化、剪枝、蒸馏、TensorRT推理优化等；\n6、熟悉以下任一方向的技术：\n1）CV&多模态：在多媒体和计算机视觉某个领域有较深入的研究，包括但不限于：图像搜索、图像/视频分类和识别、图像分割、目标检测、OCR、图神经网络、多模态、无监督和自监督学习等；有CV/多模态大模型相关项目经验，研发&优化电商视频&商品多模态大模型，结合LLM和视频/商品表征，支持视频多模态分类，视频QA，跨模态检索，商品分类等任务，显著超越线上模型；有较强的实践能力，在Kaggle，COCO，ImageNet，ActivityNet，ICPC等比赛获奖；熟悉前沿工作，在顶级学术会议（如CVPR、ICCV、ECCV等）发表论文；\n2）自然语言处理（NLP）：NLP方向上有较深入的研究，包括但不限于：预训练技术，自然语言理解，多语言&跨语言学习，自然语言生成，迁移学习，半监督学习等；有LLM大模型相关项目经验；研发NLP大模型，以统一电商场景的NLP任务，落地电商业务场景；有较强的实践能力，在Kaggle，GLUE，Super GLUE，CLUE等比赛获奖；熟悉前沿工作，在顶级学术会议（如ACL、EMNLP等）发表论文。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7603634578615994629","sourceKey":"bytedance","company":"字节跳动","title":"机器人热仿真工程实习生 - Seed Model","city":"北京","category":"硬件","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7603634578615994629/detail","duty":"团队介绍：字节跳动 Seed 团队成立于 2023 年，致力于寻找通用智能的新方法，追求智能上限，为科技和社会发展作出贡献。\n\nSeed 团队在 AI 领域拥有长期愿景与决心，团队研究方向涵盖 MLLM、GenMedia、AI for Science、机器人等，在中国、新加坡、美国等地设有实验室和岗位。目前，团队已推出业界领先的通用大模型以及前沿的多模态能力，支持豆包、即梦、TRAE 等超过 50 个应用场景，并通过火山引擎开放给企业客户。第三方数据显示，豆包 App 用户量在中国市场排名第一，豆包大模型日均 Token 调用量行业领先。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、参与机器人核心部件（电机、控制器、电池、传感器等）热设计方案的讨论与设计；\n2、参与完成热仿真分析工作，运用ICEPAK、Fluent等仿真工具，协助搭建仿真模型、设置参数、分析仿真结果，并整理仿真报告；\n3、开展热性能测试，准备测试样品、搭建测试环境，记录测试数据，整理测试报告，优化热设计方案；\n4、关注机器人热设计行业的前沿技术，收集相关技术资料，协助团队完成技术调研和方案迭代。","requirements":"1、本科及以上学历在读，工程热物理、能源与动力工程、新能源科学与工程、机械设计制造及其自动化、航空航天工程、飞行器动力工程、电子与机械工程等相关专业优先；\n2、掌握传热原理，具备基础的热力学、流体力学知识，对热设计有一定的兴趣和认知；\n3、具备较强的软件应用能力，熟练掌握Fluent、ICEPAK等流、热仿真软件，能够使用Creo、SolidWorks等绘图工具，掌握MATLAB、Python等编程语言，具备良好的数据处理和分析能力；\n4、有机器人、换热器、电子设备热设计相关竞赛或项目经验，具备计算传热学编程能力，或在《Journal of Fluid Mechanics》《International Communications in Heat and Mass Transfer》等流体、传热领域期刊发表论文者优先；\n5、可实习5个月及以上。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7685652943334279429","sourceKey":"bytedance","company":"字节跳动","title":"居家生活行业经营分析 - 抖音电商","city":"上海","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7685652943334279429/detail","duty":"团队介绍：抖音电商以“总能发现好东西”为主张，致力于成为用户发现丰富好物的首选平台。众多抖音创作者通过短视频、直播、商城等丰富的形式，给用户提供更个性化、更生动、更高效的消费体验。同时，抖音电商积极引入优质合作伙伴，为商家变现提供多元的选择。\n\n1、基于业务场景，深度理解数据生产链路，掌握数据获取和数据分析能力；\n2、负责业务指标的定义、口径对齐等工作，参与指标体系建设，协助数据监控看板建设，提升数据化运营效率；\n3、负责业务经营诊断，基于目标达成做好归因和风险预警，包括但不限于周会/月会等场景提供数据支持和决策分析；\n4、协助策略团队展开策略效果研究、增长机会洞察等工作，协同完成策略迭代、落地和效果评估，建立数据和策略的正向循环，牵引策略带来业务增长；\n5、开展市场、竞争分析、产业政策研究等工作，为业务规划提供决策依据。","requirements":"1、2027届获得本科及以上学历，统计学、应用数学、计算机等理工科专业优先；\n2、对数据敏感，有较强的数据分析、数据整理能力，熟练使用SQL、Python等，有互联网数据分析、经营分析、商业分析实习经验优先；\n3、拥有较强的逻辑思维能力、自驱力和主动性，良好的团队沟通和合作能力，喜欢挑战性工作，工作激情饱满。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7684095945077016885","sourceKey":"bytedance","company":"字节跳动","title":"商机产品（商品增长）实习生 - 抖音电商","city":"上海","category":"产品","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7684095945077016885/detail","duty":"团队介绍：抖音电商以“总能发现好东西”为主张，致力于成为用户发现丰富好物的首选平台。众多抖音创作者通过短视频、直播、商城等丰富的形式，给用户提供更个性化、更生动、更高效的消费体验。同时，抖音电商积极引入优质合作伙伴，为商家变现提供多元的选择。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、参与抖音电商商机中心相关To B产品建设，围绕商品供给增长、商家经营效率提升等方向，支持产品需求分析、方案设计与功能落地；\n2、协助业务和运营团队梳理商品供给增长链路，参与商家端产品能力、策略机制、运营工具的设计与优化；\n3、参与商机识别、策略调度、数据追踪、效果归因等工作，支持业务团队提升招品策略的有效性和执行效率；\n4、基于数据分析发现业务问题，协助完成数据看板、分析报告、案例复盘等工作，为产品迭代和策略优化提供依据；\n5、参与供给提升AI链路建设，协助梳理业务场景、沉淀产品需求，支持Skill平台相关能力的搭建与优化，提升电商供给丰富度和竞争力。","requirements":"1、本科及以上学历在读，专业不限，数据分析、统计学、计算机、信息管理、经济学、电子商务、市场营销等相关背景优先；\n2、对电商业务、商家经营、商品供给、增长策略或AI产品方向感兴趣，有相关实习、项目或课程经历者优先；\n3、具备较好的逻辑思维和结构化表达能力，能够快速理解业务问题，并将问题拆解为可执行的分析或产品需求；\n4、具备基础数据分析能力，熟悉Excel/SQL/Python等工具之一优先，能够通过数据发现问题并形成初步判断；\n5、具备良好的沟通协作能力和责任心，执行力强，能够在多方协作中推进事项落地；\n6、每周可实习4天及以上，连续实习3个月及以上优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7680510617432459525","sourceKey":"bytedance","company":"字节跳动","title":"安全实习生 - 中国交易与广告","city":"上海/杭州","category":"安全","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7680510617432459525/detail","duty":"团队介绍：中国交易与广告，负责抖音电商、生活服务、广告营销等营收业务的研发。用技术带来美好生活，让用户发现更多优价好物，为用户提供更丰富独特的生活体验；连接海量用户与商家，促进交易达成，让生态里全流程体验更流畅，助力营收业务长效增长。\n加入团队，你将投身流量与增长主战场，挑战复杂业务场景技术难题；直面真实商家和用户，用技术解决看得见的问题，在实战中快速成长，书写属于你的价值故事！\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、参与电商SDLC运营，建设电商安全体系；\n2、参与蓝军攻防演练，挖掘电商真实风险，验证电商安全防护能力；\n3、建设自动化安全工具和攻防平台，提升蓝军攻防效率；\n4、跟踪新型攻击技术、漏洞和黑灰产手法，结合实际业务完成复现、影响分析及检测方案建设。","requirements":"1、本科及以上学历在读；\n2、具备Linux环境下开发能力，掌握Python/Golang/C/C++任一种语言，熟练掌握AI使用；\n3、对Web安全有浓厚的兴趣和实践经验，熟悉OWASP Top10漏洞原理与防御技术。\n\n符合以下任意要求者优先：\n1、有Windows/Linux客户端安全攻防的经验，或了解Android/iOS移动安全；\n2、熟悉AI安全，了解目前Agent架构常见风险，有相关漏洞挖掘经验；\n3、熟悉电商领域黑灰产手法，有风控对抗经历；\n4、参加过CTF比赛，并在国家级比赛中获奖；\n5、有SRC漏洞挖掘经历，熟悉复杂系统的漏洞挖掘流程。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7672332033945422085","sourceKey":"bytedance","company":"字节跳动","title":"3D数字人算法工程师 - PICO","city":"北京/上海","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7672332033945422085/detail","duty":"团队介绍：作为一家拥有自主创新和研发创造能力的科技品牌，PICO致力于成为领先的世界级XR平台，成就开发者与创作者，共同为全球消费者创造更美好的生活体验。我们开创性地将虚拟现实扩展到了多个领域，为运动、视频、娱乐等消费级场景带来了全新体验；并广泛应用在教育、医疗和企业培训等商用场景，给全球企业级用户提供了多元化的VR解决方案。\n\n1、负责3D数字人相关前沿技术的探索和研究，包括但不限于全身3D数字人资产构建和仿真，全身3D数字人重建、生成和多模态驱动等；\n2、支持3D数字人技术在业务中的落地，将先进技术转化为PICO产品；\n3、支持3D数字人方向的技术影响力建设，产出高质量的专利和学术报告。","requirements":"1、2027届获得硕士及以上学位，计算机视觉/图像处理/机器视觉相关专业优先；\n2、在计算机视觉/图形学的一个或多个领域具备研究和实践经验，包括但不限于以下方面：\n1）3D人脸/人体的建模、编辑和驱动；\n2）人体（或面部）的显式和隐式表示，例如Nerf、3DGS、Codec Avatar等；\n3）人体（或面部）生成模型；\n3、熟练掌握算法设计和实现，精通C/C++/Python等计算机语言；\n4、具备优秀的沟通协作能力，对XR技术兴趣浓厚，具备快速学习新技术的能力；\n5、具备优秀的科研能力，在CVPR、ICCV、ECCV、SIGGRAPH等顶级期刊上发表过论文者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667885791859837237","sourceKey":"bytedance","company":"字节跳动","title":"Agent开发工程师 - AI Platform","city":"上海/北京","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667885791859837237/detail","duty":"团队介绍：AI Platform 团队，隶属于产品研发和工程架构部门。面向公司内部各业务线，建设统一的AI 应用基础设施和工程平台，帮助业务高效、稳定地落地大模型应用，加速 AI 产品创新。\n在平台产品侧，团队打造了新一代AgentOps平台，提供 Prompt Engineering、Agent观测、评测、数据处理、模型微调等 Agent 全生命周期解决方案，帮助Agent开发者构建效果调优的数据飞轮。产品也已成功推出商业化版本。\nAI Platform 团队还持续孵化多种面向内部与外部场景的AI应用创新产品，积极探索大模型应用的技术发展。团队氛围好，发展空间大，欢迎加入！\n\n1、基于业务场景核心诉求，主导Agent架构设计、深度迭代与落地，适配复杂业务需求，解决Agent工程化落地的核心痛点；\n2、设计并落地Agent自进化全链路体系，构建自主反思、迭代优化的闭环能力，实现Agent基于业务反馈的持续能力升级；\n3、打磨Agent任务拆解、推理规划、工具调用、多智能体协作等核心模块，持续优化架构性能，沉淀业务场景最佳实践；\n4、跟进Agent领域前沿技术，开展自进化、多模态智能体等方向的技术预研，结合业务完成创新落地，提升核心竞争力。","requirements":"1、2027届获得本科及以上学历，计算机、人工智能、自动化、数学相关专业优先；\n2、精通Go、Python、C++等一种或多种编程语言，具备扎实的编程技能和算法设计能力；\n3、对AI Agent技术有深入了解，熟悉LangChain等框架，熟悉LangSmith等平台；\n4、具备出色的团队协作精神和良好的英文阅读及沟通能力。\n\n加分项：\n1、在LLM工程领域有落地经验；\n2、对AgentOps平台熟悉，如LangSmith、Langfuse等；\n3、具备优秀的研究和探索精神，对最新Agent技术趋势和论文有深入的了解。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667877341592373509","sourceKey":"bytedance","company":"字节跳动","title":"后端开发工程师 - 火山引擎","city":"上海","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667877341592373509/detail","duty":"团队介绍：火山引擎是字节跳动旗下云和AI服务平台，将字节跳动快速发展过程中积累的增长方法、技术能力和应用工具开放给外部企业，通过云和AI技术，推进企业智能化转型，激发增长潜能。\n\n1、负责火山引擎费用分析，账务财务资金相关领域的整体架构设计与核心功能研发，服务火山引擎内部经营；\n2、建设和迭代账单中心、费用分析、财资客服智能体、资金结算、财务关系、财报管报、成本毛利等服务客户和支撑经营效率、实现经营风险透明化的平台与系统；\n3、持续推动核心技术的改进与性能优化，解决复杂工程技术问题，关注行业前沿技术尤其是AI方向，跟进最新研究进展和应用趋势，提出创新思路并推动落地。","requirements":"1、2027届获得本科及以上学历，计算机相关专业优先；\n2、熟练掌握至少一门编程语言（Golang/Java/Python/C++等），具备扎实的编码能力和良好的工程习惯；\n3、具备丰富的AI Coding实践经验，能够熟练运用AI编程工具辅助需求拆解、代码生成、重构、测试与问题定位；理解AI Coding的能力边界，并能基于工程经验对AI生成结果进行判断、优化和验证，持续提升研发效率与代码质量；\n4、熟悉MySQL、Redis、MQ等常用组件并理解其基本原理，理解服务化、异步化、高可用、可扩展等常规架构设计思想，并有实际实践经验；\n5、对业务敏感，具备优秀的抽象与设计能力，能够将业务问题沉淀为通用平台能力，具备良好的跨团队沟通与协作能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667862424641407285","sourceKey":"bytedance","company":"字节跳动","title":"效能Agent开发工程师 - 火山引擎","city":"北京","category":"测试","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667862424641407285/detail","duty":"团队介绍：火山引擎是字节跳动旗下云和AI服务平台，将字节跳动快速发展过程中积累的增长方法、技术能力和应用工具开放给外部企业，通过云和AI技术，推进企业智能化转型，激发增长潜能。\n\n1、测试Agent开发：负责测试相关Agent和相关套件工具的设计与开发工作，使其能高效应用于火山引擎平台的质量保障体系，涵盖对不同测试场景（如功能、性能、兼容性等）的适配，以提升整体测试效率与准确性；\n2、协同AI测试策略制定：深度介入火山引擎官网平台质量保障工作，与团队协作制定并推进AI相关的测试策略、计划及方法；确保测试Agent与整体测试流程紧密协同，有力保障平台产品的高质量交付；\n3、质量体系创新建设：积极投身火山引擎质量体系建设，探索质量Agent领域的创新技术与方法；结合质量要求与官网业务需求，提出前沿的Agent范式，推动测试流程向自动化、智能化迈进，全面提升测试效率。","requirements":"1、2027届获得本科及以上学历，计算机科学与技术、软件工程等相关专业；\n2、需要对大模型有深入理解，熟悉LLM、技术原理与应用方法，有Agent系统设计与实现经验；了解Memory机制、RAG、工具调用、规划执行等Agent关键技术，有相关实践经验；\n3、熟练掌握Python/Java/Go等至少一门编程语言，精通计算机基础技术，熟悉测试流程、质量保证方法、目标及常用工具，并能在Agent开发与测试工作中灵活运用；\n4、需具备：在测试工具开发过程中实际应用AI技术或拥有丰富的Agent系统设计与实现经验；在顶会发表过相关论文或有开源项目贡献者优先；\n5、拥有To B相关产品或云服务产品的质量保障经验者优先，熟悉此类产品的测试特点与Agent应用场景者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667106441702197557","sourceKey":"bytedance","company":"字节跳动","title":"大模型算法工程师（AI Agent方向） - TikTok研发","city":"上海","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667106441702197557/detail","duty":"团队介绍：TikTok研发团队，旨在实现TikTok业务的研发工作，搭建及维护业界领先的产品。加入我们，你能接触到包括用户增长、社交、直播、电商C端、内容创造、内容消费等核心业务场景，支持产品在全球赛道上高速发展；也能接触到包括服务架构、基础技术等方向上的技术挑战，保障业务持续高质量、高效率、且安全地为用户服务；同时还能为不同业务场景提供全面的技术解决方案，优化各项产品指标及用户体验。 \n在这里， 有大牛带队与大家一同不断探索前沿， 突破想象空间。 在这里，你的每一行代码都将服务亿万用户。在这里，团队专业且纯粹，合作氛围平等且轻松。目前在北京，上海，杭州、广州、深圳分别开放多个岗位机会。\n\n1、专注大模型领域，特别关注智能交互、文本生成以及其他核心NLP/ML算法模型在隐私安全的构建和提升；\n2、在隐私领域内开发其他相关算法应用，包括但不限于内容生成、推理和代码生成等；\n3、探索与大模型相关的前沿技术，并将它们应用于以隐私安全为中心的场景。","requirements":"1、2027届获得硕士及以上学位，计算机、软件工程等相关专业优先；\n2、具备大模型训练和强化学习算法经验，以及具有在大模型训练和应用中有效解决问题的经验加分；\n3、熟练掌握至少一种深度学习框架，如TensorFlow或PyTorch，包括其训练和部署的具体细节；熟悉常用的机器学习和深度学习算法，以及基本的网络模型结构和文本表示方法；\n4、出色的编码技能，熟练掌握至少一种编程语言，如Python、Go或C++，并具备算法和数据结构的扎实基础；\n5、有AI助手、智能对话、智能机器人经验优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7684175224719853829","sourceKey":"bytedance","company":"字节跳动","title":"端侧大模型算法实习生 - TikTok泛架构","city":"上海","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7684175224719853829/detail","duty":"团队介绍：TikTok是一个覆盖150个国家和地区的国际短视频平台，我们希望通过TikTok发现真实、有趣的瞬间，让生活更美好。TikTok 在全球各地设有办公室，全球总部位于洛杉矶和新加坡，办公地点还包括纽约、伦敦、都柏林、巴黎、柏林、迪拜、雅加达、首尔和东京等多个城市。\n\nTikTok泛架构团队处于业务和基础架构之间，我们的目标是拥抱AI，构建最先进的业务架构基建，建立公众信任和合规，关注资源管理和成本优化，用户体验和稳定性，提高工程质量和研发效率。在这里你既能感受到技术对上层业务的赋能，又可以提高在架构层面技术深度的理解，期待你的加入！\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、在TikTok客户端环境内构建策略和AI算法模型，在智能决策、意图识别、内容理解等领域进行业务落地；\n2、和工程团队合作，分析和提升模型性能，包括但不限于推理速度、内存占用和能耗优化；\n3、参与适用于客户端的CV、NLP、LLM、MLLM等垂直基础能力模型的优化和落地；\n4、参与端智能算法的长期探索，如端侧大模型应用、隐私计算、端边云协同等；\n5、业务覆盖搜索、推荐、社交、直播等多个场景。","requirements":"1、硕士及以上学位在读，计算机、软件工程等相关专业优先；\n2、扎实的算法基础（数据结构/机器学习/深度学习），熟练掌握Python，熟悉PyTorch框架，编码能力优秀；\n3、熟悉ML、强化学习、NLP、CV等相关的技术，有性能优化策略、用户体验策略、流媒体优化等方向的实战经验优先；\n4、理解Transformer/BERT/GPT等模型架构，有LLM相关项目经验者优先。\n\n加分项\n1、在顶会（CCF-A）发表过相关论文。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7683804060418361605","sourceKey":"bytedance","company":"字节跳动","title":"AI技术产品实习生（AI数据应用方向） - 中国交易与广告","city":"上海","category":"产品","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7683804060418361605/detail","duty":"团队介绍：中国交易与广告，负责抖音电商、生活服务、广告营销等营收业务的研发。用技术带来美好生活，让用户发现更多优价好物，为用户提供更丰富独特的生活体验；连接海量用户与商家，促进交易达成，让生态里全流程体验更流畅，助力营收业务长效增长。\n加入团队，你将投身流量与增长主战场，挑战复杂业务场景技术难题；直面真实商家和用户，用技术解决看得见的问题，在实战中快速成长，书写属于你的价值故事！\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、深度参与电商多端增长运营Agent项目，覆盖需求挖掘、产品方案设计、研发落地、线上迭代全流程，联动研发、算法、数据、业务等多方团队协同完成项目；\n2、深度参与人群圈选Agent项目，基于业务目标完成人群与商品的圈选口径设计与验证，协助搭建标签、规则与投放策略，通过数据反馈持续优化圈选精准度与转化效果；\n3、深入电商多端增长业务场景，识别影响增长表现的关键因素，从产品视角拆解问题并沉淀策略框架，完成需求梳理与方案设计，跟踪线上效果、输出优化方案以提升增长收益；\n4、参与Agent效果评测与复盘，协助定义评估指标、设计标注与实验规则，形成数据闭环，持续提升策略与Agent的质量和体验。","requirements":"1、本科及以上学历在读，计算机、人工智能、数据科学、统计学、信息管理经济学、数学等相关专业优先；\n2、每周可实习4天，可连续实习3个月优先，学习能力强、上手快，面对陌生业务和工具能快速理解并投入，愿意主动补齐知识缺口；\n3、对电商业务、AI产品有浓厚兴趣，关注电商发展和AI前沿应用，愿意钻研新问题、追求更好的结果；\n4、能把复杂、模糊的业务问题拆解为指标、策略与产品方案，具备较强的数据分析与结构化思考能力；\n5、表达清晰、协作顺畅，能主动与业务方探讨对齐需求、推进跨团队落地，自驱、责任心强；\n6、有电商业务（增长/内容/行业运营等）、Agent产品、智能分析相关项目或产品实习经验，会熟练使用AI工具者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7677863681490962693","sourceKey":"bytedance","company":"字节跳动","title":"多模态大模型推理算子优化工程师 - Data AML","city":"北京/杭州/上海","category":"机器学习","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7677863681490962693/detail","duty":"团队介绍：Data AML是字节跳动的机器学习中台，为抖音/今日头条/西瓜视频等业务提供推荐/广告/CV/语音/NLP的训练和推理系统。为公司内业务部门提供强大的机器学习算力，并在这些业务的问题上研究一些具有通用性和创新性的算法。同时，也通过火山引擎将一些机器学习/推荐系统的核心能力提供给外部企业客户。\n\n1、负责Seedance/Seedream基础模型及衍生模型异构卡推理加速工作；\n2、负责视频/图像生成/多模态等方向模型的异构卡适配。","requirements":"1、2027届获得硕士及以上学位，计算机相关专业优先；\n2、有AI工程系统优化经验，深入理解计算机体系结构、熟悉CUDA/AscendC/BangC/HIP中的一种或者多种算子，熟悉计算密集型算子如FlashAttention、Conv2d、Matmul、GroupedMatmul、MOE实现和加速；\n3、具备低比特量化、稀疏等优化技术经验者优先；\n4、熟悉Triton、TileLang、Cute DSL等语言并具备相关技术优化经验优先；\n5、了解主流AIGC、多模态算法模型原理，有AIGC模型训练适配&加速、通算融合/掩盖经验优先；\n6、熟悉TensorRT-LLM、SGLang、vLLM引擎，或熟悉ZeRO、TP、SP等并行技术原理优先；具备良好的沟通能力和团队合作精神。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7674872390589188405","sourceKey":"bytedance","company":"字节跳动","title":"推荐产品实习生 - 抖音电商","city":"北京","category":"产品","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7674872390589188405/detail","duty":"团队介绍：抖音电商以“总能发现好东西”为主张，致力于成为用户发现丰富好物的首选平台。众多抖音创作者通过短视频、直播、商城等丰富的形式，给用户提供更个性化、更生动、更高效的消费体验。同时，抖音电商积极引入优质合作伙伴，为商家变现提供多元的选择。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、通过数据分析、用户调研等方式发现策略问题和优化机会，推动策略上线和效果验证，平衡用户体验、业务目标和生态健康，制定合理的推荐排序规则；\n2、对电商常见营销玩法有了解，联合运营、算法优化营销策略、完善推荐场域营销功能和玩法，提升用户交易；\n3、负责优化推荐场景下的用户交易体验，包括产品形态、交互链路和展示策略；\n4、配合完成部门其他相关工作。","requirements":"1、本科及以上学历在读；\n2、对算法有基本认知，能与算法工程师进行有效沟通和合作，熟练掌握SQL，有推荐、搜索、广告等策略产品相关实习经验者优先；\n3、具备良好的用户思维，关注用户在信息获取中的核心体验，善于通过数据和案例进行归因分析，定位和解决复杂问题；\n4、学习能力强，能快速理解复杂的策略系统和技术原理；\n5、可实习6个月。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7670123048703445253","sourceKey":"bytedance","company":"字节跳动","title":"具身智能研发工程师 - 火山引擎","city":"北京/上海","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7670123048703445253/detail","duty":"团队介绍：火山引擎是字节跳动旗下云和AI服务平台，将字节跳动快速发展过程中积累的增长方法、技术能力和应用工具开放给外部企业，通过云和AI技术，推进企业智能化转型，激发增长潜能。\n\n1、参与具身智能研究，推动具身智能解决方案的研发落地工作，包括但不限于：多模态交互，具身大脑、Agent系统，世界模型，RL强化学习，VLA、VLN、运控等方向；\n2、参与具身智能解决方案中的软件架构设计，模型研发、数据研发、仿真评测和集成部署工作；\n3、与团队成员紧密协作，共同解决复杂的跨领域技术难题。","requirements":"1、2027届获得硕士及以上学位，计算机科学、数据工程、机器人或相关背景；\n2、精通Python/C++，具备扎实的工程能力和良好的代码习惯；\n3、有机器人系统经验者加分，你的工作将能立刻落地到真实机器人体内；\n4、对前沿技术保持好奇心与热情，愿意在具身智能领域迎接挑战、突破边界；\n5、具备出色的沟通能力和团队协作精神，能够高效指导和推动他人开展研究工作。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669730292838353157","sourceKey":"bytedance","company":"字节跳动","title":"大模型应用算法工程师 - TikTok内容安全算法","city":"北京/上海","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669730292838353157/detail","duty":"团队介绍：国际化内容安全算法研究团队致力于为字节跳动国际化产品的用户维护安全可信赖环境，通过开发、迭代机器学习模型和信息系统以更早、更快发掘风险、监控风险、响应紧急事件，团队同时负责产品基座大模型的研发，我们在研发过程中需要解决数据合规、模型推理能力、多语种性能优化等方面的问题，从而为平台上的内容审核、搜索、推荐等多项业务提供安全合规，性能优越的基座模型。\n\n1、Reward模型的设计：在强化学习过程中，设计一个合适的Reward模型是关键；Reward模型需要准确地反映推理过程的效果，并引导模型逐步提升其推理能力；这不仅要求对不同任务精准设定评估标准，还要确保Reward模型能够在训练过程中动态调整，以适应模型性能的变化和提高；\n2、稳定的训练过程：在缺乏高质量SFT数据的情况下，如何确保强化学习过程中的稳定训练是一个重大挑战；强化学习过程通常涉及大量的探索和试错，这可能导致训练不稳定甚至模型性能下降；需要开发具有鲁棒性的训练方法，以保证模型在训练过程中的稳定性和效果；\n3、如何从数学和代码任务上拓展到自然语言任务上：现有的推理强化方法主要应用在数学和代码这些CoT数据量相对丰富的任务上；然而，自然语言任务的开放性和复杂性更高，如何将成功的RL策略从这些相对简单的任务拓展到自然语言处理任务上，要求对数据处理和RL方法进行深入的研究和创新，以实现跨任务的通用推理能力；\n4、推理效率的提升：在保证推理性能的前提下，提升推理效率也是一个重要挑战，推理过程的效率直接影响到模型在实际应用中的可用性和经济性；可以考虑利用知识蒸馏技术，将复杂模型的知识传递给较小的模型，以减少计算资源消耗；另外，使用长思维链（Long Chain-of-Thought,Long-CoT）技术来改进短思维链（Short-CoT）模型，也是一种潜在的方法，以在保证推理质量的同时提升推理速度。","requirements":"1、2027届获得硕士及以上学位，计算机、电子等相关专业优先；\n2、丰富的ML/CV/NLP/推荐经验，包括但不限于：\n1）机器学习/数据挖掘/CV/NLP/多模态等相关竞赛或行业经验；\n2）机器学习/数据挖掘/人工智能/大模型相关领域的会议论文；（KDD/WWW/NIPS/ICML/CVPR/ACL/AAAI...）；\n3）有大模型/强化学习相关的研究经历和创新探索；动手快，在开源社区有大模型相关的贡献记录；在业务场景有大模型落地经验者优先；\n3、扎实的编程功底，熟悉Python/C++等编程语言；\n4、优秀的分析问题和解决问题的能力，并热衷于解决具有挑战性的问题；\n5、对技术充满热情，良好的沟通能力和团队合作精神。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669711727048444165","sourceKey":"bytedance","company":"字节跳动","title":"算法工程师（激励方向） - Ads Core","city":"北京/上海","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669711727048444165/detail","duty":"团队介绍：Ads Core 是抖音集团广告业务体系中负责交易机制与智能决策的核心技术团队之一。\n \n我们面对的是一个超大规模的商业化经济系统：一端是广告主和商家，希望在可控成本下获得订单、GMV、线索、用户增长和长期生意增长；另一端是抖音等产品中有限而高价值的用户流量。Ads Core 要解决的问题，是预算从哪里来、流量给到哪里，以及如何让每一次商业流量分配都更接近客户增量、用户体验和平台长期收入的共同最优。\n \n团队覆盖出价与竞价、归因与信号、自动化投放、流量机制、激励增长等关键方向，通过机器学习、因果推断、强化学习、机制设计和大规模工程系统，把客户经营目标转化为平台可理解、可执行、可优化的交易决策。\n \n技术上，Ads Core 处在超大规模、高并发、强约束的真实交易系统中。我们需要在每天海量请求里完成预算分配、实时出价、归因度量、自动化决策和流量机制优化；也需要在客户目标、用户体验和平台长期收入之间做多目标建模与系统决策。这里会持续产生因果归因、强化学习、机制设计、长期价值建模、大规模在线实验、实时工程系统等高难度问题，并要求算法能力真正落到线上交易链路和业务结果中。\n \n加入 Ads Core，你将参与建设抖音集团广告业务最核心的底层系统：让广告主真正把生意做大，让用户体验持续被保护，让平台获得长期、合理、可持续的商业化收入。如果你希望在真实商业系统里把算法、机制和工程能力转化为可见的业务影响，这里会提供足够复杂、也足够有成长空间的问题。\n\n1、围绕抖音、今日头条、番茄小说等App进行激励策略迭代；\n2、落地因果推断、运筹优化、强化学习及营销大模型等前沿算法技术，结合多元激励玩法与流量策略，持续改善用户体验，推动用户规模扩增、广告收入提升与业务持续增长；\n3、依托海量用户数据与创新激励玩法，运用前沿机器学习算法实现更精准的个性化营销，高效应对业务增长场景中的各类实际问题；\n4、参与抖音、今日头条、番茄小说等亿级用户规模产品的变现、增长工作，聚焦流量优化、激励补贴以及长期价值建模，推动广告营收提升与用户留存优化；\n5、运用强化学习、因果推断和大模型等技术提升个性化激励策略效果，通过算法建模实现激励与流量的高效协同，落地前沿研究成果，持续提升用户LTV；\n6、在超大规模深度学习框架下，参与模型、出价优化以及策略升级，持续优化激励场景的CTR/CVR/Uplift模型，探索激励策略在广告与营销场景中的最佳实践。","requirements":"1、2027届获得本科及以上学历，计算机、机器学习和模式识别等相关专业优先；\n2、具备优秀的编程和算法能力，熟练掌握C++/Python等编程语言，熟悉常见的数据结构与算法；\n3、具备扎实的统计学习与深度学习理论基础，在强化学习、大模型应用、因果推断、运筹优化等一个或多个领域有深入的研究或实践经验；\n4、有国际顶级会议或期刊论文发表经历，或参与过知名开源项目者优先；曾获Kaggle、ACM等算法比赛奖项者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668648081328818485","sourceKey":"bytedance","company":"字节跳动","title":"电商增长产品经理（内广投放&CRM方向） - TikTok Shop","city":"北京","category":"产品","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668648081328818485/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商。平台汇聚全球优质商家与创作者，通过短视频、直播等多场景连接消费者，让新奇好物畅销全球，让美好生活触手可得。目前团队分布在美国、英国、法国、印尼、墨西哥、中国等全球多个国家和地区，在这里你将有机会深入国际业务场景，面向全世界商家及用户，和跨区域团队协作，共同探索创新购物模式。期待和优秀的你一起创造更多可能！\n\n1、负责电商增长产品的策略与效果目标，围绕交易用户规模增长、GMV/MAC提升及ROAS等关键指标负责；\n2、负责站内广告（内广）增长策略建设与迭代，制定并优化人群定向、素材策略、选品策略、出价/投放策略等，持续提升流量与转化效率；\n3、负责CRM增长产品能力建设（Push/Email/Inbox/SNS等触达渠道），基于用户行为与生命周期运营，设计CRM事件与触达策略，并通过漏斗分析持续优化转化链路；\n4、通过用户细分、人群分析、营销工具/产品流程优化等手段，识别增长机会、定位问题并推动方案落地；\n5、深入理解全球市场与用户，协同算法、数据、供给、产品等多团队合作，推进增长方案的产出、上线与复盘迭代。","requirements":"1、2027届获得本科及以上学历，专业不限；\n2、具备较强的逻辑分析能力与数据敏感度，能基于数据发现问题、提炼关键洞察并输出可执行的策略方案；\n3、具备良好的产品与用户理解能力，能从用户需求与业务目标出发进行方案设计、推进协作并推动落地；\n4、有增长策略/增长产品相关实践经验者优先（如投放增长、站内广告、CRM触达、漏斗优化、转化提升等），具备与算法/数据团队协作或对接推荐/广告/增长模型经验者优先；\n5、英文可作为工作语言，有全球/国际化学习、生活、实习经历或全球/国际化项目经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668646542006667573","sourceKey":"bytedance","company":"字节跳动","title":"用户增长运营（AMS） - TikTok Shop","city":"上海","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668646542006667573/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商。平台汇聚全球优质商家与创作者，通过短视频、直播等多场景连接消费者，让新奇好物畅销全球，让美好生活触手可得。目前团队分布在美国、英国、法国、印尼、墨西哥、中国等全球多个国家和地区，在这里你将有机会深入国际业务场景，面向全世界商家及用户，和跨区域团队协作，共同探索创新购物模式。期待和优秀的你一起创造更多可能！\n\n1、支持区域市场用户增长工作，围绕拉新、促活、复购等场景开展产品分析，支持增长策略制定与落地；\n2、通过数据分析和A/B实验，制定合理的补贴、投放标准，优化运营能力和经营效率；\n3、协同供给、产品、算法等团队，参与用户增长相关横向项目，推动项目落地与效果复盘；\n4、持续加强对全球市场的理解，探索差异化运营策略和创新产品方案，沉淀可复用的方法与经验。","requirements":"1、2027届获得本科及以上学历，专业不限；\n2、有结合数据分析和用户洞察制定增长策略或产品方案的实践案例，对用户购买决策路径有较好的敏感度，有电商行业战略、策略、经营分析等相关经验者优先；\n3、具备较强的数据逻辑和数据敏感性，熟练使用SQL、Excel，掌握R、Python、SAS等分析工具者优先；\n4、中英文可作为工作语言，具备跨部门沟通与问题处理能力，能够适应多时区协作。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668623234049018117","sourceKey":"bytedance","company":"字节跳动","title":"测试开发工程师 - 抖音研发中台","city":"北京/深圳","category":"测试","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668623234049018117/detail","duty":"团队介绍：抖音研发中台团队主要负责抖音、剪映、今日头条、番茄小说、财经等产品的质量建设，面向质量、体验、安全提供全方位、深层次、高效的解决方案。\n\n1、主要负责客户端/服务端产品质量相关或业务线测试与工具开发工作；\n2、深度参与产品研发项目，协同产品和研发团队高质量交付产品；\n3、日常项目线下测试与线上质量分析；\n4、参与质量体系规划和建设；\n5、参与开发效率工具和保证技术项目质量。","requirements":"1、2027届获得本科及以上学历，计算机等相关专业；\n2、热爱计算机科学和技术，对软件质量保障工作有浓厚兴趣；\n3、扎实的数据结构和算法基础；熟悉至少一门编程语言，包括但不仅限于：Java、OC、C、C++、Python、Go、PHP；\n4、优秀的产品意识，对市场上典型App有自己的想法和改进方案；\n5、快速适应和学习能力，善于发现和定位问题；\n6、了解常用客户端、服务端开发或测试工具，如自动化框架、压测工具、大数据处理工具者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668518023789414661","sourceKey":"bytedance","company":"字节跳动","title":"跨境物流美洲运营 - TikTok Shop","city":"上海/深圳","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668518023789414661/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商。平台汇聚全球优质商家与创作者，通过短视频、直播等多场景连接消费者，让新奇好物畅销全球，让美好生活触手可得。目前团队分布在美国、英国、法国、印尼、墨西哥、中国等全球多个国家和地区，在这里你将有机会深入国际业务场景，面向全世界商家及用户，和跨区域团队协作，共同探索创新购物模式。期待和优秀的你一起创造更多可能！\n\n1、参与制定跨境区域物流正逆向解决方案，负责跨境端到端物流履约流程SOP制定和物流商管理；\n2、负责履约线路时效、成本及体验相关指标运营，搭建运营体系，跟踪日常运营数据，协调物流商资源，推动运营指标提升；\n3、结合业务不同阶段的履约问题，推动相关部门开展物流履约专项优化，协同提升跨境物流履约体验；\n4、参与跨部门沟通协调，基于运营过程提出流程及产品改善建议，推动相关项目落地。","requirements":"1、2027届获得本科及以上学历，物流、供应链管理、电子商务等相关专业优先；\n2、有搭建物流运营的相关工作经历优先，有美洲物流线路相关运营经验、熟悉国际电商流程和物流运作模式、运营管理模式经验优先；\n3、高度的责任心，有较强的数据分析能力；\n4、具备流利的英语听说读写能力，具备国际化留学经历者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668269590400698677","sourceKey":"bytedance","company":"字节跳动","title":"Agent策略工程师 - Seed","city":"深圳/上海/杭州","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668269590400698677/detail","duty":"团队介绍：产品研发和工程架构-Seed 团队深耕大模型技术在场景中的创新应用，负责多款现象级AI产品的工程研发 —— 包括豆包、飞书、豆包工作、豆包爱学、Gauth、猫箱等创新产品，覆盖消费级与企业级多个场景。我们致力于将大模型能力从 \"生成内容\" 推进到 \"完成工作\"，让 AI 服务用户日常与企业协作。你将面对多模态交互、工具调用可靠性、企业级数据安全等真实工程挑战，与团队一起推动 AI 生产力落地。\n\n1、参与设计和开发基于LLM的AI Agent系统，包括工具调用、记忆管理等核心模块；\n2、探索和优化Agent架构，提升任务规划、推理和执行的效果与可靠性；\n3、设计和实施AI应用的评测体系，通过数据驱动持续优化Agent表现；\n4、跟进前沿Agent技术，快速原型验证并落地到产品中。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程等相关专业优先；\n2、扎实的算法和数据结构基础，熟练掌握至少一门编程语言；\n3、对LLM和AI Agent有浓厚兴趣，动手能力强，有独立完成项目的能力，学习能力优秀；\n4、有良好的团队合作精神，有责任心。\n\n以下经历加分：\n1、有AI Agent产品的开发或调优经验（如OpenClaw、Claude Code、Codex等）；\n2、有LLM应用调优经验（效果评测、Prompt优化、模型选型等）；\n3、有NLP或大模型相关科研经历。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668264548848224517","sourceKey":"bytedance","company":"字节跳动","title":"大模型算法工程师 - TikTok研发","city":"上海","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668264548848224517/detail","duty":"团队介绍：TikTok研发团队，旨在实现TikTok业务的研发工作，搭建及维护业界领先的产品。加入我们，你能接触到包括用户增长、社交、直播、电商C端、内容创造、内容消费等核心业务场景，支持产品在全球赛道上高速发展；也能接触到包括服务架构、基础技术等方向上的技术挑战，保障业务持续高质量、高效率、且安全地为用户服务；同时还能为不同业务场景提供全面的技术解决方案，优化各项产品指标及用户体验。 \n在这里， 有大牛带队与大家一同不断探索前沿， 突破想象空间。 在这里，你的每一行代码都将服务亿万用户。在这里，团队专业且纯粹，合作氛围平等且轻松。目前在北京，上海，杭州、广州、深圳分别开放多个岗位机会。\n\n1、参与TikTok Feed及垂直消费场景的多模态内容理解、用户理解等底层能力建设和业务场景应用，为用户价值创造提供底层能力支撑；\n2、负责TikTok主框架用户触达与资源位（交互区组件、弹窗、异形卡、气泡、头像挂件等）及App框架流量位（顶/底Tab）的流量分发与个性化算法策略，涵盖个性化排序、展示与投放；协同工程、产品团队推动策略落地，提升资源容器的分发效率与用户消费体验；\n3、夯实海量数据下的基础算法能力和算法框架，探索并引入业界优秀实践，包括超长序列/大规模异构场景建模/大规模图神经网络等；\n4、参与面向TikTok用户与内部研发的AI Agent建设：对外打造智能交互与个性化服务能力，提升用户消费体验与触达效率；对内构建研发提效Agent，赋能算法策略的自动化生产、实验与迭代，提升团队研发效能；探索大模型与Agent技术在推荐与消费场景的深度应用。","requirements":"1、2027届获得本科及以上学历，机器学习等相关专业优先；\n2、熟练掌握深度学习算法，掌握TensorFlow、PyTorch等至少一种主流深度学习编程框架；\n3、熟练掌握C/C++、Python、Shell编程语言，对数据结构和算法设计有较好的理解；\n4、熟悉大规模数据挖掘、机器学习、分布式计算中的一项或多项，有深度学习实战经验，有机器学习算法优化理论的研究经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668246456235739397","sourceKey":"bytedance","company":"字节跳动","title":"AI产品经理（抖音电商方向） - 数据BP","city":"北京/杭州","category":"大数据","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668246456235739397/detail","duty":"团队介绍：负责字节跳动旗下泛抖音、国际化、创新与中台等业务的数据 BP 工作，业务版图覆盖抖音、国际化、大模型、番茄小说等板块。我们以数据高效赋能业务增长为核心使命，深度扎根各业务线，以数据体系建设为根基、以业务目标达成为导向，为业务方提供专业、稳定、高效的数据服务与架构解决方案。工作内容聚焦海量数据的治理与应用，需对产品全链路数据进行复杂且深度的分析挖掘；深度参与大数据产品的迭代优化，探索前沿数据技术在业务场景中的落地实践，在字节跳动的技术土壤中实现个人能力与业务价值的双重增长。\n\n1、参与抖音电商数据Agent、知识库、评测等多方向产品设计，打造懂电商业务的AI智能体；\n2、与业务对接，梳理业务需求，具备通过Skill交付业务需求的能力；\n3、协同技术、运营、算法等团队，推进产品落地及推广。","requirements":"1、2027届获得本科及以上学历，计算机、统计学、数据分析、人工智能、软件工程、产品设计等相关专业优先；\n2、优秀的业务意识，具备将AI与业务结合起来的能力，了解电商业务优先；\n3、具备AI需求洞察能力，能够从业务场景中识别高价值AI机会，并通过合理方案解决用户核心痛点；\n4、具备快速原型验证能力，熟悉主流大模型能力，能通过调研分析、Demo、Prompt、Vibe coding快速验证想法；\n5、具备强烈的负责人意识、优秀的跨团队协作能力，能与算法、研发、设计、运营、售前高效协作，推动AI需求从方案设计到上线推广的完整流程，自我驱动、结果导向；\n6、持续学习，主动关注大模型、Agent、大数据等技术进展，对于产品方向、行业趋势、市场机会有洞察力，能主动挖掘业务增长方向。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668221581466175797","sourceKey":"bytedance","company":"字节跳动","title":"基于多模态大模型与用户行为理解的下一代分发与交互技术 - 抖音","city":"北京/上海/深圳","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668221581466175797/detail","duty":"团队介绍：Data-抖音团队，负责抖音APP的推荐算法、AI大模型应用、内容算法、增长算法、广告自动化投放、智能对话等算法工作，对接全链路各体裁（短视频，图文）各业务（内容消费，互动，UGC，双列，社交，生态，垂类，创作，消息，汽水音乐，精选，随变，增长投放，评论，内容理解&安全、智能对话等）。我们的工作涉及大规模推荐算法的优化、多业务复杂约束下的优化问题、多模态内容理解、LLM基础技术研究、业务Agent化和创新AI落地应用、CV/NLP等多个学术领域的算法改进工作、对多种场景的推荐架构的设计和实现和对产品数据的复杂深入的分析工作。在这里，你可以深入钻研机器学习算法的改进和优化，探索工业界最领先的推荐系统架构和推荐大模型算法、可以通过使用最新的大模型技术支持抖音的AI分身、业务智能化、智能客服等创新探索；可以通过对产品的深度理解和思考，将算法应用到业务中去；也可以通过对产品和内容生态的深度分析，影响产品未来的发展方向。\n\n课题介绍：\n本课题旨在探索基于多模态大模型的模态理解与表征、世界知识、推理等能力，并深度的与信息分发（推荐、搜索等）中的用户行为理解和建模结合起来，构建支撑下一代分发与交互技术的基础模型和系统范式。通过基础技术突破和探索，既尝试解决原有分发技术中对长尾兴趣分发、用户复杂意图理解、多模态与行为协同融合、System Bias、分发系统的算力与推理分配等一系列关键问题，也探索基于新的多模态大模型与用户对齐的理解，支持全新的可对话性需求满足、可自然交互性的分发调节与个性化等能力和产品形态上的突破。\n\n课题挑战：\n1、多模态大模型的完整流程的训练，以及与大规模用户行为深度理解和对齐；\n2、突破多模态大模型与长序列高并发高效推理的瓶颈；\n3、实现大模型泛化推理能力与复杂推荐业务目标的深度对齐。\n\n课题价值：\n1、打破信息茧房，提供个性化可解释推荐，提升长尾/冷启分发效率；\n2、沉淀大模型Scaling Up范式，重塑大模型时代的下一代推荐系统；\n3、探索全新的支持下一代交互场景的分发基础技术突破。","requirements":"1、2027届毕业，获得博士学位；人工智能、计算机、数学相关专业优先；\n2、优秀的代码能力、数据结构和基础算法功底，熟练C/C++（传统编码方向）或Python（智能编码方向）；\n3、智能编码方向要求有扎实的机器学习基础，在TPAMI/CVPR/NeurIPS/ICCV等期刊会议上发表论文者优先；\n4、有向标准组织提出过提案并有标准会议经验的同学优先；\n5、出色的问题分析和解决能力，有自主探索解决方案的能力，良好的沟通协作能力，能和团队一起探索新技术，推进技术进步；\n6、出色的心理素质与应变能力，面对困难勇于迎接挑战；面对复杂局面沉着、冷静、灵活。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668162735155562757","sourceKey":"bytedance","company":"字节跳动","title":"基础服务与架构后端开发工程师 - 集团信息系统","city":"深圳","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668162735155562757/detail","duty":"团队介绍：集团信息系统部（Corporate Information System） 负责字节跳动企业内信息系统、工具与AI创新应用的整体规划与建设，我们服务全球所有员工与业务单元，覆盖通用办公、人事、财务、法务、采购、审批、职场等核心领域。在AI时代下，我们致力于推动公司组织效率跃升与业务流程变革，我们正用AI重构企业运作的毛细血管：通过系统工具 AI 化与构建企业级 Agent 体系，让系统进化为 “智能助手”，提升全球团队的协同协作与业务运转效率；通过深耕企业上下文建设，实现从端到端业务流的智能化升级与流程再造。在持续激发AI 生产力的同时，部门加强安全、隐私与合规的治理，为公司长远发展保驾护航。\n\n1、参与平台产品的服务端研发工作，推动业务的快速发展和高效迭代；\n2、参与系统架构设计、优化，提升系统性能和开发效率，保证设计和编码的质量；\n3、协助团队攻克各种高并发、系统解耦等方面的技术难关；\n4、参与各专项技术调研，新技术引入等前瞻项目。","requirements":"1、2027届获得本科及以上学历，计算机、通信等相关专业者优先；\n2、有扎实的编程能力，有优秀的设计和代码质量；\n3、深刻理解计算机原理，有良好的数据结构和算法基础；\n4、熟悉MySQL、Redis、消息队列等常用研发组件；\n5、积极乐观，责任心强，工作认真细致，有良好的团队沟通和协作能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667806455349807413","sourceKey":"bytedance","company":"字节跳动","title":"内容治理AI产品经理（抖音AI产品人才校招） - 抖音社区治理","city":"北京","category":"产品经理","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667806455349807413/detail","duty":"团队介绍：抖音致力于打造一个开放、积极、多元、友善的平台，鼓励表达、沟通和记录，激发创造，丰富人们的精神世界，让现实生活更美好。我们通过AI算法驱动的个性化推荐与智能创作工具，满足用户表达、学习、娱乐、社交、消费等需求。回顾抖音一路走来的历程，我们在帮助亿万用户记录美好生活的过程中，努力变得更好。抖音社区治理团队负责抖音的社区治理工作，包括视频、直播等多体裁的内容治理，以及安全产品中台能力建设。\n\n这是抖音面向具备AI能力的同学发起的校招项目，覆盖产品、策略运营方向。\nAI 正在重新定义产品，也在重新定义\"做产品\"这件事 —— AI Native 的产品，需要你既能理解大模型技术边界，又能定义产品价值。\n如果你也有着许多的奇思妙想， 欢迎加入抖音，把想法落地成亿万用户真实可感的产品体验，来抖音，和我们一起探索 AI 产品的下一种可能！\n\n1、负责抖音直播、视频等场景下，基于AI能力的风险感知产品设计与落地，包括但不限于风险识别模型、智能分析系统、Agent应用等；\n2、主导构建和优化以RAG、知识库为核心的内容理解与治理策略，深入挖掘舆情、热点等风险场景，协同算法、数据团队，提升风险识别的准确性与时效性；\n3、探索并实践Agent在社区治理、应急响应等流程中的应用，设计和搭建自动化、智能化的解决方案，提升平台治理效率；\n4、深入理解平台风险与治理逻辑，持续跟踪AI产品上线后的运行效果与数据反馈，通过数据分析驱动产品迭代和模型优化，保障业务健康发展与用户体验。","requirements":"1、2027届获得本科及以上学历；计算机、软件工程等相关专业优先；\n2、拥有扎实的AI产品设计与落地经验，对RAG、知识库、Agent搭建等至少一个领域有深入理解和实践，有成功的产品落地案例；\n3、具备优秀的数据分析能力和逻辑思维，能从复杂业务场景中发现问题，并通过数据驱动产品持续创新与优化；\n4、对内容治理、风险控制、应急响应等领域有浓厚兴趣或相关经验，能快速理解业务并转化为产品方案；\n5、具备出色的跨团队沟通、协调和项目推进能力，能够高效协同算法、工程、运营等多个团队，确保产品目标的达成。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667767817475901749","sourceKey":"bytedance","company":"字节跳动","title":"AI音乐产品经理（抖音AI产品人才校招） - 抖音音乐","city":"北京/上海","category":"产品经理","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667767817475901749/detail","duty":"团队介绍：团队负责字节跳动中国音乐业务，包括流媒体汽水音乐，抖音音乐、版权内容等相关业务，我们致力于成为具有影响力的音乐平台，成为让用户最容易发现音乐、了解音乐、进行音乐表达和创作、围绕音乐交流的社区。\n\n这是抖音面向具备AI能力的同学发起的校招项目，覆盖产品、策略运营方向。\nAI 正在重新定义产品，也在重新定义\"做产品\"这件事 —— AI Native 的产品，需要你既能理解大模型技术边界，又能定义产品价值。\n如果你也有着许多的奇思妙想， 欢迎加入抖音，把想法落地成亿万用户真实可感的产品体验，来抖音，和我们一起探索 AI 产品的下一种可能！\n\n1、负责AI音乐创作工具的整体产品规划与设计，打造面向音乐人、内容创作者的下一代AI辅助创作平台；\n2、主导核心创作功能（AI歌声合成、编曲辅助、作词作曲、MIDI编辑、混音母带、人声克隆、Stem分离等）的产品设计与体验优化；\n3、深入理解目标用户（专业音乐人、半专业创作者、UGC用户）的创作工作流，挖掘差异化产品价值点；\n4、建立产品数据指标体系，跟踪用户创作留存、作品产出率、工具使用深度等核心指标，驱动产品迭代；\n5、跨团队协同：与设计、前端、客户端、算法、业务方紧密配合，推动高复杂度创作工具的落地与上线；\n6、深度调研行业音乐创作类产品的产品形态与用户体验，输出产品洞察与产品策略。","requirements":"1、2027届获得本科及以上学历，产品设计、计算机、音乐科技、数字媒体等相关专业优先；\n2、有ACE Studio、Suno、BandLab、GarageBand等音乐创作类产品的深度使用经验；\n3、熟悉DAW（数字音频工作站）工作流，理解MIDI编辑、音频编辑、VST插件、混音等核心概念；\n4、具备一定的用户体验与交互设计功底，能够独立完成复杂专业工具的产品方案设计；\n5、对AI音乐生成技术有基本认知，能够将算法能力转化为优秀的用户体验；\n6、具备音乐创作背景，有个人作品或音乐项目经验的优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667534248074840325","sourceKey":"bytedance","company":"字节跳动","title":"特效与算法策略 - 剪映CapCut","city":"北京","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667534248074840325/detail","duty":"团队介绍：剪映CapCut团队成立七年，先后孵化了剪映、CapCut、醒图、Hypic、即梦、Dreamina、Pippit等产品，覆盖视频、图片、Al生成、视频营销等多领域，打造与AI结合的全球化产品矩阵。\n我们的愿景是：激发想象力，成为全球领先的互动内容平台，创造独特的体验和价值。\n我们期待你的加入，一同极致打磨用户体验,构建创意生态和商业化能力，定义AI与创作结合的无限可能，让内容互动更简单、更精彩!\n\n1、负责CapCut产品内的AI模型（视频模型）的算法效果评估、优化及接入策略，基于用户需求场景理解制定模型效果定义、设计模型效果评测体系，对模型效果进行评估与验收，并推进模型接入和效果打磨；\n2、通过对内外部AI模型整体效果评估，明确模型接入策略，并牵头推动算法、产品、设计等团队共同推进模型能力上线，对上线后的用户反馈及模型采纳率负责；\n3、根据上线的模型数据进行数据处理和分析，迭代模型效果，并对不同功能模块的数据梳理优先级，明确业务重心，持续优化算法性能。","requirements":"1、2027届获得本科及以上学历，影视专业背景；\n2、具备小语种能力、社媒资深视频创作者等经验的候选人优先；\n3、对AI领域的动态/新技术深入研究，熟悉不同类型AI模型能力和效果，有AI算法相关运营工作经验者优先；\n4、熟悉国际化社交软件及视频内容平台，熟悉国际化潮流文化，有良好的内容洞察力；\n5、良好的数据分析能力，逻辑能力强，能快速梳理出核心问题并提出解决方案；\n6、具备优秀的沟通和协作能力，能够与跨部门团队有效合作。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667519570013915445","sourceKey":"bytedance","company":"字节跳动","title":"AI产品经理 - 抖音电商","city":"上海/北京","category":"产品","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667519570013915445/detail","duty":"团队介绍：抖音电商以“总能发现好东西”为主张，致力于成为用户发现丰富好物的首选平台。众多抖音创作者通过短视频、直播、商城等丰富的形式，给用户提供更个性化、更生动、更高效的消费体验。同时，抖音电商积极引入优质合作伙伴，为商家变现提供多元的选择。\n\n1、负责抖音电商治理运营平台产品相关工作，通过AI能力优化原有的流程，包括但不限于哨兵策略引擎、治理规则中心、治理审核平台、智能立规、智能审核等；\n2、探索AI原生的产品，通过建设治理管家，期望能够逐步建设AI独立接管治理策略的治理中心；\n3、通过用户调研、产品数据分析、行业调研、业务专题讨论等多种手段，抽象产品能力，驱动电商治理问题得到解决，提升运营工作效率；\n4、推进内部交流，协同业务团队、算法、研发团队，保证团队合作的顺畅，及跨横向团队间的协作等。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程、数据、人工智能等相关专业优先；\n2、拥有AI产品/B端/平台产品工作经验，具备出色的学习能力和逻辑思维，跨团队协同能力强，能够深入业务，理解业务，有自驱力目标导向；\n3、熟悉产品全生命周期管理，能够高效的与技术、算法团队沟通，并转化成可行的产品方案。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667086447781988661","sourceKey":"bytedance","company":"字节跳动","title":"AI全栈工程师（东南亚业务） - TikTok Shop","city":"北京/上海/深圳","category":"前端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667086447781988661/detail","duty":"团队介绍：TikTok Shop是以TikTok为载体的内容电商业务，致力于成为用户发现并获取优价好物的首选平台，在直播电商、视频内容电商等多场景下，TikTok Shop希望能为用户提供更个性化、更主动、更高效的消费体验，为商家提供稳定可靠的平台服务，在更多的地区实现没有难卖的优价好物，让美好生活触手可得的使命。我们邀请你来此成长、钻研，发掘无限的潜力，一起应对技术和业务上的挑战。目前团队拥有丰富的国际产品研发经验，包容多元的文化，且在全球设立研发团队，邀请你来一起接受跨国合作的挑战！\n\n1、参与TikTok Shop东南亚业务的研发工作，包含从前端页面、服务端接口、数据链路到上线验证的端到端全栈交付；\n2、参与TikTok Shop前端与全栈工程建设，包括：数据模型抽象、性能优化、用户体验优化；\n3、基于AI Coding工具，建设需求理解、方案生成、代码实现、测试验证、Code Review和线上排障的AI辅助研发流程，提升需求效率与质量，参与AI工程化能力在真实业务中落地；\n4、基于东南亚业务场景和Agent应用，参与设计AI业务落地场景，帮助业务提效、解决业务痛点。","requirements":"1、2027届获得本科及以上学历，计算机相关专业优先；\n2、具备扎实的计算机基础和优秀的工程编码能力，熟悉至少一门主流编程语言或技术栈（TS/Go/Java/Android/iOS），能够在指导下完成模块的方案设计、开发实现、问题定位和性能优化；\n3、具备较强的全栈工程能力，理解前后端之间的协作方式，能够围绕AI产品场景完成从交互体验、接口设计、服务实现到上线交付的闭环；\n4、对Agent技术在研发场景有一定了解，在AI Coding、Skills、Prompt Engineering、RAG、Embedding、Tool Calling、MCP、结构化输出、AI评测等任一方向有实践经验；\n5、具备良好的问题拆解能力、逻辑分析能力和快速学习能力，能够从一定复杂度的场景中抽象问题、设计方案，并完成交付。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7655179901108947253","sourceKey":"bytedance","company":"字节跳动","title":"PMO实习生 - Data AML","city":"北京","category":"项目管理","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7655179901108947253/detail","duty":"团队介绍：Data AML是字节跳动的机器学习中台，为抖音/今日头条/西瓜视频等业务提供推荐/广告/CV/语音/NLP的训练和推理系统。为公司内业务部门提供强大的机器学习算力，并在这些业务的问题上研究一些具有通用性和创新性的算法。同时，也通过火山引擎将一些机器学习/推荐系统的核心能力提供给外部企业客户。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、负责跟进大模型相关项目的里程碑与关键节点，输出项目进度跟踪表、风险台账，及时预警延期风险，保障项目按计划推进；\n2、协助推动大模型项目的需求对齐、跨团队协作与任务闭环，跟进开发、评测、上线等关键环节，确保项目流程顺畅、问题快速响应；\n3、协助规范大模型项目的PMO流程，优化项目管理工具的使用，维护项目过程数据的准确性，保障项目按标准化流程推进；\n4、制作项目周报、月报、流程说明等文档，将项目关键节点、进展状态在团队内同步，提升信息传递效率；\n5、协助组织项目例会、整理会议纪要，跟进会议决议的落地执行，完成与项目推进相关的其他日常工作。","requirements":"1、本科及以上学历在读，计算机、软件工程相关专业优先；\n2、每周可到岗4-5天，可连续实习，能稳定参与项目全周期；\n3、英语能力优秀，可支撑工作场景使用；\n4、有项目管理或算法相关实习经验优先；有AI、英语背景优先；\n5、具备较强的沟通协作、跨团队推进能力，以及目标导向的执行与问题解决能力；\n6、责任心强，能快速适应变化，具备持续学习能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7629177462161852725","sourceKey":"bytedance","company":"字节跳动","title":"AI驱动的新一代计算化学方法与应用研究 - AI for Science","city":"北京/深圳/上海","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7629177462161852725/detail","duty":"团队介绍：AI for Science 团队专注于科学计算与物质发现领域的前瞻技术探索，围绕生物和材料领域基础模型、量子化学、AI分子动力学、高通量实验技术等方向，用 AI 推动科学领域的研究范式突破，也在实际应用场景中创造价值。我们希望用 AI 赋能科学，探索 AI 在科研领域的变革，拓展人类认知边界！\n\n课题介绍：\n在人工智能快速发展的背景下，计算化学作为“AI for Science”的重要方向之一，近年来取得了显著进展。数据驱动方法在分子性质预测、材料筛选等任务中展现出良好潜力，但在强关联分子与复杂材料体系等关键问题上，仍面临基础性挑战：高精度方法算不大，高效率方法算不准。这一瓶颈导致计算结果与实验观测之间仍存在明显差距，限制了其在实际应用中的广泛落地。 本课题拟在此背景下，探索人工智能与计算化学方法的深度融合，发展兼具精度与效率的新一代计算化学方法，提升复杂体系的模拟能力与预测可靠性，推动计算结果向实验可验证与实际可用的方向迈进，为材料设计、催化与分子工程等领域提供关键方法支撑。\n\n课题挑战：\n1、黑盒模型在物理、化学问题中的泛化性；\n2、物理先验与AI模型的有效结合；\n3、适应科学场景的新模型、新优化方法的研发；\n4、小样本学习在复杂化学问题中的有效性。\n\n课题价值：\n1、为复杂分子体系与材料体系提供可扩展的计算化学工具，降低高精度计算的门槛；\n2、加速新材料、新催化剂及功能分子的设计与筛选过程；\n3、为大规模化学空间探索提供可行路径，支持高通量计算与自动化研究。","requirements":"1、2027届毕业，获得博士学位；计算机科学、机器学习、物理、化学、数学等相关专业优先；\n2、有扎实数学基础及良好编程能力；\n3、具有独立研究和创新的才能，能够在跨学科的环境中成长；\n4、持续关注人工智能前沿发展，熟练使用各类AI工具。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7623004282471614773","sourceKey":"bytedance","company":"字节跳动","title":"音频多模态算法实习生-Seed大模型人才实习","city":"北京","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7623004282471614773/detail","duty":"团队介绍：字节跳动 Seed 团队成立于 2023 年，致力于寻找通用智能的新方法，追求智能上限，为科技和社会发展作出贡献。\nSeed 团队在 AI 领域拥有长期愿景与决心，团队研究方向涵盖 MLLM、GenMedia、AI for Science、机器人等，在中国、新加坡、美国等地设有实验室和岗位。目前，团队已推出业界领先的通用大模型以及前沿的多模态能力，支持豆包、即梦、TRAE 等超过 50 个应用场景，并通过火山引擎开放给企业客户。第三方数据显示，豆包 App 用户量在中国市场排名第一，豆包大模型日均 Token 调用量行业领先。\n\n1、参与研发多模态大模型等下一代人工智能核心技术，挑战最具颠覆性的AI前沿工作，参与构建全球领先的Seed音频多模态基座大模型，探索下一代AI；\n2、关注和推进技术在业务场景中的广泛应用，包括但不限于语言、音乐、语音、音频的生成与理解等；\n3、深入调研和关注音频/LLM/VLM等方向的前沿技术。","requirements":"1、2028届及以后本科及以上学历在读，人工智能、计算机、自动化、数学相关专业优先；\n2、怀有科技改变世界的远大抱负，有志于投身机器学习、人工智能、大模型、多模态理解和生成等技术领域；\n3、有自然语言处理、语音合成与识别、音乐生成等研究或者技术背景优先；在ACL/EMNLP/NAACL/NeurIPS/ICML/ICLR/ICASSP/Interspeech等顶级会议上发表论文者优先；\n4、优秀的代码能力、数据结构和基础算法功底，熟练C/C++或Python，ACM/ICPC、NOI/IOI、Top Coder、Kaggle等比赛获奖者优先；\n5、在大模型领域或者RL领域，主导过有影响力的项目或论文者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7623002843758872885","sourceKey":"bytedance","company":"字节跳动","title":"音频多模态算法实习生-Seed大模型人才实习","city":"北京","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7623002843758872885/detail","duty":"团队介绍：字节跳动 Seed 团队成立于 2023 年，致力于寻找通用智能的新方法，追求智能上限，为科技和社会发展作出贡献。\nSeed 团队在 AI 领域拥有长期愿景与决心，团队研究方向涵盖 MLLM、GenMedia、AI for Science、机器人等，在中国、新加坡、美国等地设有实验室和岗位。目前，团队已推出业界领先的通用大模型以及前沿的多模态能力，支持豆包、即梦、TRAE 等超过 50 个应用场景，并通过火山引擎开放给企业客户。第三方数据显示，豆包 App 用户量在中国市场排名第一，豆包大模型日均 Token 调用量行业领先。\n\n1、参与研发多模态大模型等下一代人工智能核心技术，挑战最具颠覆性的AI前沿工作，参与构建全球领先的Seed音频多模态基座大模型，探索下一代AI；\n2、关注和推进技术在业务场景中的广泛应用，包括但不限于语言、音乐、语音、音频的生成与理解等；\n3、深入调研和关注音频/LLM/VLM等方向的前沿技术。","requirements":"1、2028届及以后本科及以上学历在读，人工智能、计算机、自动化、数学相关专业优先；\n2、怀有科技改变世界的远大抱负，有志于投身机器学习、人工智能、大模型、多模态理解和生成等技术领域；\n3、有自然语言处理、语音合成与识别、音乐生成等研究或者技术背景优先；在ACL/EMNLP/NAACL/NeurIPS/ICML/ICLR/ICASSP/Interspeech等顶级会议上发表论文者优先；\n4、优秀的代码能力、数据结构和基础算法功底，熟练C/C++或Python，ACM/ICPC、NOI/IOI、Top Coder、Kaggle等比赛获奖者优先；\n5、在大模型领域或者RL领域，主导过有影响力的项目或论文者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7622492139368597765","sourceKey":"bytedance","company":"字节跳动","title":"大语言模型预训练算法工程师-Seed大模型人才校招","city":"北京","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7622492139368597765/detail","duty":"Seed 大模型人才校招，是字节跳动 Seed 面向高校人才推出的招聘项目。我们始终相信，真正重要的技术进步来自对高难度问题的持续挑战。面对 AI 时代的巨大机遇，Seed 团队并不止步于模型迭代，而是选择进入技术深水区，推进下一代 AI 范式突破，不断探索智能的边界与上限。\n\n团队介绍：字节跳动 Seed 团队成立于 2023 年，致力于寻找通用智能的新方法，追求智能上限，为科技和社会发展作出贡献。Seed 团队在 AI 领域拥有长期愿景与决心，团队研究方向涵盖 MLLM、GenMedia、AI for Science、机器人等，在中国、新加坡、美国等地设有实验室和岗位。目前，团队已推出业界领先的通用大模型以及前沿的多模态能力，支持豆包、即梦、TRAE 等超过 50 个应用场景，并通过火山引擎开放给企业客户。第三方数据显示，豆包 App 用户量在中国市场排名第一，豆包大模型日均 Token 调用量行业领先。\n\n1、预训练和持续学习：大规模预训练、持续学习和自主迭代，突破自然语料、多模态、上下文和记忆的瓶颈；\n2、大语言模型数据科学：压缩世界知识和经验，构建基础模型智能的深厚内在和锋利边界；\n3、Scaling机制和最优化：解读模型的优化动态，用数学物理和实验科学，祛除“炼丹炉”上的阴霾；\n4、通用效率优化：让数据更快迭代，让训练更快收敛，让评估更快置信，让实验更快见效，让下一代智能更早浮现。","requirements":"1、2027届获得本科及以上学历，计算机、数学、统计等相关专业；\n2、优秀的代码能力、数据结构和基础算法功底，熟练C/C++或Python/Rust，熟悉Vibe coding和Agent工程则更优；拥有扎实的数学功底和机器学习理论基础；\n3、熟悉NLP/CV相关算法和技术，熟悉预训练、后训练算法，在相关领域有良好研究记录者优先，在大模型领域主导过大影响力的项目或论文者优先。\n\n我们期待你是潜在的：\n1、以数据为AI底层代码的编码圣体；\n2、以模型为产品的迭代高手；\n3、以研究为事业的超级个体。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7615215714170194229","sourceKey":"bytedance","company":"字节跳动","title":"跨端/客户端开发实习生-红果短剧","city":"上海","category":"客户端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7615215714170194229/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：红果短剧是抖音集团2023年推出的免费看剧产品，致力于为用户提供海量免费优质短剧，同时也为用户提供电影、电视剧、小说、有声书等多元内容，满足不同用户的内容消费需求。\n\n1、负责字节跳动红果短剧产品的客户端开发，编写高质量的代码；\n2、和产品经理配合，深度参与产品需求讨论、功能定义等。","requirements":"1、2027届本科及以上学历在读，计算机等相关专业优先；\n2、热爱计算机科学和互联网技术，对移动产品有浓厚兴趣；\n3、扎实的数据结构和算法基础；精通至少一门编程语言，包括但不限于：Java、Objective-C、Swift、C、C++；\n4、关注用户体验，能够积极把技术转化到用户体验改进上；\n5、对新技术保持热情，具备良好的分析、解决问题的能力；\n6、接触过移动端开发者优先；学习能力强，可在移动端零基础培养状态下快速成长的同学优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7591414964634355973","sourceKey":"bytedance","company":"字节跳动","title":"数据产品实习生（SEA业务洞察） - TikTok Shop","city":"上海","category":"产品经理","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7591414964634355973/detail","duty":"团队介绍：TikTok Shop是以TikTok为载体的内容电商业务，致力于成为用户发现并获取优价好物的首选平台，在直播电商、视频内容电商等多场景下，TikTok Shop希望能为用户提供更个性化、更主动、更高效的消费体验，为商家提供稳定可靠的平台服务，在更多的地区实现没有难卖的优价好物，让美好生活触手可得的使命。我们邀请你来此成长、钻研，发掘无限的潜力，一起应对技术和业务上的挑战。目前团队拥有丰富的国际产品研发经验，包容多元的文化，且在全球设立研发团队，邀请你来一起接受跨国合作的挑战！\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、深度挖掘业务痛点，梳理真实和有效的分析需求，跟进产品原型和方案设计，撰写高质量的产品需求文档（PRD），并推动项目开发实施和上线的完整流程；\n2、负责业务数据看板的全链路交付，从指标体系梳理，到数据分析看板的搭建，数据验证，推动看板上线并不断迭代升级；\n3、协助平台日常运营推广，包括但不限于制作双语宣传推广材料、组织功能使用培训，并建立基于用户反馈的持续产品迭代机制。","requirements":"1、本科及以上学历在读；\n2、过往在电商业务、BI分析工具领域有实习经验者优先，有基础的数据分析、数据整理能力，能使用SQL、Python、Tableau、Excel优先；\n3、逻辑性强，善于拆解问题，较熟练使用Figma、Axure或其他原型工具，责任心强，善于沟通协作，同时具备较强自驱力，细致耐心；\n4、实习6个月及以上优先，英语熟练，可作为工作语言者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7561337145907038525","sourceKey":"bytedance","company":"字节跳动","title":"软硬件协同实习生-服务器","city":"北京","category":"后端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7561337145907038525/detail","duty":"日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n团队介绍：服务器部门的主要职责是通过持续开展业务需求跟踪和行业洞察，以及对各业务场景开展系统性能分析，为公司的全球业务打造具备高性价比和高可靠性的通用计算、存储和智能计算（AI）等产品与解决方案。在技术层面，深入钻研计算体系架构的研究与开发、CPU/GPU及部件的定制与评估、高速电路设计、新型供电散热技术、固件开发、驱动开发、内核及操作系统、编译器、可靠性、可用性和可维护性（RAS）等领域，推动软硬件的联合设计与优化，在人工智能时代为公司提供最具竞争力的算力和存储基础支撑。\n\n1、开发和使用性能分析工具、性能模拟器、仿真工具进行实验，验证通算和智算领域新架构方案的性能收益；\n2、研究和分析数据中心关键Workload的特征，探索软硬件协同设计与优化方案；\n3、参与CPU、GPU及其他开放架构生态的研究，探索开源软硬件协同优化的可能性；\n4、撰写研究报告，并有机会参与学术论文或专利的撰写。","requirements":"1、本科及以上学历在读，计算机体系结构、电子工程、计算机科学等相关专业优先；\n2、具备良好的编程能力，熟悉C/C++、Python；\n3、熟悉计算机体系结构基本知识，如流水线、缓存、分支预测、乱序执行等；\n4、了解x86、ARM、RISC-V或其他主流CPU指令集，有相关优化经验者优先；\n5、熟悉CPU、GPU性能分析工具和仿真器，如Perf、VTune、Gem5、Simics、GPGPU-Sim等；\n6、具备良好的分析能力和研究能力，有学术论文发表经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7439641248027298056","sourceKey":"bytedance","company":"字节跳动","title":"技术产品实习生（AI基础与应用方向）-中国交易与广告","city":"上海","category":"产品","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7439641248027298056/detail","duty":"日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n团队介绍：中国交易与广告，负责抖音电商、生活服务、广告营销等营收业务的研发。用技术带来美好生活，让用户发现更多优价好物，为用户提供更丰富独特的生活体验；连接海量用户与商家，促进交易达成，让生态里全流程体验更流畅，助力营收业务长效增长。\n加入团队，你将投身流量与增长主战场，挑战复杂业务场景技术难题；直面真实商家和用户，用技术解决看得见的问题，在实战中快速成长，书写属于你的价值故事！\n\n1、负责大语言模型在RAG知识问答、查询诊断类插件场景的落地，制定应用层的产品策略；\n2、协同运营和研发，负责Agent产品的应答能力提升，包括知识运营及策略梳理，实现产品的核心指标提升；\n3、负责各类模型的效果评测、归因，并制定模型的优化策略。","requirements":"1、本科及以上学历在读，计算机、通信、数据分析等相关专业优先；\n2、具备良好的中文基础，能够从语法、结构等角度抽象大模型的应答策略，了解大模型的基本原理和技术边界；\n3、具备优秀的沟通推动能力、结构化表达能力、总结归纳能力、业务理解能力及逻辑思维能力，工作中表现出较强的自驱性与责任感；\n4、实习周期半年以上，每周不少于4个工作日。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668574691846031669","sourceKey":"bytedance","company":"字节跳动","title":"策略运营 - 抖音生活服务","city":"上海/北京","category":"产品运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668574691846031669/detail","duty":"团队介绍：抖音生活服务依托抖音POI （Point of Interest）、短视频、直播、搜索等，以“激发线下生意，丰富美好生活”为使命，致力于成为最值得信赖的生活服务平台，为用户提供更丰富、独特的生活体验，为合作伙伴提供包容且公平的健康营商生态。截至2025年底，抖音生活服务业务已覆盖400+城市，超过1500万家动销门店。抖音生活服务将继续携手生态伙伴，为用户提供值得心动的商品和服务。\n\n1、深入业务场景，洞察商家在管理与经营中的痛点，制定并迭代可落地的策略方案，帮助商家提升经营效率与管理能力；\n2、站在平台视角，推动行业健康增长从抖音平台的视角理解房产行业生态，面向行业不同角色（如商家、经纪人、门店等）设计激励与牵引机制，促进生态的长期、可持续发展；\n3、用数据驱动决策，把问题拆清楚跟进业务核心指标变化，对异常波动进行归因分析，深入挖掘根因，提出可验证、可推进的优化建议，并推动闭环；\n4、把想法产品化、工具化，提升效率基于业务需求沉淀方法论，输出产品功能或工具建设建议，推动策略落地规模化，让“做对一次”变成“长期可复用”。","requirements":"1、2027届获得本科及以上学历，专业不限；\n2、踏实靠谱，有基础的数据能力：能做基础的数据处理与分析，并愿意用数据验证判断、支撑决策；\n3、有项目推进意识与主人翁精神，沟通清晰、能协同多方把事情做成；\n4、持续学习，喜欢挑战和独立思考，并敢于提出观点与方案。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668545535465474309","sourceKey":"bytedance","company":"字节跳动","title":"搜索产品运营 - TikTok Shop","city":"上海","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668545535465474309/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商。平台汇聚全球优质商家与创作者，通过短视频、直播等多场景连接消费者，让新奇好物畅销全球，让美好生活触手可得。目前团队分布在美国、英国、法国、印尼、墨西哥、中国等全球多个国家和地区，在这里你将有机会深入国际业务场景，面向全世界商家及用户，和跨区域团队协作，共同探索创新购物模式。期待和优秀的你一起创造更多可能！\n\n1、负责国际化业务的电商搜索场景，直播及短视频搜索入口，及电商相关推荐场景中的策略优化，与产品、数据、算法、技术等多团队协同，制定产品和实验方案设计，对人群实验框架和增长指标进行细致分析，对增长结果直接负责；\n2、了解各类产品链路和风险，分析产品功能现有策略暴露的问题，制定有效的人群、场景、渠道和内容策略，并推动策略落地，持续提升用户在搜索推荐场景中的体验；\n3、负责根据目前的策略，制定并培训可执行的运营流程，与当地团队协作，完成对与推荐体验相关策略的评估；\n4、具有较强的电商类视频、直播、商品及节日大促的认知，独立完成产品功能现状分析，搭建评估流程，进行体验评估验证分析结论，能对产品进行可用性测试和分析，并提出改进方案。","requirements":"1、2027届获得本科及以上学历；\n2、有产品运营相关实习经验，对电商业务有较好认知；有搜索、推荐、广告领域实习经验优先；自驱力强，逻辑清晰，乐于分析事件本质，擅长系统性的解决问题，亲和力强，沟通和协同能力，擅长牵引跨部门的合作达成；\n3、具备优秀的数据分析能力和敏锐的问题挖掘能力，擅长通过波动的数据去合理的归因；\n4、独自承担用户体验视角下的产品项目管理和方案设计，具备创新思维，实现用户体验上的突破。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668197821772253445","sourceKey":"bytedance","company":"字节跳动","title":"物流计划&经营分析 - TikTok Shop","city":"上海","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668197821772253445/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商。平台汇聚全球优质商家与创作者，通过短视频、直播等多场景连接消费者，让新奇好物畅销全球，让美好生活触手可得。目前团队分布在美国、英国、法国、印尼、墨西哥、中国等全球多个国家和地区，在这里你将有机会深入国际业务场景，面向全世界商家及用户，和跨区域团队协作，共同探索创新购物模式。期待和优秀的你一起创造更多可能！\n\n1、完成国际电商跨境业务的S&OP需求预测全流程，整合历史销售数据、市场趋势及业务目标和促销计划，生成周、月、季度出库量预测数据，为干线运营提供决策依据；\n2、监控预测准确性，定期复盘预测偏差（如大促期间波动），优化预测算法及参数，持续提升预测精度；跟踪预测目标达成情况，分析未达标原因，联动相关团队调整策略，确保出库量与业务目标偏差率控制在可接受范围；\n3、与上游团队深度协作，对齐销售目标、促销计划及库存策略，确保预测数据与业务节奏一致；\n4、持续优化端到端S&OP流程框架，建立需求预测沟通机制，定期组织跨部门评审会（如周度S&OP会议），同步预测调整及执行进展；\n5、联动产品技术和数据资源，以及供应链计划域产品和研发等相关团队合作，对预测和监控系统推进优化和迭代；\n6、负责国际电商跨境物流成本的深入分析，基于项目，深入业务视角，做好成本数据的分析，支持运营团队的决策使用。","requirements":"1、2027届获得本科及以上学历，供应链与物流、数据、统计学等相关理工科专业优先；\n2、熟悉电商供应链、跨境物流业务模式，有S&OP、需求预测或供应链计划相关实习经验者优先；\n3、数据分析基础扎实，能够熟练使用供应链相关数字化工具；\n4、具备问题拆解、跨团队沟通与协同推进能力，英语可作为工作语言；\n5、学习能力和执行力较强，逻辑清晰，善于表达观点并推动落地。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667171107864692997","sourceKey":"bytedance","company":"字节跳动","title":"安全开发工程师 - 安全与风控","city":"杭州","category":"安全","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667171107864692997/detail","duty":"团队介绍：我们通过部署先进的安全系统、推行标准化操作流程，构建基于零信任的安全防护体系，提升字节跳动全球办公环境的整体安全态势。我们坚持以主动预防为核心，同时构建敏捷高效的安全响应能力，为全球办公环境提供持续、可靠的安全保障。\n\n1、参与研发和迭代内部安全系统，包括办公网络准入控制、办公终端安全管控系统等，建设字节跳动零信任办公安全基础设施；\n2、解决日常安全业务开发需求，设计可扩展的业务功能模块，建设和沉淀通用解决方案和功能模块；\n3、建设安全验证能力框架，度量企业安全防护能力和管控效率，持续保障企业信息安全无漏水。","requirements":"1、2027届获得本科及以上学历，计算机、信息安全等相关专业优先；\n2、具备良好的计算机系统科学基础，逻辑能力强；\n3、熟悉以下至少一种编程语言：Golang、Python、Java、Rust、C/C++；\n4、具有用户视角的业务理解能力，具备独立解决问题的能力、良好的团队合作意识与沟通能力。\n\n加分项\n1、有业务系统的运维经验的优先；\n2、对AI Agent有强烈兴趣，并解决过实际问题的优化；\n3、可以熟练使用英文进行日常和专业沟通无障碍的同学优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667165600451725573","sourceKey":"bytedance","company":"字节跳动","title":"内容作者运营(DE) - 剪映CapCut","city":"上海","category":"用户运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667165600451725573/detail","duty":"团队介绍：剪映CapCut团队成立七年，先后孵化了剪映、CapCut、醒图、Hypic、即梦、Dreamina、Pippit等产品，覆盖视频、图片、Al生成、视频营销等多领域，打造与AI结合的全球化产品矩阵。\n我们的愿景是：激发想象力，成为全球领先的互动内容平台，创造独特的体验和价值。\n我们期待你的加入，一同极致打磨用户体验,构建创意生态和商业化能力，定义AI与创作结合的无限可能，让内容互动更简单、更精彩!\n\n1、根据业务目标筛选欧洲创作者资料并建立联系，同时协助开展创作者教育，并向本地创作者分享灵感与创作方向；\n2、社区运营：与本地创作者保持日常沟通，了解其在模板创作中的痛点，总结共性问题并推动解决方案落地；\n3、活动创意共创：围绕节日节点和新产品功能，策划模板创意方向，并将其作为灵感分享给创作者，跟进后续创作进度；\n4、趋势追踪：每日收集全球及区域热门趋势，协助团队产出更符合欧盟市场本地化需求的内容。","requirements":"1、2027届获得本科及以上学历；\n2、具备扎实的视频剪辑能力（可使用PC或移动端平台进行剪辑），英语可作为工作语言，并熟练使用德语或法语，以便与欧盟/德国/法国市场的相关方及外部客户进行高效沟通；\n3、深度熟悉主流社交媒体平台（TikTok、Instagram或YouTube），并对「欧洲/德国/法国」的文化有较强理解；\n4、对内容趋势高度敏感，能够快速捕捉社交媒体热点，有社交媒体账号运营经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7664851280653257013","sourceKey":"bytedance","company":"字节跳动","title":"AI全栈工程师（广告业务） - 中国交易与广告","city":"深圳","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7664851280653257013/detail","duty":"团队介绍：中国交易与广告，负责抖音电商、生活服务、广告营销等营收业务的研发。用技术带来美好生活，让用户发现更多优价好物，为用户提供更丰富独特的生活体验；连接海量用户与商家，促进交易达成，让生态里全流程体验更流畅，助力营收业务长效增长。\n加入团队，你将投身流量与增长主战场，挑战复杂业务场景技术难题；直面真实商家和用户，用技术解决看得见的问题，在实战中快速成长，书写属于你的价值故事！\n\n1、依托各类AI Coding工具，独立完成广告业务相关项目的前后端全栈开发、功能迭代与接口联调，负责前/后端技术选型和开发工作，参与方案设计，保障业务需求高质量落地；\n2、主导或参与前后端基础设施建设，包括组件库沉淀、工程化工具链优化、CI/CD流程改进，提升团队研发效率；\n3、与产品、算法等团队紧密协作，推动跨团队技术方案对齐，保障项目按时交付；\n4、参与Agent在广告业务场景中的落地探索（如Agent产品交互开发、工作流编排等），利用AI Coding工具提升个人及团队开发效率，跟进前沿Agent开源方案，沉淀可复用的调度模板与工程最佳实践。","requirements":"1、2027届获得本科及以上学历，计算机、人工智能、软件工程等相关专业；\n2、掌握Python/Go/Java/JavaScript任意2门开发语言，熟悉Node.js/Go，具备前后端一体化开发能力；\n3、理解LLM基础原理，熟悉AI Agent核心模块（Prompt、记忆机制、工具调用、RAG、多智能体），能区分不同层级模型的业务适用场景；\n4、熟练掌握主流AI编码工具（TRAE、Claude Code、Codex等），能够利用AI完成需求拆解、代码编写、复杂逻辑重构、Bug定位修复、单测编写、代码评审，具备AI协同研发思维；\n5、熟悉Git基础操作，具备良好的沟通能力与团队合作精神；对技术保持好奇心，善于独立思考并反思总结；\n6、有相关岗位实习及项目开发经历优先。\n\n加分项：\n1、有AI辅助前后端全栈开发、Agent项目部署与二次开发实战经验；\n2、实操过Agent任务拆分、多智能体并行调度、模型自动择优等核心功能；\n3、熟悉MCP协议、LLM工具调用、AI自动化工作流搭建；\n4、有对话应用、智能编排、知识库平台等相关项目开发经验。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7622248262099667253","sourceKey":"bytedance","company":"字节跳动","title":"视觉多模态应用算法实习生-Seed大模型人才实习","city":"深圳","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7622248262099667253/detail","duty":"团队介绍：字节跳动 Seed 团队成立于 2023 年，致力于寻找通用智能的新方法，追求智能上限，为科技和社会发展作出贡献。\nSeed 团队在 AI 领域拥有长期愿景与决心，团队研究方向涵盖 MLLM、GenMedia、AI for Science、机器人等，在中国、新加坡、美国等地设有实验室和岗位。目前，团队已推出业界领先的通用大模型以及前沿的多模态能力，支持豆包、即梦、TRAE 等超过 50 个应用场景，并通过火山引擎开放给企业客户。第三方数据显示，豆包 App 用户量在中国市场排名第一，豆包大模型日均 Token 调用量行业领先。\n\n参与AI及多模态前沿技术的研究与落地，跟踪领域最新进展、复现前沿论文，并将技术创新应用到真实产品场景中，推动模型在测试与应用阶段的持续迭代；你将深度参与以下一或多个方向的研发工作： \n1、多模态大模型Post-training全链路优化：参与SFT、RL、Agent训练等核心算法的调优与创新，围绕搜索、教育、医疗等业务场景进行定向能力打磨，提升模型在真实任务中的效果与稳定性；\n2、视频通话AI体验与多模态融合：参与视频通话基础AI能力的优化，包括视觉理解、长多轮对话、逻辑推理、联网搜索等；同时参与创新特性研发，如视频Memory、智能主动响应、音视频双工等，并推动多模态推理、智能体等技术在产品中的落地；\n3、可穿戴硬件端AI能力与端云协同：协同优化端侧执行链路与服务端多模态模型的适配效果，打通端云协同流程，提升视频通话及硬件联动场景下的端到端体验；\n4、手机助手基础体验与智能特性研发：参与手机助手的视觉理解、工具调用、跨应用任务规划等基础能力优化；同时参与手机Memory、GUI Agent、Intent理解等新特性的研究与落地，提升整体交互体验。","requirements":"1、2028届及以后本科及以上学历在读，人工智能、计算机、自动化、数学等相关专业优先；\n2、扎实的数据结构与算法基础，熟练掌握Python和PyTorch，有RL、多模态大模型、GUI Agent、Tool Use经验者优先；\n3、良好的英文读写能力与数学基础；\n4、有大模型相关研究或项目经验者优先，在顶会发表论文或在多模态、CV、ML比赛中取得优异成绩者优先；\n5、责任心强，积极主动，具备良好的沟通与团队协作能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7613237638787270917","sourceKey":"bytedance","company":"字节跳动","title":"直播后台开发实习生-音视频技术","city":"北京","category":"后端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7613237638787270917/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：视频与边缘部门承载了字节跳动的媒体内容分发基建及技术中台，支持了字节全系产品，如抖音、今日头条、番茄小说、西瓜视频等APP的点播、直播、实时通信、图片等多媒体业务发展，同时将业务发展过程中沉淀下来的技术能力和工具，通过火山引擎对外输出，面向各行各业用户提供视频云产品和服务，愿景是为内外部业务伙伴提供最低成本、最优画质、最低延时、最安全可靠的富媒体内容分发解决方案，助力业务伙伴降本提效实现持续增长。\n\n1、参与字节跳动流媒体处理平台的业务功能开发、调度系统开发和整体框架设计，包括转码、录制、截图、RTC混流、AI创新应用等具体功能，支撑抖音、今日头条、豆包等多个产品；\n2、参与需求分析，实现产品模块、核心代码的编写；\n3、不断对系统优化，分析和预估可能的风险，保障系统稳定性。","requirements":"1、2027届本科及以上学历在读，计算机科学、软件工程或相关专业优先；\n2、熟悉Go语言开发，或者有扎实的C/C++基础，熟悉常用的算法和数据结构，熟悉TCP/IP协议栈；\n3、熟悉数据库技术，如SQL，Mongo，Redis等；\n4、熟悉消息队列，如Kafka；熟悉ZooKeeper；熟悉Docker、K8s等技术；\n5、有基本的流媒体知识和图像处理知识，使用过FFmpeg；\n6、有大模型应用于多媒体处理的经验是加分项，比如数字人、视频生成、翻译等。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7593244792345086213","sourceKey":"bytedance","company":"字节跳动","title":"安全攻防实习生-安全与风控","city":"北京","category":"安全","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7593244792345086213/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：我们团队致力于通过对攻防技术的持续研究，最大限度降低零日漏洞与安全事件造成的影响。我们提供红队演练、威胁检测、安全保障工具支持及事件调查等服务，助力提升系统韧性。通过不断强化攻防两端能力，我们在巩固公司核心安全基础、保障数据与业务安全方面发挥着关键作用。\n\n1、AI赋能红队：将大模型、机器学习等技术应用于红队攻防，搭建自动化攻击工具，提升漏洞挖掘、红队攻防效率；\n2、AI安全红队：开展AI系统（大模型/AI应用等）安全测试，挖掘数据、算法、对抗攻击等方面的安全风险；\n3、参与实战演练与技术预研，跟踪前沿动态，总结攻防经验，优化技术方案与工具；\n4、撰写技术文档/测试报告，参与团队分享，协助提升团队AI攻防综合能力。","requirements":"1、2027届本科及以上学历在读，计算机/信息安全/人工智能等相关专业优先；\n2、对红队攻防、AI安全领域有浓厚兴趣，了解基础的Web渗透、漏洞挖掘概念者优先；\n3、了解至少一种AI框架（TensorFlow/PyTorch等）基础用法，对大模型应用、对抗攻击有初步认知者优先；\n4、熟悉Python编程语言，具备基础的代码编写与简单工具使用能力；\n5、学习能力强、态度积极，具备良好的沟通能力与团队协作意识。\n\n加分项：\n1、有CTF比赛参与经历、在校AI/安全相关项目经验，或相关技术博客/开源贡献者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7686332540506802437","sourceKey":"bytedance","company":"字节跳动","title":"创意视觉与AI工具设计（特效方向）实习生 - TikTok设计","city":"上海","category":"设计","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7686332540506802437/detail","duty":"团队介绍：TikTok是一个覆盖150个国家和地区的国际短视频平台，我们希望通过TikTok发现真实、有趣的瞬间，让生活更美好。TikTok在全球各地设有办公室，全球总部位于洛杉矶和新加坡，办公地点还包括纽约、伦敦、都柏林、巴黎、柏林、迪拜、雅加达、首尔和东京等多个城市。\n\nTikTok设计团队的目标是为全球数亿用户提供一流的用户体验，从而帮助用户更好的创作与表达，发现世界的多元与美好，不断打破隔阂，建立起人与人的连接。我们是一个国际化的设计团队，遍布中国、美国、新加坡等国家，世界各地的产品设计师、创意设计师、效果设计师、内容文案专家与本地化经理通力合作，把一个个不可能变成可能。\n\n加入我们，你就有机会理解世界不同地域的文化差异，分析并解决复杂的体验问题，进行前沿的设计探索，更能亲身主导如何把一个想法转化成服务亿级数量用户的产品体验。 如果你积极自驱，对世界充满好奇心和想象力，有希望通过设计打造一流的产品，同时又脚踏实地，欢迎成为我们的一员！\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、创作者模板定义（Effect House）：聚焦Effect House工具生态，针对全球创作者开发低门槛、高品质的互动游戏及音视频特效模板；\n2、AI驱动的逻辑构建：熟练运用Claude、Codex等AI工具辅助搭建游戏化交互逻辑，快速将创意想法转化为可落地的互动Demo；\n3、极致视觉与多风格探索：保持较高视觉审美，深入钻研设计细节与创意表达，能够自如切换视觉风格，输出包容性强的UI与视觉资产；\n4、高潜AI项目跟进：保持对生成式AI技术的敏锐追踪，在导师（Mentor）带领下，快速学习并参与团队内前沿AI探索性项目。","requirements":"1、本科及以上学历在读，交互设计、视觉传达设计、数字媒体艺术、人机交互（HCI）或相关设计专业；\n2、视觉审美与细节把控能力：具备视觉设计基本功，对色彩、排版、数字图形及UI细节有较高要求；\n3、创意逻辑与AI探索：对“设计背后的逻辑”有清晰的思考，能够熟练使用Claude、Codex等大模型工具进行交互逻辑梳理；\n4、敏捷学习力：具备自驱力与适应力，能迅速跟进并消化全新的AI设计工具与多变的项目类型。\n\n加分项：\n1、双语沟通：具备优秀的中英双语（中文和英语）沟通能力，能够流畅地与跨国产品、技术和运营团队对齐思路；\n2、重度特效/游戏玩家：热爱创意探索，喜欢玩游戏、拍摄滤镜特效、剪辑Vlog，对短视频平台的流行趋势极度敏感；\n3、设计多样性：拥有独立且完整的多风格创意设计项目作品集（有成功上架或有实际用户体验过的项目优先）。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7683125670243207429","sourceKey":"bytedance","company":"字节跳动","title":"拉美市场电商交易产品实习生 - TikTok Shop","city":"上海","category":"产品","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7683125670243207429/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商。平台汇聚全球优质商家与创作者，通过短视频、直播等多场景连接消费者，让新奇好物畅销全球，让美好生活触手可得。目前团队分布在美国、英国、法国、印尼、墨西哥、中国等全球多个国家和地区，在这里你将有机会深入国际业务场景，面向全世界商家及用户，和跨区域团队协作，共同探索创新购物模式。期待和优秀的你一起创造更多可能！\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、通过市场调研、数据分析、业务讨论等多种手段，支撑产品经理发现问题、定义产品功能需求；\n2、协助撰写PRD，与设计、研发、测试等多团队紧密协作，推动产品功能按时高质量交付；\n3、跟踪产品上线后的数据表现和用户反馈，针对性优化产品功能，提高用户体验，扩大产品价值；\n4、协助横向项目的全流程推进，包括收集各方信息、组织会议、协同解决卡点问题。","requirements":"1、本科及以上学历在读，专业不限；\n2、逻辑能力和执行力强，善于沟通，主动积极，高度自驱，具备独立思考能力；\n3、对电商行业和国际化产品有兴趣，具备基础的产品思维和数据敏感度，有实习经验优先；\n4、英语听说读写流利，可作为工作语言；\n5、每周能保证至少4天到岗，连续实习3个月及以上。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7678931657625471285","sourceKey":"bytedance","company":"字节跳动","title":"拉美物流运营（巴西/墨西哥） - TikTok Shop","city":"深圳/杭州","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7678931657625471285/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商。平台汇聚全球优质商家与创作者，通过短视频、直播等多场景连接消费者，让新奇好物畅销全球，让美好生活触手可得。目前团队分布在美国、英国、法国、印尼、墨西哥、中国等全球多个国家和地区，在这里你将有机会深入国际业务场景，面向全世界商家及用户，和跨区域团队协作，共同探索创新购物模式。期待和优秀的你一起创造更多可能！\n\n1、根据国际电商发展需求，负责所辖国家物流供应商的运营管理，保障物流时效及体验达成；\n2、负责开展市场及行业调研，制定运营计划，并能够识别实际业务问题并输出相应的解决方案；\n3、负责供应商的标准操作流程（SOP）和运营绩效指标（KPI）的迭代及监控，以及与业务合作伙伴的战略合作；\n4、负责指标的监控及优化，并持续提升生产效率、服务质量、成本效益和满意度等关键指标。","requirements":"1、2027届获得本科及以上学历，供应链物流运营管理领域或相关专业优先；\n2、英文可以作为工作语言，具备较好的跨文化理解能力，沟通能力强，具备西班牙语/葡萄牙语能力者优先；\n3、具备自我驱动力且以结果为导向，具备良好的协作能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7675257382511282485","sourceKey":"bytedance","company":"字节跳动","title":"本地化项目管理实习生（小云雀Pippit） - 剪映CapCut","city":"北京","category":"用户运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7675257382511282485/detail","duty":"团队介绍：剪映研发团队，主要支持剪映、CapCut、醒图、Hypic、即梦、Dreamina、小云雀、Pippit等多款国内外产品的研发工作，业务覆盖多元化影像创作场景，并孵化了多款AIGC明星产品，相关产品多次登顶国内外App Store 免费应用榜第一，并继续保持高速增长。加入我们，一起打造全球最受用户欢迎的影像创作和GenAI产品。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、协助本地化项目管理负责人，管理软件和市场本地化需求，维护本地化语言资产；\n2、支持与产品本地化相关的文化调研项目、AI测评项目；\n3、协助Leader/Mentor完成其他相关工作。","requirements":"1、本科及以上学历在读，专业不限，英语、本地化专业优先；\n2、英语六级600/雅思7/托福100以上，具有流利的英语口语和书面表达能力，掌握小语种（西班牙语等）优先；\n3、熟悉剪辑产品和AI工具的使用，有图像、视频、AI创作经历优先；\n4、有一定项目管理经验或能力；\n5、良好的沟通表达能力、团队协作能力和创新精神；\n6、可保证每周出勤4天，可连续实习。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7673492055689332997","sourceKey":"bytedance","company":"字节跳动","title":"大模型推荐算法工程师（交互式推荐方向） - TikTok算法","city":"北京/上海","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7673492055689332997/detail","duty":"团队介绍：TikTok搜推算法团队，负责TikTok短视频产品的基础推荐、搜索算法，加入我们，你能接触到包括搜索、用户增长、社交、直播、内容创造、内容消费等核心业务场景，直接为核心用户体验负责，支持产品在全球赛道上高速发展。我们的工作内容包括大规模推荐算法的优化、复杂约束的优化问题的解决、多模态大模型的落地，并着力研究下一代AI Search和Chatbot的核心研发技术，包括不限于Multi-Agent、Agentic RL、Harness、Loop Engineering，探索强化学习在大模型时代的新范式。在这里，你可以深入钻研机器学习算法的改进和优化，探索前沿的技术；可以感受不同文化的碰撞，激发认知；可以通过对产品和内容生态的深度分析，影响产品未来的发展方向。\n\n1、推荐领域意图理解智能体的建模与训练：参与意图空间的定义与刻画、指令数据的合成与构造、评测基准的建设，并在继续预训练（CPT）、监督微调（SFT）、偏好对齐（RLHF）各环节承担实验设计与调优；\n2、推荐链路可编程控制能力的建设与验证：一类是调参型控制，覆盖多样性、新鲜度、内容屏蔽、多目标强度、流量分配等维度，核心挑战是利用LLM把自然语言表达映射为链路可执行且用户可感知的配置和调节幅度；另一类是主动诉求与兴趣点的分发能力，包括LLM4Rec、主动兴趣分发、I2I相似推荐等；\n3、端到端生成式推荐（LLM4Rec）的前沿探索：语义ID（Semantic ID）表征学习、语义ID与文本的双向对齐、「用户历史+当前指令」条件下的个性化生成、解码策略与在线推理方案，对齐并挑战业界最新范式；\n4、评估体系与实验科学：搭建可复现的离线评测流程与自动化评估基准，围绕意图识别准确率、指令响应成功率、调节效果的可感知性与用户满意度做分析与归因，把结论沉淀为团队可复用的方法与工具；\n5、前沿跟踪与落地转化：跟进LLM4Rec，生成式推荐、Agentic Recommendation等方向的最新工作，并在真实业务场景中完成有价值的复现与创新验证；表现优秀的课题有机会形成对外论文或专利产出。","requirements":"1、2027届获得硕士及以上学位，计算机、电子、数学等相关专业；\n2、扎实的编程基础、良好的编程风格与工作习惯，掌握扎实的数据结构与算法知识；\n3、在机器学习/深度学习领域具备扎实的理论基础与丰富的实践经验，熟练使用至少一种主流深度学习框架，并理解大语言模型的训练与推理体系（预训练、微调、对齐、解码与推理优化）；\n4、具备优秀的问题定义与解决能力，能够在没有既定答案的开放问题上推进；沟通良好，工作积极主动，责任心强，具备良好的团队协作能力；\n5、有以下任一背景者优先考虑：\n1）在顶级会议发表过论文，在ACM/机器学习类竞赛中获奖，或有大规模推荐系统、计算广告、搜索引擎等核心算法业务经验；\n2）有推荐系统全链路的实际项目经验，理解召回、粗排、精排、重排、混排以及多样性与生态调控等环节；\n3）有大语言模型端到端的训练经验，涵盖继续预训练、监督微调、偏好对齐（DPO/PPO/GRPO）中的一个或多个环节；\n4）有Agent、Function Calling/Tool Use、多轮意图理解与对话状态管理的落地经验。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669793768980531509","sourceKey":"bytedance","company":"字节跳动","title":"大模型算法工程师 - 今日头条","city":"深圳/北京","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669793768980531509/detail","duty":"团队介绍：产品覆盖今日头条、头条极速版等各类产品，为上亿用户持续提供优质的资讯、视频等服务。我们通过建立良好的内容生态，鼓励原创优质的内容，为创作者提供优质的服务和创作体验，促进创作和交流，同时我们致力于通过尽可能丰富的内容体裁和尽可能多的分发方式，连接人与信息，丰富大家的精神生活，让人们看到更大的世界。\n\n1、负责今日头条领域模型的构建，包括领域预训练、指令微调、训练和推理加速、模型评测等技术；\n2、探索大语言模型技术在今日头条业务场景中的应用，为今日头条内容创作、运营、交互体验等各环节提供更智能化的模型能力；\n3、优化现有线上算法，包括智能创作，智能摘要，知识图谱，智能对话等方向研发工作，结合实际业务需求与数据，研发高效可靠的NLP解决方案；\n4、跟踪探索大语言模型的前沿技术与应用落地。","requirements":"1、2027届获得本科及以上学历，人工智能、机器学习、计算机视觉、自然语言处理、计算机、自动化等相关专业优先；\n2、熟悉NLP领域的理论基础，掌握统计模型、机器学习相关原理，具有NLP实战经验，参与过相关项目；\n3、有大模型训练、调优、熟悉大模型分布式训练和Debug经验者优先；\n4、优秀的代码能力、数据结构和基础算法功底，熟悉Python，熟练掌握深度学习框架TensorFlow或者PyTorch；\n5、出色的问题分析和解决能力，能深入解决大模型训练和应用存在的问题，有自主探索解决方案的能力；\n6、良好的沟通协作能力，能和团队一起探索新技术，推进技术进步；在NLP顶级会议/期刊上有学术成果发表者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669725381667211525","sourceKey":"bytedance","company":"字节跳动","title":"治理策略运营 - 抖音电商","city":"上海/北京","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669725381667211525/detail","duty":"团队介绍：抖音电商以“总能发现好东西”为主张，致力于成为用户发现丰富好物的首选平台。众多抖音创作者通过短视频、直播、商城等丰富的形式，给用户提供更个性化、更生动、更高效的消费体验。同时，抖音电商积极引入优质合作伙伴，为商家变现提供多元的选择。\n\n1、基于用户体验升级与公司战略方向，负责大服饰赛道风险防控全流程体系建设，确保风险及时感知、阻断、高效攻防；为用户消费体验提供综合解决方案；\n2、围绕治理目标，建立良好的沟通协同机制，联动产品、算法、售后等协同团队，主导治理策略落地与过程管理，及时识别风险并主动干预；\n3、运用大模型能力，制定智能化治理解决方案，推动治理从“风险感知-标准立规-风险识别”的全链路智能化升级；\n4、常态化监控策略效果，反哺策略优化；基于风险动态变化，快速落地专项治理与应急处置，沉淀方法论，推进风险治理长效化、精细化运营。","requirements":"1、2027届获得本科及以上学历，统计学、应用数学、计算机等理工科专业背景优先；\n2、具备良好的数据分析能力，能熟练使用SQL；\n3、逻辑清晰，具备良好的项目管理能力，沟通协同能力强，目标感强，能0-1推进项目落地；\n4、有电商治理、内容安全、风控策略相关实习经验优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669677733932239109","sourceKey":"bytedance","company":"字节跳动","title":"搜索体验运营（短剧方向） - 红果短剧","city":"北京","category":"内容运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669677733932239109/detail","duty":"团队介绍：红果短剧是抖音集团2023年推出的免费看剧产品，致力于为用户提供海量免费优质短剧，同时也为用户提供电影、电视剧、小说、有声书等多元内容，满足不同用户的内容消费需求。\n\n1、基于红果短剧生态，搭建搜索体验量化评测体系，定义搜索结果页理想体验标准，结合用户调研、用户反馈等多维手段验证体验问题影响面和有效性；\n2、协同算法/策略产品团队，基于用户体验数据洞察，输出有效结论，牵引/推动算法策略迭代；\n3、推动评估标准的落地执行，保障各类例行和摸底任务能够按时按质交付；\n4、结合AI能力持续挖掘用户在搜索场景的需求，设计合理的AI入口、AI评估标准，优化用户找剧效率+泛搜索体验。","requirements":"1、2027届获得本科及以上学历；\n2、搜索推荐产品运营/AI产品运营相关工作经验，熟悉短剧行业；\n3、逻辑思维和数据分析能力良好，能从数据中发现问题、解决问题；\n4、沟通协调能力优秀，擅长推动跨部门合作达成目标；\n5、能够独立承担体验项目管理和方案设计，具备创新思维以推动用户体验的突破。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668630764718000389","sourceKey":"bytedance","company":"字节跳动","title":"KA营销活动运营 - 抖音生活服务","city":"上海/杭州/北京/成都","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668630764718000389/detail","duty":"团队介绍：抖音生活服务依托抖音POI （Point of Interest）、短视频、直播、搜索等，以“激发线下生意，丰富美好生活”为使命，致力于成为最值得信赖的生活服务平台，为用户提供更丰富、独特的生活体验，为合作伙伴提供包容且公平的健康营商生态。截至2025年底，抖音生活服务业务已覆盖400+城市，超过1500万家动销门店。抖音生活服务将继续携手生态伙伴，为用户提供值得心动的商品和服务。\n\n1、负责抖音生活服务行业KA营销（到店餐饮、游玩、服务、零售），能够结合用户、商家、市场的洞察，制定并落地整合营销规划，带动线下零售场景下的消费者习惯并拉动GMV与广告的增长，包括但不限于方案策划、活动执行、会场搭建、玩法配置、广告投放等；\n2、拥有资源协调、内容创意及热点策划等能力，能有效整合平台、品牌、媒体等多端资源，并结合多端诉求实现多方共赢，能针对行业特色和平台特性进行亮点挖掘与包装展示，沉淀出对市场和行业有影响力的整合营销案例；\n3、具备数据化营销运营思维和能力，能基于数据分析和洞察，制定针对行业、品牌和人群的营销策略。","requirements":"1、2027届获得本科及以上学历，新闻传播、广告学、市场营销专业优先；\n2、具备消费者洞察和创意能力，有较好的内容营销敏感度与数据逻辑性；\n3、具备较强的资源整合、沟通能力，能够协同跨团队资源实现营销效率的提升；\n4、具备多线程工作管理能力者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668562361263753525","sourceKey":"bytedance","company":"字节跳动","title":"机器学习推理执行引擎研发工程师 - Data AML","city":"杭州/上海/北京","category":"机器学习","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668562361263753525/detail","duty":"团队介绍：Data AML是字节跳动的机器学习中台，为抖音/今日头条/西瓜视频等业务提供推荐/广告/CV/语音/NLP的训练和推理系统。为公司内业务部门提供强大的机器学习算力，并在这些业务的问题上研究一些具有通用性和创新性的算法。同时，也通过火山引擎将一些机器学习/推荐系统的核心能力提供给外部企业客户。\n\n1、负责大模型推理引擎底层架构迭代与GPU全链路性能优化，通过算子融合、编译优化等手段，深度优化GPU访存、计算流水线、Stream异步调度，消除推理计算瓶颈，提升单卡推理吞吐、降低推理延迟；\n2、适配全系GPU/NPU硬件架构，打磨推理引擎通用性与硬件适配性，搭建高性能、低损耗的大模型推理底层底座；\n3、主导大模型推理场景下的分布式并行方案设计、开发与优化，重点落地张量并行（TP）、流水线并行（PP）、序列并行、MoE专家并行等多维度并行策略，解决超大模型多卡拆分部署、跨卡通信开销大、负载不均衡、并行效率低下等问题；\n4、跟进全球大模型推理、GPU高性能计算、分布式并行、缓存优化等前沿技术，对标vLLM、TensorRT-LLM等主流推理框架，完成方案落地与技术创新，持续迭代优化推理系统性能与成本优势，构建团队技术壁垒。","requirements":"1、2027届获得本科及以上学历；\n2、扎实的计算机底层基础，精通C/C++、Python编程，熟练掌握CUDA编程、GPU硬件架构原理，熟悉GPU内存模型、计算调度、通信机制；\n3、熟练掌握深度学习各类基础算子的底层开发实现，精通矩阵运算、归一化、激活函数等算子的GPU适配优化，可独立完成算子手写重构、访存优化、向量化加速、精度对齐，保障算子推理的高性能与高稳定性；\n4、熟悉深度学习推理编译全链路，理解计算图优化、算子融合、常量折叠、内存复用、调度优化、量化编译等编译技术，能够通过编译层级改造简化推理链路、降低显存占用、减少推理时延，大幅提升模型推理吞吐效率；\n5、熟练使用Nsight、Profiler等GPU性能分析工具，可精准定位推理过程中算力浪费、访存阻塞、调度冗余等性能瓶颈，具备软硬件协同优化思维，能够输出系统化优化方案并完成落地迭代，适配产业级高并发、低时延推理业务需求；\n6、具备良好的跨团队协作能力、沟通表达能力与文档撰写能力，有较强的责任心，能够推动复杂技术问题的解决与项目落地。\n\n加分项\n1、深入理解大模型推理原理，熟练掌握模型并行技术，具备张量并行、流水线并行、序列并行等分布式推理方案落地经验，熟悉多卡通信、负载均衡、并行效率优化方法；\n2、有vLLM、SGLang、TensorRT-LLM等主流大模型推理框架二次开发、性能优化经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668297472185977093","sourceKey":"bytedance","company":"字节跳动","title":"抖音热点资讯编辑 - 抖音内容运营","city":"北京","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668297472185977093/detail","duty":"团队介绍：致力于通过热点内容管理、平台沟通与信任建设、编辑与研判等手段，持续为打造健康繁荣的抖音内容生态护航，提升用户内容消费体验。同时我们希望以创新的智能内容挖掘与理解为手段，针对低质、争议、谣言、虚假等问题展开治理，营造一个良好的内容消费氛围。\n\n1、配合热点资讯业务完成AI编辑工作，构建新的人-机协同模式；\n2、负责AI资讯内容生产、安全和质量评测的工作，通过评测发现问题，联动上下游共同解决安全和质量问题；\n3、借助数据分析、内容拆解对模型问题进行分析，提供解决思路及优化方向，输出有价值的分析报告辅助模型迭代优化；\n4、跨团队合作协调，建立完善的运营机制，协同业务、产品、算法、等团队，支撑进审策略、审核标准、交付质量的提升和优化。","requirements":"1、2027届获得本科及以上学历，大模型或AI相关专业；\n2、对资讯内容的价值、质量有判断，有主流资讯平台实习经验者优先；\n3、对新产品、新技术保持高度的好奇心和探索欲，具备较好的适应能力，具备良好的环境适应与项目协调能力，用AI化的能力去解决问题。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668238560618678533","sourceKey":"bytedance","company":"字节跳动","title":"后端研发工程师 - AI算力基础设施","city":"北京/杭州/成都","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668238560618678533/detail","duty":"团队介绍：字节跳动基础设施部门，负责字节跳动的全栈算力基础设施，从芯片服务器产研、到超大规模数据中心，到传统云平台和如今的AI Native Cloud，全方位为抖音、豆包、今日头条、飞书、火山引擎等各类产品提供领先、稳定的百万量级大规模算力基础设施服务。我们的领域涵盖数据中心建设、内核操作系统开发、服务器集群管理、高速网络通信、EB级数据存储体系、搜索型数据库探索、基于LLM的AI基础设施的研发调度与治理等，致力于打造业界领先的、面向LLM的AI云原生基础设施架构与产品矩阵。\n\n1、负责字节跳动大规模基础设施资源（IDC、云、服务器等）及其运维的数字化平台能力建设；\n2、负责数据中心基础系统服务的研发和运维，持续优化和提升服务性能，保障服务稳定性；\n3、在字节云数据中心海量主机集群与超大规模核心组件的自动化运维体系搭建过程中，构建标准化、自动化、可扩展的云运维基础平台与运维底座，支撑公司全球化业务规模化扩张与技术架构升级；\n4、负责字节跳动全球服务器、云主机和数据中心基础设施运维、运营等相关平台开发；\n5、负责AI Coding的探索与实践，通过大模型、Agent工程架构等技术的合理应用，提升产品体验和开发效率。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程、人工智能等相关专业优先；\n2、至少掌握一门编程语言，包括但不限于Golang、Python、C++、Java等；\n3、掌握计算机原理，具备扎实的数据结构和算法功底以及优秀的编码能力；\n4、具备良好的自驱力与学习能力，优秀的沟通能力、组织协调与项目推动能力；英语可作为工作语言者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668232018053155125","sourceKey":"bytedance","company":"字节跳动","title":"数据科学 - 抖音生活服务","city":"北京/上海","category":"数据分析","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668232018053155125/detail","duty":"团队介绍：抖音生活服务依托抖音POI （Point of Interest）、短视频、直播、搜索等，以“激发线下生意，丰富美好生活”为使命，致力于成为最值得信赖的生活服务平台，为用户提供更丰富、独特的生活体验，为合作伙伴提供包容且公平的健康营商生态。截至2025年底，抖音生活服务业务已覆盖400+城市，超过1500万家动销门店。抖音生活服务将继续携手生态伙伴，为用户提供值得心动的商品和服务。\n\n1、数据科学：\n1）执行抖音平台生活服务领域的数据分析项目，提供洞见以支持业务决策，帮助业务实现快速增长；围绕商家增长、交易效率、生态健康等业务目标，开展数据挖掘与建模工作，覆盖用户/商家分层、需求预测、效果归因、策略评估等场景，输出可落地的业务洞察与策略建议；\n2）运用统计学与机器学习方法，解决业务实际问题，包括异动诊断、因果分析、指标体系搭建、AB实验设计与效果评估等，支撑业务科学决策；\n3）负责日常数据提取、清洗、分析与可视化输出，构建标准化分析模板与数据看板，保障业务数据的可获得性与准确性；\n4）独立承担细分领域的专题分析项目，完成从问题拆解、数据处理、分析建模到结论输出的完整闭环，跟进策略落地效果并复盘迭代；\n2、AI应用与提效工作：\n1）探索大模型等AI技术在数据科学工作流中的落地应用，包括智能取数、代码生成与优化、报告自动化、辅助建模调优等场景，沉淀个人提效方法；\n2）参与团队AI智能分析工具的场景验证、效果测试与迭代优化，协助输出需求文档与评估报告；\n3）沉淀AI+数据科学的最佳实践与操作规范，协助团队内部推广AI分析方法，提升整体工作效率；\n4）跟进AI技术在数据领域的前沿动态，结合业务场景输出可行性落地建议，参与创新场景的预研与试点。","requirements":"1、2027届获得本科及以上学历，统计学、数学、计算机科学、软件工程、经济学、信息管理等相关专业优先；\n2、具备扎实的编程与数据处理能力：熟练使用SQL完成多表关联、复杂查询与数据统计；熟练掌握数据分析与建模库，可独立完成从数据处理到建模输出的完整流程；\n3、具备良好的逻辑思维与问题拆解能力，对数据敏感，有较强的业务理解能力与结果导向意识；\n4、对AI技术有兴趣，能够结合数据工作场景主动探索AI提效方法，具备将AI工具转化为实际生产力的意识，有真实动手实践经历，如使用大模型辅助数据建模与代码开发、参与AI应用类课程项目/创新竞赛、有Prompt优化等实操经验；\n5、有主动学习与探索的意愿，愿意持续跟进AI技术发展，尝试新工具、新方法解决数据工作中的痛点。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667884524668160309","sourceKey":"bytedance","company":"字节跳动","title":"AgentOps平台研发工程师 - AI Platform","city":"上海/北京","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667884524668160309/detail","duty":"团队介绍：AI Platform 团队，隶属于产品研发和工程架构部门。面向公司内部各业务线，建设统一的AI 应用基础设施和工程平台，帮助业务高效、稳定地落地大模型应用，加速 AI 产品创新。\n在平台产品侧，团队打造了新一代AgentOps平台，提供 Prompt Engineering、Agent观测、评测、数据处理、模型微调等 Agent 全生命周期解决方案，帮助Agent开发者构建效果调优的数据飞轮。产品也已成功推出商业化版本。\nAI Platform 团队还持续孵化多种面向内部与外部场景的AI应用创新产品，积极探索大模型应用的技术发展。团队氛围好，发展空间大，欢迎加入！\n\n1、负责AgentOps一站式AI研发平台能力建设，落地AI应用开发调试、全链路可观测、效果评测分析等功能，保障产品体验与系统稳定性；\n2、负责大模型应用数据飞轮体系搭建，实现数据回流、加工处理、训练投递、评估部署的全流程平台化能力，构建全生命周期数据管理底座；\n3、主导平台整体技术架构设计与持续优化，解决大规模业务场景下的技术难题，保障系统高可用、高性能与可扩展性；\n4、跟进AI研发工具领域前沿技术，沉淀AI应用工程化最佳实践，通过平台化方式输出能力，助力AI应用高效落地与迭代。","requirements":"1、2027届获得本科及以上学历，计算机、人工智能、自动化、数学相关专业优先；\n2、具备扎实的计算机专业基础，精通主流的后端/前端语言；\n3、具备良好的系统设计与问题拆解能力，能独立完成技术攻坚，有高可用分布式系统/前端全栈项目研发经验者优先；\n4、对LLMOps/AgentOps赛道有浓厚兴趣，自驱力与学习能力突出，能持续跟进AI领域前沿技术，工作严谨负责，具备良好的团队协作与沟通能力；\n5、有大模型应用开发、RAG/Agent落地、大数据平台建设、研发效能工具研发相关经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667868985950013749","sourceKey":"bytedance","company":"字节跳动","title":"大模型算法工程师（游戏互动方向） - 抖音直播","city":"北京/深圳/上海","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667868985950013749/detail","duty":"团队介绍：直播团队负责为抖音集团旗下产品提供直播服务。团队负责直播平台技术和直播业务研发，打造灵活稳定的直播服务平台，为用户提供优质直播体验，支持电商、本地生活、游戏、节目、多人互动等不同类型的业务场景。直播业务发展迅猛，处于行业头部地位，业务发展空间巨大。现在加入我们，和优秀的人一起做有挑战的事，你的技术与创意将影响亿级用户，激发创意和丰富生活。\n\n1、负责抖音游戏互动方向的大语言模型/多模态大模型的算法研发，利用AI工具降低创作门槛，扩大玩法创作者规模与供给，以AI Native的游戏互动玩法丰富抖音内容生态；\n2、负责游戏生成智能体的搭建与优化，探索游戏生成全流程自动化路径，实现用户通过自然语言生成完整可交互游戏的目标；\n3、负责LLM/VLM模型在Agent调度、代码生成、视觉理解、空间理解等能力的后训练，构建生成-验证的闭环迭代机制；\n4、跟踪AI前沿技术进展，推动前沿技术的产品化落地。","requirements":"1、2027届获得本科及以上学历，人工智能、计算机、软件工程等相关专业优先；\n2、熟悉Linux系统和常用的数据结构，熟练使用Python/C++等至少一种编程语言，熟练使用TensorFlow/PyTorch等至少一种深度学习框架；熟悉Attention、Transformer、BERT、GPT等常用模型结构，熟悉Llama、ChatGLM等开源大模型原理与实现；\n3、优秀的分析和解决问题的能力，对解决具有挑战性的问题充满激情，良好的沟通和团队合作能力。\n\n优先考虑：\n1、在代码生成、大模型训练、Agent、RLHF等方面有积累者。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667543390654368005","sourceKey":"bytedance","company":"字节跳动","title":"电商运营管培生（全托管） - TikTok Shop","city":"上海","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667543390654368005/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商。平台汇聚全球优质商家与创作者，通过短视频、直播等多场景连接消费者，让新奇好物畅销全球，让美好生活触手可得。目前团队分布在美国、英国、法国、印尼、墨西哥、中国等全球多个国家和地区，在这里你将有机会深入国际业务场景，面向全世界商家及用户，和跨区域团队协作，共同探索创新购物模式。期待和优秀的你一起创造更多可能！\n\n项目介绍：起航计划是国际电商跨境业务板块专为2027届校招生打造的运营管培项目，旨在寻找优秀的有潜力应届毕业生，结合系统的培训与实践，助力他们在国际电商运营领域扬帆起航，迅速提升专业技能，成长为跨境业务未来领军人物。与字节跳动一起，实现“好货卖全球”。 \n\n项目亮点： \n1、全球化视野：有机会深入全球场景，面向全球商家及用户，创新互动式趣味购物模式； \n2、大咖导师带教：行业大牛专属辅导，全程助你提升业务能力与素养； \n3、快速成长通道：定制化职业发展指导，给你更快速的成长； \n4、灵活轮岗机会：安排轮岗实践，深入不同业务板块，让你全方位了解国际电商价值链。\n\n1、参与跨境电商业务运营，面向全球商家、达人机构与用户，支持相关运营工作；\n2、负责达人及机构内容运营支持，参与运营方案设计，协同推进短视频、直播等内容玩法执行；\n3、参与跨境业务营销活动运营，支持活动策划、营销玩法设计、场域资源协同及执行跟进；\n4、参与商城运营相关工作，输出市场、行业类目、货盘等分析，支持搜索推荐、商城频道运营等方向；\n5、参与市场洞察与重点方向规划支持，开展培养项目学习、导师带教与轮岗实践，积累国际化运营相关能力。","requirements":"1、2027届获得本科及以上学历，理科、商科、传播类相关专业优先；\n2、英语口语流利交流，有国际化留学经验优先，有相关英语成绩单或证书可随简历一并上传（如雅思、托福等）；\n3、有较强的数据分析能力、问题解决能力和沟通协作能力；\n4、积极主动，责任心强。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667121135016446261","sourceKey":"bytedance","company":"字节跳动","title":"用户增长运营实习生 - 抖音生活服务","city":"北京/上海/成都","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667121135016446261/detail","duty":"团队介绍：抖音生活服务依托抖音POI （Point of Interest）、短视频、直播、搜索等，以“激发线下生意，丰富美好生活”为使命，致力于成为最值得信赖的生活服务平台，为用户提供更丰富、独特的生活体验，为合作伙伴提供包容且公平的健康营商生态。截至2025年底，抖音生活服务业务已覆盖400+城市，超过1500万家动销门店。抖音生活服务将继续携手生态伙伴，为用户提供值得心动的商品和服务。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、负责抖音生活服务用户增长团队相关策略产品运营工作，包括但不限于补贴策略制定、数据监测、分析复盘等；\n2、从用户生命周期切入，结合已有用户增长的线上、线下渠道，通过补贴策略进行拉新、促活；\n3、从商家经营视角切入，对超值券产品GTM的渗透率、商家体验负责，提升商家的持续供给动力。","requirements":"1、本科及以上学历在读，数学、经济学、商业分析等相关专业优先；\n2、具备较强的数据分析和业务分析能力，对数据敏感；\n3、有较好的逻辑思维，善于沟通，能积极主动承担工作；\n4、具备资源协调项目管理能力，能够推动业务相关方快速行动，促成结果达成，结果导向；\n5、全勤实习4个月以上，有用户增长策略运营实习经历优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667118991484176645","sourceKey":"bytedance","company":"字节跳动","title":"广告后端开发工程师 - 国际化商业安全","city":"上海/北京","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667118991484176645/detail","duty":"团队介绍：国际化商业安全团队致力于在国际化用户、企业和产品之间建立安全可靠的连接。我们通过一系列完善的系统和能力，审核广告内容、预测政策违规行为，并执行广告审核通过或拒绝的措施。\n作为国际商业化团队的业务合作伙伴，我们提供的业务诚信解决方案不仅确保国际化业务始终是一个安全、积极、友好的用户环境，同时也推动业务增长。\n\n1、负责字节跳动国际化商业化产品线的内容安全解决方案建设；\n2、构建Agentic风险运营平台，一站式完成感知-归因-研判-治理，挖掘策略模型并部署，控制底线风险；\n3、面向日均亿级别广告素材和全广告形态，搭建审核流程框架，沉淀通用策略平台和编排引擎；\n4、建设Agentic质量平台和申诉流程，误伤可半自动迭代；建立标检训一体的数据工程和标注工具，提升模型效果。","requirements":"1、2027届获得本科及以上学历，计算机科学、软件工程相关专业；\n2、精通Golang/Java/Python中的一种或者多种语言，具备良好的编码能力、扎实的数据结构和算法功底，参加ACM/Topcoder/Codeforces等至少一种算法编程竞赛；\n3、具备高可用、高并发、高性能的分布式系统建设经验，熟悉HBase/Mongo/MySQL等至少一种存储系统；\n4、具备生产系统快速Trouble-Shooting的经验和能力；\n5、较好的产品意识和数据分析能力，有较强的自驱力和工匠精神打磨工具产品，有广告相关领域优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667106823808305413","sourceKey":"bytedance","company":"字节跳动","title":"Agent效果评测工程师 - 开发者服务","city":"深圳","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667106823808305413/detail","duty":"团队介绍：字节跳动开发者服务团队负责公司研发工具与基础设施体系建设，为内部开发者提供覆盖全技术栈的框架、工具和研发体系能力，支撑业务高效稳定迭代。\n在此基础上，团队正打造面向全场景的AI Agent平台，将大模型与公司内部工程知识深度结合，覆盖需求分析、编码开发、测试发布、运维治理等软件全生命周期，帮助ByteDancer显著提升生产力，重塑开发者服务的形态与体验。\n期待对研发工具体系、AI工程生产力有热情、希望在大规模真实场景中打磨技术的同学加入，与我们一起建设新一代开发者基础设施，共同成长！\n\n1、评估体系建设：面向字节跳动软件工程研发真实场景，定义效果评估标准与验收准则，构建高仿真评测集，设计科学客观的量化指标体系，系统化开展效果评测；\n2、效果洞察与归因：对齐业务目标，洞察高价值效果问题并进行根因分析，协同策略PM与算法推进效果闭环优化，放大产品业务价值；\n3、自动化评测：建设自动评测与洞察分析能力，探索AI新技术落地，提升评测与归因效率，加速产品迭代；\n4、技术前瞻：跟踪行业与技术趋势，引入新技术、新方法并在业务场景中验证应用。","requirements":"1、2027届获得本科及以上学历，计算机、人工智能、数学等相关专业；\n2、有评测经验者优先，具备良好的工程架构设计与编码能力，精通Go/Python/Java中至少一种；\n3、沟通表达能力强，具备好奇心、创新意识、自驱力与复杂问题解决能力；\n4、对大模型与Agent有深入理解，熟悉主流LLM应用模式与评估框架，了解Agent架构（Multi-Agent、Context Engineering、ReAct）及协议（MCP、A2A、Function Call）；\n5、加分项：具备Agent开发或复杂场景评测经验；有AI论文发表、大模型评测或训练经验。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7665568162248788229","sourceKey":"bytedance","company":"字节跳动","title":"客户端开发工程师 - 中国交易与广告","city":"上海","category":"客户端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7665568162248788229/detail","duty":"团队介绍：中国交易与广告，负责抖音电商、生活服务、广告营销等营收业务的研发。用技术带来美好生活，让用户发现更多优价好物，为用户提供更丰富独特的生活体验；连接海量用户与商家，促进交易达成，让生态里全流程体验更流畅，助力营收业务长效增长。\n加入团队，你将投身流量与增长主战场，挑战复杂业务场景技术难题；直面真实商家和用户，用技术解决看得见的问题，在实战中快速成长，书写属于你的价值故事！\n\n1、负责电商业务相关产品迭代改进及移动新产品的开发；\n2、参与APP性能、体验优化及质量监控评估体系建设；\n3、参与客户端基础组件及架构设计，推进研发效率；\n4、参与Hybrid容器搭建，组件化、Flutter等跨平台&动态化技术调研。","requirements":"1、2027届获得本科及以上学历，计算机相关专业；\n2、热爱计算机科学和互联网技术，对移动产品有浓厚兴趣；\n3、扎实的数据结构和算法基础，熟练掌握至少一门编程语言（包括但不限于：Java、Kotlin、Objective-C、Swift、C、C++、JS、Python）；\n4、关注用户体验，能够积极把技术转化到用户体验改进上；\n5、对新技术保持热情，具备良好的分析、解决问题的能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7664438281645279493","sourceKey":"bytedance","company":"字节跳动","title":"算法实习生 - TikTok直播","city":"上海","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7664438281645279493/detail","duty":"团队介绍：TikTok是一个覆盖150个国家和地区的国际短视频平台，我们希望通过TikTok发现真实、有趣的瞬间，让生活更美好。TikTok 在全球各地设有办公室，全球总部位于洛杉矶和新加坡，办公地点还包括纽约、伦敦、都柏林、巴黎、柏林、迪拜、雅加达、首尔和东京等多个城市。\n\nTikTok直播研发团队，旨在实现TikTok直播业务的研发工作，搭建及维护业界领先的产品。\n加入我们，你能接触到包括：社交互动、营收活动、主播生态、消费订阅、游戏直播、公会&运营平台等核心业务场景，支持产品在全球赛道上高速发展；\n也能接触到包括服务架构、大模型算法、基础技术等方向上的技术挑战，保障业务持续高质量、高效率、且安全地为用户服务；同时还能为不同业务场景提供全面的技术解决方案，优化各项产品指标及用户体验。 \n在这里， 有大牛带队与大家一同不断探索前沿， 突破想象空间。 \n在这里，你的每一行代码都将服务亿万用户。\n在这里，团队专业且纯粹，合作氛围平等且轻松。\n目前在北京，上海，杭州、广州、深圳分别开放多个岗位机会。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、参与前沿算法研发：深耕LLM、多模态大模型、CV、NLP等技术，应用于召回、点击率、转化率预估、内容生态、直播热点挖掘、推荐系统等核心场景，参与大规模推荐系统的设计与模型优化；\n2、参与全流程算法落地：独立承担或深度参与大型算法项目，覆盖从模型训练、调优、部署到效果评估、持续迭代的完整链路，支撑大规模乃至超大规模业务场景；\n3、参与学术研究与产出：总结研究成果，有机会发表顶会论文、参与国际学术会议。","requirements":"1、博士学位在读，计算机、软件工程、电子信息等相关专业优先；\n2、熟练掌握PyTorch等主流深度学习框架，精通Python，熟悉C++、Shell等脚本语言、熟悉文生图，文生视频，视频生成和流式视频生成的相关技术、熟练掌握多模态大模型相关的技术；\n3、扎实的数据结构与算法基础，优秀的算法设计与编码能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7663024106425731381","sourceKey":"bytedance","company":"字节跳动","title":"安全攻防工程师 - 安全与风控","city":"北京","category":"安全","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7663024106425731381/detail","duty":"团队介绍：我们团队致力于通过对攻防技术的持续研究，最大限度降低零日漏洞与安全事件造成的影响。我们提供红队演练、威胁检测、安全保障工具支持及事件调查等服务，助力提升系统韧性。通过不断强化攻防两端能力，我们在巩固公司核心安全基础、保障数据与业务安全方面发挥着关键作用。\n\n1、模拟攻击，用渗透测试技术模拟攻击公司网络、系统及应用，定位安全薄弱点；\n2、漏洞挖掘，跟踪漏洞情报，研究并挖掘各类漏洞，分析影响并提供修复建议；\n3、协同防御，与蓝队合作，助力优化安全策略与响应机制，提升整体防御能力；\n4、技术研究，参与安全项目与前沿技术研究，推动公司安全技术发展。","requirements":"1、2027届获得本科及以上学历，计算机、网络工程、信息安全等相关专业优先；\n2、热爱网络安全，掌握网络安全基础理论与网络协议、Web安全等知识，熟练运用至少一种编程语言（Python/Java/C/C++）；\n3、熟悉渗透测试流程与工具（Nmap/Burp Suite等），能独立完成测试任务，了解Web漏洞原理与利用技巧，懂内网渗透基本技术，具备一定漏洞挖掘能力，有相关经验者优先；\n4、学习能力强，能快速掌握新技术，具备团队精神与沟通能力，有较强问题解决能力。\n\n加分项：\n1、在CTF等网络安全竞赛中获奖；\n2、为安全开源项目有实质贡献；\n3、发表过网络安全相关技术文章或有研究成果。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7662733701416782085","sourceKey":"bytedance","company":"字节跳动","title":"测试开发（AI评测方向）实习生 - 中国交易与广告","city":"上海","category":"测试","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7662733701416782085/detail","duty":"团队介绍：中国交易与广告，负责抖音电商、生活服务、广告营销等营收业务的研发。用技术带来美好生活，让用户发现更多优价好物，为用户提供更丰富独特的生活体验；连接海量用户与商家，促进交易达成，让生态里全流程体验更流畅，助力营收业务长效增长。\n加入团队，你将投身流量与增长主战场，挑战复杂业务场景技术难题；直面真实商家和用户，用技术解决看得见的问题，在实战中快速成长，书写属于你的价值故事！\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、跟随AI评测平台的业务迭代，依托各类AI Coding工具，独立完成项目前后端全栈开发、功能迭代与接口联调，落地业务需求；\n2、迭代AI评测助理Agent，包括但不限于借用Skill、CLI、MCP、Workflow等技术，完成助理能力迭代，任务完成准确率提升，优化交互体验；\n3、为评测集、评估器市场化运营提供平台和技术支撑，助力评测资产高效高质积累；\n4、不断追寻AI评测新技术和解决方案，为评测效率、评测质量和评测资产的提升和积累产出最佳实践。","requirements":"1、本科及以上学历在读，计算机、软件工程等相关专业；\n2、每周可以实习4天，可连续实习4个月，掌握Python/TypeScript/Go/Java任意2门开发语言，具备基础工程开发思维；\n3、熟悉前后端开发语法、技术原理与基础架构，拥有真实项目开发经验；\n4、了解LLM、Skills、MCP、工作流、AI评测等基本原理和它们之间的关系。\n\n加分项\n1、熟悉AI评测流程、Benchmark构建、评估器调优，且有相关实战经验；\n2、熟悉Skills编写、调优、工作流搭建，且有相关实战经验。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7649280013948520709","sourceKey":"bytedance","company":"字节跳动","title":"Agent开发实习生-抖音直播","city":"北京","category":"客户端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7649280013948520709/detail","duty":"日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n团队介绍：直播团队负责为抖音集团旗下产品提供直播服务。团队负责直播平台技术和直播业务研发，打造灵活稳定的直播服务平台，为用户提供优质直播体验，支持电商、本地生活、游戏、节目、多人互动等不同类型的业务场景。直播业务发展迅猛，处于行业头部地位，业务发展空间巨大。现在加入我们，和优秀的人一起做有挑战的事，你的技术与创意将影响亿级用户，激发创意和丰富生活。\n\n1、参与2D AIGC游戏生成管线研发：从需求理解、资产生成、代码生成到自动验证的端到端链路开发；\n2、设计并迭代游戏Agent系统：包括VLM驱动的游戏理解/操作循环、多步任务编排、工具调用与反馈闭环；\n3、打磨Agent架构关键环节：Prompt工程、上下文管理、工具系统、长链路稳定性与可观测性优化；\n4、前沿技术跟进与落地：跟进大模型与Agent领域最新进展，将可落地的方法引入系统。","requirements":"1、本科及以上学历在读，计算机相关专业优先；\n2、计算机基础扎实，掌握数据结构与算法、操作系统/网络等基础，至少熟练一门编程语言（Python优先）；\n3、独立或参与过完整的2D游戏项目（H5/Phaser/Godot/Unity2D等均可），理解游戏循环、状态管理、精灵/动画、资产与场景组织；\n4、完整经历过至少一个AI项目从想法到落地的全过程（数据→训练/调用→评估→部署/上线），不只是跑通Demo；\n5、了解Agent范式（ReAct/Tool Use/Planning/Memory等），动手搭建过Agent或多步LLM应用，能清晰讲解模块拆分；\n6、理解Transformer、Attention、预训练/微调、RLHF等基础概念，能区分不同模型能力边界与适用场景。\n\n加分项：\n1、熟悉主流Agent框架或自研过Agent Runtime；\n2、有VLM/多模态模型实践经验；\n3、有强化学习相关经验（PPO/BC/离线RL）；\n4、熟悉Python异步编程、Pydantic、FastAPI等工程栈；\n5、有开源贡献、技术博客或可展示的个人项目。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7628965645790562613","sourceKey":"bytedance","company":"字节跳动","title":"面向大模型与AI Agent的AI云原生基础设施关键技术研究 - AI算力基础设施","city":"北京/上海/杭州","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7628965645790562613/detail","duty":"团队介绍：字节跳动基础设施部门，负责字节跳动的全栈算力基础设施，从芯片服务器产研、到超大规模数据中心，到传统云平台和如今的AI Native Cloud，全方位为抖音、豆包、今日头条、飞书、火山引擎等各类产品提供领先、稳定的百万量级大规模算力基础设施服务。我们的领域涵盖数据中心建设、内核操作系统开发、服务器集群管理、高速网络通信、EB级数据存储体系、搜索型数据库探索、基于LLM的AI基础设施的研发调度与治理等，致力于打造业界领先的、面向LLM的AI云原生基础设施架构与产品矩阵。\n\n课题介绍：\n随着大语言模型与AI Agent规模化落地，传统云原生基础设施已难以适配AI负载的极致性能与弹性需求。本课题围绕AI基础设施全栈展开系统性研究：\n1、网络与可观测：研究大规模AI集群故障智能定位与根因分析，结合时序数据库智能调优，提升集群稳定性；\n2、存储系统：研发AI场景专属的Serverless高性能弹性文件系统与存储加速架构，探索DPU软硬件协同优化，突破AI存储性能瓶颈；\n3、算力调度：研究GPU/CPU/MEM异构协同调度技术，面向AI Agent构建Serverless异构算力编排系统，解决负载异构、状态依赖等调度难题；\n4、向量检索：优化面向大模型应用的向量检索核心技术，打造云原生分布式向量索引引擎，满足超大规模向量检索的低延迟、低成本需求；\n5、智能化与Agent架构：探索基于AI Agent工作流的基础设施自动寻优，构建可自主进化的业务Agent框架，通过AI for Infra赋能全栈智能优化；\n本课题旨在构建支撑大模型与AI Agent落地的下一代AI原生基础设施，提升资源利用率、降低成本、支撑弹性扩展，推动AI基础设施技术演进。\n\n课题挑战：\n1、全栈协同挑战：覆盖多技术领域，需要从端到端视角实现系统性优化，避免单点优化收益不足；\n2、性能成本平衡：AI场景对性能提出极致要求，需要在吞吐、延迟、规模与成本之间找到最优平衡点；\n3、云原生适配：需要将传统单机技术方案重构为适配云原生分布式架构，解决扩缩容、容错、调度等新问题；\n4、AI系统融合：既需要用AI赋能基础设施优化，又需要基础设施原生适配AI负载，深度融合对技术整合要求高；\n5、Agent稳定性：自主进化Agent框架需要解决经验学习、知识一致性、持续安全进化等基础问题，工程化难度大；\n6、研发生态平衡：需要平衡前沿理论创新与工程落地，兼顾技术突破与现有业务生态适配。\n\n课题价值：\n1、构建大模型/RAG 场景的高性能基础设施底座，支撑大规模向量数据高效检索；\n2、优化AI业务存储成本结构与运维复杂度；\n3、提升异构算力资源配置效率与技术复用性。","requirements":"1、2027届毕业，获得博士学位，优先考虑人工智能、计算机科学、数学相关专业；\n2、拥有扎实的信息检索、数据挖掘、机器学习、计算机网络等相关领域理论基础，精通计算机网络和网络编程，熟练掌握至少一门编程语言，如C/C++、Python、Go等，具备优秀的代码能力、数据结构和基础算法功底；\n3、针对不同研究方向，需具备相应能力，如能够独立完成复杂搜索任务的设计与开发；有LLM和基础架构相关研究背景；能完成研究点的设计文档、独立交付件、演示Demo；熟悉当前高性能网络和系统领域的最新进展，包括RDMA，拥塞控制、AI网络优化等技术；\n4、具备高效的学习能力，拥有较强的自我驱动意识；具有良好的团队合作精神，善于与团队成员协作交流，共同攻克难题；出色的问题分析和解决能力，有自主探索解决方案的能力；出色的心理素质与应变能力，面对困难勇于迎接挑战，面对复杂局面沉着、冷静、灵活；\n5、在SIGIR、VLDB、ICDE、NeurIPS、SIGCOMM、NSDI等顶级学术会议或期刊上发表过论文者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7628120805838424373","sourceKey":"bytedance","company":"字节跳动","title":"OpenViking产品实习生 - Data AML","city":"北京","category":"产品","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7628120805838424373/detail","duty":"团队介绍：Data AML是字节跳动的机器学习中台，为抖音/今日头条/西瓜视频等业务提供推荐/广告/CV/语音/NLP的训练和推理系统。为公司内业务部门提供强大的机器学习算力，并在这些业务的问题上研究一些具有通用性和创新性的算法。同时，也通过火山引擎将一些机器学习/推荐系统的核心能力提供给外部企业客户。\n\nByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n\n1、负责OpenViking的开发者问卷调研、数据分析、需求收集及转化落地；\n2、负责内容建设与品牌传播，包括但不限于社媒、公众号，跟踪数据表现；\n3、跟踪产品上线效果与用户反馈，为产品功能优化提供合理建议，挖掘最佳实践；\n4、参与开发者社区增长运营，制定社区增长策略，建立开发者分层运营体系，策划并落地社区活动；\n5、关注AI领域的技术和产品动态，为团队提供有价值的洞察和行动方案。","requirements":"1、2027届本科及以上学历在读，计算机科学、信息技术、人工智能或相关专业优先；\n2、对AI Coding产品、AI工具是重度用户，可提供作品（产品Demo、技术博客等），能独立完成中等复杂度的开发任务；\n3、了解Agent Harness，RAG和Agent记忆的相关技术概念，有搭建Agent服务的相关经验；\n4、熟悉开发者生态，了解国内外主流开发者社区（如GitHub、掘金、InfoQ等）的运营逻辑与用户特性；具备优秀的内容创作与策划能力，文字功底扎实，能够独立完成技术类、干货类内容的撰写与编辑；\n5、工作地点北京，实习时长5个月，每周4天以上。\n\n加分项：\n1、参与贡献开源项目相关经历。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7594450450141939973","sourceKey":"bytedance","company":"字节跳动","title":"算法开发实习生-SRE","city":"北京","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7594450450141939973/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：字节跳动基础架构SRE团队，主要负责构建字节跳动私有云的组件服务和稳定性保障，支撑今日头条、西瓜视频、火山小视频、抖音等字节跳动旗下全产品线。Site reliability engineering (SRE) 致力于打造高扩展、高可用系统，并将其贯彻为原则的软件工程师。\n\n1、探索大模型在智能运维领域中的应用，提供基于大模型的智能交互、根因定位和异常检测等算法服务；\n2、搭建Multi-Agent框架，具备ReAct、Memory、RAG、MCP、A2A、微调等技术能力，为运维效率提升提供智能服务；\n3、持续跟进大模型前沿技术、开源方案及其在智能运维领域的应用。","requirements":"1、2027届本科及以上学历在读，计算机、软件工程、通信等相关专业；\n2、精通AIOps，尤其是稳定性方面的智能运维，有相关项目的落地经验；\n3、理解主流大模型的算法原理，具备模型和Agent层面的算法和开发能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7220424726634940733","sourceKey":"bytedance","company":"字节跳动","title":"隐私BP实习生-隐私和数据保护办公室","city":"北京","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7220424726634940733/detail","duty":"日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n团队介绍：我们是字节跳动隐私与数据保护核心团队，联动法律、安全、研发等多方力量，为全球数亿用户构建第一道数据安全防线。聚焦隐私合规落地、数据风险防控，在超150个国家/地区的复杂隐私、数据合规场景中，构建全生命周期数据安全方案，以“隐私+数据”双通道驱动保护创新。\n为什么加入我们？\n1、全球化核心战场：加入支撑字节跳动国际化生态的关键团队，主导服务数亿用户的隐私安全体系，同字节跳动系产品一起定义行业标准；\n2、硬核能力历练：攻克数亿级数据防护，横跨美洲、欧盟、东南亚等法律差异等难题，沉淀覆盖多区域的合规技术视野；\n3、多元成长生态：融入跨多国家多城市的协作团队，参与行业隐私标杆项目，在文化碰撞中解锁国际化合规实战经验。\n\n1、负责电商、游戏、教育等业务合规风险的识别、改进、跟踪及事后评估，与法务团队合作，将法律合规要求转化为技术和流程解决方案，处置相应的风险；\n2、协助支持集团合规管理框架落地，包括按照管理框架标准实施流程制定、相关方沟通、决策记录、推进集团合规管理的成熟度；\n3、协助推进公司层面统一的合规工作专项在各业务线落地执行；\n4、配合内审内控团队，协助实施内部合规审计，包括数据权限、跨境传输合规、APP/SDK合规。","requirements":"1、本科及以上学历在读，计算机科学、信息安全、法学相关专业优先；\n2、了解重要市场的法律法规，如GDPR、CCPA、CPRA、COPPA等优先；\n3、英语作为工作沟通语言，良好的听说读写能力，具备跨国企业或国际化留学/工作经历者优先，书面表达流畅、专业；\n4、良好的团队协作能力、沟通能力、自我驱动力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7687456173532367157","sourceKey":"bytedance","company":"字节跳动","title":"内容产品实习生 - TikTok","city":"上海/北京","category":"产品","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7687456173532367157/detail","duty":"团队介绍：TikTok是一个覆盖150个国家和地区的国际短视频平台，我们希望通过TikTok发现真实、有趣的瞬间，让生活更美好。TikTok在全球各地设有办公室，全球总部位于洛杉矶和新加坡，办公地点还包括纽约、伦敦、都柏林、巴黎、柏林、迪拜、雅加达、首尔和东京等多个城市。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、支持TikTok作者理解与内容理解工作，参与“规则设计、标注管理、特征分析、模型训练”全流程环节；\n2、基于内容生态与业务目标，迭代内容理解规则；优化标注管理流程，保障内容标注的样本准确性；\n3、基于样本特征分析与数据分析，辅助算法进行内容理解建模，提升模型的准确率与召回率，并推动标签体系建设与策略优化。","requirements":"1、本科及以上学历在读，专业不限；\n2、尽快到岗，每周保证实习4天及以上，可连续实习6个月；\n3、英语听说读写流利，可作为工作语言；\n4、熟悉国际化社交媒体和内容平台，内容理解能力优秀，有内容创作经验、内容产品实习经验者优先；\n5、有良好的数据分析能力，能熟练使用SQL为加分项。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667561645229279541","sourceKey":"bytedance","company":"字节跳动","title":"后端开发工程师 - 火山引擎","city":"北京","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667561645229279541/detail","duty":"团队介绍：火山引擎是字节跳动旗下云和AI服务平台，将字节跳动快速发展过程中积累的增长方法、技术能力和应用工具开放给外部企业，通过云和AI技术，推进企业智能化转型，激发增长潜能。\n\n1、负责火山引擎产品商业化业务支撑工作，包含营销活动、交易下单、实例交付、计量计费、账务处理等业务平台的需求分析，系统分析，设计及实现；\n2、深入理解业务模型，采用合适的系统架构应对多变市场环境带来的需求变动和复杂的业务模型；\n3、攻克服务中高并发，高稳定性，大数据处理，业务合规要求带来的各种挑战及技术难关。","requirements":"1、2027届获得本科及以上学历，计算机相关专业；\n2、热爱计算机科学和技术，精通至少一门编程语言，包括但不仅限于：Java、C、C++、PHP、Python、Go；\n3、掌握扎实的计算机基础知识，深入理解数据结构、算法和操作系统知识；\n4、有优秀的逻辑分析能力，能够对业务逻辑进行合理的抽象和拆分；\n5、有强烈的求知欲，优秀的学习和沟通能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667507228895676677","sourceKey":"bytedance","company":"字节跳动","title":"数据挖掘工程师（营销方向） - 数据平台","city":"上海/北京/深圳","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667507228895676677/detail","duty":"团队介绍：数据平台是字节跳动数据中台部门，为公司多业务线（包括抖音、电商、直播和生活服务等）提供一站式大数据解决方案，涵盖数据的生产、清洗、传输、建模、分析等全流程链路，提供数据开发、实验评估、画像标签、增强分析等多元场景解决能力。同时，数据平台部门也致力于把字节跳动积累沉淀的数据中台解决方案做商业化输出，让更多行业能够应用我们的产品能力构建自己的数据中台。在火山引擎上，我们提供了营销增长套件，数据中台等相关产品解决方案，为泛互联网、金融、汽车、新零售等行业提供了行业解决方案。\n\n1、基于海量数据，利用机器学习、数据挖掘、LLM，为智能推荐、线上线下广告推荐等业务提供模型与策略，提升营销效果；\n2、理解并分析营销推荐领域的相关技术现状与前沿，为算法升级提供决策支持。","requirements":"1、2027届获得本科及以上学历，计算机、机器学习和模式识别相关专业；\n2、扎实掌握机器学习与数据挖掘技术，熟练使用开源算法库，熟悉Python、Scala等至少一门语言；\n3、具有相关项目工程化实践经历者优先；\n4、具有Hadoop、Spark等大数据框架项目开发经验者优先；\n5、沟通能力强，能够跟非技术人员对模型的优势进行有效沟通；\n6、逻辑思维好，有优秀的分析问题解决问题的能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7666323993705220357","sourceKey":"bytedance","company":"字节跳动","title":"数据库开发工程师 - AI算力基础设施","city":"深圳","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7666323993705220357/detail","duty":"团队介绍：字节跳动基础设施部门，负责字节跳动的全栈算力基础设施，从芯片服务器产研、到超大规模数据中心，到传统云平台和如今的AI Native Cloud，全方位为抖音、豆包、今日头条、飞书、火山引擎等各类产品提供领先、稳定的百万量级大规模算力基础设施服务。我们的领域涵盖数据中心建设、内核操作系统开发、服务器集群管理、高速网络通信、EB级数据存储体系、搜索型数据库探索、基于LLM的AI基础设施的研发调度与治理等，致力于打造业界领先的、面向LLM的AI云原生基础设施架构与产品矩阵。\n\n1、参与AI时代的数据库产品研发与架构设计，包括但不限于：Mem0、Agent RAG、Serverless PG、ContextSearch、Supabase、Lakebase等；\n2、参与AI数据库前沿技术探索，包括但不限于：Multi-Agent/Agentic RAG/DeepResearch前沿研究（LLM×检索)、向量检索算法研究（算法×系统×硬件协同)、多模态查询处理、基于AI Agent工作流的基础设施自动优化等；\n3、参与数据库智能策略研发：基于AI的数据库性能调优系统，包括自动索引推荐、查询计划优化、资源分配策略等；构建智能监控系统，实现异常检测、根因分析、容量预测等AIOps能力；\n4、参与AI与数据库结合的实践方案探索与落地：探索AI技术和数据库各产品结合的最佳实践方案并落地，服务超大规模的集团内部业务及火山引擎业务。","requirements":"1、2027届获得本科及以上学历，计算机、数据科学、人工智能相关专业；\n2、熟悉Go/Java/Python/C++语言中的一种，对代码质量有追求；\n3、掌握扎实的计算机基础知识，深入理解数据结构、算法和操作系统知识；\n4、有优秀的逻辑分析能力，能够对业务逻辑进行合理的抽象和拆分。\n\n加分项：\n1、了解AI领域的基本概念和常用算法，在数据库、信息检索、机器学习或人工智能系统相关领域有高质量论文、开源影响力或代表性技术成果；\n2、有Agent Memory、用户画像、搜广推特征平台、知识库等相关研究或工程经验；\n3、有AI Agent、研发AI工作流等相关实践经验；\n4、具备SQL引擎扩展开发经验，如自定义UDF/存储过程集成AI模型；\n5、参与过AI4DB或DB4AI类开源项目，如Apache MADlib、Mem0、MemOS、MemU。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7594377753097652533","sourceKey":"bytedance","company":"字节跳动","title":"视频编辑开发实习生-音视频技术","city":"上海","category":"多媒体","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7594377753097652533/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：视频与边缘部门承载了字节跳动的媒体内容分发基建及技术中台，支持了字节全系产品，如抖音、今日头条、番茄小说、西瓜视频等APP的点播、直播、实时通信、图片等多媒体业务发展，同时将业务发展过程中沉淀下来的技术能力和工具，通过火山引擎对外输出，面向各行各业用户提供视频云产品和服务，愿景是为内外部业务伙伴提供最低成本、最优画质、最低延时、最安全可靠的富媒体内容分发解决方案，助力业务伙伴降本提效实现持续增长。\n\n1、参与视频编辑服务的模块开发与接口开发调试，支持相关的场景功能验证与性能调优等；\n2、参与音视频编辑AIGC相关的处理流程的调研、测试与优化工作，包括但不限于渲染效果验证、服务部署验证；\n3、协助进行产品功能或技术方案的初步分析，整理行业动态与新技术应用场景；\n4、在导师指导下参与调度系统、任务队列或监控告警等子模块的开发或运维支持。","requirements":"1、2027届本科及以上学历在读，计算机、软件工程等相关专业优先；\n2、熟悉至少一门编程语言（如Python、C/C++、Golang等），具备良好的编码习惯和调试能力；\n3、对音视频剪辑创作技术有浓厚兴趣，了解过FFmpeg、MP4、HLS等基本概念者优先；有OpenGL、WebGL或后端多媒体开发经验亦可；\n4、具备基础的Linux使用能力，了解Git、HTTP、RESTful API等开发常识；\n5、学习能力强，责任心强，乐于钻研技术问题，具备良好的沟通能力和团队协作意识。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7688177690629556533","sourceKey":"bytedance","company":"字节跳动","title":"房产租赁实习生 - Corporate Services","city":"北京","category":"职能 / 支持","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7688177690629556533/detail","duty":"团队介绍：企业服务团队致力于为全球ByteDancer提供最佳的管理和员工体验，我们支持员工协同并高效地完成工作，同时保护和促进公司的业务发展。企业服务团队通过专业服务来改善ByteDancer的体验，同时建立并不断探索可广泛共享的新行业最佳实践。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、租赁前台支持：协助对接办公需求，完成办公室选址和现场踏勘的相关工作，参与从办公选址到合同签署的租赁全流程；\n2、项目执行支持：协助整理租赁项目的决策依据、谈判材料等，跟进内部审批与关键节点，推动相关事项按时落地；\n3、市场信息整理：收集所在城市写字楼市场、租金、政策等一手信息，参与专题研究，输出可供团队决策参考的相关分析；\n4、租后与跨部门协同：协助跟进已签约项目的租期节点提醒、台账更新和资料归档；对接行政、IT、财务、法务等团队，准确传递相关信息。","requirements":"1、本科及以上学历在读，专业不限，房地产、经济、金融、管理、数据分析等相关专业优先；\n2、学习能力强，能够快速理解办公室租赁业务，从复杂信息中抓住关键问题并形成自己的判断；\n3、有好奇心和自驱力，对写字楼市场和办公空间有真实兴趣，愿意跑现场、看楼盘，能够主动推动事情向前；\n4、具有较好的逻辑思考和结构化能力，能够把杂乱信息做适当的抽象与总结；\n5、善于沟通，表达清晰，能够与房产、财务、法务等不同团队高效协作；\n6、英文可作为工作语言者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7687448320140970245","sourceKey":"bytedance","company":"字节跳动","title":"大客户销售（餐饮行业） - 抖音生活服务","city":"郑州","category":"销售","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7687448320140970245/detail","duty":"团队介绍：抖音生活服务依托抖音POI （Point of Interest）、短视频、直播、搜索等，以“激发线下生意，丰富美好生活”为使命，致力于成为最值得信赖的生活服务平台，为用户提供更丰富、独特的生活体验，为合作伙伴提供包容且公平的健康营商生态。截至2025年底，抖音生活服务业务已覆盖400+城市，超过1500万家动销门店。抖音生活服务将继续携手生态伙伴，为用户提供值得心动的商品和服务。\n\n1、负责生活服务餐饮/游玩/服务/零售行业的大客户销售工作；\n2、负责餐饮/游玩/服务/零售行业品牌商家在本地生活服务的各项商务事宜，包括商务谈判、资源投入发掘、资源分配等，提升抖音生活服务份额占比，与公司关联部门沟通协作，确保广告的及时投放与问题反馈、广告资源的合理利用与开发；\n3、负责全国餐饮/游玩/服务/零售连锁品牌的市场规划、策略制定及实施，挖掘增长机会点和重大项目拓展，联合商户打造营销事件；\n4、通过数据分析客户需求，为客户提供咨询服务、产品培训、优化投放、数据分析等营销策略，制定整合营销方案及策略，推动各行业营销策略的实施，整合内外部资源，包括大促、数据协同、品牌门店赋能等增值服务方案等。","requirements":"1、2027届获得本科及以上学历；\n2、热爱销售工作，具备良好的客户开拓和服务能力，建立良好的客户群体关系的能力；\n3、掌握商务谈判、沟通及文字写作表达交流技巧，具有一定的市场洞察力和执行力；\n4、性格开朗，敢于面对挑战。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7685271320315414789","sourceKey":"bytedance","company":"字节跳动","title":"招聘实习生 - 招聘中心","city":"上海","category":"人力","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7685271320315414789/detail","duty":"团队介绍：人力与管理部作为公司的职能部门之一，助力字节跳动从一家创业公司发展成为拥有超过十万名员工的全球化公司。人力与管理部以“释放人才成长力，激发组织生命力”为使命，在组织、人才、文化等方面持续像打造产品一样打造公司，推动业务成长。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、负责简历的筛选、搜索、推荐及候选人意向沟通工作；\n2、负责跟进面试安排、面试反馈等招聘全流程相关工作；\n3、负责招聘渠道的开拓及维护，同步更新招聘信息，完成人才市场的盘点和研究工作；\n4、协助完成人力资源相关数据统计工作，参与探索招聘领域的优秀实践方法。","requirements":"1、本科及以上学历在读，人力资源、工商管理等专业学生优先；\n2、积极主动，乐观向上，有责任心，具有较强的团队意识；\n3、善于与人沟通、逻辑思维能力及应变能力较好，富于团队协助精神；\n4、能够连续实习3个月及以上，每周出勤4天及以上。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7682702665320007989","sourceKey":"bytedance","company":"字节跳动","title":"AI应用后端开发实习生（即梦） - 剪映CapCut","city":"深圳/北京","category":"后端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7682702665320007989/detail","duty":"团队介绍：剪映研发团队，主要支持剪映、CapCut、醒图、Hypic、即梦、Dreamina、小云雀、Pippit等多款国内外产品的研发工作，业务覆盖多元化影像创作场景，并孵化了多款AIGC明星产品，相关产品多次登顶国内外App Store 免费应用榜第一，并继续保持高速增长。加入我们，一起打造全球最受用户欢迎的影像创作和GenAI产品。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、负责即梦App功能研发工作、架构设计以及体验优化；\n2、通过调研、评估和引入前沿AI能力，与产品、设计团队紧密协作，将前沿的AIGC技术转化为实际应用；\n3、开展AI生成领域相关技术研究与应用，包括但不限于生成模型优化、多模态内容合成、实时交互体验提升等方向；\n4、持续关注行业动态和用户反馈，通过技术手段迭代产品AI应用能力，为用户创造全新体验。","requirements":"1、本科及以上学历在读，计算机、软件工程、人工智能等相关专业优先；\n2、精通至少一门编程语言，包括但不仅限于：C/C++、Python、Go、Java，有一定工程能力；\n3、熟悉算法基础和AI原理，包括不限于：机器学习、深度学习、LLM、多模态、CV等；\n4、对AIGC相关技术感兴趣，有Agent搭建、Pre-training、SFT、RL经验优先；\n5、每周出勤至少4天，实习4个月及以上。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7675312353537231157","sourceKey":"bytedance","company":"字节跳动","title":"策略运营实习生 - 抖音电商","city":"上海","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7675312353537231157/detail","duty":"团队介绍：抖音电商以“总能发现好东西”为主张，致力于成为用户发现丰富好物的首选平台。众多抖音创作者通过短视频、直播、商城等丰富的形式，给用户提供更个性化、更生动、更高效的消费体验。同时，抖音电商积极引入优质合作伙伴，为商家变现提供多元的选择。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、协助策略团队展开数据研究工作：包括但不限于行业的趋势分析、产业带研究、数据收集整理与解读、业务指标的下钻分析等；\n2、结合对市场营销、电商生态的理解，深度参与业务执行工作：包括但不限于协助电商商家端沟通、协助部门进行信息梳理、项目跟进和其他日常运营；\n3、基于对业务全貌、电商活动玩法的深入了解，与策略、运营、市场等团队并肩作战，共同推动重点业务开展；\n4、深度支持并协同履约运营团队，保证履约质量和时效服务体验。","requirements":"1、本科及以上学历在读；\n2、有行业研究、数据分析、市场营销的实习经验优先；\n3、有基础的数据分析、数据整理能力，能使用SQL、Python、Tableau、Excel优先；\n4、有扎实的项目管理能力，包括跨团队协作和沟通、信息整理汇总、结构化的提炼总结、清晰有逻辑的表达和写作；\n5、拥有较强的逻辑思维能力、自驱力和主动性，以及良好的团队沟通和合作能力，积极应对项目挑战，工作激情饱满。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7673029792892045573","sourceKey":"bytedance","company":"字节跳动","title":"平台算法实习生 - DCS","city":"杭州/北京","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7673029792892045573/detail","duty":"团队介绍：字节跳动基础设施DCS【Data Center/Cloud Service/System Service】团队，负责字节跳动全球数据中心全生命周期的运营管理，职责涵盖数据中心运维、服务器管理、资产管理、AI运维平台研发、系统服务、云服务等。致力于为抖音、豆包、今日头条、飞书、火山引擎等各类产品提供高可用、高稳定、高性能、低成本的算力资源。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、负责字节跳动全球服务器容量规划、交付、运营、运维等相关平台开发；\n2、负责在线大数据量高并发系统设计与研发；\n3、负责服务化平台和通用中台架构设计与研发；\n4、负责全球服务器相关运行数据数据分析、数据挖掘、故障预测等相关能力建设。","requirements":"1、本科及以上学历在读，计算机科学、数学、人工智能相关专业优先；\n2、热爱计算机科学和技术，精通至少一门编程语言，包括但不仅限于Java、C、C++、PHP、Python、Go；\n3、熟悉大模型应用场景和落地，包括但不限于单模态/多模态LLM训练，了解至少一种主流框架；了解OpenCV、PIL、NumPy张量操作；了解深度学习训练/推理基本流程，能够看懂、修改开源项目代码优先；\n4、了解计算机视觉基础：图像分类、目标检测、语义/实例分割基本概念；有YOLO、SegGPT任一开源模型使用经验优先；\n5、具备良好的自驱力与学习能力，优秀的沟通能力、组织协调与项目推动能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669711970535278901","sourceKey":"bytedance","company":"字节跳动","title":"AIGC算法工程师 - 中国交易与广告","city":"北京/上海/深圳","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669711970535278901/detail","duty":"团队介绍：中国交易与广告，基于个性化推荐、深度学习和大模型技术，依托抖音、今日头条、红果短剧、西瓜视频、番茄小说等多元产品，构建抖音电商、生活服务、广告营销等核心营收业务的算法策略和工程架构。部门运用领先的算法能力，精准连接海量用户与商家，通过推荐、广告和搜索算法精准匹配需求并促进交易达成，保障用户体验与商家权益，实现营收业务可持续增长；基于深厚的技术积累，构建高效、智能、可靠的交易与广告产品，全面提升多行业收入变现与市场占有。在这里，你将直面超大规模流量与复杂业务场景的技术挑战，深度应用业界领先的商业模型与算法技术，投身面向未来的数字营销能力建设，持续探索前沿技术。\n\n1、基于大模型构建文本-图像-视频跨模态创作引擎，实现从文案、图像到视频的全模态创意AIGC；\n2、针对商业化短剧和漫画短剧场景定制化训练和优化模型，提升素材生产效率、素材质量，包括迭代Reward Model指导生成模型生成多模态素材，提升广告体验和转化率等；\n3、通过自动化投放，打通AIGC创意的动态个性化生产，最终提升广告的变现效率。","requirements":"1、2027届获得本科及以上学历，计算机、机器学习等相关专业优先；\n2、热爱计算机科学和技术，对人工智能类产品有浓厚兴趣；\n3、具备扎实的编码能力，熟悉Linux开发环境，熟悉C++和Python语言优先；\n4、有扎实的数据结构和算法功底，熟悉机器学习、自然语言处理、数据挖掘、分布式计算、计算机视觉、计算机图形、语音识别与合成中一项或多项；\n5、对推荐系统、计算广告、搜索引擎相关技术有经验者优先；\n6、优秀的分析问题和解决问题的能力，对解决具有挑战性问题充满激情。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669705525936523573","sourceKey":"bytedance","company":"字节跳动","title":"多模态内容理解算法工程师 - 抖音直播","city":"北京/深圳","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669705525936523573/detail","duty":"团队介绍：直播团队负责为抖音集团旗下产品提供直播服务。团队负责直播平台技术和直播业务研发，打造灵活稳定的直播服务平台，为用户提供优质直播体验，支持电商、本地生活、游戏、节目、多人互动等不同类型的业务场景。直播业务发展迅猛，处于行业头部地位，业务发展空间巨大。现在加入我们，和优秀的人一起做有挑战的事，你的技术与创意将影响亿级用户，激发创意和丰富生活。\n\n1、负责抖音直播AI视觉互动相关的多模态内容理解工作，实现视觉内容的结构化解析和跨模态语义对齐，打造面向AI视觉互动的多模态内容理解大模型；\n2、基于CNN、VLM等技术推进模型训练、微调、评测及高效部署，推动模型在下游业务上的应用，包括AI视觉互动内容生成、Caption文本生成等，助力业务规模应用落地；\n3、规划实现并优化海量多模态数据的预处理、清洗、标注、特征提取及高效融合方法。","requirements":"1、2027届获得本科及以上学历，计算机及相关专业优先；\n2、在计算机视觉/多模态某领域有深入的研究或项目经验，在顶级学术会议有论文发表者或获得竞赛优胜者优先；\n3、熟悉多模态大模型（VLM）、大语言模型（LLM）、RL相关的算法技术，熟悉大模型相关的数据构造方法、Post-training算法，对多模态数据处理具备优秀的独立开发与调试能力；\n4、有大规模模型训练、压缩、蒸馏、微调等经验，熟悉Megatron、DeepSpeed等框架者优先；\n5、对视觉CoT有研究经验者优先；\n6、优秀的分析和解决问题的能力，对解决具有挑战性的问题充满激情，良好的沟通和团队合作能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669652440381688069","sourceKey":"bytedance","company":"字节跳动","title":"大模型策略产品经理 - TikTok","city":"北京","category":"产品","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669652440381688069/detail","duty":"团队介绍：TikTok是一个覆盖150个国家和地区的国际短视频平台，我们希望通过TikTok发现真实、有趣的瞬间，让生活更美好。TikTok在全球各地设有办公室，全球总部位于洛杉矶和新加坡，办公地点还包括纽约、伦敦、都柏林、巴黎、柏林、迪拜、雅加达、首尔和东京等多个城市。\n\n1、应用最新的大模型技术，结合国际化短视频App的业务场景，提升Chatbot产品用户体验；\n2、与评估、数据分析、算法团队紧密合作，推动项目按时按质落地；\n3、深入洞察用户需求，参与探索大模型产品的落地场景，持续迭代和优化；\n4、关心AIGC行业动态，研究行业产品动向，为产品发展提供创新思路。","requirements":"1、2027届获得本科及以上学历，计算机、人工智能、数据科学等相关专业优先；\n2、具备敏锐的用户体验洞察力和良好的数据分析能力，能够在指导下基于各种信息定位产品问题，推动问题解决；\n3、逻辑清晰，沟通能力强，具备团队协作精神；\n4、有搜索、推荐、NLP、AI相关项目经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668598472568293637","sourceKey":"bytedance","company":"字节跳动","title":"推荐算法工程师 - 抖音","city":"上海/深圳/北京","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668598472568293637/detail","duty":"团队介绍：Data-抖音团队，负责抖音APP的推荐算法、AI大模型应用、内容算法、增长算法、广告自动化投放、智能对话等算法工作，对接全链路各体裁（短视频，图文）各业务（内容消费，互动，UGC，双列，社交，生态，垂类，创作，消息，汽水音乐，精选，随变，增长投放，评论，内容理解&安全、智能对话等）。我们的工作涉及大规模推荐算法的优化、多业务复杂约束下的优化问题、多模态内容理解、LLM基础技术研究、业务Agent化和创新AI落地应用、CV/NLP等多个学术领域的算法改进工作、对多种场景的推荐架构的设计和实现和对产品数据的复杂深入的分析工作。在这里，你可以深入钻研机器学习算法的改进和优化，探索工业界最领先的推荐系统架构和推荐大模型算法、可以通过使用最新的大模型技术支持抖音的AI分身、业务智能化、智能客服等创新探索；可以通过对产品的深度理解和思考，将算法应用到业务中去；也可以通过对产品和内容生态的深度分析，影响产品未来的发展方向。\n\n1、负责抖音APP、汽水音乐APP、随变APP产品的算法模块的优化和核心项目的研究与落地，共同搭建业界领先的推荐系统，为用户提供一流的产品体验；\n2、深度参与LLM在推荐系统中的应用，包括生成式推荐、LLM4Rec、LLM as Judge、Agentic Recommendation等，深入理解各场景业务和机器学习技术，优化模型、策略，持续提升推荐效果；\n3、深入了解业务和用户行为，依托海量真实数据，进行数据挖掘和分析建模，持续提升用户体验和留存；\n4、与优秀的技术和产品同学共事，获得充分的技术探索空间和业务影响力，共同促进抖音生态的长期繁荣发展。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程等相关专业优先；\n2、具备优秀的编码能力、良好的编程风格和工作习惯，扎实的数据结构和算法功底；\n3、对推荐算法和机器学习有热情、乐于学习、思考和创新；\n4、优秀的分析问题和解决问题的能力，有良好的沟通表达能力和团队精神；\n5、在会议发表论文或ACM、机器学习等竞赛获奖，或有推荐系统、计算广告、搜索引擎等相关领域有经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668587408078375173","sourceKey":"bytedance","company":"字节跳动","title":"创作者运营 - 抖音生活服务","city":"上海/杭州/北京/广州","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668587408078375173/detail","duty":"团队介绍：抖音生活服务依托抖音POI （Point of Interest）、短视频、直播、搜索等，以“激发线下生意，丰富美好生活”为使命，致力于成为最值得信赖的生活服务平台，为用户提供更丰富、独特的生活体验，为合作伙伴提供包容且公平的健康营商生态。截至2025年底，抖音生活服务业务已覆盖400+城市，超过1500万家动销门店。抖音生活服务将继续携手生态伙伴，为用户提供值得心动的商品和服务。\n\n1、负责达人运营，具备较高内容调优能力，具备优质内容的判断能力，能结合达人能力模型和成长路径，规模化推动达人视频及直播内容的优质产出；\n2、对达人和达人供需生态有深度认知和判断，能精准捕捉潜力达人，打通多方生态资源，对达人做深度经营，成长为行业标杆，收敛成功标杆案例，沉淀具备高内容力与营销能力的达人成长方法论；\n3、持续优化人货匹配、选品机制，协助达人解决商家与达人交易撮合过程中的问题，通过拓展生态合作模式提升达人收入；\n4、高效跨团队协作以达成业务目标，和达人保持深度的合作关系，具备沉淀模式与规模增长方法论的能力。","requirements":"1、2027届获得本科及以上学历；\n2、较强的自驱力，有良好的工作文档习惯，有强烈的工作责任心，较好的学习能力，较强的拿结果能力；有本地生活或电商相关运营实习经验优先；\n3、有优秀的逻辑分析能力，能够对业务逻辑进行合理的抽象和拆分，有良好的团队合作精神；\n4、具有良好的沟通技巧，有优秀的谈判沟通技巧和跨部门共建能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668586665136523525","sourceKey":"bytedance","company":"字节跳动","title":"全栈开发工程师（生活服务-交易） - TikTok研发","city":"北京/上海","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668586665136523525/detail","duty":"团队介绍：TikTok研发团队，旨在实现TikTok业务的研发工作，搭建及维护业界领先的产品。加入我们，你能接触到包括用户增长、社交、直播、电商C端、内容创造、内容消费等核心业务场景，支持产品在全球赛道上高速发展；也能接触到包括服务架构、基础技术等方向上的技术挑战，保障业务持续高质量、高效率、且安全地为用户服务；同时还能为不同业务场景提供全面的技术解决方案，优化各项产品指标及用户体验。 \n在这里， 有大牛带队与大家一同不断探索前沿， 突破想象空间。 在这里，你的每一行代码都将服务亿万用户。在这里，团队专业且纯粹，合作氛围平等且轻松。目前在北京，上海，杭州、广州、深圳分别开放多个岗位机会。\n\n1、参与TikTok生活服务C端/B端各类场景的研发，深入理解生活服务各场景业务，与产品、设计、测试和运营团队协作，完成复杂问题抽象、技术方案设计及项目落地，并持续跟踪上线效果；\n2、负责高质量前后端与全栈工程建设，包括前端开发、接口设计、数据模型、性能优化、稳定性治理及用户体验提升等；\n3、面向实际业务场景设计和开发Agent Workflow、MCP工具及Skills，提升研发、业务运营等效率和AI自动化程度；\n4、深度运用AI Coding工具开展开发工作，提升代码开发效率与质量，主动探索AI工具在多端开发场景的优化空间，助力提升团队AI代码贡献率。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程、人工智能等相关专业优先；\n2、具备良好的沟通协作能力、自驱力和学习能力，能够使用AI Coding工具端到端推进需求迭代，覆盖从需求理解、方案设计、代码实现、测试验证、Code Review和线上排障的AI Native的开发方式；具备良好的主人翁意识，能够主动识别问题并推动解决；\n3、具备AI全栈思维，愿意借助AI能力完成从页面到接口的全链路开发，相信AI能够帮助抹平技术栈差异；具备根据工作和业务需要设计Agent Workflow的能力；\n4、具备良好的业务理解和抽象能力，能够在复杂、信息不完整的场景中主动构造上下文、拆解问题并推动端到端闭环；重视工程质量，对可维护性、性能、稳定性、可观测性、测试及上线风险有系统性认识；\n5、具备扎实的计算机基础知识（数据结构、算法、计算机网络、操作系统等），至少掌握一门编程语言；具备前端（JS/TS/Vue/React等）、客户端（Flutter/iOS/Android任一）、服务端（Golang/Python/Java任一）任一领域的开发经验，有全栈开发经验者优先；具备良好的接口设计、数据建模和系统设计能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668368427569481989","sourceKey":"bytedance","company":"字节跳动","title":"用户体验判责策略产品经理（AI Agent方向） - 抖音电商","city":"上海/北京","category":"产品","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668368427569481989/detail","duty":"团队介绍：抖音电商以“总能发现好东西”为主张，致力于成为用户发现丰富好物的首选平台。众多抖音创作者通过短视频、直播、商城等丰富的形式，给用户提供更个性化、更生动、更高效的消费体验。同时，抖音电商积极引入优质合作伙伴，为商家变现提供多元的选择。\n\n1、负责抖音电商的售后判责大模型能力建设，包含判责策略定义、特征引入及场景建设；\n2、负责抖音电商的售后判责模型的评测Agent建设，包括评测标准的制定、评测Agent建设、评测结果输出及归因优化；\n3、了解电商平台售后和服务的场景，推进判责结果在电商各场景的应用落地；\n4、紧密联动运营、研发、QA等多团队，保障高效高质量的完成产品交付，跟进产品效果，驱动目标完成。","requirements":"1、2027届获得本科及以上学历，计算机、人工智能、软件工程、数据科学等相关专业优先；\n2、具有敏锐的需求洞察和抽象能力，能够从复杂业务逻辑中发现问题的本质，找到最优解决方案并推动落地；\n3、具备较好的数据分析能力，能够进行独立SQL分析者优先；\n4、具备快速学习能力、强执行力，有较强的自驱力和责任心；\n5、有良好的团队沟通协作能力，能保障多业务、多角色的项目顺利推进，结果导向。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668192668948678917","sourceKey":"bytedance","company":"字节跳动","title":"商城用户产品经理 - 抖音电商","city":"上海","category":"产品","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668192668948678917/detail","duty":"团队介绍：抖音电商以“总能发现好东西”为主张，致力于成为用户发现丰富好物的首选平台。众多抖音创作者通过短视频、直播、商城等丰富的形式，给用户提供更个性化、更生动、更高效的消费体验。同时，抖音电商积极引入优质合作伙伴，为商家变现提供多元的选择。\n\n1、负责抖音商城用户增长规模与流量效率等产品建设，覆盖首页框架迭代、全域流量导流、营销活动三大方向；承担首页体验优化、流量转化链路、营销工具与玩法等产品项目，通过产品方案持续优化增长效果，兼顾业务目标与用户体验；\n2、深入挖掘用户需求、理解用户结构与流量分发逻辑，围绕首页场景、导流场景、大促/日常活动场景持续输出创新产品思路并推动落地，通过数据复盘与用户研究持续打磨迭代；\n3、关注电商行业趋势及业内优秀增长、首页产品、营销活动案例，总结沉淀方法论，输出符合抖音商城用户特性与业务阶段的产品方案，沉淀可复用的产品能力。","requirements":"1、2027届获得本科及以上学历；\n2、具备较强的数据洞察与逻辑分析能力，思维严谨，能够通过数据拆解问题、验证产品方案效果；\n3、自驱力强，敢于突破创新，具备良好的责任心，能适应业务环境；\n4、有互联网增长、电商产品、活动营销相关实习经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667855299516320005","sourceKey":"bytedance","company":"字节跳动","title":"大模型策略产品经理（抖音AI产品人才校招） - 抖音UGC","city":"北京","category":"产品经理","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667855299516320005/detail","duty":"团队介绍：我们为抖音UGC的交流活跃与氛围负责，通过激发用户分享其兴趣爱好、衣食住行真实生活，逐渐构建真诚互动、具有一定利他性的UGC内容生态。团队组成多元， 有成员通过敏锐的用户洞察做产品创新，有成员凭借对内容风向的前瞻判断造圈层趋势，有成员在字节跳动丰富的大模型资源之上推动策略创新。欢迎大家与我们一起，以内容和兴趣连接人与人，建设抖音的竞争优势与壁垒。\n\n这是抖音面向具备AI能力的同学发起的校招项目，覆盖产品、策略运营方向。\nAI 正在重新定义产品，也在重新定义\"做产品\"这件事 —— AI Native 的产品，需要你既能理解大模型技术边界，又能定义产品价值。\n如果你也有着许多的奇思妙想， 欢迎加入抖音，把想法落地成亿万用户真实可感的产品体验，来抖音，和我们一起探索 AI 产品的下一种可能！\n\n1、参与抖音UGC内容策略建设，结合用户洞察与数据分析，协助制定、落地并迭代内容产品策略，优化平台内容生态与用户体验；\n2、跟进AI大模型、多模态技术在内容场景的落地应用，参与内容识别、用户人群挖掘、内容推荐等策略优化，协同技术、运营、审核等团队，提升平台内容质量与分发效率；协助搭建模型效果评估体系，负责日常数据分析、A/B实验设计与效果复盘，定位模型识别偏差、指标不达标的问题，推动迭代优化；\n3、具备良好的内容感知能力，可将用户体验、内容审美转化为标准化规则与可量化数据信号，沉淀可复用的流程、工具与文档；\n4、持续关注内容行业与AI前沿技术，结合业务场景输出创新思路，助力业务高效迭代。","requirements":"1、2027届获得本科及以上学历，理工科、统计、数据、新媒体、产品相关专业优先；\n2、了解AI大模型基础原理与落地场景，掌握基础Prompt使用，有LLM内容理解、多模态、模型评估相关项目/实习经历优先；\n3、对内容质量、用户审美敏感，有独立内容判断力，具备良好的产品感知；\n4、逻辑清晰，掌握SQL，具备扎实的数据分析、实验复盘能力；\n5、学习能力强、乐于创新，沟通协作与执行力优秀，有较强的自驱力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667542779799652661","sourceKey":"bytedance","company":"字节跳动","title":"电商运营管培生（POP） - TikTok Shop","city":"上海","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667542779799652661/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商。平台汇聚全球优质商家与创作者，通过短视频、直播等多场景连接消费者，让新奇好物畅销全球，让美好生活触手可得。目前团队分布在美国、英国、法国、印尼、墨西哥、中国等全球多个国家和地区，在这里你将有机会深入国际业务场景，面向全世界商家及用户，和跨区域团队协作，共同探索创新购物模式。期待和优秀的你一起创造更多可能！\n\n项目介绍：起航计划是国际电商跨境业务板块专为2027届校招生打造的运营管培项目，旨在寻找优秀的有潜力应届毕业生，结合系统的培训与实践，助力他们在国际电商运营领域扬帆起航，迅速提升专业技能，成长为跨境业务未来领军人物。与字节跳动一起，实现“好货卖全球”。 \n\n项目亮点： \n1、全球化视野：有机会深入全球场景，面向全球商家及用户，创新互动式趣味购物模式； \n2、大咖导师带教：行业大牛专属辅导，全程助你提升业务能力与素养； \n3、快速成长通道：定制化职业发展指导，给你更快速的成长； \n4、灵活轮岗机会：安排轮岗实践，深入不同业务板块，让你全方位了解国际电商价值链。\n\n1、负责达人与机构运营相关工作，参与运营方案设计与短视频、直播等内容玩法支持；\n2、支持商家内容运营，提升商家直播、短视频等内容场运营能力，推动内容相关经营指标提升，沉淀运营方法；\n3、负责跨境业务营销活动运营，参与平台活动策划、营销玩法设计、场域资源协同及用户认知建设，推动活动落地；\n4、负责招商、育商、行业类目、货盘等策略分析与输出，支持搜索推荐、商城频道运营等方向；\n5、输出市场洞察与专题分析，支持重点方向规划完善。","requirements":"1、2027届获得本科及以上学历，理科、商科、传播类相关专业优先；\n2、英语口语流利交流，有国际化留学经验优先，有相关英语成绩单或证书可随简历一并上传（如雅思、托福等）；\n3、有较强的数据分析能力、问题解决能力和沟通协作能力；\n4、积极主动，责任心强。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667422799551727877","sourceKey":"bytedance","company":"字节跳动","title":"大模型算法工程师 - 抖音用户增长","city":"北京/深圳","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667422799551727877/detail","duty":"团队介绍：抖音用户增长（User Growth）负责抖音、今日头条、番茄小说等多个产品的用户增长业务，建立行业领先的增长和营销技术，打造极致的用户体验。加入我们，有机会参与亿级用户场景的开发与架构工作，也有机会从数据出发，利用策略和模型为业务带来更大的助力。\n\n1、深度参与User Growth团队在AI4SE（AI for Software Engineering）、AI4DA（AI for Data Analysis）等方向相关算法的设计与研发；\n2、深入研究大语言模型（LLM）和视觉模型（VLM）的前沿技术，基于业务需求设计并实现解决方案；\n3、持续关注大模型领域的技术动态，并推动前沿技术在业务中的落地。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程等相关专业优先；\n2、具备扎实的编程能力、数据结构与算法基础，具有快速学习新技术的能力；\n3、熟悉大模型（LLM&VLM）训练技术，复现过业内领先工作优先；\n4、具备良好的沟通协作能力，能够与团队共同探索新技术、推进新技术落地。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7666763144032930053","sourceKey":"bytedance","company":"字节跳动","title":"大客户销售（本地服务与亲子教培） - 抖音生活服务","city":"上海/广州/杭州/北京/成都/深圳","category":"销售","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7666763144032930053/detail","duty":"团队介绍：抖音生活服务依托抖音POI （Point of Interest）、短视频、直播、搜索等，以“激发线下生意，丰富美好生活”为使命，致力于成为最值得信赖的生活服务平台，为用户提供更丰富、独特的生活体验，为合作伙伴提供包容且公平的健康营商生态。截至2025年底，抖音生活服务业务已覆盖400+城市，超过1500万家动销门店。抖音生活服务将继续携手生态伙伴，为用户提供值得心动的商品和服务。\n\n1、负责生活服务餐饮、游玩、服务、零售行业的大客户销售工作；\n2、负责餐饮、游玩、服务、零售行业品牌商家在本地生活服务的各项商务事宜，包括商务谈判、资源投入发掘、资源分配等，提升抖音生活服务份额占比，与公司关联部门沟通协作，确保广告的及时投放与问题反馈、广告资源的合理利用与开发；\n3、负责全国餐饮、游玩、服务、零售连锁品牌的市场规划、策略制定及实施，挖掘增长机会点和重大项目拓展，联合商户打造营销事件；\n4、通过数据分析客户需求，为客户提供咨询服务、产品培训、优化投放、数据分析等营销策略，制定整合营销方案及策略，推动各行业营销策略的实施。整合内外部资源，包括大促、数据协同、品牌门店赋能等增值服务方案等。","requirements":"1、2027届获得本科及以上学历；\n2、热爱销售工作，具备良好的客户开拓和服务能力，建立良好的客户群体关系的能力；\n3、掌握商务谈判、沟通及文字写作表达交流技巧，具有一定的市场洞察力和执行力；\n4、性格开朗，敢于面对挑战。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7665928898505853237","sourceKey":"bytedance","company":"字节跳动","title":"行业产品运营 - 抖音生活服务","city":"北京/上海","category":"产品运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7665928898505853237/detail","duty":"团队介绍：抖音生活服务依托抖音POI （Point of Interest）、短视频、直播、搜索等，以“激发线下生意，丰富美好生活”为使命，致力于成为最值得信赖的生活服务平台，为用户提供更丰富、独特的生活体验，为合作伙伴提供包容且公平的健康营商生态。截至2025年底，抖音生活服务业务已覆盖400+城市，超过1500万家动销门店。抖音生活服务将继续携手生态伙伴，为用户提供值得心动的商品和服务。\n\n1、负责生活服务酒店行业的产品运营，围绕酒店C端产品功能、流量策略、目的地经营等重点业务，从不同分层商家及用户的经营痛点出发，挖掘业务增长机会，为酒店行业基础产品能力及重点专项的经营结果负责；\n2、基于酒店行业经营场景和业务策略，设计并落地行业解决方案，推动包括但不限于搜索、货架、C端交易转化、平台营销及流量探索等模块的产品能力建设与持续优化；\n3、聚焦酒店行业开展深度分析，通过对商业模式、用户需求、流量机制、供需关系等理解，洞察行业机会，并结合抖音内容、直播、搜索及货架等用户场景，产出对业务有价值的关键经营策略，明确可落地的产品方向；\n4、结合用户分层、消费行为和交易链路，参与目的地经营等项目用户运营及策略设计，推动用户拉新、活跃、转化、留存和复购等核心指标提升；\n5、协同产品、研发、行业运营、商家运营、营销及数据等团队，推动产品需求和运营策略从问题诊断、方案设计、上线落地到效果复盘的完整闭环，并沉淀可复用的行业运营方法论。","requirements":"1、2027届获得本科及以上学历；\n2、有产品运营、用户运营、用户研究、商业分析或酒旅行业相关经历者优先，有AI应用相关项目实践者优先；有互联网平台产品运营、用户运营或策略运营实习经历者优先，重点关注在电商、内容社区、本地生活、酒旅等业务中取得明确项目成果的同学；\n3、具备良好的行业敏感度、用户视角和抽象能力，对产品创新有热情，能够输出业务策略，深度参与产品功能的上线及迭代；\n4、具备结构化思维和较强的数据分析能力，逻辑清晰，能够通过数据分析发现经营问题，挖掘用户需求、客户痛点及业务增长机会；\n5、具备一定的策略运营能力，能够围绕商家经营、用户分层、权益设计、交易转化、流量分配等场景提出可落地的解决方案；\n6、具备良好的横向沟通和跨团队协作能力，学习能力及工作韧性强，能够快速适应业务变化，主动推动复杂事项并对结果负责。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7665685397213595909","sourceKey":"bytedance","company":"字节跳动","title":"创意设计师 - 抖音生活服务","city":"北京/上海","category":"视觉设计","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7665685397213595909/detail","duty":"团队介绍：抖音生活服务依托抖音POI （Point of Interest）、短视频、直播、搜索等，以“激发线下生意，丰富美好生活”为使命，致力于成为最值得信赖的生活服务平台，为用户提供更丰富、独特的生活体验，为合作伙伴提供包容且公平的健康营商生态。截至2025年底，抖音生活服务业务已覆盖400+城市，超过1500万家动销门店。抖音生活服务将继续携手生态伙伴，为用户提供值得心动的商品和服务。\n\n1、负责抖音生活服务线下业务的创意视觉工作，包含线下物料的设计，制定创意方案，创作主视觉，完善设计细节；\n2、关注行业内设计趋势，有过一定线下物料、周边礼品、包装设计经验；\n3、洞察和分析设计趋势，研究目标用户审美倾向，定制符合体验且有创意的设计方案。","requirements":"1、2027届获得本科及以上学历，设计类专业优先；\n2、可独立完成设计工作，有较好的平面排版及主视觉创造能力，能很好的整合信息及元素，完成各种风格的画面设计；\n3、有较强创意能力，富有好奇心和娴熟的设计技巧，能够突破传统创造新的视觉语言；\n4、会用AI工具辅助创意设计、落地设计物料；\n5、良好的团队合作精神，细心，具有较强责任感。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7664514265328503045","sourceKey":"bytedance","company":"字节跳动","title":"客户端开发工程师（AI搜） - 抖音用户产品","city":"北京/上海/深圳","category":"客户端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7664514265328503045/detail","duty":"团队介绍：抖音用户产品研发团队为抖音全业务提供研发支持与底层技术能力，是驱动业务持续进化的重要工程力量之一。团队围绕首页、推荐、搜索、图文、中长视频、AI 创作、相机、账号及社交通讯等核心场景，承担从客户端、服务端到 AI 工程链路的端到端建设，在亿级 DAU 的真实流量下，持续攻坚极致体验与前沿 AI 系统的工程命题。\n我们相信，AI 正在重塑产品的底层架构。团队依托大模型与多模态技术、Multi-Agent 系统工程、在线推理与评测基础设施，面向下一代 AI 原生应用持续投入：在社交与通讯场景，探索长期记忆、多模态理解与人格化对话的技术边界，构建真正能陪伴用户的 AI 交互系统；在内容与创作场景，建设面向亿级创作者的多模态生成与可控创作引擎，让 AI 成为创作者的表达延伸；在搜索与信息获取场景，探索生成式检索、Agentic Search 与个性化推理的新一代系统架构，重新定义 \"人与信息\" 的连接方式。\n这里有工业界领先规模的真实流量，有最前沿的 AI 工程命题，也有一群把技术做到极致的同行者。诚邀热爱技术、追求极致、渴望在真实世界解决硬核问题的你加入我们，一起在 Agent 驱动的技术浪潮中，构建支撑大规模用户的新一代产品。\n\n1、负责抖音搜索和AI搜等相关产品的客户端开发工作，完成从需求分析、方案设计到编码上线的完整研发流程；\n2、参与系统架构设计与优化、性能调优、API设计、自动化测试等工程化工作，提升系统的稳定性和可维护性；\n3、AI Coding实践：使用AI Coding工具（如Cursor、Copilot、TRAE、Claude Code等）辅助日常开发，探索AI驱动的研发提效方式；\n4、参与将AI能力融入到搜索的技术方案设计与落地，在实践中验证和优化AI驱动开发流程，持续提升生产力。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程等相关专业优先；\n2、热爱计算机科学和技术，对移动产品有浓厚兴趣；\n3、扎实的数据结构和算法基础；精通至少一门编程语言，包括但不限于：Java、Objective-C、Swift、C、C++；\n4、关注用户体验，能够积极把技术转化到用户体验改进上；\n5、有优秀的逻辑分析能力，能够对业务逻辑进行合理的抽象和拆分；\n6、良好的沟通能力与自驱力，能在AI辅助下独立推进任务。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7640103627147938101","sourceKey":"bytedance","company":"字节跳动","title":"多模态内容理解算法实习生-抖音直播","city":"上海","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7640103627147938101/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：团队负责抖音、抖音极速版、抖音火山版等App的直播体裁基建和直播营收业务，直播体裁基建立足对边生产边分发时效性高的直播体裁的理解，结合多模态信号理解动态的时间切片和长尾兴趣点，建立短视频域到直播域的兴趣迁移，在全场景分发直播体裁，满足用户看播需求并服务于营收、电商、生活服务、游戏等多业务。直播营收致力于为歌唱/舞蹈/弹奏/朗读/情感/户外等广泛的具有一技之长的普通人通过直播这个舞台被更多人看到获得收入，并满足用户多层次的精神消费和情感表达诉求，让优质内容供给持续增长反哺整个直播生态。\n\n1、研究方向：提升视频、音频、图像、文本及多模态的大模型基础能力，在业务领域与通用领域取得行业领先的效果，建设体系化的模型能力提升方法论；探索理解大模型与生成大模型能力结合互补模式，探索并落地一体化模型并取得更高的模型效果；推动多模态内容理解能力在推荐场景的落地应用；\n2、负责抖音直播业务场景下的内容理解工作，建设多模态大模型、生成式模型等前沿模型技术能力，接近人类感知认知模型能力，产出相应的研究成果；\n3、跟进行业最新技术进展，探索多模态方向的新技术研究与落地。","requirements":"1、2027届硕士及以上学位在读，计算机/软件/人工智能/数学等相关专业的优先；\n2、具有扎实的机器学习基础，对深度学习、大语言模型、多模态模型、生成式模型等内容理解与生成技术有深入的理解，数理功底扎实，自学能力强；有扎实的编码能力，熟练使用相关机器学习框架和工程框架；\n3、在多模态大模型领域有经验，在短视频、图文算法领域有经验者优先；在计算机科学高水平会议和期刊如NIPS、ICML、CVPR、ICCV、ECCV、IJCAI、AAAI、KDD、SIGIR、WWW、ACL、PAMI、IJCV等发表过论文或有竞赛经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7633857383984826629","sourceKey":"bytedance","company":"字节跳动","title":"平台研发实习生-App Infra","city":"深圳","category":"后端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7633857383984826629/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：App Infra是字节跳动面向应用的基建中台部门，以App侧性能/稳定性深度优化为基础，结合LLM、Agent、生成式推荐模型等前沿技术，为字节跳动旗下的核心应用提供终端+平台的解决方案。于下层，结合操作系统、虚拟机、工具链、编译器等技术，建设了稳定性、流畅性、电量在内全链路的监控体系和调试分析工具；于上层，则结合端侧特征工程、深度学习模型/决策树模型/SLM训练等基建，围绕搜索/推荐/广告/直播/电商等场景，建设了云端协同推荐、品质体验优化等端智能解决方案。如果你热爱挑战底层技术、追求极致优化，又渴望把AI转化为千万用户感受得到的流畅与智能——欢迎加入，和我们一起打造下一代移动体验！\n\n1、参与字节跳动亿级DAU产品端智能服务端研发，建设高可用、高并发服务架构，保障业务链路稳定；\n2、参与大模型端云协同方案的探索，优化资源调度，协同移动研发工程师完成业务落地；\n3、通过Agent技术实现解决方案自动化迭代，覆盖特征工程、模型训练、策略优化、部署观测的完整流程。","requirements":"1、2027届硕士及以上学位在读，计算机、通信和电子信息科学等相关专业优先；\n2、掌握C++/Go/Python中任意一门后端开发语言，了解常用开发框架与基础组件；\n3、了解MySQL、Redis等常见存储/缓存系统的基本使用方法和原理。\n\n加分项：\n1、理解LLM原理，具备Agent系统设计与落地经验，关注Agent上下文管理、状态维护与效果评估，能持续提升智能体执行效率与可靠性；\n2、了解本地大模型部署与推理框架，对模型量化、加速或推理优化有一定实践经验或认知；\n3、具备大数据处理、分布式系统相关课程或项目经验，对高并发、高可用系统有基本认识。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7594490378343581957","sourceKey":"bytedance","company":"字节跳动","title":"端到端视频编解码实习生-音视频技术","city":"杭州","category":"多媒体","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7594490378343581957/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：视频与边缘部门承载了字节跳动的媒体内容分发基建及技术中台，支持了字节全系产品，如抖音、今日头条、番茄小说、西瓜视频等APP的点播、直播、实时通信、图片等多媒体业务发展，同时将业务发展过程中沉淀下来的技术能力和工具，通过火山引擎对外输出，面向各行各业用户提供视频云产品和服务，愿景是为内外部业务伙伴提供最低成本、最优画质、最低延时、最安全可靠的富媒体内容分发解决方案，助力业务伙伴降本提效实现持续增长。\n\n1、端到端视频压缩框架研究与实现：参与设计并实现高压缩率、低复杂度的端到端压缩网络，攻坚1080p视频实时解码，并以压缩性能超越H.266/VVC为目标；\n2、模型设计与性能优化：围绕主流研究方向，研究部署友好的时空上下文建模、码率控制与熵编码结构设计，持续提升端到端压缩收益；\n3、模型高性能推理优化：探索量化感知训练、算子融合等技术，极致优化模型推理效率、并行计算与存储访问，使神经网络模型能高效运行在目标硬件上；\n4、系统化评测与分析：构建系统化的编解码器评测流水线，对方案进行模块级复杂度评估和全面的性能分析，识别并优化端到端链路中的关键瓶颈，实现率-失真-复杂度的联合优化。","requirements":"1、2027届硕士及以上学位在读，计算机科学与技术、电子信息工程、通信工程、应用数学等相关专业优先；\n2、熟练掌握Python与至少一种深度学习框架（如PyTorch/TensorFlow），具备独立设计、训练和调试复杂神经网络的能力；\n3、理解深度学习基本原理，熟悉CNN、Transformer等主流网络结构；对视频/图像压缩、信号处理、信息论有基本的理论储备；\n4、有实际的深度学习项目经验，能够独立完成模型的设计、训练、调试与评估；\n5、对视频编码与深度学习的交叉领域怀有浓厚兴趣，有持续追踪和学习前沿技术的热情与主动性；\n6、具备优秀的逻辑思维与问题分析能力，能够系统性地定位、分析并解决科研或工程中遇到的问题。\n\n加分项：\n1、在相关领域顶级会议/期刊发表过论文，或有开源项目贡献经验；\n2、熟悉JPEG-AI/IEEE1857/MPEG-VCM等端到端压缩标准或H.265、H.266等视频编码标准；\n3、具备GPU/NPU平台的性能优化经验。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7593028823600498997","sourceKey":"bytedance","company":"字节跳动","title":"前端开发实习生-APM","city":"杭州","category":"前端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7593028823600498997/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：字节跳动APM(Application Performance Management) 团队负责公司所有服务端、移动端、 前端、 跨端产品的稳定性和性能质量监控保障，构建业界领先的可观测性基础设施，结合机器学习智能化，提供一站式平台覆盖字节跳动各业务线的排障、监控和稳定性提升等需求。\n\n1、负责字节跳动Web端基础体验的基建（涵盖H5、小程序、Node.js、Electron等），通过Agentic AI提供一系列围绕观测、排障、治理场景的智能体以及智能解决方案，全方位提升业务Web应用的基础体验；\n2、负责前端性能分析工具的设计开发和落地，Web端、Node.js监控工具的设计开发和落地，APM相关平台的前端开发；\n3、负责前端基础体验相关标准的制定、落地以及Workflow/Agent Infra相关的能力建设。","requirements":"1、2027届本科及以上学历在读，计算机、通信和电子信息科学等相关专业优先；\n2、熟练掌握一种及以上前端语言，包括HTML/CSS/JavaScript/TypeScript等；\n3、熟悉前端工程化，在开发效率、性能体验、稳定性、自动化等方面有一定的认知和实践。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7592840560030419253","sourceKey":"bytedance","company":"字节跳动","title":"前端开发实习生-TikTok生活服务","city":"北京","category":"前端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7592840560030419253/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：TikTok是一个覆盖150个国家和地区的国际短视频平台，我们希望通过TikTok发现真实、有趣的瞬间，让生活更美好。TikTok 在全球各地设有办公室，全球总部位于洛杉矶和新加坡，办公地点还包括纽约、伦敦、都柏林、巴黎、柏林、迪拜、雅加达、首尔和东京等多个城市。\nTikTok Local Services，我们以‘激发新生活，助力好生意’为使命，致力于成为全球用户与合作伙伴的首选生活服务平台。我们不断努力为用户提供更丰富、独特的生活体验，同时为合作伙伴打造一个包容且公平的健康商业生态。在这里，你将充分参与国际化生活服务业务的各个阶段，经历早期到全球布局流程。\n\n1、参与TikTok业务产品研发，深度参与产品需求讨论，C 端和 B 端的功能构建等；\n2、参与设计基于前端和全栈的解决方案，核心代码开发、组件抽象以及系统调优等；\n3、参与系统工程效率和性能优化，提升研发效率以及用户体验；\n4、调研和学习前端新技术，进行技术分享并在重要项目内落地，参与部门前端和全栈技术建设。","requirements":"1、2027届本科及以上学历在读，计算机、软件工程等相关专业优先；\n2、热爱计算机科学，对数据分析、前端架构、渲染和性能等技术有热情； \n3、精通Javascript、HTML、CSS，熟悉DOM、HTTP协议等前端领域知识，至少掌握一种主流前端框架（如React/Vue等） ； \n4、有优秀的逻辑分析能力，能够对业务逻辑进行合理的抽象和拆分； \n5、有强烈的求知欲，优秀的学习能力和沟通能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7314217905796614427","sourceKey":"bytedance","company":"字节跳动","title":"测试开发实习生-生活服务","city":"上海","category":"测试","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7314217905796614427/detail","duty":"日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n团队介绍：生活服务业务依托于抖音、抖音极速版等平台，致力于促进用户与本地服务的连接。过去一年，生活服务业务开创了全新的视频种草和交易体验，让更多用户通过抖音发现线下好去处，也帮助众多本地商家拓展了新的经营阵地。我们期待你的加入，一同为亿万用户创造更美好的生活。\n\n1、参与产品测试的全流程，包括需求评审、设计评审、制定测试计划、测试用例设计及执行、缺陷跟踪、测试报告等；\n2、开发测试工具和自动测试框架、自动测试脚本，进行自动化测试，提升测试效率；\n3、对产品、流程提出持续性改进意见，提升产品质量和研发效率。","requirements":"1、本科及以上学历在读，计算机软件、通讯相关专业优先；\n2、熟悉至少一种编程语言；\n3、良好的数据结构、算法基础；\n4、学习能力强，有较强分析、定位和解决问题的能力，较强逻辑思维能力和表达能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7677585479047563573","sourceKey":"bytedance","company":"字节跳动","title":"AI Agent开发工程师 - Data-抖音/直播/电商/剪映","city":"北京/杭州","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7677585479047563573/detail","duty":"团队介绍：Data-架构团队是字节跳动的核心技术引擎，为抖音、今日头条、番茄小说、剪映等旗舰产品构建大规模、高可用、可持续演进的推荐、搜索与广告工程架构。团队深耕推荐架构、搜索架构、广告架构、机器学习基础设施、在线服务架构与稳定性工程等领域，在千亿乃至万亿级数据规模、超大流量与复杂业务逻辑的真实工程挑战中，持续以技术创新驱动人与信息、人与服务的高效连接，服务全球数亿用户。\n目前，团队正积极探索搜广推架构下一代范式：从大规模在线预估框架到生成式推荐大模型的训练、后训练与端到端推理，从分布式异步图引擎、统一数据编排到平台化业务策略与 Infra Research，让大模型真正落地于亿级流量的真实在线系统。欢迎热爱分布式、AI 大模型、搜广推架构的同学加入。\n\n1、参与RAG与Agent上下文数据库的框架和中间件的后端开发和交付，包括记忆抽取与检索、长上下文管理等核心能力，实现公有云产品的特性交付和需求支持，参与开源项目Openviking的开发；\n2、在多模态理解（文档、图片、视频、3D模型）、RAG、记忆/自进化、LLM-wiki等领域的效果上持续演进，做到具备行业竞争力；\n3、参与大规模Agent上下文基础设施的开发，对于数据处理Pipeline、检索引擎、检索服务的稳定性和性能吞吐负责。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程等相关专业优先；\n2、掌握良好的编程能力，熟悉C++/Golang/Python/Java等其中一种语言，坚持简洁易读代码设计风格；\n3、掌握常见的后端开发技术，如Linux操作系统、通讯协议、微服务、数据库、消息队列、Web框架等；\n4、具备良好的研究能力，具有出色的分析、自主解决问题的能力，掌握科学的评测方法，对大模型、Agent方向有热情。\n\n加分项：有RAG、记忆、自进化、Agent框架、视频生成等开源项目或研发经验优先，有相关顶会论文发表优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669698605365709061","sourceKey":"bytedance","company":"字节跳动","title":"经营分析 - 抖音电商","city":"上海","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669698605365709061/detail","duty":"团队介绍：抖音电商以“总能发现好东西”为主张，致力于成为用户发现丰富好物的首选平台。众多抖音创作者通过短视频、直播、商城等丰富的形式，给用户提供更个性化、更生动、更高效的消费体验。同时，抖音电商积极引入优质合作伙伴，为商家变现提供多元的选择。\n\n1、协助策略团队展开经营分析、数据研究工作：包括但不限于周维度经营分析、行业的趋势分析及研究、数据收集整理与解读、业务指标分析等；\n2、参与业务指标体系和数据体系建设，协助数据监控看板建设和业务经营诊断报告输出，提供决策支持；\n3、协助推进分析建议在行业的应用推进，跟踪和复盘落地效果。","requirements":"1、2027届获得本科及以上学历，统计学、应用数学、计算机等理工科专业优先；\n2、对数据敏感，有较强的数据分析、数据整理能力，熟练使用SQL、Python等，有互联网数据分析、经营分析、商业分析实习经验优先；\n3、拥有较强的逻辑思维能力、自驱力和主动性，良好的团队沟通和合作能力，喜欢挑战性工作，工作激情饱满。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667840882890590469","sourceKey":"bytedance","company":"字节跳动","title":"GEO策略运营（抖音AI产品人才校招） - 抖音","city":"北京","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667840882890590469/detail","duty":"团队介绍：抖音致力于打造一个开放、积极、多元、友善的平台，鼓励表达、沟通和记录，激发创造，丰富人们的精神世界，让现实生活更美好。我们通过AI算法驱动的个性化推荐与智能创作工具，满足用户表达、学习、娱乐、社交、消费等需求。回顾抖音一路走来的历程，我们在帮助亿万用户记录美好生活的过程中，努力变得更好。\n\n这是抖音面向具备AI能力的同学发起的校招项目，覆盖产品、策略运营方向。\nAI 正在重新定义产品，也在重新定义\"做产品\"这件事 —— AI Native 的产品，需要你既能理解大模型技术边界，又能定义产品价值。\n如果你也有着许多的奇思妙想， 欢迎加入抖音，把想法落地成亿万用户真实可感的产品体验，来抖音，和我们一起探索 AI 产品的下一种可能！\n\n1、负责各产品GEO运营策略制定与落地，挖掘GEO优化机会，拿到对应业务结果；\n2、深度研究主流AI平台，输出内容优化策略，提升产品在AI场景中的可见性和权威性；\n3、具备多渠道内容分发和优化能力，保障产品核心信息的一致性与权威性，提升内容引用率；\n4、高效协调产品、算法、工程等多团队，确保产品落地实施与持续迭代。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程等相关专业优先；\n2、有AI相关作品集者优先；具备大模型原生产品或业务应用经验，有GEO/SEO实操案例者优先；\n3、具备良好的文字撰写与编辑能力，能独立策划、撰写适配AI抓取偏好的结构化内容者优先；\n4、对AI领域有极大兴趣3，对技术的发展阶段和行业应用有深入理解和专业洞见，日常使用AI产品，具有创新精神和进取心的优先；\n5、出色的团队协作与沟通能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667816003494054149","sourceKey":"bytedance","company":"字节跳动","title":"推荐算法工程师 - TikTok Shop","city":"上海/北京/杭州","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667816003494054149/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商业务，致力于成为用户发现并获取优价好物的首选平台。面向直播电商、视频内容电商、货架电商等多元购物场景，国际电商持续为全球用户提供更个性化、更主动、更高效的消费体验，也为商家提供稳定、可靠、可持续增长的平台服务，推动“新奇好物畅销全球，美好生活触手可得”的使命落地。\n目前，国际电商算法团队分布在中国、美国、新加坡等多个国家和地区，深度参与全球化业务建设。加入我们，你将有机会面向全球用户、商家和商品生态，与跨区域的产品、工程、运营和业务团队协作，持续提升商品供给质量、用户购物体验、平台交易效率与履约体验，共同探索内容电商与智能购物的新模式。\nData-国际电商团队是 TikTok Shop 的核心算法技术力量，专注于电商场景下的算法创新与规模化落地，方向包括但不限于：生成式推荐与大规模 Foundation Model、多模态商品理解与内容生成、搜索与导购、智能客服、风控治理、物流履约优化、商家经营智能化，以及 Agentic 智能体在电商全链路中的应用。我们希望通过先进的算法能力，帮助用户更高效地发现感兴趣的商品，帮助商家实现更高质量的经营增长，并持续提升交易各环节的智能化水平。\n在这里，你将与一流的产品和技术团队合作，面对复杂且真实的国际化电商挑战，推动前沿技术在大规模业务场景中落地，与团队一起创造更多可能。\n\n1、负责推荐系统全链路的搭建和优化：参与商品、短视频、直播多场景的个性化推荐算法研发，覆盖召回、粗排、精排、重排混排、供给和生态优化、用户增长、体验复购、兴趣探索等推荐系统各种环节的算法优化工作；\n2、用户兴趣建模：\n1）超长行为序列建模：在万级长度的用户行为序列上做兴趣建模，处理位置编码外推、注意力复杂度、在线推理时延与存储成本之间的真实权衡；\n2）长短期兴趣解耦：区分稳定偏好、季节性需求、即时冲动与已被满足需求，优化用户的长短期兴趣表征和抽取；\n3）隐式负反馈与潜在兴趣：从曝光未点、连续跳过、快速划走等弱信号中挖掘信息，同时通过探索机制发现用户自己尚未表达的兴趣；研究隐式负反馈在推荐系统各个环节中的应用，以及如何解决推荐系统feedback loop的问题；\n4）多模态与表征学习：结合商品图像、文本、视频内容，以及丰富的用户行为数据，构建高质量的物品和用户表征；\n3、冷启动与内容生态：负责内容生态的机制设计；新商品、新主播、新创作者每天大量涌入，需设计高效的探索和扶持机制，在有限流量下快速判断潜力；构建商品与主播的质量、潜力、专业度、口碑信号（如复购率模型、批量化低质内容识别），让优质供给获得更多曝光，提升作者留存；除了人找货，系统的设计“货找人”的推荐链路，研究和设计实现双边匹配的推荐系统；\n4、参与长期价值建模、user复购/留存建模、成交归因、疲劳度建模、新用户推荐、增量价值建模、LLM4rec等真实推荐系统中各种前沿和不确定性的话题，业界没有标准答案，我们期望你在这些有挑战的问题上做出原创性的工作；\n5、用Agent重写研发范式：我们正在把Coding Agent深度嵌入算法研发的各个流程，希望你能与我们一起高效重构超大规模推荐系统和模型的开发、设计、评估、以及迭代和实验流程。","requirements":"1、2027届获得本科及以上学历，人工智能、计算机、数学、统计等相关专业优先；\n2、扎实的算法与数据结构基础，优秀的编码能力，能写出干净、高效、可复现的代码；\n3、扎实的机器学习与概率统计基础：理解模型背后的假设与失效边界，能讲清楚一个方法为什么有效、在什么条件下会失效，而不止于调用API；\n4、熟悉深度学习框架（PyTorch/TensorFlow）与至少一种大规模数据处理工具（Spark/Flink/SQL），熟悉Python，具备C++与Linux开发环境的基本能力；\n5、具备数据敏感度与实验素养：能从指标波动中定位真实原因，理解A/B实验的设计、置信度与常见陷阱；\n6、优秀的学习能力、清晰的表达能力与良好的协作精神。\n\n加分项：\n1、有推荐、搜索、广告、信息检索、NLP或大规模机器学习系统的研究或工程实践经验；\n2、在KDD、NeurIPS、WWW、SIGIR、WSDM、ICML、ICLR、RecSys、CIKM等会议发表过论文，或有高质量开源贡献；\n3、有Kaggle、天池、RecSys Challenge等竞赛获奖经历，或ACM-ICPC/NOI竞赛背景；\n4、有因果推断、在线学习/Bandit、图神经网络、序列建模或大规模分布式训练的实践经验；\n5、AI coding及AI自动化搭建系统、优化模型的重度用户。\n\n为什么选择我们\n1、工业级推荐系统：十亿级用户、亿级商品、日均千亿级行为样本；很多在论文里被简化掉的问题，在这里是每天要面对的现实；\n2、完整的闭环推荐链路：从数据、特征、模型到线上实验与业务收益，你能看到自己的想法在多长时间内、以多大幅度改变了真实世界的交易；\n3、Open开放的团队氛围：在这里，你有机会和优秀的算法工程师共事，只要有想法，就会有无限种可能和创意的碰撞、探索；\n4、技术与业务不割裂：我们要求算法工程师理解业务，也保护算法工程师做长期技术投入的空间；这里衡量你的是判断力和影响力，不是工时；\n5、站在高速增长业务的最前沿：TikTok Shop正加速在全球各地区落地，你有机会亲历从冷启动到规模化爆发的完整周期；背靠TikTok庞大且仍在快速扩张的用户基础，电商业务的增长天花板远未触及。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667579581055043893","sourceKey":"bytedance","company":"字节跳动","title":"AIGC视觉生成算法工程师 - TikTok Shop","city":"上海/杭州/北京","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667579581055043893/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商业务，致力于成为用户发现并获取优价好物的首选平台。面向直播电商、视频内容电商、货架电商等多元购物场景，国际电商持续为全球用户提供更个性化、更主动、更高效的消费体验，也为商家提供稳定、可靠、可持续增长的平台服务，推动“新奇好物畅销全球，美好生活触手可得”的使命落地。\n目前，国际电商算法团队分布在中国、美国、新加坡等多个国家和地区，深度参与全球化业务建设。加入我们，你将有机会面向全球用户、商家和商品生态，与跨区域的产品、工程、运营和业务团队协作，持续提升商品供给质量、用户购物体验、平台交易效率与履约体验，共同探索内容电商与智能购物的新模式。\nData-国际电商团队是 TikTok Shop 的核心算法技术力量，专注于电商场景下的算法创新与规模化落地，方向包括但不限于：生成式推荐与大规模 Foundation Model、多模态商品理解与内容生成、搜索与导购、智能客服、风控治理、物流履约优化、商家经营智能化，以及 Agentic 智能体在电商全链路中的应用。我们希望通过先进的算法能力，帮助用户更高效地发现感兴趣的商品，帮助商家实现更高质量的经营增长，并持续提升交易各环节的智能化水平。\n在这里，你将与一流的产品和技术团队合作，面对复杂且真实的国际化电商挑战，推动前沿技术在大规模业务场景中落地，与团队一起创造更多可能。\n\n1、参与AIGC视觉生成算法的前沿研究与应用开发，方向涵盖图像生成、图像编辑、视频生成、视频编辑、及多模态数字人生成等；\n2、参与相关模型的训练优化、效果调优及性能提升，重点攻克高保真图像生成、ID一致性、多模态可控生成等关键技术难题；\n3、推动算法在电商图像生成和编辑、短视频生成、数字人直播等核心场景的验证与落地探索，将算法能力转化为可体验的产品功能，优化生成效率与用户体验；\n4、跟进学术界与工业界前沿进展，参与团队的技术调研、方案设计与创新实验，将前沿研究成果快速应用于实际项目，共同推动团队在AIGC视觉生成领域的技术竞争力。","requirements":"1、2027届获得本科及以上学历，人工智能、计算机、数学相关专业优先；\n2、熟悉图像&视频生成算法，有视频生成或数字人相关项目经验者优先；\n3、熟练掌握PyTorch等框架，具备良好的Python/C++编程能力；\n4、具备较强的学习能力和解决问题能力，能积极参与团队协作与项目推进。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7628830121033632053","sourceKey":"bytedance","company":"字节跳动","title":"基于多模态大模型与用户行为理解的下一代分发与交互技术-抖音智能对话（北京/上海/杭州/深圳）","city":"上海","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7628830121033632053/detail","duty":"团队介绍：抖音智能对话团队负责抖音集团对话算法相关工作，通过使用最新的大模型等技术支持抖音创新业务探索、智能客服等方向相关需求。得益于抖音独特和丰富的多模态数据和业务应用需求，先后支持了抖音数字人模型、小说角色机器人、智能客服等落地场景的算法模型。团队一方面横向支持各个团队在对话场景的技术需求，同时也是抖音集团在大语言模型在对话场景落地应用的重要算法团队，承担了开创新业务方向和技术探索的重要角色。\n\n课题介绍：\n本课题旨在探索基于多模态大模型的模态理解与表征、世界知识、推理等能力，并深度的与信息分发（推荐、搜索等）中的用户行为理解和建模结合起来，构建支撑下一代分发与交互技术的基础模型和系统范式。通过基础技术突破和探索，既尝试解决原有分发技术中对长尾兴趣分发、用户复杂意图理解、多模态与行为协同融合、System Bias、分发系统的算力与推理分配等一系列关键问题，也探索基于新的多模态大模型与用户对齐的理解，支持全新的可对话性需求满足、可自然交互性的分发调节与个性化等能力和产品形态上的突破。\n\n课题挑战：\n1、多模态大模型的完整流程的训练，以及与大规模用户行为深度理解和对齐；\n2、突破多模态大模型与长序列高并发高效推理的瓶颈；\n3、实现大模型泛化推理能力与复杂推荐业务目标的深度对齐。\n\n课题价值：\n1、打破信息茧房，提供个性化可解释推荐，提升长尾/冷启分发效率；\n2、沉淀大模型Scaling Up范式，重塑大模型时代的下一代推荐系统；\n3、探索全新的支持下一代交互场景的分发基础技术突破。","requirements":"1、2027届毕业，获得博士学位，人工智能、计算机、数学相关专业优先；\n2、具备扎实的编码能力、数据结构和基础算法功底，熟练运用各种算法框架与工程框架；\n3、在国际会议或期刊发表论文者（包括但不限于ACL、EMNLP、NeurIPS、ICML、ICLR、CVPR等）优先；\n4、拥有扎实的机器学习基础，在深度学习、强化学习、NLP、多模态方向有深入的理解与研究经历；\n5、具备良好的沟通协作能力，能够与团队共同探索新技术，推动技术发展。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7683820226734049541","sourceKey":"bytedance","company":"字节跳动","title":"汽车行业市场营销实习生 - 飞书商业化","city":"北京/上海","category":"市场","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7683820226734049541/detail","duty":"团队介绍：飞书商业化团队（Go to Market）负责将飞书先进产品和服务全面推向中国和国际市场，通过制定精准的业务战略，进行破圈的市场营销，深入理解不同行业的趋势和特点，传递飞书的理念和价值给不同行业的企业客户并达成业务合作，帮助客户加强使用深度和广度，最终让飞书成为各行各业先进企业的首选、持续助力企业组织升级。目前已在中国、新加坡、美国、日本等国家和地区建立了商业化团队，开启了为全球各行各业组织和个人提升创造力和效率的历程。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、参与汽车行业市场拓展与市场活动落地，包括但不限于活动方案策划、活动现场执行及项目分析复盘等；\n2、开展创意策划，输出创意内容与想法，撰写传播文案及物料文案；\n3、维护日常活动数据，对数据进行周期性分析并输出洞察；\n4、跨部门协作推进项目进程，达成既定目标。","requirements":"1、本科及以上学历在读；\n2、可尽快入职，具有较好的数据分析能力和逻辑思维能力；\n3、有一定的内容创作能力、PPT设计能力；\n4、拥有良好的学习能力和自驱力，出色的沟通和协作能力；\n5、对AI有热情，有AI相关实习经验者优先；\n6、每周出勤5天，至少实习6个月。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7683495342436419893","sourceKey":"bytedance","company":"字节跳动","title":"Agent数据运营（ToB方向） - AI数据与安全","city":"北京","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7683495342436419893/detail","duty":"团队介绍：AI 数据与安全团队为 Seed 基座模型及 AI 原生应用提供跨模态数据服务，覆盖数据生产全流程，包含模型评估标准的制定、数据规模化生产、数据飞轮搭建，不断提升数据质量，支持模型快速迭代。\n团队由产品经理、数据工程、数据运营等跨职能人才组成，并通过与 Seed 研究员、行业专家、全球顶尖数据供应商紧密合作，从真实场景中收集反馈并分析模型表现数据，解决 AI 前沿突破过程中的复杂数据问题，推动模型性能与用户体验的双重提升。我们既是帮助模型技术迭代的一线贡献者，也是模型和 AI 产品的一手用户。\n\n1、深入理解AI大模型，产出Agent、Coding等方向的高质量数据，分析Rubric、环境、轨迹等方面的问题，输出分析报告；\n2、与产品研发团队进行沟通协作，参与业务场景定义、数据标准制定、标注策略迭代，联动运营数据团队推进优化专项，为数据生产流程提效和交付质量负责；\n3、能通过代码和Prompt Engineering，完成数据挖掘、预处理、数据分析、链路、Agent搭建等任务，自动化构建训练集和评测集，同步探索AI领域新的知识与工具，为业务带来新的思路和方法，并在业务中实践落实；\n4、针对大模型的突出问题，与产品、算法、标注、评估等团队合作开展专项攻坚。","requirements":"1、2027届获得本科及以上学历，计算机相关专业优先；\n2、熟练掌握2种及以上主流编程语言，能够独立阅读主流代码逻辑及报错日志，高频使用AI开发工具，如TRAE/Claude Code/Cursor；\n3、精通提示词工程（Prompt Engineering），能优化Prompt解决不同类型的任务需求，理解Agent实现原理，有实际搭建工作流/Agent经验；\n4、了解机器学习/人工智能/模型调优，熟悉各种算法的基本概念，有模型优化/评估相关经验者优先；\n5、对AI有高度热情，有较强的自驱、学习、沟通能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7683370235057539333","sourceKey":"bytedance","company":"字节跳动","title":"前端/跨栈开发工程师 - Seed","city":"北京","category":"前端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7683370235057539333/detail","duty":"团队介绍：产品研发和工程架构-Seed 团队深耕大模型技术在场景中的创新应用，负责多款现象级AI产品的工程研发 —— 包括豆包、飞书、豆包工作、豆包爱学、Gauth、猫箱等创新产品，覆盖消费级与企业级多个场景。我们致力于将大模型能力从 \"生成内容\" 推进到 \"完成工作\"，让 AI 服务用户日常与企业协作。你将面对多模态交互、工具调用可靠性、企业级数据安全等真实工程挑战，与团队一起推动 AI 生产力落地。\n\n1、参与飞书UG增长相关前端产品的设计与研发，覆盖官网、落地页、活动、注册转化等核心增长场景；\n2、参与AI驱动的增长产品建设，探索AI生成落地页、智能内容分发、个性化推荐等AI原生增长玩法的前端实现；\n3、参与团队AI Coding工程化实践，在真实业务中应用并沉淀AI辅助研发的最佳实践，持续提升人效；\n4、参与前端基础建设，包括增长场景专属的搭建体系、A/B实验、性能与转化优化等；\n5、主要技术栈：React、TypeScript、Node.js，以及LLM/Agent相关的前端工程链路。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程等相关专业优先；\n2、扎实的前端基础：精通HTML/CSS/JavaScript/TypeScript，熟悉React及其生态，理解现代前端工程化体系（Webpack/Vite/Rspack等）；\n3、对AI技术有热情并有实践经验：\n1）熟悉至少一种主流LLM的调用与Prompt工程；\n2）有AI Coding工具（Cursor/Copilot/Claude Code等）深度使用经验者优先；\n3）有基于LLM的应用开发经验（RAG/Agent/Function Calling/MCP等）者优先；\n4、具备以下任一方向经验者优先：\n1）增长业务相关：官网/落地页/活动搭建、A/B实验、数据埋点与转化分析、SEO；\n2）AI相关：AI应用开发、AI辅助研发工具链、AI原生前端交互；\n3）Node.js/全栈开发；\n5、有较强的产品意识和数据敏感度，理解“增长”不只是技术实现，更是对用户和业务的洞察；\n6、乐于在快速变化中学习，能主动拥抱AI带来的研发范式变革。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7681168023424764165","sourceKey":"bytedance","company":"字节跳动","title":"内容生态策略产品实习生 - TikTok生活服务","city":"北京","category":"产品","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7681168023424764165/detail","duty":"团队介绍：TikTok是一个覆盖150个国家和地区的国际短视频平台，我们希望通过TikTok发现真实、有趣的瞬间,让生活更美好。TikTok在全球各地设有办公室，全球总部位于洛杉矶和新加坡，办公地点还包括纽约、伦敦、都柏林、巴黎、柏林、迪拜、雅加达、首尔和东京等多个城市。\n\nTikTok生活服务(TikTok GO) 是一站式商业解决方案，创造性地通过TikTok POI、短视频、直播和搜索等，连接全球用户与本地服务，提供有价值的真实世界生活体验，激发用户探索周围的世界。以“发现好去处，助力本地商家”为使命，致力于成为最值得信赖的发现好去处和连接本地商家的平台，让社区更轻松地与餐厅、酒店和景点互动，为商家提供全新方式来连接客户并促进交易，结合创新的营销和运营工具，带来可持续增长。团队分布多国，目前积极扩张中。大航海时代，我们欢迎大家一起加入国际化征程，共同打造TikTok生活服务业务!\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、负责协助制定本地内容标准训练本地内容模型；\n2、基于对用户需求的理解和用户真实反馈不断调整内容标准；\n3、对重要实验多出内容和线上高热内容定期进行画风走查，根据结果调优评估标准细则；\n4、负责搭建AI自动化内容标注流程，并基于实际效果调优Agent，提升标注准确率。","requirements":"1、本科及以上学历在读；\n2、具备敏锐的用户视角和内容意识，TikTok/抖音等社媒app重度用户优先；\n3、学习能力强，过往有互联网策略产品实习经验者优先，有Codex等AI工具使用经验者优先；\n4、具备一定的数据分析能力，熟练掌握基本数据分析方法和SQL；\n5、沟通能力强，有主动意识，能积极推动各方需求进展；\n6、实习时间不少于6个月者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7680432495125317941","sourceKey":"bytedance","company":"字节跳动","title":"大模型Agent算法实习生 - 国际化商业安全","city":"上海","category":"产品","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7680432495125317941/detail","duty":"团队介绍：国际化商业安全团队致力于在国际化用户、企业和产品之间建立安全可靠的连接。我们通过一系列完善的系统和能力，审核广告内容、预测政策违规行为，并执行广告审核通过或拒绝的措施。\n作为国际商业化团队的业务合作伙伴，我们提供的业务诚信解决方案不仅确保国际化业务始终是一个安全、积极、友好的用户环境，同时也推动业务增长。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、前沿调研与抽象：跟踪LLM Agent领域中与记忆、长程任务相关的前沿理论与技术、认知科学、神经科学、心理学，提炼可指导系统设计的计算原则；\n2、记忆与长程能力设计：参与Agent记忆及长程任务相关架构的探索与设计，方向包括但不限于记忆的写入与检索、合并与遗忘、反思与离线巩固、长程规划与多步推理等；\n3、算法研发与实验：负责相关算法的设计、实现与评测，参与构建评测体系（如记忆质量、长程一致性、抗干扰与抗遗忘等）；\n4、前沿跟踪与判断：跟进领域前沿工作，输出可落地的技术判断与方案。","requirements":"1、本科及以上学历在读，认知科学、心理学、神经科学、计算机、人工智能、数学、物理、统计等专业优先；\n2、对Agent的长程任务能力、人如何学习与记忆等方向有真实的好奇心，能就至少一个相关话题展开深入讨论；\n3、创新思维突出，能从底层原理出发思考Context压缩、Memory管理、长期记忆持久化等核心问题，具备自主设计并验证解决方案的能力；\n4、具备基本的编程能力；\n5、自我驱动，能独立调研文献并形成判断；\n6、能持续实习3个月以上，每周不少于4天。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7680392413642934581","sourceKey":"bytedance","company":"字节跳动","title":"产品（主架构基础体验）实习生 - TikTok产品","city":"上海","category":"产品","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7680392413642934581/detail","duty":"团队介绍：TikTok是一个覆盖150个国家和地区的国际短视频平台，我们希望通过TikTok发现真实、有趣的瞬间，让生活更美好。TikTok在全球各地设有办公室，全球总部位于洛杉矶和新加坡，办公地点还包括纽约、伦敦、都柏林、巴黎、柏林、迪拜、雅加达、首尔和东京等多个城市。\n\nTikTok产品团队的目标是促进TikTok的发展并能持续性成为业界领先的产品。团队包括但不限于产品架构、用户增长、搜索、社交、创作、Lemon8、PGC、音乐、开放平台、内容生态、平台安全、数据科学、商业分析等关键业务场景，支持产品在全球赛道上高速发展，保障业务持续高质量、高效率、且安全地为用户服务。同时覆盖国际化直播场景，为TikTok用户提供独特的内容和消费体验，以及国际化生活服务场景，链接海外线下商家、创作者与用户。\n\nTikTok的使命是通过提供一个创造性表达的产品，通过真实、快乐和积极的体验激发创造力和带来快乐。在TikTok，我们的员工谦逊、聪明、富有同情心和创造力。我们创造是为了激励--为了你，为了我们，也为了我们平台上的10亿用户。我们带着好奇心领导，追求最高目标。在这里，对于那些敢于追求超越可能性边界的大胆想法的人充满机会。加入我们，在TikTok的职业生涯中产生影响。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、负责国际化创作者社区产品的功能原型设计、需求推进和管理、数据分析和持续迭代优化；\n2、以用户体验为核心，对社区社交、内容产品有深度理解和热情，有创新能力和热情，为产品的进一步增长创造可能性；\n3、与设计、研发、分析等团队合作，协同推动多合作方保障需求落地；\n4、对推荐、数据、国内外社区产品有明确研究，通过调研、反馈收集和数据分析等方式明确用户需求，提炼有效的产品方向。","requirements":"1、本科及以上学历在读，社会学/心理学/计算机相关专业优先；\n2、有优秀的用户同理心，具备社区产品使用敏感度，有创新精神和创新能力，有社区产品实习经验优先；\n3、乐于探索钻研，有很强的责任心和合作精神，逻辑性强，对数据敏感，有判断力，结果导向；\n4、良好的数据理解能力，逻辑思维能力强，具有探求心，自我驱动力强；\n5、擅长跨文化沟通，英语可作为工作语言，全勤实习6个月及以上优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7679727632775104821","sourceKey":"bytedance","company":"字节跳动","title":"大模型技术与应用算法工程师（用户智能） - TikTok算法","city":"北京/上海","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7679727632775104821/detail","duty":"团队介绍：TikTok搜推算法团队，负责TikTok短视频产品的基础推荐、搜索算法，加入我们，你能接触到包括搜索、用户增长、社交、直播、内容创造、内容消费等核心业务场景，直接为核心用户体验负责，支持产品在全球赛道上高速发展。我们的工作内容包括大规模推荐算法的优化、复杂约束的优化问题的解决、多模态大模型的落地，并着力研究下一代AI Search和Chatbot的核心研发技术，包括不限于Multi-Agent、Agentic RL、Harness、Loop Engineering，探索强化学习在大模型时代的新范式。在这里，你可以深入钻研机器学习算法的改进和优化，探索前沿的技术；可以感受不同文化的碰撞，激发认知；可以通过对产品和内容生态的深度分析，影响产品未来的发展方向。\n\n1、探索基于大语言模型的推荐（LLM4Rec）、交互式推荐、生成式推荐、智能体推荐等新范式，推动推荐系统与交互范式的升级；\n2、研究用户全生命周期建模，结合超长行为序列和多源交互信号，构建统一的用户表征，理解用户兴趣及其动态演化；\n3、推进自然语言语义与推荐系统中用户、内容和行为语义的对齐，使系统能够理解用户的文本输入，并通过检索、推荐或生成等方式动态响应用户需求；\n4、利用大语言模型和多模态大模型理解用户和视频，研究跨模态、跨语言的内容理解与用户—内容统一表征；\n5、面向新用户冷启动、兴趣激活与探索、跨域兴趣迁移、智能触达与获客等场景，提升模型在稀疏反馈和复杂业务环境下的泛化能力；\n6、探索智能体与强化学习在推荐决策中的应用，构建具备感知、记忆、推理、规划和反馈学习能力的推荐智能体，兼顾短期效果、用户体验与长期价值。","requirements":"1、2027届获得硕士及以上学位，计算机、电子信息、人工智能、机器学习等相关专业；\n2、具备扎实的机器学习和深度学习基础，熟悉大语言模型、多模态模型、推荐系统或强化学习中的一个或多个方向；\n3、具备以下至少一个领域的研究或实践经验：\n1）大模型预训练、后训练、微调与对齐；\n2）多模态理解与跨模态表征学习；\n3）生成式推荐、序列推荐与用户建模；\n4）强化学习与长期价值建模；\n5）冷启动、跨域迁移与多目标优化；\n4、具备较强的算法设计、实验分析和工程实现能力，能够从实际问题中抽象关键技术问题；\n5、对大模型与推荐系统的结合有持续兴趣，具备良好的学习能力和创新意识。\n\n加分项\n1、在大模型、多模态、推荐系统或强化学习方向有高水平论文、竞赛、开源项目或工业落地经验；\n2、具有大规模推荐、广告、搜索、用户增长或智能触达系统研发经验；\n3、具有生成式推荐、推荐基础模型、用户行为大模型或多模态推荐实践经验；\n4、能够兼顾技术前瞻性与业务落地，对用户体验、平台生态及长期价值有深入理解。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7676290873403623733","sourceKey":"bytedance","company":"字节跳动","title":"广告策略产品实习生 - 广告业务","city":"北京/上海","category":"产品","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7676290873403623733/detail","duty":"团队介绍：广告业务为抖音集团的商业化提供产品规划、迭代与运营，负责端到端大型广告系统建设、覆盖抖音、今日头条、番茄小说、红果短剧、穿山甲等产品矩阵，践行\"激发生意新可能\"理念，致力于让营销更省心、更高效、更美好，推动商业的可持续增长。领先的Al营销能力、成熟的趋势营销理念，让不分体量、地域的企业及个体，在这里都能通过数字化技术激发创造、驱动生意。在这里，你将投身建设面向未来的数字营销能力，接触到先进的商业产品架构、模型、算法、运营模式和营销理念、在互联网广告行业始终创新。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、负责商业化广告策略产品工作，包括但不限于广告流量策略、投放策略产品、广告归因策略产品、广告出价策略产品、广告创意策略产品、AIGC等新兴策略平台产品等；\n2、洞察和理解上述领域内具体工作事项的需求，结合反馈和用户体验，设计和迭代业务核心指标和方向，产出产品方案，包括但不限于抽象产品业务模块的设计、产品策略、算法模型的应用和落地等；\n3、通过市场机制设计，提升商业化广告产品生态健康度和活力，提升用户、商家和平台的共赢效率；\n4、推进内部交流，协同业务团队、算法、研发团队，保证团队合作的顺畅，不同产品之间的协作等。","requirements":"1、本科及以上学历在读；\n2、出色的产品规划能力，能主导产品方向和制定长期规划，并拆分为可实施项目；\n3、良好的沟通协调能力，可独立完成跨职能和跨部门沟通；\n4、有策略产品/商业产品实习经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7674932405712111877","sourceKey":"bytedance","company":"字节跳动","title":"推荐策略产品经理 - TikTok生活服务","city":"上海/北京","category":"产品","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7674932405712111877/detail","duty":"团队介绍：TikTok是一个覆盖150个国家和地区的国际短视频平台，我们希望通过TikTok发现真实、有趣的瞬间,让生活更美好。TikTok在全球各地设有办公室，全球总部位于洛杉矶和新加坡，办公地点还包括纽约、伦敦、都柏林、巴黎、柏林、迪拜、雅加达、首尔和东京等多个城市。\n\nTikTok生活服务(TikTok GO) 是一站式商业解决方案，创造性地通过TikTok POI、短视频、直播和搜索等，连接全球用户与本地服务，提供有价值的真实世界生活体验，激发用户探索周围的世界。以“发现好去处，助力本地商家”为使命，致力于成为最值得信赖的发现好去处和连接本地商家的平台，让社区更轻松地与餐厅、酒店和景点互动，为商家提供全新方式来连接客户并促进交易，结合创新的营销和运营工具，带来可持续增长。团队分布多国，目前积极扩张中。大航海时代，我们欢迎大家一起加入国际化征程，共同打造TikTok生活服务业务!\n\n1、深度参与TikTok生活服务推荐策略优化，通过问题发现、指标建设、策略设计等方式，服务分发效率、用户规模与业务增长目标；\n2、深入理解内容生态与用户行为，参与制定流量分发策略，推进流量获取与转化效率提升；\n3、优化推荐逻辑与流量承接体验，提升用户观看时长与互动深度，优化用户推荐体验；\n4、与算法、数据、运营团队紧密协作，通过用户调研、数据分析与实验验证洞察分发瓶颈，有效推进策略落地。","requirements":"1、2027届获得本科及以上学历，计算机、统计学、数学等相关专业优先；\n2、有推荐策略、广告策略、数据科学等相关实习经验者优先；理解推荐系统的基本原理，具备基本的用户理解、行业洞察与数据分析能力（掌握SQL），能基于业务场景设计策略方案并推动落地；\n3、有较强的学习理解能力、逻辑思维能力与跨团队协作能力，自驱力强、对数据敏感、结果导向；\n4、具备良好的英文沟通协作与项目管理能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7673733057043712261","sourceKey":"bytedance","company":"字节跳动","title":"AI产品实习生 - 数据平台","city":"上海/北京","category":"产品经理","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7673733057043712261/detail","duty":"团队介绍：数据平台是字节跳动数据中台部门，为公司多业务线（包括抖音、电商、直播和生活服务等）提供一站式大数据解决方案，涵盖数据的生产、清洗、传输、建模、分析等全流程链路，提供数据开发、实验评估、画像标签、增强分析等多元场景解决能力。同时，数据平台部门也致力于把字节跳动积累沉淀的数据中台解决方案做商业化输出，让更多行业能够应用我们的产品能力构建自己的数据中台。在火山引擎上，我们提供了营销增长套件，数据中台等相关产品解决方案，为泛互联网、金融、汽车、新零售等行业提供了行业解决方案。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、参与企业知识库或企业相关业务Agent的产品设计，包括行业洞察、产品方法论、客户案例等内容的结构化沉淀；\n2、调研行业内业务场景的最佳实践，输出产品分析与机会点洞察；\n3、跟踪Agent运行数据与用户反馈，参与产品迭代与能力升级；\n4、调研前沿AI Agent技术与行业应用，输出产品机会点建议。","requirements":"1、本科及以上学历在读，专业不限；\n2、每周可到岗4天，能连续实习3个月，对AI产品与To B企业服务有浓厚兴趣，了解大语言模型/AI Agent的基本原理与应用场景；\n3、具备良好的逻辑思维与结构化表达能力，能独立完成信息搜集、分析与文档输出；\n4、有较强的自驱力与学习能力，能主动推进任务；\n5、具备基础的数据敏感度，能使用Excel/飞书表格等工具进行简单数据分析。\n\n加分项\n1、深度使用过AI/Agent类工具，有持续使用习惯并形成自己的工作流；\n2、有AI/Agent相关的个人实践或项目经验；\n3、有内容创作经验，如社交媒体平台运营经历；\n4、熟悉SQL、Python或数据分析工具；\n5、对B端SaaS/企业服务行业有一定理解。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7673456813362333957","sourceKey":"bytedance","company":"字节跳动","title":"产品实习生（渠道产品） - 国际支付","city":"上海/北京","category":"产品经理","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7673456813362333957/detail","duty":"团队介绍：国际支付，立足于为字节跳动国际化业务提供专业的支付和金融服务，专注于全球支付产品线的质量和效率，确保为国际产品提供高度可靠和稳定的服务，建立国际支付产品和能力，同时在高效助力业务快速拓展的同时，打造行业领先的支付和金融产品能力。团队当前所提供的产品和服务，遍布全球多个国家和地区，团队拥有丰富的国际化产品研发经验；同时这里有全球超大规模的支付网络；覆盖多业务场景的海外钱包及金融产品解决方案；围绕分布式一致性、高并发、高可用、资金安全在内的核心技术能力攻坚；LLM等前沿AI技术在支付&金融服务中的探索、研发和应用。另外，我们在全球设立团队，团队同学背景多元，不同的思维方式，打造了一个多元、碰撞、融合、包容的工作环境。我们邀请你来此成长、专研，发掘无限的潜力，一起应对技术和业务以及跨国合作上的挑战，还有跨文化交流机会在等你！\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、负责国际支付渠道支付网络建设，满足字节跳动国际化生态下对支付方式能力覆盖全球下有竞争力的支付能力要求；\n2、持续跟进支付产品的升级迭代，负责渠道支付产品的核心能力建设；\n3、通过与多团队协作，协同完成支付产品整体解决方案的撰写、评审和产品方案的落地。","requirements":"1、本科及以上学历在读，工程或计算机科学背景者优先；\n2、具备较强的分析能力和结构化解决问题的能力，能够独立、有逻辑地思考；\n3、具备强烈的责任感和执行力，能够推动项目落地并高效解决问题；\n4、沟通协作能力优秀，能够在跨职能团队中良好协作；\n5、对产品管理、支付、金融科技或数字化平台有兴趣，能够适应模糊不确定的工作环境；\n6、有产品管理、软件、金融科技或相关领域的实习经验，熟悉全球支付、跨境业务或数字内容平台者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7672709044188236085","sourceKey":"bytedance","company":"字节跳动","title":"AI产品实习生（企业级智能体） - 数据平台","city":"北京/深圳","category":"产品经理","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7672709044188236085/detail","duty":"团队介绍：数据平台是字节跳动数据中台部门，为公司多业务线（包括抖音、电商、直播和生活服务等）提供一站式大数据解决方案，涵盖数据的生产、清洗、传输、建模、分析等全流程链路，提供数据开发、实验评估、画像标签、增强分析等多元场景解决能力。同时，数据平台部门也致力于把字节跳动积累沉淀的数据中台解决方案做商业化输出，让更多行业能够应用我们的产品能力构建自己的数据中台。在火山引擎上，我们提供了营销增长套件，数据中台等相关产品解决方案，为泛互联网、金融、汽车、新零售等行业提供了行业解决方案。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、参与企业级智能体产品架构的搭建与迭代，协助推进决策层、记忆系统、Skills生态、SubAgent、安全管控等能力模块的产品设计；\n2、协助定义平台级的产品边界与架构，规划跨Agent的协同交互、能力调度与统一体验，探索该创新性平台从0到1的构建与落地；\n3、调研市场先进产品的设计理念，共同探索产品的发展方向和商业化路径；\n4、结合客户及业务的实际场景，参与对应应用及产品功能的落地设计。","requirements":"1、本科及以上学历在读，计算机、软件工程、人工智能、产品设计等相关专业优先；\n2、对大数据、AI、Skill及Agent技术有兴趣并有一定了解，有数据产品或平台型产品实习经验，深度参与过复杂的、平台级或生态型产品的战略性构建优先，每周可实习4天，可连续实习3个月；\n3、具备出色的系统性思维和抽象能力，能够协助梳理平台架构与产品逻辑，学习意愿强，能快速上手复杂业务场景；\n4、对数据有一定敏感度，具备基本的业务意识和场景理解能力，能够从用户体验和数据资产价值角度思考产品功能；\n5、具备较强的责任心、主动学习态度与良好的沟通协调能力，能够协助推动跨团队的简单协作与需求对齐，结果导向。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7670544380457584949","sourceKey":"bytedance","company":"字节跳动","title":"AI训练/推理框架研发工程师 - 火山方舟","city":"北京","category":"机器学习","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7670544380457584949/detail","duty":"团队介绍：火山方舟是火山引擎推出的一站式大模型服务平台，是中国大模型市场产品和份额领跑者。平台提供模型推理、评测、精调等全流程服务。方舟搭载了豆包及业界主流大模型，提供丰富的插件生态和AI应用开发服务，并通过稳定可靠的安全互信方案、专业的算法技术服务，全方位保障企业级AI应用落地。\n\n1、参与火山自研训推框架开发，包括xLLM（LLM推理）、veFuser（DiT推理）、veOmini（LLM/DiT训练）、veRL（强化学习），保持框架的先进性；\n2、参与框架-平台协同设计，实现异构资源智能调度与弹性扩缩容；\n3、参与异构芯片（GPU、NPU等）上的算子适配开发，提供多元的算力供应方式。","requirements":"1、2027届获得本科及以上学历，计算机、人工智能、信息安全等相关专业；\n2、熟悉Linux开发环境，良好的系统编程、数据结构、算法基础、系统设计能力；\n3、乐于挑战没有明显答案的问题，快速理解业务场景，从具体问题中抽象出通用的解决方案；\n4、有实际的分布式系统相关经验者优先；\n5、对机器学习系统有经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669686538323020037","sourceKey":"bytedance","company":"字节跳动","title":"芯片系统软件工程师 - 芯片研发","city":"北京/上海/杭州/深圳","category":"硬件","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669686538323020037/detail","duty":"团队介绍：字节芯片研发团队目前工作主要集中在芯片设计环节，主要围绕字节自身业务展开芯片探索，为字节多项业务的专用场景定制硬件优化，设计多款基于先进半导体工艺的云端复杂芯片，以期提升性能、降低成本。早期若干芯片项目已经进入到量产部署阶段，有多次一版成功的投片经历，所用工艺包含多个主流的先进工艺节点。与基础设施各团队之间工作的整体协同，能更容易和更好地发挥芯片研发的价值。\n\n1、负责芯片底层软件开发（MSCP、Tiano、U-Boot、CorBoot、LinuxBoot、TF-A、TF-M、OpenSBI）和SOC Bring-up；\n2、负责SOC芯片的软件验证，包括PreSilicon和Post-Silicon阶段的验证；\n3、负责自研芯片的行为模型仿真系统的开发和交付，支持完整软件栈的开发测试和芯片软硬件接口验证；\n4、负责Core、NOC、UCIe、PCIe、DDR等某一IP的Firmware、Driver开发；\n5、负责SOC HSM、Secure Boot、TF-A、TEE OS等软件开发，Crypto Engine、安全Driver等功能开发和验证。","requirements":"1、2027届获得本科及以上学历，计算机、电子、微电子、通信等相关专业；\n2、熟悉Linux Kernel和系统软件，固件；具备软件编程能力（C/C++，Python）；\n3、熟悉ARM、RISC-V CPU体系架构，掌握其Privilege Level、Interrupt、MMU的实现原理优先；\n4、熟悉各种低速接口，包括UART、I2C、SPI、GPIO等；熟悉PCIe，DDR，CXL等高速接口协议优先；\n5、熟悉安全启动，TEE，机密计算等安全特性优先；熟悉基础云产品，大数据、AI解决方案者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669645528939153717","sourceKey":"bytedance","company":"字节跳动","title":"大模型训练推理工程师 - Commercial AI","city":"北京/上海","category":"机器学习","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669645528939153717/detail","duty":"团队介绍：Commercial AI 负责中国交易与广告的to B应用统一模型建设，包含基础模型能力、AI Infra、统一商业数据、评测等方向。\n\n1、负责超大规模机器学习及广告大模型系统架构的设计与研发，解决系统在高并发、高可靠性、高可扩展性等方面的技术难题；\n2、参与大模型训练与推理系统能力建设，包括超长上下文训练与推理加速、多轮轨迹交互、分布式推理性能优化等方向；\n3、负责大模型推理任务的性能优化、流量调度、池化部署等工作，覆盖LLM、MLLM、Diffusion等多类模型场景；\n4、面向PyTorch、TensorFlow等主流深度学习框架，提供高自动化、高性能的模型优化方案，提升模型训练与推理效率；\n5、推动基于大模型开源组件的系统构建与能力沉淀，并负责国产硬件的适配、性能调优与稳定性优化。","requirements":"1、2027届获得本科及以上学历，计算机相关专业优先；\n2、熟练掌握Python、Rust、C++等一门或多门编程语言，编程风格良好，有框架设计和抽象能力；\n3、有训练、推理框架使用、设计、研发经验，参与过大模型训推工程或复杂分布式系统开发；\n4、乐于追踪和解决问题，喜欢钻研底层原理与性能瓶颈，擅长科学建模。\n\n加分项\n1、有扎实的体系结构优化经验，熟悉异构硬件、高性能网络特性；\n2、有科学优化的能力，能自主分析训练效率，并确定优化方向；\n3、对主流强化学习框架、算法有了解，对于大模型训推有技术见解与Insight。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668650334029383989","sourceKey":"bytedance","company":"字节跳动","title":"Lemon8内容推荐算法工程师（大模型驱动的内容生产与分发） - TikTok算法","city":"北京/上海","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668650334029383989/detail","duty":"团队介绍：TikTok搜推算法团队，负责TikTok短视频产品的基础推荐、搜索算法，加入我们，你能接触到包括搜索、用户增长、社交、直播、内容创造、内容消费等核心业务场景，直接为核心用户体验负责，支持产品在全球赛道上高速发展。我们的工作内容包括大规模推荐算法的优化、复杂约束的优化问题的解决、多模态大模型的落地，并着力研究下一代AI Search和Chatbot的核心研发技术，包括不限于Multi-Agent、Agentic RL、Harness、Loop Engineering，探索强化学习在大模型时代的新范式。在这里，你可以深入钻研机器学习算法的改进和优化，探索前沿的技术；可以感受不同文化的碰撞，激发认知；可以通过对产品和内容生态的深度分析，影响产品未来的发展方向。\n\n1、依托LLM与多模态大模型能力，深度参与Lemon8推荐全链路升级迭代，基于大模型语义表征与大模型推荐重构传统推荐架构，持续优化全球种草内容分发效率与用户个性化体验；\n2、基于大模型Agent智能体技术，搭建自动化、智能化的算法迭代体系，实现推荐算法闭环式智能迭代；\n3、和产品以及运营团队紧密合作，对用户、作者的行为做深入的理解和分析，并设计合理策略持续提升用户体验。","requirements":"1、2027届获得硕士及以上学位，计算机相关专业；\n2、具备优秀的编码能力，扎实的数据结构和算法功底；\n3、优秀的分析问题和解决问题的能力，对解决具有挑战性问题充满激情；\n4、对技术有热情，有良好的沟通表达能力和团队精神；\n5、熟悉机器学习、自然语言处理、数据挖掘中一项或多项，对推荐系统、计算广告、搜索引擎相关领域有经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668543383427336453","sourceKey":"bytedance","company":"字节跳动","title":"电商产品经理 - TikTok Shop","city":"上海/北京","category":"产品经理","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668543383427336453/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商。平台汇聚全球优质商家与创作者，通过短视频、直播等多场景连接消费者，让新奇好物畅销全球，让美好生活触手可得。目前团队分布在美国、英国、法国、印尼、墨西哥、中国等全球多个国家和地区，在这里你将有机会深入国际业务场景，面向全世界商家及用户，和跨区域团队协作，共同探索创新购物模式。期待和优秀的你一起创造更多可能！\n\n1、负责国际电商欧洲/日本市场产品工作，包括但不限于用户购物功能和体验，商家、达人经营工具和策略，平台供求匹配策略等；\n2、结合业务反馈和用户体验调研，定义业务核心指标和迭代方向，产出产品方案，包括但不限于抽象产品业务模块的设计、产品策略、算法模型的应用和落地；\n3、根据产品效果以及业务发展状况分析，设计产品原型，撰写需求文档，不断改进产品；\n4、协同研发、设计、数据等团队落地方案，基于数据评估和收益，持续获取认知和进一步迭代；\n5、能够用原生AI的方式思考产品和业务链路的创新解法，为业务提供有力支持。","requirements":"1、2027届获得本科及以上学历；\n2、具备数据分析能力，能够以数据驱动进行产品需求发现、改进和完善；\n3、优秀的逻辑思维能力、沟通能力和自我驱动能力；\n4、优秀的组织和协作能力，自驱力强，结果导向，为结果负责；\n5、优秀的英文沟通能力；\n6、对AI有持续的探索和应用尝试。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668517886824270085","sourceKey":"bytedance","company":"字节跳动","title":"跨境物流欧洲运营 - TikTok Shop","city":"上海/杭州","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668517886824270085/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商。平台汇聚全球优质商家与创作者，通过短视频、直播等多场景连接消费者，让新奇好物畅销全球，让美好生活触手可得。目前团队分布在美国、英国、法国、印尼、墨西哥、中国等全球多个国家和地区，在这里你将有机会深入国际业务场景，面向全世界商家及用户，和跨区域团队协作，共同探索创新购物模式。期待和优秀的你一起创造更多可能！\n\n1、参与制定跨境区域物流正逆向解决方案，负责跨境端到端物流履约流程SOP制定和物流商管理；\n2、负责履约线路时效、成本及体验相关指标运营，搭建运营体系，跟踪日常运营数据，协调物流商资源，推动运营指标提升；\n3、结合业务不同阶段的履约问题，推动相关部门开展物流履约专项优化，协同提升跨境物流履约体验；\n4、参与跨部门沟通协调，基于运营过程提出流程及产品改善建议，推动相关项目落地。","requirements":"1、2027届获得本科及以上学历，物流、供应链管理、电子商务等相关专业优先；\n2、有搭建物流运营的相关工作经历优先，有欧洲物流线路相关运营经验，熟悉国际电商流程和物流运作模式、运营管理模式经验优先；\n3、高度的责任心，有较强的数据分析能力；\n4、具备流利的英语听说读写能力，具备国际化留学经历者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668351587061287221","sourceKey":"bytedance","company":"字节跳动","title":"Tako AI Agent算法工程师 - TikTok算法","city":"北京/上海/杭州","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668351587061287221/detail","duty":"团队介绍：TikTok搜推算法团队，负责TikTok短视频产品的基础推荐、搜索算法，加入我们，你能接触到包括搜索、用户增长、社交、直播、内容创造、内容消费等核心业务场景，直接为核心用户体验负责，支持产品在全球赛道上高速发展。我们的工作内容包括大规模推荐算法的优化、复杂约束的优化问题的解决、多模态大模型的落地，并着力研究下一代AI Search和Chatbot的核心研发技术，包括不限于Multi-Agent、Agentic RL、Harness、Loop Engineering，探索强化学习在大模型时代的新范式。在这里，你可以深入钻研机器学习算法的改进和优化，探索前沿的技术；可以感受不同文化的碰撞，激发认知；可以通过对产品和内容生态的深度分析，影响产品未来的发展方向。\n\n1、Agent Learning与模型能力扩展：研究Agent如何从真实任务Trajectory、环境反馈和用户反馈中学习，结合Post-training、Test-time Scaling、RL Scaling等方法，提升模型在任务拆解、信息获取、工具使用、决策路径、失败恢复和复杂泛化上的能力；\n2、个性化Agent：研究用户长期兴趣、上下文、行为反馈和场景状态建模，让Agent能够理解不同用户的需求、偏好和决策习惯，提供因人而异的智能体验；\n3、Auto Research与自进化闭环：研究模型如何自动发现问题、获取信息、生成假设、验证结果，并将成功/失败轨迹沉淀为数据、Reward、Benchmark和策略迭代信号，形成持续进化的能力闭环；\n4、TikTok生态中的复杂任务智能：结合TikTok视频、评论、创作者内容、热点、经验决策、本地生活、电商等场景，研究Agent如何理解内容语境、整合多源信息、辅助用户比较判断，并完成从信息获取到决策支持的复杂任务。","requirements":"1、2027届获得本科及以上学历，计算机、人工智能、数学、电子信息等相关专业优先；\n2、具备扎实的机器学习、深度学习和自然语言处理基础，熟悉PyTorch、TensorFlow等训练框架；\n3、熟悉大语言模型的训练与优化方法，了解SFT、DPO、PPO、GRPO等后训练或强化学习算法；\n4、能分析Agent的完整行为链路，从任务轨迹、反馈信号、策略选择和失败模式中定位问题；\n5、实验能力强，能设计Benchmark、拆解Failure Mode，并判断模型提升是否真实、稳定、可泛化；\n6、不满足于复现论文或堆技术词，能把真实用户问题抽象成可验证、可迭代、可规模化的算法问题。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667879966262528261","sourceKey":"bytedance","company":"字节跳动","title":"前端开发工程师 - APM","city":"北京/上海/杭州/深圳","category":"前端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667879966262528261/detail","duty":"团队介绍：字节跳动APM(Application Performance Management) 团队负责公司所有服务端、移动端、前端、跨端产品的稳定性和性能质量监控保障，构建业界领先的可观测性基础设施，结合机器学习智能化，提供一站式平台覆盖字节跳动各业务线的排障、监控和稳定性提升等需求。\n\n1、负责字节跳动Web端基础体验的基建（涵盖H5、小程序、Node.js、Electron等）；通过Agentic AI提供一系列围绕观测、排障、治理场景的智能体以及智能解决方案，全方位提升业务Web应用的基础体验；\n2、负责前端性能分析工具的设计开发和落地，Web端、Node.js监控工具的设计开发和落地，APM相关平台的前端开发；\n3、负责前端基础体验相关标准的制定、落地以及Workflow/Agent Infra相关的能力建设。","requirements":"1、2027届获得本科及以上学历，计算机、通信和电子信息科学等相关专业优先；\n2、熟练掌握一种及以上前端语言，包括HTML/CSS/JavaScript/TypeScript等；熟悉前端工程化，在开发效率、性能体验、稳定性、自动化等方面有一定的认知和实践。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667862065905682741","sourceKey":"bytedance","company":"字节跳动","title":"后端开发工程师 - 开发者服务","city":"北京","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667862065905682741/detail","duty":"团队介绍：字节跳动开发者服务团队负责公司研发工具与基础设施体系建设，为内部开发者提供覆盖全技术栈的框架、工具和研发体系能力，支撑业务高效稳定迭代。\n在此基础上，团队正打造面向全场景的AI Agent平台，将大模型与公司内部工程知识深度结合，覆盖需求分析、编码开发、测试发布、运维治理等软件全生命周期，帮助ByteDancer显著提升生产力，重塑开发者服务的形态与体验。\n期待对研发工具体系、AI工程生产力有热情、希望在大规模真实场景中打磨技术的同学加入，与我们一起建设新一代开发者基础设施，共同成长！\n\n1、参与建设面向App Store、安卓、鸿蒙等平台的应用上架预审能力，探索并应用LLM、Agent、AI Coding等技术，完成原型构建、流程验证与方案迭代，参与多Agent编排、工具接入、知识检索与上下文管理的设计与落地；\n2、围绕平台审核规则、历史驳回案例及业务需求，沉淀可执行的预审规则、知识库与风险识别策略，覆盖隐私声明、权限使用、三方SDK、应用内容、商店元数据及区域化配置等场景；\n3、参与预审平台、服务及工作流的设计与开发，推动能力接入CI/CD与应用发布链路，实现风险前置发现、自动诊断与闭环跟踪；\n4、建设预审效果评估与反馈机制，持续优化风险召回率、误报率、规则更新效率及用户体验；跟踪Apple等审核政策变化，与客户端研发、测试、隐私合规、法务及发布团队协作，推动预审能力持续演进。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程、人工智能、电子信息等相关专业；\n2、具备扎实的计算机基础和良好的工程编码能力，熟悉至少一种编程语言（Python&TypeScrip优先，Java、Go、C++亦可）；\n3、了解LLM、Agent、Prompt Engineering或模型评测等AI技术，并愿意探索其在软件工程中的应用；\n4、具备较强的学习能力、问题分析能力和动手能力，能够完成技术调研、原型验证及工程化落地；\n5、具备良好的英文阅读能力，能够理解Apple等国际化平台的政策和技术文档；\n6、具备良好的沟通协作能力和责任心，能够主动推进跨团队问题闭环。\n\n加分项\n1、有iOS/Android应用开发、打包、签名、提审或App Store Connect等使用经验优先；\n2、了解移动端隐私合规、权限管理、第三方SDK治理或应用商店审核规则优先；\n3、有AI Agent/LLM应用相关的开源项目、竞赛、论文或个人作品（含GitHub项目）优先；\n4、熟悉CI/CD、服务端开发或数据分析工具优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667575829174405429","sourceKey":"bytedance","company":"字节跳动","title":"语音与音频大模型算法工程师 - 抖音","city":"上海/深圳/北京/杭州","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667575829174405429/detail","duty":"团队介绍：Data-抖音团队，负责抖音APP的推荐算法、AI大模型应用、内容算法、增长算法、广告自动化投放、智能对话等算法工作，对接全链路各体裁（短视频，图文）各业务（内容消费，互动，UGC，双列，社交，生态，垂类，创作，消息，汽水音乐，精选，随变，增长投放，评论，内容理解&安全、智能对话等）。我们的工作涉及大规模推荐算法的优化、多业务复杂约束下的优化问题、多模态内容理解、LLM基础技术研究、业务Agent化和创新AI落地应用、CV/NLP等多个学术领域的算法改进工作、对多种场景的推荐架构的设计和实现和对产品数据的复杂深入的分析工作。在这里，你可以深入钻研机器学习算法的改进和优化，探索工业界最领先的推荐系统架构和推荐大模型算法、可以通过使用最新的大模型技术支持抖音的AI分身、业务智能化、智能客服等创新探索；可以通过对产品的深度理解和思考，将算法应用到业务中去；也可以通过对产品和内容生态的深度分析，影响产品未来的发展方向。\n\n1、负责抖音AI分身、智能客服、VoIP等场景的语音与音频算法研发，提升实时语音交互的智能水平、自然度和稳定性；\n2、依托公司语音及多模态基座模型，开展端到端语音对话的后训练和场景适配，提升语音理解、指令遵循和情感表达能力；\n3、研发和优化流式语音识别、语音合成、音色与韵律建模、音频理解及音视频协同等核心能力；\n4、建设语音后训练数据和评测体系，综合优化识别准确性、首包延迟、打断响应、轮次衔接、自然度和复杂环境鲁棒性；\n5、推动语音模型规模化落地，通过流式推理、蒸馏、量化和缓存等方法平衡模型效果、交互延迟和服务成本。","requirements":"1、2027届获得本科及以上学历，计算机、人工智能、电子信息、自动化、声学、数学等相关专业优先；\n2、具有扎实的机器学习、深度学习和信号处理基础，在语音识别、语音合成、语音对话或音频理解等方向有实践经验；\n3、理解Transformer、Conformer及端到端语音模型的基本原理，了解大模型后训练相关技术；\n4、具备扎实的Python及PyTorch编程能力；有C++、分布式训练或在线推理优化经验者优先；\n5、具备良好的实验分析和工程协作能力；有相关论文、开源项目、竞赛或实习经历者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667466124049205509","sourceKey":"bytedance","company":"字节跳动","title":"多模态传输SDK开发工程师 - 音视频技术","city":"北京/杭州/上海","category":"客户端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667466124049205509/detail","duty":"团队介绍：视频与边缘部门承载了字节跳动的媒体内容分发基建及技术中台，支持了字节跳动全系产品，如抖音、今日头条、番茄小说、西瓜视频等APP的点播、直播、实时通信、图片等多媒体业务发展，同时将业务发展过程中沉淀下来的技术能力和工具，通过火山引擎对外输出，面向各行各业用户提供视频云产品和服务，愿景是为内外部业务伙伴提供最低成本、最优画质、最低延时、最安全可靠的富媒体内容分发解决方案，助力业务伙伴降本提效实现持续增长。\n\n1、负责多模态传输SDK的设计和开发，建设AIGC场景通用传输能力；\n2、负责音视频新技术在AIGC场景中的应用，能协调多个团队合作完成技术方案的落地；\n3、持续优化SDK在音视频体验、性能、质量等各方面的表现，提升产品在市场上的技术竞争力；\n4、负责相关场景中的QoS、QOE指标的建设、优化，不断优化业务体验。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程、网络工程等相关专业优先；\n2、热爱计算机科学和技术，有扎实的计算机基础和编程功底，熟练掌握至少一门编程语言，包括但不限于：C、C++、Java、Objective-C、Swift、JavaScript；\n3、有良好的计算机专业基本功，熟悉HTTP、TCP/IP等常见网络协议；\n4、对技术有追求有热情，具备良好的学习能力、分析和解决问题的能力；\n5、有音视频开发经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667133130802268421","sourceKey":"bytedance","company":"字节跳动","title":"品牌传播（信息安全意识与技术方向） - 安全与风控","city":"北京","category":"内容运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667133130802268421/detail","duty":"团队介绍：安全运营团队是安全部门的协调与沟通核心，负责确保公司全域的安全举措具备可见性、易理解性，并能有效落地执行。\n我们统筹战略规划、项目交付及安全意识推广工作，同时推动构建统一的安全文化。\n通过推动运营工作的精细化落地与多方协同，助力提升组织信任度，为字节跳动全球安全战略的推进提供支撑。\n\n1、对内指围绕“信息安全”内容主题，以线上线下课程、整合营销活动、会议、设计图文、宣导视频等多样化方式提升公司员工安全意识，提升团队影响力；\n2、对外指基于“品牌营销方法论”搭建完备的安全技术影响力体系，联动安全与风控各方全面推广技术实力，负责价值翻译输出、信任体系与行业标准建设，推进行业安全技术品牌影响力建设；\n3、需负责安全技术品牌传播项目的全流程管理，清晰识别用户需求，制定传播目标和策略，推动项目落地；\n4、通过互动、调研、访谈等方式跟踪和评估传播的效率和效果，根据需求持续优化内容营销策略和推广运营计划；\n5、建联内外部合作伙伴，涉及公司业务、职能等多团队。","requirements":"1、2027届获得本科及以上学历，市场营销、新闻传播、网络安全等相关专业优先；\n2、对品牌传播、内容营销有基础认知，拥有市场推广、活动策划、内容创作、新媒体运营相关实习经历，或校园社团、学生组织项目经验者优先；\n3、具备良好的文字表达与逻辑梳理能力，有基础文案撰写、图文排版经验为佳，可提供个人相关作品者加分；\n4、具备良好的沟通协作能力与同理心，能够快速理解需求，适配多角色沟通场景；\n5、自驱力强，乐于接受挑战，执行力与结果导向意识强，对信息安全领域有好奇心，愿意主动学习跨领域知识。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7666755120239757621","sourceKey":"bytedance","company":"字节跳动","title":"大客户销售（休闲娱乐） - 抖音生活服务","city":"北京/上海/广州/成都/杭州","category":"销售","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7666755120239757621/detail","duty":"团队介绍：抖音生活服务依托抖音POI （Point of Interest）、短视频、直播、搜索等，以“激发线下生意，丰富美好生活”为使命，致力于成为最值得信赖的生活服务平台，为用户提供更丰富、独特的生活体验，为合作伙伴提供包容且公平的健康营商生态。截至2025年底，抖音生活服务业务已覆盖400+城市，超过1500万家动销门店。抖音生活服务将继续携手生态伙伴，为用户提供值得心动的商品和服务。\n\n1、负责生活服务餐饮、游玩、服务、零售行业的大客户销售工作；\n2、负责餐饮、游玩、服务、零售行业品牌商家在本地生活服务的各项商务事宜，包括商务谈判、资源投入发掘、资源分配等，提升抖音生活服务份额占比，与公司关联部门沟通协作，确保广告的及时投放与问题反馈、广告资源的合理利用与开发；\n3、负责全国餐饮、游玩、服务、零售连锁品牌的市场规划、策略制定及实施，挖掘增长机会点和重大项目拓展，联合商户打造营销事件；\n4、通过数据分析客户需求，为客户提供咨询服务、产品培训、优化投放、数据分析等营销策略，制定整合营销方案及策略，推动各行业营销策略的实施。整合内外部资源，包括大促、数据协同、品牌门店赋能等增值服务方案等。","requirements":"1、2027届获得本科及以上学历；\n2、热爱销售工作，具备良好的客户开拓和服务能力，建立良好的客户群体关系的能力；\n3、掌握商务谈判、沟通及文字写作表达交流技巧，具有一定的市场洞察力和执行力；\n4、性格开朗，敢于面对挑战。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7666002065484138757","sourceKey":"bytedance","company":"字节跳动","title":"国际直播后端研发工程师（游戏方向） - TikTok研发","city":"深圳","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7666002065484138757/detail","duty":"团队介绍：TikTok研发团队，旨在实现TikTok业务的研发工作，搭建及维护业界领先的产品。加入我们，你能接触到包括用户增长、社交、直播、电商C端、内容创造、内容消费等核心业务场景，支持产品在全球赛道上高速发展；也能接触到包括服务架构、基础技术等方向上的技术挑战，保障业务持续高质量、高效率、且安全地为用户服务；同时还能为不同业务场景提供全面的技术解决方案，优化各项产品指标及用户体验。 \n在这里， 有大牛带队与大家一同不断探索前沿， 突破想象空间。 在这里，你的每一行代码都将服务亿万用户。在这里，团队专业且纯粹，合作氛围平等且轻松。目前在北京，上海，杭州、广州、深圳分别开放多个岗位机会。\n\n1、负责架构设计和开发，为亿级用户提供优质顺畅的信息服务和极致体验；\n2、参与设计系统技术方案，核心代码开发和系统调优；\n3、参与制定代码规范、测试规范，建立起开发质量控制方法；\n4、协助团队攻克各种高并发、数据隔离、系统解耦等方面的技术难关；\n5、参与各专项技术调研，新技术引入等前瞻项目。","requirements":"1、2027届获得本科及以上学历，计算机、软件、电子信息等相关专业；\n2、热爱计算机科学和互联网技术，精通至少一门编程语言，包括但不仅限于：Java、C、C++、PHP、Python、Go；\n3、掌握扎实的计算机基础知识，深入理解数据结构、算法和操作系统知识；\n4、有优秀的逻辑分析能力，能够对业务逻辑进行合理的抽象和拆分；\n5、有强烈的求知欲，优秀的学习和沟通能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7665565694024747317","sourceKey":"bytedance","company":"字节跳动","title":"产品运营实习生 - 抖音生活服务","city":"北京","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7665565694024747317/detail","duty":"团队介绍：抖音生活服务依托抖音POI （Point of Interest）、短视频、直播、搜索等，以“激发线下生意，丰富美好生活”为使命，致力于成为最值得信赖的生活服务平台，为用户提供更丰富、独特的生活体验，为合作伙伴提供包容且公平的健康营商生态。截至2025年底，抖音生活服务业务已覆盖400+城市，超过1500万家动销门店。抖音生活服务将继续携手生态伙伴，为用户提供值得心动的商品和服务。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、负责生活服务销售运营CRM系统，销售及商家策略板块的产品运营工作；\n2、完成用户使用反馈收集、Oncall问题排查、业务侧与商家侧的问题答疑、建立监控机制并提出优化建议；\n3、深入分析业务问题，产出分析报告，提出有建设性的建议，结合产品和运营等能力落地并持续跟进，推动业务增长；\n4、参与销售目标及绩效激励效果的数据分析与复盘，沉淀执行方法论，为后续策略迭代提供数据支撑。","requirements":"1、本科及以上学历在读，专业不限；\n2、具备较强的学习能力、能快速理解复杂的业务体系，有沟通协调能力与自驱力，擅长跨部门协作，能高效整合内外部资源推进项目落地；\n3、有基础数据分析能力（Excel/SQL优先），以数据结果为导向，能通过数据梳理业务逻辑、定位问题并制定相应策略；\n4、抖音深度使用者，对团购业务有清晰了解，有相关领域实习经验者优先；\n5、base北京，每周出勤5天，可实习4个月以上者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7665353413696096517","sourceKey":"bytedance","company":"字节跳动","title":"Video/Image AI/ML多媒体算法工程师 - 音视频技术","city":"北京/深圳/上海","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7665353413696096517/detail","duty":"团队介绍：视频与边缘部门承载了字节跳动的媒体内容分发基建及技术中台，支持了字节跳动全系产品，如抖音、今日头条、番茄小说、西瓜视频等APP的点播、直播、实时通信、图片等多媒体业务发展，同时将业务发展过程中沉淀下来的技术能力和工具，通过火山引擎对外输出，面向各行各业用户提供视频云产品和服务，愿景是为内外部业务伙伴提供最低成本、最优画质、最低延时、最安全可靠的富媒体内容分发解决方案，助力业务伙伴降本提效实现持续增长。\n\n1、设计视频分析算法（如ROI分析、内容理解、特征提取等）及视频质量评估算法，参与数据库构建、算法设计/开发/优化等相关工作；\n2、参与编码器的端到端（E2E）视频质量优化策略与解决方案的设计，结合视频分析、视频处理与编码算法（例如帧级码率控制等）进行系统优化；\n3、将设计的算法应用于点播（VOD）/直播监控、数据分析及算法客观评估等场景；\n4、与基础架构（Infra）团队及多媒体平台团队协作，将算法集成到生产工作流程中，并通过A/B测试验证算法效果与实际收益。","requirements":"1、获得2027届硕士及以上学位，计算机科学、电子工程、数学、统计学专业；\n2、熟练掌握一种或多种通用编程语言，具备优秀的编程、调试与优化能力，比如：C/C++、Python；\n3、了解视频分析算法或主观/客观视频质量评估算法及前沿技术，例如VMAF、PSNR、SSIM等。\n\n加分项\n1、熟悉Transformer架构及主流多模态大模型（MLLM），具有相关实现或研究经验者优先；\n2、了解常见视频处理算法，如锐化（Sharpen Filter）、降噪模型（De-noise Model）等；\n3、具备机器学习或深度学习经验，熟悉TensorFlow、PyTorch等深度学习框架；\n4、了解视频编码标准（AVC、HEVC、AV1、VP9等），并具有视频编码器设计经验；\n5、具备嵌入式处理器经验（如ARM Cortex M0/M3/M4或RISC-V架构）及RTOS实时系统开发经验；\n6、具备良好的沟通能力，积极主动、乐于学习，并热衷于将前沿技术落地到实际应用场景中。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7615512580086483205","sourceKey":"bytedance","company":"字节跳动","title":"AI Agent服务端研发实习生-开发者服务","city":"北京","category":"后端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7615512580086483205/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：字节跳动开发者服务团队负责公司研发工具与基础设施体系建设，为内部开发者提供覆盖全技术栈的框架、工具和研发体系能力，支撑业务高效稳定迭代。\n在此基础上，团队正打造面向全场景的AI Agent平台，将大模型与公司内部工程知识深度结合，覆盖需求分析、编码开发、测试发布、运维治理等软件全生命周期，帮助ByteDancer显著提升生产力，重塑开发者服务的形态与体验。\n期待对研发工具体系、AI工程生产力有热情、希望在大规模真实场景中打磨技术的同学加入，与我们一起建设新一代开发者基础设施，共同成长！\n\n1、围绕研发高可用治理，质量保障AI化，研发环境管理等方向进行Agent应用开发工作，推动AI技术在相关场景的落地与突破；\n2、参与大模型应用开发全流程，包括但不限于模型接入、AI Agent开发、RAG优化、MCP及工具开发、数据工程等；\n3、跟踪AI领域的发展动态，推动Agent应用的持续优化。","requirements":"1、2027届本科及以上学历在读，计算机、人工智能、自动化、数学相关专业优先；\n2、优秀的代码能力、数据结构和基础算法功底，熟练掌握至少一门编程语言，包括但不限于Python、Java、Go等；\n3、了解AI Agent相关技术与设计思想，了解主流AI模型及其应用场景；\n4、有从0-1搭建AI Agent应用经验，能够独立完成Agent应用的设计开发者优先；\n5、在ACM/ICPC、NOI/IOI、Top Coder、Kaggle等比赛获奖者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7594717764830366005","sourceKey":"bytedance","company":"字节跳动","title":"大模型评估与环境算法实习生-Commercial AI","city":"北京","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7594717764830366005/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：Commercial AI 负责中国交易与广告的to B应用统一模型建设，包含基础模型能力、AI Infra、统一商业数据、评测等方向。\n\n1、协助从商家运营、广告优化、内容运营、客服等业务中抽取高价值任务，设计评估样本与任务集；\n2、参与大模型能力图谱与指标体系设计，覆盖任务完成度、业务收益代理指标（Proxy）、安全与合规等维度；\n3、参与探索/实现评测方法，如LLM-As-A-Judge、多维Rubric、Pairwise比较、自动Red-Teaming（攻防评估）等；\n4、编写实验代码与分析脚本，完成结果分析、可视化与小结；\n5、撰写技术文档/报告，与模型、算法、产品等同学合作推动项目落地。","requirements":"1、2027届本科及以上学历在读，计算机、数学、统计等相关专业优先；\n2、有机器学习/NLP/推荐/广告/RL等任一方向基础，做过课程项目或科研/实习项目；\n3、对大语言模型/Agent有兴趣，有相关项目/论文/开源作品者优先；\n4、熟练使用Python，熟悉至少一种常用深度学习框架（PyTorch/TensorFlow等）；\n5、具备基本实验设计与数据分析能力，习惯用代码说话；\n6、主动性强，愿意在不确定环境下学习新东西、探索新问题；每周出勤不少于3天，实习周期不少于3个月，可长期实习优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7686029224306264373","sourceKey":"bytedance","company":"字节跳动","title":"大客户物流解决方案实习生 - TikTok Shop","city":"上海","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7686029224306264373/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商。平台汇聚全球优质商家与创作者，通过短视频、直播等多场景连接消费者，让新奇好物畅销全球，让美好生活触手可得。目前团队分布在美国、英国、法国、印尼、墨西哥、中国等全球多个国家和地区，在这里你将有机会深入国际业务场景，面向全世界商家及用户，和跨区域团队协作，共同探索创新购物模式。期待和优秀的你一起创造更多可能！\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、协助团队为核心大客户设计端到端物流解决方案，包括仓储、干线、配送等环节；\n2、协助收集并分析客户业务数据（如订单量、区域分布、物流成本等），输出洞察报告；\n3、协助跨部门沟通，推动解决方案从设计到落地的执行，包括流程梳理、SOP撰写、问题跟进等；\n4、跟踪方案试点或上线的运营表现，提出优化建议；\n5、支持行业洞察研究、市场调研等专项项目；\n6、完成团队分配的其他相关任务。","requirements":"1、本科及以上学历在读，物流管理、供应链、运营管理、数据分析、商科类等相关专业优先；\n2、具备良好的数据处理和分析能力，熟练使用Excel，掌握SQL或Python优先；\n3、逻辑思维清晰，具备良好的结构化思考能力；\n4、做事认真细致，有责任心，有一定的项目管理意识；\n5、具备良好的沟通协调能力，能够与不同职能部门合作；\n6、每周可实习4天及以上，可以实习5个月及以上。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7673033397752777013","sourceKey":"bytedance","company":"字节跳动","title":"机器学习研究员（Agent评测与演进方向） - 火山方舟","city":"北京","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7673033397752777013/detail","duty":"团队介绍：火山方舟是火山引擎推出的一站式大模型服务平台，是中国大模型市场产品和份额领跑者。平台提供模型推理、评测、精调等全流程服务。方舟搭载了豆包及业界主流大模型，提供丰富的插件生态和AI应用开发服务，并通过稳定可靠的安全互信方案、专业的算法技术服务，全方位保障企业级AI应用落地。\n\n1、设计面向大语言模型Agent的评测体系，覆盖任务成功率、工具使用、推理质量和可靠性等维度；\n2、构建Benchmark和自动化评测流水线，综合运用规则检查、模型评审和人工评审等方式；\n3、分析Agent执行轨迹和用户反馈，识别典型失败模式，并将分析结果转化为具体的系统改进；\n4、推动从经验数据到能力提升的闭环，与研究、平台和产品团队协作，将相关方法落地到生产环境。","requirements":"1、2027届获得硕士及以上学位，计算机科学、人工智能、机器学习、数据科学或相关专业优先；\n2、具备扎实的机器学习和深度学习基础；\n3、通过科研、实习或项目，对基于大语言模型的系统有实践经验，例如Agent、工具调用、检索或多Agent系统等；\n4、具备扎实的Python编程能力，熟悉主流机器学习或Agent评测框架；\n5、通过论文、重要项目、实习或开源贡献展现出较强的研究或工程能力。\n\n加分项：\n1、在机器学习或自然语言处理领域的顶级会议发表过论文，如NeurIPS、ICML、ICLR、ACL等；研究方向涉及Agent学习、自我改进、自演进、递归式自我改进（RSI）或Agent评测者优先；\n2、具备评测方法相关经验，例如指标设计、基于模型的评审、数据标注或统计分析等；\n3、熟悉大语言模型后训练、推理与规划方法或持续学习；\n4、具备反馈驱动的优化闭环，或大规模日志及执行轨迹分析经验。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668631875896805685","sourceKey":"bytedance","company":"字节跳动","title":"豆包大模型多模态算法工程师 - Data AML","city":"上海/北京/深圳/杭州","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668631875896805685/detail","duty":"团队介绍：Data AML是字节跳动的机器学习中台，为抖音/今日头条/西瓜视频等业务提供推荐/广告/CV/语音/NLP的训练和推理系统。为公司内业务部门提供强大的机器学习算力，并在这些业务的问题上研究一些具有通用性和创新性的算法。同时，也通过火山引擎将一些机器学习/推荐系统的核心能力提供给外部企业客户。\n\n1、探索研究多模态理解、强化学习、计算机视觉Agent等前沿技术；对多模态模型能力和理想态的差距保持敏感，评测和优化提升多模态模型的能力极限；\n2、专注提升多模态大模型在现实世界复杂任务的效果，追求通用可规模化的方法，优化领域包括但不限于视觉推理、Streaming video交互、多模态Agent、大规模数据合成、Mid-training等方向；\n3、推动多模态大模型在成本/效率方面的极致优化，包括但不限于大规模蒸馏/自蒸馏、Efficient reasoning、极致的Video压缩等方向；\n4、依托公司和业界的大模型和基础CV技术，构建面向To B业务应用的多模态算法能力，帮助业务取得成功。","requirements":"1、2027届获得硕士及以上学位，计算机、数学等相关专业优先；\n2、具有优秀的基础算法、代码能力，熟练掌握C/C++或Python编程语言，ACM/ICPC、NOI/IOI、Top Coder、Kaggle等比赛获奖者优先；\n3、具有扎实的计算机视觉、机器学习基础，熟悉CV、AIGC、NLP、RL等技术领域，在CVPR、ECCV、ICCV、NeurIPS、ICLR、SIGGRAPH或SIGGRAPH Asia等顶级会议上发表论文者优先；\n4、在大模型领域或者RL领域，主导过大影响力的项目者优先；\n5、具有出色的分析、解决问题的能力，能深入解决大模型训练和应用存在的问题，有自主探索解决方案的能力者优先；对AI技术的实际落地和突破性应用充满热情，追求技术创新与现实价值的结合；\n6、具有良好的沟通协作能力，工作积极主动，能够与团队融洽合作，一起探索新技术，推进技术进步。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668568027743013125","sourceKey":"bytedance","company":"字节跳动","title":"平台产品经理 - 抖音生活服务","city":"上海/北京","category":"产品","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668568027743013125/detail","duty":"团队介绍：抖音生活服务依托抖音POI （Point of Interest）、短视频、直播、搜索等，以“激发线下生意，丰富美好生活”为使命，致力于成为最值得信赖的生活服务平台，为用户提供更丰富、独特的生活体验，为合作伙伴提供包容且公平的健康营商生态。截至2025年底，抖音生活服务业务已覆盖400+城市，超过1500万家动销门店。抖音生活服务将继续携手生态伙伴，为用户提供值得心动的商品和服务。\n\n1、面向销售团队建设CRM工作台产品，帮助管理者看清数据、辅助决策以及管理动作的快速推进，帮助销售线上化执行客户运营动作；\n2、与内部销售团队紧密合作，收集和分析管理数据，挖掘业绩提升方向、线下动作线上化机会点；\n3、通过数据发现问题，能够进行数据的逻辑下拆、数理归因；\n4、撰写高质量需求文档，协调产品及内部协作团队资源，确保产品高质量落地。","requirements":"1、2027届获得本科及以上学历，专业不限；\n2、对生活服务和商家/平台产品保持充分热情；\n3、对用户体验和工具设计敏感，在交互、视觉方面具备良好的感觉，同理心强、数据敏感；\n4、逻辑思维出色，沟通表达清晰，具备辩证思维和探索精神，有一定的想象力和创造力；\n5、对新型生活服务商业模式有思考和兴趣，自驱成长、结果导向。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668252418966980917","sourceKey":"bytedance","company":"字节跳动","title":"抖音视频安全治理策略 - 抖音社区治理","city":"北京/上海","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668252418966980917/detail","duty":"团队介绍：抖音致力于打造一个开放、积极、多元、友善的平台，鼓励表达、沟通和记录，激发创造，丰富人们的精神世界，让现实生活更美好。我们通过AI算法驱动的个性化推荐与智能创作工具，满足用户表达、学习、娱乐、社交、消费等需求。回顾抖音一路走来的历程，我们在帮助亿万用户记录美好生活的过程中，努力变得更好。抖音社区治理团队负责抖音的社区治理工作，包括视频、直播等多体裁的内容治理，以及安全产品中台能力建设。\n\n1、负责抖音内容安全治理策略体系建设，协同产品、算法、审核、运营等团队，推进问题发现、定义、识别、处置和复盘机制落地；\n2、围绕内容安全风险与业务场景，参与治理策略设计和能力建设，平衡内容治理效果与业务发展诉求，持续优化审核链路和处置效率；\n3、基于内容特征、用户行为、消费路径及风险表现进行分析，识别潜在治理问题，制定内容处置策略并推动迭代；\n4、结合数据分析、策略评估和业务反馈，参与治理项目目标拆解、优先级判断及跨团队协作推进，产出可持续优化方案；\n5、关注大模型在内容理解、风险识别、策略辅助分析等方向的应用，探索将大模型能力融入治理策略设计、问题归因和效率提升场景。","requirements":"1、2027届获得本科及以上学历，专业不限，统计学/计算机/数据科学等理工专业优先；\n2、具备较强的内容理解能力和文字敏感度，对内容安全、社区生态、平台治理等方向有兴趣，认真负责，主观能动性强；\n3、具备基础的数据分析能力，能通过数据发现问题、验证判断并总结规律，有SQL/Python/数据分析项目经验优先；\n4、逻辑思维清晰，善于拆解问题并推动解决，具备良好的沟通协作能力和一定产品思维；\n5、大模型应用实践经验优先：包括提示词设计、AI工具使用、文本理解/分类/归因场景实践，或参与过大模型相关项目；不要求深度算法背景，需具备主动学习和业务应用意识。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667949032820492597","sourceKey":"bytedance","company":"字节跳动","title":"广告算法工程师 - Data AML","city":"北京/深圳/杭州","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667949032820492597/detail","duty":"团队介绍：Data AML是字节跳动的机器学习中台，为抖音/今日头条/西瓜视频等业务提供推荐/广告/CV/语音/NLP的训练和推理系统。为公司内业务部门提供强大的机器学习算力，并在这些业务的问题上研究一些具有通用性和创新性的算法。同时，也通过火山引擎将一些机器学习/推荐系统的核心能力提供给外部企业客户。\n\n1、将字节跳动的推荐广告算法Ranking技术在多种亿级日活商业化变现场景落地，开展以下工作：\n2、参与字节跳动亿级日活广告推荐系统建设，探索推荐模型Scaling Law，将更大规模数据、模型和算力转化为广告效果、用户体验和商业价值提升；\n3、研究生成式广告推荐技术，探索生成式召回、语义ID、端到端召回排序统一建模、Session-wise generation等下一代推荐范式；\n4、优化大规模广告系统中的建模问题，包括深度转化预估、转化延迟、广告混排、多场景联动、冷启动、ID泛化、粗精排一致性和长期价值建模；\n5、探索LLM、VLM、多模态大模型在广告推荐中的应用，包括广告内容理解、用户意图建模、创意质量预估、跨域迁移、可解释推荐和智能投放辅助；\n6、推进大规模推荐模型的训练与推理效率优化，重点关注GPU利用率、长序列建模、MoE、模型并行、量化蒸馏、Triton、CUDA Kernel优化和低延迟在线推理。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程、人工智能等相关专业；\n2、扎实的算法和数据结构基础，熟悉深度学习算法；\n3、熟悉数据挖掘、机器学习、分布式计算中的一项或多项，有深度学习实战经验和机器学习算法优化理论的研究经验优先；\n4、具备优秀的学习能力和良好的团队合作精神，较好的沟通能力，对解决具有挑战性的业务问题充满激情。\n\n加分项：\n1、熟悉Deep Models在业务上的应用；\n2、有个性化推荐、广告、信息检索、机器学习等相关领域研究或者项目实践经验；\n3、在推荐、广告业务有实习经历；\n4、在KDD、NeurIPS、WWW、SIGIR、WSDM、ICML、IJCAI、AAAI、RecSys等会议发表过论文，在ACM/ICPC、NOI/IOI、Top Coder、Kaggle等比赛获奖者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667766805872740661","sourceKey":"bytedance","company":"字节跳动","title":"AI策略产品经理（抖音AI产品人才校招） - 抖音搜索","city":"北京","category":"产品","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667766805872740661/detail","duty":"团队介绍：抖音搜索是抖音的核心产品能力之一，满足用户找内容、找商品、找服务、找经验、找人等多元需求，基于海量的内容和商品供给、领先的意图识别和产品能力，用户搜索规模保持高速增长，快速成为中国第一梯队的移动搜索平台。抖音搜索业务体系完善，涵盖内容、电商、生活服务、推荐、交互、数据分析等多个方向。AI大模型和抖音内容生态的结合，会给抖音搜索带来的新的增长动力！\n\n这是抖音面向具备AI能力的同学发起的校招项目，覆盖产品、策略运营方向。\nAI 正在重新定义产品，也在重新定义\"做产品\"这件事 —— AI Native 的产品，需要你既能理解大模型技术边界，又能定义产品价值。\n如果你也有着许多的奇思妙想， 欢迎加入抖音，把想法落地成亿万用户真实可感的产品体验，来抖音，和我们一起探索 AI 产品的下一种可能！\n\n1、负责抖音搜索策略产品工作，能够深入用户搜索体验，发现问题，提出解决方案；\n2、参与抖音搜索AI Agent方向产品工作，协同算法/工程团队落地AI Agent驱动的搜索排序方案；\n3、负责基于搜索AI Agent框架的搜索需求挖掘和理解、工具调用、多轮追问等模块的效果优化。","requirements":"1、2027届获得本科及以上学历，具备计算机相关专业背景；\n2、有一定的编程和数据能力，了解算法和大语言模型等方面知识；有AI/大模型策略、搜索策略、或在搜索场景应用大模型的相关经验者优先；\n3、熟悉大模型/AI的基本原理，对AI Agent/LLM应用产品有理解和认知者优先；\n4、自驱、学习能力强；逻辑清晰，数据分析能力强；沟通协同能力强。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667118756632168757","sourceKey":"bytedance","company":"字节跳动","title":"前端研发工程师 - 国际化广告商业平台","city":"杭州/北京/上海/深圳","category":"前端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667118756632168757/detail","duty":"团队介绍：国际广告平台团队负责字节跳动国际短视频业务的大型广告系统建设，是推动国际化产品商业化营收的核心力量之一。自成立以来，我们始终紧跟国际化产品发展的步伐，不断创新，致力于打造服务全球广告主的综合数字化营销服务平台，为广告主、创作者和用户搭建起一座价值互通的桥梁。我们诚邀怀揣梦想与激情的你，加入我们的行列，一同探索广告科技的无限可能！\n\n1、负责前端技术选型和开发工作；\n2、优化前端功能设计，解决各种浏览器和终端设备的兼容性问题；\n3、通过技术手段，提升用户体验并满足高性能要求；\n4、编写通用组件、类库，提升开发效率和质量。","requirements":"1、2027届获得本科及以上学历，计算机相关专业优先；\n2、精通HTML、CSS、JS、JavaScript、AJAX、DOM、jQuery等技术，熟悉页面架构和布局，熟悉HTML5/CSS3等常用技术；\n3、熟悉常用UI框架（如Bootstrap/Pure/Kendo等）；\n4、熟悉Node.js，熟练使用Grunt、gulp、Webpack等构建工具；\n5、具备MVVM框架开发经验，如React、Vue.js、AngularJS等；\n6、良好的沟通和团队协作能力、热爱技术、责任心强、能推动技术框架的落地使用。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7652275704996940037","sourceKey":"bytedance","company":"字节跳动","title":"项目管理（AI）实习生-隐私和数据保护办公室","city":"北京","category":"项目管理","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7652275704996940037/detail","duty":"日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n团队介绍：我们是字节跳动隐私与数据保护核心团队，联动法律、安全、研发等多方力量，为全球数亿用户构建第一道数据安全防线。聚焦隐私合规落地、数据风险防控，在超150个国家/地区的复杂隐私、数据合规场景中，构建全生命周期数据安全方案，以\"隐私+数据\"双通道驱动保护创新。\n为什么加入我们？\n1、全球化核心战场：加入支撑字节跳动国际化生态的关键团队，主导服务数亿用户的隐私安全体系，同字节跳动系产品一起定义行业标准；\n2、硬核能力历练：攻克数亿级数据防护，横跨美洲、欧盟、东南亚等法律差异等难题，沉淀覆盖多区域的合规技术视野；\n3、多元成长生态：融入跨多国家多城市的协作团队，参与行业隐私标杆项目，在文化碰撞中解锁国际化合规实战经验。\n\n1、负责TikTok主站，电商，商业化，以及游戏等其他面向业务线的隐私合规技术治理工作；\n2、能够理解字节跳动体系的技术架构，推动技术治理场景等判断和组织协调工作；\n3、协助推进公司层面统一的合规工作专项在各业务线落地执行，推动治理工单等交付，以及跨团队的复杂技术治理工作组织和统筹；\n4、配合内审内控等团队，协助实施内部合规审计，包括数据权限、跨境传输合规、APP/SDK合规。","requirements":"1、本科及以上学历在读，计算机科学、信息安全、法学相关专业优先；\n2、对互联网技术有一定的理解力；了解重要市场的法律法规，如GDPR、CCPA、CPRA、COPPA等优先；\n3、英语可以作为工作语言，具备良好的听说读写能力，有跨国企业或国际化留学/工作经历者优先；\n4、具备良好的团队协作能力、沟通能力与自我驱动力，过往有项目管理经验优先；\n5、能保证一周至少4天实习，持续六个月以上，有AI实践具体业务场景提效或Agent构建实践使用等经验优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7548030428407040274","sourceKey":"bytedance","company":"字节跳动","title":"测试开发实习生-今日头条","city":"北京","category":"测试","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7548030428407040274/detail","duty":"日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n团队介绍：产品覆盖今日头条、头条极速版等各类产品，为上亿用户持续提供优质的资讯、视频等服务。我们通过建立良好的内容生态，鼓励优质的原创内容，为创作者提供优质的服务和创作体验，促进创作和交流，同时我们致力于通过尽可能丰富的内容体裁和尽可能多的分发方式，连接人与信息，丰富大家的精神生活，让人们看到更大的世界。\n\n1、主要负责客户端/服务端产品质量相关或业务线测试与工具开发工作；\n2、深度参与产品研发项目， 协同产品和研发团队高质量交付产品；\n3、日常项目线下测试与线上质量分析；\n4、参与质量体系规划和建设；\n5、参与开发效率工具和保证技术项目质量。","requirements":"1、本科及以上学历在读，计算机、软件工程等相关专业优先；\n2、热爱互联网，对互联网相关业务和技术充满好奇及热情；\n3、具备快速的产品及业务学习能力、敏捷而周到的逻辑思维能力以及良好的沟通协作能力；\n4、有移动互联网测试经验，有自动化或白盒测试经验优先考虑；\n5、了解常用客户端、服务端开发及前沿技术， 如自动化框架、压测工具、大数据处理，AI大模型等优先；\n6、每周至少工作4天，实习时间3个月及以上。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7687460668896381189","sourceKey":"bytedance","company":"字节跳动","title":"世界生成互动创作Agent算法实习生 - 剪映CapCut","city":"北京/深圳","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7687460668896381189/detail","duty":"团队介绍：剪映研发团队，主要支持剪映、CapCut、醒图、Hypic、即梦、Dreamina、小云雀、Pippit等多款国内外产品的研发工作，业务覆盖多元化影像创作场景，并孵化了多款AIGC明星产品，相关产品多次登顶国内外App Store 免费应用榜第一，并继续保持高速增长。加入我们，一起打造全球最受用户欢迎的影像创作和GenAI产品。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、负责互动视频/游戏相关AI算法的研发与落地应用，聚焦AIGC基础模型在互动视频/游戏场景的适配与创新，包括世界生成、剧情分支智能推进、用户与系统的互动行为实现等；\n2、高质量互动影游相关数据挖掘、清洗与对齐，探索游戏剧情、角色动作、玩家交互等多维度数据的自动合成方法，结合Self-Instruct等技术优化数据质量，支撑模型训练；\n3、全模态大模型（文本、图像、语音）的Post-training算法研究，探索多模态感知与交互能力在互动影游场景的边界，实现剧情、角色、玩家行为的精准匹配与响应；\n4、结合LongCoT/RL等技术实现互动影游AI Agent的全链路自主探索学习，探索Agent与游戏剧情推进、玩家交互目标深度融合的学习方式，提升游戏交互的自主性与趣味性；\n5、结合互动影游业务场景，将AI算法技术转化为线上产品功能，赋能游戏研发、剧情生成、玩家交互等环节，服务广大互动影游创作者与玩家。","requirements":"1、本科及以上学历在读，计算机/软件工程/人工智能等相关专业优先；\n2、在计算机视觉、机器学习算法方向一个或多个细分领域有研究/实践经验，包括但不限于以下方向：\n1）多模态生成与交互理解：如文本To图像/视频/3D生成和编辑，以及其他相关的多模态经验；\n2）有强化学习结合大模型落地游戏场景的经验，有剧情智能生成、虚拟角色交互、游戏AI逻辑设计等相关经验优先；\n3）熟悉扩散模型、GAN、Transformer等生成式模型，具备将生成模型应用于业务场景的实践能力；\n4）具备模型训练经验，熟悉AIGC、LLM、RLHF等技术；\n3、动手能力强，具有熟练的算法设计和编程能力，熟悉C/C++和Python编程，掌握TensorFlow、PyTorch等深度学习框架；\n4、工作积极主动，能与团队融洽合作相处，同时能够独立完成研究工作；\n5、每周出勤至少4天，可实习4个月以上。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7683812147665438981","sourceKey":"bytedance","company":"字节跳动","title":"AI策略产品（抖音AI产品人才校招） - 抖音增长","city":"北京","category":"产品","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7683812147665438981/detail","duty":"团队介绍：抖音增长团队（User Growth）负责抖音旗下产品的增长工作。我们帮助产品量身定做增长方案，并运用营销、产品、数据分析等方式达成业务增长目标。UG团队维护和优化一系列类似付费广告、裂变、导量等成熟的产品增长方案，并熟练将其应用到各种不同的业务中，推动业务增长；同时当发现新的增长机会时，我们也及时构建新的解决方案，帮助业务实现突破。加入 UG 团队，可以负责亿级用户产品的增长工作，掌握业界先进、第一手的增长实践。\n\n这是抖音面向具备AI能力的同学发起的校招项目，覆盖产品、策略运营方向。\nAI 正在重新定义产品，也在重新定义\"做产品\"这件事 —— AI Native 的产品，需要你既能理解大模型技术边界，又能定义产品价值。\n如果你也有着许多的奇思妙想， 欢迎加入抖音，把想法落地成亿万用户真实可感的产品体验，来抖音，和我们一起探索 AI 产品的下一种可能！\n\n1、负责面向抖音用户场景的AI产品探索和落地，挖掘增长机会点，提升业务效率与增长效果；\n2、能够深入理解实际场景，具备一定的想象和创新能力，结合数据分析和用户研究，把产品洞察和认知转化成模型实际需求；\n3、能够运用业界最新AI技术与先进模型，推进AI内容生成和分发的功能设计和实现，并能定义测评标准和方法，迭代测评指标，确定后续方向；\n4、持续追踪AI技术趋势，快速响应技术变革，推动产品迭代。","requirements":"1、2027届获得本科及以上学历，人工智能、计算机、信息管理、数学、统计学、经济学相关专业优先；\n2、对AI技术和新产品有浓厚兴趣，关注业界最新动态，能主动发现应用场景和机会并转化为产品需求；\n3、具备较强的动手能力和全栈能力，熟练使用各类AI模型和AI编程工具将想法转化为现实；\n4、有AI行业实践经验及AI创业经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7678945790992304437","sourceKey":"bytedance","company":"字节跳动","title":"商家直播产品实习生 - TikTok生活服务","city":"北京","category":"产品","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7678945790992304437/detail","duty":"团队介绍：TikTok是一个覆盖150个国家和地区的国际短视频平台，我们希望通过TikTok发现真实、有趣的瞬间,让生活更美好。TikTok在全球各地设有办公室，全球总部位于洛杉矶和新加坡，办公地点还包括纽约、伦敦、都柏林、巴黎、柏林、迪拜、雅加达、首尔和东京等多个城市。\n\nTikTok生活服务(TikTok GO) 是一站式商业解决方案，创造性地通过TikTok POI、短视频、直播和搜索等，连接全球用户与本地服务，提供有价值的真实世界生活体验，激发用户探索周围的世界。以“发现好去处，助力本地商家”为使命，致力于成为最值得信赖的发现好去处和连接本地商家的平台，让社区更轻松地与餐厅、酒店和景点互动，为商家提供全新方式来连接客户并促进交易，结合创新的营销和运营工具，带来可持续增长。团队分布多国，目前积极扩张中。大航海时代，我们欢迎大家一起加入国际化征程，共同打造TikTok生活服务业务!\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、参与直播商家/达人的复盘诊断、直播切片、内部工具等影响主播成长孵化的产品能力建设；\n2、基于用户反馈和业务数据，优化直播评论管理、直播回放等基础工具建设；\n3、善用AI工具（大模型、AI数据分析/Agent等）辅助取数分析、策略生成、内容/流程自动化，提升个人与团队工作效率；\n4、跟进产品/运营方案从需求到上线的全流程，参与需求评审、方案撰写、灰度验证与效果复盘；与产品、运营、研发、数据等团队协同，推动项目落地。","requirements":"1、本科及以上学历在读，专业不限；\n2、每周可到岗4天以上，可持续实习3个月以上（优先长期）；\n3、具备较强的AI应用能力：熟练使用主流AI工具（如大模型对话、AI编程/数据分析、Agent等）辅助完成工作，具备用AI解决实际业务问题的意识和实践；\n4、具备较强的数据分析能力，熟练使用Excel/SQL，能独立完成取数、分析与结论输出；\n5、逻辑清晰、结构化思考能力强，具备较好的业务意识和用户/商家、达人经营视角；主动性强，执行力好，推动事情落地；\n6、有直播、电商、本地生活、增长/供给相关实习经历者优先；英文可作为工作语言者优先（涉及国际化市场业务）。\n\n加分项\n1、有B端直播、短视频等相关项目经验；\n2、熟悉直播电商生态与商家运营逻辑；\n3、有AI工具深度应用经验，如用Prompt工程、AI Agent、自动化工作流提升效率或搭建业务小工具。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7678943572557383989","sourceKey":"bytedance","company":"字节跳动","title":"AI Agent开发工程师 - 抖音研发","city":"北京/杭州/上海","category":"前端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7678943572557383989/detail","duty":"团队介绍：抖音研发部门负责多款大型产品的研发，包括但不限于抖音、西瓜视频、汽水音乐。\n加入我们，你将有机会参与亿级用户场景的开发与架构工作，使用前沿的技术助力业务一起不断成长。\n\n1、参与抖音跨平台AI Agent产品及Agent Harness的架构设计与功能开发，推动AI能力在跨端研发场景中落地；\n2、参与AI Coding产品的基建能力建设，包括SDLC全流程中代码理解与修改、工程构建、设备调试、Verify验证、部署、问题排查、性能优化等环节任务；\n3、参与Agent Harness能力建设，包括上下文与状态管理、任务规划与执行控制、工具调用、记忆、权限管理、沙箱执行、异常恢复及执行可观测；根据实际任务复杂度选择单Agent或Multi-Agent架构；\n4、建设跨平台研发工具链的AI Native原子能力，通过MCP、API、CLI等方式，使Agent能够在真实工程环境中完成任务并验证结果；\n5、建设评测体系，围绕功能正确性、执行轨迹、工具调用、稳定性、时延、成本及安全风险设计评测方法，支持离线评估、历史任务回放、回归验证和问题归因；\n6、参与边缘模型部署与推理基础服务建设，围绕“端/边/云”模型场景的性能成本探索，全局异构资源治理、Token成本运营等相关工作。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程、人工智能等相关专业优先；\n2、具备扎实的编程基础，深入理解数据结构、基础算法和常用计算机系统知识；熟练掌握TypeScript/JavaScript、Python、Java/Kotlin、Swift、C++、Golang等至少一门语言，能够独立完成工程项目；\n3、在前端、客户端或服务端至少一个方向具备较好的工程基础，能够完成模块设计、编码、测试和问题排查，并愿意跨技术边界解决问题；具备基本的服务端与API开发能力，熟悉Node.js、Golang生态下至少一套开发框架，理解异步任务、状态持久化、超时重试、服务部署及故障排查；\n4、理解大语言模型及Agent的基本机制，包括上下文构建、任务规划、工具调用、状态与记忆管理、执行控制、RAG和结果验证；有可实际运行的Agent、AI编程工具或自动化项目经验；\n5、具备良好的质量意识，能够针对模型输出的不确定性设计测试与评估方法，并通过日志、Tracing、执行轨迹和指标定位问题；关注系统稳定性、性能、成本、权限及安全边界；\n6、具备较强的问题拆解、学习和协作能力，能够将模糊需求转化为可实现、可验证的工程任务，并对最终交付结果负责。\n\n加分项\n1、有Agent Harness、MCP、Coding Agent、Multi-Agent、运行时沙箱、自动化评测或可观测性相关实践；\n2、有移动端跨端容器、开发者工具、CI/CD等领域经验；\n3、了解SFT、模型推理优化，使用过LangChain、LangGraph、LlamaIndex等LLM应用框架，并清晰掌握原理；\n4、独立完成过高质量AI项目，或有相关开源贡献、论文、技术竞赛成果。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669716980568049973","sourceKey":"bytedance","company":"字节跳动","title":"游戏算法工程师（3D方向） - AIGC","city":"杭州","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669716980568049973/detail","duty":"团队介绍：游戏-AIGC部门，致力于将生成式AI落地到游戏中，包括但不限于模型、贴图、动画、场景、剧情、对话、玩法等游戏核心元素的AI生成和AI提效。部门近几年一直在游戏AI和数字人方向持续深耕，欢迎加入我们。\n\n1、参与到AI3D、动作、视频等研究方向之一，探索AI技术在游戏制作效率提升、玩法创新上的可能性；\n2、包括但不限于3D生成模型、贴图生成模型、3D数据分析、几何结构优化等；\n3、包括但不限于动作生成模型、视频动作捕捉、动作数据分析、自动重定向、自动绑定等；\n4、包括但不限于围绕视频模型的上下游算法设计与调优；\n5、包括但不限于上述流程的Agent化、自动流程设计与开发。","requirements":"1、2027届获得本科及以上学历，计算机、自动化、电子信息、数学等相关专业；\n2、熟悉2D、3D视觉的基本知识，熟悉DiT、AR等模型；在3D生成、几何处理、动作生成、数字人等方向之一有研究经验；\n3、在以上方向有主导过有影响力的项目或论文者优先；\n4、具备出色的编程能力、数据结构和算法技能，熟练掌握C/C++或Python编程语言，在ACM/ICPC、NOI/IOI、Top Coder、Kaggle等比赛中获奖者优先；\n5、对数据敏感、有良好的逻辑思维及沟通协作能力；\n6、对AIGC与游戏有强烈兴趣和热情者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669709609729313077","sourceKey":"bytedance","company":"字节跳动","title":"大模型应用算法工程师 - 中国交易与广告","city":"上海/深圳/北京","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669709609729313077/detail","duty":"团队介绍：中国交易与广告，基于个性化推荐、深度学习和大模型技术，依托抖音、今日头条、红果短剧、西瓜视频、番茄小说等多元产品，构建抖音电商、生活服务、广告营销等核心营收业务的算法策略和工程架构。部门运用领先的算法能力，精准连接海量用户与商家，通过推荐、广告和搜索算法精准匹配需求并促进交易达成，保障用户体验与商家权益，实现营收业务可持续增长；基于深厚的技术积累，构建高效、智能、可靠的交易与广告产品，全面提升多行业收入变现与市场占有。在这里，你将直面超大规模流量与复杂业务场景的技术挑战，深度应用业界领先的商业模型与算法技术，投身面向未来的数字营销能力建设，持续探索前沿技术。\n\n1、构建高质量短剧和游戏多模态推理及细粒度数据集，通过数据合成技术不断优化数据质量与丰富度，沉淀短剧和游戏行业高价值信息；\n2、针对业务需求对内容消费行业多模态大模型进行后训练，包括CPT、SFT、RLVR、多轮Agent RL，提升模型能力；\n3、结合业务场景设计搭建Agent架构，探索Agent Test-Time-Scaling技术；\n4、通过大模型不断优化针对短剧和游戏内容的理解和生成能力，包括：视频内容理解、用户兴趣挖掘、漫剧内容生产、引流视频剪辑和游戏Agent/AI coding等。","requirements":"1、2027届获得本科及以上学历，计算机、机器学习等相关背景优先；\n2、在NLP算法、多模态算法、大模型训练和应用、知识图谱等领域有实际的开发和实习经验者优先；\n3、思维开阔，具备优秀的逻辑思考能力，面对挑战性问题充满热情，具有良好的团队合作、沟通协调能力，执行力和自驱力强；\n4、学习能力强，对AI前沿技术持续关注，能够洞察技术和业务的结合点。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669705874123262213","sourceKey":"bytedance","company":"字节跳动","title":"推理优化工程师 - 抖音直播","city":"北京/深圳","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669705874123262213/detail","duty":"团队介绍：直播团队负责为抖音集团旗下产品提供直播服务。团队负责直播平台技术和直播业务研发，打造灵活稳定的直播服务平台，为用户提供优质直播体验，支持电商、本地生活、游戏、节目、多人互动等不同类型的业务场景。直播业务发展迅猛，处于行业头部地位，业务发展空间巨大。现在加入我们，和优秀的人一起做有挑战的事，你的技术与创意将影响亿级用户，激发创意和丰富生活。\n\n1、负责抖音AI分身数字人的多模态理解、数字人生成算法的训练、推理技术优化，与算法Co-Design提升实时互动模型的效果与性能上限；\n2、负责抖音AI分身数字人相关模型的规模部署，支撑Multi Agent、多模态的交互探索和效果迭代，打造下一代直播实时互动能力。","requirements":"1、2027届获得本科及以上学历，计算机及相关专业优先；\n2、精通Python/Go等编程语言之一，熟悉CUDA编程，具备优秀的开发调试能力，熟悉Triton、CUTLASS、有算子库开发经验者优先；掌握多机多卡通信机制与并行策略；\n3、熟悉大模型训练/推理相关技术，对训推主流框架有实际开发和应用落地经验，如Megatron、DeepSpeed、vLLM、TRT-LLM等；\n4、对大模型有强烈的好奇心和自驱学习力，具备良好的沟通协作能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668698983221119237","sourceKey":"bytedance","company":"字节跳动","title":"大模型应用算法工程师（AI Agent方向） - Commercial AI","city":"北京/上海","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668698983221119237/detail","duty":"团队介绍：Commercial AI 负责中国交易与广告的to B应用统一模型建设，包含基础模型能力、AI Infra、统一商业数据、评测等方向。\n\n1、作为广告商家服务方向的大模型算法团队成员，致力于打造面向广告主的下一代AI经营成长伙伴；负责Agent和模型的研发与落地，服务于在字节跳动平台经营和投广的商家，覆盖电商、本地生活、游戏、短剧等多个行业及独立App/平台Web/抖音私信/微信/电话外呼等多个场景；需实现商家问题解答、经营状态理解、问题诊断、工具调用、长程任务完成及商家提案说服等功能；聚焦模型经营和投广专家级能力打造，包括理解、推理、多轮沟通、行动引导和持续学习能力，通过长程对话帮助商家提升经营效果，为平台创造可衡量的商业价值；\n2、调研并应用前沿的大规模模型高效训练/推理方案，包括但不限于极致优化SFT、RM、RLHF等技术；\n3、聚焦LLM的Post-training技术，以及RL与LLM-based Agent相结合的交叉研究与应用落地。","requirements":"1、2027届获得本科及以上学历，机器学习、人工智能、数理统计等相关专业背景优先；\n2、熟悉大模型的相关基础知识，具备大语言模型相关训练或推理的基础知识；\n3、熟悉LLM Post-training技术，例如SFT/RLHF的常用方法；熟悉Agent领域，了解Agentic RL的常见方法；\n4、具备代码工程能力、数据结构和基础算法功底，熟练掌握Python等编程语言，熟悉常用AI工具；\n5、具备激情与探索精神，乐于了解业务知识，拥有良好的团队合作意识、沟通能力及独立解决问题的能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668576797001664821","sourceKey":"bytedance","company":"字节跳动","title":"策略产品经理 - 抖音生活服务","city":"北京/上海/成都","category":"产品经理","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668576797001664821/detail","duty":"团队介绍：抖音生活服务依托抖音POI （Point of Interest）、短视频、直播、搜索等，以“激发线下生意，丰富美好生活”为使命，致力于成为最值得信赖的生活服务平台，为用户提供更丰富、独特的生活体验，为合作伙伴提供包容且公平的健康营商生态。截至2025年底，抖音生活服务业务已覆盖400+城市，超过1500万家动销门店。抖音生活服务将继续携手生态伙伴，为用户提供值得心动的商品和服务。\n\n1、负责抖音生活服务内容流量策略迭代，包括策略制定、实验设计和数据分析；\n2、基于本地生活的差异化，与算法、运营、各协作方优化推荐策略，持续提升内容生态的健康度，提升抖音用户内容消费体验，牵引作者在抖音内规范经营、闭环经营；\n3、深入调研作者的经营难题与经营逻辑，数据拆解经营中的流量问题与增益，通过推荐策略帮助作者度量经营收益，精细化提升经营效果；\n4、洞察用户的核心诉求，给出科学的策略优化预期目标与衡量指标，与算法团队高效协同，完成目标拆解、策略验证；\n5、深入理解并探索行业自然流量与商业流量协同的经营方法，与内外部团队紧密协作，打造经营的第一阵地。","requirements":"1、2027届获得本科及以上学历；\n2、具有一定的产品调研能力和数据分析能力；\n3、具有良好的沟通协调能力，责任心强，踏实敬业，逻辑清晰；\n4、有生活服务或策略产品相关实习经历者优先考虑。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668321648775022853","sourceKey":"bytedance","company":"字节跳动","title":"多模态算法工程师 - TikTok算法","city":"北京/上海","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668321648775022853/detail","duty":"团队介绍：TikTok搜推算法团队，负责TikTok短视频产品的基础推荐、搜索算法，加入我们，你能接触到包括搜索、用户增长、社交、直播、内容创造、内容消费等核心业务场景，直接为核心用户体验负责，支持产品在全球赛道上高速发展。我们的工作内容包括大规模推荐算法的优化、复杂约束的优化问题的解决、多模态大模型的落地，并着力研究下一代AI Search和Chatbot的核心研发技术，包括不限于Multi-Agent、Agentic RL、Harness、Loop Engineering，探索强化学习在大模型时代的新范式。在这里，你可以深入钻研机器学习算法的改进和优化，探索前沿的技术；可以感受不同文化的碰撞，激发认知；可以通过对产品和内容生态的深度分析，影响产品未来的发展方向。\n\n1、探索下一代大模型推荐范式的技术突破，负责攻坚LLM4Rec与Agentic Rec技术架构，推动其在直播推荐场景的规模化落地，驱动指标的跨越式增长；\n2、打造具备强语义理解、信息无损与全模态能力的表征大模型，探索前沿的语义ID化技术并形成突破，实现在直播复杂、实时变化场景下的内容精准表征；\n3、推进大模型在推荐以及安全治理等场景的深度应用，探索业务后训练，强化学习，Agent系统等技术方案来重塑各个业务链路，驱动治理效率以及业务指标的突破；\n4、主导直播场景下基座大模型的技术建设，包括高质量数据管道建设、预训练（CPT)、强化学习以及全模态等方向的探索，打造支持推荐与治理的统一基座；\n5、持续跟踪并探索前沿技术，紧贴直播业务场景定义研究方向，沉淀并推动团队技术迭代。","requirements":"1、2027届获得硕士及以上学位，计算机等相关专业优先；\n2、掌握多模态理解相关的技术与应用经验，熟悉主流大模型的结构与训练框架，持续跟踪相关领域的最新进展；\n3、有业务激情，责任心强，积极主动，有良好的沟通能力和团队合作能力；\n4、有想象力和独立思考能力，具备出色的实验分析与问题解决能力，能够提出想法并能付诸实践验证；\n5、在多模态或者大模型方向，主导过项目或者发表过高水平论文者（NeurIPS、CVPR、ICCV、ICML等）优先；\n6、具备内容理解在推荐搜索或者安全治理场景端到端的落地经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668280556798839093","sourceKey":"bytedance","company":"字节跳动","title":"抖音反欺诈治理策略 - 抖音社区治理","city":"北京","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668280556798839093/detail","duty":"团队介绍：抖音致力于打造一个开放、积极、多元、友善的平台，鼓励表达、沟通和记录，激发创造，丰富人们的精神世界，让现实生活更美好。我们通过AI算法驱动的个性化推荐与智能创作工具，满足用户表达、学习、娱乐、社交、消费等需求。回顾抖音一路走来的历程，我们在帮助亿万用户记录美好生活的过程中，努力变得更好。抖音社区治理团队负责抖音的社区治理工作，包括视频、直播等多体裁的内容治理，以及安全产品中台能力建设。\n\n1、负责抖音社区反诈治理相关工作，分析黑产作弊链路，从全链路发现风险信号特征，并应用于线上防控策略迭代；\n2、独立为具体业务场景和风险场景负责，能够联动算法、研发、审核、运营团队落地治理方案，共同为结果负责；\n3、了解抖音App产品功能，对业务规模及用户转化等数据有敏锐的洞察力，能基于数据做出风险判断；\n4、持续挖掘黑灰产新增欺诈手法，迭代Agent识别逻辑与对抗策略，推进自动化研判、处置、复盘的治理体系升级。","requirements":"1、2027届获得本科及以上学历，计算机/信息安全/统计学/数学及相关专业优先；\n2、有技术背景优先，有反诈相关领域工作经验优先，具有较强的数据分析能力和逻辑判断能力，目标导向；\n3、拥有强烈的责任心和团队合作精神，出色的学习能力；\n4、具备强烈的好奇心和自我驱动力，喜欢接受挑战。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667889560824154373","sourceKey":"bytedance","company":"字节跳动","title":"评测产品经理 - AI Platform","city":"上海/深圳","category":"产品经理","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667889560824154373/detail","duty":"团队介绍：AI Platform 团队，隶属于产品研发和工程架构部门。面向公司内部各业务线，建设统一的AI 应用基础设施和工程平台，帮助业务高效、稳定地落地大模型应用，加速 AI 产品创新。\n在平台产品侧，团队打造了新一代AgentOps平台，提供 Prompt Engineering、Agent观测、评测、数据处理、模型微调等 Agent 全生命周期解决方案，帮助Agent开发者构建效果调优的数据飞轮。产品也已成功推出商业化版本。\nAI Platform 团队还持续孵化多种面向内部与外部场景的AI应用创新产品，积极探索大模型应用的技术发展。团队氛围好，发展空间大，欢迎加入！\n\n1、负责LLM大模型AgentOps平台相关的评测产品规划和设计，包括需求调研、用户场景分析、行业趋势研究、产品设计与优化等；\n2、与应用开发者、社区紧密沟通，深入理解用户需求和市场动态，设计具有竞争力的AI产品方案；\n3、与研发团队保持紧密合作，协调组织设计、开发、测试资源，推动产品发布和项目落地。","requirements":"1、2027届获得本科及以上学历，计算机、人工智能、软件工程、数据科学等相关专业背景优先；\n2、具备一定的技术理解能力，对大语言模型技术有浓厚兴趣；\n3、具备优秀的逻辑思维能力、自主学习意识和跨部门沟通协调能力；\n4、对AI技术及其应用场景有浓厚的兴趣、敏锐的洞察力，具备快速理解和掌握新技术的能力；\n5、具有AI评测产品经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667772793693473029","sourceKey":"bytedance","company":"字节跳动","title":"云与AI解决方案架构师 - 火山引擎","city":"上海/成都","category":"产品","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667772793693473029/detail","duty":"团队介绍：火山引擎是字节跳动旗下云和AI服务平台，将字节跳动快速发展过程中积累的增长方法、技术能力和应用工具开放给外部企业，通过云和AI技术，推进企业智能化转型，激发增长潜能。\n\n1、面向公有云场景，与销售、BD、产品研发等部门紧密协同，跟进行业重点客户，推动标准产品或解决方案在客户侧落地；\n2、为字节跳动内外部客户提供业务和技术层面的架构咨询服务，理解合作伙伴及客户的业务和功能性需求、非功能性需求、性能和可靠性需求，提供基于火山引擎产品体系的架构设计方案，支持客户或合作伙伴成功地在火山引擎产品上构建上层应用系统和服务；\n3、通过对客户业务的深入理解和分析，提炼客户的终极诉求，结合公司产品和技术能力，沉淀行业细分方向的GTM方法论，树立行业标杆案例和典型场景价值案例。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程、AI大模型等相关专业优先；\n2、具备良好的沟通表达能力与逻辑思维；\n3、主动投身云服务、大数据、人工智能等领域的技术革新，具备快速学习能力与市场洞察力。\n\n【加分项】\n1、在校期间担任学生干部、组织过校级项目并担任负责人；\n2、有企业解决方案或架构设计实习经验，对云原生应用架构/大数据和人工智能架构/视频云有一定了解。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7666037605550573829","sourceKey":"bytedance","company":"字节跳动","title":"安全工程师 - 安全与风控","city":"北京","category":"安全","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7666037605550573829/detail","duty":"团队介绍：我们团队为字节跳动旗下各类业务线提供信息安全保障。通过与各业务团队紧密协作，我们针对其特定的运营及业务需求，设计并落地专属安全策略。依托安全部门的专业能力，我们交付与业务目标高度契合、兼具成本效益与可扩展性的安全解决方案，助力各团队获取最高效、最可靠的安全服务与工具。\n\n1、参与业务需求的安全设计与风险评估，指出方案设计中的网络、应用、数据等方向的安全问题，主动挖掘和分析潜在安全风险，提供最佳安全解决方案并推动落地；\n2、推动业务线网络安全、应用安全、数据安全等方向的风险治理，提升治理效率和完成率，减小风险暴露面；\n3、参与制定适用业务的安全策略、标准及规范，并根据业务发展和技术变革进行动态优化与更新；\n4、参与业务信息安全应急响应体系的建设与优化，协调资源对安全事件开展调查、分析和处置；\n5、持续跟进安全平台、安全工具的功能开发、能力优化和日常运营，利用自动化能力持续提升安全检测和响应的效率。","requirements":"1、2027届获得本科及以上学历，信息安全、网络安全、计算机科学相关专业；\n2、掌握网络安全、应用安全、数据安全中某一方向的相关安全技术，如常见防火墙配置、常见Web漏洞挖掘、常见加解密原理等；\n3、以下一种或几种语言，Java/Python/Go/Node/C++等，具备一定的代码阅读和分析能力；\n4、具备较强的逻辑思维能力、团队合作意识和自驱力，能够快速协调业务线资源完成风险治理和项目落地；\n5、了解SDL相关流程，了解SAST，DAST，IAST等自动化工具的原理和使用者优先考虑；\n6、了解数据安全生命周期、各生命周期数据安全风险点、金融行业或有相关实习经历者优先考虑。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7666037078211332405","sourceKey":"bytedance","company":"字节跳动","title":"安全攻防工程师 - 安全与风控","city":"北京","category":"安全","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7666037078211332405/detail","duty":"团队介绍：我们团队为字节跳动旗下各类业务线提供信息安全保障。通过与各业务团队紧密协作，我们针对其特定的运营及业务需求，设计并落地专属安全策略。依托安全部门的专业能力，我们交付与业务目标高度契合、兼具成本效益与可扩展性的安全解决方案，助力各团队获取最高效、最可靠的安全服务与工具。\n\n1、识别业务安全风险，挖掘业务安全需求，统一推进风险治理；\n2、推动集团安全要求及工具在业务线落地，提供相关技术支持与培训；\n3、制定安全解决方案，满足业务线在应用安全、数据安全、合规和隐私保护等方面的保障需求。","requirements":"1、2027届获得本科及以上学历，信息安全、计算机、通信相关专业优先；\n2、对信息安全理论知识有较为全面的掌握，包括网络安全、系统安全、应用安全、数据安全等，深入了解其中至少一个领域；\n3、缜密的逻辑思考与分析能力；\n4、良好的跨团队协作能力、推动力、沟通能力、自我驱动力；\n5、有强烈的项目责任意识和高度的责任心。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7665328677891180853","sourceKey":"bytedance","company":"字节跳动","title":"基础技术AI原生后端开发工程师 - AI算力基础设施","city":"上海","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7665328677891180853/detail","duty":"团队介绍：字节跳动基础设施部门，负责字节跳动的全栈算力基础设施，从芯片服务器产研、到超大规模数据中心，到传统云平台和如今的AI Native Cloud，全方位为抖音、豆包、今日头条、飞书、火山引擎等各类产品提供领先、稳定的百万量级大规模算力基础设施服务。我们的领域涵盖数据中心建设、内核操作系统开发、服务器集群管理、高速网络通信、EB级数据存储体系、搜索型数据库探索、基于LLM的AI基础设施的研发调度与治理等，致力于打造业界领先的、面向LLM的AI云原生基础设施架构与产品矩阵。\n\n1、负责字节跳动云原生计算底座，支持字节跳动大模型训练推理以及抖音等业务线推荐、广告、搜索等训推场景集群管理与调度工作，同时支持集团整体的通用计算业务；\n2、负责字节跳动GPU集群统一调度系统的设计与实现，优化大规模AI训练与推理场景的资源分配效率；参与训练推理场景的分布式计算框架设计与实现；\n3、负责字节跳动Agent Runtime底层系统开发，探索极致轻量级虚拟化、高密度容器等前沿技术；\n4、支撑基于DPU的软硬一体架构计算基础设施设计与开发；\n5、负责基础设施的智能化运维，用Agent方式重构基础设施系统的设计、开发、运维流程，提升基础设施系统的自动化与智能化水平；参与超大规模基础设施的可用性和稳定性保障。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程等相关专业优先；\n2、相关专业PhD优先，热爱计算机科学和技术，熟练掌握至少一门编程语言（C++、Go、Rust、Python等）；\n3、具备良好的系统化问题分析能力，能够主动发现并解决问题；\n\n加分项：\n1、有容器、Kubernetes、调度器、分布式计算、并行计算相关项目经历；\n2、有GPU编程、CUDA、高速网络或异构计算相关经验；\n3、对大模型训练推理架构有了解；\n4、有AI Agent、LLM应用开发经验。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7664555422581852421","sourceKey":"bytedance","company":"字节跳动","title":"计算平台开发工程师 - 音视频技术","city":"北京/杭州","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7664555422581852421/detail","duty":"团队介绍：视频与边缘部门承载了字节跳动的媒体内容分发基建及技术中台，支持了字节跳动全系产品，如抖音、今日头条、番茄小说、西瓜视频等APP的点播、直播、实时通信、图片等多媒体业务发展，同时将业务发展过程中沉淀下来的技术能力和工具，通过火山引擎对外输出，面向各行各业用户提供视频云产品和服务，愿景是为内外部业务伙伴提供最低成本、最优画质、最低延时、最安全可靠的富媒体内容分发解决方案，助力业务伙伴降本提效实现持续增长。\n\n1、负责字节跳动视频中台的高性能计算平台的业务开发和技术架构；\n2、构建稳定支撑海量多媒体处理业务的业界领先的计算系统，包括但不限于云原生计算框架、函数计算、分布式调度、FaaS/Serverless，集群管控，异构资源（GPU/ARM/FPGA等）；\n3、基于多IDC构建边缘计算网络，提供无边界全球计算能力支持；\n4、用户需求驱动，追踪业界趋势，利用技术推动业务的成长。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程、网络工程等相关专业优先；\n2、热爱计算机科学和技术，掌握扎实的计算机基础知识，深入理解算法、数据结构、操作系统等基础知识扎实，优秀的逻辑思维能力；\n3、精通主流语言的至少一门Go/C++/Python等；\n4、有强烈的求知欲和工作责任心，优秀的学习和沟通能力、自驱力和执行力；\n5、有良好的工作文档习惯，及时按要求撰写更新工作流程及技术文档；\n6、有云计算系统设计和开发经验，了解/熟悉容器、lambda、Serverless、K8s、GPU等相关技术。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7664496776372242693","sourceKey":"bytedance","company":"字节跳动","title":"AI Infra研发实习生 - 存储","city":"北京","category":"基础架构","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7664496776372242693/detail","duty":"团队介绍：字节跳动基础设施存储团队，为字节跳动全系产品提供存储服务，对外打造火山引擎公有云存储产品体系，在AI时代深度支撑豆包大模型和方舟大模型平台。我们根植字节跳动最佳技术实践，以数十万台服务器规模和百EB 级数据稳定存储的企业服务经验，通过火山引擎丰富的存储产品矩阵对外赋能。我们积极探索业界顶尖的技术，从底层硬件构造到数据治理和上层应用加速，致力于构建业界领先的云存储服务，释放海量数据的无限价值。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、参与AI框架与分布式存储的适配层开发，实现Tensor、Checkpoint等AI数据结构的高效存储与读取，支撑大模型训推场景；\n2、参与多介质存储调度策略研发，优化DRAM、NVMe等介质的分层存储，平衡AI场景的性能与成本；\n3、参与EIC、CFS等分布式存储产品的AI场景功能迭代，提升万卡级集群下的IO性能与可靠性；\n4、参与存算协同技术研发，探索GDR、NVMe-oF等技术在AI场景的应用，优化数据在GPU与存储间的流转效率。","requirements":"1、本科及以上学历在读，计算机、软件工程等相关专业优先；\n2、熟练掌握至少一门编程语言，包括但不限于：C/C++、Python、Golang等；\n3、掌握扎实的计算机基础知识，深入理解数据结构、算法和操作系统知识；\n4、了解分布式系统核心概念，有分布式存储或AI框架相关项目经验优先；对大模型训推流程有一定了解，有AI Infra相关经验优先；\n5、有优秀的逻辑分析能力，能够对业务逻辑进行合理的抽象和拆分；\n6、有强烈的求知欲，优秀的学习和沟通能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7599562381458983221","sourceKey":"bytedance","company":"字节跳动","title":"数字人算法实习生-智能创作","city":"杭州","category":"计算机视觉","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7599562381458983221/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：智能创作团队是字节跳动的创作场景业务中台，以AI赋能创造，致力于通过AI技术降低创作门槛，赋能视觉内容生产与创作的智能化升级。团队深度支持抖音、剪映、即梦、豆包、商业化等多个业务线，持续深耕图片与视频生成、智能剪辑、数字人、特效等多个业务场景，通过由AI驱动的智能化工具与算法，为用户提供了更智能、更便捷、更丰富的创作体验，助力普通用户轻松实现高质量内容创作，同时为专业创作者提供强大的技术支持，推动内容生态的繁荣与创新。\n\n1、负责2D/3D数字人、人体、服饰、口型、AI模特、商品等相关计算机视觉前沿技术的探索和研究；\n2、负责图像/视频换装、实时视频生成、多模态数字人互动等相关计算机视觉前沿技术的探索和研究；\n3、参与和推动上述相关技术在抖音、剪映等产品线的落地。","requirements":"1、2027届硕士及以上学位在读，数学、计算机、电子、自动化、软件工程等相关专业优先；\n2、良好的数学和算法基础；\n3、熟悉C++或Python，具有较强的代码开发能力；\n4、在相关国际顶尖会议或期刊上发表过论文者优先；\n5、在数字人、人体/手3D重建和驱动、AR试穿试戴、服饰商品理解、Virtual Tryon等方向有研究经验者优先；\n6、对VAE、扩散/AR模型、实时生成、模型蒸馏、多模态等方向有研究经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7595626050760804661","sourceKey":"bytedance","company":"字节跳动","title":"音频算法实习生-抖音","city":"上海","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7595626050760804661/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：Data-抖音团队，负责抖音APP的推荐算法、AI大模型应用、内容算法、智能对话等算法工作，对接全链路各体裁（短视频，直播，图文）各业务（内容消费，UGC，打赏，社交，生态，投稿，消息，汽水音乐，精选，增长投放，评论，内容理解&安全、智能对话等）。我们的工作涉及大规模推荐算法的优化、复杂约束的优化问题的解决、内容理解、LLM技术技术研究、AI落地应用以及新业务方向探索、CV/NLP等多个学术领域的算法改进工作、对多种场景的推荐架构的设计和实现和对产品数据的复杂深入的分析工作。在这里，你可以深入钻研机器学习算法的改进和优化，探索工业界最领先的推荐系统架构和推荐大模型算法、可以通过使用最新的大模型等技术支持抖音的数字人、智能客服、AI工具等创新探索；可以通过对产品的深度理解和思考，将算法应用到业务中去；也可以通过对产品和内容生态的深度分析，影响产品未来的发展方向。\n\n1、承担抖音内多元语音交互场景中的语音模型需求，涵盖抖音AI分身音视频对话、客服热线、VOIP场景下的相关音频算法研发工作；包括对语音识别、合成、对话理解等模型展开针对性训练与优化，全力提升对话效果及语音合成稳定性和表现力；\n2、深入探索端到端语音大模型的落地与优化举措，致力于降低语音交互延时，显著提升语音对话品质；同时，专注于语音合成/音频AI生成相关算法模型的研发与精进，跟进语音领域前沿技术研究，负责音频表征模型、Seq2Seq底膜的研发优化；\n3、紧密跟踪研发业界先进的音频技术进展，积极探索语音/音频领域最新技术，并推动其成功落地于抖音产品之中。","requirements":"1、2027届本科及以上学历在读，计算机、软件工程、人工智能、数学等相关专业优先；\n2、对语音识别、合成、对话理解等技术具备扎实的理论根基，熟悉端到端语音大模型原理和架构；熟悉LLM-based/Diffusion-based音频合成原理，有相关模型经验者优先；\n3、拥有扎实的编码能力，能够熟练运用相关机器学习框架和工程框架；\n4、在国际会议或期刊发表论文者优先，包括但不限于ICASSP、INTERSPEECH等。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7589516329644853557","sourceKey":"bytedance","company":"字节跳动","title":"推荐算法实习生-抖音","city":"上海","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7589516329644853557/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：Data-抖音团队，负责抖音APP的推荐算法、AI大模型应用、内容算法、智能对话等算法工作，对接全链路各体裁（短视频，直播，图文）各业务（内容消费，UGC，打赏，社交，生态，投稿，消息，汽水音乐，精选，增长投放，评论，内容理解&安全、智能对话等）。我们的工作涉及大规模推荐算法的优化、复杂约束的优化问题的解决、内容理解、LLM技术技术研究、AI落地应用以及新业务方向探索、CV/NLP等多个学术领域的算法改进工作、对多种场景的推荐架构的设计和实现和对产品数据的复杂深入的分析工作。在这里，你可以深入钻研机器学习算法的改进和优化，探索工业界最领先的推荐系统架构和推荐大模型算法、可以通过使用最新的大模型等技术支持抖音的数字人、智能客服、AI工具等创新探索；可以通过对产品的深度理解和思考，将算法应用到业务中去；也可以通过对产品和内容生态的深度分析，影响产品未来的发展方向。\n\n1、负责抖音APP产品的算法工作，共同搭建业界领先的推荐系统、内容理解系统，为用户提供一流的产品体验；\n2、深入理解业务和机器学习技术，优化模型&策略，持续提升推荐效果；\n3、深入理解用户行为，结合数据挖掘等技术，优化用户创作和浏览等体验；\n4、在抖音各个业务场景应用内容算法，改进内容社区的运行效率，支持下游的算法和产品需求；\n5、和产品、运营团队紧密合作，通过对产品和用户的深入理解和分析，制定算法策略促进抖音生态的长期繁荣发展。","requirements":"1、2027届本科及以上学历在读，计算机、软件工程等相关专业优先；\n2、具备优秀的编码能力，扎实的数据结构和算法功底；\n3、对推荐算法和机器学习有热情、乐于学习、思考和创新；\n4、优秀的分析问题和解决问题的能力，有良好的沟通表达能力和团队精神；\n5、熟悉机器学习、自然语言处理、数据挖掘中一项或多项，对推荐系统、计算广告、搜索引擎、CV、NLP、语音、LLM、AIGC等相关领域有经验者优先；\n6、每周可实习4天以上，实习时间3个月以上。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7480517459352193298","sourceKey":"bytedance","company":"字节跳动","title":"计算语言学（翻译/同传方向）实习生 - Data语音","city":"北京","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7480517459352193298/detail","duty":"团队介绍：Data-语音团队致力于语音、音乐等大模型AIGC技术的研发和产品创新，我们的使命是通过多模态AIGC音频技术赋能内容创作和语音交互，让内容生产、消费与互动变得更加简单、沉浸、多元化。当前团队已有成熟的大模型语音合成、语音理解、音乐生成等多模态音频技术，并持续迭代大模型端到端语音交互方案等，一方面通过中台形式服务于公司众多业务线，例如豆包/Dola、抖音/TikTok、剪映/CapCut、番茄小说、海绵音乐等产品；另一方面，团队已经通过字节跳动旗下的火山引擎开放平台-语音技术和火山方舟平台，向众多企业开放技术成熟稳定的能力和服务。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、参与业内前沿的同传（同声传译）大模型项目，深入了解大型语言模型的策略迭代过程，协助完成数据标注和模型评测的落地实施；\n2、参与同传大模型的策略迭代：协助收集和分析市场需求，参与制定同传大模型的产品策略和迭代计划；跟进产品开发、测试进度，与算法与工程技术团队合作，确保产品功能按时高质量交付；关注各场景的用户反馈，分析线上产品模型输出效果表现，分析后提出优化迭代方案；\n3、模型数据标注支持：协助制定数据标注方案，确保数据符合模型训练要求；与内部标注团队沟通，跟进标注进度，保证数据质量；协助优化数据标注流程，提高效率和质量；\n4、模型评测落地：参与设计模型评测标准和评测方法，确保评测过程客观、公正、全面；组织和实施模型评测，收集评测数据和结果；分析评测结果，与技术团队讨论，推动模型优化提升。","requirements":"1、本科及以上学历在读，翻译、小语种、语言学等相关专业优先；\n2、对人工智能、大语言模型、自然语言处理有相关经验或兴趣者优先；\n3、有翻译理论基础，或参与口笔译相关经验者优先；\n4、具备基本的数据分析能力，熟练使用Excel、Python等工具者优先；\n5、英文方向有CATTI口/笔译二级及以上证书者优先；小语种方向（法语、德语、西语、阿语、意大利语、越南语等）有相关小语种能力证书或证明者优先；\n6、每周出勤至少4天，能够长期实习者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7685951361649772805","sourceKey":"bytedance","company":"字节跳动","title":"游戏角色原画实习生 - ZERO36工作室","city":"上海","category":"游戏美术","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7685951361649772805/detail","duty":"团队介绍：ZERO36工作室旗下有《航海王热血航线》、《花亦山心之月》、《初音未来：缤纷舞台》多款游戏产品。\nZERO，是从0开始，是不念过往，不畏将来；是回到原点，对知识诚实；是一切开始的基础。\n36，如果加上°C，即为人体的温度，戒骄戒躁保持初衷，用\"温度\"拉齐大家的目标和价值观，做有温度的产品，有温度的运营，成为一个有温度的团队，欢迎加入我们！\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、根据文案描述，提炼需求，绘制相应角色，协助制作完成包括但不限于角色立绘、服装道具等；\n2、根据剧情描述，协助设计相关镜头，绘制氛围插画；\n3、配合上下游环节，协助制作相应的角色原画素材。","requirements":"1、本科及以上学历在读，艺术类等相关专业优先；\n2、有相关游戏开发实习或项目经验者优先，熟练掌握PS等绘图软件，学习能力强，能配合完成基础设计辅助工作；\n3、热爱游戏，女性向游戏玩家优先，理解女性向审美；\n4、审美优秀，有良好的镜头感和画面叙事能力，逻辑清晰，沟通顺畅，执行力强，能快速上手基础工作；\n5、投递简历需附带个人作品（作品类型不限，能展示设计能力即可）。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7681274434498103605","sourceKey":"bytedance","company":"字节跳动","title":"商业分析实习生 - 抖音电商","city":"上海","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7681274434498103605/detail","duty":"团队介绍：抖音电商以“总能发现好东西”为主张，致力于成为用户发现丰富好物的首选平台。众多抖音创作者通过短视频、直播、商城等丰富的形式，给用户提供更个性化、更生动、更高效的消费体验。同时，抖音电商积极引入优质合作伙伴，为商家变现提供多元的选择。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、协助策略团队开展经营分析、数据研究工作：包括但不限于电商履约时效数据拆解分析、行业趋势分析、产业带研究、数据收集整理与解读、业务指标下钻分析等；\n2、结合对市场营销、电商生态的理解，深度参与业务执行工作：包括但不限于协助电商商家端沟通、协助部门进行信息梳理、项目跟进和其他日常运营；\n3、基于对业务全貌、电商活动玩法的深入了解，与策略、运营、市场等团队并肩作战，共同推动重点业务开展；\n4、深度支持并协同履约运营团队，保证履约质量和时效服务体验。","requirements":"1、本科及以上学历在读；\n2、有相关行业研究、数据分析、市场营销的实习经验优先；\n3、有基础的数据分析、数据整理能力，能使用SQL、Python、Tableau、Excel优先；\n4、有扎实的项目管理能力，包括跨团队协作和沟通、信息整理汇总、结构化的提炼总结、清晰有逻辑的表达和写作；\n5、拥有较强的逻辑思维能力、自驱力和主动性，以及良好的团队沟通和合作能力，喜欢富有挑战性的工作，工作激情饱满。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7678967047988758837","sourceKey":"bytedance","company":"字节跳动","title":"策略运营实习生 - TikTok Shop","city":"上海","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7678967047988758837/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商。平台汇聚全球优质商家与创作者，通过短视频、直播等多场景连接消费者，让新奇好物畅销全球，让美好生活触手可得。目前团队分布在美国、英国、法国、印尼、墨西哥、中国等全球多个国家和地区，在这里你将有机会深入国际业务场景，面向全世界商家及用户，和跨区域团队协作，共同探索创新购物模式。期待和优秀的你一起创造更多可能！\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、协助团队开展数据处理、分析、测算等工作，通过数据分析产出场域及玩法业务洞察和业务策略；\n2、搭建场域及玩法分析框架、看板，协助一线国家运营完善数据监控，产出运营优化建议，协助监控执行落地细节等工作；\n3、支持电商场域运营分析、电商玩法策略分析、市场场域及玩法调研分析等专项研究；\n4、支持电商平台活动，项目协同和项目流程管理工作。","requirements":"1、本科及以上学历在读；\n2、有扎实数据处理能力；\n3、有电商运营、直播运营、玩法运营、产品运营、咨询/战略/商业分析等实习经验优先；\n4、英语可作为工作语言，实习期在3个月及以上。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669705537843382581","sourceKey":"bytedance","company":"字节跳动","title":"大模型训练系统工程师 - 火山方舟","city":"杭州/北京/上海","category":"机器学习","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669705537843382581/detail","duty":"团队介绍：火山方舟是火山引擎推出的一站式大模型服务平台，是中国大模型市场产品和份额领跑者。平台提供模型推理、评测、精调等全流程服务。方舟搭载了豆包及业界主流大模型，提供丰富的插件生态和AI应用开发服务，并通过稳定可靠的安全互信方案、专业的算法技术服务，全方位保障企业级AI应用落地。\n\n1、参与方舟训练系统研发，支持内外用户以Serverless形式使用方舟平台进行模型后训练（SFT、RL）；\n2、针对方舟复杂多租户训练场景设计弹性训练方案，支持在多机房多异构硬件下开展多租户混合训练，优化训练吞吐和稳定性；\n3、设计强化学习系统，提升训练效率，并打造用户友好的强化学习训练接口。","requirements":"1、2027届获得本科及以上学历，计算机相关专业优先；\n2、熟练掌握Python、Rust、C++等一门或多门编程语言，编程风格良好，有框架设计和抽象能力；\n3、有训练框架设计或训练系统优化经验，参与过大模型训练工程或复杂分布式系统开发；\n4、乐于追踪和解决问题，喜欢钻研底层原理与性能瓶颈，擅长科学建模。\n\n加分项\n1、有扎实的体系结构优化经验，熟悉异构硬件、高性能网络特性；\n2、有科学优化的能力，能自主分析训练效率，并确定优化方向；\n3、对主流强化学习框架有了解，对于训练框架有技术见解与insight。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669690089723889973","sourceKey":"bytedance","company":"字节跳动","title":"渠道销售（全域经营） - 商业化","city":"北京/上海/广州/杭州","category":"销售","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669690089723889973/detail","duty":"团队介绍：抖音集团商业化是抖音集团旗下的综合数字化营销服务平台，致力于让不分行业、地域的企业及个体都能通过数字化技术激发创造、驱动生意，实现商业的可持续增长。\n\n1、负责巨量引擎渠道生态建设，结合公司产品优势，通过内容生态和精准营销，助力代理商合作伙伴生意增长；\n2、根据公司渠道战略方向，帮助代理商合作伙伴进行生意的诊断与分析，为代理商提供专业的数字营销解决方案，促进目标的达成和生意的长效发展；\n3、研究广告主需求及行业数据，提炼、沉淀、优化方法论，深入理解广告产品营销体系，进行定期培训和指导，参与产品或策略规划与执行，加强业务合作伙伴的服务能力；\n4、深入洞察并掌握市场、行业、政策动态，敏锐分析，不断提升和迭代业务合作的模式和机制，提升效率的同时把控风险，保障生意健康可持续发展。","requirements":"1、2027届获得本科及以上学历；\n2、热爱广告行业，对市场、行业、营销产品具有敏锐洞察力，具有逻辑化与多元化的思维；\n3、具有自驱动力、执行力，以及强烈的好奇心与求知欲，具有出色的沟通能力和协调能力；\n4、性格开朗，为人正直，责任心强，擅长多任务、跨部门的协同与推进。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669439289629247749","sourceKey":"bytedance","company":"字节跳动","title":"AI研发工程师（AI Music） - TikTok研发","city":"上海","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669439289629247749/detail","duty":"团队介绍：TikTok研发团队，旨在实现TikTok业务的研发工作，搭建及维护业界领先的产品。加入我们，你能接触到包括用户增长、社交、直播、电商C端、内容创造、内容消费等核心业务场景，支持产品在全球赛道上高速发展；也能接触到包括服务架构、基础技术等方向上的技术挑战，保障业务持续高质量、高效率、且安全地为用户服务；同时还能为不同业务场景提供全面的技术解决方案，优化各项产品指标及用户体验。 \n在这里， 有大牛带队与大家一同不断探索前沿， 突破想象空间。 在这里，你的每一行代码都将服务亿万用户。在这里，团队专业且纯粹，合作氛围平等且轻松。目前在北京，上海，杭州、广州、深圳分别开放多个岗位机会。\n\n1、负责音乐业务场景下的业务研发，包括旗下音乐发行平台SoundOn的业务迭代和端内音乐宣传推广和消费指标提升和优化；\n2、服务端系统的架构设计与实现，保障业务在高速发展中的架构稳定和可靠性，解决超高流量带来的分布式技术问题；\n3、与多个跨职能团队合作，在快速产品开发中提供高质量的工作；\n4、负责调研业界前沿技术，针对业务领域问题有相应解决方案并落地。","requirements":"1、2027届获得本科及以上学历，计算机、软件、电子信息等相关专业；\n2、热爱计算机科学和技术，精通至少一门编程语言，包括但不仅限于：Java、C、C++、PHP、Python、Go；\n3、掌握扎实的计算机基础知识，深入理解数据结构、算法和操作系统知识；\n4、有优秀的逻辑分析能力，能够对业务逻辑进行合理的抽象和拆分；\n5、有强烈的求知欲，优秀的学习和沟通能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667887015312345397","sourceKey":"bytedance","company":"字节跳动","title":"AI产品经理 - 抖音电商","city":"上海/北京","category":"产品","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667887015312345397/detail","duty":"团队介绍：抖音电商以“总能发现好东西”为主张，致力于成为用户发现丰富好物的首选平台。众多抖音创作者通过短视频、直播、商城等丰富的形式，给用户提供更个性化、更生动、更高效的消费体验。同时，抖音电商积极引入优质合作伙伴，为商家变现提供多元的选择。\n\n1、负责抖音电商客服AI Agent产品建设，围绕咨询、售前售后、投诉等服务场景，设计并推动智能客服Agent落地，对产品效果负责；\n2、参与客服Agent建设，负责Query理解、方案召回、智能决策、工具调用、方案生成和用户交互等全链路产品设计与优化；\n3、建设智能客服评估和优化体系，通过业务案例、效果评测、问题分析和线上实验，持续提升AI服务能力，推动客服从“回答问题”向“解决问题”升级。","requirements":"1、2027届本科及以上学历，计算机、人工智能、软件工程、数据科学等相关专业优先；\n2、具备大模型应用能力，了解AI Agent构建与优化方法，熟悉Agent Harness、RAG、Prompt Engineering、Tool Calling、Agent Loop等核心技术，能够结合业务场景推动Agent效果优化；\n3、对电商、客服和用户体验方向有兴趣，具备业务理解能力，能够洞察用户需求并推动产品落地；\n4、具备较强的数据分析和问题解决能力，能够通过数据、实验和用户反馈持续优化AI产品效果；\n5、学习能力强，逻辑清晰，自驱力强，能够在快速发展的AI产品领域持续探索。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667854281463023925","sourceKey":"bytedance","company":"字节跳动","title":"AI产品经理（人审Agent平台方向） - TikTok","city":"北京","category":"产品","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667854281463023925/detail","duty":"团队介绍：TikTok是一个覆盖150个国家和地区的国际短视频平台，我们希望通过TikTok发现真实、有趣的瞬间，让生活更美好。TikTok在全球各地设有办公室，全球总部位于洛杉矶和新加坡，办公地点还包括纽约、伦敦、都柏林、巴黎、柏林、迪拜、雅加达、首尔和东京等多个城市。\n\n1、AI能力平台化：建立标准化的AI能力接入与管理机制，推动LLM、多模态模型等与内容质量管控系统的无缝集成，驱动内容质量把控流程自动化与人机协同效率最大化；\n2、产品设计与落地：深入理解内容质量把控、数据标注、劳动力管理等业务痛点，覆盖审标工作台、WFM平台、知识库等核心模块的产品规划与迭代，产出高质量PRD与交互方案，推动产品从0到1建设；\n3、AI知识工程：利用LLM、RAG等技术构建智能知识生产与检索能力，建立“生产→评估→修正”的知识迭代闭环，为全球审核团队提供高质量知识支撑；\n4、数据驱动决策：构建并监控各模块核心指标体系（AI采纳率、自动化覆盖率、人均效率、准确率等），通过数据分析持续优化产品与运营策略；\n5、跨团队协作：主导大型跨职能项目，与算法、工程、运营及全球安全团队高效协作，确保产品按时上线并实现业务价值。","requirements":"1、2027届获得本科及以上学历，计算机相关专业优先；\n2、具有良好的英语听写能力和沟通能力；\n3、具备逻辑分析与策略推演能力，对待数据与文档严谨细致，能主动跟进项目细节；\n4、熟悉大模型原理，具备优秀的Prompt Engineering调优经验，能通过调整策略解决复杂生成问题优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667576488259193141","sourceKey":"bytedance","company":"字节跳动","title":"多模态大语言模型算法工程师 - TikTok Shop","city":"上海/杭州/北京","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667576488259193141/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商业务，致力于成为用户发现并获取优价好物的首选平台。面向直播电商、视频内容电商、货架电商等多元购物场景，国际电商持续为全球用户提供更个性化、更主动、更高效的消费体验，也为商家提供稳定、可靠、可持续增长的平台服务，推动“新奇好物畅销全球，美好生活触手可得”的使命落地。\n目前，国际电商算法团队分布在中国、美国、新加坡等多个国家和地区，深度参与全球化业务建设。加入我们，你将有机会面向全球用户、商家和商品生态，与跨区域的产品、工程、运营和业务团队协作，持续提升商品供给质量、用户购物体验、平台交易效率与履约体验，共同探索内容电商与智能购物的新模式。\nData-国际电商团队是 TikTok Shop 的核心算法技术力量，专注于电商场景下的算法创新与规模化落地，方向包括但不限于：生成式推荐与大规模 Foundation Model、多模态商品理解与内容生成、搜索与导购、智能客服、风控治理、物流履约优化、商家经营智能化，以及 Agentic 智能体在电商全链路中的应用。我们希望通过先进的算法能力，帮助用户更高效地发现感兴趣的商品，帮助商家实现更高质量的经营增长，并持续提升交易各环节的智能化水平。\n在这里，你将与一流的产品和技术团队合作，面对复杂且真实的国际化电商挑战，推动前沿技术在大规模业务场景中落地，与团队一起创造更多可能。\n\n1、参与全球商品库建设，探索NLP技术、图像识别、多模态知识推理等技术在商品内容理解的应用，挖掘多维度商品属性，进行商品结构化处理；\n2、负责商品、商家、品牌等多元消重系统搭建，运用多模态技术攻克海量数据实时流式聚合、多粒度聚合、跨语言聚合等技术难点；\n3、负责电商比价系统设计和搭建，运用机器学习和深度学习相关技术，进行商品比价、商品定价和价格监控和预警，支持百亿补贴等重要业务场景；\n4、负责多语言多模态大模型在上述场景中的基建和应用，充分挖掘MLLM潜力，攻克国际化电商场景中面临的多语言、缺乏标注数据等难点；\n5、参与数据到业务落地全流程，包括但不限于数据处理、数据分析、特征工程、算法模型设计、评估、迭代，并持续探索最前沿技术。","requirements":"1、2027届获得本科及以上学历，人工智能、计算机、数学相关专业优先；\n2、在NLP、CV、多模态某个领域有较深入的研究，包括但不限于：大模型、多语言NLP、图像理解、多模态、小样本学习等；\n3、熟悉PyTorch/TensorFlow其中一种或多种框架模型的训练和部署，了解混合精度训练、分布式训练、TensorRT部署等；\n4、有较强的实践能力，在NLP/多模态检索方向有项目经验者优先，在Kaggle、COCO、ActivityNet、ICPC、NOI/IOI等比赛获奖者优先；\n5、算法技术领先，在顶级学术会议/期刊发表论文者优先；\n6、能与团队融洽合作相处，积极主动有热情。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667469859947366661","sourceKey":"bytedance","company":"字节跳动","title":"大语言模型研究员（数据智能体） - 数据平台","city":"北京/上海/杭州","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667469859947366661/detail","duty":"团队介绍：数据平台是字节跳动数据中台部门，为公司多业务线（包括抖音、电商、直播和生活服务等）提供一站式大数据解决方案，涵盖数据的生产、清洗、传输、建模、分析等全流程链路，提供数据开发、实验评估、画像标签、增强分析等多元场景解决能力。同时，数据平台部门也致力于把字节跳动积累沉淀的数据中台解决方案做商业化输出，让更多行业能够应用我们的产品能力构建自己的数据中台。在火山引擎上，我们提供了营销增长套件，数据中台等相关产品解决方案，为泛互联网、金融、汽车、新零售等行业提供了行业解决方案。\n\n1、大语言模型（LLM）驱动的智能Agent在各类任务中展现出强大的推理与交互能力，已成为AI领域的前沿热点；然而，现有大多数Agent设计隐含地基于“确定性假设”，即默认输入信息完全可靠、任务目标明确；这在现实场景中往往并不成立——数据不完整、外部工具执行失败、用户意图随时间演变，使Agent产生误导性甚至错误的结论；面对“信息不确定性”这一核心挑战：课题一方面聚焦知识冲突与推理鲁棒性，另一方面聚焦SQL逻辑依赖与演进维护；\n2、鲁棒Agent推理问题：检索增强生成（RAG）是获取外部知识主流机制，但存在知识冲突问题，当前LLM面对噪声检索表现仍有提升空间；\n3、演进式SQL任务开发与维护问题：企业级数据治理中，SQL脚本面临底层数仓Schema变更和业务统计口径演进问题，传统方法无法提供深层语义偏差指导，现有模型在超100行存量SQL维护任务成功率较低；\n4、鲁棒Agent推理技术路线：基于POMDP的决策规划，维护信念状态并计算最优行动策略；多策略协同，认知不确定性超阈值时切换并发探索模式；自适应响应，依据信念状态残余不确定性决定输出；\n5、演进式SQL任务开发与维护技术路线：SynSQL-Evolution数据工程，构建百万级合成语料；GRPO强化学习框架，设计复合奖励函数；计划驱动推理范式，输出“逻辑变更清单”；依赖感知Agent协同，结合拓扑规划器处理长序列需求并构建实时纠错循环。","requirements":"1、2027届获得硕士学位，人工智能等相关专业优先（如计算机科学、数学、电子工程等）；\n2、熟练使用Python、PyTorch等语言和代码库，熟悉大模型领域尤其是强化学习相关研究工作和算法，有大模型强化学习的研发基础，拥有高影响力会议论文（ICLR、NeurIPS、ICML等）、知名竞赛获奖经验者优先；\n3、具备优秀的学术视野与判断力，拥有出色的问题提出、分析及解决能力，良好的团队协作精神和沟通意识。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7596987935236032773","sourceKey":"bytedance","company":"字节跳动","title":"AI全栈开发实习生-音视频技术","city":"北京","category":"前端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7596987935236032773/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：视频与边缘部门承载了字节跳动的媒体内容分发基建及技术中台，支持了字节全系产品，如抖音、今日头条、番茄小说、西瓜视频等APP的点播、直播、实时通信、图片等多媒体业务发展，同时将业务发展过程中沉淀下来的技术能力和工具，通过火山引擎对外输出，面向各行各业用户提供视频云产品和服务，愿景是为内外部业务伙伴提供最低成本、最优画质、最低延时、最安全可靠的富媒体内容分发解决方案，助力业务伙伴降本提效实现持续增长。\n\n1、参与千万级DAU产品开发，优化大型Web应用性能和体验，体验全栈和全终端开发模式，包括Node.js服务、Web、Flutter、React Native、Electron、Uniapp、小程序等多端形态；\n2、参与音视频全链路能力建设，从内容采集与生产、编辑处理、实时传输、编解码优化到播放渲染，结合WebRTC、WebTransport、WebCodecs、MSE、WASM等技术，提升浏览器端直播与点播体验；\n3、参与AI Media Agent核心研发，构建覆盖图片/视频AI生产、AI编辑、内容理解、AI二次创作、AI播放的全流程能力，探索数字人、漫剧、短剧、广告创意等场景的AI原生应用落地；\n4、参与AI Platform Agent体系搭建，将传统Open API升级为MCP化服务，依托AI智能决策、智能编排与Generative UI等技术，打造突破传统GUI局限的下一代终端平台；\n5、参与AI Cloud平台研发，提供AI建站、Pages托管、Serverless部署等一站式Web应用开发服务，赋能开发者高效构建AI原生应用。","requirements":"1、2027届本科及以上学历在读，计算机、软件工程等相关专业优先；\n2、具备良好的编程功底，至少熟练掌握一种主流语言（如JavaScript/TypeScript，Python，Go，C++等）；\n3、对前后端技术有广泛的好奇心，具备AI全栈的发展潜力，乐于学习和实践新知识；\n4、逻辑清晰、善于沟通，能够清晰地表达自己的想法，并与团队高效协作。\n\n加分项\n1、有实际的大模型/AI Agent使用、微调或推理优化经验；\n2、了解Web Video/Audio、Web Image、WebCodec、WebTransport、WebGL、WebRTC、WebAssembly等任意一项Web媒体技术；\n3、了解Flutter/React Native/Electron/CEF/Chromium/Uniapp/小程序等任意一项技术；\n4、为开源项目贡献过代码，或在技术社区活跃、有自己的技术博客。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7686816711521732917","sourceKey":"bytedance","company":"字节跳动","title":"AI产品经理（医疗服务方向） - 小荷健康","city":"北京","category":"产品","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7686816711521732917/detail","duty":"团队介绍：小荷健康是字节跳动旗下的医疗健康品牌，我们致力于利用大模型技术，探索医疗健康服务的新范式，孵化了“小荷AI医生”app，为用户提供专业的健康咨询服务。小荷健康拥有专业的医学和互联网产研团队，认真探索AI医疗。\n\n1、参与AI问诊、AI健康管理、智能就医指引等产品的设计，从用户真实需求出发，定义AI驱动的服务模式与交互体验，深入理解大模型的能力边界，将AI能力转化为可落地的产品方案，明确“AI做什么、人做什么、如何协同”；\n2、设计AI回答的质量评测体系，持续分析负面案例，推动模型效果与产品体验的迭代优化，参与AI安全与合规机制设计，确保产品在专业边界内稳定运行；\n3、搭建并跟踪业务核心指标，通过数据分析定位问题、验证假设，驱动产品持续进化，关注用户反馈与行业动态，输出产品分析和产品洞察；\n4、与算法、研发、设计、医疗专家紧密协作，把AI技术语言翻译成用户体验，把用户需求翻译成可执行的产品方案，参与产品从立项到上线的全流程，见证自己的想法变成千万用户使用的产品。","requirements":"1、2027届获得本科及以上学历；\n2、有计算机相关知识，掌握编程能力，了解算法和大语言模型等方面的知识；\n3、有产品思维、有基本的用户理解、行业洞察、数据分析能力；对业务有理解，能基于明确的业务场景或需求输出产品Demo或搭建AI应用等工作流，高效推动产品落地；\n4、有很好的学习理解能力、逻辑思维能力，有自驱力/好奇心/求知欲等，结果导向，有成长潜力；如果你有医疗背景，对医疗和健康行业有理想与热情，会更加分。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7686797543070419205","sourceKey":"bytedance","company":"字节跳动","title":"音乐合作平台产品实习生 - 汽水音乐","city":"上海/北京","category":"产品经理","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7686797543070419205/detail","duty":"团队介绍：汽水音乐是字节跳动推出的一款音乐应用软件，是一款面向热爱音乐潮流的年轻人的听歌平台。核心功能包括听推荐、歌单、榜单、搜索。其歌曲切换方式与抖音短视频类似，采用手动上下滑屏操作，简单便捷，易于上手。我们致力于成为具有影响力的音乐平台，成为让用户最容易发现音乐、了解音乐、进行音乐表达和创作、围绕音乐交流的社区。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、负责汽水音乐开放平台基础能力建设，覆盖合作/签约/资产管理/结算全链路，保障版权方和音乐人的合作效率；\n2、负责汽水音乐平台经营能力建设，搭建音乐宣传推广经营/数据中心等产品能力，为版权方和音乐人提供宣传推广经营与数据服务。","requirements":"1、本科及以上学历在读；\n2、有B端/中后台产品实习经验，熟悉平台系统架构，逻辑能力强，具备理解复杂业务逻辑并抽象化、独立设计系统方案的能力；\n3、热爱思考、自驱力强，能透过现象看本质，具备迅速抓住关键问题的能力；\n4、有韧性，遇到困难不轻易放弃，能独立思考并推动问题解决。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7683485653992950069","sourceKey":"bytedance","company":"字节跳动","title":"AI数据运营（电商方向） - AI数据与安全","city":"北京","category":"产品运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7683485653992950069/detail","duty":"团队介绍：AI 数据与安全团队为 Seed 基座模型及 AI 原生应用提供跨模态数据服务，覆盖数据生产全流程，包含模型评估标准的制定、数据规模化生产、数据飞轮搭建，不断提升数据质量，支持模型快速迭代。\n团队由产品经理、数据工程、数据运营等跨职能人才组成，并通过与 Seed 研究员、行业专家、全球顶尖数据供应商紧密合作，从真实场景中收集反馈并分析模型表现数据，解决 AI 前沿突破过程中的复杂数据问题，推动模型性能与用户体验的双重提升。我们既是帮助模型技术迭代的一线贡献者，也是模型和 AI 产品的一手用户。\n\n1、负责大模型图文、音视频数据项目的整体交付管理，制定交付计划并把控数据质量，对数据敏感，能够快速定位问题并推动解决；\n2、使用Prompt Engineering、Agent/Workflow等技术进行项目提效及自动化探索，通过技术手段提升项目人效和数据质量；\n3、统筹跨部门资源，协同算法、产品团队制定数据规范与交付标准，确保项目目标高质量达成；\n4、通过技术分享和实践指导，提升团队对AI应用及前沿技术的理解能力，推动业务目标达成。","requirements":"1、2027届获得本科及以上学历，计算机/AI/软件工程/人工智能/数据科学等相关专业优先；\n2、其他专业如果做过AI大模型训练和评测方面相关的也可，熟悉Python等编程语言加分，在多模态领域的PE、Workflow、Agent等技术的使用上有落地成果，理解大模型基础原理（如Transformer架构、SFT/RLHF训练范式），持续追踪AIGC前沿进展，具备数据清洗、数据分析、数据预处理或自动化脚本开发经验；\n3、大模型训练和评测以及自动化等领域相关实习或项目经验（做过电商行业多模态模型经验加分），熟悉数据生产全流程，对大模型训练、评测或应用领域、各项AI工具有浓厚兴趣和热情，持续关注前沿研究与技术趋势，具备快速学习与探索能力；\n4、具备较强的自驱力和学习能力，思路清晰，逻辑性强，具备跨团队协作与沟通能力，能够在复杂项目环境中独立推进工作。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7677809080896293125","sourceKey":"bytedance","company":"字节跳动","title":"大模型PMO实习生 - Data AML","city":"深圳","category":"项目管理","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7677809080896293125/detail","duty":"团队介绍：Data AML是字节跳动的机器学习中台，为抖音/今日头条/西瓜视频等业务提供推荐/广告/CV/语音/NLP的训练和推理系统。为公司内业务部门提供强大的机器学习算力，并在这些业务的问题上研究一些具有通用性和创新性的算法。同时，也通过火山引擎将一些机器学习/推荐系统的核心能力提供给外部企业客户。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、负责模型内部业务方合规体系全流程落地推进，设计并完善合规审批逻辑、规则与执行机制；\n2、统筹OA审批流程、素材库录入管理、业务场景定制化白名单配置等合规相关工作，保障模型使用合规可控；\n3、跟进模型精调、模型新版本上线及权限开通流程，协调各方推进版本迭代与功能灰度开放；\n4、负责日常资源数据记录与流程梳理，持续优化审批效率与协作机制，提升内部运转效率。","requirements":"1、本科及以上学历在读，计算机、软件工程相关专业优先；\n2、有项目管理相关实习经验或相关经验优先，有算法经验和数据分析经验优先；\n3、有较强的沟通能力，良好的与人交流协作的能力；\n4、有较高的责任心、较强的执行能力，以及目标导向的落地执行能力、问题解决能力；\n5、乐意迎接变化接受挑战，持续学习，自律；\n6、能保证一周至少4-5天实习，持续六个月以上。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7675348782494189877","sourceKey":"bytedance","company":"字节跳动","title":"AI Agent开发工程师（创新&中台） - 数据BP","city":"北京","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7675348782494189877/detail","duty":"团队介绍：负责字节跳动旗下泛抖音、国际化、创新与中台等业务的数据 BP 工作，业务版图覆盖抖音、国际化、大模型、番茄小说等板块。我们以数据高效赋能业务增长为核心使命，深度扎根各业务线，以数据体系建设为根基、以业务目标达成为导向，为业务方提供专业、稳定、高效的数据服务与架构解决方案。工作内容聚焦海量数据的治理与应用，需对产品全链路数据进行复杂且深度的分析挖掘；深度参与大数据产品的迭代优化，探索前沿数据技术在业务场景中的落地实践，在字节跳动的技术土壤中实现个人能力与业务价值的双重增长。\n\n1、负责数据领域AI Agent平台的后端架构设计与模块研发，覆盖智能体调度引擎、工具编排体系、数据接入网关、权限与可观测性等能力，保障平台高可用、高性能与可扩展性；\n2、主导数据场景Agent应用全链路落地，包括但不限于Text-to-SQL、智能数据开发助手、数据质量自动巡检、指标归因分析、数据资产智能检索等方向，支持全栈研发交付；\n3、对接公司内部数据中台、数仓体系、数据开发平台、BI系统等底层数据产品，沉淀标准化集成方案与技术规范；\n4、跟踪大模型Agent、数据智能领域前沿技术，探索落地路径，持续优化平台架构与能力。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程、人工智能等相关专业；\n2、精通Java/Python/Go至少一门后端开发语言，熟悉分布式系统设计与微服务架构，具备扎实的工程素养；\n3、熟悉大数据技术体系，了解Hive/Spark/ClickHouse/Doris等至少一种计算/存储组件，有数据平台或数仓相关研发经验；\n4、理解AI Agent原理，熟悉智能体编排、工具调用、RAG检索增强等机制，有大模型API对接与应用落地经验；\n5、全栈方向需熟练掌握React/Vue等主流前端框架，具备JS/TS开发能力。\n\n加分项\n1、有Text-to-SQL、数据Copilot、智能数据治理相关项目落地经验；\n2、有LangChain、LlamaIndex、AutoGen等Agent框架深度使用或二次开发经验；\n3、熟悉向量数据库、Prompt工程、大模型微调相关技术；\n4、有数据中台、数据资产、数据质量系统研发经验；\n5、开源社区活跃贡献者，或拥有个人技术产品。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7674830007332522293","sourceKey":"bytedance","company":"字节跳动","title":"Agent开发工程师 - 抖音直播","city":"北京","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7674830007332522293/detail","duty":"团队介绍：直播团队负责为抖音集团旗下产品提供直播服务。团队负责直播平台技术和直播业务研发，打造灵活稳定的直播服务平台，为用户提供优质直播体验，支持电商、本地生活、游戏、节目、多人互动等不同类型的业务场景。直播业务发展迅猛，处于行业头部地位，业务发展空间巨大。现在加入我们，和优秀的人一起做有挑战的事，你的技术与创意将影响亿级用户，激发创意和丰富生活。\n\n1、参与抖音直播客户端AI Agent方向的建设，面向直播场景，设计并落地具备感知、理解、规划与执行能力的智能体能力；负责基于大语言模型的客户端Agent框架研发，探索AI在直播消费、互动、创作辅助、主播经营等场景中的落地方案；\n2、参与端侧、云端协同的AI能力建设，推动Agent在复杂业务场景下的任务拆解、工具调用、上下文管理与执行链路优化；\n3、参与客户端智能化产品能力研发，结合抖音直播业务特点，提升AI Agent在多轮交互、实时响应、个性化服务等方向的用户体验；\n4、与产品、设计、服务端、算法等团队密切合作，推进AI Agent在直播客户端场景中的工程化落地，持续优化效果、性能与稳定性；关注Multi-Agent、Prompt Engineering、长短期记忆、任务规划等前沿技术，探索其在直播业务中的实际应用与价值。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程等相关专业优先；\n2、扎实的工程功底与数据结构、算法基础：精通至少一门主流编程语言或技术栈（Python/Go/JS/TS/Java/Objective-C/Swift/C/C++/Android/iOS/Harmony），对软件架构有良好的理解；\n3、对Agent技术在研发及直播业务场景落地有兴趣，熟悉大语言模型技术栈，在上下文工程、Skills、Agent编排、评测等方向有实践经验，并能清晰阐述如何通过Agent解决实际业务问题；\n4、优秀的系统设计与问题拆解能力：能够将模糊、复杂的业务问题拆解为清晰、可执行的技术模块和迭代路径；\n5、关注用户体验，能够积极把技术转化为用户体验改进；对新技术保持热情，具备良好的分析、解决问题能力；\n6、具备良好的沟通协作能力与自驱力，愿意在快速变化的AI领域中持续学习与探索。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7673438749160016133","sourceKey":"bytedance","company":"字节跳动","title":"FDE实习生 - Seed Model","city":"北京","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7673438749160016133/detail","duty":"团队介绍：字节跳动 Seed 团队成立于 2023 年，致力于寻找通用智能的新方法，追求智能上限，为科技和社会发展作出贡献。\n\nSeed 团队在 AI 领域拥有长期愿景与决心，团队研究方向涵盖 MLLM、GenMedia、AI for Science、机器人等，在中国、新加坡、美国等地设有实验室和岗位。目前，团队已推出业界领先的通用大模型以及前沿的多模态能力，支持豆包、即梦、TRAE 等超过 50 个应用场景，并通过火山引擎开放给企业客户。第三方数据显示，豆包 App 用户量在中国市场排名第一，豆包大模型日均 Token 调用量行业领先。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、负责团队垂类课题组（如生物、材料、化学等科学方向）的基线访谈与需求梳理，深入了解课题组原有领域的工作方式与流程，并持续跟踪其工作进展；\n2、对接课题组内的软件与计算环境需求，协调完成采购落地流程；\n3、高频和科学家沟通，基于对课题组内工作流程的理解，识别可被AI替代或增效的具体环节，提出可执行的AI能力介入方案与替换流程设计；\n4、对AI能参与的流程设定科学、可靠的评测方案并测试，发现现有模型的问题；\n5、持续追踪相关工作中数据的完整性与质量，为后续算法迭代提供可靠依据。","requirements":"1、本科及以上学历在读，有垂类相关专业知识背景优先；\n2、热爱大模型/Agent技术领域，日常对AI相关产品和工具有较高使用频率，对大模型能力边界有自己的判断和思考；\n3、具备良好的Agent开发能力，可完成CLI适配、Harness改进等基础开发任务；\n4、具备良好的沟通协作能力和较强的跨领域学习能力，能够快速理解不同专业背景专家的工作内容并建立有效协作；\n5、能保证每周至少实习4天，持续实习6个月以上的同学优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669712735105976581","sourceKey":"bytedance","company":"字节跳动","title":"广告算法工程师 - 中国交易与广告","city":"上海/北京","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669712735105976581/detail","duty":"团队介绍：中国交易与广告，基于个性化推荐、深度学习和大模型技术，依托抖音、今日头条、红果短剧、西瓜视频、番茄小说等多元产品，构建抖音电商、生活服务、广告营销等核心营收业务的算法策略和工程架构。部门运用领先的算法能力，精准连接海量用户与商家，通过推荐、广告和搜索算法精准匹配需求并促进交易达成，保障用户体验与商家权益，实现营收业务可持续增长；基于深厚的技术积累，构建高效、智能、可靠的交易与广告产品，全面提升多行业收入变现与市场占有。在这里，你将直面超大规模流量与复杂业务场景的技术挑战，深度应用业界领先的商业模型与算法技术，投身面向未来的数字营销能力建设，持续探索前沿技术。\n\n1、设计并实现创新品牌广告产品，优化字节跳动全系App的广告投放算法策略与模型；\n2、优化品牌竞价广告的自动化投放能力，结合机器学习、强化学习、运筹优化等技术，为广告主提供自动化创编决策、素材创意优选、自动出价等能力；\n3、从客户视角出发，优化投放系统召回、粗排、精排等各阶段效果，优化广告扶持、出价等策略；\n4、协同产品团队打造业界一流品牌产品，探索种草等营销科学方法论的落地。","requirements":"1、2027届获得本科及以上学历，计算机、机器学习和模式识别相关专业优先；\n2、热爱计算机科学和互联网技术，对人工智能类产品有浓厚兴趣；\n3、具备扎实的编码能力，熟悉Linux开发环境，熟悉C++和Python语言；\n4、有扎实的数据结构和算法功底，熟悉机器学习、深度学习、强化学习、运筹优化、大模型、自然语言处理、数据挖掘中一项或多项；\n5、对推荐系统、计算广告相关技术有经验；\n6、优秀的分析问题和解决问题的能力，对解决具有挑战性问题充满激情。\n\n加分项\n1、有国际顶级会议论文；\n2、有GitHub作品等公开成果；\n3、曾获Kaggle/ACM等算法比赛奖项等。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669432548027828533","sourceKey":"bytedance","company":"字节跳动","title":"后端开发工程师（PGC Creator Strategy） - TikTok研发","city":"上海","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669432548027828533/detail","duty":"团队介绍：TikTok研发团队，旨在实现TikTok业务的研发工作，搭建及维护业界领先的产品。加入我们，你能接触到包括用户增长、社交、直播、电商C端、内容创造、内容消费等核心业务场景，支持产品在全球赛道上高速发展；也能接触到包括服务架构、基础技术等方向上的技术挑战，保障业务持续高质量、高效率、且安全地为用户服务；同时还能为不同业务场景提供全面的技术解决方案，优化各项产品指标及用户体验。 \n在这里， 有大牛带队与大家一同不断探索前沿， 突破想象空间。 在这里，你的每一行代码都将服务亿万用户。在这里，团队专业且纯粹，合作氛围平等且轻松。目前在北京，上海，杭州、广州、深圳分别开放多个岗位机会。\n\n1、参与架构设计和开发，为亿级用户提供优质顺畅的信息服务和极致体验；\n2、参与设计系统技术方案，代码开发和系统调优；\n3、参与制定代码规范、测试规范，建立起开发质量控制方法；\n4、协助团队攻克各种高并发、数据隔离、系统解耦等方面的技术难关；\n5、参与各专项技术调研，新技术引入等前瞻项目。","requirements":"1、2027届获得本科及以上学历，计算机、软件、电子信息等相关专业；\n2、热爱计算机科学和技术，精通至少一门编程语言，包括但不仅限于：Java、C、C++、PHP、Python、Go；\n3、掌握扎实的计算机基础知识，深入理解数据结构、算法和操作系统知识；\n4、有优秀的逻辑分析能力，能够对业务逻辑进行合理的抽象和拆分；\n5、有强烈的求知欲，优秀的学习和沟通能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668342249999894789","sourceKey":"bytedance","company":"字节跳动","title":"后端开发工程师 - Seed 产品研发","city":"深圳","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668342249999894789/detail","duty":"团队介绍：产品研发和工程架构-Seed 团队深耕大模型技术在场景中的创新应用，负责多款AI产品的工程研发 —— 包括豆包、飞书、豆包工作、豆包爱学、Gauth、猫箱等创新产品，覆盖消费级与企业级多个场景。我们致力于将大模型能力从 \"生成内容\" 推进到 \"完成工作\"，让 AI 服务用户日常与企业协作。你将面对多模态交互、工具调用可靠性、企业级数据安全等真实工程挑战，与团队一起推动 AI 生产力落地。\n\n1、负责飞书相关产品的服务端功能研发与维护，探索AI能力在业务场景中的应用；\n2、参与服务架构、性能与稳定性优化、基础设施及研发工具建设，持续提升服务质量、工程质量和研发效率；\n3、参与面向AI Agent的工程体系建设，包括飞书能力的工具/API封装、上下文管理、任务执行与效果评测，提升Agent在软件研发场景中的效率、正确性和可靠性。","requirements":"1、2027届获得本科及以上学历，计算机科学、软件工程、人工智能等相关专业优先；\n2、具备扎实的数据结构、算法和计算机基础，熟练掌握至少一门编程语言，包括但不限于Go、Java、C/C++、Rust、Python；\n3、了解服务端开发基础，在网络、系统架构、存储、缓存或安全等至少一个方向有项目实践；具备产品意识，关注实际效果和用户价值；\n4、具备良好的学习、分析和动手能力；有使用AI编程或Agent工具解决实际问题的经验，能够理解其局限并验证生成结果。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668197844242794805","sourceKey":"bytedance","company":"字节跳动","title":"国际物流服务体验运营 - TikTok Shop","city":"杭州","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668197844242794805/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商。平台汇聚全球优质商家与创作者，通过短视频、直播等多场景连接消费者，让新奇好物畅销全球，让美好生活触手可得。目前团队分布在美国、英国、法国、印尼、墨西哥、中国等全球多个国家和地区，在这里你将有机会深入国际业务场景，面向全世界商家及用户，和跨区域团队协作，共同探索创新购物模式。期待和优秀的你一起创造更多可能！\n\n1、通过日常数据监测与信息分析，识别并梳理商家在物流场景的核心体验问题，联合相关部门密切协同推进问题解决，通过产品能力、服务链路等优化，持续提升商家整体物流体验；\n2、深入行业物流趋势研究与消费者核心诉求洞察，制定和完善消费者服务流程与方案，提高物流服务效率与质量；\n3、负责对接第三方物流/配送/仓储服务商客服的日常运营工作。","requirements":"1、2027届获得本科及以上学历，物流、供应链管理、电子商务等相关专业优先；\n2、具备良好的逻辑思维能力与数据分析能力，能熟练使用Excel、SQL、BI工具等，基于业务数据和用户案例发现问题、提出优化建议，并协助推动业务需求产品化、数据化；\n3、具备互联网体验运营、物流管理、商家服务等相关实习或工作经验者优先；\n4、具备良好的沟通协调能力，具备客户意识和服务意识；\n5、具备较好的英文说写能力，能够胜任日常英文沟通场景。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667900909641369909","sourceKey":"bytedance","company":"字节跳动","title":"Agentic AI算法工程师 - 风控","city":"杭州/深圳/北京","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667900909641369909/detail","duty":"团队介绍：风控团队由算法、工程、产品三大团队协同构成，为抖音、今日头条、豆包、剪映等字节跳动业务的内容、交易、流量、账号场景提供智能风控，服务十亿级用户；场景对抗性极强、推理链路长、多模态数据海量，是 AI 时代最有挑战的实战领域之一。算法团队推进 LLM/MLLM 与 Agentic AI 的工业化落地，构建下一代智能风控基建；工程团队依托高并发、大数据与大模型，搭建端云一体的多层对抗体系与情报预警；产品团队评估业务风险、制定策略、探索 AI 在风控中的边界。三线协同，打造高效、前瞻的智能风控防线。\n\n1、参与风控垂域大模型基座优化：打造业内领先的风控垂域基座，深入研究CPT、SFT、RL及训练与推理加速等技术；重点攻克强对抗环境下的多模态理解难题，提升模型在超长上下文、复杂逻辑推理和指令遵循等方面的表现；\n2、参与Agentic AI架构研究与演进：参考行业标杆，推进风控Agent的架构升级与工业化落地，打磨领域Skill/Tool框架，优化复杂工具调用、长短期记忆管理、长链路任务编排和多Agent协同等，打造具备自演进能力的下一代智能风控架构；\n3、参与构建科学评估与Harness Engineering体系：构建高质量的领域数据集，设计科学严谨的Benchmark评测体系，构建工业级Harness Engineering系统，持续驱动模型能力边界的突破。","requirements":"1、2027届获得本科及以上学历，计算机、机器学习和模式识别相关专业者优先；\n2、扎实的算法与数据结构基础，熟练掌握Python/Go/C++等至少一门编程语言，具备优秀的工程落地能力；\n3、熟悉主流大模型（如Gemini，Qwen，DeepSeek等）的训练与微调原理，了解RAG、长上下文处理等技术；\n4、在LLM/MLLM/Agent有扎实积累，在NeurIPS/ICML/ICLR/ACL/CVPR等顶会发表过相关高质量论文者优先；\n5、具备系统的研究思维与独立思考能力，对风控领域的复杂性、对抗性有浓厚兴趣，敢于挑战现有技术范式。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667796578648082741","sourceKey":"bytedance","company":"字节跳动","title":"AI策略产品经理（抖音AI产品人才校招） - 抖音","city":"北京","category":"产品","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667796578648082741/detail","duty":"团队介绍：抖音致力于打造一个开放、积极、多元、友善的平台，鼓励表达、沟通和记录，激发创造，丰富人们的精神世界，让现实生活更美好。我们通过AI算法驱动的个性化推荐与智能创作工具，满足用户表达、学习、娱乐、社交、消费等需求。回顾抖音一路走来的历程，我们在帮助亿万用户记录美好生活的过程中，努力变得更好。\n\n这是抖音面向具备AI能力的同学发起的校招项目，覆盖产品、策略运营方向。\nAI 正在重新定义产品，也在重新定义\"做产品\"这件事 —— AI Native 的产品，需要你既能理解大模型技术边界，又能定义产品价值。\n如果你也有着许多的奇思妙想， 欢迎加入抖音，把想法落地成亿万用户真实可感的产品体验，来抖音，和我们一起探索 AI 产品的下一种可能！\n\n1、负责抖音增长业务中的AI产品应用，重点围绕增长营销和投放场景做能力突破，提升业务效率与增长效果；\n2、结合AIGC、Agent、Workflow等能力，推动广告创意生成、理解、筛选、优化、投放等环节的自动化系统落地和智能化Agent产品落地；\n3、通过PE调试、Vibe coding、工作流搭建等方式做效果验证，并将验证方案转为可执行的工程算法方案；\n4、建设多模态模型及Agent Harness的评估方案和迭代机制，确保模型及系统的好用性和稳定性；\n5、理解业务场景，拆解业务核心指标，并通过数据分析、用户调研和业务反馈，持续挖掘问题点和机会点，协同运营、算法、工程、设计等团队，高效推进产品落地。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程等相关专业优先；\n2、具备AI Native产品应用经验、优秀的AI相关应用与落地能力，对多模态评测、Agent评测等有较好认知，有相关项目实践经验，投递时附带个人AI作品集者优先；\n3、熟悉AIGC相关能力及典型应用场景，理解文本、图片、视频等生成式AI在内容生产中的应用方式及能力边界；熟悉Agent harness的核心机制与应用场景，理解任务拆解、工具调用、记忆、反馈与迭代等关键能力，并能结合业务判断其落地方式；熟悉Workflow/工作流编排，能够围绕复杂业务流程设计多步骤AI执行链路，实现AI与业务系统、策略规则及人工流程的协同；\n4、数据敏感、逻辑清晰，具备良好的跨团队协作和项目推动能力，能够独立推进复杂项目落地并对结果负责。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667601553702848773","sourceKey":"bytedance","company":"字节跳动","title":"搜索大模型算法工程师 - TikTok Shop","city":"上海/杭州","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667601553702848773/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商业务，致力于成为用户发现并获取优价好物的首选平台。面向直播电商、视频内容电商、货架电商等多元购物场景，国际电商持续为全球用户提供更个性化、更主动、更高效的消费体验，也为商家提供稳定、可靠、可持续增长的平台服务，推动“新奇好物畅销全球，美好生活触手可得”的使命落地。\n目前，国际电商算法团队分布在中国、美国、新加坡等多个国家和地区，深度参与全球化业务建设。加入我们，你将有机会面向全球用户、商家和商品生态，与跨区域的产品、工程、运营和业务团队协作，持续提升商品供给质量、用户购物体验、平台交易效率与履约体验，共同探索内容电商与智能购物的新模式。\nData-国际电商团队是 TikTok Shop 的核心算法技术力量，专注于电商场景下的算法创新与规模化落地，方向包括但不限于：生成式推荐与大规模 Foundation Model、多模态商品理解与内容生成、搜索与导购、智能客服、风控治理、物流履约优化、商家经营智能化，以及 Agentic 智能体在电商全链路中的应用。我们希望通过先进的算法能力，帮助用户更高效地发现感兴趣的商品，帮助商家实现更高质量的经营增长，并持续提升交易各环节的智能化水平。\n在这里，你将与一流的产品和技术团队合作，面对复杂且真实的国际化电商挑战，推动前沿技术在大规模业务场景中落地，与团队一起创造更多可能。\n\n1、探索大模型与搜索深度融合的创新技术，参与下一代Agentic Search引擎研发，负责搜索全链路（Query理解、规划、召回、重排、生成）的算法设计与优化，包括Query Understanding、Retrieval、Ranking、RAG、LLM、Agent、多模态、强化学习等方向，持续提升搜索相关性、回答质量、用户体验及业务价值；\n2、参与Agentic Search能力建设，负责Search Agent、Deep Search、Deep Research等能力研发，探索Planning、Tool Use、Multi-hop Retrieval、Information Grounding、Citation、Self-Verification等关键技术在真实搜索场景中的落地；\n3、参与搜索基础模型（Search Foundation Model）训练与数据体系建设，构建覆盖数据、评测、训练的完整闭环，包括SFT、Preference Learning、RLHF/RLVR、Distillation、Synthetic Data、Self-Improvement、Long Context、Memory等方向；挖掘用户行为与搜索日志，构建Query理解、召回、排序、Agent推理等训练数据，设计Rubric、LLM-as-a-Judge、自动化评测体系，持续提升模型推理能力、泛化能力与效果；\n4、深入参与搜索产品设计，与产品、工程团队共同推动算法方案高质量落地，持续优化Agentic Search产品体验，打造面向亿级用户的新一代智能搜索系统；\n5、持续关注国际前沿研究，探索大模型、Agent、多模态、强化学习、长上下文、Memory、Inference-time Compute等技术在Agentic Search场景中的创新应用。","requirements":"1、2027届获得硕士及以上学位，人工智能、计算机、软件工程、电子信息、自动化、数学、统计等相关专业优先；\n2、具备扎实的数据结构、算法和编程基础，熟练掌握C/C++、Python等至少一种编程语言，具有良好的工程实现能力；\n3、熟悉机器学习、深度学习基础，了解Transformer、Attention、Embedding、Optimization等算法，熟悉PyTorch等深度学习框架；\n4、在搜索、推荐、广告、信息检索（IR）、自然语言处理（NLP）、大语言模型（LLM）、多模态、强化学习（RL）等一个或多个方向具有较深入的研究或实践经验者优先；\n5、具备良好的问题分析与解决能力，具有较强的学习能力、沟通协作能力和技术探索精神，能够快速推动创新技术落地。\n\n加分项\n1、具有扎实的机器学习、深度学习、强化学习基础，在Agentic Search、Search Agent、Deep Search、Deep Research、LLM、RAG、Post-Training、多模态、World Model、RLHF/RLVR等方向具有深入研究经验；\n2、在KDD、SIGIR、WWW、ICML、NeurIPS、ICLR、ACL、EMNLP、NAACL、CVPR、ECCV、ICCV、AAAI、IJCAI、CoRL等国际顶级会议或期刊发表论文者优先；\n3、获得ACM/ICPC、NOI、IOI、TopCoder、Kaggle等国内外算法竞赛奖项者优先；\n4、具有Agentic Search、Search Agent、Deep Search、Deep Research、RAG、LLM Post-Training、Preference Learning、RLHF/RLVR、Synthetic Data、Long Context、Memory等方向的项目经验者优先；\n5、具有大规模搜索引擎、推荐系统、计算广告、分布式训练、大模型训练与推理优化、超大规模数据计算等相关经验者优先；\n6、主导或参与过具有较大影响力的Agentic Search、大模型、Agent或AI应用项目，具有优秀的技术创新能力和工程落地能力者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667537338419611957","sourceKey":"bytedance","company":"字节跳动","title":"云与AI解决方案架构师 - 火山引擎","city":"深圳","category":"产品经理","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667537338419611957/detail","duty":"团队介绍：火山引擎是字节跳动旗下云和AI服务平台，将字节跳动快速发展过程中积累的增长方法、技术能力和应用工具开放给外部企业，通过云和AI技术，推进企业智能化转型，激发增长潜能。\n\n1、面向公有云场景，与销售、BD、产品研发等部门紧密协同，跟进行业重点客户，推动标准产品或解决方案在客户侧落地；\n2、为字节跳动内外部客户提供业务和技术层面的架构咨询服务，理解合作伙伴及客户的业务和功能性需求、非功能性需求、性能和可靠性需求，提供基于火山引擎产品体系的架构设计方案，支持客户或合作伙伴成功地在火山引擎产品上构建上层应用系统和服务；\n3、通过对客户业务的深入理解和分析，提炼客户的终极诉求，结合公司产品和技术能力，沉淀行业细分方向的GTM方法论，树立行业标杆案例和典型场景价值案例。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程、AI大模型等相关专业优先；\n2、具备良好的沟通表达能力，逻辑思维、表达和沟通能力；\n3、主动投身云服务、大数据、人工智能等领域的技术革新，快速学习能力与市场洞察力兼备。\n\n【加分项】\n1、在校期间担任学生干部、组织过校级项目并担任负责人；\n2、有企业解决方案或架构设计实习经验，对云原生应用架构/大数据和人工智能架构/视频云有一定了解。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667154545639246085","sourceKey":"bytedance","company":"字节跳动","title":"云与AI咨询销售 - 火山引擎","city":"北京/上海/成都/武汉/深圳/杭州","category":"销售","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667154545639246085/detail","duty":"团队介绍：火山引擎是字节跳动旗下云和AI服务平台，将字节跳动快速发展过程中积累的增长方法、技术能力和应用工具开放给外部企业，通过云和AI技术，推进企业智能化转型，激发增长潜能。\n\n1、梳理不同行业客户信息，直接或通过渠道伙伴收集客户信息，触达并维护决策关系，挖掘需求并捕获项目机会；\n2、推进双方在技术、产品和商务等多层面的沟通，全局掌控项目节点与节奏，并推进项目落地；\n3、协同产品和解决方案，对不同产品线在某行业拓展的标杆客户落地、客户覆盖数及营收目标负责；\n4、体系化的数据化的业务思路，能够根据销售过程管理数据分析，发现业务问题，提出改进方案，制定业务策略和规划，优化业务模型；协助业务团队建立可执行、可追溯的动作；\n5、你将获得：传递客户价值并输出和参与完整客户业务合作的机会，收获一线实践经验，快速提升个人综合能力，为职业发展奠定坚实基础。","requirements":"1、2027届获得本科及以上学历，科学技术或计算机相关背景优先；\n2、可以快速学习AI和云产品知识，具备良好的沟通能力、学习能力以及团队合作能力，对AI、云、大数据等感兴趣并且愿意长期从事相关工作；\n3、熟悉主流大模型与AI应用，持续关注AI领域前沿动态，具备动手实践能力。\n\n加分项：\n1、在校期间担任学生干部、组织过校级项目并担任负责人；\n2、具有相关实习经验；\n3、如有相关作品或项目成果（如自主开发的AI应用、微调模型、开源项目、技术文章、竞赛获奖作品等），可在简历中附上作品链接或上传附件展示。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7665584035664054533","sourceKey":"bytedance","company":"字节跳动","title":"清算产品经理 - 国际支付","city":"北京/上海","category":"产品经理","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7665584035664054533/detail","duty":"团队介绍：国际支付，立足于为字节跳动国际化业务提供专业的支付和金融服务，专注于全球支付产品线的质量和效率，确保为国际产品提供高度可靠和稳定的服务，建立国际支付产品和能力，同时在高效助力业务快速拓展的同时，打造行业领先的支付和金融产品能力。团队当前所提供的产品和服务，遍布全球多个国家和地区，团队拥有丰富的国际化产品研发经验；同时这里有全球超大规模的支付网络；覆盖多业务场景的海外钱包及金融产品解决方案；围绕分布式一致性、高并发、高可用、资金安全在内的核心技术能力攻坚；LLM等前沿AI技术在支付&金融服务中的探索、研发和应用。另外，我们在全球设立团队，团队同学背景多元，不同的思维方式，打造了一个多元、碰撞、融合、包容的工作环境。我们邀请你来此成长、专研，发掘无限的潜力，一起应对技术和业务以及跨国合作上的挑战，还有跨文化交流机会在等你！\n\n1、协助产品经理梳理国际支付的各业务场景，进行清算中心相关产品建设，包括需求收集，整理分析，产品原型设计，协助验证产品功能及业务项目的上线；\n2、通过用户调研、数据分析等手段，对清算中心的产品进行升级迭代，推动产品体验和运营效率的提升；\n3、跟踪产品的上线效果、用户反馈，进行功能解答，同时为产品功能优化提供合理建议；\n4、参与清算中心相关文档的撰写与维护，包括产品说明书、操作手册、需求文档等；\n5、与运营、研发、测试等团队密切合作，保证产品功能按时上线。","requirements":"1、2027届获得本科及以上学历，计算机、财务、金融等相关背景优先；\n2、对支付、清算、金融系统等领域有兴趣，学习能力强，逻辑思维清晰，能理解复杂业务和资金链路；\n3、工作认真负责，主动性强，有良好的文字表达与沟通协作能力，能高效对接跨团队需求；\n4、具备基础的英文读写能力，能够在简要准备后进行结构化表达。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7665348578872903989","sourceKey":"bytedance","company":"字节跳动","title":"多模态视频理解大模型算法工程师 - 音视频技术","city":"北京/深圳","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7665348578872903989/detail","duty":"团队介绍：视频与边缘部门承载了字节跳动的媒体内容分发基建及技术中台，支持了字节跳动全系产品，如抖音、今日头条、番茄小说、西瓜视频等APP的点播、直播、实时通信、图片等多媒体业务发展，同时将业务发展过程中沉淀下来的技术能力和工具，通过火山引擎对外输出，面向各行各业用户提供视频云产品和服务，愿景是为内外部业务伙伴提供最低成本、最优画质、最低延时、最安全可靠的富媒体内容分发解决方案，助力业务伙伴降本提效实现持续增长。\n\n1、探索多模态视频理解大模型技术前沿，长视频理解、token压缩、影视视频剧本还原、全模态高光理解、流式视频理解、理解和生成统一等技术方向，创新性优化相关算法；\n2、全模态大模型（文本、图像、语音）的Post-training算法，同时结合用户消费行为持续优化模型效果，结合LongCOT和RL自主探索学习，探索多模态感知能力的边界；\n3、探索视频剪辑Agent相关的研发和应用，研究高质量数据的挖掘和合成、大模型的对齐效率、多目标融合的学习，Agent全链路优化的方法等等；\n4、探索直播流式场景比如体育、游戏等实时解说，解决工业级效率和效果难题，支持多语言服务全球化；\n5、发表相关技术创新成果，比如顶会论文、专利或比赛。","requirements":"1、2027届获得硕士及以上学位，计算机、人工智能、数学等相关专业优先；\n2、熟练掌握Python/C++，熟悉NLP、CV、多模态中的1-2个领域，熟悉大模型训练、RL算法者优先；\n3、熟悉Qwen-VL、InternVL、InternVideo等模型，有基于视频Catpion、视频Grounding、视频摘要、视频问答、美学评价、高光检测、动作识别、视频编辑、视频风格化等项目落地经验者加分，能深入解决大模型训练和应用存在的问题；\n4、发表过CV/NLP/多模态相关顶会论文（比如CVPR/ICLR/ICCV/PAMI/ACL等）或ACM等竞赛获奖；\n5、强烈的技术热爱和好奇心与自主探索能力，优秀的分析和解决问题的能力，和团队一起探索新技术创新和落地。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7664522560570689845","sourceKey":"bytedance","company":"字节跳动","title":"搜索架构工程师 - 搜索架构","city":"北京/上海/杭州","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7664522560570689845/detail","duty":"团队介绍：作为字节跳动核心业务的技术引擎，搜索架构部门致力于构建全球领先的大规模智能搜索架构，支撑抖音、电商等业务的飞速发展。在抖音等短视频生态与电商业务，我们直面千亿级数据规模下的复杂工程挑战。团队深耕检索架构、分布式系统、模型工程与特征工程四大核心领域。我们通过技术创新驱动人与信息的高效连接，服务全球数亿用户的大规模搜索需求，打造极致的搜索体验。\n\n1、参与搜索引擎研发工作，用前沿的机器学习算法、海量的数据，做激动人心的技术、给用户好的搜索体验；\n2、参与今日头条、抖音等产品的搜索研发工作，服务相关产品数亿用户；\n3、参与搜索核心架构改进，可能的方向包括：1）设计开发千亿级网页搜索的数据流、分布式建库、在线检索系统，设计业内领先的检索架构；2）设计开发万亿级Spider系统的实时计算、调度分发、压力控制、蜘蛛抓取等服务；3）设计开发高可用的搜索引擎稳定性解决方案、自动测试和运维平台；\n4、在这里你可以毫无历史包袱地实现自己的架构梦想。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程等相关专业优先；\n2、出色的分析问题、解决问题能力；\n3、出色的代码能力，出色的数据结构和基础算法功底；\n4、有分布式系统基础和开发经验者优先；\n5、熟悉Linux开发环境、至少熟悉C++、Java、Python、Go等一种语言。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7597811305958066485","sourceKey":"bytedance","company":"字节跳动","title":"后端开发实习生-商业信任与安全","city":"上海","category":"后端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7597811305958066485/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：商业化信任与安全研发团队致力于构建业界领先的智能审核系统，通过前沿 AI 技术保障商业内容安全与合规，提升用户客户的信任。团队通过研发大模型基座、先进的审核大模型和审核系统，持续提升大模型系统对复杂商业化内容的理解、让准确理解遵循安全规则、基于规则深度推理并拉齐人与机器之间的认知，并能感知发现潜在问题，并用Agent高效处理审核问题、自动迭代审核系统，为商业内容安全提供全链路、智能化的技术支撑。\n\n1、负责字节跳动商业化相关产品线的内容安全和风控能力建设，设计和实现通用审核流框架，日均覆盖亿级别的素材；\n2、负责商业化内容安全相关的工具的搭建和优化，包括但不限于：规则引擎、策略平台、审核Workflow、人审/人效平台工具等；\n3、负责GIP产品广告算法核心服务的后端模块设计与实现，包括召回、点击/转化率预估、创意和样式优选、广告和内容混合排序等；\n4、为GIP产品的广告算法建设深度学习能力，包括流式样本生成、深度模型实时训练、深度模型在线推理服务、深度模型召回服务等；\n5、负责GIP产品广告链路的混排策略、投放策略、竞价策略、流量优选、算力分配、工程性能等内容的优化；\n6、设计与实现高可用的广告投放系统，承载高并发、低延迟的广告投放需求，与产品团队配合，提升GIP产品的广告变现效率和用户体验，实现业务的快速、稳健迭代。","requirements":"1、2027届硕士及以上学位在读，计算机相关专业；\n2、具备良好的编码能力，扎实的计算机基础、数据结构和算法功底，熟悉C++/Golang/Python中的至少一门编程语言；\n3、对可扩展性、稳定性、性能、质量有特别的执着，若具有高可用、高性能Web实践经验更佳；\n4、对数据敏感，熟悉常用的大数据处理工具（Hive/Spark）、Linux操作系统和开发环境；\n5、能快速理解业务，较好的产品意识，善于沟通，工作积极主动，责任心强，具备良好的团队协作能力；\n6、有统计背景、数据分析与数据挖掘经验，广告相关领域经验（互联网广告系统、搜索引擎、个性化推荐系统开发），或者内容安全平台或规则引擎背景优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7595512426763045125","sourceKey":"bytedance","company":"字节跳动","title":"后端开发实习生-DataLeap","city":"杭州","category":"后端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7595512426763045125/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：负责字节跳动一站式数据研发治理套件Dataleap，提供从数据集成、开发、治理、资产管理、安全合规等全链路大数据管理能力，帮助数据团队有效降低工作成本和数据维护成本、挖掘数据价值，为企业决策提供数据支撑。\n\n1、参与全域数据集成平台和底层引擎的开发迭代和优化；\n2、参与需求调研与用户技术支持；\n3、致力于打造业内领先的数据中台产品。","requirements":"1、2027届本科及以上学历在读，计算机、软件工程等相关专业优先；\n2、扎实的计算机基础，对技术有热情，愿意不断尝试新技术和业务挑战，熟悉Java/Scala语言，包括JVM、类装载、线程、并发、IO资源管理、网络；\n3、了解Spring/MyBatis等开源框架，或Flink/Spark等大数据引擎；\n4、熟悉分布式、缓存、消息等机制。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7593031395927181573","sourceKey":"bytedance","company":"字节跳动","title":"移动研发实习生-App Infra","city":"北京","category":"客户端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7593031395927181573/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：App Infra是字节跳动面向应用的基建中台部门，以App侧性能/稳定性深度优化为基础，结合LLM、Agent、生成式推荐模型等前沿技术，为字节跳动旗下的核心应用提供终端+平台的解决方案。于下层，结合操作系统、虚拟机、工具链、编译器等技术，建设了稳定性、流畅性、电量在内全链路的监控体系和调试分析工具；于上层，则结合端侧特征工程、深度学习模型/决策树模型/SLM训练等基建，围绕搜索/推荐/广告/直播/电商等场景，建设了云端协同推荐、品质体验优化等端智能解决方案。如果你热爱挑战底层技术、追求极致优化，又渴望把AI转化为千万用户感受得到的流畅与智能——欢迎加入，和我们一起打造下一代移动体验！\n\n1、主导端侧AI基建与架构设计，深度参与框架选型、技术路线决策，与算法团队共建高可用、高性能的端智能体系；\n2、负责SLM、VLM、端侧大模型的工程化落地，攻克轻量化部署、低延迟推理、资源受限场景下的实时智能难题；\n3、面向Android、iOS、鸿蒙多平台做深度适配，解决端侧算力、功耗、内存、稳定性等硬核工程问题；\n4、结合LLM/Agent最新演进方向，迭代工具链与部署方案，持续提升端云协同智能的效率与体验。","requirements":"1、2027届本科及以上学历在读，计算机、人工智能、自动化等相关专业背景；\n2、具备扎实的编程基础，熟悉至少一门开发语言（如C++/Java/Kotlin/Objective-C/Swift/Python等），对技术充满好奇与热情；\n3、逻辑思维清晰，具备良好的沟通协作能力，渴望用技术解决复杂问题。\n\n加分项：\n1、理解LLM原理，具备Agent系统设计与落地经验，关注Agent上下文管理、状态维护与效果评估，能持续提升智能体执行效率与可靠性；\n2、有端侧模型部署与优化经验，了解本地大模型推理框架，熟悉模型量化、推理加速等相关技术。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7560582505469151506","sourceKey":"bytedance","company":"字节跳动","title":"后端开发实习生（客服平台方向）-TikTok","city":"北京","category":"后端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7560582505469151506/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：TikTok研发团队，旨在实现TikTok业务的研发工作，搭建及维护业界领先的产品。加入我们，你能接触到包括用户增长、社交、直播、电商C端、内容创造、内容消费等核心业务场景，支持产品在全球赛道上高速发展；也能接触到包括服务架构、基础技术等方向上的技术挑战，保障业务持续高质量、高效率、且安全地为用户服务；同时还能为不同业务场景提供全面的技术解决方案，优化各项产品指标及用户体验。 \n在这里， 有大牛带队与大家一同不断探索前沿， 突破想象空间。 在这里，你的每一行代码都将服务亿万用户。在这里，团队专业且纯粹，合作氛围平等且轻松。目前在北京，上海，杭州、广州、深圳分别开放多个岗位机会。\n\n1、参与TikTok客服平台的设计和研发工作，深入业务，理解抽象，为用户提供智能化、高效的服务解决方案；\n2、参与相关产品的技术文档编写，方案设计和代码开发；\n3、参与各专项技术调研，新技术引入等前瞻项目。","requirements":"1、2027届本科及以上学历在读，计算机相关专业优先；\n2、热爱计算机科学和互联网技术，精通至少一门编程语言，包括但不仅限于：Go、Java、Python、C/C++； \n3、掌握扎实的计算机基础知识，深入理解数据结构、算法和操作系统知识； \n4、有优秀的逻辑分析能力，能够对业务逻辑进行合理的抽象和拆分； \n5、有强烈的求知欲，优秀的学习和沟通能力；\n6、能保证至少4个月及以上的实习，每周可出勤至少4天及以上。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7685720469166541061","sourceKey":"bytedance","company":"字节跳动","title":"策略运营（履约配送方向） - 抖音电商","city":"北京/上海","category":"用户运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7685720469166541061/detail","duty":"团队介绍：抖音电商以“总能发现好东西”为主张，致力于成为用户发现丰富好物的首选平台。众多抖音创作者通过短视频、直播、商城等丰富的形式，给用户提供更个性化、更生动、更高效的消费体验。同时，抖音电商积极引入优质合作伙伴，为商家变现提供多元的选择。\n\n1、负责抖音电商的履约配送管理策略设计和迭代，结合抖音电商业务诉求，分析消费者需求和行业现状，制定适合抖音电商平台的履约规则；\n2、改善消费者购物后的履约及退货体验，探索全新的商家、平台、履约服务商合作模式，寻求消费者履约成本与履约体验的最佳平衡点；\n3、深挖不同行业、不同产品、不同消费者画像的履约需求，制定差异化体验提升方案，并联动产品、算法、技术等部门团队完成方案落地；\n4、日常数据监控及问题研判，及时发现风险问题并推动解决，同时针对已落地的策略方案通过实验验证其效果和对平台价值。","requirements":"1、2027届获得本科及以上学历，数学/商业分析/物流专业/统计学等相关专业优先；\n2、对抖音电商有一定了解，有电商实习经验优先；\n3、具备较强逻辑思考能力和数据分析能力，熟练使用Excel、SQL及可视化分析工具；\n4、良好的沟通表达能力，学习能力强、自驱导向、责任心强，踏实靠谱、积极主动。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7672980664934025525","sourceKey":"bytedance","company":"字节跳动","title":"算法工程师（金融自动化方向） - 中国交易与广告","city":"北京/杭州","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7672980664934025525/detail","duty":"团队介绍：中国交易与广告，基于个性化推荐、深度学习和大模型技术，依托抖音、今日头条、红果短剧、西瓜视频、番茄小说等多元产品，构建抖音电商、生活服务、广告营销等核心营收业务的算法策略和工程架构。部门运用领先的算法能力，精准连接海量用户与商家，通过推荐、广告和搜索算法精准匹配需求并促进交易达成，保障用户体验与商家权益，实现营收业务可持续增长；基于深厚的技术积累，构建高效、智能、可靠的交易与广告产品，全面提升多行业收入变现与市场占有。在这里，你将直面超大规模流量与复杂业务场景的技术挑战，深度应用业界领先的商业模型与算法技术，投身面向未来的数字营销能力建设，持续探索前沿技术。\n\n1、负责金融行业（以保险为主）B端经营与投放链路的自动化与出价/预算算法建设，围绕“目标设定—策略生成—执行控制—在线学习—效果归因”的闭环，提升投放效率与合作伙伴经营效率；\n2、出价与预算控制：建设与迭代出价、预算分配、节奏控制与成本约束策略（ROI/CPA/GMV/线索质量等目标），结合竞价机制与流量供需特性，保障稳定达成与可控波动；\n3、策略学习与自适应：结合监督学习、强化学习/上下文Bandit、因果推断与反事实评估等方法，实现策略的在线自适应、冷启动与长尾经营能力，提升长期收益与鲁棒性；\n4、自动化投放与经营策略：建设自动化建计划/关停/扩量/控量、行业/险种/人群分层策略、线索分发与承接策略、预算再分配与人群探索等能力，支持合作伙伴差异化经营目标；\n5、Agentic投放产品：探索并落地面向投放/经营场景的Agentic Workflow与智能体能力，将策略生成、工具调用（预算/出价/素材/人群/诊断）、多轮反馈与自动执行串联起来，打造“可规划、可执行、可回溯、可控”的Agentic自动化投放产品形态；\n6、诊断与归因体系：建设可观测与可解释体系，沉淀经营诊断、效果分解、异常检测、策略推荐与自动化回滚机制，提升问题定位效率与交付确定性。","requirements":"1、2027届获得本科及以上学历，计算机、数学、统计学、运筹学、经济学或相关专业优先；\n2、具备扎实的机器学习、优化算法、统计建模与数据分析基础，能将复杂经营/投放问题抽象为可建模、可评估、可迭代的算法问题；\n3、熟悉至少一种编程语言（Python/Java/C++等）与常见数据处理/建模工具，具备良好的工程实现能力与代码习惯；\n4、对竞价机制、预算与出价控制、资源分配、多目标优化/约束优化等方向有系统性理解或实践经验；\n5、具备实验设计、指标体系、效果归因与策略迭代经验，能够从海量数据中发现规律、定位根因并推动上线闭环。\n\n加分项：\n1、有出价策略、预算分配、节奏控制、MPC/PID等控制类方法在工业场景落地经验；\n2、有强化学习/因果推断等在策略优化场景的工程化经验，熟悉离线评估与在线安全探索机制；\n3、有保险/金融/B端经营平台/线索分发/商家经营等复杂业务经验，理解合规、安全与长期经营约束。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669698543337097477","sourceKey":"bytedance","company":"字节跳动","title":"珠宝行业运营 - 抖音电商","city":"上海","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669698543337097477/detail","duty":"团队介绍：抖音电商以“总能发现好东西”为主张，致力于成为用户发现丰富好物的首选平台。众多抖音创作者通过短视频、直播、商城等丰富的形式，给用户提供更个性化、更生动、更高效的消费体验。同时，抖音电商积极引入优质合作伙伴，为商家变现提供多元的选择。\n\n1、结合抖音内容特性，制定行业在抖音产品内的完整策略，根据珠宝饰品行业的特性、发展阶段及竞争趋势制定行业策略及商家在字节跳动系内的发展运营策略；\n2、对珠宝饰品行业的兴趣度高，有较强的好奇心和快速学习能力；\n3、了解抖音的短视频和直播流量规律，关注内容电商的运营模式。","requirements":"1、2027届获得本科及以上学历；\n2、数据敏感度好，有行业运营、类目运营、商品运营等实习经验优先，对平台侧商家商品运营有好奇心，有过复杂项目的支持经验；\n3、自我驱动力强，主动学习，有团队合作精神、较好的协同能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668571156576307509","sourceKey":"bytedance","company":"字节跳动","title":"后端架构工程师 - 抖音电商&直播","city":"北京/上海","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668571156576307509/detail","duty":"团队介绍：抖音电商算法团队，依托抖音、今日头条、番茄小说、红果短剧等产品，帮助用户发现、讨论并获得好物，享受美好生活；帮助商家高效经营，创建良性商业生态；激励创作并分享购物经验使用心得，构建有真诚有信息的电商内容氛围。在这个团队，我们不仅要通过推荐、广告和搜索算法搭建消费者和商家之间的桥梁，也要通过风控算法和治理算法去甄别违规行为，保护用户的购物体验，保护真正诚信经营的商家；我们还要建设智能客服技术、大规模商品知识图谱来提升各个交易环节的效率，降低商家的经营成本；我们也要结合机器学习和运筹算法，来优化供应链和物流的效率和成本，并进一步提升用户物流体验；另外我们还会用业界先进的数据科学技术为业务健康发展保驾护航。我们的使命：用算法的能力，让用户总能发现好东西，让美好生活触手可得。\n\n抖音直播算法团队，负责抖音、抖音极速版、抖音火山版等App的直播推荐算法优化，业务包括直播体裁基建和直播营收。直播体裁基建从用户侧的召回/粗排/精排/混排等模型和策略和主播侧的冷启动算法，结合多模态内容技术动态理解切片和用户兴趣，建立短视频域到直播域的兴趣迁移，在全场景分发直播体裁，满足用户看播需求并服务于营收、电商、生活服务、游戏等多业务。直播营收致力于为歌唱/舞蹈/弹奏/朗读/情感/户外等广泛的具有一技之长的普通人通过直播这个舞台被更多人看到获得收入，并满足用户多层次的精神消费和情感表达诉求，让优质内容供给持续增长反哺整个直播生态。在推荐技术方面，我们持续验证并落地全链路模型的高效scaling up方案，积极探索生成式推荐和LLM4Rec路线，提升模型系统的整体智能。\n\n1、参与电商导购链路（如物流时效、推荐理由、价格等）算法服务的后端开发，参与高QPS场景下的性能优化与稳定性建设，提升服务迭代效率；\n2、基于Flink、Spark、Kafka等技术，在商品、内容、用户等维度参与构建高效批流一体的数据处理框架，支撑复杂业务场景下的特征与数据需求；\n3、参与算法模型特征链路迭代，协助机器学习模型推理加速、在线部署与服务化运维，提升推理性能与特征时效性；\n4、围绕电商场景（物流体验、商品库、视频内容理解等），参与AI Agent系统的架构设计、开发与落地迭代，探索Agent在算法链路中的应用，沉淀可复用的技术方案。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程、大数据等相关专业；\n2、扎实掌握计算机体系结构、操作系统、计算机网络、数据库等底层基础知识，动手能力强，擅长Go/C++/Java编程语言，具备完成一个项目经验；\n3、工作积极主动、认真细致，具备良好的沟通表达与团队协作能力，能高效推进业务落地；\n4、熟悉主流大数据分布式系统架构、熟悉机器学习工程化架构、具备大模型部署与推理优化相关经验优先；\n5、具备良好的系统思维与问题拆解能力，了解设计模式、性能优化、架构设计基本方法，乐于深耕算法工程架构，有大数据平台、模型服务化项目经历优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668349808459254069","sourceKey":"bytedance","company":"字节跳动","title":"搜索算法工程师 - TikTok算法","city":"北京/上海/杭州","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668349808459254069/detail","duty":"团队介绍：TikTok搜推算法团队，负责TikTok短视频产品的基础推荐、搜索算法，加入我们，你能接触到包括搜索、用户增长、社交、直播、内容创造、内容消费等核心业务场景，直接为核心用户体验负责，支持产品在全球赛道上高速发展。我们的工作内容包括大规模推荐算法的优化、复杂约束的优化问题的解决、多模态大模型的落地，并着力研究下一代AI Search和Chatbot的核心研发技术，包括不限于Multi-Agent、Agentic RL、Harness、Loop Engineering，探索强化学习在大模型时代的新范式。在这里，你可以深入钻研机器学习算法的改进和优化，探索前沿的技术；可以感受不同文化的碰撞，激发认知；可以通过对产品和内容生态的深度分析，影响产品未来的发展方向。\n\n1、LLM for Search：探索前沿AI技术，用LLM重构搜索相关性、Query理解、内容理解、语义匹配、结果组织和体验建模，提升搜索系统对复杂意图和内容语义的理解能力；\n2、推荐大模型与搜推一体化：构建面向搜索和推荐的统一建模体系及Scaling Law，融合主动意图、长期兴趣、实时行为、内容语义和反馈信号，提升系统对用户与场景的理解能力；\n3、生成式搜索：面向复杂、开放和决策型搜索需求，研究复杂需求理解、生成式建模、LLM4Rec、Agentic Search和搜索场景下的RL/Feedback Learning，让搜索具备更强的信息组织、推荐式结果生成和任务完成能力；\n4、多模态内容理解：建模视频、图像、文本、语音、评论、标题等多源信号，让搜索系统理解内容生态，而不是只依赖文本索引；\n5、大规模搜索学习系统：研究模型训练、在线推理、持续学习、效果评估和系统效率，让前沿模型能力稳定服务全球搜索体验。","requirements":"1、2027届获得本科及以上学历，计算机、人工智能、数学、统计、电子信息等相关专业优先；\n2、算法、数据结构、机器学习和深度学习基础扎实，具备优秀的代码实现和实验分析能力；\n3、在搜索、推荐、大模型、多模态或生成式AI中至少一个方向有深入积累；\n4、能把真实产品问题抽象成可学习、可优化、可验证的算法问题，而不是只复现论文或调用框架；\n5、能在大规模数据和真实系统约束下验证算法价值，理解效果、效率和体验之间的Trade-off；\n6、对AI如何重构Search、Recommendation和Discovery有判断力，愿意挑战没有标准答案的问题。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668246248919730485","sourceKey":"bytedance","company":"字节跳动","title":"市场营销活动运营 - 抖音生活服务","city":"上海/广州","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668246248919730485/detail","duty":"团队介绍：抖音生活服务依托抖音POI （Point of Interest）、短视频、直播、搜索等，以“激发线下生意，丰富美好生活”为使命，致力于成为最值得信赖的生活服务平台，为用户提供更丰富、独特的生活体验，为合作伙伴提供包容且公平的健康营商生态。截至2025年底，抖音生活服务业务已覆盖400+城市，超过1500万家动销门店。抖音生活服务将继续携手生态伙伴，为用户提供值得心动的商品和服务。\n\n1、负责抖音生活服务城市营销相关工作，对城市交易和拉新相关指标负责；\n2、区域营销活动发起与执行，包括但不限于业务需求对接、项目策划、落地执行等，并能对所负责的活动效果负责；\n3、使用市场调研工具进行数据分析，对接拓展城市相关资源，与内外部合作伙伴进行沟通；\n4、线上通过达人、文旅、明星、商家营销、热点等资源与玩法进行内容种草，提升抖音生活服务在城市范围内的认知，对提升城市搜索相关指标负责；\n5、线下通过商家联合营销、商圈事件、城市大事件、大型市集等活动促进交易增长和拉新促活。","requirements":"1、2027届获得本科及以上学历，市场营销、广告学、新闻与传播等相关专业优先；\n2、在校期间如有内外部活动对接经验，且可独立负责市场活动策划、执行，具备应急问题处理能力优先；\n3、善于沟通，具备良好的跨部门协作能力及较高的执行力，主动进行内外部沟通，思维活跃、领悟能力强；\n4、有较强的团队合作精神，责任感强，可以快速融入工作。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667952201713977653","sourceKey":"bytedance","company":"字节跳动","title":"大模型算法工程师 - AI Platform","city":"深圳/上海","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667952201713977653/detail","duty":"团队介绍：AI Platform 团队，隶属于产品研发和工程架构部门。面向公司内部各业务线，建设统一的AI 应用基础设施和工程平台，帮助业务高效、稳定地落地大模型应用，加速 AI 产品创新。\n在平台产品侧，团队打造了新一代AgentOps平台，提供 Prompt Engineering、Agent观测、评测、数据处理、模型微调等 Agent 全生命周期解决方案，帮助Agent开发者构建效果调优的数据飞轮。产品也已成功推出商业化版本。\nAI Platform 团队还持续孵化多种面向内部与外部场景的AI应用创新产品，积极探索大模型应用的技术发展。团队氛围好，发展空间大，欢迎加入！\n\n1、参与面向AI Coding场景的研发提效项目，包括大模型、Agent效果优化等，包括模型训练、数据准备、Agent自进化、测试时计算等；\n2、参与面向内部研发场景的模型训练调优，包括CT、SFT、RL以及相应的数据工程、评测工程等；\n3、参与面向内部研发场景的Agent调优，包括上下文工程、测试时计算、记忆、知识库等；\n4、持续跟进LLM前沿技术，参与AI相关新产品功能的设计，为团队提供前沿的知识和见解。","requirements":"1、2027届获得硕士及以上学位，计算机、人工智能、自动化、数学相关专业优先；\n2、拥有AI coding相关研究经验，或拥有Agent优化、大模型训练相关实操经验者优先；\n3、拥有AI领域的研究经历，特别是在大语言模型（LLMs）和生成式人工智能等方面，在顶会上发表过论文者优先，主导过业内影响力较大的项目者优先；\n4、具备优秀的开发能力，熟练使用Vibe coding工具者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667863099529677109","sourceKey":"bytedance","company":"字节跳动","title":"效能Agent开发工程师 - 火山引擎","city":"上海","category":"测试","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667863099529677109/detail","duty":"团队介绍：火山引擎是字节跳动旗下云和AI服务平台，将字节跳动快速发展过程中积累的增长方法、技术能力和应用工具开放给外部企业，通过云和AI技术，推进企业智能化转型，激发增长潜能。\n\n1、测试Agent开发：负责测试相关Agent和相关套件工具的设计与开发工作，使其能高效应用于火山引擎平台的质量保障体系，涵盖对不同测试场景（如功能、性能、兼容性等）的适配，以提升整体测试效率与准确性；\n2、协同AI测试策略制定：深度介入火山引擎官网平台质量保障工作，与团队协作制定并推进AI相关的测试策略、计划及方法；确保测试Agent与整体测试流程紧密协同，有力保障平台产品的高质量交付；\n3、质量体系创新建设：积极投身火山引擎质量体系建设，探索质量Agent领域的创新技术与方法；结合质量要求与官网业务需求，提出前沿的Agent范式，推动测试流程向自动化、智能化迈进，全面提升测试效率。","requirements":"1、2027届获得本科及以上学历，计算机科学与技术、软件工程等相关专业；\n2、需要对大模型有深入理解，熟悉LLM技术原理与应用方法，有Agent系统设计与实现经验；了解Memory机制、RAG、工具调用、规划执行等Agent关键技术，有相关实践经验；\n3、熟练掌握Python/Java/Go等至少一门编程语言，精通计算机基础技术，熟悉测试流程、质量保证方法、目标及常用工具，并能在Agent开发与测试工作中灵活运用；\n4、需具备：在测试工具开发过程中实际应用AI技术或拥有丰富的Agent系统设计与实现经验；在顶会发表过相关论文或有开源项目贡献者优先；\n5、拥有To B相关产品或云服务产品的质量保障经验者优先，熟悉此类产品的测试特点与Agent应用场景者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667450368835422469","sourceKey":"bytedance","company":"字节跳动","title":"多模态大模型算法工程师 - TikTok Shop","city":"上海/北京","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667450368835422469/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商业务，致力于成为用户发现并获取优价好物的首选平台。面向直播电商、视频内容电商、货架电商等多元购物场景，国际电商持续为全球用户提供更个性化、更主动、更高效的消费体验，也为商家提供稳定、可靠、可持续增长的平台服务，推动“新奇好物畅销全球，美好生活触手可得”的使命落地。\n目前，国际电商算法团队分布在中国、美国、新加坡等多个国家和地区，深度参与全球化业务建设。加入我们，你将有机会面向全球用户、商家和商品生态，与跨区域的产品、工程、运营和业务团队协作，持续提升商品供给质量、用户购物体验、平台交易效率与履约体验，共同探索内容电商与智能购物的新模式。\nData-国际电商团队是 TikTok Shop 的核心算法技术力量，专注于电商场景下的算法创新与规模化落地，方向包括但不限于：生成式推荐与大规模 Foundation Model、多模态商品理解与内容生成、搜索与导购、智能客服、风控治理、物流履约优化、商家经营智能化，以及 Agentic 智能体在电商全链路中的应用。我们希望通过先进的算法能力，帮助用户更高效地发现感兴趣的商品，帮助商家实现更高质量的经营增长，并持续提升交易各环节的智能化水平。\n在这里，你将与一流的产品和技术团队合作，面对复杂且真实的国际化电商挑战，推动前沿技术在大规模业务场景中落地，与团队一起创造更多可能。\n\n1、多模态大模型算法研发：构建电商领域的多模态大模型底座，融合电商的知识，快速落地电商业务，例如：沉淀电商大模型预训练链路，研发电商图文或者视频多模态大模型和相关应用链路；\n2、基础算法研发：持续建设和深耕CV/多模态基础预训练算法，例如：沉淀&优化电商场景的预训练模型，基于电商图片/视频自监督，适配电商商品的多模态表征学习等；\n3、梳理&沉淀算法库，抽象算法接口，最大化提高算法/预训练模型的复用率，同时优化数据采集&模型训练&部署&推理的流程，提升研发效率；\n4、技术输出：定期分享SOTA模型，赋能电商甚至公司级别的业务BU，沉淀专利和论文。","requirements":"1、2027届获得本科及以上学历，人工智能、计算机、数学相关专业优先；\n2、扎实的机器技术基础，了解前沿的AI技术；发表过高水平学术会议论文或者有竞赛经验者优先；在Kaggle，COCO，ImageNet，ActivityNet等比赛获奖者优先；有顶级学术会议（如CVPR、ICCV、ECCV等）发表论文者优先；\n3、熟悉多模态大模型工作优先，包括但不限于Llava，Mini-Gemini，Qwen-VL，Shikra等；\n4、在多媒体和计算机视觉某个领域有较深入的研究，包括但不限于：图像搜索、图像/视频分类和识别、图像分割、目标检测、图文多模态模型、和视频文本多模态模型等；\n5、有CV/多模态大模型相关项目经验优先；研发&优化电商视频&商品多模态大模型，结合LLM和视频/商品表征，支持视频多模态分类，视频QA，跨模态检索，商品分类等任务，显著超越线上模型；\n6、有较强的实践能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7666064710523455749","sourceKey":"bytedance","company":"字节跳动","title":"PMO技术项目经理 - 抖音研发","city":"北京","category":"项目管理","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7666064710523455749/detail","duty":"团队介绍：抖音研发部门负责多款大型产品的研发，包括但不限于抖音、西瓜视频、汽水音乐。加入我们，你将有机会参与亿级用户场景的开发与架构工作，使用前沿的技术助力业务一起不断成长。\n\n1、协助抖音产品研发团队，跟进项目，协助完成相关项目的流程设计、执行落地、总结改进等；\n2、针对团队协作中发现的问题，归纳总结，协助改进；\n3、帮助团队进行日常通用任务的管理，有效地跟进、推动，确保交付；\n4、在日常过程中，推动团队进行知识库的沉淀、归档等。","requirements":"1、2027届获得本科及以上学历，计算机、通信和电子信息科学、数学等相关专业优先；\n2、有较强的沟通能力，良好的与人交流协作的能力；\n3、有较高的责任心，以及目标导向的落地执行能力、问题解决能力；\n4、乐意迎接变化接受挑战，持续学习，自律。\n\n加分项：\n1、英语流利、热爱项目管理、技术背景。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7665250565488609541","sourceKey":"bytedance","company":"字节跳动","title":"Agentic AI研发工程师（架构方向） - TikTok研发","city":"深圳","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7665250565488609541/detail","duty":"团队介绍：TikTok研发团队，旨在实现TikTok业务的研发工作，搭建及维护业界领先的产品。加入我们，你能接触到包括用户增长、社交、直播、电商C端、内容创造、内容消费等核心业务场景，支持产品在全球赛道上高速发展；也能接触到包括服务架构、基础技术等方向上的技术挑战，保障业务持续高质量、高效率、且安全地为用户服务；同时还能为不同业务场景提供全面的技术解决方案，优化各项产品指标及用户体验。 \n在这里， 有大牛带队与大家一同不断探索前沿， 突破想象空间。 在这里，你的每一行代码都将服务亿万用户。在这里，团队专业且纯粹，合作氛围平等且轻松。目前在北京，上海，杭州、广州、深圳分别开放多个岗位机会。\n\n1、我们正在寻找对Agentic AI充满热情、具备优秀技术潜力的应届毕业生。你将参与智能体核心能力与产品的研发，探索大模型在任务规划、工具调用、记忆、推理、多智能体协作和自主执行等方向的落地；\n2、参与Agentic AI系统的设计与研发，包括任务规划、工具调用、记忆管理、上下文工程、多智能体协作等核心能力，研究并落地大模型推理、RAG、工作流编排、模型评测及强化学习等相关技术；\n3、构建面向真实业务场景的智能体产品，持续提升任务成功率、执行效率、稳定性和用户体验，建设智能体评测体系，分析复杂任务中的失败原因，推动模型、策略和工程架构持续迭代；\n4、跟进Agentic AI领域前沿进展，将优秀论文、开源项目和技术方案转化为可验证的产品能力；\n5、与产品、算法及工程团队紧密协作，推动智能体能力规模化应用。","requirements":"1、2027届获得本科及以上学历，计算机、人工智能、软件工程、数学等相关专业优先；\n2、具备扎实的计算机基础，熟悉数据结构、算法、操作系统、计算机网络及软件工程；\n3、熟练掌握Python、Go、Java、C++、TypeScript中至少一种编程语言；\n4、了解大语言模型基本原理，熟悉Prompt Engineering、RAG、Function Calling、Agent Framework等技术；\n5、具备较强的工程实现能力，能够独立完成技术调研、原型开发、实验评估和问题定位；\n6、对复杂问题有强烈好奇心，具备清晰的逻辑分析能力和持续学习能力；认可快速实验、数据驱动和结果导向的研发方式。\n\n加分项：\n1、参与过Agent、RAG、大模型应用或模型训练相关项目；\n2、熟悉LangGraph、AutoGen、OpenAI Agents SDK、Claude Code、MCP、A2A等框架或协议；\n3、具备模型微调、强化学习、推理优化或智能体评测经验；\n4、在人工智能相关会议发表过论文，或在高水平竞赛中取得优秀成绩；有高质量开源项目、技术博客或活跃的开源社区贡献；在实习、科研或个人项目中独立解决过具有挑战性的真实问题。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7687906361073551669","sourceKey":"bytedance","company":"字节跳动","title":"AI Agent质量效能工程师 - Seed 产品研发","city":"北京/深圳/杭州/上海","category":"测试","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7687906361073551669/detail","duty":"团队介绍：产品研发和工程架构-Seed 团队深耕大模型技术在场景中的创新应用，负责多款AI产品的工程研发 —— 包括豆包、飞书、豆包工作、豆包爱学、Gauth、猫箱等创新产品，覆盖消费级与企业级多个场景。我们致力于将大模型能力从 \"生成内容\" 推进到 \"完成工作\"，让 AI 服务用户日常与企业协作。你将面对多模态交互、工具调用可靠性、企业级数据安全等真实工程挑战，与团队一起推动 AI 生产力落地。\n\n1、参与飞书AI Harness质量系统的构建与演进，围绕服务端、Web端、移动端及AI相关能力，建设面向真实业务场景的自动化验证、评测执行、结果分析与质量闭环能力；\n2、参与团队AI质量体系与工程体系建设，包括但不限于自动化评测、流程验证、持续集成、上线准入与质量门禁等；\n3、面向AI场景设计质量方案，覆盖结果质量、过程质量与系统稳定性，提升问题发现效率与质量反馈速度；\n4、参与线上问题追踪、归因分析与质量数据建设，推动问题从发现、定位到修复验证的闭环提效；\n5、参与通用质量工具、评测脚本与效率平台建设，提升团队在复杂业务和AI场景下的验证效率。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程、人工智能、自动化等相关专业优先；\n2、熟练使用至少一种AI编程工具，包含但不限于Claude、Codex、TRAE等，能够将AI能力应用于自动化验证、评测脚本开发、问题分析与质量效率优化等场景，具备基础的编程能力，至少熟悉一门常用开发语言，包括但不限于Python、Golang、Java、C/C++等，有脚本开发、工具开发或工程实践经验者优先；\n3、具备扎实的计算机基础知识，了解网络通信基础，包括TCP/IP、HTTP等常见协议，了解常见的自动化方法、数据驱动验证思路或持续集成流程，有质量工具、评测平台、自动化流程或工程效率建设经验者优先；\n4、对AI产品质量、自动化验证、评测体系或工程效率方向有兴趣，理解除“结果是否正确”之外，还需要关注“过程是否可控、系统是否稳定、反馈是否高效”；\n5、了解常见算法评测方法与客观评估指标，有大模型、搜索、NLP、语音、多模态等相关评测经验者优先；\n6、具备良好的问题分析与协作能力，能够从业务、流程与系统多个层面推动质量与效率持续优化。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7670756030309435701","sourceKey":"bytedance","company":"字节跳动","title":"服务商渠道经理 - 抖音生活服务","city":"北京/上海","category":"销售","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7670756030309435701/detail","duty":"团队介绍：抖音生活服务依托抖音POI （Point of Interest）、短视频、直播、搜索等，以“激发线下生意，丰富美好生活”为使命，致力于成为最值得信赖的生活服务平台，为用户提供更丰富、独特的生活体验，为合作伙伴提供包容且公平的健康营商生态。截至2025年底，抖音生活服务业务已覆盖400+城市，超过1500万家动销门店。抖音生活服务将继续携手生态伙伴，为用户提供值得心动的商品和服务。\n\n1、负责抖音生活服务服务商的日常管理，包括但不限于准入、考核、清退、风控等，保障服务商日常运营，推动达成业绩目标；\n2、为服务商制定合理的生活服务行业商家运营方案，提供活动、团单设计与运营支持，维护良好合作关系，做好交易额提升优化；\n3、持续研究抖音生活服务行业经营策略，分析服务指标，明确服务商能力现状，制定提升方向并定期复盘，沉淀输出经营方法论；\n4、分析服务商团队架构、经营人效等，根据业务发展规划，给予合理意见，组织并实施服务商团队技能培训和赋能，提升服务商团队作战力；\n5、充分了解市场现状，整合、协调内外部资源，推动整体策略方案输出落地。","requirements":"1、2027届获得本科及以上学历；\n2、具备良好的客户开拓和服务能力，以及建立良好的客户群体关系的能力；\n3、掌握商务谈判、沟通及文字写作表达交流技巧，具有一定的市场洞察力和执行力，项目统筹能力和跨团队协作能力；\n4、性格开朗，敢于面对挑战，具有开拓精神。\n\n加分项：\n1、在本地生活赛道，拥有渠道销售/项目运营等经验；具备数据分析能力，可以搭建数据看板并分析汇报，具备数据洞察和业务洞察力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7670755833004804405","sourceKey":"bytedance","company":"字节跳动","title":"服务商渠道经理 - 抖音生活服务","city":"北京","category":"销售","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7670755833004804405/detail","duty":"团队介绍：抖音生活服务依托抖音POI （Point of Interest）、短视频、直播、搜索等，以“激发线下生意，丰富美好生活”为使命，致力于成为最值得信赖的生活服务平台，为用户提供更丰富、独特的生活体验，为合作伙伴提供包容且公平的健康营商生态。截至2025年底，抖音生活服务业务已覆盖400+城市，超过1500万家动销门店。抖音生活服务将继续携手生态伙伴，为用户提供值得心动的商品和服务。\n\n1、负责抖音生活服务服务商的日常管理，包括但不限于准入、考核、清退、风控等，保障服务商日常运营，推动达成业绩目标；\n2、为服务商制定合理的生活服务行业商家运营方案，提供活动、团单设计与运营支持，维护良好合作关系，做好交易额提升优化；\n3、持续研究抖音生活服务行业经营策略，分析服务指标，明确服务商能力现状，制定提升方向并定期复盘，沉淀输出经营方法论；\n4、分析服务商团队架构、经营人效等，根据业务发展规划，给予合理意见，组织并实施服务商团队技能培训和赋能，提升服务商团队作战力；\n5、充分了解市场现状，整合、协调内外部资源，推动整体策略方案输出落地。","requirements":"1、2027届获得本科及以上学历；\n2、具备良好的客户开拓和服务能力，以及建立良好的客户群体关系的能力；\n3、掌握商务谈判、沟通及文字写作表达交流技巧，具有一定的市场洞察力和执行力，项目统筹能力和跨团队协作能力；\n4、性格开朗，敢于面对挑战，具有开拓精神。\n\n加分项：在本地生活赛道，拥有渠道销售/项目运营等经验；具备数据分析能力，可以搭建数据看板并分析汇报，具备数据洞察和业务洞察力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7670124452865378565","sourceKey":"bytedance","company":"字节跳动","title":"服务策略 - 体验与服务","city":"北京","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7670124452865378565/detail","duty":"团队介绍：体验与服务部门是为用户的体验和服务负责。关心用户的诉求，通过智能化和人工能力，帮助用户解决问题；基于问题洞察，协同产品提升用户体验，促进业务长期发展。\n\n1、负责用户服务策略制定，对抖音用户服务场景的服务类指标负责，包括但不限于智能服务解决率、人工服务解决率、转人工率等；\n2、推动AI大模型在智能服务方向的探索和落地，使抖音的用户服务在行业内处于领先水平；\n3、重点统筹智能服务策略，优化智能侧的服务流程、产品交互设计、用户意图识别及优化解决方案，沉淀运营标准，提升智能解决能力；\n4、搭建智能服务全链路指标体系，监控数据异常及时应对和部署，同时通过数据分析识别业务问题、推动解决。","requirements":"1、2027届获得本科及以上学历；\n2、对智能服务和AI大模型有较高的热情和好奇心；有敏锐的问题洞察能力及良好的逻辑思考能力；\n3、有良好的书面和口头表达能力，具备良好的沟通与团队协同意识，能有效推进跨团队合作；\n4、具备强烈的好奇心、同理心，具有换位思考的意识和能力，有韧性、有上进心。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669690054541150517","sourceKey":"bytedance","company":"字节跳动","title":"大客户销售（互动影视） - 商业化","city":"北京/上海/广州","category":"销售","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669690054541150517/detail","duty":"团队介绍：抖音集团商业化是抖音集团旗下的综合数字化营销服务平台，致力于让不分行业、地域的企业及个体都能通过数字化技术激发创造、驱动生意，实现商业的可持续增长。\n\n1、按照商业化战略规划，负责消费品行业、互动影视、互动应用、互动娱乐（游戏）、金融、电商平台、教育行业、MCN及达人等方向的客户的开拓与维护工作；\n2、与企业建立深度合作关系，完成既定销售指标；\n3、与公司关联部门沟通协作，确保广告的及时投放与问题反馈、广告资源的合理利用与开发；\n4、通过数据分析客户需求，为客户提供咨询服务、产品培训、优化投放、数据分析等营销策略，制定整合营销方案及策略，推动各行业营销策略的实施。","requirements":"1、2027届获得本科及以上学历；\n2、热爱销售工作，具备良好的客户开拓和服务能力，以及建立良好的客户群体关系的能力；\n3、掌握商务谈判、沟通及文字写作表达交流技巧，具有一定的市场洞察力和执行力；\n4、性格开朗，敢于面对挑战。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669688946746165557","sourceKey":"bytedance","company":"字节跳动","title":"广告履约运营 - 商业化","city":"北京/上海","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669688946746165557/detail","duty":"团队介绍：抖音集团商业化是抖音集团旗下的综合数字化营销服务平台，致力于让不分行业、地域的企业及个体都能通过数字化技术激发创造、驱动生意，实现商业的可持续增长。\n\n1、负责国内销售业务平台客户/代理商/服务商全生命周期的履约服务，建设智能化客户服务链路，运用AI、API等工具优化签约合作、合同拟定、投放策略、资金安全、结算回款、退款清退等全流程，提升业务运转效率；\n2、挖掘商业化营销合作及品牌投放链路中的流程痛点，运用AI思维诊断业务风险，并提出可行性分析和优化方案，输出智能化资源组合推荐、售卖流程优化、效率提升及服务改进方案；\n3、协同战略、销售、产品、法财税等团队，通过AI赋能、系统迭代、智能工具搭建，推动业务合规落地，打造更智能、高效的商业化服务体验。","requirements":"1、2027届获得本科及以上学历；\n2、较强的学习能力、自驱力和良好的团队合作意识，具备出色的内外部沟通协作能力和资源整合能力，能有效参与和推动重大平台的应用落地；沟通协调能力强，逻辑清晰，责任心强，工作积极主动，乐于从业务一线沉淀经验，赋能商业化智能化升级；\n3、对AI技术抱有浓厚兴趣，愿意主动探索AI、API工具在业务场景的落地应用；\n4、具备流程梳理、问题洞察能力，擅长用智能化思路优化履约业务与服务体验。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669684016106981685","sourceKey":"bytedance","company":"字节跳动","title":"后端开发工程师 - 中国交易与广告","city":"北京","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669684016106981685/detail","duty":"团队介绍：中国交易与广告，基于个性化推荐、深度学习和大模型技术，依托抖音、今日头条、红果短剧、西瓜视频、番茄小说等多元产品，构建抖音电商、生活服务、广告营销等核心营收业务的算法策略和工程架构。部门运用领先的算法能力，精准连接海量用户与商家，通过推荐、广告和搜索算法精准匹配需求并促进交易达成，保障用户体验与商家权益，实现营收业务可持续增长；基于深厚的技术积累，构建高效、智能、可靠的交易与广告产品，全面提升多行业收入变现与市场占有。在这里，你将直面超大规模流量与复杂业务场景的技术挑战，深度应用业界领先的商业模型与算法技术，投身面向未来的数字营销能力建设，持续探索前沿技术。\n\n1、负责架构设计和开发，为亿级用户提供优质顺畅的信息服务和极致体验；\n2、参与设计系统技术方案，核心代码开发和系统调优；\n3、参与制定代码规范、测试规范，建立起开发质量控制方法；\n4、协助团队攻克各种高并发、数据隔离、系统解耦等方面的技术难关；\n5、参与各专项技术调研，新技术引入等前瞻项目；\n6、参与机器学习与异构计算系统研发。","requirements":"1、2027届获得本科及以上学历，计算机相关专业优先；\n2、至少熟悉一种主流编程语言（Go/Java/C++），有扎实的编程能力和良好的编码风格；\n3、熟悉Linux操作系统和开发环境，有良好的数据结构、算法基础和系统设计能力；\n4、善于沟通，工作积极主动，责任心强，具备良好的团队协作能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668527393919437061","sourceKey":"bytedance","company":"字节跳动","title":"网络工程师 - AI算力基础设施","city":"北京","category":"基础架构","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668527393919437061/detail","duty":"团队介绍：字节跳动基础设施部门，负责字节跳动的全栈算力基础设施，从芯片服务器产研、到超大规模数据中心，到传统云平台和如今的AI Native Cloud，全方位为抖音、豆包、今日头条、飞书、火山引擎等各类产品提供领先、稳定的百万量级大规模算力基础设施服务。我们的领域涵盖数据中心建设、内核操作系统开发、服务器集群管理、高速网络通信、EB级数据存储体系、搜索型数据库探索、基于LLM的AI基础设施的研发调度与治理等，致力于打造业界领先的、面向LLM的AI云原生基础设施架构与产品矩阵。\n\n1、负责抖音集团和火山引擎数据大规模AI集群网络设施的规划、设计和运维工作；\n2、参与大规模AI集群网络设施的自动化平台的设计和落地工作；\n3、负责公网和专线的带宽容量，资源排布等规划以及成本管理工作。","requirements":"1、2027届获得本科及以上学历，网络工程、通信工程和计算机等相关专业优先；\n2、具备一定的数据分析能力，掌握至少一门开发语言，如Python、Golang等；\n3、熟悉如TCP/IP、BGP等常用网络协议，有校园网建设和维护经验优先；\n4、具有CCIE/HCIE、RHCE或者同等能力证书优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667950077989980469","sourceKey":"bytedance","company":"字节跳动","title":"Agent数据&评测工程师 - AI Platform","city":"北京/上海/杭州","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667950077989980469/detail","duty":"团队介绍：AI Platform 团队，隶属于产品研发和工程架构部门。面向公司内部各业务线，建设统一的AI 应用基础设施和工程平台，帮助业务高效、稳定地落地大模型应用，加速 AI 产品创新。\n在平台产品侧，团队打造了新一代AgentOps平台，提供 Prompt Engineering、Agent观测、评测、数据处理、模型微调等 Agent 全生命周期解决方案，帮助Agent开发者构建效果调优的数据飞轮。产品也已成功推出商业化版本。\nAI Platform 团队还持续孵化多种面向内部与外部场景的AI应用创新产品，积极探索大模型应用的技术发展。团队氛围好，发展空间大，欢迎加入！\n\n1、深入探索LLM在编程、个人助理等各种场景中的应用，支持TRAE、扣子等业务的端到端评测工作，参与Agent评测、调优和自迭代等相关工作；\n2、制定评测标准，开发评测Agent，建设自动化评测基础设施，同时通过数据分析与算法改进，持续探索创新的评测方法；\n3、构建大规模高质量的数据（数据建设、数据抓取与解析、数据合成等），提出更好的Benchmark，度量Agent和模型能力；\n4、关注行业动态与技术趋势，及时引入新的技术和理念，协同团队参与校企横向项目、学术论坛会议、发布论文等，协助团队构建学术界影响力。","requirements":"1、2027届获得本科及以上学历，计算机科学、人工智能、数学等相关专业优先；\n2、具备优秀的编码能力，扎实的数据结构和算法功底，至少熟练掌握C/C++/Go/Python一种开发语言；\n3、有Agent开发或复杂场景评测经验者优先，在相关顶级会议发表过论文者优先；\n4、具备优秀的学习能力且对探索未知领域有强烈兴趣，具备优秀的问题解决能力与自驱力者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667854716023195909","sourceKey":"bytedance","company":"字节跳动","title":"AI经纪人产品经理（抖音AI产品人才校招） - 抖音直播","city":"北京/深圳","category":"产品","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667854716023195909/detail","duty":"团队介绍：直播团队为抖音在内的字节跳动多款产品提供直播支持。在直播间里，时空的隔阂被打破，五湖四海的人们连接在一起，共同见证、分享、传递生活中的美好。美好的定义不尽相同，越来越多的人在抖音直播里寻找自己向往的美好，拥抱理想生活。960万平方公里的美好现场，尽收直播间。直播团队，期待你的加入！​\n\n这是抖音面向具备AI能力的同学发起的校招项目，覆盖产品、策略运营方向。\nAI 正在重新定义产品，也在重新定义\"做产品\"这件事 —— AI Native 的产品，需要你既能理解大模型技术边界，又能定义产品价值。\n如果你也有着许多的奇思妙想， 欢迎加入抖音，把想法落地成亿万用户真实可感的产品体验，来抖音，和我们一起探索 AI 产品的下一种可能！\n\n1、深入抖音直播业务，洞察主播、机构、运营等不同角色需求，探索AI Agent在直播全生命周期中的应用机会；\n2、参与AI经纪人产品设计，包括主播孵化、直播策略、内容分析、经营诊断、复盘总结、智能问答等核心能力建设；\n3、与算法、工程、设计、运营等团队紧密合作，推动大模型能力在真实业务中的落地，打造高可用、高体验的AI产品；\n4、基于用户反馈和业务数据，持续优化AI Agent的效果，包括建议采纳率、任务完成率、用户满意度等核心指标；\n5、跟踪全球AI Agent、大模型、多模态等前沿技术发展，结合直播业务持续探索创新方向。","requirements":"1、2027届获得本科及以上学历，专业不限，计算机、人工智能、数据科学、信息管理、工业设计、心理学、传播学等相关专业优先；\n2、对AI、大模型、Agent、AIGC等方向充满兴趣，关注行业最新发展；\n3、具备优秀的逻辑分析能力和用户洞察能力，能够快速理解复杂业务并抽象产品方案；\n4、良好的沟通协作能力，善于推动跨团队合作，高效解决问题；\n5、对直播、电商、内容社区或创作者生态有兴趣或相关实践经验者优先；\n6、有AI产品、Prompt Engineering、智能体、产品设计、数据分析等项目经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667850499396651269","sourceKey":"bytedance","company":"字节跳动","title":"抖音星图产品经理（抖音AI产品人才校招） - 抖音品牌营销与星图达人","city":"北京","category":"产品","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667850499396651269/detail","duty":"团队介绍：品牌营销与星图达人为抖音、今日头条等全产品矩阵提供一体化品牌与达人营销解决方案，助力品牌实现精准触达与高效增长。依托行业领先的达人匹配算法、全链路数据洞察能力及创新的品牌营销产品和样式，我们打破内容与商业的壁垒，让品牌营销更具创意、更显精准、更有温度。\n在这里，你将深度参与全球领先的达人营销生态建设，接触行业前沿的AI与营销产品结合、创新的品牌营销策略。你将与顶尖团队并肩，在品牌广告与达人营销的创新浪潮中，不断探索品牌营销的新可能，在数字营销领域快速成长。\n\n这是抖音面向具备AI能力的同学发起的校招项目，覆盖产品、策略运营方向。\nAI 正在重新定义产品，也在重新定义\"做产品\"这件事 —— AI Native 的产品，需要你既能理解大模型技术边界，又能定义产品价值。\n如果你也有着许多的奇思妙想， 欢迎加入抖音，把想法落地成亿万用户真实可感的产品体验，来抖音，和我们一起探索 AI 产品的下一种可能！\n\n1、负责内容策略&达人推荐策略的AI Agent产品，依托大模型深入理解客户需求，为客户的达人营销方案提供内容策略、达人推荐策略等；\n2、完成从数据接入、数据清洗、策略制定等全流程的产品能力建设，为策略的有效性和客户的实际投放效果负责；\n3、及时收集客户、达人、业务团队的推广反馈，并提炼产品优化建议，推进产品的持续迭代优化；\n4、定义产品理想体验与核心指标，通过AI能力（如Prompt工程、RAG应用）优化内容分发；搭建科学的策略迭代框架，推动策略效果持续提升。","requirements":"1、2027届获得本科及以上学历；计算机、数学、统计等相关专业；\n2、有达人营销、内容创意相关产品经验优先；具备策略设计能力，有AI相关产品经验，能有完整的视角串联上下游，保证产品能力的完整性和有效性；\n3、有良好的逻辑思维能力、数据分析能力和业务解读能力，并对客户需求有高敏感度；\n4、具备较高的工作热情，有较强的自我驱动能力，能主动发现问题、解决问题、达成目标；\n5、与模型算法、工程技术、评测和标注等团队紧密协作，对齐大模型应用技术边界与产品需求，驱动产品持续迭代进化，保持产品竞争力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667541378700642565","sourceKey":"bytedance","company":"字节跳动","title":"富文本编辑器AI产品经理（抖音AI产品人才校招） - 抖音运营","city":"北京/上海","category":"产品经理","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667541378700642565/detail","duty":"团队介绍：负责抖音知识，兴趣，消费，生活，娱乐等垂类的创作者运营，主要目标为提升抖音内容供给，探索多元化的作者变现和商业模式，促进多领域的创作者更好地在平台经营和成长。同时也包括抖音中长视频、演出相关业务。\n\n这是抖音面向具备AI能力的同学发起的校招项目，覆盖产品、策略运营方向。\nAI 正在重新定义产品，也在重新定义\"做产品\"这件事 —— AI Native 的产品，需要你既能理解大模型技术边界，又能定义产品价值。\n如果你也有着许多的奇思妙想， 欢迎加入抖音，把想法落地成亿万用户真实可感的产品体验，来抖音，和我们一起探索 AI 产品的下一种可能！\n\n1、负责AI富文本原生编辑器的产品设计，跑通「自然语言输入—AI生成/修改—差异对比—局部采纳/合并—撤销与版本追溯」的人机协同编辑链路；\n2、负责通用Agent框架建设及编辑器内容模型设计，包括意图分类与路由、上下文和状态管理、任务编排、工具调用以及异常兜底，支持不同业务意图快速接入和独立迭代；设计编辑器内容模型及Agent读写协议，推动文本内容的结构化提炼、可视化表达和多场景复用，打通创作、编辑与消费体验；\n3、建立Agent及编辑器效果指标，持续优化意图识别准确率、任务完成率、工具调用成功率、编辑采纳率和响应效率；\n4、协同算法、研发及业务产品团队，推动复杂AI能力从方案设计到上线落地。","requirements":"1、2027届获得本科及以上学历，计算机、人工智能、大数据等相关专业优先；\n2、熟悉大模型和Agent产品原理，理解意图路由、上下文管理、Function Calling、工具调用和工作流编排，能够结合执行轨迹定位问题；\n3、具备良好的数据意识和产品判断力，能够建立评测标准并持续推动效果迭代；\n4、具备较强的用户洞察、逻辑分析和项目推动能力，能够高效协同算法、研发及业务团队。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667090366638295349","sourceKey":"bytedance","company":"字节跳动","title":"广告模型算法工程师 - Commercial AI","city":"北京/上海/杭州","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667090366638295349/detail","duty":"团队介绍：Commercial AI隶属于国际化广告（国际化商业产品与技术），聚焦在商业化场景下的AI研发与创新，包括围绕广告场景，探索超长序列复杂模型、生成式推荐和 AI 广告素材生成等核心能力。简化产品流程，提升客户体验，并推动广告系统从素材生成到推荐建模的持续升级，助力广告效果提升和收入增长。\n\n1、参与/负责字节跳动国际化业务广告投放算法，深入研究并改进工业级深度学习排序架构，提升系统变现效率，优化客户体验；\n2、端到端的参与/负责大规模广告投放系统全链路的优化，包括召回/粗排/精排等，基于模型优化，提升海量数据、超大参数背景下的广告系统变现效率；\n3、广告投放系统的通用算法创新与改进，结合因果推断、序列建模、多模态、强化学习等技术，突破现有架构瓶颈，解决广告投放模型侧的长期痛点问题。","requirements":"1、2027届获得本科及以上学历，计算机、机器学习和模式识别相关专业；\n2、热爱计算机科学和技术，对人工智能类产品有浓厚兴趣；\n3、具备编码能力，熟悉Linux开发环境，熟悉C++和Python语言优先；\n4、有扎实的数据结构和算法功底，熟悉机器学习、自然语言处理、数据挖掘、分布式计算、计算机视觉、计算机图形、语音识别与合成中一项或多项；\n5、对推荐系统、计算广告、搜索引擎、对话问答、图像和视频分析处理相关技术有经验者优先；\n6、优秀的分析问题和解决问题的能力，对解决具有挑战性问题充满激情。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7665702229265041669","sourceKey":"bytedance","company":"字节跳动","title":"渲染引擎研发工程师（AI agent方向） - TikTok研发","city":"上海","category":"多媒体","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7665702229265041669/detail","duty":"团队介绍：TikTok研发团队，旨在实现TikTok业务的研发工作，搭建及维护业界领先的产品。加入我们，你能接触到包括用户增长、社交、直播、电商C端、内容创造、内容消费等核心业务场景，支持产品在全球赛道上高速发展；也能接触到包括服务架构、基础技术等方向上的技术挑战，保障业务持续高质量、高效率、且安全地为用户服务；同时还能为不同业务场景提供全面的技术解决方案，优化各项产品指标及用户体验。 \n在这里， 有大牛带队与大家一同不断探索前沿， 突破想象空间。 在这里，你的每一行代码都将服务亿万用户。在这里，团队专业且纯粹，合作氛围平等且轻松。目前在北京，上海，杭州、广州、深圳分别开放多个岗位机会。\n\n1、参与设计和开发企业级Agent系统，实现自动化规划、任务拆解及执行，服务特效创作工具、游戏生成等应用场景；\n2、推动Agent系统对复杂任务的规划和拆解，不断优化Agent解决实际问题的路径和效果；\n3、参与Agent评测调优，识别瓶颈和问题，通过Prompt工程优化、Skill等调优手段，持续改进Agent的准确性和可用性；\n4、持续关注大模型、智能体开发以及安全领域的前沿技术动态，收集相关技术信息，为团队引入新技术、新方法提供参考，助力团队保持技术先进性。","requirements":"1、2027届获得本科及以上学历，计算机、人工智能等相关专业优先；\n2、扎实的计算机、编程基础，熟悉主流大语言模型的原理及方法；\n3、熟悉Web前端（TS/Vue/React等）或后端（Node.js/Python/Java等），有全栈开发经验优先，熟练运用任一AI Coding工具（TRAE/Claude Code/Codex等）；\n4、逻辑清晰，善于总结归纳，能够通过观察和数据发现问题；\n5、热爱AI相关技术，对应用和落地工程感兴趣，富有钻研创新精神。\n\n加分项：\n1、拥有大量Prompt实践和优化经验；\n2、有LLM应用/Agent开发经验，了解Function Call、RAG、Eval、Multi-Agent等任一方向；\n3、有Multi-Agent系统搭建实践经验或Agent落地应用经验；\n4、有游戏引擎的实践经验，如：Unity、UE、Godot、Cocos等；\n5、对技术有较大的热情，学习能力强，责任心强，工作认真细致，具备良好的服务意识，具有良好的团队沟通与协作能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7665569665583319301","sourceKey":"bytedance","company":"字节跳动","title":"安全工程师（电商商家） - 中国交易与广告","city":"上海","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7665569665583319301/detail","duty":"团队介绍：中国交易与广告，负责抖音电商、生活服务、广告营销等营收业务的研发。用技术带来美好生活，让用户发现更多优价好物，为用户提供更丰富独特的生活体验；连接海量用户与商家，促进交易达成，让生态里全流程体验更流畅，助力营收业务长效增长。\n加入团队，你将投身流量与增长主战场，挑战复杂业务场景技术难题；直面真实商家和用户，用技术解决看得见的问题，在实战中快速成长，书写属于你的价值故事！\n\n1、参与电商安全防御实战及红蓝对抗演练项目；\n2、有效对接安全研发团队，将前沿攻防经验沉淀为产品、工具等自动化服务模块；\n3、研究并跟进最新的安全漏洞与安全动态，并能够分析定性对电商业务的实际影响。","requirements":"1、2027届获得本科及以上学历，计算机相关专业；\n2、有过作为一线技术成员深度参与攻防赛事的经验，熟悉当下攻防流行的各类漏洞的原理及利用；\n3、熟悉Java漏洞挖掘及利用，挖掘过国内外常见的Java项目；\n4、熟悉开发测试流程，熟练掌握Go/Python，具备扎实的开发技能基础，熟悉常用的开发协作流程者优先；\n5、具有自我思考和理解能力，能够独立分析问题及提出解决方案；\n6、善于跨团队沟通和协调，具备良好的团队意识和自驱力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7664518280353138949","sourceKey":"bytedance","company":"字节跳动","title":"搜索大模型训练/推理工程师 - 搜索架构","city":"北京/杭州/上海","category":"机器学习","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7664518280353138949/detail","duty":"团队介绍：作为字节跳动核心业务的技术引擎，搜索架构部门致力于构建全球领先的大规模智能搜索架构，支撑抖音、电商等业务的飞速发展。在抖音等短视频生态与电商业务，我们直面千亿级数据规模下的复杂工程挑战。团队深耕检索架构、分布式系统、模型工程与特征工程四大核心领域。我们通过技术创新驱动人与信息的高效连接，服务全球数亿用户的大规模搜索需求，打造极致的搜索体验。\n\n1、完成LLM训练、推理技术在搜索大模型场景的研发、落地和调优，解决推荐场景的大模型工程问题；\n2、针对PyTorch、TensorFlow等框架提供高自动化、极致性能的模型优化方案；\n3、推动基于大模型开源组件构建，设计和实现新一代推荐系统架构，支持推荐大模型在业务落地；\n4、与算法团队Co-Design，推动端到端生成式推荐技术创新的预研和落地。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程等相关专业优先；\n2、扎实的编程和算法基础，熟练掌握C/C++、Python、Java等编程语言，有CUDA开发经验，熟悉TensorRT/Triton/CUTLASS经验者优先；\n3、熟悉大模型推理加速的研究和技术进展，包括但不限于模型量化、图编译、算子调优、KVCache、PD分离等；\n4、掌握LLM训练/推理技术，有实际开发和应用落地经验，例如Megatron、DeepSpeed、vLLM、SGLang、TRT-LLM等；\n5、对大模型工程有丰富的经验和广阔视野，紧追开源动态，具备独立的Troubleshooting能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7663044797028960517","sourceKey":"bytedance","company":"字节跳动","title":"安全运营工程师 - 安全与风控","city":"深圳","category":"安全","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7663044797028960517/detail","duty":"团队介绍：我们团队致力于通过对攻防技术的持续研究，最大限度降低零日漏洞与安全事件造成的影响。我们提供红队演练、威胁检测、安全保障工具支持及事件调查等服务，助力提升系统韧性。通过不断强化攻防两端能力，我们在巩固公司核心安全基础、保障数据与业务安全方面发挥着关键作用。\n\n1、负责公司安全运营体系的建设与运营，围绕检测策略的设计、优化与持续迭代，提升告警质量与运营效率；\n2、结合AI/机器学习/大模型能力，建设智能化安全运营能力，覆盖告警自动研判、降噪聚合、异常行为建模、威胁情报关联、SOAR自动化处置等场景；\n3、负责各类安全产品（WAF/HIDS/NTA/EDR/ITDR等）的策略制定、效果调优与运营，建立策略效果评估与迭代闭环；\n4、负责安全事件的分析、调查与处置，沉淀可复用的运营SOP与知识库，建设有效监控能力，防范规模性安全事件与系统性风险。","requirements":"1、2027届获得本科及以上学历，信息安全、计算机科学、人工智能、数据科学等相关专业优先；\n2、具备AI/算法能力：熟悉机器学习/深度学习常用算法，或具备大模型（LLM）应用、数据挖掘、异常检测建模等相关经验，能将算法能力应用于安全场景；\n3、具备扎实的安全基础，熟悉网络、主机、应用、容器安全，熟悉常见安全攻防对抗手段与漏洞技术原理；\n4、能基于数据分析制定、优化并运营检测规则与分析策略，具备用数据/算法解决安全问题的能力；\n5、熟练Python/Go等至少一种开发语言，熟悉业界开源LLMs，具备AI Agent或Agentic AI开发能力；\n6、具备良好的沟通表达、数据思维、团队合作意识与自驱力。\n\n加分项\n1、有安全场景（告警研判、UEBA、威胁检测等）算法落地经验者优先；\n2、熟悉业界开源LLMs，具备AI Agent/Agentic AI开发能力者优先；\n3、有安全+AI方向的论文、开源工具或竞赛/红蓝对抗成果者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7628527932612397365","sourceKey":"bytedance","company":"字节跳动","title":"面向国际电商场景的大模型应用-国际电商（杭州）","city":"杭州","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7628527932612397365/detail","duty":"团队介绍：国际电商是以TikTok为载体的电商业务（也称为TikTok Shop），致力于成为用户发现并获取优价好物的首选平台，在直播电商、视频内容电商、货架电商等多场景下，国际电商希望能为用户提供更个性化、更主动、更高效的消费体验，为商家提供稳定可靠的平台服务，致力于新奇好物畅销全球，美好生活触手可得的使命。\nData-电商团队是国际电商的核心算法技术力量，专注于电商领域的算法创新，帮助用户高效发现感兴趣的商品，保障用户的购物安全，提升交易各环节的智能化水平。在这里，你将与一流的产品和技术团队合作、钻研，一起应对技术和业务上的挑战，推动技术在电商场景的深度落地。\n\n课题介绍：\n国际电商生态中沉淀了用户行为、商品图文、多媒体内容、商品销量与物流时序等海量异构数据，但传统模型在长周期预测、跨模态理解及复杂决策推理上仍存在明显瓶颈。\n本课题拟以大模型为基础，联合构建面向国际电商场景的基础大模型，将用户、商品、内容、物流与库存等关键信息统一建模，并在其之上设计可插拔的Agent框架，系统整合任务规划、工具调用、多轮交互与环境感知等能力，从而在需求预测、流量分发与个性化推荐等链路中实现端到端的智能决策。\n\n课题挑战：\n1、异构融合与对齐：统一建模用户行为序列、商品销量时序信号与多模态商品内容，完成高维时序与图文表征的深度语义对齐；\n2、推荐大模型与世界模型协同：把推荐问题定义还原为用户推荐列表的生成问题，基于大模型的技术完成端到端推荐建模；\n3、推荐物品的Tokenizor：如何把亿级别的物品进行多模态和特征语义编码，支撑后续训练和生成任务，处理几十TB级别的用户行为Tokens的预训练，通过模型结构和训练方式拉高Scaling Law曲线，把各类推荐任务重构为后训练任务，以RLVR的思路进行推荐任务建模，最大化GMV和体验价值，训练推理优化，基于SGLang 等大模型推理套件定制构建高性能的推荐服务；\n4、电商多模态大模型：构建面向电商领域的多语言多模态大模型，在核心电商场景达到SOTA性能，并以此为基础打造电商智能体基座，广泛支撑各类电商场景下的Agent应用落地；\n5、Agent评测与安全合规：构建贴合实际业务的Agent评测指标与基准，保障在强约束、强对抗环境下的稳定性、安全性与合规性。\n\n课题价值：\n1、技术价值：打造通用多模态基座，以模型、数据、算力迭代实现幂律增长，夯实规模化技术底座；\n2、业务价值：搭建国际电商大模型底座，以生成式推荐、时序大模型、Agent等驱动GMV与留存，打造高杠杆营收引擎。","requirements":"1、2027届毕业，获得博士学位，计算机等相关专业优先；\n2、扎实的机器学习技术基础，了解前沿的AI技术，发表过高水平学术会议论文或有竞赛经验；\n3、熟悉大数据相关框架和应用Hadoop、MapReduce/Spark等；\n4、熟悉TensorFlow/PyTorch模型的训练和部署，了解混合精度训练、分布式训练等训练加速方法；\n5、了解模型压缩&推理加速的研究和技术进展，包括但不限于模型量化、剪枝、蒸馏、TensorRT推理优化等；\n6、熟悉以下任一方向的技术：\n1）CV&多模态：在多媒体和计算机视觉某个领域有较深入的研究，包括但不限于：图像搜索、图像/视频分类和识别、图像分割、目标检测、OCR、图神经网络、多模态、无监督和自监督学习等；有CV/多模态大模型相关项目经验，研发&优化电商视频&商品多模态大模型，结合LLM和视频/商品表征，支持视频多模态分类，视频QA，跨模态检索，商品分类等任务，显著超越线上模型；有较强的实践能力，在Kaggle，COCO，ImageNet，ActivityNet，ICPC等比赛获奖；熟悉前沿工作，在顶级学术会议（如CVPR、ICCV、ECCV等）发表论文；\n2）自然语言处理（NLP）：NLP方向上有较深入的研究，包括但不限于：预训练技术，自然语言理解，多语言&跨语言学习，自然语言生成，迁移学习，半监督学习等；有LLM大模型相关项目经验；研发NLP大模型，以统一电商场景的NLP任务，落地电商业务场景；有较强的实践能力，在Kaggle，GLUE，Super GLUE，CLUE等比赛获奖；熟悉前沿工作，在顶级学术会议（如ACL、EMNLP等）发表论文。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7626407480047716613","sourceKey":"bytedance","company":"字节跳动","title":"面向大模型与AI Agent的AI云原生基础设施关键技术研究-存储","city":"北京","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7626407480047716613/detail","duty":"团队介绍：字节跳动基础设施存储团队，为字节跳动全系产品提供存储服务，对外打造火山引擎公有云存储产品体系，在AI时代深度支撑豆包大模型和方舟大模型平台。我们根植字节跳动最佳技术实践，以数十万台服务器规模和百EB 级数据稳定存储的企业服务经验，通过火山引擎丰富的存储产品矩阵对外赋能。我们积极探索业界顶尖的技术，从底层硬件构造到数据治理和上层应用加速，致力于构建业界领先的云存储服务，释放海量数据的无限价值。\n\n课题介绍：\n随着大语言模型与AI Agent规模化落地，传统云原生基础设施已难以适配AI负载的极致性能与弹性需求。本课题围绕AI基础设施全栈展开系统性研究：\n1、网络与可观测：研究大规模AI集群故障智能定位与根因分析，结合时序数据库智能调优，提升集群稳定性；\n2、存储系统：研发AI场景专属的Serverless高性能弹性文件系统与存储加速架构，探索DPU软硬件协同优化，突破AI存储性能瓶颈；\n3、算力调度：研究GPU/CPU/MEM异构协同调度技术，面向AI Agent构建Serverless异构算力编排系统，解决负载异构、状态依赖等调度难题；\n4、向量检索：优化面向大模型应用的向量检索核心技术，打造云原生分布式向量索引引擎，满足超大规模向量检索的低延迟、低成本需求；\n5、智能化与Agent架构：探索基于AI Agent工作流的基础设施自动寻优，构建可自主进化的业务Agent框架，通过AI for Infra赋能全栈智能优化；\n本课题旨在构建支撑大模型与AI Agent落地的下一代AI原生基础设施，提升资源利用率、降低成本、支撑弹性扩展，推动AI基础设施技术演进。\n\n课题挑战：\n1、全栈协同挑战：覆盖多技术领域，需要从端到端视角实现系统性优化，避免单点优化收益不足；\n2、性能成本平衡：AI场景对性能提出极致要求，需要在吞吐、延迟、规模与成本之间找到最优平衡点；\n3、云原生适配：需要将传统单机技术方案重构为适配云原生分布式架构，解决扩缩容、容错、调度等新问题；\n4、AI系统融合：既需要用AI赋能基础设施优化，又需要基础设施原生适配AI负载，深度融合对技术整合要求高；\n5、Agent稳定性：自主进化Agent框架需要解决经验学习、知识一致性、持续安全进化等基础问题，工程化难度大；\n6、研发生态平衡：需要平衡前沿理论创新与工程落地，兼顾技术突破与现有业务生态适配。\n\n课题价值：\n1、构建大模型/RAG 场景的高性能基础设施底座，支撑大规模向量数据高效检索；\n2、优化AI业务存储成本结构与运维复杂度；\n3、提升异构算力资源配置效率与技术复用性。","requirements":"1、2027届毕业，获得博士学位，优先考虑人工智能、计算机科学、数学相关专业；\n2、拥有扎实的信息检索、数据挖掘、机器学习、计算机网络等相关领域理论基础，精通计算机网络和网络编程，熟练掌握至少一门编程语言，如C/C++、Python、Go等，具备优秀的代码能力、数据结构和基础算法功底；\n3、针对不同研究方向，需具备相应能力，如能够独立完成复杂搜索任务的设计与开发；有LLM和基础架构相关研究背景；能完成研究点的设计文档、独立交付件、演示Demo；熟悉当前高性能网络和系统领域的最新进展，包括RDMA，拥塞控制、AI网络优化等技术；\n4、具备高效的学习能力，拥有较强的自我驱动意识；具有良好的团队合作精神，善于与团队成员协作交流，共同攻克难题；出色的问题分析和解决能力，有自主探索解决方案的能力；出色的心理素质与应变能力，面对困难勇于迎接挑战，面对复杂局面沉着、冷静、灵活；\n5、在SIGIR、VLDB、ICDE、NeurIPS、SIGCOMM、NSDI等顶级学术会议或期刊上发表过论文者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7593279097802328325","sourceKey":"bytedance","company":"字节跳动","title":"测试开发实习生-TikTok搜索","city":"北京","category":"测试","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7593279097802328325/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：TikTok是一个覆盖150个国家和地区的国际短视频平台，我们希望通过TikTok发现真实、有趣的瞬间，让生活更美好。TikTok 在全球各地设有办公室，全球总部位于洛杉矶和新加坡，办公地点还包括纽约、伦敦、都柏林、巴黎、柏林、迪拜、雅加达、首尔和东京等多个城市。\n \nTikTok搜索团队致力于为用户提供精准高效的搜索工具，创造良好的搜索体验，提升信息流动的效率，同时高价值的搜索流量也能带来商业化价值，为TikTok生态内的其他业务提供高效的入口，支持内容生态的发展，提升中尾部视频的消费力量。\n你可以有机会参与核心业务功能的开发工作，接触到第一线的用户，我们期待你的加入！\n\n1、负责TikTok用户增长的质量保障工作；\n2、深度参与产品研发全生命周期，协同产品经理、业务开发交付高质量产品，手段包括但不限于功能测试、自动化实施、性能测试、安全测试、专项测试、稳定性监控、流程改进等；\n3、通过质量和效率数据分析，持续完善产品质量和用户体验；\n4、通过工具或平台开发，提升研发效率，完善质量保障策略；\n5、参与质量体系的规划和建设，参与自动化、无人值守、智能测试、故障演练等创新测试方法的实施。","requirements":"1、2027届本科及以上学历在读，计算机、软件工程等相关专业优先；\n2、热爱计算机科学和互联网技术，对质量保障工作有浓厚兴趣，熟悉测试理论和方法；\n3、有扎实的计算机理论基础和代码编写能力，掌握至少一门编程语言，包括但不限于：Java/C/C++/Python/Go；\n4、具备优秀的业务理解能力，逻辑思维灵活全面，良好的沟通协作能力，善于发现问题和解决问题；\n5、能保证至少4个月及以上的实习，每周可出勤至少4天及以上，实习优秀者提供转正机会。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7314217905797089563","sourceKey":"bytedance","company":"字节跳动","title":"测试开发实习生-生活服务","city":"成都","category":"测试","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7314217905797089563/detail","duty":"日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n团队介绍：生活服务业务依托于抖音、抖音极速版等平台，致力于促进用户与本地服务的连接。过去一年，生活服务业务开创了全新的视频种草和交易体验，让更多用户通过抖音发现线下好去处，也帮助众多本地商家拓展了新的经营阵地。我们期待你的加入，一同为亿万用户创造更美好的生活。\n\n1、参与产品测试的全流程，包括需求评审、设计评审、制定测试计划、测试用例设计及执行、缺陷跟踪、测试报告等；\n2、开发测试工具和自动测试框架、自动测试脚本，进行自动化测试，提升测试效率；\n3、对产品、流程提出持续性改进意见，提升产品质量和研发效率。","requirements":"1、本科及以上学历在读，计算机软件、通讯相关专业优先；\n2、熟悉至少一种编程语言；\n3、良好的数据结构、算法基础；\n4、学习能力强，有较强分析、定位和解决问题的能力，较强逻辑思维能力和表达能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669694035128371461","sourceKey":"bytedance","company":"字节跳动","title":"用户产品经理 - 西瓜视频","city":"北京","category":"产品经理","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669694035128371461/detail","duty":"团队介绍：西瓜视频作为国内领先的综合视频平台，源源不断地为不同人群提供优质内容，让人们看到更丰富的世界。同时，西瓜视频鼓励多样化创作，帮助人们轻松地向全世界分享视频作品，创造更大的价值。目前平台累计用户数超过 3.5 亿，日均播放量超过 40 亿，用户平均使用时长超过 100 分钟。\n\n1、负责西瓜视频产品端内功能设计，提升用户的视频消费体验，带动时长和留存；\n2、负责产品功能的完整流程，独立完成需求分析，方案设计以及协调资源跟进项目落地；\n3、负责产品上线后的效果分析，对产品进行迭代优化；\n4、具备成熟的规划能力，针对业务目标，拆解关键路径，制定长短期规划。","requirements":"1、2027届获得本科及以上学历；\n2、用户产品经验，视频APP相关实习经验优先，对数据敏感，能透过数据分析业务现状，持续优化产品体验；\n3、具有良好的团队沟通与项目推动能力，思维活跃有创新精神，具有较强的责任心和执行力；\n4、具备独立深入思考和推进工作的意识和能力，能快速学习和成长。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668616756222495029","sourceKey":"bytedance","company":"字节跳动","title":"前端开发工程师（商业化） - 剪映CapCut","city":"深圳","category":"前端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668616756222495029/detail","duty":"团队介绍：剪映研发团队，主要支持剪映、CapCut、醒图、Hypic、即梦、Dreamina、小云雀、Pippit等多款国内外产品的研发工作，业务覆盖多元化影像创作场景，并孵化了多款AIGC明星产品，相关产品多次登顶国内外App Store 免费应用榜第一，并继续保持高速增长。加入我们，一起打造全球最受用户欢迎的影像创作和GenAI产品。\n\n1、负责剪映系产品商业化方向的前端研发工作，参与会员、订阅、支付、权益、积分、营销活动、资源位、团队版、经营后台等业务模块建设；\n2、参与Web、H\n5、Lynx、跨端容器等多端前端场景研发，支持剪映、CapCut、醒图、Hypic、即梦、Dreamina、小云雀、Pippit等产品的商业化功能落地；\n3、参与商业化链路的体验优化与性能优化，提升用户体验和业务转化效率；\n4、参与商业化前端基础能力建设，包括中台化、活动基建、品质保障和架构优化等；\n5、参与AI/Agent在商业化场景中的落地，包括面向不同角色的Agent智能助手、AI研发提效等方向探索。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程、电子信息、通信、自动化等相关专业优先；\n2、具备扎实的计算机基础，熟悉前端基础知识体系，有良好的编码规范和工程化质量意识；\n3、能够主动使用AI工具辅助学习、编码、调试、测试和文档生成，并能识别、校验和修正AI输出中的问题；\n4、具备较强的学习能力、自驱力和责任心，愿意主动承担具备挑战的任务，对个人成长负责；\n5、具备良好的沟通协作能力和团队合作精神，能够与产品、设计、后端、客户端、测试等角色高效协同。\n\n加分项：\n1、有Web前端、移动端H\n5、小程序、Lynx、React Native、跨端容器等项目经验者优先；\n2、有AI/大模型/Agent相关项目实践经验者优先，如智能助手、自动问答、知识库/RAG、自动化验证、工作流编排、AI辅助编码等；\n3、有开源项目、技术博客、竞赛获奖、复杂课程项目或可展示作品者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668568604380891397","sourceKey":"bytedance","company":"字节跳动","title":"商家产品经理 - 抖音生活服务","city":"上海/北京","category":"产品","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668568604380891397/detail","duty":"团队介绍：抖音生活服务依托抖音POI （Point of Interest）、短视频、直播、搜索等，以“激发线下生意，丰富美好生活”为使命，致力于成为最值得信赖的生活服务平台，为用户提供更丰富、独特的生活体验，为合作伙伴提供包容且公平的健康营商生态。截至2025年底，抖音生活服务业务已覆盖400+城市，超过1500万家动销门店。抖音生活服务将继续携手生态伙伴，为用户提供值得心动的商品和服务。\n\n1、参与抖音生活服务商家操作平台的建设；\n2、深入参与商户调研，能够结合商家反馈和数据分析，洞察不同类型商家的经营诉求，驱动产品演进；\n3、协调内外部合作资源，推动项目按时保质上线，及时进行项目复盘推动产品持续更新迭代。","requirements":"1、2027届获得本科及以上学历，专业不限；\n2、对生活服务和商家/平台产品保持充分热情；\n3、对用户体验和工具设计敏感，在交互、视觉方面具备良好的感觉，同理心强、数据敏感；\n4、逻辑思维出色，沟通表达清晰，具备辩证思维和探索精神，有一定的想象力和创造力；\n5、对新型生活服务商业模式有思考和兴趣，自驱成长、结果导向。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668562361263343925","sourceKey":"bytedance","company":"字节跳动","title":"广告策略产品经理 - 抖音生活服务","city":"上海/北京","category":"产品经理","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668562361263343925/detail","duty":"团队介绍：抖音生活服务依托抖音POI （Point of Interest）、短视频、直播、搜索等，以“激发线下生意，丰富美好生活”为使命，致力于成为最值得信赖的生活服务平台，为用户提供更丰富、独特的生活体验，为合作伙伴提供包容且公平的健康营商生态。截至2025年底，抖音生活服务业务已覆盖400+城市，超过1500万家动销门店。抖音生活服务将继续携手生态伙伴，为用户提供值得心动的商品和服务。\n\n1、负责本地广告、线索广告的策略产品设计与迭代，聚焦投放效率、转化效果、成本控制三大核心目标，搭建贴合本地商家、线索类广告主需求的策略体系；\n2、深入洞察本地生活及线索类广告主的投放痛点，结合行业趋势、用户行为数据，设计可落地的策略产品方案，推动产品从0到1或从1到N的落地迭代；\n3、联动算法、研发、运营、销售团队，推进策略产品上线，建立策略效果监测体系，通过数据复盘持续优化策略参数，提升广告投放ROI、线索有效率及商家留存率；\n4、对接内外部需求，平衡广告主、平台、用户三方利益，制定策略产品的灰度测试、推广计划及效果评估标准，确保策略合规且符合业务发展目标；\n5、跟踪行业产品动态，挖掘策略创新点，输出策略优化报告，为业务决策提供产品层面的专业支持，推动本地及线索广告业务规模增长。","requirements":"1、2027届获得本科及以上学历；\n2、互联网广告策略产品相关经验，有本地生活广告、线索广告策略产品经验者优先；\n3、具备较强的数据分析能力，能通过广告投放数据、用户行为数据、商家反馈定位策略痛点并输出优化方案，熟练使用Excel、SQL等数据分析工具者优先；\n4、熟悉广告投放全流程，了解广告算法基础逻辑，能独立完成策略产品方案的设计、落地及效果复盘；\n5、具备优秀的跨团队协同能力、沟通表达能力及问题解决能力，目标感强，主动推进项目落地；\n6、对本地生活行业、线索广告行业有深入理解，关注行业趋势，具备敏锐的产品洞察力和创新意识。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667953284506077445","sourceKey":"bytedance","company":"字节跳动","title":"AI应用开发工程师 - AI Platform","city":"深圳/上海","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667953284506077445/detail","duty":"团队介绍：AI Platform 团队，隶属于产品研发和工程架构部门。面向公司内部各业务线，建设统一的AI 应用基础设施和工程平台，帮助业务高效、稳定地落地大模型应用，加速 AI 产品创新。\n在平台产品侧，团队打造了新一代AgentOps平台，提供 Prompt Engineering、Agent观测、评测、数据处理、模型微调等 Agent 全生命周期解决方案，帮助Agent开发者构建效果调优的数据飞轮。产品也已成功推出商业化版本。\nAI Platform 团队还持续孵化多种面向内部与外部场景的AI应用创新产品，积极探索大模型应用的技术发展。团队氛围好，发展空间大，欢迎加入！\n\n1、负责智能客服场景的LLM应用开发，利用LLM和工程技术的结合，探索高智能化水平的解决方案；\n2、持续跟进LLM前沿技术，并能在产品中应用解决复杂任务，提高应用处理问题的准确率。","requirements":"1、2027届获得本科及以上学历，计算机、物理、数学、统计学相关专业优先；\n2、对AI应用开发有强烈的热情，有深入使用过大模型相关应用，并了解大模型基本原理；\n3、掌握至少一门服务端开发语言（Go/Python/Java/Rust）；\n4、有大模型应用开发经验的优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667887564768643333","sourceKey":"bytedance","company":"字节跳动","title":"大模型应用开发工程师（AI Coding方向） - AI Platform","city":"上海/杭州","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667887564768643333/detail","duty":"团队介绍：AI Platform 团队，隶属于产品研发和工程架构部门。面向公司内部各业务线，建设统一的AI 应用基础设施和工程平台，帮助业务高效、稳定地落地大模型应用，加速 AI 产品创新。\n在平台产品侧，团队打造了新一代AgentOps平台，提供 Prompt Engineering、Agent观测、评测、数据处理、模型微调等 Agent 全生命周期解决方案，帮助Agent开发者构建效果调优的数据飞轮。产品也已成功推出商业化版本。\nAI Platform 团队还持续孵化多种面向内部与外部场景的AI应用创新产品，积极探索大模型应用的技术发展。团队氛围好，发展空间大，欢迎加入！\n\n1、负责AI Coding产品的核心模型能力建设，包括代码生成、代码补全、代码理解等场景的模型集成与工程优化；\n2、设计并实现基于LLM的Agentic Coding系统，探索Multi-Agent协作在复杂软件工程任务中的应用；\n3、与算法、数据、评测团队紧密协作，建立“模型训练→线上部署→用户反馈→数据回流”的迭代闭环，持续提升产品效果；\n4、跟踪AI Coding领域前沿进展（如长上下文工程等），快速验证并落地到产品中。","requirements":"1、2027届获得本科及以上学历，计算机、人工智能、自动化、数学相关专业优先；\n2、精通Go、Python、C++等一种或多种编程语言，具备扎实的编程技能和算法设计能力；\n3、对AI Agent技术有深入了解，熟悉LangChain等框架，熟悉LangSmith等平台；\n4、具备出色的团队协作精神和良好的英文阅读及沟通能力。\n\n加分项：\n1、在LLM工程领域有落地经验；\n2、对AgentOps平台熟悉，如LangSmith、Langfuse等；\n3、有不错的research和探索精神，对最新Agent技术趋势和论文有不错的了解。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667865137391503621","sourceKey":"bytedance","company":"字节跳动","title":"后端开发工程师（AI效能工具） - 质量团队","city":"北京/上海","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667865137391503621/detail","duty":"团队介绍：字节跳动质量团队作为公司质量保障体系的核心力量，覆盖Trae、Coze、开发者服务、语音等多个业务关键领域，通过建设和提供更高效的质量保障方案、技术、工具以及业务自动化保障服务，为公司业务稳健发展提供坚实保障。\n当前，我们聚焦用 AI 重构测试流程、提升研发效能，探索从 “自动化” 到 “智能化” 的质量保障新路径。我们坚信，AI 将彻底改变测试行业的底层逻辑，欢迎加入，与我们一同突破技术边界，定义下一代质量保障模式，推动行业变革！\n\n1、参与字节跳动数字QA智能体、智能工具开发工作，需应用的AI4SE领域的AI技术，与传统效能技术相结合，构建AI主导的AI4SE效能工具，为AI主导的新软件交付模式提供AI技术支撑；\n2、调研业界最新的LLM、Agent相关技术，致力于构建AI时代的软件交付测试新模式；\n3、快速学习最新前沿AI技术，在工作中进行快速验证，探索构建高效的效能工具智能体服务。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程相关专业优先；\n2、具备快速学习能力，对探索与应用新技术有热情，有热情参与到AI产品的测试技术的创新与探索；\n3、具备一定的工程编码能力，对LLM/Agent有一定了解。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667535743867128117","sourceKey":"bytedance","company":"字节跳动","title":"AI产品运营（Agent方向） - 剪映CapCut","city":"北京","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667535743867128117/detail","duty":"团队介绍：剪映CapCut团队成立七年，先后孵化了剪映、CapCut、醒图、Hypic、即梦、Dreamina、Pippit等产品，覆盖视频、图片、Al生成、视频营销等多领域，打造与AI结合的全球化产品矩阵。\n我们的愿景是：激发想象力，成为全球领先的互动内容平台，创造独特的体验和价值。\n我们期待你的加入，一同极致打磨用户体验,构建创意生态和商业化能力，定义AI与创作结合的无限可能，让内容互动更简单、更精彩!\n\n1、以桌面端用户规模为核心目标，负责CapCut在Web端的用户需求梳理；\n2、协同增长与区域团队完成产品宣发的全链路流程；\n3、分析用户的使用场景和用户反馈，提炼产品优化方向并提出改善建议；\n4、与产品经理合作，提高产品自传播能力。","requirements":"1、2027届获得本科及以上学历；\n2、熟悉各种国际化社交媒体平台，对视频创作或者广告营销有一定接触；\n3、具备视频剪辑能力优先；\n4、具备团队合作能力，能够与不同部门的同事进行有效沟通和协作；\n5、具备创新思维和解决问题的能力，能够应对市场变化并提出相应的策略调整；\n6、英语可作为工作语言。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667471048071940357","sourceKey":"bytedance","company":"字节跳动","title":"后端开发工程师（AI大模型开发平台） - 数据平台","city":"杭州/北京/上海","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667471048071940357/detail","duty":"团队介绍：数据平台是字节跳动数据中台部门，为公司多业务线（包括抖音、电商、直播和生活服务等）提供一站式大数据解决方案，涵盖数据的生产、清洗、传输、建模、分析等全流程链路，提供数据开发、实验评估、画像标签、增强分析等多元场景解决能力。同时，数据平台部门也致力于把字节跳动积累沉淀的数据中台解决方案做商业化输出，让更多行业能够应用我们的产品能力构建自己的数据中台。在火山引擎上，我们提供了营销增长套件，数据中台等相关产品解决方案，为泛互联网、金融、汽车、新零售等行业提供了行业解决方案。\n\n1、负责LLM驱动的AI Agent框架的研究和实现，构建基础服务如MCP/Memory/Skill等；\n2、根据应用场景的需求，优化并提升AI Agent的算法性能和用户体验；\n3、持续追踪AI Agent领域的最新技术趋势和研究成果，将前沿技术整合进我们的项目与解决方案中。","requirements":"1、2027届获得硕士及以上学位，计算机、软件工程等相关专业；\n2、精通Go、Python、Java等一种或多种编程语言，具备扎实的编程技能和算法设计能力；\n3、对AIAgent技术有深入了解，熟悉ContextEngineering，MultiAgent，Memory等机制；\n4、具备团队协作精神和良好的英文阅读及沟通能力；\n5、加分项：有在相关领域的研究或项目经验，尤其是在LLM或AIAgent应用上。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667099804536948997","sourceKey":"bytedance","company":"字节跳动","title":"大模型算法工程师（业务风控） - TikTok研发","city":"上海","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667099804536948997/detail","duty":"团队介绍：TikTok研发团队，旨在实现TikTok业务的研发工作，搭建及维护业界领先的产品。加入我们，你能接触到包括用户增长、社交、直播、电商C端、内容创造、内容消费等核心业务场景，支持产品在全球赛道上高速发展；也能接触到包括服务架构、基础技术等方向上的技术挑战，保障业务持续高质量、高效率、且安全地为用户服务；同时还能为不同业务场景提供全面的技术解决方案，优化各项产品指标及用户体验。 \n在这里， 有大牛带队与大家一同不断探索前沿， 突破想象空间。 在这里，你的每一行代码都将服务亿万用户。在这里，团队专业且纯粹，合作氛围平等且轻松。目前在北京，上海，杭州、广州、深圳分别开放多个岗位机会。\n\n1、负责AI Native应用的算法研发和LLM（大语言模型）效果优化工作，推动技术的探索和应用；\n2、提升基于LLM（大语言模型）的自然语言理解能力，比如内容理解、分类、向量召回、结构化、短文本、长文本的表征学习等；\n3、结合LLM（大语言模型）技术，对用户行为、特征进行总结、理解、分类等探索；\n4、探索Agent在复杂任务中的应用，实现基于LLM（大语言模型）的复杂任务在风控领域场景的应用落地。","requirements":"1、2027届获得硕士及以上学位，计算机科学与技术、人工智能相关专业优先；\n2、掌握LLM（大语言模型）的算法原理、Fine-Tuning、Prompt Engineering、向量数据库和LangChain/AutoGen等Agent应用框架者优先；了解最新的LLM技术，有训练或应用经验加分；\n3、良好的设计和编码风格，热爱写代码，能产出高质量的设计和代码；\n4、出色的分析问题、解决问题能力，能从纷繁复杂的数据中看出问题本质；\n5、有主流风控策略、LLM系统的算法研发经验加分；\n6、责任心强，积极主动，有良好的沟通能力和团队合作能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7686799888371468549","sourceKey":"bytedance","company":"字节跳动","title":"运营实习生 - 国际化电商广告","city":"北京","category":"运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7686799888371468549/detail","duty":"团队介绍：国际化电商广告团队始终以广告主为核心，追求技术卓越。我们与电商、零售、旅游等各行业广告主紧密合作，致力于将国际化产品打造为各类企业不可或缺的增长平台，同时成为消费者发现并购买产品、内容及服务的首选目的地。团队肩负着实现国际化广告营收的重要使命，正在全力构建新一代网络广告解决方案。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、协助完成商业化项目的数据分析工作；\n2、协调跨职能部门，推进项目落地；\n3、围绕商业化AI工具进行实践，在实际工作中加以运用，总结产品需求点，帮助团队提升AI工具使用效率；\n4、配合跨团队沟通协调工作。","requirements":"1、本科及以上学历在读，数学、统计、数据分析、经济学、计算机等相关专业优先；\n2、责任心强，能快速融入团队、主动跟进业务需求，有商业化/广告/电商相关的数据分析实习经验优先；\n3、熟练SQL、具备扎实的数据分析能力，做事细致、响应及时；\n4、英语能正常读写即可（能读英文文档、邮件沟通）。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7676331141710416133","sourceKey":"bytedance","company":"字节跳动","title":"多模态大模型算法工程师 - PICO","city":"北京","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7676331141710416133/detail","duty":"团队介绍：作为一家拥有自主创新和研发创造能力的科技品牌，PICO致力于成为领先的世界级XR平台，成就开发者与创作者，共同为全球消费者创造更美好的生活体验。我们开创性地将虚拟现实扩展到了多个领域，为运动、视频、娱乐等消费级场景带来了全新体验；并广泛应用在教育、医疗和企业培训等商用场景，给全球企业级用户提供了多元化的VR解决方案。\n\n1、负责MR场景中LLM及多模态相关基础算法研发与优化，包括基础模型优化、数据建设、评测完善、训练/推理加速等技术研发；\n2、负责MR场景下场景理解、多模态交互、意图识别等算法Feature研发，包括但不限于微调、多轮Agent RL、long term mem或y Agent等；\n3、深入探索并跟进业界前沿技术，推进LLM及多模态技术在MR场景的应用与落地。","requirements":"1、2027届获得硕士及以上学位，计算机、电子、数学等相关专业；\n2、熟悉常用的多模态大模型预训练、后训练等技术及优化策略；\n3、在LLM、计算机视觉、多模态、强化学习、AIGC生成等一个或多个领域有一定研究或实践经验；\n4、较强的问题分析与学习能力，能快速跟进前沿技术，并应用于实际问题解决；\n5、熟练掌握C++/Python等编程语言，扎实的编程能力和工程实现能力。\n\n加分项：\n1、ACMICPC、NOI/IOI、Coder等比赛获奖者优先；\n2、了解常用的2D/3D CV任务，如检测分割深度等优先；\n3、在计算机视觉、机器人、图形学等相关领域顶会发表论文或竞赛取得名次者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7673509678010108213","sourceKey":"bytedance","company":"字节跳动","title":"大模型算法研究员 - 火山方舟","city":"北京/深圳","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7673509678010108213/detail","duty":"团队介绍：火山方舟是火山引擎推出的一站式大模型服务平台，是中国大模型市场产品和份额领跑者。平台提供模型推理、评测、精调等全流程服务。方舟搭载了豆包及业界主流大模型，提供丰富的插件生态和AI应用开发服务，并通过稳定可靠的安全互信方案、专业的算法技术服务，全方位保障企业级AI应用落地。\n\n1、参与多模态大模型后训练（SFT、RL、OPD等）算法研发，提升模型在内容理解等场景的能力表现；\n2、深入分析失败模式，建立从任务与评测、问题定位到数据、训练和系统优化的完整闭环，持续提升模型在复杂场景上的准确度和泛化能力；\n3、跟踪学术界与工业界前沿进展，将最新研究成果转化为线上生产力。","requirements":"1、2027届获得本科及以上学历，专业不限；\n2、具有优秀的基础算法、代码能力，熟练掌握C/C++或Python编程语言，ACM/ICPC、NOI/IOI、Top Coder、Kaggle等比赛获奖者优先；具有扎实的机器学习和数学基础，熟悉Transformer架构和大模型原理，熟悉CV、AIGC、NLP、RL等技术领域，在CVPR、ECCV、ICCV、NeurIPS、ICLR、ICML、ACL、EMNLP等顶级会议上发表论文者优先；\n3、具有出色的分析、解决问题的能力，能深入解决大模型训练和应用存在的问题，有自主探索解决方案的能力者优先；对AI技术的实际落地和突破性应用充满热情，追求技术创新与现实价值的结合；具备良好的沟通协作能力与自驱力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668624840068663605","sourceKey":"bytedance","company":"字节跳动","title":"豆包大模型Agent算法研究员 - 火山方舟","city":"上海/北京/深圳/杭州","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668624840068663605/detail","duty":"团队介绍：火山方舟是火山引擎推出的一站式大模型服务平台，是中国大模型市场产品和份额领跑者。平台提供模型推理、评测、精调等全流程服务。方舟搭载了豆包及业界主流大模型，提供丰富的插件生态和AI应用开发服务，并通过稳定可靠的安全互信方案、专业的算法技术服务，全方位保障企业级AI应用落地。\n\n1、面向真实生产力场景，探索和提升大模型Agent的核心智能能力，让Agent能够更自主、可靠地完成复杂工作；方向覆盖General Agent、Coding Agent及其交叉场景；\n2、围绕真实高价值任务开展Agent能力优化，包括但不限于：\n1）搜索调研、信息处理、数据分析等复杂知识工作；\n2）代码理解、代码生成与修改、测试、Debug、Repo-level软件工程任务；\n3）跨工具、跨步骤、长程复杂任务中的规划、执行、验证与动态调整；\n3、围绕Agent核心能力和训练方法开展研究与优化，包括但不限于：\n1）Planning、Tool Use、Context Management、Memory、Verification；\n2）指令与格式遵循、事实性与幻觉治理；\n3）Long-horizon Agent、错误恢复与自我纠正；\n4）大规模任务与环境构造、Trajectory生成与筛选；\n5）Reward/Verifier、强化学习、Self-improvement等训练方法；\n4、从真实职业和工作流出发，系统梳理高价值任务，例如研究、数据分析、投资分析、软件开发等，将真实工作转化为可训练、可评测、可规模化的Agent任务与环境；\n5、深入分析Agent的执行轨迹和失败模式，建立从任务与评测、问题定位到数据、训练和系统优化的完整闭环，持续提升Agent在真实任务上的完成能力和泛化能力。","requirements":"1、2027届获得本科及以上学历，专业不限；\n2、扎实的机器学习/强化学习基础，或优秀的软件工程与系统能力，在Agent、强化学习、代码智能或相关方向有深入积累；出色的问题分析和解决能力，能够从模型表现和真实任务中发现关键问题，形成可靠的技术判断，并独立推动方案设计、实验验证和最终落地；对AI的实际效用和突破性应用有热情，自驱力强，愿意挑战开放、复杂、没有标准答案的问题，并关注技术最终能否转化为真实可用的Agent能力；\n3、优秀的代码和工程能力，熟练使用Python，具备良好的系统调试和复杂工程实践能力，能够独立完成数据分析、环境构建、Agent实验、训练、评测和问题定位；\n4、在NeurIPS/ICML/ICLR/ACL/EMNLP等顶级会议发表过相关高质量工作，或主导过有影响力的Agent、模型训练或智能软件系统项目者优先；在ACM/ICPC、NOI/IOI、Top Coder、Kaggle等算法或编程比赛中取得优秀成绩者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668564191087855925","sourceKey":"bytedance","company":"字节跳动","title":"全栈开发/测试开发工程师（用户增长） - TikTok研发","city":"上海","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668564191087855925/detail","duty":"团队介绍：TikTok研发团队，旨在实现TikTok业务的研发工作，搭建及维护业界领先的产品。加入我们，你能接触到包括用户增长、社交、直播、电商C端、内容创造、内容消费等核心业务场景，支持产品在全球赛道上高速发展；也能接触到包括服务架构、基础技术等方向上的技术挑战，保障业务持续高质量、高效率、且安全地为用户服务；同时还能为不同业务场景提供全面的技术解决方案，优化各项产品指标及用户体验。 \n在这里， 有大牛带队与大家一同不断探索前沿， 突破想象空间。 在这里，你的每一行代码都将服务亿万用户。在这里，团队专业且纯粹，合作氛围平等且轻松。目前在北京，上海，杭州、广州、深圳分别开放多个岗位机会。\n\n1、我们希望寻找一批具备扎实工程基础、全栈潜力和AI原生能力的应届同学，加入TikTok各业务质量工程团队，区别于传统意义上的“测试执行”岗位，这是一个以质量场景为切入点，面向复杂系统和智能工程建设的研发岗位；\n2、参与业务质量平台、研发效能工具和自动化基础设施的设计与开发，覆盖前端、后端、数据链路和平台能力建设；\n3、深入客户端、服务端及上下游协同链路，建设功能、接口、稳定性、性能、安全等多维质量保障能力；通过代码分析、链路分析、日志分析、压测、故障演练等方式发现复杂系统中的深层问题，并推动问题闭环；\n4、探索并落地AI在质量工程中的应用，包括测试生成、智能缺陷分析、质量评测、测试智能体、自主探索式测试等方向；\n5、沉淀可复用的工程能力，包括测试框架、诊断工具、自动化脚本、质量方法论与平台化能力；与研发、产品、算法、数据等团队协作，共同推动质量内建、研发提效和工程规范升级。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程、人工智能、自动化、数学等相关专业优先；\n2、具备扎实的计算机基础，理解数据结构与算法的核心思想，能够将抽象问题转化为可实现、可优化的工程方案；熟悉至少一门编程语言，如Go、Java、Python、TypeScript/C++等，具备独立完成中型工程项目或核心模块开发的能力；\n3、理解操作系统、计算机网络、数据库、并发编程、常见系统架构等基础知识；对软件工程有基本理解，熟悉从需求分析、设计实现到测试验证、上线迭代的研发流程；\n4、具备良好的问题拆解能力、系统性思维和学习能力，能够面对复杂问题持续追问本质并推动解决；具备良好的沟通协作能力和责任心，能够在跨团队、多角色合作中推动目标达成；\n5、能熟练使用AI工具辅助编码、排障、文档理解和方案设计，具备对AI输出进行判断、校验和二次加工的能力；对AI在测试与质量场景中的应用有兴趣，对大语言模型、Agent、RAG、模型评测、自动化工作流等AI工程方向有认知或实践经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668355065725503749","sourceKey":"bytedance","company":"字节跳动","title":"前端开发工程师 - Aime","city":"北京/上海/深圳","category":"前端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668355065725503749/detail","duty":"团队介绍：Aime 是字节跳动打造的企业级 AI Agent 平台，面向研发、产品、运营等多类岗位，提供基于大模型的智能服务。平台集成代码仓库、文档、知识库、飞书、Browser Use、MCP、研发工具链等企业能力，支持调研、Coding、数据分析、文档生成、Browser Automation 等复杂任务，通过自研 Agent 架构完成端到端日常工作提效。\n\n1、参与Aime Web与桌面端核心功能研发，设计并实现对话流、任务执行、工具调用、权限确认、异常恢复与产物预览等复杂AI Agent交互；\n2、参与插件、Dynamic UI、Canvas等开放能力建设，支持多业务在Aime平台快速构建自己的Agent应用；\n3、持续优化前端架构、性能与稳定性，保障复杂长任务和多端场景下的流畅体验；\n4、使用AI Coding工具参与需求分析、方案设计、编码与测试，与产品、设计、后端及算法团队协作，将Agent能力转化为用户真正可用、可信的产品。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程等相关专业优先；\n2、具备扎实的计算机基础（数据结构、算法、网络、操作系统）；\n3、熟悉HTML/CSS/JavaScript/TypeScript，掌握React或Vue等现代前端框架，理解浏览器机制、状态管理与异步编程；\n4、有完整项目实践，能清晰说明问题拆解、方案选择与调试验证过程，重视代码质量与用户体验；\n5、对AI和Agent产品有兴趣，有LLM应用、流式对话、Tool Calling等相关经验，或有Electron/跨端/桌面端开发经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668308656179939589","sourceKey":"bytedance","company":"字节跳动","title":"安全研发工程师（AI For渗透测试） - 安全与风控","city":"杭州/北京","category":"安全","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668308656179939589/detail","duty":"团队介绍：负责公司大模型信息安全保障体系，持续识别和治理大模型衍生出的新型风险，并建设相应安全产品,保障大模型及其应用在训练、推理和部署等阶段的安全。同时将大模型相关技术应用到安全技术和安全运营领域，实现技术突破，做到效果和效率双提升。\n\n1、参与大模型应用于漏洞扫描、自动化渗透测试的研究与开发；\n2、参与漏洞扫描插件的编写和扫描能力的持续开发优化；\n3、负责公司安全漏洞事件应急响应相关工作；\n4、开展漏洞检测新技术的研究和开发工作。","requirements":"1、2027届获得本科及以上学历，计算机/软件/信息安全/人工智能等相关专业；\n2、有CTF比赛获奖经历、动态扫描工具（DAST、IAST等）开发经验、AI for Security相关项目实践经验者优先；至少熟练掌握以下一种或多种编程语言：Python、Go；\n3、熟悉各类漏洞原理、挖掘与防御；\n4、具备良好的逻辑思维能力、沟通能力、学习能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668218225453435189","sourceKey":"bytedance","company":"字节跳动","title":"后端开发实习生（AI MediaKit） - 音视频技术","city":"北京/杭州","category":"后端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668218225453435189/detail","duty":"团队介绍：视频与边缘部门承载了字节跳动的媒体内容分发基建及技术中台，支持了字节跳动全系产品，如抖音、今日头条、番茄小说、西瓜视频等APP的点播、直播、实时通信、图片等多媒体业务发展，同时将业务发展过程中沉淀下来的技术能力和工具，通过火山引擎对外输出，面向各行各业用户提供视频云产品和服务，愿景是为内外部业务伙伴提供最低成本、最优画质、最低延时、最安全可靠的富媒体内容分发解决方案，助力业务伙伴降本提效实现持续增长。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、提供业界领先的视频和图片AI解决方案，负责To B商业化和内部客户需求高质量开发交付、技术架构长期演进；\n2、负责微服务的稳定性建设，理解业务痛点，设计合理架构，保证高代码质量和系统高可靠。","requirements":"1、本科及以上学历在读，计算机、通信等相关专业优先；\n2、熟悉Golang、Java等服务端开发语言，熟悉高可用高并发的架构设计，了解微服务架构的技术挑战，并有对应的解决方案，有多媒体处理、多媒体AI相关的经验优先；\n3、扎实的技术基础，熟悉性能、可用性、伸缩性、扩展性、安全性、运维监控、集成发布等；\n4、熟悉PaaS设计理论，熟悉行业常见的架构方案；\n5、积极乐观，责任心强，工作认真细致，具备良好的服务意识，具有良好的团队沟通与协作能力；\n6、热爱编程，有较强的学习能力和抽象能力，有强烈的求知欲、好奇心和进取心，能及时关注和学习业界新技术。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667831565862701317","sourceKey":"bytedance","company":"字节跳动","title":"后端开发工程师 - 火山引擎","city":"北京","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667831565862701317/detail","duty":"团队介绍：火山引擎是字节跳动旗下云和AI服务平台，将字节跳动快速发展过程中积累的增长方法、技术能力和应用工具开放给外部企业，通过云和AI技术，推进企业智能化转型，激发增长潜能。\n\n1、参与到火山引擎云平台业务系统的需求分析、功能设计与核心模块研发，打造专业、安全、稳定的智能化云平台架构；\n2、参与到火山引擎统一服务框架的高性能、高并发、高可用等系统建设；\n3、参与到在线业务系统的技术问题定位并修复；\n4、学习前沿的分布式系统架构、云架构和智能化架构的相关知识，探索技术创新。","requirements":"1、2027届获得本科及以上学历，计算机科学与技术、软件工程、电子信息、数学等相关专业优先；\n2、熟练掌握至少一门服务端编程语言（如Java/Go/Python），熟悉常见数据结构与算法，理解操作系统、计算机网络、数据库（MySQL/Redis等）的核心原理；\n3、熟悉K8s、Docker等云原生技术，或有中间件开发经验优先；\n4、学习能力强，对技术有热情，具备基础的代码编写与调试能力，能阅读并理解开源框架源码；\n5、参与过开源项目贡献、技术竞赛（如ICPC、力扣周赛）或发表技术博客等优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667453198986627381","sourceKey":"bytedance","company":"字节跳动","title":"AI Agent算法工程师 - TikTok Shop","city":"上海/北京/杭州","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667453198986627381/detail","duty":"团队介绍：TikTok Shop 是 TikTok 旗下的内容电商业务，致力于成为用户发现并获取优价好物的首选平台。面向直播电商、视频内容电商、货架电商等多元购物场景，国际电商持续为全球用户提供更个性化、更主动、更高效的消费体验，也为商家提供稳定、可靠、可持续增长的平台服务，推动“新奇好物畅销全球，美好生活触手可得”的使命落地。\n目前，国际电商算法团队分布在中国、美国、新加坡等多个国家和地区，深度参与全球化业务建设。加入我们，你将有机会面向全球用户、商家和商品生态，与跨区域的产品、工程、运营和业务团队协作，持续提升商品供给质量、用户购物体验、平台交易效率与履约体验，共同探索内容电商与智能购物的新模式。\nData-国际电商团队是 TikTok Shop 的核心算法技术力量，专注于电商场景下的算法创新与规模化落地，方向包括但不限于：生成式推荐与大规模 Foundation Model、多模态商品理解与内容生成、搜索与导购、智能客服、风控治理、物流履约优化、商家经营智能化，以及 Agentic 智能体在电商全链路中的应用。我们希望通过先进的算法能力，帮助用户更高效地发现感兴趣的商品，帮助商家实现更高质量的经营增长，并持续提升交易各环节的智能化水平。\n在这里，你将与一流的产品和技术团队合作，面对复杂且真实的国际化电商挑战，推动前沿技术在大规模业务场景中落地，与团队一起创造更多可能。\n\n1、参与构建电商Agent核心大脑及多智能体系统研发：探索主流Agent框架，如LangGraph、OpenClaw、Hermes、Codex、Claude Code等，构建稳定可靠的Agent基座，重点提升任务的自动规划与调度、工具调用、多模态交互及深度研究能力；同时参与多智能体工具、模型、引擎、平台的研发，提升其在电商场景自动规划、泛化决策、多模态交互能力，以Agent的形式突破现有方法和模型无法解决的问题，识别模型能力缺陷，从应用探索反哺基础模型迭代；\n2、打造电商场景Skills工具集：基于电商业务系统，构建和优化一系列高性能、可复用的Skills，这包括利用小尺寸模型打造支撑高QPS场景的基础模型工具集，也包括将复杂的业务SOP（标准作业程序）封装为稳定可调用的治理Agent（如审核、RCA、立规Agent）；\n3、参与优化Agentic RL：基于主流agent框架，并结合Post-training技术（SFT/RLHF）与强化学习（PPO/GRPO）对模型进行持续优化，建立电商大模型的Agentic RL训练体系，提升模型在复杂问题上的准确率与动态反思能力；\n4、参与探索Agent自动化与自进化：结合Auto-Workflow与多智能体系统（MAS），一方面支持工作流的自动生成与优化，另一方面探索基于Agentic RAG和Memory机制的自进化（Self-Evolution）闭环，让Agent能够从真实交互数据中学习，持续提升其决策与执行能力；\n5、与团队一起，深入研究和挖掘多智能体在电商内容生态、商家/达人服务、用户体验、搜索推荐等领域的创新应用场景，用技术驱动业务的变革与想象。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程专业优先；\n2、具备扎实的代码功底、数据结构和基础算法功底，熟悉NLP、CV、多模态中的1-2个领域，熟悉大模型训练、RL算法者优先；\n3、优秀的分析和解决问题的能力，能深入解决大模型训练和应用存在的问题；\n4、具备良好的团队合作精神，较强的沟通能力，一起探索和推进新技术落地；\n5、熟悉至少一种主流Agent框架，如LangGraph、OpenClaw、Hermes、Codex、Claude Code等；\n6、有大模型落地、Agent项目等经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667126080873433397","sourceKey":"bytedance","company":"字节跳动","title":"AI Infra工程师 - 中国交易与广告","city":"北京/上海","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667126080873433397/detail","duty":"团队介绍：中国交易与广告，基于个性化推荐、深度学习和大模型技术，依托抖音、今日头条、红果短剧、西瓜视频、番茄小说等多元产品，构建抖音电商、生活服务、广告营销等核心营收业务的算法策略和工程架构。部门运用领先的算法能力，精准连接海量用户与商家，通过推荐、广告和搜索算法精准匹配需求并促进交易达成，保障用户体验与商家权益，实现营收业务可持续增长；基于深厚的技术积累，构建高效、智能、可靠的交易与广告产品，全面提升多行业收入变现与市场占有。在这里，你将直面超大规模流量与复杂业务场景的技术挑战，深度应用业界领先的商业模型与算法技术，投身面向未来的数字营销能力建设，持续探索前沿技术。\n\n1、负责LLM/VLM/Omni/Diffusion大规模分布式训练与推理基础设施的研发，深度优化计算、通信与存储性能，保障（多至）千卡任务集群的高效运行；\n2、针对NVIDIA GPU（CUDA/Triton）、NPU进行深度性能调优，包括算子融合、显存管理优化、通信算子重叠（Overlap）等，将硬件算力发挥到极致；\n3、设计并实现高性能LLM/VLM/Omni/Diffusion模型推理引擎，优化计算图编译、动态Batching及KV Cache管理，打造极致低延迟与高吞吐的线上服务架构；\n4、技术演进与落地：持续跟进业界最新的Infra技术（如FlashAttention演进、高效通信库、FP8/INT8量化、稀疏蒸馏等训练部署方案），配合实际业务驱动技术预研并转化为生产力。","requirements":"1、2027届获得本科及以上学历，计算机相关专业优先；\n2、熟练掌握C++/Python，精通数据结构与算法，并有并发编程基础；熟练使用PyTorch/TensorFlow或其他深度学习框架，熟练掌握深度学习性能加速技术包括但不限于计算图优化，算子性能优化，通信优化等；\n3、具有LLM/VLM/Omni/Diffusion模型训练/推理优化经验，熟悉TensorRT-LLM、vLLM、LightX2V等推理效率优化工具；\n4、积极主动有热情，具备较强的沟通能力以及优秀的团队协作能力；\n5、对于AI-Native代码工作流程有思考、有经验者优先，实践动手能力强，ACMICPC，NOI/IOI，Top Coder，Kaggle比赛获奖者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667086531504769333","sourceKey":"bytedance","company":"字节跳动","title":"后端开发工程师（东南亚业务） - TikTok Shop","city":"北京/上海","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667086531504769333/detail","duty":"团队介绍：TikTok Shop是以TikTok为载体的内容电商业务，致力于成为用户发现并获取优价好物的首选平台，在直播电商、视频内容电商等多场景下，TikTok Shop希望能为用户提供更个性化、更主动、更高效的消费体验，为商家提供稳定可靠的平台服务，在更多的地区实现没有难卖的优价好物，让美好生活触手可得的使命。我们邀请你来此成长、钻研，发掘无限的潜力，一起应对技术和业务上的挑战。目前团队拥有丰富的国际产品研发经验，包容多元的文化，且在全球设立研发团队，邀请你来一起接受跨国合作的挑战！\n\n1、负责TikTok Shop东南亚业务的后端开发工作；\n2、负责架构设计和开发，为亿级用户提供优质顺畅的信息服务和极致体验；\n3、负责在线大流量高并发系统设计和性能调优；\n4、参与各专项技术调研，新技术引入等前瞻项目。","requirements":"1、2027届获得本科及以上学历，计算机相关专业优先；\n2、热爱计算机科学和互联网技术，精通至少一门编程语言，包括但不仅限于：Java、C、C++、PHP、Python、Go；\n3、掌握扎实的计算机基础知识，深入理解数据结构、算法和操作系统知识；\n4、有优秀的逻辑分析能力，能够对业务逻辑进行合理的抽象和拆分；\n5、有强烈的求知欲，优秀的学习和沟通能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7667052074640148741","sourceKey":"bytedance","company":"字节跳动","title":"AI全栈开发工程师（客户端方向） - TikTok研发","city":"杭州","category":"客户端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7667052074640148741/detail","duty":"团队介绍：TikTok研发团队，旨在实现TikTok业务的研发工作，搭建及维护业界领先的产品。加入我们，你能接触到包括用户增长、社交、直播、电商C端、内容创造、内容消费等核心业务场景，支持产品在全球赛道上高速发展；也能接触到包括服务架构、基础技术等方向上的技术挑战，保障业务持续高质量、高效率、且安全地为用户服务；同时还能为不同业务场景提供全面的技术解决方案，优化各项产品指标及用户体验。 \n在这里， 有大牛带队与大家一同不断探索前沿， 突破想象空间。 在这里，你的每一行代码都将服务亿万用户。在这里，团队专业且纯粹，合作氛围平等且轻松。目前在北京，上海，杭州、广州、深圳分别开放多个岗位机会。\n\n1、参与iOS客户端功能的设计、开发、迭代与交付，覆盖短视频业务、用户体验及相关技术能力建设；\n2、参与客户端工程架构演进，包括模块化、组件化、构建工具、研发流程及开发效率优化等工作；\n3、参与AI能力在客户端的接入、工程化落地与体验优化，关注性能、稳定性、兼容性及用户体验；\n4、在导师指导下参与关键技术问题的分析与攻坚，跟踪行业技术趋势，探索可落地的技术创新方案；\n5、与产品、服务端及测试等团队协作，推动高质量、高效率的业务交付。","requirements":"1、2027届获得本科及以上学历，计算机科学与技术、软件工程、电子信息等相关专业；\n2、具备扎实的计算机基础，理解数据结构、算法、操作系统、计算机网络及软件工程相关知识；\n3、熟悉至少一门编程语言，如Swift、Objective-C、Java、Kotlin、C/C++等；有移动端开发基础者优先；\n4、对客户端开发、AI应用及新兴技术保持好奇心，具备较强的学习能力、问题分析能力和实践能力；\n5、具备良好的代码质量意识，逻辑清晰，养成规范的编码、调试与协作习惯；\n6、具备良好的沟通能力和团队协作意识，能够主动推进问题解决。\n\n加分项：\n1、有iOS、Android或跨端项目开发经验，具备完整项目或开源项目经历；\n2、了解端侧AI、模型推理、智能体应用或AI产品工程化实践；\n3、对客户端性能优化、工程效率、架构设计或用户体验有深入兴趣和实践积累。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7666012400843950389","sourceKey":"bytedance","company":"字节跳动","title":"国际直播大模型算法工程师（基础业务） - TikTok研发","city":"北京","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7666012400843950389/detail","duty":"团队介绍：TikTok研发团队，旨在实现TikTok业务的研发工作，搭建及维护业界领先的产品。加入我们，你能接触到包括用户增长、社交、直播、电商C端、内容创造、内容消费等核心业务场景，支持产品在全球赛道上高速发展；也能接触到包括服务架构、基础技术等方向上的技术挑战，保障业务持续高质量、高效率、且安全地为用户服务；同时还能为不同业务场景提供全面的技术解决方案，优化各项产品指标及用户体验。 \n在这里， 有大牛带队与大家一同不断探索前沿， 突破想象空间。 在这里，你的每一行代码都将服务亿万用户。在这里，团队专业且纯粹，合作氛围平等且轻松。目前在北京，上海，杭州、广州、深圳分别开放多个岗位机会。\n\n1、参与TikTok业务中的基础算法（LLM/multimodal LLM、CV/NLP）相关工作，在智能对话、热点事件发现、内容生态治理、本地生活等业务运用算法能力解决业务核心问题；\n2、参与研发LLM大语言模型和多模态大模型，并提升大模型在多个通用评测集及垂直业务评测集上的效果；\n3、总结研究成果，并发表论文，参与学术会议。","requirements":"1、2027届获得硕士及以上学位，LLM/multimodal LLM，机器学习等相关背景优先；\n2、掌握TensorFlow，PyTorch等社区开源工具中的一种及以上；\n3、熟练掌握C/C++，Python，Shell编程语言，对数据结构和算法设计有较好的理解；\n4、在相关国际会议（NeurIPS,ICLR,ACL,IJCAL,AAAI CVPR等）上发表论文者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7665605822222780725","sourceKey":"bytedance","company":"字节跳动","title":"AI后端开发工程师 - 抖音音乐","city":"北京/上海","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7665605822222780725/detail","duty":"团队介绍：抖音音乐研发团队的使命是用音乐建立共鸣和激发表达，成为让用户最容易发现音乐、了解音乐、进行音乐创作、表达和交流的平台。目前已经上线了汽水音乐APP、妙响（AI音乐及MV创作）、汽水音乐内容合作平台等消费端、创作端以及平台产品。汽水音乐是旨在成为Z世代用户最喜欢的音乐应用，主打个性化推荐与沉浸式听歌体验；妙响是一站式AI音乐创作发行平台，“灵感即刻成歌”，旨在通过AI技术重塑音乐创作、分发与消费的全链路，团队有自研音乐生成大模型，结合AI打造专业音乐创作平台；汽水音乐内容合作平台，为音乐人及厂牌提供音乐作品管理、发行、宣推、词曲生产等平台能力，旨在为音乐人带来更多听众，激发创作和成长，也带来更多收益。我们期待热爱技术的你加入，一起创造更多可能。\n\n1、参与汽水音乐核心后端系统的设计、开发、测试、上线及持续演进，覆盖内容消费、用户增长、商业化等业务场景；\n2、参与高并发、高可用分布式系统建设，持续提升系统的性能、稳定性、可扩展性与研发效率；\n3、理解业务和用户需求，通过数据分析、技术优化和工程创新，持续改善产品体验；\n4、关注业界技术发展，参与AI在音乐业务及研发提效场景中的探索与实践。","requirements":"1、2027届获得本科及以上学历，计算机、软件工程及相关专业优先；\n2、熟练掌握至少一门编程语言，包括但不限于Go、Java、C/C++、Python；\n3、具备扎实的计算机基础，理解数据结构、算法、操作系统、计算机网络及数据库等基础知识；\n4、具备良好的逻辑分析和问题解决能力，能够对复杂问题进行合理抽象与拆解；\n5、有较强的学习意愿、责任心和协作意识，愿意主动了解业务并持续改进技术方案；\n6、对后端技术和产品有热情，乐于面对有挑战、有真实用户反馈的问题。\n\n加分项：\n1、有后端项目、技术竞赛、科研、实习或开源项目经验；\n2、了解分布式系统、数据库、缓存、消息队列、云原生等技术，并有相关实践；\n3、有AI相关知识或实践经验，例如大模型应用、RAG、Agent、模型评测、AI Coding或AI工具开发；\n4、善于利用AI工具提升学习、编码、调试和问题分析效率，并能关注结果的正确性；\n5、对音乐、音视频、内容产品或创作者生态感兴趣。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7665573911026747653","sourceKey":"bytedance","company":"字节跳动","title":"大语言模型Agent全栈开发工程师 - 中国交易与广告","city":"杭州","category":"后端","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7665573911026747653/detail","duty":"团队介绍：中国交易与广告，负责抖音电商、生活服务、广告营销等营收业务的研发。用技术带来美好生活，让用户发现更多优价好物，为用户提供更丰富独特的生活体验；连接海量用户与商家，促进交易达成，让生态里全流程体验更流畅，助力营收业务长效增长。\n加入团队，你将投身流量与增长主战场，挑战复杂业务场景技术难题；直面真实商家和用户，用技术解决看得见的问题，在实战中快速成长，书写属于你的价值故事！\n\n1、负责内部研发场景AI Agent平台架构设计与核心开发，实现具备代码生成、缺陷诊断、工程重构能力的智能体，落地规划、记忆、工具调用、多轮交互等核心能力；\n2、结合交易广告业务研发流程，搭建AI原生研发工具：智能代码助手、自动化CodeReview、测试生成、线上故障诊断、知识库问答等，提升研发交付效率与代码质量；\n3、开发Agent任务编排引擎，搭建标准化工具生态，打通代码仓、CI/CD、监控、测试平台等基础设施，实现研发流程端到端自动化；\n4、搭建工程领域RAG知识系统，整合代码、技术文档、项目案例，为Agent提供精准知识支撑；\n5、联动算法团队开展大模型场景适配，搭建Agent评测基准与指标体系，持续迭代智能体效果；优化平台使用体验、性能与可观测能力，搭建用户反馈闭环，推动AI研发工具规模化落地。","requirements":"1、2027届获得本科及以上学历，计算机、人工智能相关专业；\n2、扎实工程功底，熟练掌握Python/Go/Java任一语言，具备分布式、高可用系统开发经验；\n3、精通LLM应用技术栈，熟悉Prompt工程、Function Calling、RAG、Agent任务编排，拥有完整Agent系统落地经验；\n4、了解LangChain、LlamaIndex、AutoGen等主流Agent框架，可基于框架二次开发；\n5、熟悉AI辅助开发工具，对AI原生研发模式有实践思考；\n6、良好跨团队协作能力，自驱力强，可推动复杂项目落地。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7662325740423579957","sourceKey":"bytedance","company":"字节跳动","title":"客户端开发实习生 - 中国交易与广告","city":"北京/上海/杭州","category":"客户端","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7662325740423579957/detail","duty":"团队介绍：中国交易与广告，负责抖音电商、生活服务、广告营销等营收业务的研发。用技术带来美好生活，让用户发现更多优价好物，为用户提供更丰富独特的生活体验；连接海量用户与商家，促进交易达成，让生态里全流程体验更流畅，助力营收业务长效增长。\n加入团队，你将投身流量与增长主战场，挑战复杂业务场景技术难题；直面真实商家和用户，用技术解决看得见的问题，在实战中快速成长，书写属于你的价值故事！\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、负责电商业务相关产品迭代改进及移动新产品的开发；\n2、参与APP性能、数据基建、体验优化及质量监控评估体系建设；\n3、参与客户端基础组件及架构设计，推进研发效率；\n4、参与鸿蒙新技术开发，Lynx、KMP等跨平台、动态化技术开发。","requirements":"1、本科及以上学历在读，计算机、软件工程等相关专业优先；\n2、热爱计算机科学和互联网技术，对移动产品有浓厚兴趣；\n3、扎实的数据结构和算法基础，熟练掌握至少一门编程语言（包括但不限于：Java、Kotlin、Objective-C、Swift、C、C++、JS、Python）；\n4、关注用户体验，能够积极把技术转化到用户体验改进上；\n5、对新技术保持热情，具备良好的分析、解决问题的能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7654466849254590773","sourceKey":"bytedance","company":"字节跳动","title":"Seedance2.5摄影实习生-火山方舟","city":"北京","category":"产品","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7654466849254590773/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：火山方舟是火山引擎推出的一站式大模型服务平台，是中国大模型市场产品和份额领跑者。平台提供模型推理、评测、精调等全流程服务。方舟搭载了豆包及业界主流大模型，提供丰富的插件生态和AI应用开发服务，并通过稳定可靠的安全互信方案、专业的算法技术服务，全方位保障企业级AI应用落地。\n\n1、利用Seedance模型完成世界观视觉落地与风格化研发，以高质量美术资产定义项目视觉基准，检验模型在造型、光影、材质与一致性生成上的极限能力；\n2、针对算法团队提供的特定版本模型进行美术向压力测试，深入理解生成逻辑，将角色/场景/道具的艺术痛点转化为可量化指标，直接参与视觉能力迭代与优化方向定义；\n3、在指定AI工具链与Workflow下进行资产创作，建立并维护项目Asset Bible，推动资产库标准化、可复用化，提升团队整体制作效率；\n4、依据影视与动画工业标准，建设高质量视觉素材数据配比，驱动模型在角色连续性、场景空间一致性、道具风格统一等维度实现质变。","requirements":"1、2027届本科及以上学历在读，动画、游戏设计、视觉传达、数字媒体、影视美术等相关专业优先；\n2、熟练掌握AIGC生图/生视频工具，具备完整AI美术创作链路能力，生图能力突出者优先，有成熟作品集/获奖作品/商业美术资产代表作优先；\n3、具备较强审美与造型能力，懂世界观构建、角色/场景/道具设计，能将艺术诉求清晰转化为可执行方向与技术反馈；\n4、对大模型与视觉生成原理有强烈好奇心，学习能力强，能快速适应迭代式创作与测试环境。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7628831582910679301","sourceKey":"bytedance","company":"字节跳动","title":"基于LLM的软件缺陷检测技术的探索和研究-质量技术","city":"上海","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7628831582910679301/detail","duty":"团队介绍：字节跳动质量技术团队，我们聚焦质量领域前沿创新，打造稳定、高效、领先的质量技术，深度赋能抖音、今日头条、豆包、电商等亿级用户产品。\n当前，我们通过AI来检测代码、架构、产品的缺陷、风险和效果，用AI重构质量保障模式，提升研发效能。聚焦智能缺陷检测、GUI agent、AI评测等前沿方向，希望通过质量技术的突破，用AI改变测试行业。欢迎加入，与我们一起，定义和构建下一代质量技术，推动行业前进。\n\n课题介绍：\n随着大模型技术在软件开发领域的广泛应用，代码开发效率显著提升，AI生成代码的质量不确定性，都为软件测试带来了全新挑战。传统静态分析方法在复杂业务逻辑校验、功能一致性验证等场景存在明显局限，而动态GUI测试与API测试则面临执行开销高、测试覆盖度不足等问题。\n本课题旨在构建一种基于LLM的智能缺陷检测系统。通过对需求文档和技术方案的语义理解，结合跨端、跨仓的代码调用关系的刻画，产出业务逻辑与代码实现的精准对齐，在此基础上，构建具备对各类缺陷特征有充分感知的缺陷检测智能体，高效、精准的识别业务逻辑、架构性能、程序安全等复杂缺陷。\n\n课题挑战：\n1、公司多样化业务场景下，对多模态需求的语义理解和功能逻辑提取；\n2、跨端、跨仓、多技术栈的代码链路分析；\n3、海量缺陷数据的特征分析和提取；\n4、支持大规模应用的Agent系统工程；\n\n课题价值：\n1、保证软件质量的要求下，构建一种以静态检测技术为主的软件测试模式，优化测试资源的配置和效率；\n2、实现软件缺陷的早期发现，降低缺陷识别和修复的成本，显著提升研发效能。","requirements":"1、2027届毕业，获得博士学位，人工智能、计算机、数学相关专业优先；\n2、对LLM在代码领域的应用有较大的兴趣，有一定实践经验者优先；\n3、出色的问题分析能力，能够自主探索前沿技术，并积极应用到业务问题解决中；\n4、良好的沟通联动能力，与团队持续探索&学习新技术，实现先进技术的不断落地；\n5、优秀的代码能力、数据结构和基础算法功底；\n6、在LLM、Agent架构领域有扎实的理论和实践基础，有发表顶会论文优先，有高影响力的开源项目者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7594493172216351029","sourceKey":"bytedance","company":"字节跳动","title":"视频编码策略算法实习生-音视频技术","city":"北京","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7594493172216351029/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：视频与边缘部门承载了字节跳动的媒体内容分发基建及技术中台，支持了字节全系产品，如抖音、今日头条、番茄小说、西瓜视频等APP的点播、直播、实时通信、图片等多媒体业务发展，同时将业务发展过程中沉淀下来的技术能力和工具，通过火山引擎对外输出，面向各行各业用户提供视频云产品和服务，愿景是为内外部业务伙伴提供最低成本、最优画质、最低延时、最安全可靠的富媒体内容分发解决方案，助力业务伙伴降本提效实现持续增长。\n\n1、设计视频编码优化算法，包括但不限于基于视频内容的自适应编码、基于上下文感知的编码优化等，优化视频画质和端到端用户体验；\n2、设计优化不同应用场景（直播/点播/VR、上传端/服务端、软编/硬编等）的视频编码方案；\n3、建设视频端到端处理编码仿真系统、支持大数据采集与分析；\n4、根据不同业务需求，评估设计编码策略，优化业务存储/计算/带宽成本。","requirements":"1、2027届本科及以上学历在读，计算机、通信、数学、统计等相关专业优先；\n2、熟悉C/C++、Python等主流编程语言至少一种，有扎实的数据结构与算法功底；\n3、有视频编解码及画质评估经验，了解视频编解码及端到端传输流程；\n4、熟悉编码实时码率控制算法，自适应编码策略优化算法优先；\n5、积极乐观，责任心强，工作认真细致，具有良好的团队沟通与协作能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7669698519996860725","sourceKey":"bytedance","company":"字节跳动","title":"滋补行业运营 - 抖音电商","city":"上海","category":"运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7669698519996860725/detail","duty":"团队介绍：抖音电商以“总能发现好东西”为主张，致力于成为用户发现丰富好物的首选平台。众多抖音创作者通过短视频、直播、商城等丰富的形式，给用户提供更个性化、更生动、更高效的消费体验。同时，抖音电商积极引入优质合作伙伴，为商家变现提供多元的选择。\n\n1、结合抖音内容特性，制定行业在抖音产品内的完整策略，根据滋补行业的特性、发展阶段及市场趋势制定行业策略及商家在字节跳动系内的发展运营策略；\n2、对滋补行业兴趣度高，有较强的好奇心和快速学习的能力；\n3、了解抖音的短视频和直播流量规律，关注内容电商的玩法。","requirements":"1、2027届获得本科及以上学历；\n2、数据敏感度好，有行业运营、类目运营、商品运营等实习经验优先，对平台侧商家商品运营有好奇心，有过复杂项目的支持经验；\n3、自我驱动力强，主动学习，有团队合作精神，良好的协同能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668630538194471221","sourceKey":"bytedance","company":"字节跳动","title":"豆包大模型多模态算法工程师 - 火山方舟","city":"上海/北京/深圳/杭州","category":"算法","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668630538194471221/detail","duty":"团队介绍：火山方舟是火山引擎推出的一站式大模型服务平台，是中国大模型市场产品和份额领跑者。平台提供模型推理、评测、精调等全流程服务。方舟搭载了豆包及业界主流大模型，提供丰富的插件生态和AI应用开发服务，并通过稳定可靠的安全互信方案、专业的算法技术服务，全方位保障企业级AI应用落地。\n\n1、探索研究多模态理解、强化学习、计算机视觉、Agent等前沿技术；对多模态模型能力和理想态的差距保持敏感，评测和优化提升多模态模型的能力极限；\n2、专注提升多模态大模型在现实世界复杂任务的效果，追求通用可规模化的方法，优化领域包括但不限于视觉推理、Streaming video交互、多模态Agent、大规模数据合成、Mid-training等方向；\n3、推动多模态大模型在成本/效率方面的极致优化，包括但不限于大规模蒸馏/自蒸馏、Efficient reasoning、极致的Video压缩等方向；\n4、依托公司和业界的大模型和基础CV技术，构建面向To B业务应用的多模态算法能力，帮助业务取得成功。","requirements":"1、2027届获得硕士及以上学位，计算机、数学等相关专业优先；\n2、具有优秀的基础算法、代码能力，熟练掌握C/C++或Python编程语言，ACM/ICPC、NOI/IOI、Top Coder、Kaggle等比赛获奖者优先；\n3、具有扎实的计算机视觉、机器学习基础，熟悉CV、AIGC、NLP、RL等技术领域，在CVPR、ECCV、ICCV、NeurIPS、ICLR、SIGGRAPH或SIGGRAPH Asia等顶级会议上发表论文者优先；\n4、在大模型领域或者RL领域，主导过大影响力的项目者优先；\n5、具有出色的分析、解决问题的能力，能深入解决大模型训练和应用存在的问题，有自主探索解决方案的能力者优先；对AI技术的实际落地和突破性应用充满热情，追求技术创新与现实价值的结合；\n6、具有良好的沟通协作能力，工作积极主动，能够与团队融洽合作，一起探索新技术，推进技术进步。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7668567025011181877","sourceKey":"bytedance","company":"字节跳动","title":"AI产品运营 - 抖音生活服务","city":"上海/北京","category":"产品运营","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7668567025011181877/detail","duty":"团队介绍：抖音生活服务依托抖音POI （Point of Interest）、短视频、直播、搜索等，以“激发线下生意，丰富美好生活”为使命，致力于成为最值得信赖的生活服务平台，为用户提供更丰富、独特的生活体验，为合作伙伴提供包容且公平的健康营商生态。截至2025年底，抖音生活服务业务已覆盖400+城市，超过1500万家动销门店。抖音生活服务将继续携手生态伙伴，为用户提供值得心动的商品和服务。\n\n1、负责商家智能服务运营，以提升智能解决能力、降低智能转人工比例为目标，持续优化业务知识、扩充智能的解决能力，优化智能服务全链路体验；\n2、参与评估体系建设，建立可信解决率、未解决归因、上线质量围栏等评测机制，共同定义解决判定标准、诉求类型边界和分档口径，保障智能服务效果可衡量、可归因、可优化；\n3、深度协同业务、运营、研发、算法、设计等团队，推进跨团队问题闭环，整理未解决问题、供给缺口和产品体验反馈，推动相关方跟进优化；\n4、基于数据分析、用户反馈和业务调研，持续识别关键问题与增长机会，沉淀可复用的产品方法论和解决方案，驱动AI产品在生活服务领域的长期发展。","requirements":"1、2027届获得本科及以上学历，专业不限；\n2、具备独立数据分析能力，能通过数据发现问题、评估运营效果，并产出优化思路；\n3、有较强的用户视角，喜欢体验新产品，对于用户产品体验、用户需求本质有自己的思考和理解；\n4、学习能力强，快速理解业务目标，有较好的沟通能力、能完成跨团队协作；\n5、对AI行业和大模型产品有热情、有理解，关注行业趋势和技术发展，具备较强的创新意识与业务判断力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7596907701939570997","sourceKey":"bytedance","company":"字节跳动","title":"广告算法实习生-中国区搜索广告","city":"北京","category":"算法","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7596907701939570997/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：搜索广告团队是负责抖音，抖音电商，今日头条，西瓜视频等搜索全场景的收入变现团队。在这里我们有丰富的搜索流量， 综合的广告业务场景（包括不限于电商、本地、到店商家、游戏客户、装修客户、下载类客户等）。作为技术团队，我们的系统拥有核心并且先进的算法：1、使用LLM和视频理解技术进行广告的匹配和相关性计算；2、使用AIGC技术帮助客户自动生成广告的标题、图片和视频创意提升创意效率；3、利用先进模型预估用户的点击率和转化率；4、客户机制和策略帮助客户提升转化效果和投放效率；5、同时丰富的流量也带来了非常多的工程挑战。如果你在机器学习、LLM、Coding、工程等方向有不错的知识和经验，欢迎加入我们一起丰富和完善搜索广告营销和技术平台。\n\n1、参与抖音搜索广告产品的广告全场景、全链路优化，包括召回/粗排/精排/混排/创意生成各模块的整体优化，构建业界领先的下一代广告投放系统；\n2、在超大规模在线深度学习框架下，结合前沿技术，持续优化CTR/CVR/DeepCVR模型精度，持续提升预估能力天花板；\n3、在海量广告候选下，进行召回/粗排模型及链路优化，结合服务/素材等不同投放标的，不断优化链路漏斗效率；\n4、使用AIGC技术自动生成广告标题、图片、视频，帮助客户提升创意效率；\n5、参与混排/长期价值建模/人群转化渗透/用户体验等业务策略前沿探索，做到收入和体验价值最大化。","requirements":"1、2027届本科及以上学历在读，计算机等相关专业优先；\n2、具备优秀的编码能力，扎实的数据结构和算法功底；\n3、优秀的分析问题和解决问题的能力，对解决具有挑战性问题充满激情；\n4、对技术有热情，有良好的沟通表达能力和团队精神；\n5、熟悉机器学习、计算机视觉、自然语言处理、数据挖掘中一项或多项。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7592121978364053813","sourceKey":"bytedance","company":"字节跳动","title":"测试开发实习生-中国交易与广告","city":"上海","category":"测试","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7592121978364053813/detail","duty":"ByteIntern：面向2027届毕业生（2026年9月-2027年8月期间毕业），为符合岗位要求的同学提供转正机会。\n团队介绍：中国交易与广告，负责抖音电商、生活服务、广告营销等营收业务的研发。用技术带来美好生活，让用户发现更多优价好物，为用户提供更丰富独特的生活体验；连接海量用户与商家，促进交易达成，让生态里全流程体验更流畅，助力营收业务长效增长。\n加入团队，你将投身流量与增长主战场，挑战复杂业务场景技术难题；直面真实商家和用户，用技术解决看得见的问题，在实战中快速成长，书写属于你的价值故事！\n\n1、参与产品测试的全流程，包括需求评审、设计评审、制定测试计划、测试用例设计及执行、缺陷跟踪、测试报告等；\n2、开发测试工具和自动测试框架、自动测试脚本，进行自动化测试，提升测试效率；\n3、对产品、流程提出持续性改进意见，提升产品质量和研发效率。","requirements":"1、2027届本科及以上学历在读，计算机、软件工程等相关专业优先；\n2、熟练掌握至少一门编程语言，包括但不限于：Java、C、C++、PHP、Python、Go；\n3、掌握扎实的计算机基础知识，深入理解数据结构、算法和操作系统知识；\n4、学习能力强，有较强分析、定位和解决问题的能力，较强逻辑思维能力和表达能力；\n5、每周可以实习4天及以上，连续实习4个月以上。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7687460003879487797","sourceKey":"bytedance","company":"字节跳动","title":"大客户销售（游玩行业） - 抖音生活服务","city":"西安","category":"销售","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7687460003879487797/detail","duty":"团队介绍：抖音生活服务依托抖音POI （Point of Interest）、短视频、直播、搜索等，以“激发线下生意，丰富美好生活”为使命，致力于成为最值得信赖的生活服务平台，为用户提供更丰富、独特的生活体验，为合作伙伴提供包容且公平的健康营商生态。截至2025年底，抖音生活服务业务已覆盖400+城市，超过1500万家动销门店。抖音生活服务将继续携手生态伙伴，为用户提供值得心动的商品和服务。\n\n1、负责生活服务餐饮、游玩、服务、零售行业的大客户销售工作；\n2、负责餐饮、游玩、服务、零售行业品牌商家在本地生活服务的各项商务事宜，包括商务谈判、资源投入发掘、资源分配等，提升抖音生活服务份额占比，与公司关联部门沟通协作，确保广告的及时投放与问题反馈、广告资源的合理利用与开发；\n3、负责全国餐饮、游玩、服务、零售连锁品牌的市场规划、策略制定及实施，挖掘增长机会点和重大项目拓展，联合商户打造营销事件；\n4、通过数据分析客户需求，为客户提供咨询服务、产品培训、优化投放、数据分析等营销策略，制定整合营销方案及策略，推动各行业营销策略的实施，整合内外部资源，包括大促、数据协同、品牌门店赋能等增值服务方案。","requirements":"1、2027届获得本科及以上学历；\n2、热爱销售工作，具备良好的客户开拓和服务能力，建立良好的客户群体关系的能力；\n3、掌握商务谈判、沟通及文字写作表达交流技巧，具有一定的市场洞察力和执行力；\n4、性格开朗，敢于面对挑战。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7685966918117574965","sourceKey":"bytedance","company":"字节跳动","title":"Seedance2.5剪辑实习生 - 火山方舟","city":"北京","category":"设计","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7685966918117574965/detail","duty":"团队介绍：火山方舟是火山引擎推出的一站式大模型服务平台，是中国大模型市场产品和份额领跑者。平台提供模型推理、评测、精调等全流程服务。方舟搭载了豆包及业界主流大模型，提供丰富的插件生态和AI应用开发服务，并通过稳定可靠的安全互信方案、专业的算法技术服务，全方位保障企业级AI应用落地。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、参与创作向电影叙事类视频内容的剪辑工作，配合团队完成从素材梳理到成片落地的全流程剪辑环节；\n2、负责对实时生成的创作向电影叙事类视频内容进行剪辑加工，完成素材梳理、片段拼接、节奏调整等剪辑工作；\n3、与导演、算法及技术团队紧密协作，理解创作意图与叙事目标，确保剪辑节奏与影片叙事逻辑高度统一；\n4、参与作品成片质量把控，沉淀剪辑方法论与最佳实践，持续提升团队整体创作效率与作品交付质量。","requirements":"1、本科及以上学历在读，戏剧影视导演、影视技术、影视摄影与制作、数字媒体艺术相关专业优先；\n2、熟练掌握达芬奇、Final Cut、剪映三款剪辑软件，可独立完成基础剪辑全流程操作；\n3、拥有个人独立剪辑代表作，长片、短片题材不限，作品需体现清晰的剪辑逻辑与完整的成片质量；\n4、具备较强的叙事理解能力与审美功底，能准确把握影片节奏与情绪表达，沟通协作顺畅。\n\n加分项\n1、具备跟组剪辑实操经验，剪辑效率高、出片速度快；\n2、作品曾入围/获得FIRST青年电影展、平遥国际电影展、金鸡电影节等国内主流影视节展奖项。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7685273998659553541","sourceKey":"bytedance","company":"字节跳动","title":"企业服务BP - Corporate Services","city":"北京","category":"职能 / 支持","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7685273998659553541/detail","duty":"团队介绍：企业服务团队致力于为全球ByteDancer提供最佳的管理和员工体验，我们支持员工协同并高效地完成工作，同时保护和促进公司的业务发展。企业服务团队通过专业服务来改善ByteDancer的体验，同时建立并不断探索可广泛共享的新行业最佳实践。\n\n1、深入理解各业务线的办公与运营需求，结合业务发展方向和目标，前置规划企业服务全链路解决方案，覆盖办公空间、行政运营、物理安全及EHS（环境健康安全）相关要求等相关职能，统筹相关资源，为业务提供匹配业务发展需求的企业服务支持；\n2、作为业务侧与房产、行政、安全、EHS等相关团队之间的沟通协调人，准确理解并传递业务需求，协调相关职能围绕空间方案、成本管理与规划、合规要求及服务标准进行有效对齐，推动需求高效落地；\n3、作为业务侧统一对接人，承接公司级办公空间调整项目，以及新办公室开设、重保支撑、大促保障等重大业务专项需求，协调相关职能团队做好需求承接与资源匹配，推动重点项目及专项需求端到端落地，持续优化业务服务体验；\n4、建立和维护有效的跨部门工作关系，及时、准确地将企业服务相关规则、政策、成本及资源信息与业务沟通触达，结合业务反馈持续优化服务与协作机制，提升企业服务响应效率和业务满意度。","requirements":"1、2027届获得本科及以上学历；\n2、具备较强的学习能力和业务理解能力，能够快速了解办公空间、行政运营、物理安全及EHS等企业服务领域的基础知识，并准确理解业务需求；\n3、具备良好的沟通表达与协调能力，逻辑清晰，能够准确传递信息，推动多方协作与共识达成；\n4、具备较强的执行力和项目推进意识，有校园活动、学生组织、社会实践或相关实习项目经验者优先；\n5、具备良好的服务意识和团队合作精神，能够主动关注业务需求及服务体验，善于建立和维护协作关系；\n6、责任心强，积极主动，能够适应多任务的工作环境，具备基本的数据分析和成本意识，熟练使用常用办公软件，具备一定的英文沟通能力者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7684190028444338437","sourceKey":"bytedance","company":"字节跳动","title":"AI芯片ESL建模实习生 - 芯片研发","city":"北京/上海","category":"硬件","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7684190028444338437/detail","duty":"团队介绍：字节芯片研发团队目前工作主要集中在芯片设计环节，主要围绕字节自身业务展开芯片探索，为字节多项业务的专用场景定制硬件优化，设计多款基于先进半导体工艺的云端复杂芯片，以期提升性能、降低成本。早期若干芯片项目已经进入到量产部署阶段，有多次一版成功的投片经历，所用工艺包含多个主流的先进工艺节点。与基础设施各团队之间工作的整体协同，能更容易和更好地发挥芯片研发的价值。\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、负责AI芯片架构的探索与建模；\n2、负责不同业务场景下的AI芯片架构及微架构的性能分析；\n3、进行IP模型测试、RTL校准、性能分析，找出和优化IP微架构的性能瓶颈。","requirements":"1、本科及以上学历在读，专业不限；\n2、基本掌握C++/SystemC，了解AI Core、NOC、DMA、Memory等硬件IP规格和内部实现；\n3、了解计算机体系结构，对典型的AI硬件加速器架构有一定了解者更佳。\n\n加分项\n1、有性能建模或参考模型开发经验；\n2、有SystemC/Gem5等仿真工具的开发经验；\n3、做过有一定规模和复杂度的RTL模块设计，IC或FPGA背景均可。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7684185488314206469","sourceKey":"bytedance","company":"字节跳动","title":"日本内容运营（图片素材方向）实习生 - 剪映CapCut","city":"深圳","category":"内容运营","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7684185488314206469/detail","duty":"团队介绍：剪映CapCut团队成立七年，先后孵化了剪映、CapCut、醒图、Hypic、即梦、Dreamina、Pippit等产品，覆盖视频、图片、Al生成、视频营销等多领域，打造与AI结合的全球化产品矩阵。\n我们的愿景是：激发想象力，成为全球领先的互动内容平台，创造独特的体验和价值。\n我们期待你的加入，一同极致打磨用户体验,构建创意生态和商业化能力，定义AI与创作结合的无限可能，让内容互动更简单、更精彩!\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、围绕图片创作场景，关注国际以及日本本地化热点风向，挖掘图片及素材的创意灵感，通过对接作者回收优秀图片模板及贴纸/滤镜等素材；\n2、推广图片功能，结合端内资源和端外达人营销，将图片亮点功能推向日本市场；\n3、协助开展图片及素材的作者运营工作，挖掘潜力图片、素材作者，负责垂类作者的日常对接、沟通跟进；\n4、和日本作者沟通对齐创作方向，收集作者的诉求与反馈，整理汇总同步团队。","requirements":"1、本科及以上学历在读；\n2、可实习3个月；\n3、能够阅读日文，具备简单日语沟通能力优先，有创作工具、创作者运营、内容策划相关实习/项目经验优先；\n4、主动性强，细心负责，脑洞活跃，愿意主动输出创意想法；\n5、高频浏览INS、TikTok等国际平台，拥有不错图文视觉审美，有修图软件的使用习惯者优先；\n6、具备基础信息整理、归纳能力，擅长收集整理行业案例与灵感。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7683440461094668549","sourceKey":"bytedance","company":"字节跳动","title":"机器人灵巧手结构工程师 - Seed大模型人才校招","city":"北京","category":"硬件","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7683440461094668549/detail","duty":"Seed 大模型人才校招，是字节跳动 Seed 面向高校人才推出的招聘项目。我们始终相信，真正重要的技术进步来自对高难度问题的持续挑战。面对 AI 时代的巨大机遇，Seed 团队并不止步于模型迭代，而是选择进入技术深水区，推进下一代 AI 范式突破，不断探索智能的边界与上限。\n\n团队介绍：字节跳动 Seed 团队成立于 2023 年，致力于寻找通用智能的新方法，追求智能上限，为科技和社会发展作出贡献。Seed 团队在 AI 领域拥有长期愿景与决心，团队研究方向涵盖 MLLM、GenMedia、AI for Science、机器人等，在中国、新加坡、美国等地设有实验室和岗位。目前，团队已推出业界领先的通用大模型以及前沿的多模态能力，支持豆包、即梦、TRAE 等超过 50 个应用场景，并通过火山引擎开放给企业客户。第三方数据显示，豆包 App 用户量在中国市场排名第一，豆包大模型日均 Token 调用量行业领先。\n\n1、负责灵巧手的机械结构设计，并推进样机生产落地，包括但不限于指节、腱绳/连杆传动、及腕部结构设计等；\n2、精通连杆、腱绳、齿轮等微型活动件的设计，能通过理论计算与实验，优化手指自由度布局、构型尺寸及传动参数；\n3、面向高集成度与小型化场景，完成灵巧手内部电机、减速机、传感器的核心器件设计与走线设计；\n4、提供富有创新性的结构解决方案且能落地实现，持续优化方案以提升灵巧手的操作性能；\n5、持续提升模块的可靠性与量产性，解决生产、装配、测试过程中的各类问题。","requirements":"1、2027届获得本科及以上学历，机械、机电一体化等相关专业；\n2、有机器人、灵巧手、可穿戴设备或精密机构相关项目经验者优先，熟悉主流厂家灵巧手方案，并对核心设计点有深入理解；\n3、熟悉常见加工工艺 (如CNC、注塑、3D打印等)，对小型化、轻量化、可靠性及量产性设计有一定理解；\n4、力学基础扎实，熟悉受力分析，对仿真底层原理有了解、具备二次开发能力为加分项；\n5、对腱绳驱动、柔性结构、微型传动或人机工程学有了解者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7683082923512711477","sourceKey":"bytedance","company":"字节跳动","title":"游戏监修PM实习生 - Glow Studio","city":"广州","category":"项目管理","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7683082923512711477/detail","duty":"团队介绍：Glow Studio 微光工作室。团队深耕轻竞技和动作游戏赛道，也在持续探索品类发展新可能。我们以热爱、匠心、和创新的理念专注精品研发，打造富有激情与感染力的游戏产品，服务全球玩家。期待您的加入，共筑创意梦想！\n\n日常实习：面向全体在校生，为符合岗位要求的同学提供为期3个月及以上的项目实践机会。\n\n1、参与游戏研发监修的文档处理流程；\n2、协助项目管理团队进行监修文档整理；\n3、按照规范进行文档更新与归档；\n4、协助设计团队进行监修文档的翻译与校对。","requirements":"1、本科及以上学历在读；\n2、掌握日语读写能力；\n3、是游戏爱好者，对ARPG/卡牌游戏有一定体验；\n4、对待工作能做到主动、灵活、细心。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7678601631490984197","sourceKey":"bytedance","company":"字节跳动","title":"AI产品经理（Seed评测方向） - 火山方舟","city":"北京/上海","category":"产品经理","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7678601631490984197/detail","duty":"团队介绍：火山方舟是火山引擎推出的一站式大模型服务平台，是中国大模型市场产品和份额领跑者。平台提供模型推理、评测、精调等全流程服务。方舟搭载了豆包及业界主流大模型，提供丰富的插件生态和AI应用开发服务，并通过稳定可靠的安全互信方案、专业的算法技术服务，全方位保障企业级AI应用落地。\n\n1、定义Coding质量标准，评审大模型在编码任务中生成的多个候选实现，从功能正确性、架构设计、代码质量、性能表现、可维护性及用户体验等维度判断方案优劣，沉淀\"什么是优秀实现\"的评价标准；\n2、建设大模型评测体系，围绕真实开发场景设计具有挑战性和区分度的评测任务，制定清晰、可执行的验收标准与评分细则，客观衡量不同模型的能力水平；\n3、分析模型能力与短板，对模型输出进行深入测试和归因分析，识别模型在需求理解、方案设计、代码实现、调试修复等环节的问题，为模型优化提供可解释、可落地的评测依据；\n4、建设高质量训练与评测数据，参与Coding相关训练数据和评测数据的生产、合成、筛选与优化，并通过实验验证数据质量及其对模型效果的影响；\n5、探索AI编程的新场景，跟踪Claude Code、Codex等前沿AI编程产品与技术进展，探索大模型在软件开发、游戏开发、交互应用等场景中的能力边界。","requirements":"1、2027届获得本科及以上学历，计算机科学、软件工程、人工智能等其他相关专业优先；\n2、具备扎实的编程基础，至少熟悉一个技术方向（前端/后端/移动端/Web3D&渲染/游戏开发均可）；\n3、深度使用过Claude Code、Codex等一线AI编程工具，能够熟练运用AI完成需求分析、代码生成、调试和迭代；\n4、对大语言模型及AI Coding有基础认知，能够客观分析模型生成结果的质量；\n5、具备良好的逻辑分析、问题拆解和文字表达能力，能将主观体验转化为清晰可复用的评测标准；\n6、认真负责，对代码及数据质量敏感，具备良好的沟通协作能力。\n\n加分项\n1、有大模型评测、模型效果分析或AI产品测评相关经验；\n2、参与构建过Coding评测集、内部评测体系或公开Benchmark；\n3、发表过Benchmark、大模型评测、代码生成或智能体相关论文；\n4、有完整的软件/游戏/AI Coding项目经验；\n5、熟悉自动化测试、性能分析、代码审查或数据分析方法。","description":"","jdComplete":true,"sourceStatus":null},{"id":"bytedance:7676398110972741941","sourceKey":"bytedance","company":"字节跳动","title":"大数据开发工程师（抖音电商） - 数据BP","city":"北京/杭州/上海","category":"大数据","channels":["campus"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://jobs.bytedance.com/campus/position/7676398110972741941/detail","duty":"团队介绍：负责字节跳动旗下泛抖音、国际化、创新与中台等业务的数据 BP 工作，业务版图覆盖抖音、国际化、大模型、番茄小说等板块。我们以数据高效赋能业务增长为核心使命，深度扎根各业务线，以数据体系建设为根基、以业务目标达成为导向，为业务方提供专业、稳定、高效的数据服务与架构解决方案。工作内容聚焦海量数据的治理与应用，需对产品全链路数据进行复杂且深度的分析挖掘；深度参与大数据产品的迭代优化，探索前沿数据技术在业务场景中的落地实践，在字节跳动的技术土壤中实现个人能力与业务价值的双重增长。\n\n1、负责抖音电商业务的海量数据全链路建设，基于分布式计算与存储底座搭建高稳定、高吞吐数据流水线，沉淀标准化数据平台工具与商业化数据产品，支撑集团规模化数据生产；\n2、深度联动各相关业务线，综合运用数据开发、多维分析、数据挖掘能力输出一站式数据解决方案，挖掘数据资产价值，持续优化整体数据流转与使用效率；\n3、落地复杂SQL、ETL流程开发交付，负责超大规模数据任务性能调优、故障治理与高复杂度业务需求落地，跟进并落地前沿大数据技术方案迭代；\n4、基于LLM提升数据开发和数据消费的效率，覆盖需求拆解、数据建模、开发实现、自动化测试、标准化文档全流程，协同前后端工程师共同完成对外数据服务接口交付与上线。","requirements":"1、2027届获得本科及以上学历，计算机、数学等相关专业优先；\n2、计算机基础（操作系统、数据库、算法与数据结构、网络、概率统计等）扎实，有优秀的编码能力，熟练掌握至少一种主流编程语言（包括但不限于C/C++/Java/Python/Golang）；\n3、对数据开发、分析、挖掘领域有兴趣和热情，有志于在大数据领域长期发展；\n4、有分布式系统/数据挖掘等相关领域论文发表，或参与过大数据社区开源项目者加分；\n5、能使用AI Coding加速建模、ETL开发、测试与文档生成，对大模型和AI技术有好奇心和自驱力者优先。","description":"","jdComplete":true,"sourceStatus":null}];
